@dataclass
class PageBudget:
    limit: int
    used: int = 0

    def __post_init__(self) -> None:
        self.limit = max(0, int(self.limit))

    def claim(self) -> bool:
        if self.used >= self.limit:
            return False
        self.used += 1
        return True

    @property
    def exhausted(self) -> bool:
        return self.used >= self.limit


def session() -> requests.Session:
    s = SafeSession()
    s.headers.update(
        {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/125.0 Safari/537.36",
            "Accept-Language": "ko-KR,ko;q=0.9,en;q=0.8",
        }
    )
    active_sessions = _ACTIVE_CRAWL_SESSIONS.get()
    if active_sessions is not None:
        active_sessions.append(s)
    return s


def close_crawl_sessions(func: Callable[..., _T]) -> Callable[..., _T]:
    """Close every HTTP session created during one top-level target crawl."""

    @wraps(func)
    def wrapped(*args: Any, **kwargs: Any) -> _T:
        if _ACTIVE_CRAWL_SESSIONS.get() is not None:
            return func(*args, **kwargs)
        created_sessions: list[requests.Session] = []
        token = _ACTIVE_CRAWL_SESSIONS.set(created_sessions)
        try:
            return func(*args, **kwargs)
        finally:
            _ACTIVE_CRAWL_SESSIONS.reset(token)
            for created_session in reversed(created_sessions):
                try:
                    created_session.close()
                except Exception as exc:
                    logger.debug("Failed to close municipal crawler session: %s", exc)

    return wrapped


def stable_provider(prefix: str, value: str) -> str:
    parsed = urlparse(value)
    host = re.sub(r"[^A-Za-z0-9]+", "_", parsed.netloc.upper()).strip("_")
    digest = hashlib.sha1(value.encode("utf-8")).hexdigest()[:8].upper()
    provider = f"{prefix}_{host}_{digest}" if host else f"{prefix}_{digest}"
    return provider[:50]


def stable_course_id(provider: str, url: str, title: str, branch: str) -> str:
    raw = "|".join([provider, url, title, branch])
    digest = hashlib.sha1(raw.encode("utf-8")).hexdigest()[:20]
    token = urlparse(url).path.rstrip("/").split("/")[-1] or digest
    token = re.sub(r"[^A-Za-z0-9\uAC00-\uD7A3_:-]+", "_", token)[:50]
    return f"{token}:{digest}"[:100]


def stable_list_item_url(
    page_url: str,
    provider: str,
    title: str,
    branch: str,
    *identity_parts: Any,
) -> str:
    """Return a stable per-item URL when a list has no real detail links.

    The fragment is an internal course identity. Browsers still open the source
    list page, while the database can keep multiple courses from that page
    without weakening the provider/raw_url uniqueness guard.
    """

    base_url = urldefrag(clean_text(page_url))[0]
    if not base_url:
        return ""
    identity = "|".join(
        clean_text(value).casefold()
        for value in (provider, title, branch, *identity_parts)
    )
    digest = hashlib.sha256(identity.encode("utf-8")).hexdigest()[:20]
    return f"{base_url}#mooncen-item-{digest}"


def parse_optional_krw_amount(value: Any) -> Optional[int]:
    """Keep unknown fees distinct from source-confirmed free programs."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return max(0, int(value))
    text = clean_text(value)
    if not text:
        return None
    if any(token in text for token in ("무료", "무상")):
        return 0
    compact = re.sub(r"\s+", "", text)
    if compact in {"0", "0원"}:
        return 0
    if not (
        re.fullmatch(r"\d[\d,]*", compact)
        or re.search(r"\d[\d,.]*\s*(?:만|천)?\s*원", text)
    ):
        return None
    return max(0, int(extract_krw_amount(text)))


def has_any(text: str, keys: tuple[str, ...] | list[str]) -> bool:
    return any(key in text for key in keys)


def first_by_keys(values: dict[str, str], keys: tuple[str, ...]) -> str:
    normalized_values = [
        (clean_text(key).rstrip(":：").strip(), clean_text(value))
        for key, value in values.items()
    ]
    for expected in keys:
        normalized_expected = clean_text(expected).rstrip(":：").strip()
        for normalized_key, value in normalized_values:
            if normalized_key == normalized_expected:
                return value
    for expected in keys:
        normalized_expected = clean_text(expected).rstrip(":：").strip()
        for normalized_key, value in normalized_values:
            if normalized_expected and normalized_expected in normalized_key:
                return value
    return ""


def parse_capacity_number(value: Any) -> Optional[int]:
    text = clean_text(value).replace(",", "")
    if not text:
        return None
    match = re.search(r"(\d{1,5})", text)
    return int(match.group(1)) if match else None


def parse_capacity_pair(value: Any) -> tuple[Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    if not text:
        return None, None
    match = re.search(r"(\d{1,5})\s*/\s*(\d{1,5})", text)
    if match:
        return int(match.group(1)), int(match.group(2))
    current = None
    total = None
    current_match = re.search(r"(?:신청|접수|현재|참여)\s*(?:인원|자)?\s*[:：]?\s*(\d{1,5})", text)
    total_match = re.search(r"(?:정원|모집인원|모집|총원)\s*[:：]?\s*(\d{1,5})", text)
    if current_match:
        current = int(current_match.group(1))
    if total_match:
        total = int(total_match.group(1))
    return current, total


def infer_program_type(*parts: Any) -> str:
    text = clean_text(" ".join(clean_text(part) for part in parts if clean_text(part)))
    checks = (
        (("\uc804\uc2dc", "\uc804\uc2dc\ud68c", "\uae30\ud68d\uc804", "\ud2b9\ubcc4\uc804"), "\uc804\uc2dc"),
        (("\uacf5\uc5f0", "\uc5f0\uadf9", "\uc74c\uc545\ud68c", "\ucf58\uc11c\ud2b8", "\uc778\ud615\uadf9", "\ubba4\uc9c0\uceec"), "\uacf5\uc5f0"),
        (("\ubb38\ud654\ud589\uc0ac", "\ud589\uc0ac", "\ucd95\uc81c", "\uc774\ubca4\ud2b8"), "\ud589\uc0ac"),
        (("\uccb4\ud5d8", "\uacac\ud559", "\ud0d0\ubc29", "\ucea0\ud504", "\ub180\uc774"), "\uccb4\ud5d8"),
        (("\uac15\uc88c", "\uac15\uc758", "\uc218\uac15", "\uad50\uc721", "\ud3c9\uc0dd\ud559\uc2b5"), "\uac15\uc88c"),
        (("\ud504\ub85c\uadf8\ub7a8",), "\ud504\ub85c\uadf8\ub7a8"),
    )
    for keywords, value in checks:
        if any(keyword in text for keyword in keywords):
            return value
    return ""


def normalize_program_type(value: Any, *parts: Any) -> str:
    current = clean_text(value)
    inferred = infer_program_type(*parts)
    if not current:
        return inferred
    default_values = {"\uac15\uc88c", "\uad50\uc721", "\uc218\uc5c5", "\uacfc\uc815"}
    broad_values = default_values | {"\ud504\ub85c\uadf8\ub7a8"}
    specific_values = {"\uc804\uc2dc", "\uacf5\uc5f0", "\ud589\uc0ac", "\uccb4\ud5d8", "\uacac\ud559", "\ud504\ub85c\uadf8\ub7a8"}
    if inferred in specific_values and current in broad_values:
        return inferred
    return current


def infer_application_state(
    *,
    application_url: str | None,
    method_text: str | None,
    raw_url: str | None,
    title: str | None,
    description: str | None,
    has_course_data: bool,
) -> tuple[str, bool, str]:
    text = clean_text(" ".join(part for part in [method_text, title, description] if clean_text(part)))
    raw_url_text = clean_text(raw_url).lower()
    if application_url and any(keyword in text for keyword in ONLINE_APPLICATION_KEYWORDS):
        return "ONLINE_RESERVATION", True, "online_application_text"
    if any(keyword in text for keyword in OFFLINE_APPLICATION_KEYWORDS):
        return "OFFLINE_APPLY", False, "offline_application_text"
    if has_course_data:
        return "OFFLINE_APPLY", False, "course_data_default_offline"
    if any(keyword in raw_url_text for keyword in NOTICE_URL_KEYWORDS):
        return "EXTERNAL_NOTICE", False, "notice_or_article_url"
    return "NO_COURSE_DATA", False, "no_structured_course_data"


def normalize_application_type(value: Any, fallback: str) -> str:
    text = clean_text(value).upper()
    mapping = {
        "ONLINE": "ONLINE_RESERVATION",
        "ON": "ONLINE_RESERVATION",
        "RESERVATION": "ONLINE_RESERVATION",
        "ONLINE_RESERVATION": "ONLINE_RESERVATION",
        "OFFLINE": "OFFLINE_APPLY",
        "OFFLINE_APPLY": "OFFLINE_APPLY",
        "NOTICE": "EXTERNAL_NOTICE",
        "EXTERNAL_NOTICE": "EXTERNAL_NOTICE",
        "INFO": "INFO_ONLY",
        "INFO_ONLY": "INFO_ONLY",
        "NO_COURSE_DATA": "NO_COURSE_DATA",
        "BLOCKED": "BLOCKED_OR_JS_ONLY",
        "BLOCKED_OR_JS_ONLY": "BLOCKED_OR_JS_ONLY",
        "FACILITY_RESERVATION": "ONLINE_RESERVATION",
    }
    return mapping.get(text, fallback)


def public_raw_fields(row: dict[str, Any]) -> dict[str, Any]:
    ignored = {"provider", "provider_course_id", "title", "branch", "branch_code"}
    raw: dict[str, Any] = {}
    for key, value in row.items():
        if key in ignored:
            continue
        if isinstance(value, (str, int, float, bool)) or value is None:
            raw[key] = value
        elif isinstance(value, (list, tuple)):
            raw[key] = [str(item) for item in value[:20]]
        elif isinstance(value, dict):
            raw[key] = {str(k): str(v) for k, v in list(value.items())[:50]}
        else:
            raw[key] = str(value)
    return raw


def has_course_evidence(text: str) -> bool:
    text = clean_text(text)
    if not text:
        return False
    patterns = [
        r"\d{4}[./-]\d{1,2}[./-]\d{1,2}",
        r"\d{1,2}\s*[:시]\s*\d{2}",
        r"\d[\d,]*\s*원",
        r"(접수|모집|마감|대기|신청|수강|예약|예매|관람|전시|공연|문화행사|행사기간|관람기간|공연기간|전시기간|교육기간|강좌기간|교육시간|강좌시간|수강료|대상|정원)",
    ]
    return any(re.search(pattern, text) for pattern in patterns)


def is_navigation_title(title: str, evidence: str) -> bool:
    title = clean_text(title)
    if not title:
        return False
    if any(token in title for token in NAV_TITLE_TOKENS):
        return True
    if title in {"\uc218\uac15\uc2e0\uccad", "\ud3c9\uc0dd\ud559\uc2b5", "\ud3c9\uc0dd\ud559\uc2b5\uad00", "\uad50\uc721\uc548\ub0b4", "\uac15\uc88c\uc548\ub0b4"}:
        return not re.search(r"\d{4}[./-]\d{1,2}[./-]\d{1,2}|\d[\d,]*\s*\uC6D0", evidence)
    return False


