def jinju_branch_name_for_all_course_link(link: Any) -> str:
    current = link
    while current is not None:
        parent_li = current.find_parent("li") if hasattr(current, "find_parent") else None
        if parent_li is None:
            break
        direct_link = parent_li.find("a", recursive=False)
        if direct_link is not None and direct_link is not link:
            text = clean_text(direct_link.get_text(" ", strip=True))
            if text and text != "\uc804\uccb4\uac15\uc88c" and "\uc7a5\ub09c\uac10\uc740\ud589" in text and "\ub300\uccb4\uc218\uac15" not in text:
                return text
        current = parent_li
    return ""


HAMAN_WELFARE_AGENCIES = ("AGENCY001", "AGENCY024", "AGENCY003", "AGENCY005", "AGENCY006")


def url_with_query(base_url: str, updates: dict[str, Any]) -> str:
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    for key, value in updates.items():
        if value is None or value == "":
            query.pop(key, None)
        else:
            query[key] = [str(value)]
    return parsed._replace(query=urlencode(query, doseq=True)).geturl()


def lines_from_node(node: Any) -> list[str]:
    if not hasattr(node, "get_text"):
        return []
    return [clean_text(line) for line in node.get_text("\n", strip=True).splitlines() if clean_text(line)]


def first_matching_line(lines: list[str], candidates: set[str]) -> str:
    for line in lines:
        text = clean_text(line)
        if text in candidates:
            return text
    return ""


def first_title_candidate(soup: BeautifulSoup) -> str:
    for selector in ("h1", "h2", "h3", "h4", ".title", ".tit", "caption", "title"):
        for node in soup.select(selector)[:20]:
            text = clean_text(node.get_text(" ", strip=True) if node else "")
            if text and not is_low_value_title(text):
                return text
    for line in lines_from_node(soup)[:180]:
        text = clean_text(line)
        if not text or len(text) > 100 or is_low_value_title(text):
            continue
        if re.match(r"^\[[^\]]{2,30}\]\s*.{2,}", text):
            return text
    return ""


def leading_bracket_label(value: Any) -> str:
    text = clean_text(value)
    match = re.match(r"^[\[\(【]\s*([^\]\)】]{2,40})\s*[\]\)】]", text)
    return clean_text(match.group(1)) if match else ""


def is_generic_venue_name(value: Any) -> bool:
    text = clean_text(value)
    if not text:
        return True
    if len(text) <= 1:
        return True
    generic_values = {
        "-",
        "없음",
        "미정",
        "온라인",
        "비대면",
        "강의실",
        "교육장",
        "교육장소",
        "장소",
        "해당없음",
    }
    if text in generic_values:
        return True
    if re.fullmatch(r"(?:\d+층|[A-Za-z]?\d{1,4}호|제?\d+강의실)", text):
        return True
    if re.search(r"(?:강의실|회의실|교육실|교실)$", text) and not re.search(
        r"(?:학습관|센터|주민센터|도서관|복지관|체육관|문화관|청소년|미술관|박물관)", text
    ):
        return True
    return False


PROMOTABLE_VENUE_KEYS = extend_unique(
    ROOM_KEYS,
    (
        "\uc7a5\uc18c\uba85",
        "\uc7a5\uc18c/\uc704\uce58",
        "\uc7a5\uc18c \ubc0f \uc704\uce58",
        "\ud589\uc0ac\uc7a5",
        "\ud589\uc0ac\uc7a5\uc18c",
        "\uad50\uc721\uc7a5",
        "\uad50\uc721\uc7a5\uc18c",
        "\uac15\uc758\uc7a5\uc18c",
    ),
)

VENUE_HINT_RE = re.compile(
    r"(?:"
    r"\uc13c\ud130|\ub3c4\uc11c\uad00|\ubcf5\uc9c0\uad00|\uccb4\uc721\uad00|\ubb38\ud654\uad00|"
    r"\uc544\ud2b8\uc13c\ud130|\ubc15\ubb3c\uad00|\ubbf8\uc220\uad00|\uae30\ub150\uad00|"
    r"\ubb38\ud654\uc6d0|\ubb38\ud654\ud68c\uad00|\uacf5\uc5f0\uc7a5|\uadf9\uc7a5|\uc18c\uadf9\uc7a5|"
    r"\uac24\ub7ec\ub9ac|\ubba4\uc9c0\uc5c4|\uc2a4\ud14c\uc774\uc158|\uc544\ud2b8\ud640|\ud640|"
    r"\ub300\ud559\uad50|\ub300\ud559|\ud559\uad50|\ucea0\ud37c\uc2a4|\ud559\uc2b5\uad00|\uad50\uc721\uad00|"
    r"\uac15\uc758\uc2e4|\uc2e4\uc2b5\uc2e4|\uacfc\ud559\uad00|\uccb4\ud5d8\uad00|\uc804\uc2dc\uad00|"
    r"\uc218\ub828\uad00|\uc8fc\ubbfc\uc13c\ud130|\ud589\uc815\ubcf5\uc9c0\uc13c\ud130|"
    r"\ud3c9\uc0dd\ud559\uc2b5\uad00|\uc218\ubaa9\uc6d0|\uacf5\uc6d0|\uc804\ub2f9|\ub300\uac15\ub2f9|\uac15\ub2f9"
    r")"
)


def is_region_only_name(value: Any) -> bool:
    text = clean_text(value)
    if not text:
        return True
    if VENUE_HINT_RE.search(text):
        return False
    region_unit = (
        r"(?:\ud2b9\ubcc4\uc2dc|\uad11\uc5ed\uc2dc|\ud2b9\ubcc4\uc790\uce58\uc2dc|"
        r"\ud2b9\ubcc4\uc790\uce58\ub3c4|\ub3c4|\uc2dc|\uad70|\uad6c|\uc74d|\uba74|\ub3d9|\ub9ac)"
    )
    return bool(re.fullmatch(rf"(?:[\uac00-\ud7a3]{{1,14}}{region_unit}\s*){{1,6}}", text))


def normalize_venue_candidate(value: Any, *, require_hint: bool = False) -> str:
    text = clean_text(value)
    if not text or is_generic_venue_name(text) or is_region_only_name(text):
        return ""
    if len(text) > 80:
        return ""
    venue_hints = VENUE_HINT_RE.findall(text)
    if len(text) > 45 and len(set(venue_hints)) >= 4:
        return ""
    if re.match(
        r"^(?:\ub300\uc0c1|\uad50\uc721\ub300\uc0c1|\uc218\uac15\ub300\uc0c1|\ucc38\uc5ec\ub300\uc0c1|"
        r"\uc774\uc6a9\ub300\uc0c1|\uc2e0\uccad\ub300\uc0c1|\uc778\uc6d0|\uc815\uc6d0|\ubaa8\uc9d1\uc778\uc6d0)\b",
        text,
    ):
        return ""
    if re.match(r"^(?:\uae30\uac04|\uc2dc\uac04|\uc77c\uc2dc|\uc77c\uc815)\b", text):
        return ""
    if re.search(
        r"(?:^|\s)(?:\ub300\uc0c1|\uad50\uc721\ub300\uc0c1|\uc218\uac15\ub300\uc0c1|\ucc38\uc5ec\ub300\uc0c1|"
        r"\uc774\uc6a9\ub300\uc0c1|\uc2e0\uccad\ub300\uc0c1|\uc778\uc6d0|\uc815\uc6d0|\ubaa8\uc9d1\uc778\uc6d0)(?:\s|$)",
        text,
    ):
        return ""
    text = re.sub(r"\s+(?:\uc870\ud68c\uc218|\uc870\ud68c|views?)?\s*\d{1,7}$", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+(?:\uc0c1\uc138\ubcf4\uae30|\uc790\uc138\ud788\ubcf4\uae30|\ub354\ubcf4\uae30)$", "", text)
    text = clean_text(text.strip(" -~\u223c\uff5e:：,|\u00b7"))
    if not text or is_generic_venue_name(text) or is_region_only_name(text):
        return ""
    if require_hint and not VENUE_HINT_RE.search(text):
        return ""
    if re.search(r"\d{4}[./-]\d{1,2}[./-]\d{1,2}", text):
        return ""
    return text[:100]


def raw_pair_maps_from_row(row: dict[str, Any]) -> list[dict[str, Any]]:
    raw_fields = row.get("raw_fields")
    if not isinstance(raw_fields, dict):
        return []
    maps: list[dict[str, Any]] = []
    for key in ("pairs", "list_pairs", "detail_pairs"):
        value = raw_fields.get(key)
        if isinstance(value, dict):
            maps.append(value)
    maps.append(raw_fields)
    return maps


def is_generic_parser_row(row: dict[str, Any]) -> bool:
    raw_fields = row.get("raw_fields")
    if not isinstance(raw_fields, dict):
        return False
    return clean_text(raw_fields.get("parser")).lower().startswith("generic_")


def structured_venue_name_from_row(row: dict[str, Any]) -> str:
    direct = normalize_venue_candidate(
        row.get("venue_name") or row.get("venue") or row.get("place") or row.get("room"),
        require_hint=is_generic_parser_row(row),
    )
    if direct:
        return direct
    top_level = {
        str(key): value
        for key, value in row.items()
        if isinstance(key, str) and key not in {"raw_fields", "description", "title"}
    }
    candidate = normalize_venue_candidate(first_by_keys(top_level, PROMOTABLE_VENUE_KEYS))
    if candidate:
        return candidate
    for pair_map in raw_pair_maps_from_row(row):
        candidate = normalize_venue_candidate(first_by_keys(pair_map, PROMOTABLE_VENUE_KEYS))
        if candidate:
            return candidate
    return ""


def trailing_venue_name_from_text(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    label_pattern = (
        r"(?:\uc7a5\uc18c|\uc7a5\uc18c\uba85|\uc7a5\uc18c/\uc704\uce58|\ud589\uc0ac\uc7a5\uc18c|"
        r"\uad50\uc721\uc7a5\uc18c|\uac15\uc758\uc7a5\uc18c|\uc704\uce58)\s*[:：]\s*"
    )
    stop_pattern = (
        r"(?=\s+(?:\ub300\uc0c1|\uae30\uac04|\uc77c\uc2dc|\uc2dc\uac04|\uc815\uc6d0|\ubb38\uc758|"
        r"\uc811\uc218|\uc2e0\uccad|\ube44\uc6a9|\uc694\uae08|\uc218\uac15\ub8cc)\s*[:：]|\Z)"
    )
    for match in re.finditer(label_pattern + r"(.{2,120}?)" + stop_pattern, text):
        candidate = normalize_venue_candidate(match.group(1))
        if candidate:
            return candidate

    date_pattern = r"(?:20\d{2}[./-]\s*\d{1,2}[./-]\s*\d{1,2}|\d{4}\s*\ub144\s*\d{1,2}\s*\uc6d4\s*\d{1,2}\s*\uc77c)"
    time_pattern = r"\d{1,2}\s*[:\uc2dc]\s*\d{0,2}\s*(?:\ubd84)?"
    marker_ends = [match.end() for match in re.finditer(date_pattern, text)]
    marker_ends.extend(match.end() for match in re.finditer(time_pattern, text))
    for start in sorted(marker_ends, reverse=True):
        candidate_text = text[start:]
        candidate_text = re.split(
            r"\s+(?:\uc2e0\uccad|\uc811\uc218|\uc608\uc57d|\uc608\ub9e4|\uc0c1\uc138\ubcf4\uae30|\uc790\uc138\ud788\ubcf4\uae30)\b",
            candidate_text,
            maxsplit=1,
        )[0]
        candidate = normalize_venue_candidate(candidate_text, require_hint=True)
        if candidate:
            return candidate
    return ""


def infer_venue_name_from_row(row: dict[str, Any], *, allow_text_fallback: bool = False) -> str:
    candidate = structured_venue_name_from_row(row)
    if candidate:
        return candidate
    if allow_text_fallback:
        candidate = trailing_venue_name_from_text(row.get("description"))
        if candidate:
            return candidate
        return trailing_venue_name_from_text(row.get("title"))
    return ""


def haman_course_row_from_link(
    target: CrawlTarget,
    current_url: str,
    link: Any,
    parser_name: str,
) -> dict[str, Any] | None:
    lines = lines_from_node(link)
    if len(lines) < 2:
        return None
    status = status_from_lines(lines) or lines[0]
    title = course_title_from_status_lines(lines, status)
    if not title or is_low_value_title(title):
        return None
    pairs = pairs_from_lines(lines)
    raw_url = normalize_link(current_url, link.get("href") if hasattr(link, "get") else None) or current_url
    branch = clean_text(pairs.get("교육기관")) or target.branch
    capacity = clean_text(pairs.get("신청/정원") or pairs.get("정원"))
    capacity_current, capacity_total = parse_capacity_pair(capacity)
    if capacity_total is None:
        capacity_total = parse_capacity_number(pairs.get("정원"))
    schedule_parts = [clean_text(pairs.get("강좌요일")), clean_text(pairs.get("강좌시간"))]
    schedule_raw = clean_text(" ".join(part for part in schedule_parts if part))
    application_method = clean_text(pairs.get("접수방법") or pairs.get("선별방법"))
    row = {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
        "title": title,
        "branch": branch,
        "category": clean_text(pairs.get("분류")) or "교육/강좌",
        "raw_url": raw_url,
        "application_url": raw_url if "인터넷" in application_method or "접수" in status else "",
        "status": status,
        "fee": clean_text(pairs.get("수강료") or pairs.get("부대비용")),
        "period": clean_text(pairs.get("교육기간")),
        "apply_period": clean_text(pairs.get("접수기간")),
        "schedule_raw": schedule_raw,
        "target": clean_text(pairs.get("교육대상") or pairs.get("대상")),
        "room": clean_text(pairs.get("교육장소")),
        "venue_name": clean_text(pairs.get("교육장소")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "application_method_raw": application_method,
        "description": clean_text(link.get_text(" ", strip=True)),
        "raw_fields": {"pairs": pairs, "lines": lines, "parser": parser_name},
    }
    return row


def enrich_haman_course_detail(row: dict[str, Any], detail_soup: BeautifulSoup) -> None:
    detail_node = detail_soup.select_one(".edu1view")
    if not detail_node:
        return
    lines = lines_from_node(detail_node)
    pairs = pairs_from_lines(lines)
    row["fee"] = clean_text(pairs.get("수강료") or row.get("fee"))
    row["period"] = clean_text(pairs.get("교육기간") or row.get("period"))
    row["apply_period"] = clean_text(pairs.get("접수기간") or row.get("apply_period"))
    schedule_parts = [clean_text(pairs.get("강좌요일")), clean_text(pairs.get("강좌시간"))]
    row["schedule_raw"] = clean_text(" ".join(part for part in schedule_parts if part)) or row.get("schedule_raw")
    row["room"] = clean_text(pairs.get("교육장소") or row.get("room"))
    row["venue_name"] = clean_text(pairs.get("교육장소") or row.get("venue_name"))
    row["capacity_total"] = parse_capacity_number(pairs.get("정원")) or row.get("capacity_total")
    row["capacity_current"] = parse_capacity_number(pairs.get("신청인원")) or row.get("capacity_current")
    row["phone"] = clean_text(pairs.get("문의처") or row.get("phone"))
    row["instructor"] = clean_text(pairs.get("강사명") or row.get("instructor"))
    row["description"] = clean_text(detail_node.get_text(" ", strip=True)) or row.get("description")
    raw_fields = row.setdefault("raw_fields", {})
    if isinstance(raw_fields, dict):
        raw_fields["detail_pairs"] = pairs


def collect_haman_welfare_lifelong(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    agency_counts: dict[str, int] = {}
    parsed = urlparse(target.url)
    query_agency = clean_text((parse_qs(parsed.query).get("agency") or [""])[0])
    agencies = [query_agency] if query_agency else list(HAMAN_WELFARE_AGENCIES)

    for agency in agencies:
        agency_count = 0
        for page in range(1, max_pages + 1):
            current_url = url_with_query(target.url, {"agency": agency, "cpage": page})
            soup = fetch_soup(s, current_url, timeout=timeout)
            pages += 1
            page_rows = 0
            for link in soup.select(".edu1list a[href*='amode=view'][href*='idx=']"):
                row = haman_course_row_from_link(target, current_url, link, "haman_lifelong_agency_list")
                if not row:
                    continue
                raw_url = clean_text(row.get("raw_url"))
                if raw_url and detail_pages < detail_limit:
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        enrich_haman_course_detail(row, detail_soup)
                    except Exception as exc:
                        logger.debug("Haman detail fetch failed %s: %s", raw_url, exc)
                rows.append(row)
                page_rows += 1
                agency_count += 1
            pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='cpage=']"))
            if page_rows == 0:
                break
        agency_counts[agency] = agency_count

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "agencies": len(agencies),
        "agency_rows": agency_counts,
    }
    return dedupe_rows(rows), "haman_lifelong_agency_list+detail", meta


def collect_ulsannamgu_resident_autonomy(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    first_soup = fetch_soup(s, target.url, timeout=timeout)
    per_target_limit = int(target.extra.get("per_target_limit") or 0)
    options: list[tuple[str, str]] = []
    for option in first_soup.select("select[name='dongName'] option[value]"):
        value = clean_text(option.get("value"))
        name = clean_text(option.get_text(" ", strip=True))
        if value:
            options.append((value, name))
    if not options:
        value = clean_text((parse_qs(urlparse(target.url).query).get("dongName") or [""])[0])
        options = [(value, target.branch)] if value else [("", target.branch)]

    rows: list[dict[str, Any]] = []
    pages = 0
    contact_by_branch: dict[str, str] = {}
    for dong_value, dong_name in options[: max(1, max_pages)]:
        if per_target_limit > 0 and len(rows) >= per_target_limit:
            break
        current_url = url_with_query(target.url, {"dongName": dong_value, "pageIndex": None})
        soup = first_soup if current_url == target.url else fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        for table in soup.find_all("table"):
            header_cells = [clean_text(cell.get_text(" ", strip=True)) for cell in table.select("tr:first-child th")]
            if header_cells and {"센터명", "전화번호"}.issubset(set(header_cells)):
                for tr in table.find_all("tr")[1:]:
                    cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
                    for index in range(0, len(cells) - 1, 2):
                        if cells[index] and cells[index + 1]:
                            contact_by_branch[cells[index]] = cells[index + 1]

        for table in soup.find_all("table"):
            header_row = table.find("tr")
            headers = [clean_text(cell.get_text(" ", strip=True)) for cell in header_row.find_all(["th", "td"])] if header_row else []
            if "강좌명" not in headers or "교육기관" not in headers:
                continue
            for tr in table.find_all("tr")[1:]:
                cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
                if len(cells) < len(headers):
                    continue
                pairs = {headers[index]: cells[index] for index in range(min(len(headers), len(cells)))}
                title = clean_text(pairs.get("강좌명"))
                if not title or is_low_value_title(title):
                    continue
                branch = clean_text(pairs.get("교육기관") or dong_name or target.branch)
                schedule_raw = clean_text(" ".join(part for part in [pairs.get("수업요일"), pairs.get("수업시간")] if clean_text(part)))
                capacity = clean_text(pairs.get("모집인원"))
                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, current_url, title, branch),
                        "title": title,
                        "branch": branch,
                        "category": "주민자치프로그램",
                        "raw_url": current_url,
                        "application_url": "",
                        "status": "",
                        "fee": clean_text(pairs.get("수강료(3개월분)") or pairs.get("수강료")),
                        "period": "",
                        "apply_period": "",
                        "schedule_raw": schedule_raw,
                        "target": "",
                        "room": clean_text(pairs.get("장소")),
                        "venue_name": clean_text(pairs.get("장소")),
                        "capacity": capacity,
                        "capacity_total": parse_capacity_number(capacity),
                        "phone": clean_text(contact_by_branch.get(branch)),
                        "description": clean_text(" ".join(cells)),
                        "raw_fields": {"pairs": pairs, "parser": "ulsannamgu_resident_autonomy_table"},
                    }
                )
                if per_target_limit > 0 and len(rows) >= per_target_limit:
                    break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(options),
        "pagination_detected": False,
        "recursion_depth": 0,
        "branches": len(options),
    }
    return dedupe_rows(rows), "ulsannamgu_resident_autonomy_table", meta


def bukgu_daegu_category_from_soup(soup: BeautifulSoup, fallback: str) -> str:
    for selector in (".location strong", ".sub_title", ".content_title", "h1", "h2", "h3"):
        node = soup.select_one(selector)
        text = clean_text(node.get_text(" ", strip=True) if node else "")
        if text and "서비스 접속" not in text:
            return text
    return fallback


def bukgu_daegu_page_url(base_url: str, page: int) -> str:
    if page <= 1:
        return base_url
    return url_with_query(base_url, {"pageIndex": page})


def bukgu_daegu_row_from_card(
    target: CrawlTarget,
    current_url: str,
    category: str,
    card: Any,
) -> dict[str, Any] | None:
    lines = lines_from_node(card)
    if len(lines) < 2:
        return None
    status = status_from_lines(lines) or lines[0]
    title_node = card.select_one(".le_name") if hasattr(card, "select_one") else None
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    if not title:
        title = course_title_from_status_lines(lines, status)
    if not title or is_low_value_title(title):
        return None
    pairs = pairs_from_lines(lines)
    link = card.find("a", href=True) if hasattr(card, "find") else None
    raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
    capacity = clean_text(pairs.get("수강인원") or pairs.get("교육대상/정원"))
    capacity_current, capacity_total = parse_capacity_pair(capacity)
    if capacity_total is None:
        capacity_total = parse_capacity_number(capacity)
    row = {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
        "title": title,
        "branch": target.branch,
        "category": category,
        "raw_url": raw_url,
        "application_url": raw_url if "접수" in status else "",
        "status": status,
        "fee": "",
        "period": clean_text(pairs.get("교육기간")),
        "apply_period": clean_text(pairs.get("접수기간")),
        "schedule_raw": clean_text(pairs.get("요일/교육시간")),
        "target": clean_text(pairs.get("교육대상") or pairs.get("교육대상/정원")),
        "room": clean_text(pairs.get("교육장소")),
        "venue_name": clean_text(pairs.get("교육장소")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "description": clean_text(card.get_text(" ", strip=True)),
        "raw_fields": {"pairs": pairs, "lines": lines, "parser": "bukgu_daegu_lec_list"},
    }
    return row


def enrich_bukgu_daegu_detail(row: dict[str, Any], detail_soup: BeautifulSoup) -> None:
    detail_pairs = pairs_from_tables(detail_soup)
    if not detail_pairs:
        return
    row["period"] = clean_text(detail_pairs.get("교육기간") or row.get("period"))
    row["apply_period"] = clean_text(detail_pairs.get("접수기간") or row.get("apply_period"))
    row["schedule_raw"] = clean_text(detail_pairs.get("요일/교육시간") or row.get("schedule_raw"))
    row["room"] = clean_text(detail_pairs.get("교육장소") or row.get("room"))
    row["venue_name"] = clean_text(detail_pairs.get("교육장소") or row.get("venue_name"))
    row["target"] = clean_text(detail_pairs.get("교육대상/정원") or row.get("target"))
    row["fee"] = clean_text(detail_pairs.get("수강료") or row.get("fee"))
    row["instructor"] = clean_text(detail_pairs.get("강사명") or row.get("instructor"))
    row["phone"] = clean_text(detail_pairs.get("문의") or row.get("phone"))
    capacity_current, capacity_total = parse_capacity_pair(detail_pairs.get("교육대상/정원"))
    row["capacity_current"] = capacity_current or row.get("capacity_current")
    row["capacity_total"] = capacity_total or parse_capacity_number(detail_pairs.get("교육대상/정원")) or row.get("capacity_total")
    raw_fields = row.setdefault("raw_fields", {})
    if isinstance(raw_fields, dict):
        raw_fields["detail_pairs"] = detail_pairs


def collect_bukgu_daegu_reservation(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    page_budget = PageBudget(max_pages)
    list_urls = [clean_text(url) for url in (target.extra.get("list_urls") or []) if clean_text(url)]
    if not list_urls:
        list_urls = [target.url]
    list_urls = list(dict.fromkeys(list_urls))
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pagination_detected = False
    completed_list_urls = 0

    for list_url in list_urls:
        list_complete = False
        for page in range(1, max_pages + 1):
            if not page_budget.claim():
                break
            current_url = bukgu_daegu_page_url(list_url, page)
            soup = fetch_soup(s, current_url, timeout=timeout)
            category = bukgu_daegu_category_from_soup(soup, target.branch)
            page_rows = 0
            for card in soup.select(".lec_list"):
                row = bukgu_daegu_row_from_card(target, current_url, category, card)
                if not row:
                    continue
                raw_url = clean_text(row.get("raw_url"))
                if raw_url and raw_url != current_url and detail_pages < detail_limit:
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        enrich_bukgu_daegu_detail(row, detail_soup)
                    except Exception as exc:
                        logger.debug("Bukgu Daegu detail fetch failed %s: %s", raw_url, exc)
                rows.append(row)
                page_rows += 1
            pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='pageIndex=']"))
            if page_rows == 0:
                list_complete = True
                break
            if not soup.select(".pagination, .paging, a[href*='pageIndex=']"):
                list_complete = True
                break
        if list_complete:
            completed_list_urls += 1
        if page_budget.exhausted and completed_list_urls < len(list_urls):
            break

    pagination_complete = completed_list_urls == len(list_urls)
    meta = {
        "pages": page_budget.used,
        "detail_pages": detail_pages,
        "discovered_links": len(list_urls),
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_complete,
        "pagination_exhausted": pagination_complete,
        "page_cap_reached": page_budget.exhausted and not pagination_complete,
        "source_cap_reached": not pagination_complete,
        "completed_list_urls": completed_list_urls,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "bukgu_daegu_lec_list+detail", meta


def discover_jinju_toybank_branches(
    soup: BeautifulSoup,
    base_url: str,
) -> list[tuple[str, str, str]]:
    branches: list[tuple[str, str, str]] = []
    seen_urls: set[str] = set()
    fallback_by_url = {url: (code, name, url) for code, name, url in JINJU_TOYBANK_FALLBACK_BRANCHES}
    for link in soup.find_all("a", href=True):
        text = clean_text(link.get_text(" ", strip=True))
        branch_name = jinju_branch_name_for_all_course_link(link) or text
        if "장난감은행" not in branch_name or "대체수강" in branch_name:
            continue
        url = normalize_link(base_url, link.get("href"))
        if not url or url in seen_urls:
            continue
        fallback_branch = fallback_by_url.get(url)
        if not fallback_branch:
            continue
        branches.append(fallback_branch)
        seen_urls.add(url)
    if branches:
        return branches
    return list(JINJU_TOYBANK_FALLBACK_BRANCHES)


def jinju_page_url(branch_url: str, page: int) -> str:
    return url_with_query(branch_url, {"cpage": max(1, page)})


def jinju_last_page(soup: BeautifulSoup, current_url: str) -> int:
    pages = [1]
    for link in soup.select("a[href*='cpage=']"):
        href = normalize_link(current_url, link.get("href"))
        page_text = clean_text((parse_qs(urlparse(href).query).get("cpage") or [""])[0])
        if page_text.isdigit():
            pages.append(int(page_text))
        label = clean_text(link.get_text(" ", strip=True))
        if label.isdigit():
            pages.append(int(label))
    return max(pages)


def parse_jinju_toybank_item(
    target: CrawlTarget,
    item: Any,
    current_url: str,
    branch_code: str,
    branch_name: str,
    branch_url: str,
) -> dict[str, Any] | None:
    lines = lines_from_node(item)
    if len(lines) < 3:
        return None
    status = status_from_lines(lines)
    if not status:
        status = first_matching_line(lines, {"접수중", "접수마감", "대기", "신청대기", "정원마감"})
    title = course_title_from_status_lines(lines, status)
    if not title or is_low_value_title(title):
        return None
    pairs = pairs_from_lines(lines)
    link = item.find("a", href=True) if hasattr(item, "find") else None
    raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
    capacity = clean_text(pairs.get("정원/접수인원/대기자정원") or pairs.get("정원"))
    capacity_current, capacity_total = parse_capacity_pair(capacity)
    if capacity_total is None:
        capacity_total = parse_capacity_number(capacity)
    method_parts = [line for line in lines if line in {"인터넷", "방문", "전화"}]
    application_method = clean_text(" ".join(method_parts))
    fee = clean_text(pairs.get("수강료"))
    row = {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch_name),
        "title": title,
        "branch": branch_name,
        "branch_code": branch_code,
        "branch_url": branch_url,
        "category": clean_text(pairs.get("교육구분")),
        "raw_url": raw_url,
        "application_url": raw_url if "인터넷" in application_method or "접수" in status else "",
        "status": status,
        "fee": fee,
        "period": clean_text(pairs.get("교육기간")),
        "apply_period": clean_text(pairs.get("접수일시")),
        "schedule_raw": clean_text(pairs.get("요일시간")),
        "target": clean_text(pairs.get("신청대상")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "application_method_raw": application_method,
        "description": clean_text(item.get_text(" ", strip=True)),
        "raw_fields": {"pairs": pairs, "lines": lines, "parser": "jinju_toybank_branch_list"},
    }
    return row


def collect_jinju_toybank_booking(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    discovery_soup = fetch_soup(s, target.url, timeout=timeout)
    branches = discover_jinju_toybank_branches(discovery_soup, target.url)
    rows: list[dict[str, Any]] = []
    pages = 1
    pagination_detected = False
    branch_page_counts: dict[str, int] = {}
    branch_row_counts: dict[str, int] = {}

    for branch_code, branch_name, branch_url in branches:
        first_url = jinju_page_url(branch_url, 1)
        first_soup = fetch_soup(s, first_url, timeout=timeout)
        pages += 1
        last_page = min(max_pages, jinju_last_page(first_soup, first_url))
        branch_page_counts[branch_name] = last_page
        for page in range(1, last_page + 1):
            if page == 1:
                soup = first_soup
                current_url = first_url
            else:
                current_url = jinju_page_url(branch_url, page)
                soup = fetch_soup(s, current_url, timeout=timeout)
                pages += 1
            page_rows = 0
            for item in soup.select(".cp31edu1list1 > ul > li"):
                row = parse_jinju_toybank_item(target, item, current_url, branch_code, branch_name, branch_url)
                if row:
                    rows.append(row)
                    page_rows += 1
            branch_row_counts[branch_name] = branch_row_counts.get(branch_name, 0) + page_rows
            pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='cpage=']"))
            if page_rows == 0:
                break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(branches),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "branches": len(branches),
        "branch_pages": branch_page_counts,
        "branch_rows": branch_row_counts,
    }
    return dedupe_rows(rows), "jinju_toybank_branch_list", meta


SEONGNAM_LIST_LABEL_KEYS = {
    "\uAC15\uC88C\uBA85",
    "\uAD50\uC721\uAE30\uAD00",
    "\uAD50\uC721\uAE30\uAC04",
    "\uC6B4\uC601\uD615\uD0DC",
    "\uBAA8\uC9D1\uC778\uC6D0/\uC811\uC218\uC778\uC6D0",
    "\uC0C1\uD0DC",
    "\uC218\uAC15\uC815\uBCF4",
}


def seongnam_label_key(value: Any) -> str:
    return re.sub(r"[\s:：]+", "", clean_text(value))


def seongnam_value_lines(node: BeautifulSoup | None) -> list[str]:
    if node is None:
        return []
    lines = [clean_text(line) for line in node.get_text("\n", strip=True).splitlines() if clean_text(line)]
    return [line for line in lines if seongnam_label_key(line) not in SEONGNAM_LIST_LABEL_KEYS]


def collect_seongnam_learning_list(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = tr.find_all("td")
            if len(cells) < 4:
                continue
            lines = [clean_text(line) for line in tr.get_text("\n", strip=True).splitlines() if clean_text(line)]
            title_link = cells[1].find("a") if len(cells) > 1 else None
            title_lines = seongnam_value_lines(cells[1] if len(cells) > 1 else None)
            title = next((line for line in title_lines if not is_low_value_title(line)), "")
            if not title and title_link:
                title = clean_text(title_link.get_text(" ", strip=True))
            if not title or is_low_value_title(title):
                continue
            branch_lines = seongnam_value_lines(cells[2] if len(cells) > 2 else None)
            branch_from_title = next(
                (
                    line
                    for line in title_lines[1:]
                    if line and not is_low_value_title(line) and seongnam_label_key(line) not in {"강좌", "시설"}
                ),
                "",
            )
            branch = branch_from_title or next(iter(branch_lines), target.branch)
            date_lines = seongnam_value_lines(cells[3] if len(cells) > 3 else None)
            date_indexes = [
                index for index, line in enumerate(date_lines)
                if re.fullmatch(r"\d{2}[.]\d{2}[.]\d{2}[.]?", line)
            ]
            period = ""
            schedule = ""
            if len(date_indexes) >= 2:
                start_date = date_lines[date_indexes[0]].rstrip(".")
                end_date = date_lines[date_indexes[1]].rstrip(".")
                period = f"{normalize_short_korean_date(start_date)} ~ {normalize_short_korean_date(end_date)}"
                schedule = clean_text(" ".join(line for line in date_lines[date_indexes[1] + 1:] if line != "~"))
            recruitment_lines = seongnam_value_lines(cells[4] if len(cells) > 4 else None)
            operation = next(iter(recruitment_lines), "")
            if operation:
                operation_key = seongnam_label_key(operation)
                if "모집인원" not in operation_key:
                    schedule = clean_text(" ".join(part for part in [schedule, operation] if part))
            capacity_lines = seongnam_value_lines(cells[5] if len(cells) > 5 else None)
            capacity = next(iter(capacity_lines), "")
            if recruitment_lines and "모집인원" in seongnam_label_key(recruitment_lines[0]):
                capacity = next((line for line in recruitment_lines[1:] if "명" in line or "인원" in line), capacity)
            status_values = {
                "접수중", "대기접수", "대기자신청", "대기자접수", "접수예정", "신청대기",
                "접수마감", "마감", "정원마감", "신청마감", "종료",
            }
            status_pool = [
                *seongnam_value_lines(cells[5] if len(cells) > 5 else None),
                *seongnam_value_lines(cells[6] if len(cells) > 6 else None),
                *lines,
            ]
            status = next((line for line in status_pool if line in status_values), "")
            if not status:
                status = next(iter(seongnam_value_lines(cells[6] if len(cells) > 6 else None)), "") or status_from_lines(lines)
            apply_period = ""
            apply_index = next(
                (
                    index for index, line in enumerate(lines)
                    if line in {
                        "\uC77C\uBC18 \uC811\uC218",
                        "\uC77C\uBC18 \uC778\uD130\uB137\uC811\uC218",
                        "\uC77C\uBC18 \uC778\uD130\uB137 \uC811\uC218",
                        "\uC811\uC218\uAE30\uAC04",
                    }
                ),
                -1,
            )
            if apply_index >= 0:
                apply_dates = [
                    line
                    for line in lines[apply_index + 1: apply_index + 8]
                    if re.search(r"\d{2}[.]\d{2}[.]\d{2}", line)
                ][:2]
                if len(apply_dates) == 2:
                    apply_period = f"{normalize_short_korean_date(apply_dates[0].rstrip('.'))} ~ {normalize_short_korean_date(apply_dates[1].rstrip('.'))}"
            onclick = ""
            link = tr.find("a", onclick=True)
            if link:
                onclick = clean_text(link.get("onclick"))
            match = re.search(r"fn_learning_detail\('([^']+)'\)", onclick)
            raw_url = (
                urljoin(current_url, f"/ilms/learning/learningDetail.do?learning_id={match.group(1)}")
                if match
                else current_url
            )
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": "",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "별도 안내",
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule,
                    "target": "",
                    "capacity": capacity,
                    "description": clean_text(tr.get_text(" ", strip=True)),
                    "raw_fields": {"lines": lines, "parser": "ilms_learning_table"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ilms_learning_table", meta


BSSEOGU_EDU_LIST_MENU = "DOM_000000703001001000"
BSSEOGU_EDU_DETAIL_MENU = "DOM_000000703001004000"


def bsseogu_line_value(lines: list[str], label: str) -> str:
    prefix = f"{label} :"
    for line in lines:
        if line.startswith(prefix):
            return clean_text(line.split(":", 1)[-1])
    return ""


def bsseogu_course_detail_url(base_url: str, el_code: str) -> str:
    return urljoin(
        base_url,
        "/edu/index.bsseogu?" + urlencode({"menuCd": BSSEOGU_EDU_DETAIL_MENU, "el_code": el_code}),
    )


def collect_bsseogu_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    base_query["menuCd"] = [BSSEOGU_EDU_LIST_MENU]
    seen_codes: set[str] = set()

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["nowPage"] = [str(page)]
        current_url = urlunparse(("https", "www.bsseogu.go.kr", "/edu/index.bsseogu", "", urlencode(query, doseq=True), ""))
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("#contents table tbody tr"):
            cells = tr.find_all("td")
            if len(cells) < 6:
                continue
            title_cell_lines = lines_from_soup(cells[0])
            if not title_cell_lines:
                continue
            title = re.sub(r"^\d+[.]\s*", "", title_cell_lines[0]).strip()
            if not title or is_low_value_title(title):
                continue
            link = tr.find("a", onclick=True) or tr.find("a", href=True)
            onclick = clean_text(link.get("onclick") if link else "")
            code_match = re.search(r"view_flag\('([^']+)'\)", onclick)
            if not code_match:
                href = clean_text(link.get("href") if link else "")
                code_match = re.search(r"[?&]el_code=([^&#]+)", href)
            el_code = clean_text(code_match.group(1) if code_match else "")
            if not el_code or el_code in seen_codes:
                continue
            seen_codes.add(el_code)
            raw_url = bsseogu_course_detail_url(current_url, el_code)
            list_period = normalize_mixed_date_range(bsseogu_line_value(title_cell_lines, "교육기간"))
            list_apply_period = normalize_mixed_date_range(bsseogu_line_value(title_cell_lines, "접수기간"))
            list_venue = bsseogu_line_value(title_cell_lines, "교육장소")
            detail_pairs: dict[str, str] = {}
            description = clean_text(tr.get_text(" ", strip=True))
            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_tables(detail_soup.select_one("#contents") or detail_soup)
                    detail_title = clean_text(detail_pairs.get("강좌명"))
                    if detail_title:
                        title = re.sub(r"^\d+[.]\s*", "", detail_title).strip()
                    description = clean_text(detail_pairs.get("상세내용")) or description
                except Exception as exc:
                    logger.debug("bsseogu detail fetch failed %s: %s", raw_url, exc)
            venue_name = clean_text(detail_pairs.get("교육장소") or detail_pairs.get("학습기관") or list_venue)
            schedule_raw = clean_text(detail_pairs.get("교육시간"))
            fee = clean_text(detail_pairs.get("수강료") or clean_text(cells[4].get_text(" ", strip=True))) or "별도 안내"
            target_text = clean_text(detail_pairs.get("교육대상") or cells[2].get_text(" ", strip=True)) or "전체"
            capacity = clean_text(detail_pairs.get("교육정원 / 대기정원") or cells[1].get_text(" ", strip=True))
            status = clean_text(detail_pairs.get("상태") or lines_from_soup(cells[5])[0] if lines_from_soup(cells[5]) else "")
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, venue_name or target.branch),
                    "title": title,
                    "branch": target.branch,
                    "branch_code": target.provider,
                    "category": "평생학습강좌",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status_from_lines([status]) or status,
                    "fee": fee,
                    "material_fee": extract_material_fee_amount(description),
                    "period": normalize_mixed_date_range(detail_pairs.get("학습기간") or list_period),
                    "apply_period": normalize_mixed_date_range(detail_pairs.get("접수기간") or list_apply_period),
                    "schedule_raw": schedule_raw,
                    "target": target_text,
                    "capacity": capacity,
                    "venue_name": venue_name,
                    "room": venue_name,
                    "phone": clean_text(detail_pairs.get("교육문의전화")),
                    "instructor": clean_instructor_name(detail_pairs.get("강사정보")),
                    "application_method_raw": clean_text(detail_pairs.get("접수방법") or cells[3].get_text(" ", strip=True)),
                    "description": description or clean_text(" ".join(title_cell_lines)),
                    "program_type": "강좌",
                    "collection_category": "평생학습",
                    "domain_category": "평생교육",
                    "collection_type": "static_html+detail_html",
                    "raw_fields": {
                        "parser": "bsseogu_lifelong_table+detail",
                        "el_code": el_code,
                        "list_lines": title_cell_lines,
                        "detail_pairs": detail_pairs,
                    },
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='nowPage=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_codes),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "no_current_data": pages > 0 and not rows,
        "no_current_reason": "no_bsseogu_lifelong_courses" if pages > 0 and not rows else "",
    }
    return dedupe_rows(rows), "bsseogu_lifelong_table+detail", meta


