DONGGU_ULSAN_MEM_VENUES = {
    "B0000005": "동구평생학습관",
    "B0000006": "꽃바위문화관",
}


def collect_donggu_ulsan_program_cards(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    parsed = urlparse(target.url)
    mem_match = re.search(r"/lecture/([^/]+)/list[.]do", parsed.path)
    mem_id = mem_match.group(1) if mem_match else ""
    default_venue = DONGGU_ULSAN_MEM_VENUES.get(mem_id, target.branch)
    labels = {"구분", "강습기간", "강습시간", "수강료"}

    for item in soup.select("#contents .apply_list li"):
        link = item.select_one(".tit a[href]") or item.find("a", href=True)
        title = clean_text(link.get_text(" ", strip=True) if link else "")
        if not title or is_low_value_title(title):
            continue
        raw_url = normalize_link(target.url, link.get("href") if link else None) or target.url
        lines = lines_from_soup(item)
        pairs = sequence_lines_to_pairs(lines, labels)
        status = ""
        if len(lines) > 1 and lines[1] not in labels:
            status = lines[1]
        category = clean_text(pairs.get("구분"))
        period = normalize_mixed_date_range(pairs.get("강습기간", ""))
        schedule_raw = clean_text(pairs.get("강습시간"))
        fee = clean_text(pairs.get("수강료")) or "별도 안내"
        target_text = extract_target_text(title) or "전체"
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, default_venue),
                "title": title,
                "branch": target.branch,
                "branch_code": target.provider,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": normalize_status(status, clean_text(item.get_text(" ", strip=True))),
                "fee": fee,
                "period": period,
                "schedule_raw": schedule_raw,
                "target": target_text,
                "venue_name": default_venue,
                "room": default_venue,
                "description": clean_text(item.get_text(" ", strip=True)),
                "program_type": "강좌",
                "collection_category": "평생학습",
                "domain_category": "평생교육",
                "collection_type": "static_html",
                "raw_fields": {
                    "parser": "donggu_ulsan_program_cards",
                    "mem_id": mem_id,
                    "lines": lines,
                    "pairs": pairs,
                },
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
        "no_current_data": not rows,
        "no_current_reason": "no_donggu_ulsan_programs" if not rows else "",
    }
    return dedupe_rows(rows), "donggu_ulsan_program_cards", meta


def dh_split_apply_and_period(value: str) -> tuple[str, str]:
    ranges = re.findall(
        r"\d{4}[-.]\d{1,2}[-.]\d{1,2}\s*~\s*\d{4}[-.]\d{1,2}[-.]\d{1,2}",
        clean_text(value),
    )
    apply_period = normalize_mixed_date_range(ranges[0]) if ranges else ""
    period = normalize_mixed_date_range(ranges[1]) if len(ranges) > 1 else ""
    return apply_period, period


def collect_dh_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    seen: set[str] = set()

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query.setdefault("year", [str(datetime.now().year)])
        query.setdefault("pageUnit", ["10"])
        query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 8:
                continue
            link = tr.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            if raw_url in seen:
                continue
            seen.add(raw_url)
            title = clean_text(link.get_text(" ", strip=True) if link else cells[2])
            if not title or is_low_value_title(title):
                continue
            apply_period, period = dh_split_apply_and_period(cells[3])
            detail_pairs: dict[str, str] = {}
            description = clean_text(tr.get_text(" ", strip=True))
            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_tables(detail_soup.select_one("#contents") or detail_soup)
                    period = normalize_mixed_date_range(detail_pairs.get("교육기간") or period)
                    apply_period = normalize_mixed_date_range(detail_pairs.get("접수기간") or apply_period)
                    description = clean_text(detail_pairs.get("강좌소개")) or description
                except Exception as exc:
                    logger.debug("dh detail fetch failed %s: %s", raw_url, exc)
            fee = clean_text(detail_pairs.get("수강료")) or "별도 안내"
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "branch_code": target.provider,
                    "category": cells[1],
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": normalize_status(cells[7], description),
                    "fee": fee,
                    "material_fee": extract_material_fee_amount(description),
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": clean_text(detail_pairs.get("교육시간") or cells[4]),
                    "target": "동해시민",
                    "capacity": clean_text(detail_pairs.get("접수현황") or cells[6]),
                    "room": clean_text(detail_pairs.get("교육장")),
                    "venue_name": "동해시 평생학습관",
                    "instructor": clean_instructor_name(detail_pairs.get("강사명")),
                    "application_method_raw": clean_text(detail_pairs.get("선발방법") or cells[5]),
                    "description": description,
                    "program_type": "강좌",
                    "collection_category": "평생학습",
                    "domain_category": "평생교육",
                    "collection_type": "static_html+detail_html",
                    "raw_fields": {
                        "parser": "dh_lifelong_table+detail",
                        "list_cells": cells,
                        "detail_pairs": detail_pairs,
                    },
                }
            )
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1,
        "recursion_depth": 0,
        "no_current_data": pages > 0 and not rows,
        "no_current_reason": "no_dh_lifelong_courses" if pages > 0 and not rows else "",
    }
    return dedupe_rows(rows), "dh_lifelong_table+detail", meta


def donggu_gwangju_normalize_date_range(value: str) -> str:
    text = clean_text(value)
    text = re.sub(r"(\d{4})\s*년\s*(\d{1,2})\s*월\s*(\d{1,2})\s*일", r"\1-\2-\3", text)
    return normalize_mixed_date_range(text)


def donggu_gwangju_list_url(url: str) -> str:
    parsed = urlparse(url)
    query = parse_qs(parsed.query)
    query["act"] = ["search_list"]
    query.pop("lec_no", None)
    query.pop("return_act", None)
    return parsed._replace(query=urlencode(query, doseq=True)).geturl()


def collect_donggu_gwangju_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    seen: set[str] = set()
    base_url = donggu_gwangju_list_url(target.url)
    parsed = urlparse(base_url)
    base_query = parse_qs(parsed.query)

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["nPage"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 6:
                continue
            link = tr.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            if raw_url in seen:
                continue
            seen.add(raw_url)
            title = clean_text(link.get_text(" ", strip=True) if link else cells[0])
            target_text = clean_text(cells[1]) or "전체"
            period = donggu_gwangju_normalize_date_range(cells[2])
            _, end_date = parse_date_range(period)
            if end_date and end_date < datetime.now().astimezone().date():
                continue
            detail_pairs: dict[str, str] = {}
            description = clean_text(tr.get_text(" ", strip=True))
            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_tables(detail_soup.select_one("#contents") or detail_soup)
                    category = clean_text(detail_pairs.get("교육구분"))
                    if category and title.startswith(category):
                        title = clean_text(title[len(category):])
                    period = donggu_gwangju_normalize_date_range(detail_pairs.get("교육기간") or period)
                    description = clean_text(detail_pairs.get("강좌소개")) or description
                except Exception as exc:
                    logger.debug("donggu gwangju detail fetch failed %s: %s", raw_url, exc)
            category = clean_text(detail_pairs.get("교육구분")) or ""
            if category and title.startswith(category):
                title = clean_text(title[len(category):])
            fee = clean_text(detail_pairs.get("수강료")) or "별도 안내"
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "branch_code": target.provider,
                    "category": category or "평생학습",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": normalize_status(cells[5], description),
                    "fee": fee,
                    "period": period,
                    "apply_period": donggu_gwangju_normalize_date_range(detail_pairs.get("접수일자", "")),
                    "schedule_raw": clean_text(detail_pairs.get("교육시간")) or period,
                    "target": clean_text(detail_pairs.get("대상구분") or target_text) or "전체",
                    "capacity": clean_text(detail_pairs.get("정원")),
                    "venue_name": clean_text(detail_pairs.get("교육장소") or cells[3]),
                    "room": clean_text(detail_pairs.get("교육장소") or cells[3]),
                    "phone": clean_text(detail_pairs.get("문의전화")),
                    "instructor": clean_instructor_name(detail_pairs.get("강사")),
                    "application_method_raw": clean_text(detail_pairs.get("접수방법") or cells[4]),
                    "description": description,
                    "program_type": "강좌",
                    "collection_category": "평생학습",
                    "domain_category": "평생교육",
                    "collection_type": "static_html+detail_html",
                    "raw_fields": {
                        "parser": "donggu_gwangju_lecture_table+detail",
                        "list_cells": cells,
                        "detail_pairs": detail_pairs,
                    },
                }
            )
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1,
        "recursion_depth": 0,
        "no_current_data": pages > 0 and not rows,
        "no_current_reason": "no_current_donggu_gwangju_lectures" if pages > 0 and not rows else "",
    }
    return dedupe_rows(rows), "donggu_gwangju_lecture_table+detail", meta


PYEONGTAEK_REGULAR_LIST_URL = "https://www.pyeongtaek.go.kr/learning/regular/program/list.do?mid=0201020000"
PYEONGTAEK_VENUES = {
    "북부": ("북부학습공간", "경기도 평택시 이충로 84-6, 평생학습센터 3층"),
    "남부": ("남부학습공간", "경기도 평택시 평택5로 220, 남부복지타운 2층"),
    "서부": ("서부학습공간", "경기도 평택시 안중읍 서동대로 1557, 서부복지타운 3층"),
}


def pyeongtaek_normalize_dotted_date(value: str) -> str:
    text = clean_text(value)
    text = re.sub(r"(\d{4})[.]\s*(\d{1,2})[.]\s*(\d{1,2})[.]?", lambda m: f"{m.group(1)}-{int(m.group(2)):02d}-{int(m.group(3)):02d}", text)
    return text


def pyeongtaek_global_period(soup: BeautifulSoup) -> str:
    text = pyeongtaek_normalize_dotted_date(clean_text((soup.select_one("#contents") or soup).get_text(" ", strip=True)))
    anchor = text.find("교육기간")
    if anchor < 0:
        return ""
    dates = re.findall(r"\d{4}-\d{2}-\d{2}", text[anchor : anchor + 160])
    if len(dates) >= 2:
        return f"{dates[0]} ~ {dates[1]}"
    return ""


def collect_pyeongtaek_regular_programs(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(PYEONGTAEK_REGULAR_LIST_URL)

    for page in range(1, max_pages + 1):
        query = parse_qs(parsed.query)
        query["page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        global_period = pyeongtaek_global_period(soup)
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cell_nodes = tr.find_all("td")
            cells = [clean_text(td.get_text(" ", strip=True)) for td in cell_nodes]
            if len(cells) < 6:
                continue
            title_lines = lines_from_soup(cell_nodes[1])
            if not title_lines:
                continue
            title = title_lines[0]
            if "테스트" in title or is_low_value_title(title):
                continue
            apply_period = ""
            if len(title_lines) > 1:
                apply_period = normalize_mixed_date_range(title_lines[1].strip("() "))
            onclick = clean_text((tr.find("a", onclick=True) or {}).get("onclick") if tr.find("a", onclick=True) else "")
            idx_match = re.search(r"goView\('([^']+)'\)", onclick)
            idx = clean_text(idx_match.group(1) if idx_match else cells[0])
            raw_url = parsed._replace(query=urlencode({**parse_qs(parsed.query), "idx": [idx]}, doseq=True)).geturl()
            place_lines = lines_from_soup(cell_nodes[0])
            place_label = place_lines[-1] if place_lines else ""
            place_key = next((key for key in PYEONGTAEK_VENUES if key in place_label or title.startswith(f"[{key}]")), "")
            venue_name, venue_address = PYEONGTAEK_VENUES.get(place_key, (place_label or target.branch, ""))
            status = normalize_status(cells[5], clean_text(tr.get_text(" ", strip=True)))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, venue_name),
                    "title": title,
                    "branch": target.branch,
                    "branch_code": target.provider,
                    "category": cells[2],
                    "raw_url": raw_url,
                    "application_url": raw_url if status in {"OPEN", "WAITING", "SCHEDULED"} else "",
                    "status": status,
                    "fee": cells[4] or "별도 안내",
                    "period": global_period or apply_period,
                    "apply_period": apply_period,
                    "schedule_raw": cells[3],
                    "target": "평택시민",
                    "venue_name": venue_name,
                    "venue_address": venue_address,
                    "address": venue_address,
                    "description": clean_text(tr.get_text(" ", strip=True)),
                    "program_type": "강좌",
                    "collection_category": "평생학습",
                    "domain_category": "평생교육",
                    "collection_type": "static_html",
                    "raw_fields": {
                        "parser": "pyeongtaek_regular_program_table",
                        "list_cells": cells,
                        "idx": idx,
                    },
                }
            )
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1,
        "recursion_depth": 0,
        "no_current_data": pages > 0 and not rows,
        "no_current_reason": "no_pyeongtaek_regular_programs" if pages > 0 and not rows else "",
    }
    return dedupe_rows(rows), "pyeongtaek_regular_program_table", meta


YD21_EDU_LIST_URL = "https://www.yd21.go.kr/kr/html/sub05/05090101.html?mode=L"


def collect_yd21_education_cards(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    soup = fetch_soup(s, YD21_EDU_LIST_URL, timeout=timeout)
    for card in soup.select(".list_inner"):
        title = clean_text((card.select_one("strong") or card).get_text(" ", strip=True))
        if not title or is_low_value_title(title):
            continue
        pairs: dict[str, str] = {}
        for item in card.select(".e_list li"):
            key = clean_text((item.select_one("em") or item).get_text(" ", strip=True))
            value = clean_text((item.select_one("span") or item).get_text(" ", strip=True))
            if key and value:
                pairs[key] = value
        period = normalize_mixed_date_range(pairs.get("교육기간", ""))
        _, end_date = parse_date_range(period)
        if end_date and end_date < datetime.now().astimezone().date():
            continue
        link = card.select_one(".e_btn a[href]") or card.find("a", href=True)
        raw_url = normalize_link(YD21_EDU_LIST_URL, link.get("href") if link else None) or YD21_EDU_LIST_URL
        venue_name = clean_text(pairs.get("교육장소"))
        status = clean_text((card.select_one(".cate span") or "").get_text(" ", strip=True) if card.select_one(".cate span") else "")
        method = clean_text(" ".join(span.get_text(" ", strip=True) for span in card.select(".tit span")))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, venue_name or target.branch),
                "title": title,
                "branch": target.branch,
                "branch_code": target.provider,
                "category": clean_text((card.select_one(".tab_cate") or "").get_text(" ", strip=True) if card.select_one(".tab_cate") else ""),
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": normalize_status(status, clean_text(card.get_text(" ", strip=True))),
                "fee": "별도 안내",
                "period": period,
                "apply_period": normalize_mixed_date_range(pairs.get("접수기간", "")),
                "schedule_raw": clean_text(pairs.get("교육시간")),
                "target": "전체",
                "venue_name": venue_name,
                "room": venue_name,
                "application_method_raw": method,
                "description": clean_text(card.get_text(" ", strip=True)),
                "program_type": "강좌",
                "collection_category": "평생학습",
                "domain_category": "평생교육",
                "collection_type": "static_html",
                "raw_fields": {
                    "parser": "yd21_education_cards",
                    "pairs": pairs,
                },
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
        "no_current_data": not rows,
        "no_current_reason": "no_current_yd21_education_cards" if not rows else "",
    }
    return dedupe_rows(rows), "yd21_education_cards", meta


OSAN_EDU_LIST_URL = "https://www.osanedu.go.kr/app/app0101/selectEdcList.do"
OSAN_EDU_REFERER = "https://www.osanedu.go.kr/app/app0101/selectEdcView.do"


def osan_labeled_value(text: str, label: str, stop_labels: tuple[str, ...]) -> str:
    stop_pattern = "|".join(re.escape(stop) for stop in stop_labels if stop != label)
    pattern = re.escape(label) + r"\s*\|?\s*(.*?)(?=\s*(?:" + stop_pattern + r")\s*\|?|$)"
    match = re.search(pattern, text, re.DOTALL)
    return clean_text(match.group(1)) if match else ""


def parse_osan_edu_item(target: CrawlTarget, page_url: str, item: BeautifulSoup) -> dict[str, Any] | None:
    title_node = item.select_one("h3")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    if not title or is_low_value_title(title):
        return None
    header_spans = item.select("div.flex.items-center.gap-2.mb-3 span")
    status = clean_text(header_spans[0].get_text(" ", strip=True)) if header_spans else ""
    branch = clean_text(header_spans[1].get_text(" ", strip=True)) if len(header_spans) > 1 else target.branch
    text = clean_text(item.get_text(" ", strip=True))
    labels = (
        "\uAD50\uC721\uAE30\uAC04",
        "\uAD50\uC721\uC77C\uC2DC",
        "\uAD50\uC721\uB300\uC0C1",
        "\uC218\uAC15\uB8CC",
        "\uC120\uCC29",
        "\uCD94\uCCA8",
    )
    period = osan_labeled_value(text, "\uAD50\uC721\uAE30\uAC04", labels)
    schedule = osan_labeled_value(text, "\uAD50\uC721\uC77C\uC2DC", labels)
    target_text = osan_labeled_value(text, "\uAD50\uC721\uB300\uC0C1", labels)
    fee = osan_labeled_value(text, "\uC218\uAC15\uB8CC", labels)
    fee_match = re.search(r"\d[\d,]*\s*\uC6D0|무료", fee)
    if fee_match:
        fee = clean_text(fee_match.group(0))
    capacity_node = item.select_one(".st-num")
    capacity = clean_text(capacity_node.get_text(" ", strip=True)) if capacity_node else ""
    capacity = re.sub(r"^(\uC120\uCC29|\uCD94\uCCA8)\s*", "", capacity).strip()
    edc_code = clean_text(item.get("data-ecd"))
    edc_type = clean_text(item.get("data-ty")) or "LFT"
    raw_url = urljoin(page_url, f"/app/app0101/selectEdcDtls.do?edcCode={quote(edc_code)}&edcTy={quote(edc_type)}") if edc_code else page_url
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, edc_code or raw_url, title, branch),
        "title": title,
        "branch": branch,
        "branch_code": clean_text(item.get("data-instt")),
        "category": "",
        "raw_url": raw_url,
        "application_url": raw_url,
        "status": status,
        "fee": fee,
        "period": period,
        "apply_period": "",
        "schedule_raw": schedule,
        "target": target_text,
        "capacity": capacity,
        "venue_name": branch,
        "description": text[:800],
        "raw_fields": {
            "parser": "osan_edu_ajax",
            "edc_code": edc_code,
            "edc_type": edc_type,
            "business_code": clean_text(item.get("data-bsns")),
        },
    }


def fetch_osan_edu_list(
    s: requests.Session,
    page_index: int,
    status_code: str,
    timeout: int,
) -> BeautifulSoup:
    payload: dict[str, Any] = {"pageIndex": str(page_index)}
    if status_code:
        payload["eduSttusList"] = status_code
    response = s.post(
        OSAN_EDU_LIST_URL,
        data=json.dumps({"reqData": payload}, ensure_ascii=False).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Accept": "text/html, */*; q=0.01",
            "Referer": OSAN_EDU_REFERER,
            "ajaxAt": "Y",
        },
        timeout=timeout,
    )
    response.raise_for_status()
    content = response.content
    if content.startswith(b"\x1f\x8b"):
        return BeautifulSoup(bounded_gzip_decompress(content), "lxml")
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    return BeautifulSoup(response.text, "lxml")


def collect_osan_edu_courses(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": OSAN_EDU_REFERER})
    fetch_soup(s, "https://www.osanedu.go.kr/app/app0101/selectEdcView.do", timeout=timeout)
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    status_page_counts: dict[str, int] = {}

    for status_code in ("02", "01"):
        status_pages = 0
        for page_index in range(1, max_pages + 1):
            soup = fetch_osan_edu_list(s, page_index=page_index, status_code=status_code, timeout=timeout)
            pages += 1
            status_pages += 1
            items = soup.select(".class_list .btn_dtls")
            pagination_detected = pagination_detected or bool(soup.select(".more_wrap, .pagination, input[name='totalRecordCount']"))
            if not items:
                break
            for item in items:
                row = parse_osan_edu_item(target, OSAN_EDU_REFERER, item)
                if row:
                    rows.append(row)
            total = clean_text((soup.select_one("input[name='totalRecordCount']") or {}).get("value", ""))
            if total.isdigit() and page_index * len(items) >= int(total):
                break
        status_page_counts[status_code] = status_pages

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "status_pages": status_page_counts,
    }
    return dedupe_rows(rows), "osan_edu_ajax", meta


def normalize_site_period(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    text = re.sub(
        r"(\d{4})[./](\d{1,2})[./](\d{1,2})",
        lambda match: f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}",
        text,
    )
    text = re.sub(r"\s*~\s*", " ~ ", text)
    return clean_text(text)


def normalize_site_fee(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    compact = text.replace(",", "").replace(" ", "")
    if compact in {"0", "0원"}:
        return "무료"
    won_match = re.fullmatch(r"(\d+)원", compact)
    if won_match:
        return f"{int(won_match.group(1)):,}원"
    if re.fullmatch(r"\d+", compact):
        return f"{int(compact):,}원"
    return text


def clean_site_room(value: Any) -> str:
    return clean_text(re.sub(r"\s*팝업\s*닫기\s*$", "", clean_text(value)))


def collect_yangyang_lifelong_class_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    row_limit = int(target.extra.get("per_target_limit") or 0)

    for page in range(1, max_pages + 1):
        current_url = url_with_query(target.url, {"page": page if page > 1 else None})
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        cards = soup.select(".req_list")
        pagination_detected = pagination_detected or bool(soup.select(".pg_page, .pg_current"))
        if not cards:
            break
        for card in cards:
            title_node = card.select_one(".title")
            status_node = title_node.find("a") if title_node is not None else None
            status = clean_text(status_node.get_text(" ", strip=True) if status_node else "")
            title_text = clean_text(title_node.get_text(" ", strip=True) if title_node else card.get_text(" ", strip=True))
            if status:
                title_text = clean_text(title_text.replace(status, "", 1))
            title = clean_text(re.sub(r"^\d+\.\s*", "", title_text))
            if not title or is_low_value_title(title):
                continue

            pairs: dict[str, str] = {}
            pending_key = ""
            for node in card.select(".th_st, .td_st"):
                text = clean_text(node.get_text(" ", strip=True))
                classes = set(node.get("class") or [])
                if "th_st" in classes:
                    pending_key = text.rstrip(":：").strip()
                elif "td_st" in classes and pending_key:
                    pairs[pending_key] = text
                    pending_key = ""

            collapse = card.select_one(".row.collapse[id]")
            anchor = clean_text(collapse.get("id") if collapse else "") or hashlib.sha1(title.encode("utf-8")).hexdigest()[:10]
            raw_url = f"{urldefrag(current_url)[0]}#{anchor}"
            capacity = clean_text(pairs.get("정원/신청인원"))
            capacity_current, capacity_total = parse_capacity_pair(capacity)
            application_url = current_url if status and not any(token in status for token in ("마감", "종료")) else ""
            room = clean_text(pairs.get("강의장소"))
            category = clean_text(pairs.get("강의구분") or pairs.get("기수"))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": category,
                    "raw_url": raw_url,
                    "application_url": application_url,
                    "status": status,
                    "fee": normalize_site_fee(pairs.get("수강료")),
                    "period": normalize_site_period(pairs.get("강의기간")),
                    "apply_period": normalize_site_period(pairs.get("접수기간")),
                    "schedule_raw": clean_text(pairs.get("강의시간")),
                    "target": clean_text(pairs.get("모집제한")),
                    "room": room,
                    "venue_name": room,
                    "capacity": capacity,
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "application_method_raw": clean_text(pairs.get("선발기준")),
                    "description": clean_text(card.get_text(" ", strip=True))[:1000],
                    "raw_fields": {"pairs": pairs, "parser": "yangyang_lifelong_class_list"},
                }
            )
            if row_limit > 0 and len(rows) >= row_limit:
                break
        if row_limit > 0 and len(rows) >= row_limit:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "no_current_data": pages > 0 and not rows,
        "no_current_reason": "no_yangyang_classes" if pages > 0 and not rows else "",
    }
    return dedupe_rows(rows), "yangyang_lifelong_class_list", meta


SLL_SIMIN_LIST_ENDPOINT = "https://sll.seoul.go.kr/lms/simin_course/courseRequest/doListSiminCourse.do"


def sll_simin_status_text(value: Any) -> str:
    code = clean_text(value)
    return {
        "BEFORE": "모집예정",
        "ING": "모집중",
        "FULL": "모집완료",
        "END": "접수마감",
        "CLOSE": "접수마감",
        "PAST": "종료",
        "WAIT": "모집예정",
    }.get(code, "" if code == "-" else code)


def sll_simin_time_range(item: dict[str, Any]) -> str:
    start_h = clean_text(item.get("course_str_time_h"))
    start_m = clean_text(item.get("course_str_time_m")) or "00"
    end_h = clean_text(item.get("course_end_time_h"))
    end_m = clean_text(item.get("course_end_time_m")) or "00"
    if start_h and end_h:
        return f"{start_h}:{start_m} ~ {end_h}:{end_m}"
    return ""


def sll_simin_apply_period(item: dict[str, Any]) -> str:
    start = normalize_site_period(item.get("course_request_str_dt"))
    end = normalize_site_period(item.get("course_request_end_dt"))
    start_time = ""
    if clean_text(item.get("course_request_str_hour")):
        start_time = f"{clean_text(item.get('course_request_str_hour'))}:{clean_text(item.get('course_request_str_min')) or '00'}"
    end_time = ""
    if clean_text(item.get("course_request_end_hour")):
        end_time = f"{clean_text(item.get('course_request_end_hour'))}:{clean_text(item.get('course_request_end_min')) or '00'}"
    if start and end:
        return clean_text(f"{start} {start_time} ~ {end} {end_time}")
    return start or end


def collect_sll_simin_courses(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    simin_yn = clean_text((query.get("simin_yn") or ["M,DC,MD,O,R,RG"])[0])
    mnid = clean_text((query.get("mnid") or ["202501604868"])[0])
    s = session()
    s.headers.update({"X-Requested-With": "XMLHttpRequest", "Referer": target.url})
    payload = {
        "simin_yn": simin_yn,
        "menu_se": "",
        "course_category_id": "",
        "course_gubun": "",
        "fee": "",
        "sc_status": "",
        "course_str_dt": "",
        "course_end_dt": "",
        "weekday": "",
        "keyword": "",
        "keyword_status": "",
        "course_nm": "",
        "sorting": "",
    }
    response = s.post(SLL_SIMIN_LIST_ENDPOINT, data=payload, timeout=timeout, verify=True)
    response.raise_for_status()
    data = response.json()
    items = data.get("simin_course_list") or []
    per_target_limit = int(target.extra.get("per_target_limit") or 0)
    row_limit = per_target_limit if per_target_limit > 0 else max(50, max_pages * 50)
    rows: list[dict[str, Any]] = []
    for item in items[:row_limit]:
        title = clean_text(item.get("course_nm"))
        if not title or is_low_value_title(title):
            continue
        course_gubun = clean_text(item.get("course_gubun"))
        detail_path = "/lms/simin_course/courseRequest/doDetailInfo2.do" if course_gubun == "1" else "/lms/simin_course/courseRequest/doDetailInfo.do"
        raw_url = "https://sll.seoul.go.kr" + detail_path + "?" + urlencode(
            {
                "main_se": "ssu",
                "course_id": clean_text(item.get("course_id")),
                "class_no": clean_text(item.get("class_no")),
                "course_gubun": course_gubun,
                "mnid": mnid,
                "simin_yn": clean_text(item.get("simin_yn")),
            }
        )
        period = normalize_site_period(f"{item.get('course_str_dt', '')} ~ {item.get('course_end_dt', '')}")
        schedule = clean_text(" ".join(part for part in [clean_text(item.get("weekday")), sll_simin_time_range(item)] if part))
        venue = clean_text(item.get("course_place"))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, venue or target.branch),
                "title": title,
                "branch": venue or target.branch,
                "category": clean_text(item.get("category_nm2") or item.get("category_nm")),
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": sll_simin_status_text(item.get("status")),
                "fee": normalize_site_fee(item.get("fee")),
                "period": period,
                "apply_period": sll_simin_apply_period(item),
                "schedule_raw": schedule,
                "target": "서울시민",
                "room": venue,
                "venue_name": venue,
                "capacity": clean_text(item.get("capacity")),
                "capacity_total": parse_capacity_number(item.get("capacity")),
                "instructor": clean_text(item.get("prof_nm")),
                "description": clean_text(item.get("tag_list") or title),
                "raw_fields": {"item": item, "parser": "sll_simin_course_ajax"},
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": len(items),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": len(items) > len(rows),
        "recursion_depth": 0,
        "no_current_data": not rows,
        "no_current_reason": "no_sll_simin_courses" if not rows else "",
    }
    return dedupe_rows(rows), "sll_simin_course_ajax", meta


HADONG_EDU_LIST_ENDPOINT = "https://www.hadong.go.kr/module/main/ajax/life/edu.do"
HADONG_EDU_DETAIL_URL = "https://www.hadong.go.kr/03826/03830/03831.web"


def hadong_status_from_item(item: dict[str, Any]) -> str:
    try:
        if int(item.get("equalRegStart") or 0) >= 0 and int(item.get("equalRegFinish") or 0) <= 0:
            return "접수중"
    except (TypeError, ValueError):
        pass
    return "접수완료"


def hadong_detail_values(s: requests.Session, detail_url: str, timeout: int) -> dict[str, str]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    text = clean_text(soup.get_text(" ", strip=True))
    labels = (
        "운영기관",
        "교육기간",
        "접수기간",
        "문의전화",
        "교육대상",
        "교육장소",
        "요일/시간",
        "수강료",
        "접수정원",
        "대기정원",
        "신청방법",
        "목록",
    )
    values: dict[str, str] = {}
    for label in labels[:-1]:
        values[label] = extract_korean_labeled_value(text, label, labels)
    return values


def collect_hadong_education_ajax(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"X-Requested-With": "XMLHttpRequest", "Referer": "https://www.hadong.go.kr/edu.web"})
    per_target_limit = int(target.extra.get("per_target_limit") or 0)
    row_limit = per_target_limit if per_target_limit > 0 else max(8, max_pages * 10)
    response = s.get(HADONG_EDU_LIST_ENDPOINT, params={"pageUnit": row_limit}, timeout=timeout)
    response.raise_for_status()
    items = response.json()
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    for item in items[:row_limit]:
        title = clean_text(item.get("title"))
        if not title or is_low_value_title(title):
            continue
        raw_url = url_with_query(
            HADONG_EDU_DETAIL_URL,
            {
                "amode": "view",
                "idx": clean_text(item.get("idx")),
                "facCode": clean_text(item.get("facCode")),
            },
        )
        status = hadong_status_from_item(item)
        branch = clean_text(item.get("management")) or target.branch
        detail: dict[str, str] = {}
        if detail_pages < detail_limit:
            try:
                detail = hadong_detail_values(s, raw_url, timeout)
                detail_pages += 1
            except Exception as exc:
                logger.debug("hadong education detail fetch failed %s: %s", raw_url, exc)
        room = clean_text(detail.get("교육장소"))
        online_yn = clean_text(item.get("onlineYn"))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": clean_text(detail.get("운영기관")) or branch,
                "category": "교육강좌",
                "raw_url": raw_url,
                "application_url": raw_url if online_yn == "Y" and status == "접수중" else "",
                "status": status,
                "fee": normalize_site_fee(detail.get("수강료")),
                "period": normalize_site_period(detail.get("교육기간") or f"{item.get('startDt', '')} ~ {item.get('endDt', '')}"),
                "apply_period": normalize_site_period(detail.get("접수기간") or f"{item.get('regStart', '')} ~ {item.get('regFinish', '')}"),
                "schedule_raw": clean_text(detail.get("요일/시간")),
                "target": clean_text(detail.get("교육대상")),
                "room": room,
                "venue_name": room,
                "capacity": clean_text(detail.get("접수정원")),
                "phone": clean_text(detail.get("문의전화")),
                "application_method_raw": "온라인신청 가능" if online_yn == "Y" else "온라인신청 불가",
                "description": clean_text(detail.get("신청방법") or title),
                "raw_fields": {"item": item, "detail": detail, "parser": "hadong_education_ajax"},
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": detail_pages,
        "discovered_links": len(items),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": len(items) > len(rows),
        "recursion_depth": 1,
        "no_current_data": not rows,
        "no_current_reason": "no_hadong_education_courses" if not rows else "",
    }
    return dedupe_rows(rows), "hadong_education_ajax+detail", meta


HSG_EDU_LIST_URL = "https://www.hsg.go.kr/reserve/selectEdcCourseLctreRcritListU.do?key=1668"


def hsg_detail_pairs(s: requests.Session, detail_url: str, timeout: int) -> dict[str, str]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    return pairs_from_tables(soup)


def collect_hsg_reservation_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    parsed = urlparse(target.url)
    base_url = target.url if parsed.path.startswith("/reserve/selectEdcCourseLctreRcritListU.do") else HSG_EDU_LIST_URL
    row_limit = int(target.extra.get("per_target_limit") or 0)

    for page in range(1, max_pages + 1):
        current_url = url_with_query(base_url, {"pageIndex": page if page > 1 else None})
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        page_title = clean_text(soup.find("title").get_text(" ", strip=True) if soup.find("title") else "")
        category = clean_text(page_title.replace("- 통합예약", "")) or "교육"
        for table in soup.select("table"):
            header_row = table.select_one("thead tr") or table.select_one("tr")
            headers = [clean_text(cell.get_text(" ", strip=True)) for cell in header_row.find_all(["th", "td"])] if header_row else []
            if not any("강좌명" in header for header in headers) or not any("접수상태" in header for header in headers):
                continue
            for tr in table.select("tbody tr"):
                cells = tr.find_all("td")
                if len(cells) < 8:
                    continue
                title_link = cells[1].find("a", href=True)
                title = clean_text(title_link.get_text(" ", strip=True) if title_link else cells[1].get_text(" ", strip=True))
                if not title or is_low_value_title(title):
                    continue
                raw_url = normalize_link(current_url, title_link.get("href") if title_link else None) or current_url
                date_lines = lines_from_node(cells[2])
                apply_period = normalize_site_period(date_lines[0] if date_lines else "")
                period = normalize_site_period(date_lines[1] if len(date_lines) > 1 else "")
                status = clean_text(cells[7].get_text(" ", strip=True))
                detail: dict[str, str] = {}
                if detail_pages < detail_limit and raw_url:
                    try:
                        detail = hsg_detail_pairs(s, raw_url, timeout)
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("hsg detail fetch failed %s: %s", raw_url, exc)
                room = clean_site_room(detail.get("교육장") or detail.get("교육장소"))
                capacity = clean_text(detail.get("접수현황") or cells[5].get_text(" ", strip=True))
                capacity_current, capacity_total = parse_capacity_pair(capacity)
                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, raw_url, title, room or target.branch),
                        "title": title,
                        "branch": room or target.branch,
                        "category": category if category != "전체" else "교육",
                        "raw_url": raw_url,
                        "application_url": raw_url if "접수중" in status or "대기자" in status else "",
                        "status": status,
                        "fee": normalize_site_fee(detail.get("수강료")),
                        "period": normalize_site_period(detail.get("교육기간") or period),
                        "apply_period": normalize_site_period(detail.get("접수기간") or apply_period),
                        "schedule_raw": clean_text(detail.get("교육시간") or cells[3].get_text(" ", strip=True)),
                        "target": clean_text(detail.get("교육대상")),
                        "room": room,
                        "venue_name": room,
                        "capacity": capacity,
                        "capacity_current": capacity_current,
                        "capacity_total": capacity_total,
                        "application_method_raw": clean_text(detail.get("신청방법") or cells[6].get_text(" ", strip=True)),
                        "description": clean_text(detail.get("강좌소개") or tr.get_text(" ", strip=True)),
                        "raw_fields": {"detail": detail, "parser": "hsg_reservation_education_table"},
                    }
                )
                page_rows += 1
                if row_limit > 0 and len(rows) >= row_limit:
                    break
            if row_limit > 0 and len(rows) >= row_limit:
                break
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='pageIndex=']"))
        if row_limit > 0 and len(rows) >= row_limit:
            break
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 1,
        "no_current_data": pages > 0 and not rows,
        "no_current_reason": "no_hsg_reservation_courses" if pages > 0 and not rows else "",
    }
    return dedupe_rows(rows), "hsg_reservation_education_table+detail", meta


def jjss_unique_reserv_links(soup: BeautifulSoup, base_url: str, required: tuple[str, ...]) -> list[str]:
    links: list[str] = []
    for link in soup.find_all("a", href=True):
        href = urljoin(base_url, clean_text(link.get("href")))
        if all(token in href for token in required):
            links.append(href)
    return list(dict.fromkeys(links))


def jjss_table_map(table: BeautifulSoup) -> list[dict[str, Any]]:
    headers = [clean_text(th.get_text(" ", strip=True)) for th in table.select("thead th")]
    if not headers:
        first_row = table.select_one("tr")
        headers = [clean_text(th.get_text(" ", strip=True)) for th in first_row.find_all("th")] if first_row else []
    if "\uAC15\uC2B5\uBA85" not in headers or "\uC811\uC218\uC0C1\uD0DC" not in headers:
        return []
    rows: list[dict[str, Any]] = []
    for tr in table.select("tbody tr"):
        cells = tr.find_all("td")
        if len(cells) < len(headers):
            continue
        values = {headers[index]: clean_text(cells[index].get_text(" ", strip=True)) for index in range(len(headers))}
        detail_link = tr.find("a", href=lambda href: href and "infoUid=" in href)
        values["_detail_url"] = clean_text(detail_link.get("href")) if detail_link else ""
        rows.append(values)
    return rows


def jjss_detail_fields(s: requests.Session, detail_url: str, timeout: int) -> dict[str, str]:
    if not detail_url:
        return {}
    soup = fetch_soup(s, detail_url, timeout=timeout)
    text = clean_text(soup.get_text(" ", strip=True))
    apply_period = ""
    match = re.search(r"\uC811\uC218\uAE30\uAC04\s*[:：]?\s*(\d{4}-\d{2}-\d{2}\s*[~\-]\s*\d{4}-\d{2}-\d{2})", text)
    if match:
        apply_period = clean_text(match.group(1).replace("-", "-", 2))
    fee = ""
    fee_match = re.search(r"(?:\uC694\uAE08\s*[:：]\s*)?(\d[\d,]*\s*\uC6D0)", text)
    if fee_match:
        fee = clean_text(fee_match.group(1))
    return {"apply_period": apply_period, "fee": fee, "description": text[:1000]}


def parse_jjss_course_rows(
    target: CrawlTarget,
    s: requests.Session,
    page_url: str,
    soup: BeautifulSoup,
    timeout: int,
    detail_remaining: int,
) -> tuple[list[dict[str, Any]], int]:
    rows: list[dict[str, Any]] = []
    for table in soup.select("table"):
        for values in jjss_table_map(table):
            title = values.get("\uAC15\uC2B5\uBA85", "")
            if not title or is_low_value_title(title):
                continue
            raw_url = urljoin(page_url, values.get("_detail_url") or page_url)
            detail: dict[str, str] = {}
            if detail_remaining > 0 and values.get("_detail_url"):
                try:
                    detail = jjss_detail_fields(s, raw_url, timeout=timeout)
                    detail_remaining -= 1
                except Exception as exc:
                    logger.debug("jjss detail fetch failed %s: %s", raw_url, exc)
            day = values.get("\uAC15\uC2B5\uC694\uC77C", "")
            time_band = values.get("\uC2DC\uAC04\uB300", "")
            time_text = values.get("\uAC15\uC2B5\uC2DC\uAC04", "")
            schedule = clean_text(" ".join(part for part in [day, time_band, time_text] if part))
            fee = detail.get("fee", "")
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, values.get("\uC2DC\uC124\uBA85", target.branch)),
                "title": title,
                "branch": values.get("\uC2DC\uC124\uBA85", target.branch),
                "category": values.get("\uC885\uBAA9", ""),
                "raw_url": raw_url,
                "application_url": raw_url if values.get("\uC811\uC218\uC0C1\uD0DC") == "\uC811\uC218\uC911" else "",
                "status": values.get("\uC811\uC218\uC0C1\uD0DC", ""),
                "fee": fee,
                "period": "",
                "apply_period": detail.get("apply_period", ""),
                "schedule_raw": schedule,
                "target": values.get("\uB2E8\uACC4", ""),
                "capacity": values.get("\uC815\uC6D0", ""),
                "instructor": values.get("\uAC15\uC0AC", ""),
                "venue_name": values.get("\uC2DC\uC124\uBA85", ""),
                "description": detail.get("description") or clean_text(" ".join(value for key, value in values.items() if not key.startswith("_")))[:800],
                "raw_fields": {"parser": "jjss_reserv_table", "cells": values},
            }
            rows.append(row)
    return rows, detail_remaining


def collect_jjss_reserv_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    start_soup = fetch_soup(s, target.url, timeout=timeout)
    facility_links = jjss_unique_reserv_links(start_soup, target.url, ("contentUid=0000000070e6710e0170e6d12df40255", "topUid=", "typeUid="))
    rows: list[dict[str, Any]] = []
    pages = 1
    detail_remaining = detail_limit
    subject_links: list[str] = []
    list_pages = 0
    no_current_pages = 0

    for facility_url in facility_links[:max(1, max_pages)]:
        facility_soup = fetch_soup(s, facility_url, timeout=timeout)
        pages += 1
        subject_links.extend(
            jjss_unique_reserv_links(
                facility_soup,
                facility_url,
                ("contentUid=0000000070ce17640170ce28244d003d", "topUid=", "typeUid=", "tagUid="),
            )
        )

    for list_url in list(dict.fromkeys(subject_links))[:max(1, max_pages * 3)]:
        soup = fetch_soup(s, list_url, timeout=timeout)
        pages += 1
        list_pages += 1
        page_text = clean_text(soup.get_text(" ", strip=True))
        if "현재 운영중인 강습이 없습니다" in page_text or re.search(r"총\s*게시물\s*0\s*개", page_text):
            no_current_pages += 1
        page_rows, detail_remaining = parse_jjss_course_rows(
            target,
            s,
            list_url,
            soup,
            timeout=timeout,
            detail_remaining=detail_remaining,
        )
        rows.extend(page_rows)

    meta = {
        "pages": pages,
        "detail_pages": detail_limit - detail_remaining,
        "discovered_links": len(facility_links) + len(subject_links),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 2,
        "list_pages": list_pages,
        "no_current_data": not rows and list_pages > 0 and no_current_pages == list_pages,
        "no_current_reason": "no_current_jjss_lessons" if not rows and list_pages > 0 and no_current_pages == list_pages else "",
    }
    return dedupe_rows(rows), "jjss_reserv_table", meta


RAILROAD_MUSEUM_BRANCH = "\uCCA0\uB3C4\uBC15\uBB3C\uAD00"


def railroadmuseum_period(value: Any) -> str:
    text = clean_text(value)
    match = re.search(r"(20\d{2})[.\-](\d{1,2})[.\-](\d{1,2})\s*[~\-]\s*(20\d{2})[.\-](\d{1,2})[.\-](\d{1,2})", text)
    if not match:
        return text
    return (
        f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
        f" ~ {match.group(4)}-{int(match.group(5)):02d}-{int(match.group(6)):02d}"
    )


def railroadmuseum_label_value(lines: list[str], label: str) -> str:
    prefix = f"{label} :"
    compact_prefix = f"{label}:"
    for line in lines:
        text = clean_text(line)
        if text.startswith(prefix):
            return clean_text(text[len(prefix) :])
        if text.startswith(compact_prefix):
            return clean_text(text[len(compact_prefix) :])
    return ""


def parse_railroadmuseum_edu_cards(target: CrawlTarget, s: requests.Session, timeout: int) -> tuple[list[dict[str, Any]], int]:
    url = "https://www.railroadmuseum.co.kr/edu_res"
    soup = fetch_soup(s, url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    for card in soup.select(".event_card"):
        title = clean_text(card.select_one("h3").get_text(" ", strip=True) if card.select_one("h3") else "")
        if not title or is_low_value_title(title):
            continue
        link = card.find("a", href=True)
        raw_url = urljoin(url, link.get("href")) if link else url
        status = clean_text(card.select_one(".status_badge").get_text(" ", strip=True) if card.select_one(".status_badge") else "")
        info = [clean_text(node.get_text(" ", strip=True)) for node in card.select(".card_info p")]
        period = railroadmuseum_period(info[0]) if len(info) > 0 else ""
        venue = info[1] if len(info) > 1 else ""
        target_text = info[2] if len(info) > 2 else ""
        description = clean_text(card.get_text(" ", strip=True))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, RAILROAD_MUSEUM_BRANCH),
                "title": title,
                "branch": RAILROAD_MUSEUM_BRANCH,
                "category": "\uAD50\uC721\uD504\uB85C\uADF8\uB7A8",
                "raw_url": raw_url,
                "application_url": "" if status == "\uC885\uB8CC" else raw_url,
                "status": status,
                "fee": "",
                "period": period,
                "apply_period": "",
                "schedule_raw": period,
                "target": target_text,
                "venue_name": venue,
                "description": description,
                "raw_fields": {"parser": "railroadmuseum_edu_card", "source_url": url, "info": info},
            }
        )
    return rows, 1


def parse_railroadmuseum_experience(target: CrawlTarget, s: requests.Session, timeout: int) -> tuple[list[dict[str, Any]], int]:
    url = "https://www.railroadmuseum.co.kr/page/experience"
    soup = fetch_soup(s, url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    for heading in soup.select(".sub_content h3"):
        title = clean_text(heading.get_text(" ", strip=True))
        if not title or is_low_value_title(title):
            continue
        siblings: list[BeautifulSoup] = []
        cursor = heading.find_next_sibling()
        while cursor and cursor.name != "h3":
            siblings.append(cursor)
            cursor = cursor.find_next_sibling()
        table_text = clean_text(" ".join(node.get_text(" ", strip=True) for node in siblings if getattr(node, "name", "") == "table"))
        lines = [
            clean_text(li.get_text(" ", strip=True))
            for node in siblings
            for li in node.find_all("li")
            if clean_text(li.get_text(" ", strip=True))
        ]
        venue = railroadmuseum_label_value(lines, "\uC7A5\uC18C") or railroadmuseum_label_value(lines, "\uC9D1\uACB0\uC7A5\uC18C")
        method = railroadmuseum_label_value(lines, "\uC811\uC218\uBC29\uBC95")
        duration = railroadmuseum_label_value(lines, "\uC18C\uC694\uC2DC\uAC04")
        fee = railroadmuseum_label_value(lines, "\uC774\uC6A9\uC694\uAE08")
        description = clean_text(" ".join([table_text, *lines]))
        status = method or "\uD604\uC7A5\uC811\uC218"
        raw_url = stable_list_item_url(
            url,
            target.provider,
            title,
            RAILROAD_MUSEUM_BRANCH,
            "\uC0C1\uC2DC \uC6B4\uC601",
            table_text,
            venue,
        )
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, RAILROAD_MUSEUM_BRANCH),
                "title": title,
                "branch": RAILROAD_MUSEUM_BRANCH,
                "category": "\uCCB4\uD5D8/\uC804\uC2DC\uD574\uC124",
                "raw_url": raw_url,
                "application_url": url,
                "status": status,
                "fee": fee,
                "period": "\uC0C1\uC2DC \uC6B4\uC601",
                "apply_period": "",
                "schedule_raw": clean_text(f"\uC0C1\uC2DC \uC6B4\uC601 {table_text}"),
                "target": "\uAD00\uB78C\uAC1D",
                "venue_name": venue,
                "description": clean_text(" / ".join(part for part in [description, duration] if part)),
                "raw_fields": {"parser": "railroadmuseum_experience", "source_url": url, "method": method, "lines": lines},
            }
        )
    return rows, 1


def collect_railroadmuseum_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    edu_rows, edu_pages = parse_railroadmuseum_edu_cards(target, s, timeout=timeout)
    rows.extend(edu_rows)
    pages += edu_pages
    if max_pages > 1:
        experience_rows, experience_pages = parse_railroadmuseum_experience(target, s, timeout=timeout)
        rows.extend(experience_rows)
        pages += experience_pages
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 1,
    }
    return dedupe_rows(rows), "railroadmuseum_programs", meta


NFM_BRANCH = "\uAD6D\uB9BD\uBBFC\uC18D\uBC15\uBB3C\uAD00"
NFM_EDU_LIST_URL = "https://www.nfm.go.kr/user/eduPlan/home/85/dataList.do?searchStatus=1&searchEduPlanCate="


def nfm_label_pairs(lines: list[str]) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for line in lines:
        if ":" not in line:
            continue
        key, value = line.split(":", 1)
        pairs[clean_text(key)] = clean_text(value)
    return pairs


def collect_national_folk_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_exhausted = False
    for page in range(1, max(1, max_pages) + 1):
        list_url = f"{NFM_EDU_LIST_URL}&page={page}"
        soup = fetch_soup(s, list_url, timeout=timeout)
        pages += 1
        items = soup.select("li.mixed_item")
        if not items:
            pagination_exhausted = True
            break
        for item in items:
            title = clean_text(item.select_one(".item_title").get_text(" ", strip=True) if item.select_one(".item_title") else "")
            if not title or is_low_value_title(title):
                continue
            link = item.find("a", attrs={"onclick": True})
            onclick = clean_text(link.get("onclick") if link else "")
            match = re.search(r"fn_viewEduPlan\('([^']+)'\)", onclick)
            edu_plan_idx = match.group(1) if match else ""
            detail_url = (
                f"https://www.nfm.go.kr/user/eduPlan/home/85/dataView.do?eduPlanIdx={edu_plan_idx}"
                if edu_plan_idx
                else list_url
            )
            status = clean_text(item.select_one(".item_info").get_text(" ", strip=True) if item.select_one(".item_info") else "")
            lines = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".item_txt") if clean_text(node.get_text(" ", strip=True))]
            pairs = nfm_label_pairs(lines)
            badges = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".info_box") if clean_text(node.get_text(" ", strip=True))]
            period = railroadmuseum_period(pairs.get("\uAD50\uC721\uAE30\uAC04", ""))
            apply_period = railroadmuseum_period(pairs.get("\uC811\uC218\uAE30\uAC04", ""))
            target_text = pairs.get("\uC811\uC218\uB300\uC0C1", "")
            venue = pairs.get("\uAD50\uC721\uC7A5\uC18C", "")
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, detail_url, title, NFM_BRANCH),
                    "title": title,
                    "branch": NFM_BRANCH,
                    "category": badges[0] if badges else "\uAD50\uC721",
                    "raw_url": detail_url,
                    "application_url": detail_url if "\uC811\uC218\uC911" in status else "",
                    "status": status,
                    "fee": "별도 안내",
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": period,
                    "target": target_text,
                    "venue_name": venue,
                    "description": clean_text(" ".join([status, title, *lines, *badges])),
                    "raw_fields": {"parser": "nfm_edu_plan_list", "source_url": list_url, "badges": badges, "pairs": pairs},
                }
            )
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "source_cap_reached": not pagination_exhausted,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "nfm_edu_plan_list", meta


AVIATION_BRANCH = "\uAD6D\uB9BD\uD56D\uACF5\uBC15\uBB3C\uAD00"
AVIATION_GROUP_EDU_URL = "https://www.aviation.or.kr/reservation-edu.do?menuno=336"
AVIATION_BOOKING_URL = "https://aviation.moonhwain.net:451/rsvc/rsv_pm.html?lang=kr&b_id=aviation&stk_idx=2"


def aviation_section_nodes(soup: BeautifulSoup, label: str) -> list[Any]:
    heading = None
    for candidate in soup.select(".eduRev h4"):
        if clean_text(candidate.get_text(" ", strip=True)) == label:
            heading = candidate
            break
    if not heading:
        return []
    nodes: list[Any] = []
    cursor = heading.find_next_sibling()
    while cursor and getattr(cursor, "name", "") != "h4":
        nodes.append(cursor)
        cursor = cursor.find_next_sibling()
    return nodes


def aviation_section_text(soup: BeautifulSoup, label: str) -> str:
    return clean_text(" ".join(node.get_text(" ", strip=True) for node in aviation_section_nodes(soup, label)))


def aviation_month_period(month_value: int) -> str:
    year = datetime.now().year
    last_day = calendar.monthrange(year, month_value)[1]
    return f"{year}-{month_value:02d}-01 ~ {year}-{month_value:02d}-{last_day:02d}"


def aviation_month_status(month_value: int) -> str:
    current_month = datetime.now().month
    if month_value < current_month:
        return "\uB9C8\uAC10"
    if month_value == current_month:
        return "\uC811\uC218\uC911"
    return "\uC811\uC218\uC608\uC815"


def aviation_booking_dates(value: Any) -> tuple[list[str], dict[str, int]]:
    availability: dict[str, int] = {}
    for raw_date, raw_count in re.findall(r"(\d{8}):(\d+)", clean_text(value)):
        date_value = f"{raw_date[:4]}-{raw_date[4:6]}-{raw_date[6:]}"
        availability[date_value] = int(raw_count)
    return [date_value for date_value, count in availability.items() if count > 0], availability


def aviation_booking_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for row in soup.select(".table7 tr"):
        cells = row.find_all(["th", "td"])
        if len(cells) < 2:
            continue
        key = clean_text(cells[0].get_text(" ", strip=True))
        value = clean_text(cells[1].get_text(" ", strip=True))
        if key and value:
            pairs[key] = value
    return pairs


def collect_aviation_booking_products(
    s: requests.Session,
    target: CrawlTarget,
    timeout: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], int, int]:
    landing = fetch_soup(s, AVIATION_BOOKING_URL, timeout=timeout)
    product_links: list[tuple[str, str]] = []
    for link in landing.select(".selGoods_wrap .ft_site a[href*='p_idx=']"):
        url = normalize_link(AVIATION_BOOKING_URL, link.get("href"))
        title = clean_text(link.get_text(" ", strip=True))
        if url and title and (url, title) not in product_links:
            product_links.append((url, title))

    rows: list[dict[str, Any]] = []
    detail_pages = 0
    for product_url, title_hint in product_links[: max(0, detail_limit)]:
        product_soup = fetch_soup(s, product_url, timeout=timeout)
        detail_pages += 1
        pairs = aviation_booking_pairs(product_soup)
        title = clean_text(pairs.get("프로그램명") or title_hint)
        if not title:
            continue
        act_date = product_soup.select_one("#actDate")
        available_dates, availability = aviation_booking_dates(act_date.get("value") if act_date else "")
        parsed_url = urlparse(product_url)
        query = parse_qs(parsed_url.query)
        product_id = clean_text((query.get("p_idx") or [""])[0])
        booking_group = clean_text((query.get("b_id") or [""])[0])
        period = f"{available_dates[0]} ~ {available_dates[-1]}" if available_dates else ""
        schedule = " / ".join(
            f"{date_value} (\uC794\uC5EC {availability[date_value]})" for date_value in available_dates
        )
        is_online = bool(available_dates)
        description = clean_text(
            " | ".join(f"{key}: {value}" for key, value in pairs.items() if key and value)
        )
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, product_url, title, AVIATION_BRANCH),
                "title": title,
                "branch": AVIATION_BRANCH,
                "category": "\uAD50\uC721\uC608\uC57D" if booking_group == "aviationedu" else "\uCCB4\uD5D8\uC608\uC57D",
                "program_type": "\uAD50\uC721" if booking_group == "aviationedu" else "\uCCB4\uD5D8",
                "raw_url": product_url,
                "application_url": product_url if is_online else "",
                "status": "OPEN" if is_online else "\uD604\uC7A5\uC608\uC57D/\uC608\uC815\uC5C6\uC74C",
                "fee": "",
                "period": period,
                "apply_period": period,
                "schedule_raw": schedule or clean_text(pairs.get("\uC774\uC6A9\uC2DC\uAC04")),
                "schedule_dates": available_dates,
                "target": clean_text(pairs.get("\uB300\uC0C1")),
                "phone": clean_text(pairs.get("\uBB38\uC758")),
                "venue_name": AVIATION_BRANCH,
                "description": description or title,
                "reservation_available": is_online,
                "application_type": "ONLINE_RESERVATION" if is_online else "OFFLINE_APPLY",
                "application_method_raw": clean_text(pairs.get("\uC2E0\uCCAD\uBC29\uBC95")),
                "collection_type": "calendar_html+detail_html",
                "source_group": "museum_science",
                "raw_fields": {
                    "parser": "aviation_booking_calendar",
                    "source_url": AVIATION_BOOKING_URL,
                    "product_id": product_id,
                    "booking_group": booking_group,
                    "calendar_availability": availability,
                    "product_pairs": pairs,
                },
            }
        )
    return rows, 1, detail_pages


def collect_national_aviation_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 50,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, AVIATION_GROUP_EDU_URL, timeout=timeout)
    target_text = aviation_section_text(soup, "\uAD50\uC721 \uB300\uC0C1")
    program_text = aviation_section_text(soup, "\uAD50\uC721 \uD504\uB85C\uADF8\uB7A8")
    period_text = aviation_section_text(soup, "\uAD50\uC721 \uAE30\uAC04")
    application_nodes = aviation_section_nodes(soup, "\uC2E0\uCCAD \uBC29\uBC95")
    rows: list[dict[str, Any]] = []
    for node in application_nodes:
        for link in node.find_all("a", href=True):
            href = clean_text(link.get("href"))
            if not href:
                continue
            li = link.find_parent("li")
            title_text = clean_text(li.get_text(" ", strip=True) if li else link.get_text(" ", strip=True))
            title_text = clean_text(title_text.replace("\uBC14\uB85C \uAC00\uAE30", ""))
            month_match = re.search(r"\[(\d{1,2})\uC6D4\]", title_text)
            month_value = int(month_match.group(1)) if month_match else 0
            period = aviation_month_period(month_value) if month_value else period_text
            status = aviation_month_status(month_value) if month_value else "\uC811\uC218\uC911"
            is_childcare = "\uC5B4\uB9B0\uC774\uC9D1" in title_text
            row_target = (
                "24\uAC1C\uC6D4~48\uAC1C\uC6D4 \uC5B4\uB9B0\uC774\uC9D1 \uB2E8\uCCB4"
                if is_childcare
                else "\uCD08\u00B7\uC911\u00B7\uACE0\uB4F1\uD559\uAD50 \uD559\uAE09 \uB2E8\uCCB4 \uBC0F \uAD6D\uACF5\uB9BD \uB3CC\uBD04\u00B7\uCCAD\uC18C\uB144\uC13C\uD130 \uB2E8\uCCB4"
            )
            title = clean_text(f"{AVIATION_BRANCH} {title_text}")
            raw_url = stable_list_item_url(
                AVIATION_GROUP_EDU_URL,
                target.provider,
                title,
                AVIATION_BRANCH,
                period,
                row_target,
            )
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, href, title, AVIATION_BRANCH),
                    "title": title,
                    "branch": AVIATION_BRANCH,
                    "category": "\uB2E8\uCCB4\uAD50\uC721",
                    "raw_url": raw_url,
                    "application_url": href if status != "\uB9C8\uAC10" else "",
                    "status": status,
                    "fee": "",
                    "period": period,
                    "apply_period": period,
                    "schedule_raw": period,
                    "target": row_target,
                    "venue_name": AVIATION_BRANCH,
                    "description": clean_text(" ".join([target_text, program_text, period_text, title_text])),
                    "raw_fields": {"parser": "aviation_group_edu", "source_url": AVIATION_GROUP_EDU_URL, "title_text": title_text},
                }
            )
    booking_rows, booking_pages, booking_detail_pages = collect_aviation_booking_products(
        s,
        target,
        timeout=timeout,
        detail_limit=detail_limit,
    )
    rows.extend(booking_rows)
    meta = {
        "pages": 1 + booking_pages,
        "detail_pages": booking_detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "aviation_group_edu+booking_calendar", meta


NAMUK_BRANCH = "\uAD6D\uB9BD\uB18D\uC5C5\uBC15\uBB3C\uAD00"
NAMUK_EDU_URL = "https://www.namuk.or.kr/kr/204/subview.do"
NAMUK_BOOKING_URL = "https://namuk.moonhwain.net:451/rsvc/rsv_pm.html"


def namuk_info_pairs(item: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select(".info ul li"):
        label = clean_text(li.select_one(".info-title").get_text(" ", strip=True) if li.select_one(".info-title") else "")
        value = clean_text(li.select_one("p").get_text(" ", strip=True) if li.select_one("p") else "")
        if label and value:
            pairs[label] = value
    return pairs


def collect_national_agricultural_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    first_soup = fetch_soup(s, NAMUK_EDU_URL, timeout=timeout)
    total_pages = parse_capacity_number(
        clean_text(
            first_soup.select_one("._paging ._totPage").get_text(" ", strip=True)
            if first_soup.select_one("._paging ._totPage")
            else ""
        )
    ) or 1
    page_form = first_soup.select_one("form[name='pageForm']")
    if page_form is None:
        page_form = first_soup.select_one("form[action='/reservAll/kr/artclList.do']")
    form_action = normalize_link(
        NAMUK_EDU_URL,
        page_form.get("action") if page_form else "/reservAll/kr/artclList.do",
    )
    form_payload = {
        clean_text(node.get("name")): clean_text(node.get("value"))
        for node in (page_form.select("input[name]") if page_form else [])
    }
    rows: list[dict[str, Any]] = []
    pages = 0
    for page in range(1, min(total_pages, max_pages) + 1):
        soup = first_soup
        if page > 1:
            soup = post_soup(
                s,
                form_action,
                {**form_payload, "page": str(page)},
                timeout,
            )
        reported_page = parse_capacity_number(
            clean_text(
                soup.select_one("._paging ._curPage").get_text(" ", strip=True)
                if soup.select_one("._paging ._curPage")
                else ""
            )
        )
        if reported_page is not None and reported_page != page:
            raise ValueError(
                "National Agricultural Museum pagination response repeated "
                f"page {reported_page} while requesting page {page}"
            )
        pages += 1
        for item in soup.select(".event-wrap .list-webzine > li"):
            title = clean_text(item.select_one(".title strong").get_text(" ", strip=True) if item.select_one(".title strong") else "")
            if not title or is_low_value_title(title):
                continue
            badges = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".type-text-box") if clean_text(node.get_text(" ", strip=True))]
            status = badges[0] if badges else ""
            fee = badges[1] if len(badges) > 1 else ""
            category = badges[2] if len(badges) > 2 else "\uAD50\uC721"
            pairs = namuk_info_pairs(item)
            link = item.find("a", attrs={"onclick": True})
            onclick = clean_text(link.get("onclick") if link else "")
            match = re.search(r"reserv_View\('([^']+)','([^']+)','([^']+)'\)", onclick)
            reservation_id = match.group(2) if match else stable_course_id(target.provider, NAMUK_EDU_URL, title, NAMUK_BRANCH)
            raw_url = f"{NAMUK_BOOKING_URL}?b_id=namuk&p_idx={quote(reservation_id)}"
            period = railroadmuseum_period(pairs.get("\uAE30\uAC04", ""))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, NAMUK_BRANCH),
                    "title": title,
                    "branch": NAMUK_BRANCH,
                    "category": category,
                    "raw_url": raw_url,
                    "application_url": raw_url if "\uC811\uC218\uC911" in status else "",
                    "status": status,
                    "fee": fee,
                    "period": period,
                    "apply_period": "",
                    "schedule_raw": period,
                    "target": pairs.get("\uB300\uC0C1", ""),
                    "venue_name": pairs.get("\uC7A5\uC18C", NAMUK_BRANCH),
                    "description": clean_text(" ".join([*badges, title, *pairs.values()])),
                    "raw_fields": {
                        "parser": "namuk_reservation_list",
                        "source_url": NAMUK_EDU_URL,
                        "source_page": page,
                        "onclick": onclick,
                        "pairs": pairs,
                    },
                }
            )
    pagination_complete = pages == total_pages
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": total_pages > 1,
        "pagination_complete": pagination_complete,
        "source_cap_reached": not pagination_complete,
        "total_pages": total_pages,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "namuk_reservation_list", meta


