def hscity_library_list_url(slug: str) -> str:
    menu_id = HSCITY_LIBRARY_SITE_MENU_IDS.get(clean_text(slug).lower(), "")
    if not menu_id:
        return ""
    return (
        f"https://{HSCITY_LIBRARY_DIRECTORY_HOST}/{slug}/menu/{menu_id}"
        "/program/30021/lectureList.do"
    )


def hscity_library_directory_slugs(soup: BeautifulSoup) -> set[str]:
    slugs: set[str] = set()
    for link in soup.select("a[href]"):
        parsed = urlparse(urljoin(HSCITY_LIBRARY_DIRECTORY_URL, clean_text(link.get("href"))))
        if (
            parsed.scheme.lower() != "https"
            or parsed.netloc.lower() != HSCITY_LIBRARY_DIRECTORY_HOST
            or parsed.query
            or parsed.fragment
        ):
            continue
        match = re.fullmatch(r"/([a-z0-9]+)/index\.(?:do|jsp)", parsed.path, re.IGNORECASE)
        slug = match.group(1).lower() if match else ""
        if slug and slug != "intro":
            slugs.add(slug)
    return slugs


def hscity_library_detail_identity(list_url: str, href: Any) -> tuple[str, str]:
    parsed = urlparse(urljoin(list_url, clean_text(href)))
    query = parse_qs(parsed.query)
    service_id = clean_text((query.get("lectureIdx") or [""])[0])
    if (
        parsed.scheme.lower() != "https"
        or parsed.netloc.lower() != HSCITY_EDUCATION_HOST
        or parsed.path != "/1002/3001/lectureDetail.do"
        or parsed.fragment
        or not re.fullmatch(r"\d{1,20}", service_id)
    ):
        return "", ""
    return f"lecture:{service_id}", service_id


def hscity_library_page_memberships(
    slug: str,
    list_url: str,
    soup: BeautifulSoup,
) -> tuple[dict[str, dict[str, str]], list[str]]:
    memberships: dict[str, dict[str, str]] = {}
    errors: list[str] = []
    list_roots = soup.select("ul.article-list.lecture")
    if len(list_roots) != 1:
        return {}, [f"{slug}: library lecture list root missing or duplicated"]
    linked_item_count = 0
    for item in soup.select("ul.article-list.lecture > li"):
        link = item.select_one("a[href*='lectureDetail.do']")
        if link is None:
            continue
        linked_item_count += 1
        identity, service_id = hscity_library_detail_identity(list_url, link.get("href"))
        if not identity:
            errors.append(f"{slug}: invalid library lecture detail link")
            continue
        status_node = item.select_one(".status")
        status_label = clean_text(status_node.get_text(" ", strip=True) if status_node else "")
        compact_status = re.sub(r"\s+", "", status_label)
        status_filter = HSCITY_LIBRARY_ACTIVE_STATUS_FILTERS.get(compact_status, "")
        if not status_filter:
            if compact_status and compact_status not in HSCITY_LIBRARY_TERMINAL_STATUSES:
                errors.append(f"{slug}: unknown library lecture status {compact_status[:40]}")
            continue
        if identity in memberships:
            errors.append(f"{slug}: duplicated library lecture identity {identity}")
            continue
        branch_node = item.select_one(".themeFC")
        branch = clean_text(branch_node.get_text(" ", strip=True) if branch_node else "")
        title = re.sub(
            r"^\d+\.\s*",
            "",
            clean_text(link.get_text(" ", strip=True)),
        )
        memberships[identity] = {
            "identity": identity,
            "service_id": service_id,
            "slug": slug,
            "branch": branch,
            "title": title,
            "status_filter": status_filter,
            "home_url": f"https://{HSCITY_LIBRARY_DIRECTORY_HOST}/{slug}/index.do",
            "list_url": hscity_library_list_url(slug),
        }

    if linked_item_count >= HSCITY_EDUCATION_PAGE_SIZE:
        errors.append(
            f"{slug}: library lecture list reached the "
            f"{HSCITY_EDUCATION_PAGE_SIZE}-row page size"
        )
    for link in soup.select("a[href*='currentPageNo=']"):
        parsed = urlparse(urljoin(list_url, clean_text(link.get("href"))))
        page_value = clean_text((parse_qs(parsed.query).get("currentPageNo") or [""])[0])
        if page_value.isdigit() and int(page_value) > 1:
            errors.append(f"{slug}: library lecture pagination remained after page-size expansion")
            break
    return memberships, list(dict.fromkeys(errors))


def hscity_library_membership_scan(
    crawl_session: requests.Session,
    *,
    timeout: int,
    page_budget: int,
) -> dict[str, Any]:
    pages = 0
    errors: list[str] = []
    memberships: dict[str, dict[str, str]] = {}
    source_counts: dict[str, int] = {}
    directory_slugs: set[str] = set()

    if page_budget < 1:
        errors.append("HSCITY library directory page budget is exhausted")
        return {
            "pages": pages,
            "memberships": memberships,
            "source_counts": source_counts,
            "directory_slugs": [],
            "errors": errors,
        }
    try:
        directory_soup = fetch_soup(
            crawl_session,
            HSCITY_LIBRARY_DIRECTORY_URL,
            timeout=timeout,
        )
        pages += 1
        directory_slugs = hscity_library_directory_slugs(directory_soup)
    except Exception as exc:
        logger.warning(
            "HSCITY library directory fetch failed error_type=%s",
            type(exc).__name__,
        )
        errors.append(f"HSCITY library directory fetch failed ({type(exc).__name__})")
        return {
            "pages": pages,
            "memberships": memberships,
            "source_counts": source_counts,
            "directory_slugs": [],
            "errors": errors,
        }

    if directory_slugs != HSCITY_LIBRARY_DIRECTORY_SLUGS:
        missing = sorted(HSCITY_LIBRARY_DIRECTORY_SLUGS - directory_slugs)
        unexpected = sorted(directory_slugs - HSCITY_LIBRARY_DIRECTORY_SLUGS)
        errors.append(
            "HSCITY official library directory changed "
            f"(missing={missing} unexpected={unexpected})"
        )

    for slug in HSCITY_LIBRARY_SITE_MENU_IDS:
        if pages >= page_budget:
            errors.append(
                f"HSCITY library source fanout capped at {pages} of "
                f"{len(HSCITY_LIBRARY_SITE_MENU_IDS) + 1} pages"
            )
            break
        base_url = hscity_library_list_url(slug)
        query = {
            "currentPageNo": "1",
            "recordCountPerPage": str(HSCITY_EDUCATION_PAGE_SIZE),
            "searchCondition": "contents",
            "searchKeyword": "",
            "statusCd": "",
            "freeYn": "",
            "targetCd": "",
        }
        page_url = f"{base_url}?{urlencode(query)}"
        try:
            soup = fetch_soup(crawl_session, page_url, timeout=timeout)
            pages += 1
        except Exception as exc:
            logger.warning(
                "HSCITY library lecture list fetch failed slug=%s error_type=%s",
                slug,
                type(exc).__name__,
            )
            errors.append(
                f"{slug}: library lecture list fetch failed ({type(exc).__name__})"
            )
            continue
        source_memberships, source_errors = hscity_library_page_memberships(
            slug,
            page_url,
            soup,
        )
        errors.extend(source_errors)
        source_counts[slug] = len(source_memberships)
        for identity, membership in source_memberships.items():
            previous = memberships.get(identity)
            if previous is not None:
                errors.append(
                    f"HSCITY library identity {identity} appeared in "
                    f"{previous['slug']} and {slug}"
                )
                continue
            memberships[identity] = membership

    return {
        "pages": pages,
        "memberships": memberships,
        "source_counts": source_counts,
        "directory_slugs": sorted(directory_slugs),
        "errors": list(dict.fromkeys(errors)),
    }


def apply_hscity_library_memberships(
    rows: list[dict[str, Any]],
    global_identities: set[str],
    library_scan: dict[str, Any],
) -> tuple[int, list[str]]:
    errors = list(library_scan.get("errors") or [])
    memberships = library_scan.get("memberships") or {}
    missing = sorted(set(memberships) - global_identities)
    if missing:
        errors.append(
            f"HSCITY integrated reservation missed {len(missing)} current "
            f"library lectures ({missing[:10]})"
        )

    rows_by_identity: dict[str, dict[str, Any]] = {}
    for row in rows:
        raw = row.get("raw_fields") or {}
        service_type = clean_text(raw.get("service_type"))
        service_id = clean_text(raw.get("service_id"))
        if service_type and service_id:
            rows_by_identity[f"{service_type}:{service_id}"] = row

    enriched = 0
    for identity, membership in memberships.items():
        row = rows_by_identity.get(identity)
        if row is None:
            continue
        row["branch_url"] = membership["list_url"]
        raw_fields = row.setdefault("raw_fields", {})
        raw_fields["library_directory_url"] = HSCITY_LIBRARY_DIRECTORY_URL
        raw_fields["library_home_url"] = membership["home_url"]
        raw_fields["library_list_url"] = membership["list_url"]
        raw_fields["library_branch"] = membership["branch"]
        raw_fields["library_status_filter"] = membership["status_filter"]
        enriched += 1
    return enriched, list(dict.fromkeys(errors))


def is_hscity_education_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return bool(
        target.provider == HSCITY_EDUCATION_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == HSCITY_EDUCATION_HOST
        and parsed.path in {HSCITY_EDUCATION_LIST_PATH, "/1002/3001/lectureList.do"}
        and not parsed.fragment
    )


def hscity_service_identity(item: BeautifulSoup) -> tuple[str, str]:
    if item is None:
        return "", ""
    main = item.select_one(".table-list-main") or item
    onclick = clean_text(main.get("onclick"))
    match = re.search(
        r"fnDetail\(\s*['\"](lecture|citizenuniv|citizeninfor)['\"]\s*,\s*['\"](\d+)['\"]\s*\)",
        onclick,
        re.IGNORECASE,
    )
    if match:
        return match.group(1).lower(), match.group(2)

    legacy_match = re.search(r"fnDetail\(\s*['\"](\d+)['\"]\s*\)", onclick, re.IGNORECASE)
    service_type = "lecture" if legacy_match else ""
    service_id = legacy_match.group(1) if legacy_match else ""
    service_node = item.find("input", attrs={"name": re.compile(r"\.serviceTypeCd$")})
    service_id_node = item.find("input", attrs={"name": re.compile(r"\.serviceIdx$")})
    service_type = clean_text(service_node.get("value") if service_node else service_type).lower()
    service_id = clean_text(service_id_node.get("value") if service_id_node else service_id)

    if not service_type or not service_id:
        link_node = item.find("input", attrs={"name": re.compile(r"\.linkUrl$")})
        link_url = clean_text(link_node.get("value") if link_node else "")
        parsed_link = urlparse(link_url)
        query = parse_qs(parsed_link.query)
        for candidate_type, (path, id_name) in HSCITY_EDUCATION_SERVICE_ROUTES.items():
            candidate_id = clean_text((query.get(id_name) or [""])[0])
            if parsed_link.path.endswith(path.rsplit("/", 1)[-1]) and candidate_id:
                service_type, service_id = candidate_type, candidate_id
                break

    if service_type not in HSCITY_EDUCATION_SERVICE_ROUTES or not re.fullmatch(r"\d{1,20}", service_id):
        return "", ""
    return service_type, service_id


def hscity_detail_url(current_url: str, item: BeautifulSoup) -> str:
    service_type, service_id = hscity_service_identity(item)
    if not service_type or not service_id:
        return ""
    path, id_name = HSCITY_EDUCATION_SERVICE_ROUTES[service_type]
    parsed = urlparse(current_url)
    return urlunparse((parsed.scheme, parsed.netloc, path, "", urlencode({id_name: service_id}), ""))


def hscity_provider_course_id(service_type: str, service_id: str) -> str:
    if service_type == "lecture":
        return service_id
    return f"{service_type}:{service_id}"[:100]


def hscity_item_pairs(item: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in item.select("dl.info-desc"):
        key_node = dl.select_one("dt.desc-title")
        value_node = dl.select_one("dd.desc-txt")
        key = clean_text(key_node.get_text(" ", strip=True) if key_node else "")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if key and value:
            pairs[key] = value
    return pairs


def hscity_declared_total(soup: BeautifulSoup) -> Optional[int]:
    node = soup.select_one(".table-total .num")
    text = clean_text(node.get_text(" ", strip=True) if node else "").replace(",", "")
    return int(text) if text.isdigit() else None


def hscity_record_count(soup: BeautifulSoup) -> int:
    node = soup.select_one("input[name='recordCountPerPage']")
    value = clean_text(node.get("value") if node else "")
    return int(value) if value.isdigit() and int(value) > 0 else HSCITY_EDUCATION_PAGE_SIZE


def hscity_branch_code(district_code: str, institution_idx: str, branch: str) -> str:
    institution_idx = clean_text(institution_idx)
    if not re.fullmatch(r"\d{1,20}", institution_idx):
        institution_idx = hashlib.sha1(clean_text(branch).encode("utf-8")).hexdigest()[:10].upper()
    return f"HSCITY_{district_code}_{institution_idx}"[:50]


def hscity_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in soup.select(".detail-info-list dl.item-desc"):
        key_node = dl.select_one("dt.desc-title")
        value_node = dl.select_one("dd.desc-txt")
        key = clean_text(key_node.get_text(" ", strip=True) if key_node else "")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if not key or not value:
            continue
        value = clean_text(value.replace("\uBC14\uB85C\uAC00\uAE30", "").replace("\uAC15\uC0AC\uC774\uB825\uBCF4\uAE30", ""))
        pairs[key] = value
    return pairs


def hscity_description(soup: BeautifulSoup) -> str:
    node = soup.select_one(".detail-tab.info-tab") or soup.select_one(".detail-tab-item.active")
    if not node:
        return ""
    return clean_text(node.get_text(" ", strip=True))[:2000]


def hscity_image_url(detail_url: str, soup: BeautifulSoup) -> str:
    image = soup.select_one("img[src*='/attach/editor/']")
    src = clean_text(image.get("src") if image else "")
    return urljoin(detail_url, src) if src else ""


def hscity_clean_title(title: str, branch: str) -> str:
    value = clean_text(title)
    branch = clean_text(branch)
    match = re.match(r"^\[([^\]]+)\]\s*(.+)$", value)
    if match and branch and clean_text(match.group(1)) == branch:
        return clean_text(match.group(2))
    return value


def hscity_status_from_item(item: BeautifulSoup, detail_status: str = "") -> str:
    if detail_status:
        return detail_status
    text = clean_text(item.get_text(" ", strip=True))
    if "\ub300\uae30\uc2e0\uccad" in text or "\ub300\uae30\uc811\uc218" in text:
        return "\ub300\uae30\uc811\uc218"
    if "\uc2e0\uccad\ud558\uae30" in text or "\uc811\uc218\uc911" in text:
        return "\uc811\uc218\uc911"
    if "\uc811\uc218\uc608\uc815" in text:
        return "\uc811\uc218\uc608\uc815"
    if "\uc811\uc218\ub9c8\uac10" in text or "\uac15\uc88c\uc885\ub8cc" in text or "\ub9c8\uac10" in text:
        return "\uc811\uc218\ub9c8\uac10"
    return ""


def hscity_fill_missing_target(row: dict[str, Any], target_parser: TargetParser) -> None:
    if clean_text(row.get("target")):
        return
    parsed_target = parse_crawler_target(clean_text(row.get("title")), target_parser)
    age_group = clean_text(parsed_target.get("age_group"))
    row["target"] = HSCITY_TARGET_LABELS.get(age_group, "연령 미정")
    raw_fields = row.setdefault("raw_fields", {})
    raw_fields["target_fallback"] = (
        f"title_age_group:{age_group}" if age_group else "official_source_unspecified"
    )


def hscity_capacity_pair(value: str, label: str) -> tuple[Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    match = re.search(rf"{re.escape(label)}\s*:?\s*(\d{{1,5}})\s*/\s*(\d{{1,5}})", text)
    if match:
        return int(match.group(1)), int(match.group(2))
    return None, None


def hscity_card_row(
    target: CrawlTarget,
    page_url: str,
    item: BeautifulSoup,
    district_code: str,
    status_filter: str,
) -> Optional[dict[str, Any]]:
    service_type, service_id = hscity_service_identity(item)
    main = item.select_one(".table-list-main") or item
    title_node = main.select_one(".main-title")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    if not service_type or not service_id or not title or is_low_value_title(title):
        return None

    branch_nodes = main.select(".inst-info-item .info-title > span:not(.tel)")
    list_branch = clean_text(branch_nodes[0].get_text(" ", strip=True) if branch_nodes else "")
    branch = list_branch or clean_text(target.branch) or "화성특례시 통합예약시스템"
    phone_node = main.select_one(".inst-info-item .info-title > .tel")
    phone = clean_text(phone_node.get_text(" ", strip=True) if phone_node else "")
    institution_node = item.find("input", attrs={"name": re.compile(r"\.institutionIdx$")})
    institution_idx = clean_text(institution_node.get("value") if institution_node else "")
    pairs = hscity_item_pairs(main)
    flags = [
        clean_text(node.get_text(" ", strip=True))
        for node in main.select(".flag-list .flag")
        if clean_text(node.get_text(" ", strip=True))
    ]
    target_text = ", ".join(flag for flag in flags if flag not in {"무료", "유료"})
    fee_hint = next((flag for flag in flags if flag in {"무료", "유료"}), "")
    category_node = item.select_one(".table-list-num")
    category = clean_text(category_node.get_text(" ", strip=True) if category_node else "").strip("[]")
    raw_url = hscity_detail_url(page_url, item)
    apply_button = item.select_one("button[onclick*='fnApply']")
    application_available = apply_button is not None
    capacity_current, capacity_total = parse_capacity_pair(pairs.get("신청자수", ""))
    waitlist_current, waitlist_total = parse_capacity_pair(pairs.get("대기자수", ""))
    district = HSCITY_EDUCATION_DISTRICTS[district_code]
    row: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": hscity_provider_course_id(service_type, service_id),
        "title": title,
        "branch": branch,
        "branch_code": hscity_branch_code(district_code, institution_idx, branch),
        "preserve_branch": True,
        "branch_url": HSCITY_EDUCATION_LIST_URL,
        "venue_name": branch,
        "category": category or "교육",
        "raw_url": raw_url,
        "status": HSCITY_EDUCATION_STATUS_LABELS[status_filter],
        "fee": clean_text(pairs.get("수강료")) or fee_hint,
        "material_fee": clean_text(pairs.get("재료비")),
        "period": normalize_month_day_range(pairs.get("강좌기간", "")),
        "apply_period": normalize_month_day_range(pairs.get("접수기간", "")),
        "target": target_text,
        "capacity": capacity_total,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_current": waitlist_current,
        "waitlist_total": waitlist_total,
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "phone": phone,
        "description": clean_text(item.get_text(" ", strip=True))[:2000],
        "program_type": "강좌",
        "reservation_available": application_available,
        "municipality_code": district["municipality_code"],
        "municipality_full_name": district["municipality_full_name"],
        "raw_fields": {
            "parser": HSCITY_EDUCATION_PARSER,
            "service_type": service_type,
            "service_id": service_id,
            "status_filter": status_filter,
            "district_filter": district_code,
            "district_name": district["name"],
            "institution_idx": institution_idx,
            "list_pairs": pairs,
            "list_flags": flags,
            "page_url": page_url,
            "application_button": application_available,
            "clear_application_url": not application_available,
        },
    }
    if application_available:
        row["application_url"] = raw_url
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}


def hscity_enrich_detail(row: dict[str, Any], soup: BeautifulSoup) -> None:
    detail_pairs = hscity_detail_pairs(soup)
    branch = clean_text(detail_pairs.get("운영기관")) or clean_text(row.get("branch"))
    title = hscity_clean_title(detail_pairs.get("강좌명") or row.get("title"), branch)
    if title:
        row["title"] = title
    if branch:
        row["branch"] = branch
    row["venue_name"] = clean_text(detail_pairs.get("장소")) or branch

    detail_capacity = clean_text(detail_pairs.get("신청/대기"))
    capacity_current, capacity_total = hscity_capacity_pair(detail_capacity, "신청자수")
    waitlist_current, waitlist_total = hscity_capacity_pair(detail_capacity, "대기자수")
    for key, value in (
        ("capacity_current", capacity_current),
        ("capacity_total", capacity_total),
        ("capacity", capacity_total),
        ("waitlist_current", waitlist_current),
        ("waitlist_total", waitlist_total),
    ):
        if value is not None:
            row[key] = value

    detail_values = {
        "category": clean_text(detail_pairs.get("강좌분류")),
        "target": clean_text(detail_pairs.get("교육대상")),
        "fee": clean_text(detail_pairs.get("수강료")),
        "material_fee": clean_text(detail_pairs.get("재료비")),
        "period": normalize_mixed_date_range(detail_pairs.get("수강기간", "")),
        "apply_period": normalize_mixed_date_range(detail_pairs.get("접수일시", "")),
        "schedule_raw": clean_text(detail_pairs.get("요일/시간")),
        "application_method_raw": clean_text(detail_pairs.get("접수방법")),
        "instructor": clean_instructor_name(detail_pairs.get("강사명")),
        "phone": clean_text(detail_pairs.get("문의처")),
    }
    for key, value in detail_values.items():
        if value:
            row[key] = value
    description = hscity_description(soup)
    image_url = hscity_image_url(clean_text(row.get("raw_url")), soup)
    if description:
        row["description"] = description
    if image_url:
        row["image_url"] = image_url

    detail_application_button = soup.select_one("button[onclick*='fnApply']") is not None
    application_available = bool((row.get("raw_fields") or {}).get("application_button") or detail_application_button)
    row["reservation_available"] = application_available
    raw_fields = row.setdefault("raw_fields", {})
    raw_fields["detail_pairs"] = detail_pairs
    raw_fields["detail_application_button"] = detail_application_button
    raw_fields["clear_application_url"] = not application_available
    if application_available:
        row["application_url"] = row.get("raw_url")
    else:
        row.pop("application_url", None)


def collect_hscity_lecture_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 30,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if not is_hscity_education_target(target):
        raise ValueError("HSCITY education target must use the owned official HTTPS lecture list route")
    s = session()
    pages = 0
    detail_pages = 0
    detail_errors = 0
    pagination_detected = False
    page_cap = max(1, max_pages)

    def request_url(page: int, district_code: str, status_filter: str) -> str:
        target_query = parse_qs(urlparse(target.url).query)
        query = {
            "currentPageNo": str(page),
            "recordCountPerPage": str(HSCITY_EDUCATION_PAGE_SIZE),
            "searchCondition": "lectureNm",
            "searchKeyword": clean_text((target_query.get("searchKeyword") or [""])[0]),
            "searchInstitutionTypeCd": "",
            "searchAreaEmd": district_code,
            "institutionIdx": "",
            "statusCd": status_filter,
            "freeYn": "",
            "targetCd": "",
        }
        return f"{HSCITY_EDUCATION_LIST_URL}?{urlencode(query)}"

    def fetch_scope(district_code: str, status_filter: str, *, build_rows: bool) -> dict[str, Any]:
        nonlocal pages, pagination_detected
        scope_name = f"district={district_code or 'all'} status={status_filter}"
        identities: set[str] = set()
        scope_rows: list[dict[str, Any]] = []
        errors: list[str] = []
        declared_total: Optional[int] = None
        expected_pages = 1
        page = 1
        while page <= expected_pages:
            if pages >= page_cap:
                errors.append(f"max_pages cap reached before {scope_name} page {page}")
                break
            current_url = request_url(page, district_code, status_filter)
            try:
                soup = fetch_soup(s, current_url, timeout=timeout)
            except Exception as exc:
                logger.warning(
                    "HSCITY education list fetch failed scope=%s page=%s error_type=%s",
                    scope_name,
                    page,
                    type(exc).__name__,
                )
                errors.append(f"{scope_name} page {page} fetch failed ({type(exc).__name__})")
                break
            pages += 1
            page_total = hscity_declared_total(soup)
            if page_total is None:
                errors.append(f"{scope_name} page {page} omitted the official total count")
                break
            page_unit = hscity_record_count(soup)
            page_expected_pages = max(1, (page_total + page_unit - 1) // page_unit)
            if declared_total is None:
                declared_total = page_total
                expected_pages = page_expected_pages
                pagination_detected = pagination_detected or expected_pages > 1
            elif page_total != declared_total or page_expected_pages != expected_pages:
                errors.append(
                    f"{scope_name} page {page} changed declaration from "
                    f"{declared_total}/{expected_pages} to {page_total}/{page_expected_pages}"
                )
                break

            for item in soup.select(".table-list-item:not(.total-cart)"):
                service_type, service_id = hscity_service_identity(item)
                identity = f"{service_type}:{service_id}" if service_type and service_id else ""
                if not identity:
                    errors.append(f"{scope_name} page {page} contained a card without a valid service identity")
                    continue
                if identity in identities:
                    errors.append(f"{scope_name} duplicated service identity {identity}")
                    continue
                if build_rows:
                    row = hscity_card_row(target, current_url, item, district_code, status_filter)
                    if row is None:
                        errors.append(f"{scope_name} could not parse service identity {identity}")
                        continue
                    scope_rows.append(row)
                identities.add(identity)
            page += 1

        if declared_total is not None and len(identities) != declared_total:
            errors.append(f"{scope_name} parsed {len(identities)} of {declared_total} declared cards")
        return {
            "identities": identities,
            "rows": scope_rows,
            "declared_total": declared_total,
            "expected_pages": expected_pages,
            "errors": errors,
        }

    def scan_all_scopes() -> dict[str, Any]:
        candidates: dict[str, dict[str, Any]] = {}
        district_memberships: dict[str, str] = {}
        global_identities: set[str] = set()
        scope_counts: dict[str, int] = {}
        errors: list[str] = []
        duplicate_count = 0
        for district_code in HSCITY_EDUCATION_DISTRICTS:
            for status_filter in HSCITY_EDUCATION_STATUSES:
                result = fetch_scope(district_code, status_filter, build_rows=True)
                errors.extend(result["errors"])
                scope_counts[f"{district_code}:{status_filter}"] = int(result["declared_total"] or 0)
                for row in result["rows"]:
                    raw = row.get("raw_fields") or {}
                    identity = f"{raw.get('service_type')}:{raw.get('service_id')}"
                    if identity in candidates:
                        duplicate_count += 1
                        errors.append(
                            f"district/status fanout duplicated {identity} in "
                            f"{district_memberships[identity]} and {district_code}:{status_filter}"
                        )
                        continue
                    candidates[identity] = row
                    district_memberships[identity] = f"{district_code}:{status_filter}"

        for status_filter in HSCITY_EDUCATION_STATUSES:
            result = fetch_scope("", status_filter, build_rows=False)
            errors.extend(result["errors"])
            scope_counts[f"all:{status_filter}"] = int(result["declared_total"] or 0)
            overlap = global_identities.intersection(result["identities"])
            if overlap:
                duplicate_count += len(overlap)
                errors.append(f"global status filters duplicated {len(overlap)} service identities")
            global_identities.update(result["identities"])

        district_identities = set(candidates)
        if district_identities != global_identities:
            missing = len(global_identities - district_identities)
            unexpected = len(district_identities - global_identities)
            errors.append(
                f"district union did not match global current set "
                f"(district={len(district_identities)} global={len(global_identities)} "
                f"missing={missing} unexpected={unexpected})"
            )
        return {
            "rows": list(candidates.values()),
            "district_identities": district_identities,
            "global_identities": global_identities,
            "scope_counts": scope_counts,
            "duplicate_count": duplicate_count,
            "errors": list(dict.fromkeys(errors)),
        }

    scan_attempts = 1
    scan = scan_all_scopes()
    if scan["errors"] and page_cap - pages >= (
        len(HSCITY_EDUCATION_DISTRICTS) + 1
    ) * len(HSCITY_EDUCATION_STATUSES):
        scan_attempts += 1
        scan = scan_all_scopes()

    rows = scan["rows"]
    library_scan_enabled = bool(target.extra.get("hscity_library_directory_audit"))
    library_scan_attempts = 0
    library_scan: dict[str, Any] = {
        "pages": 0,
        "memberships": {},
        "source_counts": {},
        "directory_slugs": [],
        "errors": [],
    }
    library_enriched_count = 0
    library_errors: list[str] = []
    if library_scan_enabled:
        library_scan_attempts = 1
        library_scan = hscity_library_membership_scan(
            s,
            timeout=timeout,
            page_budget=max(0, page_cap - pages),
        )
        pages += int(library_scan["pages"])
        required_library_pages = len(HSCITY_LIBRARY_SITE_MENU_IDS) + 1
        if library_scan["errors"] and page_cap - pages >= required_library_pages:
            library_scan_attempts += 1
            library_scan = hscity_library_membership_scan(
                s,
                timeout=timeout,
                page_budget=max(0, page_cap - pages),
            )
            pages += int(library_scan["pages"])
        library_enriched_count, library_errors = apply_hscity_library_memberships(
            rows,
            scan["global_identities"],
            library_scan,
        )

    list_collection_complete = not scan["errors"] and not library_errors
    if list_collection_complete:
        expected_detail_pages = min(len(rows), max(0, detail_limit))
        for row in rows:
            if detail_pages >= max(0, detail_limit):
                break
            detail_pages += 1
            try:
                detail_soup = fetch_soup(s, clean_text(row.get("raw_url")), timeout=timeout)
                hscity_enrich_detail(row, detail_soup)
            except Exception as exc:
                detail_errors += 1
                raw_fields = row.setdefault("raw_fields", {})
                raw_fields["detail_error"] = type(exc).__name__
                logger.debug(
                    "HSCITY education detail fetch failed url=%s error_type=%s",
                    safe_url_for_log(row.get("raw_url")),
                    type(exc).__name__,
                )
            if (
                detail_pages == 1
                or detail_pages % 100 == 0
                or detail_pages == expected_detail_pages
            ):
                logger.info(
                    "HSCITY education detail progress course=%s/%s errors=%s",
                    detail_pages,
                    expected_detail_pages,
                    detail_errors,
                )

    hscity_target_parser = TargetParser()
    for row in rows:
        hscity_fill_missing_target(row, hscity_target_parser)

    service_type_counts: dict[str, int] = {}
    district_counts: dict[str, int] = {}
    status_counts: dict[str, int] = {}
    for row in rows:
        raw = row.get("raw_fields") or {}
        service_type = clean_text(raw.get("service_type"))
        district_code = clean_text(raw.get("district_filter"))
        status_filter = clean_text(raw.get("status_filter"))
        service_type_counts[service_type] = service_type_counts.get(service_type, 0) + 1
        district_counts[district_code] = district_counts.get(district_code, 0) + 1
        status_counts[status_filter] = status_counts.get(status_filter, 0) + 1

    no_current_data = list_collection_complete and not rows
    detail_enrichment_capped = list_collection_complete and len(rows) > detail_pages
    collection_errors = [*scan["errors"], *library_errors]
    if detail_enrichment_capped:
        collection_errors.append(f"detail enrichment capped at {detail_pages} of {len(rows)} current courses")
    if detail_errors:
        collection_errors.append(f"detail fetch failed for {detail_errors} current courses")
    collection_complete = list_collection_complete and not detail_enrichment_capped and detail_errors == 0
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_pages,
        "detail_errors": detail_errors,
        "detail_enrichment_capped": detail_enrichment_capped,
        "discovered_links": len(scan["global_identities"]),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": True,
        "pagination_complete": collection_complete,
        "pagination_exhausted": collection_complete,
        "list_pagination_complete": list_collection_complete,
        "source_cap_reached": detail_enrichment_capped
        or any("max_pages cap" in error for error in scan["errors"]),
        "fanout_cap_reached": not list_collection_complete,
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": "official current status filters returned zero courses" if no_current_data else "",
        "scan_attempts": scan_attempts,
        "scope_counts": scan["scope_counts"],
        "district_counts": district_counts,
        "status_counts": status_counts,
        "service_type_counts": service_type_counts,
        "duplicate_count": scan["duplicate_count"],
        "global_union_matches": scan["district_identities"] == scan["global_identities"],
        "library_directory_audit": library_scan_enabled,
        "library_scan_attempts": library_scan_attempts,
        "library_directory_pages": int(library_scan.get("pages") or 0),
        "library_directory_count": len(library_scan.get("directory_slugs") or []),
        "library_source_count": len(library_scan.get("source_counts") or {}),
        "library_source_counts": library_scan.get("source_counts") or {},
        "library_current_count": len(library_scan.get("memberships") or {}),
        "library_enriched_count": library_enriched_count,
    }
    if collection_errors:
        meta["configured_collection_error"] = "; ".join(collection_errors)
    return dedupe_rows(rows), HSCITY_EDUCATION_PARSER, meta


def normalize_ydp_schedule(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    days = "\uC6D4\uD654\uC218\uBAA9\uAE08\uD1A0\uC77C"
    return re.sub(rf"\b([{days}])\s+\1\b", r"\1", text)


YDP_RESERVE_PROVIDER = "MUNI_WWW_YDP_GO_KR_02AFDA7A"
YDP_RESERVE_HOST = "www.ydp.go.kr"
YDP_RESERVE_LIST_PATH = "/reserve/selectTnEdcLctreListU.do"
YDP_RESERVE_DETAIL_PATH = "/reserve/viewTnEdcLctreU.do"
YDP_RESERVE_APPLICATION_PATH = "/reserve/addTnEdcAtnlcViewU.do"
YDP_RESERVE_KEY = "5062"
YDP_RESERVE_PAGE_SIZE = 300


def ydp_reserve_list_url(target_url: str, page: int = 1) -> str:
    del target_url
    query: list[tuple[str, str]] = [
        ("user", "USER"),
        ("key", YDP_RESERVE_KEY),
        ("rcpp", str(YDP_RESERVE_PAGE_SIZE)),
    ]
    if page > 1:
        query.append(("cpn", str(page)))
    return urlunparse(("https", YDP_RESERVE_HOST, YDP_RESERVE_LIST_PATH, "", urlencode(query), ""))


def canonical_ydp_reserve_detail_url(page_url: str, href: Any) -> tuple[str, str]:
    linked = normalize_link(page_url, clean_text(href))
    parsed = urlparse(linked)
    host = (parsed.hostname or "").lower()
    query = parse_qs(parsed.query)
    lecture_no = clean_text((query.get("lctreNo") or [""])[0])
    if (
        host != YDP_RESERVE_HOST
        or parsed.path != YDP_RESERVE_DETAIL_PATH
        or not re.fullmatch(r"\d{1,12}", lecture_no)
    ):
        return "", ""
    canonical_query = urlencode(
        (("lctreNo", lecture_no), ("user", "USER"), ("key", YDP_RESERVE_KEY))
    )
    return (
        urlunparse(("https", YDP_RESERVE_HOST, YDP_RESERVE_DETAIL_PATH, "", canonical_query, "")),
        lecture_no,
    )


def canonical_ydp_reserve_application_url(
    detail_url: str,
    href: Any,
    lecture_no: str,
) -> str:
    linked = normalize_link(detail_url, clean_text(href))
    parsed = urlparse(linked)
    query = parse_qs(parsed.query)
    linked_lecture_no = clean_text((query.get("lctreNo") or [""])[0])
    institution_no = clean_text((query.get("insttNo") or [""])[0])
    if (
        (parsed.hostname or "").lower() != YDP_RESERVE_HOST
        or parsed.path != YDP_RESERVE_APPLICATION_PATH
        or linked_lecture_no != lecture_no
        or not re.fullmatch(r"\d{1,12}", institution_no)
    ):
        return ""
    canonical_query = urlencode(
        (
            ("insttNo", institution_no),
            ("lctreNo", lecture_no),
            ("user", "USER"),
            ("key", YDP_RESERVE_KEY),
        )
    )
    return urlunparse(
        ("https", YDP_RESERVE_HOST, YDP_RESERVE_APPLICATION_PATH, "", canonical_query, "")
    )


def ydp_reserve_page_declaration(soup: BeautifulSoup) -> tuple[Optional[int], int]:
    total: Optional[int] = None
    total_node = soup.select_one("em.em_black[data-mask], em.em_black")
    total_match = re.search(r"[\d,]+", clean_text(total_node.get_text(" ", strip=True) if total_node else ""))
    if total_match:
        total = int(total_match.group(0).replace(",", ""))

    page_count = 0
    text = clean_text(soup.get_text(" ", strip=True))
    ratio_match = re.search(r"\[\s*\d+\s*/\s*(\d+)\s*\uD398\uC774\uC9C0\s*\]", text)
    if ratio_match:
        page_count = int(ratio_match.group(1))
    for link in soup.select(".p-pagination a[href*='cpn='], a[href*='cpn=']"):
        query = parse_qs(urlparse(normalize_link("https://www.ydp.go.kr/", link.get("href"))).query)
        value = clean_text((query.get("cpn") or [""])[0])
        if value.isdigit():
            page_count = max(page_count, int(value))
    return total, page_count


def ydp_reserve_status(value: Any) -> str:
    text = clean_text(value).replace(" ", "")
    if "\uB300\uAE30\uC811\uC218" in text:
        return "WAITING"
    if "\uC811\uC218\uC608\uC815" in text:
        return "SCHEDULED"
    if "\uC811\uC218\uC911" in text:
        return "OPEN"
    if any(token in text for token in ("\uC811\uC218\uB9C8\uAC10", "\uAD50\uC721\uC911", "\uAD50\uC721\uC644\uB8CC", "\uC885\uB8CC")):
        return "CLOSED"
    return normalize_status(text) or text


def ydp_reserve_card_period(text: str, label: str) -> str:
    match = re.search(
        rf"{re.escape(label)}\s*[:\uFF1A]\s*"
        r"(\d{2}[.]\s*\d{1,2}[.]\s*\d{1,2}[.])\s*~\s*"
        r"(\d{2}[.]\s*\d{1,2}[.]\s*\d{1,2}[.])",
        clean_text(text),
    )
    return normalize_yymmdd_range(" ~ ".join(match.groups())) if match else ""


def ydp_reserve_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for tr in soup.select("table.p-table.block tr, table.p-table tr"):
        cells = tr.find_all(["th", "td"], recursive=False)
        if len(cells) < 2:
            cells = tr.find_all(["th", "td"])
        index = 0
        while index + 1 < len(cells):
            label_cell = cells[index]
            value_cell = cells[index + 1]
            if label_cell.name == "th" and value_cell.name == "td":
                label = clean_text(label_cell.get_text(" ", strip=True)).rstrip(":\uFF1A")
                value = clean_text(value_cell.get_text(" ", strip=True))
                if label:
                    pairs[label] = value
                index += 2
                continue
            index += 1
    return pairs


def ydp_reserve_normalize_venue(value: Any) -> str:
    text = clean_text(value)
    text = re.sub(
        r"(?P<dong>[\uAC00-\uD7A30-9]+\uB3D9)\s*\uC8FC\uBBFC\uC13C\uD130",
        lambda match: f"{match.group('dong')} \uC8FC\uBBFC\uC13C\uD130",
        text,
    )
    return text


def ydp_reserve_branch_name(title: str, venue_name: str, fallback: str) -> str:
    venue = ydp_reserve_normalize_venue(venue_name)
    if venue.replace(" ", "") == "\uB3D9\uC8FC\uBBFC\uC13C\uD130":
        candidates = re.findall(r"\(([^()]*(?:\uC8FC\uBBFC\uC13C\uD130|\uBCF5\uC9C0\uD68C\uAD00|\uD559\uC2B5\uAD00)[^()]*)\)", title)
        if candidates:
            venue = ydp_reserve_normalize_venue(candidates[-1])
    compact = venue.replace(" ", "")
    if compact.startswith("YDP\uBBF8\uB798\uD3C9\uC0DD\uD559\uC2B5\uAD00"):
        return "YDP\uBBF8\uB798\uD3C9\uC0DD\uD559\uC2B5\uAD00"
    if compact.startswith("\uC591\uD3C9\uB3D9\uC8FC\uBBFC\uBCF5\uC9C0\uD68C\uAD00"):
        return "\uC591\uD3C9\uB3D9\uC8FC\uBBFC\uBCF5\uC9C0\uD68C\uAD00"
    return venue or clean_text(fallback)


def ydp_reserve_notice_location(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    match = re.search(
        r"\uC7A5\s*\uC18C\s*[:\uFF1A]\s*(.+?)(?=\s*[\u2714\u2605\u25CB\u25CF]\s*|\s*<[^>]+>|$)",
        text,
    )
    if not match:
        return "", ""
    location = clean_text(match.group(1))
    address = ""
    address_match = re.search(r"\(([^()]*(?:\uB85C|\uAE38|\uB3D9|\uC74D|\uBA74)\s*\d[^()]*)\)", location)
    if address_match:
        address = clean_text(address_match.group(1))
        location = clean_text(location[: address_match.start()])
    return location, address


def ydp_reserve_capacity(value: Any) -> tuple[Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    total_match = re.search(r"\uCD1D\uC778\uC6D0\s*[:\uFF1A]\s*(\d+)", text)
    waitlist_match = re.search(r"\uB300\uAE30\uC778\uC6D0\s*[:\uFF1A]\s*(\d+)", text)
    return (
        int(total_match.group(1)) if total_match else None,
        int(waitlist_match.group(1)) if waitlist_match else None,
    )


def collect_ydp_reserve_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    listed_rows: list[dict[str, Any]] = []
    seen_lectures: set[str] = set()
    pages = 0
    detail_pages = 0
    detail_attempts = 0
    declared_total: Optional[int] = None
    declared_pages = 0
    pagination_exhausted = False
    source_cap_reached = False
    errors: list[str] = []

    for page in range(1, max(1, max_pages) + 1):
        current_url = ydp_reserve_list_url(target.url, page)
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_total, page_count = ydp_reserve_page_declaration(soup)
        if declared_total is None:
            declared_total = page_total
        elif page_total is not None and declared_total != page_total:
            errors.append(f"declared total changed from {declared_total} to {page_total} on page {page}")
            break
        declared_pages = max(declared_pages, page_count)

        page_new_rows = 0
        containers = soup.select("ul.board-lines > li")
        for container in containers:
            item = container.select_one(".list-area") or container
            lines = [clean_text(line) for line in item.get_text("\n", strip=True).splitlines() if clean_text(line)]
            if not lines:
                continue
            title_link = item.select_one("a.lists[href]") or item.find("a", href=True)
            title = clean_text(title_link.get_text(" ", strip=True)) if title_link else lines[0]
            if not title or is_low_value_title(title):
                continue
            raw_url, lecture_no = canonical_ydp_reserve_detail_url(
                current_url, title_link.get("href") if title_link else ""
            )
            if not raw_url or lecture_no in seen_lectures:
                continue
            seen_lectures.add(lecture_no)
            page_new_rows += 1
            status_node = container.select_one("a.sk span") or container.select_one("a.sk")
            status_text = clean_text(status_node.get_text(" ", strip=True) if status_node else "")
            branch_node = item.select_one(".adds .ad")
            target_node = item.select_one(".adds .as")
            venue_name = ydp_reserve_normalize_venue(
                branch_node.get_text(" ", strip=True) if branch_node else ""
            )
            target_text = clean_text(
                target_node.get_text(" ", strip=True) if target_node else ""
            ).lstrip("#")
            item_text = clean_text(container.get_text(" ", strip=True))
            period = ydp_reserve_card_period(item_text, "\uAD50\uC721\uAE30\uAC04")
            apply_period = ydp_reserve_card_period(item_text, "\uC811\uC218\uAE30\uAC04")
            capacity_match = re.search(
                r"\uC811\uC218\s*/\s*\uC815\uC6D0\s*([\d,]+)\s*/\s*([\d,]+)", item_text
            )
            capacity_current = int(capacity_match.group(1).replace(",", "")) if capacity_match else None
            capacity_total = int(capacity_match.group(2).replace(",", "")) if capacity_match else None
            branch = ydp_reserve_branch_name(title, venue_name, target.branch)
            start_date, end_date = parse_date_range(period)
            apply_start, apply_end = parse_date_range(apply_period)
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": lecture_no,
                "prefer_incoming_provider_course_id": True,
                "title": title,
                "branch": branch,
                "branch_code": stable_provider(target.provider[:32], branch),
                "preserve_branch": True,
                "branch_url": target.url,
                "raw_url": raw_url,
                "status": ydp_reserve_status(status_text),
                "period": period,
                "apply_period": apply_period,
                "start_date": start_date,
                "end_date": end_date,
                "apply_start": apply_start,
                "apply_end": apply_end,
                "target": target_text or (clean_text(lines[2].lstrip("#")) if len(lines) > 2 else ""),
                "venue_name": venue_name or branch,
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "description": item_text,
                "program_type": "\uAC15\uC88C",
                "reservation_available": False,
                "raw_fields": {
                    "lines": lines,
                    "parser": "ydp_education_lecture_list",
                    "lecture_no": lecture_no,
                    "list_status": status_text,
                    "list_venue": venue_name,
                    "page_url": current_url,
                },
            }
            listed_rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

        if declared_total is not None and len(seen_lectures) == declared_total:
            pagination_exhausted = True
            break
        if declared_total is not None and len(seen_lectures) > declared_total:
            errors.append(
                f"parsed {len(seen_lectures)} rows beyond declared total {declared_total}"
            )
            break
        if declared_pages and page >= declared_pages:
            errors.append(
                f"parsed {len(seen_lectures)} of {declared_total} declared lecture rows"
            )
            break
        if page_new_rows == 0:
            errors.append(f"page {page} did not expose new lctreNo rows")
            break

    if declared_total is None:
        errors.append("list page did not declare a total row count")
    if not pagination_exhausted and not errors:
        source_cap_reached = True
        errors.append(
            f"max_pages cap reached after {pages} pages with {len(seen_lectures)} of "
            f"{declared_total} declared lecture rows"
        )
    if errors and pages >= max(1, max_pages) and not pagination_exhausted:
        source_cap_reached = True

    allowed_details = max(0, detail_limit)
    if allowed_details < len(listed_rows):
        source_cap_reached = True
        errors.append(
            f"detail_limit cap allows {allowed_details} of {len(listed_rows)} required detail pages"
        )
    detail_errors: list[str] = []
    for row in listed_rows[:allowed_details]:
        detail_url = clean_text(row.get("raw_url"))
        lecture_no = clean_text((row.get("raw_fields") or {}).get("lecture_no"))
        detail_attempts += 1
        try:
            detail_soup = fetch_soup(s, detail_url, timeout=timeout)
            detail_pages += 1
            pairs = ydp_reserve_detail_pairs(detail_soup)
            detail_title = clean_text(pairs.get("\uACFC\uC815\uBA85"))
            if detail_title and not is_low_value_title(detail_title):
                row["title"] = detail_title

            raw_venue = ydp_reserve_normalize_venue(pairs.get("\uAD50\uC721\uC7A5\uC18C"))
            notice = clean_text(pairs.get("\uC218\uAC15\uC2E0\uCCAD\uC720\uC758\uC0AC\uD56D"))
            notice_venue, notice_address = ydp_reserve_notice_location(notice)
            venue_name = raw_venue
            if raw_venue.replace(" ", "") == "\uB3D9\uC8FC\uBBFC\uC13C\uD130":
                venue_name = ydp_reserve_branch_name(row["title"], raw_venue, row["branch"])
            elif raw_venue == "\uAE30\uD0C0" and notice_venue:
                venue_name = notice_venue
            branch = ydp_reserve_branch_name(row["title"], venue_name, row["branch"])
            row["branch"] = branch
            row["branch_code"] = stable_provider(target.provider[:32], branch)
            row["venue_name"] = venue_name or branch
            if notice_address:
                row["address"] = notice_address
                row["venue_address"] = notice_address

            period = normalize_yymmdd_range(pairs.get("\uAD50\uC721\uAE30\uAC04", ""))
            apply_period = normalize_yymmdd_range(pairs.get("\uC811\uC218\uAE30\uAC04", ""))
            if period:
                row["period"] = period
                row["start_date"], row["end_date"] = parse_date_range(period)
            if apply_period:
                row["apply_period"] = apply_period
                row["apply_start"], row["apply_end"] = parse_date_range(apply_period)

            row["instructor"] = clean_instructor_name(pairs.get("\uAC15\uC0AC\uBA85"))
            row["application_method_raw"] = clean_text(pairs.get("\uC811\uC218\uBC29\uC2DD"))
            row["selection_method"] = clean_text(pairs.get("\uC120\uBCC4\uBC29\uC2DD"))
            row["target"] = clean_text(pairs.get("\uC218\uAC15\uB300\uC0C1")).lstrip("#") or row.get("target", "")
            row["fee"] = clean_text(pairs.get("\uC218\uAC15\uB8CC"))
            row["material_fee"] = clean_text(pairs.get("\uC7AC\uB8CC\uBE44"))
            row["schedule_raw"] = normalize_ydp_schedule(pairs.get("\uAC15\uC758\uC694\uC77C"))
            row["category"] = clean_text(pairs.get("\uAD00\uC2EC\uBD84\uC57C")).lstrip("#")
            capacity_total, waitlist_total = ydp_reserve_capacity(pairs.get("\uC815\uC6D0"))
            if capacity_total is not None:
                row["capacity_total"] = capacity_total
            if waitlist_total is not None:
                row["waitlist_total"] = waitlist_total
            phone_match = re.search(r"0\d{1,2}-\d{3,4}-\d{4}", clean_text(pairs.get("\uAD50\uC721\uACFC\uC815\uBB38\uC758")))
            if phone_match:
                row["phone"] = phone_match.group(0)
            description = clean_text(
                " ".join(
                    value
                    for value in (
                        pairs.get("\uAC15\uC758\uAC1C\uC694", ""),
                        notice,
                    )
                    if clean_text(value)
                )
            )
            if description:
                row["description"] = description[:4000]

            apply_link = detail_soup.select_one(
                "a[href*='addTnEdcAtnlcViewU.do'][href]"
            )
            application_url = canonical_ydp_reserve_application_url(
                detail_url,
                apply_link.get("href") if apply_link else "",
                lecture_no,
            )
            if application_url:
                row["application_url"] = application_url
            else:
                row.pop("application_url", None)
            row["reservation_available"] = bool(application_url) and row.get("status") in {
                "OPEN",
                "WAITING",
            }
            row["raw_fields"]["parser"] = "ydp_education_lecture_list+detail"
            row["raw_fields"]["detail_pairs"] = pairs
            row["raw_fields"]["raw_detail_venue"] = raw_venue
        except Exception as exc:
            detail_errors.append(f"lctreNo {lecture_no}: {type(exc).__name__}")
            logger.debug("YDP detail fetch failed %s: %s", safe_url_for_log(detail_url), exc)

    if detail_errors:
        errors.append(
            f"detail fetch failed for {len(detail_errors)} of {len(listed_rows)} lectures "
            f"({', '.join(detail_errors[:5])})"
        )

    rows: list[dict[str, Any]] = []
    expired_count = 0
    for row in listed_rows:
        if should_skip_expired_course(row):
            expired_count += 1
            continue
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

    list_complete = (
        pagination_exhausted
        and declared_total is not None
        and len(seen_lectures) == declared_total
    )
    details_complete = detail_pages == len(listed_rows) and not detail_errors
    snapshot_complete = list_complete and details_complete and not errors
    no_current_data = snapshot_complete and not rows

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "declared_total": declared_total,
        "declared_pages": declared_pages,
        "discovered_links": len(seen_lectures),
        "reservation_discovery_links": sum(
            bool(clean_text(row.get("application_url"))) for row in rows
        ),
        "pagination_detected": declared_pages > 1,
        "pagination_complete": list_complete,
        "pagination_exhausted": list_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached,
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": "official current lecture list is empty" if no_current_data else "",
        "expired_count": expired_count,
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(rows), "ydp_education_lecture_list+detail", meta


def ice_library_branch_name(soup: BeautifulSoup, target: CrawlTarget) -> str:
    title = clean_text(soup.title.get_text(" ", strip=True) if soup.title else "")
    if title:
        candidate = clean_text(title.split(">", 1)[0])
        candidate = clean_text(candidate.replace("인천광역시교육청", ""))
        if candidate:
            return candidate
    return target.branch


def ice_library_footer_address(soup: BeautifulSoup) -> str:
    text = clean_text((soup.select_one(".address") or soup.select_one("#footer") or soup).get_text(" ", strip=True))
    match = re.search(r"주소\s*:\s*(?:\(\s*)?\d{5}\s*\)?\s*(.+?)(?:\s*대표전화|\s*FAX|\s*Copyright|\s*$)", text)
    if match:
        return clean_text(match.group(1))
    match = re.search(r"인천\s+[^\s]+구\s+.+?(?=\s*(?:대표전화|FAX|Copyright|$))", text)
    return clean_text(match.group(0)) if match else ""


def ice_library_item_pairs(item: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select(".con2 li"):
        label_node = li.select_one("label")
        if not label_node:
            continue
        label = clean_text(label_node.get_text(" ", strip=True)).rstrip(":")
        label_text = clean_text(label_node.get_text(" ", strip=True))
        value = clean_text(li.get_text(" ", strip=True))
        value = clean_text(value.replace(label_text, "", 1)).lstrip(":").strip()
        if label:
            pairs[label] = value
    return pairs


def ice_library_detail_url(base_url: str, item: Any) -> str:
    link = item.select_one("a.detail-btn[keyvalue1][keyvalue2][keyvalue3], a.detail-btn[keyValue1][keyValue2][keyValue3]")
    if not link:
        link = item.select_one("a.toggle-btn[keyvalue1][keyvalue2][keyvalue3], a.toggle-btn[keyValue1][keyValue2][keyValue3]")
    if not link:
        return base_url
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    menu_idx = clean_text((query.get("menu_idx") or [""])[0])
    params = {
        "group_idx": clean_text(link.get("keyvalue1") or link.get("keyValue1")),
        "category_idx": clean_text(link.get("keyvalue2") or link.get("keyValue2")),
        "teach_idx": clean_text(link.get("keyvalue3") or link.get("keyValue3")),
    }
    if menu_idx:
        params["menu_idx"] = menu_idx
    return urljoin(base_url, f"{parsed.path.rsplit('/index.do', 1)[0]}/detail.do?{urlencode(params)}")


def ice_library_application_url(base_url: str, item: Any) -> str:
    link = item.select_one(".stat a.add[keyvalue1], .stat a.add[keyValue1]")
    if not link:
        return ice_library_detail_url(base_url, item)
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    menu_idx = clean_text((query.get("menu_idx") or [""])[0])
    params = {
        "editMode": "ADD",
        "homepage_id": clean_text(link.get("keyvalue1") or link.get("keyValue1")),
        "group_idx": clean_text(link.get("keyvalue2") or link.get("keyValue2")),
        "category_idx": clean_text(link.get("keyvalue3") or link.get("keyValue3")),
        "teach_idx": clean_text(link.get("keyvalue4") or link.get("keyValue4")),
        "large_category_idx": clean_text(link.get("keyvalue5") or link.get("keyValue5")),
        "apply_status": clean_text(link.get("apply_status")),
    }
    if menu_idx:
        params["menu_idx"] = menu_idx
    return urljoin(base_url, f"{parsed.path.rsplit('/index.do', 1)[0]}/student/edit.do?{urlencode(params)}")


def ice_library_detail_fields(s: requests.Session, detail_url: str, timeout: int) -> dict[str, str]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    pairs = pairs_from_tables(soup)
    period = normalize_mixed_date_range(clean_text(pairs.get("강의기간(*)") or pairs.get("강의기간")))
    day_text = clean_text(pairs.get("강의요일"))
    time_text = clean_text(pairs.get("강의시간"))
    schedule = clean_text(" ".join(part for part in [day_text, time_text] if part))
    return {
        "category": clean_text(pairs.get("교육과정")),
        "description": clean_text(pairs.get("강의 설명") or pairs.get("강의설명")),
        "period": period,
        "schedule_raw": schedule,
        "apply_period": normalize_mixed_date_range(clean_text(pairs.get("접수일시") or pairs.get("접수기간"))),
        "target": clean_text(pairs.get("교육대상")),
        "venue_name": clean_text(pairs.get("강의장소")),
        "room": clean_text(pairs.get("강의장소")),
        "instructor": clean_text(pairs.get("강사명")),
        "material_note": clean_text(pairs.get("준비물")),
        "capacity": clean_text(pairs.get("현재 참여 / 모집") or pairs.get("모집정원")),
        "department": clean_text(pairs.get("담당부서 및 전화번호") or pairs.get("문의")),
    }


def collect_ice_library_teach_detail(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    branch = ice_library_branch_name(soup, target)
    branch_code = clean_text(urlparse(target.url).path.strip("/").split("/", 1)[0])
    address = ice_library_footer_address(soup)
    rows: list[dict[str, Any]] = []
    detail_pages = 0

    for item in soup.select(".item"):
        category = clean_text((item.select_one(".ca") or {}).get_text(" ", strip=True) if item.select_one(".ca") else "")
        title = clean_text((item.select_one("a.toggle-btn:not(.btn)") or {}).get_text(" ", strip=True) if item.select_one("a.toggle-btn:not(.btn)") else "")
        if not title or is_low_value_title(title):
            continue
        pairs = ice_library_item_pairs(item)
        period, schedule = split_period_and_schedule(pairs.get("강의기간", ""))
        status = clean_text((item.select_one(".stat a") or {}).get_text(" ", strip=True) if item.select_one(".stat a") else "") or status_from_lines(
            [clean_text(line) for line in item.get_text("\n", strip=True).splitlines()]
        )
        detail_url = ice_library_detail_url(target.url, item)
        application_url = ice_library_application_url(target.url, item)
        detail: dict[str, str] = {}
        if detail_url != target.url:
            try:
                detail = ice_library_detail_fields(s, detail_url, timeout=timeout)
                detail_pages += 1
            except Exception as exc:
                logger.debug("ICE library detail fetch failed %s: %s", detail_url, exc)

        row = {
            "provider": target.provider,
            "provider_course_id": stable_course_id(target.provider, detail_url, title, branch),
            "title": title,
            "branch": branch,
            "branch_code": branch_code,
            "category": detail.get("category") or category,
            "raw_url": detail_url,
            "application_url": application_url,
            "status": status,
            "fee": "",
            "period": clean_text(detail.get("period") or period),
            "apply_period": clean_text(detail.get("apply_period") or pairs.get("접수기간", "")),
            "schedule_raw": clean_text(detail.get("schedule_raw") or schedule),
            "target": clean_text(detail.get("target") or pairs.get("교육대상", "")),
            "capacity": clean_text(detail.get("capacity") or pairs.get("모집인원", "") or pairs.get("접수현황", "")),
            "instructor": clean_text(detail.get("instructor") or pairs.get("강사명", "")),
            "venue_name": clean_text(detail.get("venue_name") or branch),
            "room": clean_text(detail.get("room", "")),
            "address": address,
            "venue_address": address,
            "phone": clean_text(detail.get("department", "")),
            "material_note": clean_text(detail.get("material_note", "")),
            "description": clean_text(detail.get("description") or pairs.get("상세내용", "") or item.get_text(" ", strip=True)),
            "collection_category": "도서관",
            "domain_category": "도서관",
            "operator_type": "교육청 도서관",
            "source_group": "library",
            "collection_type": "static_html",
            "program_type": "강좌",
            "application_type": "ONLINE_RESERVATION",
            "reservation_available": status in {"수강신청", "대기자신청", "접수중"},
            "raw_fields": {"pairs": pairs, "detail_url": detail_url, "parser": "ice_library_teach_detail"},
        }
        rows.append(row)

    meta = {
        "pages": 1,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "pagination_detected": bool(soup.select(".pagination, .paging")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ice_library_teach_detail", meta


def collect_ice_library_teach(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    result = collect_ice_library_teach_detail(target, timeout=timeout, max_pages=max_pages)
    if result[0] or result[2].get("no_current_data"):
        return result
    logger.info("ICE detail-layout parser returned no rows; trying the bounded legacy layout parser.")
    return collect_ice_library_teach_legacy(target, timeout=timeout, max_pages=max_pages)


def collect_ice_library_teach_legacy(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    soup = fetch_soup(s, target.url, timeout=timeout)
    labels = {"접수기간", "모집인원", "접수현황", "강의기간", "모집대상", "강사명", "학년제한", "상세내용"}

    for item in soup.select(".item"):
        lines = [clean_text(line) for line in item.get_text("\n", strip=True).splitlines() if clean_text(line)]
        if len(lines) < 4:
            continue
        category = lines[0]
        title = lines[1]
        if not title or is_low_value_title(title):
            continue
        pairs = sequence_lines_to_pairs(lines, labels)
        period, schedule = split_period_and_schedule(pairs.get("강의기간", ""))
        status = status_from_lines(lines)
        raw_url = stable_list_item_url(
            target.url,
            target.provider,
            title,
            target.branch,
            period,
            schedule,
        )
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "category": category,
                "raw_url": raw_url,
                "application_url": target.url,
                "status": status,
                "fee": "",
                "period": period,
                "apply_period": pairs.get("접수기간", ""),
                "schedule_raw": schedule,
                "target": pairs.get("모집대상", ""),
                "capacity": pairs.get("모집인원", "") or pairs.get("접수현황", ""),
                "instructor": pairs.get("강사명", ""),
                "description": pairs.get("상세내용", "") or clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"pairs": pairs, "lines": lines, "parser": "ice_library_teach"},
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": bool(soup.select(".pagination, .paging")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ice_library_teach", meta


def gbelib_branch_name(soup: BeautifulSoup, fallback: str) -> str:
    title = clean_text(soup.title.get_text(" ", strip=True) if soup.title else "")
    if ">" in title:
        candidate = clean_text(title.split(">", 1)[0])
        if candidate:
            return candidate
    og_title = soup.select_one("meta[property='og:title']")
    candidate = clean_text(og_title.get("content") if og_title else "")
    return candidate or fallback


def gbelib_footer_address(soup: BeautifulSoup) -> str:
    text = clean_text(soup.get_text(" ", strip=True))
    match = re.search(r"\(?\s*\d{5}\)?\s*([^전화팩스]+)", text)
    if match:
        return clean_text(match.group(1))
    match = re.search(r"경북\s+\S+\s+\S+\s+[^전화팩스]+", text)
    return clean_text(match.group(0)) if match else ""


def gbelib_item_pairs(item: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select("li"):
        label_node = li.select_one("label")
        if not label_node:
            continue
        label = clean_text(label_node.get_text(" ", strip=True)).rstrip(":")
        value = clean_text(li.get_text(" ", strip=True))
        label_text = clean_text(label_node.get_text(" ", strip=True))
        value = clean_text(value.replace(label_text, "", 1)).lstrip(":").strip()
        if label:
            pairs[label] = value
    return pairs


def gbelib_teach_status(item: Any, pairs: dict[str, str]) -> str:
    action_text = clean_text(" ".join(a.get_text(" ", strip=True) for a in item.select("a.add, a.cancel, .stat a")))
    source = clean_text(" ".join([action_text, pairs.get("접수현황", "")]))
    if any(token in source for token in ("수강신청", "신청가능", "접수중")):
        return "접수중"
    if any(token in source for token in ("신청대기", "접수대기", "접수예정")):
        return "접수예정"
    if any(token in source for token in ("대기자", "대기신청")):
        return "대기접수"
    if any(token in source for token in ("마감", "신청완료")):
        return "마감"
    return status_from_lines([source]) or ""


def gbelib_teach_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    pairs = pairs_from_tables(soup)
    description = clean_text(pairs.get("강의 설명") or pairs.get("강의설명"))
    period = normalize_mixed_date_range(clean_text(pairs.get("강의기간(*)") or pairs.get("강의기간")))
    time_text = clean_text(pairs.get("강의시간"))
    day_text = clean_text(pairs.get("강의요일"))
    schedule = clean_text(f"{day_text} {time_text}") if day_text and time_text else time_text or day_text
    address = gbelib_footer_address(soup)
    return {
        "category": clean_text(pairs.get("교육과정")),
        "period": period,
        "schedule_raw": schedule,
        "apply_period": normalize_mixed_date_range(clean_text(pairs.get("접수일시") or pairs.get("접수기간"))),
        "target": clean_text(pairs.get("교육대상") or pairs.get("모집대상")),
        "fee": "무료",
        "venue_name": clean_text(pairs.get("강의장소")),
        "venue_address": address,
        "address": address,
        "instructor": clean_text(pairs.get("강사명")),
        "material_note": clean_text(pairs.get("준비물 및 재료비") or pairs.get("준비물")),
        "capacity": clean_text(pairs.get("현재 참여 / 모집") or pairs.get("모집정원")),
        "description": description,
        "raw_detail_pairs": pairs,
    }


def gbelib_teach_urls(s: requests.Session, target: CrawlTarget, timeout: int) -> list[str]:
    soup = fetch_soup(s, target.url, timeout=timeout)
    parsed = urlparse(target.url)
    prefix = parsed.path.split("/module/teach/", 1)[0]
    urls = [target.url]
    for link in soup.select("a[href*='/module/teach/index.do']"):
        href = link.get("href")
        if not href:
            continue
        absolute = normalize_link(target.url, href)
        parsed_link = urlparse(absolute)
        if parsed_link.netloc != parsed.netloc:
            continue
        if not parsed_link.path.startswith(prefix + "/module/teach/"):
            continue
        query = parse_qs(parsed_link.query)
        if not query.get("searchCate1"):
            continue
        urls.append(absolute)
    return list(dict.fromkeys(urls))


def collect_gbelib_library_teach(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pages = 0
    pagination_detected = False
    discovered_urls = gbelib_teach_urls(s, target, timeout)
    page_limit = max(1, max_pages)

    for list_url in discovered_urls:
        parsed = urlparse(list_url)
        query = parse_qs(parsed.query)
        menu_idx = clean_text((query.get("menu_idx") or [""])[0])
        search_cate = clean_text((query.get("searchCate1") or [""])[0])
        search_age = clean_text((query.get("searchAge") or [""])[0])
        base_query = {key: values[-1] for key, values in query.items() if values}

        for page in range(1, page_limit + 1):
            page_query = dict(base_query)
            page_query["viewPage"] = str(page)
            page_url = parsed._replace(query=urlencode(page_query)).geturl()
            soup = fetch_soup(s, page_url, timeout=timeout)
            pages += 1
            branch = gbelib_branch_name(soup, target.branch)
            address = gbelib_footer_address(soup)
            page_rows: list[dict[str, Any]] = []

            for item in soup.select("#list_mode .item, .item"):
                title_node = item.select_one("a.detail-btn:not(.btn), .op_title a.name")
                title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
                if not title or title == "상세보기" or is_low_value_title(title):
                    continue
                detail_node = item.select_one("a.detail-btn")
                group_idx = clean_text(detail_node.get("keyvalue1") if detail_node else "")
                category_idx = clean_text(detail_node.get("keyvalue2") if detail_node else "")
                teach_idx = clean_text(detail_node.get("keyvalue3") if detail_node else "")
                large_category_idx = clean_text(detail_node.get("keyvalue4") if detail_node else search_cate)
                category = clean_text((item.select_one(".ca") or {}).get_text(" ", strip=True) if item.select_one(".ca") else "")
                pairs = gbelib_item_pairs(item)
                detail_url = ""
                if teach_idx:
                    detail_params = {
                        "group_idx": group_idx,
                        "category_idx": category_idx,
                        "teach_idx": teach_idx,
                        "large_category_idx": large_category_idx,
                        "menu_idx": menu_idx,
                        "searchCate1": search_cate,
                    }
                    if search_age:
                        detail_params["searchAge"] = search_age
                    detail_url = urljoin(list_url, f"{parsed.path.rsplit('/', 1)[0]}/detail.do?{urlencode(detail_params)}")
                row = {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, teach_idx or list_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "branch_code": parsed.path.split("/", 2)[1] if parsed.path.startswith("/") else branch,
                    "preserve_branch": True,
                    "category": category,
                    "raw_url": detail_url or page_url,
                    "application_url": detail_url or page_url,
                    "status": gbelib_teach_status(item, pairs),
                    "fee": "",
                    "period": normalize_mixed_date_range(pairs.get("수강기간", "")),
                    "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
                    "schedule_raw": clean_text(pairs.get("요일/시간", "")),
                    "target": clean_text(pairs.get("교육대상", "")),
                    "venue_name": clean_text(pairs.get("장소", "")),
                    "venue_address": address,
                    "address": address,
                    "capacity": clean_text(pairs.get("모집인원", "") or pairs.get("접수현황", "")),
                    "instructor": clean_text(pairs.get("\uAC15\uC0AC\uBA85")),
                    "material_note": clean_text(pairs.get("준비물 및 재료비", "") or pairs.get("준비물", "")),
                    "description": clean_text(item.get_text(" ", strip=True)),
                    "raw_fields": {
                        "parser": "gbelib_library_teach",
                        "list_url": list_url,
                        "pairs": pairs,
                        "menu_idx": menu_idx,
                        "searchCate1": search_cate,
                    },
                }
                if detail_url and detail_pages < detail_limit:
                    try:
                        row = merge_course_rows(row, gbelib_teach_detail_fields(s, detail_url, timeout))
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("gbelib detail fetch failed %s: %s", detail_url, exc)
                page_rows.append(row)

            rows.extend(page_rows)
            pagination_detected = pagination_detected or bool(soup.select(".paginate, .paging, .pagination, a[href*='viewPage=']"))
            if not page_rows:
                break
            if len(page_rows) < 10:
                break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(discovered_urls),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    parser_name = "gbelib_library_teach"
    if not rows:
        fallback_parsers: set[str] = set()
        for list_url in discovered_urls[:page_limit]:
            try:
                fallback_soup = fetch_soup(s, list_url, timeout=timeout)
                fallback_rows, fallback_parser = parse_all_courses(target.provider, target.branch, list_url, fallback_soup)
            except Exception as exc:
                logger.debug("gbelib generic fallback failed %s: %s", list_url, exc)
                continue
            if fallback_parser != "none":
                fallback_parsers.update(fallback_parser.split("+"))
            rows.extend(fallback_rows)
            if rows:
                break
        if fallback_parsers:
            parser_name = "+".join(["gbelib_library_teach_fallback", *sorted(fallback_parsers)])
            meta["fallback_parser"] = parser_name
    return dedupe_rows(rows), parser_name, meta


ULJIN_LIBRARY_BRANCHES = (
    "울진남부도서관",
    "북울진도서관",
    "울진작은도서관",
    "근남작은도서관",
    "매화작은도서관",
    "기성작은도서관",
    "평해작은도서관",
    "온정작은도서관",
    "죽변작은도서관",
    "흥부작은도서관",
    "통합도서관",
)

ULJIN_LIBRARY_CALENDAR_CATEGORIES = {
    "울진남부도서관": "46",
    "북울진도서관": "47",
    "울진작은도서관": "48",
    "근남작은도서관": "49",
    "매화작은도서관": "50",
    "기성작은도서관": "51",
    "평해작은도서관": "52",
    "온정작은도서관": "53",
    "흥부작은도서관": "143",
}


def normalize_uljin_korean_date_range(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    full_matches = re.findall(
        r"(\d{4})\s*년\s*(\d{1,2})\s*월\s*(\d{1,2})\s*일(?:\s*(\d{1,2})\s*시\s*(\d{1,2})\s*분?)?",
        text,
    )
    if full_matches:
        def fmt_full(match: tuple[str, str, str, str, str]) -> str:
            year, month, day, hour, minute = match
            date_part = f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
            return f"{date_part} {int(hour):02d}:{int(minute):02d}" if hour and minute else date_part

        start = fmt_full(full_matches[0])
        end = fmt_full(full_matches[-1])
        return f"{start} ~ {end}" if start != end else start
    ymd_matches = re.findall(r"(\d{4})[./-](\d{1,2})[./-](\d{1,2})(?:\s+(\d{1,2}):(\d{2}))?", text)
    if ymd_matches:
        def fmt_ymd(match: tuple[str, str, str, str, str]) -> str:
            year, month, day, hour, minute = match
            date_part = f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
            return f"{date_part} {int(hour):02d}:{minute}" if hour and minute else date_part

        start = fmt_ymd(ymd_matches[0])
        end = fmt_ymd(ymd_matches[-1])
        return f"{start} ~ {end}" if start != end else start
    return normalize_month_day_range(text)


def normalize_uljin_schedule(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    text = re.sub(r"\b매주\b", "", text)
    text = re.sub(r"\s+", " ", text)
    match = re.search(
        r"([월화수목금토일](?:\s*[,ㆍ~]\s*[월화수목금토일])*)\s*(?:요일)?\s*\(?\s*(\d{1,2}:\d{2})\s*[~-]\s*(\d{1,2}:\d{2})\s*\)?",
        text,
    )
    if match:
        return clean_text(f"{match.group(1)} {match.group(2)} ~ {match.group(3)}")
    return text


def split_uljin_library_title(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    text = re.sub(r"^\[\]\s*", "", text)
    bracket = re.match(r"^\[([^\]]+)\]\s*(.+)$", text)
    if bracket:
        return clean_text(bracket.group(1)), clean_text(bracket.group(2))
    for branch in ULJIN_LIBRARY_BRANCHES:
        if text.startswith(branch):
            return branch, clean_text(text[len(branch) :])
    return "", text


def uljin_text_with_image_alts(node: BeautifulSoup | None) -> str:
    if not node:
        return ""
    parts: list[str] = []
    text = clean_text(node.get_text(" ", strip=True))
    if text:
        parts.append(text)
    for image in node.find_all("img"):
        alt = clean_text(image.get("alt"))
        if alt:
            parts.append(alt)
    return clean_text(" ".join(parts))


def parse_uljin_library_detail(s: requests.Session, detail_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    box = soup.select_one("#edusatbox")
    if not box:
        return {}
    title_text = clean_text((box.select_one(".tit") or "").get_text(" ", strip=True))
    branch, title = split_uljin_library_title(title_text)
    pairs = pairs_from_definition_lists(box)
    pairs.update({key: value for key, value in pairs_from_tables(box).items() if value})
    editor = box.select_one(".webeditor")
    image = (editor.find("img") if editor else None) or box.find("img")
    image_url = normalize_link(detail_url, image.get("src")) if image and image.get("src") else ""
    fee_text = clean_text(pairs.get("수강료"))
    material_fee_text = clean_text(pairs.get("교재비") or pairs.get("재료비"))
    if "재료비" in fee_text:
        material_fee_text = material_fee_text or fee_text
        if "무료" in fee_text or fee_text.startswith("재료비"):
            fee_text = "무료"
    period = normalize_uljin_korean_date_range(pairs.get("강의기간") or pairs.get("행사기간"))
    schedule = normalize_uljin_schedule(pairs.get("강의일시") or pairs.get("행사일시")) or period
    return {
        "title": title,
        "branch": branch or "울진군통합도서관",
        "target": clean_text(pairs.get("교육대상") or pairs.get("참가대상") or pairs.get("대상")),
        "capacity": clean_text(pairs.get("모집인원")),
        "fee": fee_text or "무료",
        "material_fee": material_fee_text,
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "instructor": clean_text(pairs.get("강사명")),
        "status": clean_text(pairs.get("상태") or pairs.get("접수상태")),
        "apply_period": normalize_uljin_korean_date_range(pairs.get("접수기간")),
        "period": period,
        "schedule_raw": schedule,
        "room": clean_text(pairs.get("강의실") or pairs.get("행사장소")),
        "venue_name": clean_text(pairs.get("행사장소")),
        "description": clean_text(pairs.get("행사설명")) or uljin_text_with_image_alts(editor),
        "image_url": image_url,
        "raw_fields": {"pairs": pairs, "parser": "uljin_library_edusat"},
    }


def uljin_calendar_category_url(base_url: str, branch: str, year: str = "", month: str = "") -> str:
    category = ULJIN_LIBRARY_CALENDAR_CATEGORIES.get(branch, "")
    query = {"p_cate": category} if category else {}
    if year:
        query["year"] = year
    if month:
        query["month"] = month
    return normalize_link(base_url, f"/content/02schedule/01_01.php?{urlencode(query)}")


def is_uljin_library_calendar_page(soup: BeautifulSoup) -> bool:
    title = clean_text(soup.title.get_text(" ", strip=True) if soup.title else "")
    table = soup.select_one("table")
    table_text = clean_text(table.get_text(" ", strip=True) if table else "")
    weekdays = ("일요일", "월요일", "화요일", "수요일", "목요일", "금요일", "토요일")
    return "이달의 행사" in title and all(day in table_text for day in weekdays)


def parse_uljin_library_calendar_detail(
    s: requests.Session,
    detail_url: str,
    timeout: int,
    fallback_branch: str = "",
) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    table = soup.select_one("table")
    title = ""
    period = ""
    pairs: dict[str, str] = {}
    if table:
        rows = table.find_all("tr")
        if rows:
            title = clean_text(rows[0].get_text(" ", strip=True))
            branch, title = split_uljin_library_title(title)
            if branch:
                pairs["branch"] = branch
        for dl in table.select("dl.info"):
            key_node = dl.find("dt")
            value_node = dl.find("dd")
            key = clean_text(key_node.get_text(" ", strip=True) if key_node else "")
            value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
            if key and value:
                pairs[key] = value
        for tr in rows[1:]:
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
            if len(cells) >= 2:
                pairs[cells[0]] = cells[1]
    branch_from_title, title_from_title = split_uljin_library_title(title)
    branch = branch_from_title or pairs.get("branch") or fallback_branch or "울진군통합도서관"
    title = title_from_title or title
    period = normalize_uljin_korean_date_range(pairs.get("일시") or pairs.get("기간") or pairs.get("행사일시"))
    description_parts = []
    for selector in (".webeditor", "#contents", "table"):
        node = soup.select_one(selector)
        if node:
            description_parts.append(uljin_text_with_image_alts(node))
    image = soup.find("img")
    image_url = normalize_link(detail_url, image.get("src")) if image and image.get("src") else ""
    return {
        "title": title,
        "branch": branch,
        "period": period,
        "schedule_raw": period,
        "venue_name": branch,
        "description": clean_text(" ".join(description_parts)),
        "image_url": image_url,
        "raw_fields": {"pairs": pairs, "parser": "uljin_library_calendar"},
    }


def collect_uljin_library_programs(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    discovered_links = 0
    seen_list_urls: set[str] = set()

    start_soup = fetch_soup(s, target.url, timeout=timeout)
    pages += 1
    parsed_target = urlparse(target.url)
    target_query = parse_qs(parsed_target.query)
    target_branch = clean_text(target.branch)
    if parsed_target.path.startswith("/content/02schedule"):
        calendar_urls: list[str] = []
        verified_calendar_pages = 0
        if target_query.get("p_cate"):
            calendar_urls.append(target.url)
        elif target_branch in ULJIN_LIBRARY_CALENDAR_CATEGORIES:
            calendar_urls.append(uljin_calendar_category_url(target.url, target_branch))
        else:
            for branch in ULJIN_LIBRARY_CALENDAR_CATEGORIES:
                calendar_urls.append(uljin_calendar_category_url(target.url, branch))
        for list_url in calendar_urls[: max(1, max_pages)]:
            soup = start_soup if list_url == target.url else fetch_soup(s, list_url, timeout=timeout)
            if list_url != target.url:
                pages += 1
            if is_uljin_library_calendar_page(soup):
                verified_calendar_pages += 1
            for link in soup.select('a[href*="proc_type=view"][href*="b_num="]'):
                title_text = clean_text(link.get_text(" ", strip=True))
                branch_from_title, clean_title = split_uljin_library_title(title_text)
                branch = branch_from_title or target_branch or "울진군통합도서관"
                if target_branch in ULJIN_LIBRARY_CALENDAR_CATEGORIES and branch_from_title and branch_from_title != target_branch:
                    continue
                if not clean_title or is_low_value_title(clean_title) or clean_title == "휴관일":
                    continue
                raw_url = normalize_link(list_url, link.get("href"))
                if not raw_url:
                    continue
                detail: dict[str, Any] = {}
                try:
                    detail = parse_uljin_library_calendar_detail(s, raw_url, timeout, fallback_branch=branch)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("Uljin library calendar detail fetch failed %s: %s", raw_url, exc)
                final_title = clean_text(detail.get("title")) or clean_title
                final_branch = clean_text(detail.get("branch")) or branch
                period = clean_text(detail.get("period"))
                row = {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, final_title, final_branch),
                    "title": final_title,
                    "branch": final_branch,
                    "category": "도서관행사",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": "안내",
                    "period": period,
                    "schedule_raw": clean_text(detail.get("schedule_raw")) or period,
                    "fee": "무료",
                    "venue_name": final_branch,
                    "description": clean_text(detail.get("description")) or title_text,
                    "image_url": clean_text(detail.get("image_url")),
                    "raw_fields": {
                        "list_url": list_url,
                        "list_text": title_text,
                        "parser": "uljin_library_calendar",
                        **(detail.get("raw_fields") or {}),
                    },
                }
                rows.append(row)
                discovered_links += 1
        collection_complete = bool(calendar_urls) and verified_calendar_pages == len(calendar_urls)
        no_current_data = collection_complete and not rows
        meta = {
            "pages": pages,
            "detail_pages": detail_pages,
            "discovered_links": discovered_links,
            "pagination_detected": False,
            "pagination_complete": collection_complete,
            "snapshot_complete": collection_complete,
            "collection_complete": collection_complete,
            "expected_calendar_pages": len(calendar_urls),
            "verified_calendar_pages": verified_calendar_pages,
            "no_current_data": no_current_data,
            "no_current_reason": "official branch calendar has no current events" if no_current_data else "",
            "recursion_depth": 0,
        }
        return dedupe_rows(rows), "uljin_library_calendar", meta

    list_urls: list[str] = []
    for link in start_soup.find_all("a", href=True):
        label = clean_text(link.get_text(" ", strip=True))
        href = link.get("href")
        if "sh_edu_lib=" in href and label in ULJIN_LIBRARY_BRANCHES:
            list_url = normalize_link(target.url, href)
            if list_url and list_url not in seen_list_urls:
                seen_list_urls.add(list_url)
                list_urls.append(list_url)
    canonical_course_url = normalize_link(
        target.url,
        f"/content/edusat/list.php?sh_edu_lib={quote('울진남부도서관')}",
    )
    if canonical_course_url and canonical_course_url not in seen_list_urls:
        seen_list_urls.add(canonical_course_url)
        list_urls.append(canonical_course_url)
    if target.url not in seen_list_urls:
        seen_list_urls.add(target.url)
        list_urls.insert(0, target.url)
    for extra_path in ("/content/edusat3/list.php", "/content/edusat4/list.php"):
        extra_url = normalize_link(target.url, extra_path)
        if extra_url and extra_url not in seen_list_urls:
            seen_list_urls.add(extra_url)
            list_urls.append(extra_url)

    for list_url in list_urls[: max(1, max_pages)]:
        soup = start_soup if list_url == target.url else fetch_soup(s, list_url, timeout=timeout)
        if list_url != target.url:
            pages += 1
        table = soup.select_one("table.edutable2") or soup.select_one("table")
        if not table:
            continue
        for tr in table.select("tbody tr"):
            cells = [cell for cell in tr.find_all("td")]
            if len(cells) < 2:
                continue
            row_text = clean_text(tr.get_text(" ", strip=True))
            if not row_text or "검색된" in row_text:
                continue
            title_link = next((a for a in cells[0].find_all("a", href=True) if "view.php" in a.get("href", "")), None)
            raw_title = clean_text(title_link.get_text(" ", strip=True) if title_link else cells[0].get_text(" ", strip=True))
            branch_from_title, clean_title = split_uljin_library_title(raw_title)
            if not clean_title or is_low_value_title(clean_title):
                continue
            raw_url = normalize_link(list_url, title_link.get("href")) if title_link else list_url
            method_parts = [
                clean_text(image.get("alt"))
                for image in (cells[2].find_all("img") if len(cells) > 2 else [])
                if clean_text(image.get("alt"))
            ]
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, clean_title, branch_from_title),
                "title": clean_title,
                "branch": branch_from_title or (target.branch if "?" not in clean_text(target.branch) else "울진군통합도서관") or "울진군통합도서관",
                "category": "도서관",
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": clean_text(cells[-1].get_text(" ", strip=True)),
                "fee": "",
                "period": "",
                "apply_period": normalize_month_day_range(cells[1].get_text(" ", strip=True)) if len(cells) > 1 else "",
                "schedule_raw": "",
                "target": "",
                "capacity": clean_text(cells[3].get_text(" ", strip=True)) if len(cells) > 3 else "",
                "application_method_raw": ", ".join(method_parts),
                "description": "",
                "raw_fields": {"list_url": list_url, "list_text": row_text, "parser": "uljin_library_edusat"},
            }
            if raw_url:
                try:
                    detail = parse_uljin_library_detail(s, raw_url, timeout)
                    detail_pages += 1
                    for key, value in detail.items():
                        if key == "raw_fields":
                            merged = dict(row.get("raw_fields") or {})
                            merged.update(value)
                            row[key] = merged
                        elif value:
                            row[key] = value
                except Exception as exc:
                    logger.debug("Uljin library detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
        discovered_links += len(table.find_all("a", href=True))

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": discovered_links,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "uljin_library_edusat", meta


def text_with_image_alts(node: Any) -> str:
    if not node:
        return ""
    clone = BeautifulSoup(str(node), "lxml")
    for image in clone.find_all("img"):
        alt = clean_text(image.get("alt"))
        if alt:
            image.replace_with(f" {alt} ")
    return clean_text(clone.get_text(" ", strip=True))


def gne_library_list_url(target_url: str, soup: BeautifulSoup) -> str:
    parsed = urlparse(target_url)
    if parsed.path.endswith("/usr_gne/lec_list.es"):
        return target_url
    preferred_tokens = (
        "\ud3c9\uc0dd\ud559\uc2b5\uc218\uac15\uc2e0\uccad",
        "\ud604\ud669 \ubc0f \uc2e0\uccad",
        "\uc628\ub77c\uc778\uac15\uc88c\uc2e0\uccad",
        "\uc218\uac15\uc2e0\uccad",
    )
    for link in soup.find_all("a", href=True):
        text = clean_text(link.get_text(" ", strip=True))
        href = normalize_link(target_url, link.get("href"))
        if not href:
            continue
        if any(token in text for token in preferred_tokens):
            return href
    return target_url


def gne_clean_title(value: str) -> str:
    title = clean_text(value)
    title = re.sub(r"\[(?:\uc77c\ud68c\uc131\ud2b9\uac15|\ubb34\ub8cc|\uc720\ub8cc)\]", " ", title)
    title = re.sub(r"\s+", " ", title)
    return clean_text(title)


def gne_extract_after_label(text: str, label: str, stop_labels: tuple[str, ...]) -> str:
    text = clean_text(text)
    if not text:
        return ""
    label_core = label.lstrip("\u318d")
    stop_pattern = "|".join(r"\u318d?\s*" + re.escape(stop.lstrip("\u318d")) + r"\s*:" for stop in stop_labels if stop != label)
    pattern = r"\u318d?\s*" + re.escape(label_core) + r"\s*:\s*(.*?)(?=" + stop_pattern + r"|$)"
    match = re.search(pattern, text)
    return clean_text(match.group(1)) if match else ""


def gne_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    labels = {
        "\uac15\uc88c\uba85",
        "\uad50\uc721\ub300\uc0c1",
        "\uc9c4\ud589\uc0c1\ud0dc",
        "\uac15\uc0ac",
        "\ucd08\ube59\uac15\uc0ac",
        "\ub2f4\ub2f9\uc790\uba85",
        "\ub2f4\ub2f9\uc790 \uc5f0\ub77d\ucc98",
        "\ubaa8\uc9d1\uae30\uac04",
        "\uad50\uc721\uae30\uac04",
        "\uc811\uc218\ubc29\ubc95",
        "\uad50\uc721\uc77c\uc2dc",
        "\ubaa8\uc9d1\uc778\uc6d0",
        "\uc628\ub77c\uc778\uc811\uc218",
        "\ud6c4\ubcf4",
        "\uac15\uc758\uc7a5\uc18c",
        "\uc7ac\ub8cc\ube44",
        "\uc218\uac15\ub8cc",
        "\uac15\uc758\uc18c\uac1c",
    }
    pairs: dict[str, str] = {}
    for row in soup.select("table.tstyle_view tr"):
        cells = row.find_all(["th", "td"])
        index = 0
        while index + 1 < len(cells):
            key = clean_text(text_with_image_alts(cells[index])).lstrip("*").replace("\n", " ")
            value = text_with_image_alts(cells[index + 1])
            if key in labels and value:
                pairs[key] = value
                index += 2
            else:
                index += 1
    return pairs


def collect_gne_library_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    start_soup = fetch_soup(s, target.url, timeout=timeout)
    list_url = gne_library_list_url(target.url, start_soup)
    if list_url != target.url:
        list_soup = fetch_soup(s, list_url, timeout=timeout)
        list_url = getattr(list_soup, "_feed", None) and list_url or list_url
    else:
        list_soup = start_soup
    if not urlparse(list_url).path.endswith("/usr_gne/lec_list.es") and urlparse(list_url).path.endswith("/menu.es"):
        response = s.get(list_url, timeout=timeout, verify=True)
        response.raise_for_status()
        list_url = response.url
        list_soup = BeautifulSoup(response.text, "lxml")

    parsed = urlparse(list_url)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    stop_labels = ("\ubaa8\uc9d1\uae30\uac04", "\ud559\uc2b5\uae30\uac04", "\uad50\uc721\uc694\uc77c/\uc2dc\uac04")

    for page in range(1, max_pages + 1):
        query = parse_qs(parsed.query)
        query["page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = list_soup if page == 1 else fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table.tstyle_list tbody tr"):
            cells = tr.find_all("td", recursive=False)
            if len(cells) < 6:
                continue
            category = clean_text(cells[0].get_text(" ", strip=True))
            title_cell = cells[1]
            link = title_cell.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            title_text = text_with_image_alts(title_cell)
            title_text = re.split(r"\s*\u318d\ubaa8\uc9d1\uae30\uac04\s*:", title_text, maxsplit=1)[0]
            title = gne_clean_title(title_text)
            if not title or is_low_value_title(title):
                continue
            detail_text = text_with_image_alts(title_cell)
            apply_period = gne_extract_after_label(detail_text, "\u318d\ubaa8\uc9d1\uae30\uac04", stop_labels)
            period = gne_extract_after_label(detail_text, "\u318d\ud559\uc2b5\uae30\uac04", stop_labels)
            schedule = gne_extract_after_label(detail_text, "\u318d\uad50\uc721\uc694\uc77c/\uc2dc\uac04", stop_labels)
            status = ""
            status_image = cells[5].find("img")
            if status_image:
                status = clean_text(status_image.get("alt"))
            if not status:
                status = clean_text(cells[5].get_text(" ", strip=True)).replace("\uc0c1\uc138\ubcf4\uae30", "")
            method = ", ".join(
                clean_text(image.get("alt"))
                for image in cells[4].find_all("img")
                if clean_text(image.get("alt"))
            )
            fee = "\ubb34\ub8cc" if "\ubb34\ub8cc" in text_with_image_alts(title_cell) else ""
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url if status and "\ubaa8\uc9d1" in status else "",
                "status": status,
                "fee": fee,
                "period": period,
                "apply_period": apply_period,
                "schedule_raw": schedule,
                "target": "",
                "capacity": text_with_image_alts(cells[3]),
                "application_method_raw": method,
                "description": "",
                "raw_fields": {"parser": "gne_library_lec_list", "list_text": detail_text},
            }
            if detail_pages < detail_limit and raw_url:
                try:
                    s.headers.update({"Referer": current_url})
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    pairs = gne_detail_pairs(detail_soup)
                    detail = {
                        "title": gne_clean_title(pairs.get("\uac15\uc88c\uba85", "")),
                        "target": pairs.get("\uad50\uc721\ub300\uc0c1", ""),
                        "status": pairs.get("\uc9c4\ud589\uc0c1\ud0dc", ""),
                        "instructor": pairs.get("\ucd08\ube59\uac15\uc0ac") or pairs.get("\uac15\uc0ac", ""),
                        "apply_period": pairs.get("\ubaa8\uc9d1\uae30\uac04", ""),
                        "period": pairs.get("\uad50\uc721\uae30\uac04", ""),
                        "schedule_raw": pairs.get("\uad50\uc721\uc77c\uc2dc", ""),
                        "capacity": pairs.get("\ubaa8\uc9d1\uc778\uc6d0", "") or row["capacity"],
                        "venue_name": pairs.get("\uac15\uc758\uc7a5\uc18c", ""),
                        "material_fee": pairs.get("\uc7ac\ub8cc\ube44", ""),
                        "fee": pairs.get("\uc218\uac15\ub8cc", ""),
                        "description": pairs.get("\uac15\uc758\uc18c\uac1c", ""),
                        "raw_detail_pairs": pairs,
                    }
                    row = merge_course_rows(row, detail)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("gne detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": bool(rows) and pages >= max_pages,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gne_library_lec_list", meta


def jne_branch_from_title(soup: BeautifulSoup, fallback: str) -> str:
    title = clean_text(soup.title.get_text(" ", strip=True)) if soup.title else ""
    if ":" in title:
        branch = clean_text(title.rsplit(":", 1)[-1])
        if branch:
            return branch
    return fallback


def collect_jne_library_lecture(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    target_mid = clean_text((base_query.get("mid") or [""])[0])
    target_netloc = parsed.netloc.lower()
    target_path = parsed.path.rstrip("/") or "/"
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    branch = target.branch
    no_current_data = False
    out_of_scope_links = 0
    pagination_exhausted = False

    def in_target_menu_scope(candidate_url: str) -> bool:
        candidate = urlparse(candidate_url)
        if candidate.netloc.lower() != target_netloc:
            return False
        if (candidate.path.rstrip("/") or "/") != target_path:
            return False
        candidate_mid = clean_text((parse_qs(candidate.query).get("mid") or [""])[0])
        return not target_mid or candidate_mid == target_mid

    for page in range(1, max_pages + 1):
        query = {key: list(values) for key, values in base_query.items()}
        query["nPage"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        page_text = clean_text(soup.get_text(" ", strip=True))
        no_current_data = no_current_data or "등록된 자료가 존재하지 않습니다" in page_text
        if page == 1:
            branch = jne_branch_from_title(soup, target.branch)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["td", "th"])]
            if len(cells) < 7 or cells[0] in {"번호", ""} or not re.fullmatch(r"\d+", cells[0] or ""):
                continue
            link = tr.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            if not in_target_menu_scope(raw_url):
                out_of_scope_links += 1
                continue
            offset = 1 if len(cells) >= 8 and not cells[1] else 0
            title = cells[1 + offset]
            target_text = cells[2 + offset] if len(cells) > 2 + offset else ""
            raw_period = cells[3 + offset] if len(cells) > 3 + offset else ""
            apply_period = cells[4 + offset] if len(cells) > 4 + offset else ""
            capacity = cells[5 + offset] if len(cells) > 5 + offset else ""
            status = cells[6 + offset] if len(cells) > 6 + offset else ""
            period, schedule = split_period_and_schedule(raw_period)
            capacity_current, capacity_total = parse_capacity_pair(capacity)
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": "\ub3c4\uc11c\uad00",
                    "venue_name": branch,
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "\ubb34\ub8cc",
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule or raw_period,
                    "target": target_text or "\ubcc4\ub3c4 \uc548\ub0b4",
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "description": clean_text(" ".join(cells[1 + offset : 7 + offset])),
                    "raw_fields": {"cells": cells, "parser": "jne_library_lecture_table"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='nPage=']"))
        if page_rows == 0:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "pagination_detected": pagination_detected,
        "pagination_exhausted": pagination_exhausted,
        "recursion_depth": 0,
        "no_current_data": no_current_data and not rows,
        "no_current_reason": "no_current_jne_library_lectures" if no_current_data and not rows else "",
        "out_of_scope_links": out_of_scope_links,
    }
    return dedupe_rows(rows), "jne_library_lecture_table", meta


def collect_jne_library_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    pagination_exhausted = False
    branch = target.branch
    no_current_data = False

    for page in range(1, max_pages + 1):
        query = parse_qs(parsed.query)
        query["nPage"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        page_text = clean_text(soup.get_text(" ", strip=True))
        no_current_data = no_current_data or "등록된 자료가 존재하지 않습니다" in page_text
        if page == 1:
            branch = jne_branch_from_title(soup, target.branch)
        pages += 1
        page_rows = 0

        for tr in soup.select("table tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["td", "th"])]
            if len(cells) < 6 or not re.fullmatch(r"\d+", cells[0] or ""):
                continue
            link = tr.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            title = cells[1]
            apply_period = cells[2]
            period = cells[3]
            capacity = cells[4]
            status = cells[5]
            capacity_current, capacity_total = parse_capacity_pair(capacity)
            wait_current = None
            wait_total = None
            wait_match = re.search(r"\(\s*(\d{1,5})\s*/\s*(\d{1,5})\s*\)", capacity.replace(",", ""))
            if wait_match:
                wait_current = int(wait_match.group(1))
                wait_total = int(wait_match.group(2))

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": "\ub3c5\uc11c\ubb38\ud654\ud589\uc0ac",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "\ubb34\ub8cc",
                    "period": period,
                    "schedule_raw": period,
                    "apply_period": apply_period,
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "waitlist_current": wait_current,
                    "waitlist_total": wait_total,
                    "description": clean_text(" ".join(cells[1:6])),
                    "raw_fields": {"cells": cells, "parser": "jne_library_education_table"},
                }
            )
            page_rows += 1

        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='nPage=']"))
        if page_rows == 0:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "pagination_detected": pagination_detected,
        "pagination_exhausted": pagination_exhausted,
        "recursion_depth": 0,
        "no_current_data": no_current_data and not rows,
        "no_current_reason": "no_current_jne_library_lectures" if no_current_data and not rows else "",
    }
    return dedupe_rows(rows), "jne_library_education_table", meta


def collect_jne_experiences_by_branch(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    # An empty institution filter is intentional: every reservation institution
    # is returned and each row carries its own branch id and institution name.
    base_query["srchRsSysId"] = [""]
    base_query["srchAt"] = ["Y"]
    base_query["pageIndex"] = [clean_text((base_query.get("pageIndex") or ["10"])[0]) or "10"]
    rows: list[dict[str, Any]] = []
    pages = 0
    branch_counts: dict[str, int] = {}
    pagination_exhausted = False

    for page in range(1, max_pages + 1):
        query = {key: list(values) for key, values in base_query.items()}
        query["currPage"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0

        for tr in soup.select("table tbody tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td", recursive=False)]
            link = tr.select_one("a.viewExprnInfo[data-id][data-period-id][data-rssysid]")
            if len(cells) < 8 or not link:
                continue
            exprn_seq = clean_text(link.get("data-id"))
            period_seq = clean_text(link.get("data-period-id"))
            branch_code = clean_text(link.get("data-rssysid"))
            branch = cells[1] or target.branch
            if "테스트" in branch:
                continue
            title = clean_text(link.get_text(" ", strip=True))
            subtitle = clean_text((tr.select_one("td.tdW100.al p") or {}).get_text(" ", strip=True) if tr.select_one("td.tdW100.al p") else "")
            detail_query = {key: list(values) for key, values in query.items()}
            detail_query["exprnSeq"] = [exprn_seq]
            detail_query["exprnPeriodSeq"] = [period_seq]
            detail_query["srchRsSysId"] = [branch_code]
            detail_path = "/yeyak/exprn/nrmr/selectExprnSproutInfo.do" if exprn_seq == "66" else "/yeyak/exprn/selectExprnInfo.do"
            raw_url = parsed._replace(path=detail_path, query=urlencode(detail_query, doseq=True)).geturl()
            period = normalize_mixed_date_range(cells[3])
            apply_period = normalize_mixed_date_range(cells[4])
            status = cells[7]
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch_code),
                    "title": title,
                    "branch": branch,
                    "branch_code": branch_code,
                    "category": "견학체험",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "별도 안내",
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": "시간 별도 안내",
                    "target": cells[5],
                    "venue_name": branch,
                    "address": branch,
                    "application_method_raw": cells[6],
                    "description": clean_text(" ".join(part for part in [subtitle, *cells[3:8]] if part)),
                    "reservation_available": "접수중" in status,
                    "raw_fields": {
                        "exprn_seq": exprn_seq,
                        "exprn_period_seq": period_seq,
                        "branch_code": branch_code,
                        "cells": cells,
                        "parser": "jne_experience_branch_table",
                    },
                }
            )
            branch_counts[branch] = branch_counts.get(branch, 0) + 1
            page_rows += 1
        if page_rows == 0:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "pagination_detected": pages > 1,
        "pagination_exhausted": pagination_exhausted,
        "pagination_complete": pagination_exhausted,
        "source_cap_reached": not pagination_exhausted,
        "recursion_depth": 0,
        "branch_counts": branch_counts,
        "no_current_data": pagination_exhausted and not rows,
        "no_current_reason": (
            "official education experience list has no current programs"
            if pagination_exhausted and not rows
            else ""
        ),
    }
    return dedupe_rows(rows), "jne_experience_branch_table", meta


