def is_goyang_education_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query, keep_blank_values=True)
    return bool(
        target.provider == GOYANG_EDUCATION_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == GOYANG_EDUCATION_HOST
        and parsed.path == GOYANG_EDUCATION_LIST_PATH
        and query.get("q_resveTopClCode") == ["CL_01"]
        and not parsed.fragment
    )


def goyang_education_list_url(district_code: str, status_code: str, page: int) -> str:
    if district_code and district_code not in GOYANG_EDUCATION_DISTRICTS:
        return ""
    if status_code not in GOYANG_EDUCATION_STATUS_FILTERS or page < 1:
        return ""
    query: dict[str, str] = {
        "q_resveTopClCode": "CL_01",
        "q_resveSttusCode": status_code,
        "q_rowPerPage": str(GOYANG_EDUCATION_PAGE_SIZE),
        "q_currPage": str(page),
    }
    if district_code:
        query["q_guDeptCode"] = district_code
        query["q_dongDeptCode"] = "ALL"
    return f"https://{GOYANG_EDUCATION_HOST}{GOYANG_EDUCATION_LIST_PATH}?{urlencode(query)}"


def goyang_education_branch_url(district_code: str) -> str:
    if district_code not in GOYANG_EDUCATION_DISTRICTS:
        return GOYANG_EDUCATION_LIST_URL
    query = {
        "q_resveTopClCode": "CL_01",
        "q_guDeptCode": district_code,
        "q_dongDeptCode": "ALL",
    }
    return f"https://{GOYANG_EDUCATION_HOST}{GOYANG_EDUCATION_LIST_PATH}?{urlencode(query)}"


def goyang_education_detail_url(reservation_id: str) -> str:
    value = clean_text(reservation_id)
    if not re.fullmatch(r"\d{1,20}", value):
        return ""
    query = urlencode({"q_resveTopClCode": "CL_01", "resveSn": value})
    return f"https://{GOYANG_EDUCATION_HOST}{GOYANG_EDUCATION_DETAIL_PATH}?{query}"


def goyang_education_declared_total(soup: BeautifulSoup) -> Optional[int]:
    node = soup.select_one(".bbs-total strong")
    value = clean_text(node.get_text(" ", strip=True) if node else "").replace(",", "")
    return int(value) if value.isdigit() else None


def goyang_education_reservation_id(anchor: Any) -> str:
    match = re.search(r"opResveView\(\s*(\d{1,20})", clean_text(anchor.get("onclick")))
    return match.group(1) if match else ""


def goyang_education_card_row(
    target: CrawlTarget,
    anchor: Any,
    district_code: str,
    status_code: str,
) -> Optional[dict[str, Any]]:
    reservation_id = goyang_education_reservation_id(anchor)
    title_node = anchor.select_one(".subject_tit")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    if not reservation_id or not title or is_low_value_title(title):
        return None

    district = GOYANG_EDUCATION_DISTRICTS[district_code]
    place_node = anchor.select_one(".list_type02 > span")
    place = clean_text(place_node.get_text(" ", strip=True) if place_node else "")
    status = clean_text((anchor.select_one(".list_type01") or anchor).get_text(" ", strip=True))
    target_text = clean_text((anchor.select_one(".list_type03") or anchor).get_text(" ", strip=True))
    period_text = clean_text((anchor.select_one(".list_type04") or anchor).get_text(" ", strip=True))
    apply_match = re.search(r"신청\s*:\s*(.+?)(?=교육\s*:|$)", period_text)
    course_match = re.search(r"교육\s*:\s*(.+)$", period_text)
    apply_raw = clean_text(apply_match.group(1) if apply_match else "")
    period_raw = clean_text(course_match.group(1) if course_match else period_text)
    capacity_text = clean_text((anchor.select_one(".list_type05") or anchor).get_text(" ", strip=True))
    capacity_match = re.search(r"([\d,]+)", capacity_text)
    capacity_total = int(capacity_match.group(1).replace(",", "")) if capacity_match else None
    selection_fee = clean_text((anchor.select_one(".list_type06") or anchor).get_text(" ", strip=True))
    fee = "무료" if "무료" in selection_fee else clean_text(selection_fee.split()[-1] if selection_fee else "")
    method = clean_text((anchor.select_one(".list_type07") or anchor).get_text(" ", strip=True))
    raw_url = goyang_education_detail_url(reservation_id)
    row: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": reservation_id,
        "title": title,
        "branch": district["branch"],
        "branch_code": district["branch_code"],
        "preserve_branch": True,
        "branch_url": goyang_education_branch_url(district_code),
        "category": "교육·강좌",
        "category_raw": "교육·강좌",
        "collection_category": "공공예약",
        "domain_category": "교육·강좌",
        "program_type": "교육",
        "source_group": "municipal_reservation",
        "operator_type": "지자체/공공기관",
        "service_group": "공공강좌",
        "service_group_policy": "locked",
        "raw_url": raw_url,
        "status": status,
        "period": normalize_mixed_date_range(period_raw),
        "apply_period": normalize_mixed_date_range(apply_raw),
        "schedule_raw": period_raw,
        "target": target_text,
        "room": place,
        "venue_name": place,
        "fee": fee,
        "capacity": capacity_total,
        "capacity_total": capacity_total,
        "application_method_raw": method,
        "reservation_available": False,
        "municipality_code": district["municipality_code"],
        "municipality_full_name": district["municipality_full_name"],
        "description": clean_text(" ".join([period_text, target_text, place, selection_fee, method]))[:2000],
        "raw_fields": {
            "reservation_id": reservation_id,
            "status_filter": status_code,
            "district_filter": district_code,
            "district_name": district["name"],
            "selection_fee": selection_fee,
            "list_status": status,
            "parser": GOYANG_EDUCATION_PARSER,
            "clear_application_url": True,
        },
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}


def goyang_education_capacity(value: str) -> tuple[Optional[int], Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    combined = re.search(r"(\d{1,6})\s*명?\s*/\s*(\d{1,6})\s*명", text)
    recruited = re.search(r"모집정원\s*(\d{1,6})\s*명", text)
    waiting = re.search(r"대기자\s*정원\s*(\d{1,6})\s*명", text)
    combined_current = int(combined.group(1)) if combined else None
    combined_total = int(combined.group(2)) if combined else None
    capacity_total = int(recruited.group(1)) if recruited else combined_total
    waitlist_total = int(waiting.group(1)) if waiting else None
    capacity_current = None
    waitlist_current = None
    if combined_current is not None:
        if capacity_total is None:
            capacity_current = combined_current
        else:
            capacity_current = min(combined_current, capacity_total)
            waitlist_current = max(0, combined_current - capacity_total)
    return capacity_current, capacity_total, waitlist_current, waitlist_total


def goyang_education_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    table = next(
        (
            candidate
            for candidate in soup.select("table")
            if "모집정원" in clean_text(candidate.get_text(" ", strip=True))
            and "신청기간" in clean_text(candidate.get_text(" ", strip=True))
        ),
        None,
    )
    return pairs_from_tables(table) if table is not None else {}


def goyang_education_enrich_detail(row: dict[str, Any], soup: BeautifulSoup) -> bool:
    reservation_id = clean_text((row.get("raw_fields") or {}).get("reservation_id"))
    identity_node = soup.select_one("input[name='resveSn']")
    if clean_text(identity_node.get("value") if identity_node else "") != reservation_id:
        return False
    pairs = goyang_education_detail_pairs(soup)
    if not pairs:
        return False

    category_node = soup.select_one("h4.h4-title")
    category_path = clean_text(category_node.get_text(" ", strip=True) if category_node else "")
    category = clean_text(category_path.split(">")[-1]) if category_path else ""
    period_raw = clean_text(
        pairs.get("교육.강좌 일시")
        or pairs.get("교육·강좌 일시")
        or pairs.get("교육ㆍ강좌 일시")
        or pairs.get("일시")
    )
    apply_raw = clean_text(pairs.get("신청기간"))
    venue = clean_text(pairs.get("장소"))
    target_text = clean_text(pairs.get("이용대상"))
    age_limit = clean_text(pairs.get("연령제한"))
    fee = clean_text(pairs.get("이용료"))
    method = clean_text(pairs.get("신청방법"))
    selection = clean_text(pairs.get("선별방법"))
    contact = clean_text(pairs.get("담당자"))
    phone_match = re.search(r"0\d{1,2}-\d{3,4}-\d{4}", contact)
    capacity_current, capacity_total, waitlist_current, waitlist_total = goyang_education_capacity(
        pairs.get("모집정원", "")
    )

    values = {
        "category": category,
        "category_raw": category_path,
        "period": normalize_mixed_date_range(period_raw),
        "apply_period": normalize_mixed_date_range(apply_raw),
        "schedule_raw": period_raw,
        "venue_name": venue,
        "room": venue,
        "target": target_text,
        "eligibility_raw": clean_text(" ".join(part for part in [target_text, age_limit] if part)),
        "fee": fee,
        "application_method_raw": clean_text(" ".join(part for part in [method, selection] if part)),
        "phone": phone_match.group(0) if phone_match else "",
        "capacity": capacity_total,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_current": waitlist_current,
        "waitlist_total": waitlist_total,
    }
    for key, value in values.items():
        if value not in (None, ""):
            row[key] = value

    attachment_urls = [
        urljoin(clean_text(row.get("raw_url")), clean_text(link.get("href")))
        for link in soup.select("a[href]")
        if "첨부" in clean_text(link.get_text(" ", strip=True))
        or re.search(r"\.(?:hwp|hwpx|pdf|docx?|xlsx?|zip)(?:$|\?)", clean_text(link.get("href")), re.IGNORECASE)
    ]
    detail_button = soup.select_one("button[onclick*='opResveReqst'], a[onclick*='opResveReqst']") is not None
    can_apply = clean_text((row.get("raw_fields") or {}).get("status_filter")) == "1002" and detail_button
    row["reservation_available"] = can_apply
    raw_fields = row.setdefault("raw_fields", {})
    raw_fields["detail_pairs"] = pairs
    raw_fields["detail_category_path"] = category_path
    raw_fields["detail_application_button"] = detail_button
    raw_fields["attachment_urls"] = list(dict.fromkeys(url for url in attachment_urls if url))
    raw_fields["clear_application_url"] = not can_apply
    if can_apply:
        row["application_url"] = row.get("raw_url")
        row["application_type"] = "ONLINE_RESERVATION"
    else:
        row.pop("application_url", None)
    row["description"] = clean_text(" ".join(str(value) for value in pairs.values()))[:2000]
    return True


def collect_goyang_education_reservations(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 30,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if not is_goyang_education_target(target):
        raise ValueError("Goyang education target must use the canonical owned official HTTPS CL_01 route")
    s = session()
    pages = 0
    detail_pages = 0
    detail_errors = 0
    pagination_detected = False
    source_cap_reached = False
    errors: list[str] = []

    def fetch_scope(district_code: str, status_code: str, *, build_rows: bool) -> dict[str, Any]:
        nonlocal pages, pagination_detected, source_cap_reached
        scope_name = f"district={district_code or 'all'} status={status_code}"
        identities: set[str] = set()
        scope_rows: list[dict[str, Any]] = []
        scope_errors: list[str] = []
        declared_total: Optional[int] = None
        expected_pages = 1
        page = 1
        while page <= expected_pages:
            if pages >= max_pages:
                source_cap_reached = True
                scope_errors.append(f"max_pages cap reached before {scope_name} page {page}")
                break
            current_url = goyang_education_list_url(district_code, status_code, page)
            try:
                soup = fetch_soup(s, current_url, timeout=timeout)
            except Exception as exc:
                logger.warning(
                    "Goyang education list fetch failed scope=%s page=%s error_type=%s",
                    scope_name,
                    page,
                    type(exc).__name__,
                )
                scope_errors.append(f"{scope_name} page {page} fetch failed ({type(exc).__name__})")
                break
            pages += 1
            page_total = goyang_education_declared_total(soup)
            if page_total is None:
                scope_errors.append(f"{scope_name} page {page} omitted the official total count")
                break
            page_expected = max(1, (page_total + GOYANG_EDUCATION_PAGE_SIZE - 1) // GOYANG_EDUCATION_PAGE_SIZE)
            if declared_total is None:
                declared_total = page_total
                expected_pages = page_expected
                pagination_detected = pagination_detected or expected_pages > 1
            elif page_total != declared_total or page_expected != expected_pages:
                scope_errors.append(
                    f"{scope_name} page {page} changed declaration from "
                    f"{declared_total}/{expected_pages} to {page_total}/{page_expected}"
                )
                break

            for anchor in soup.select("li > a[onclick*='opResveView']"):
                reservation_id = goyang_education_reservation_id(anchor)
                if not reservation_id:
                    scope_errors.append(f"{scope_name} page {page} contained a card without a reservation id")
                    continue
                if reservation_id in identities:
                    scope_errors.append(f"{scope_name} duplicated reservation id {reservation_id}")
                    continue
                identities.add(reservation_id)
                actual_status = clean_text((anchor.select_one(".list_type01") or anchor).get_text(" ", strip=True))
                if actual_status != GOYANG_EDUCATION_STATUS_FILTERS[status_code]:
                    scope_errors.append(
                        f"{scope_name} returned reservation {reservation_id} with unexpected status {actual_status or 'missing'}"
                    )
                    continue
                if build_rows:
                    row = goyang_education_card_row(target, anchor, district_code, status_code)
                    if row is None:
                        scope_errors.append(f"{scope_name} could not parse reservation {reservation_id}")
                        continue
                    scope_rows.append(row)
            page += 1

        if declared_total is not None and len(identities) != declared_total:
            scope_errors.append(f"{scope_name} parsed {len(identities)} of {declared_total} declared cards")
        return {
            "identities": identities,
            "rows": scope_rows,
            "declared_total": declared_total,
            "errors": scope_errors,
        }

    rows_by_id: dict[str, dict[str, Any]] = {}
    district_membership: dict[str, str] = {}
    district_status_ids: dict[str, set[str]] = {}
    district_counts: dict[str, int] = {code: 0 for code in GOYANG_EDUCATION_DISTRICTS}
    status_counts: dict[str, int] = {code: 0 for code in GOYANG_EDUCATION_STATUS_FILTERS}
    duplicate_count = 0
    for district_code in GOYANG_EDUCATION_DISTRICTS:
        for status_code in GOYANG_EDUCATION_STATUS_FILTERS:
            result = fetch_scope(district_code, status_code, build_rows=True)
            errors.extend(result["errors"])
            district_status_ids.setdefault(status_code, set()).update(result["identities"])
            for row in result["rows"]:
                reservation_id = clean_text(row.get("provider_course_id"))
                previous_district = district_membership.get(reservation_id)
                if previous_district:
                    duplicate_count += 1
                    errors.append(
                        f"reservation {reservation_id} appeared in both district={previous_district} and district={district_code}"
                    )
                    continue
                district_membership[reservation_id] = district_code
                rows_by_id[reservation_id] = row
                district_counts[district_code] += 1
                status_counts[status_code] += 1

    global_status_ids: dict[str, set[str]] = {}
    global_union_matches = True
    for status_code in GOYANG_EDUCATION_STATUS_FILTERS:
        result = fetch_scope("", status_code, build_rows=False)
        errors.extend(result["errors"])
        global_status_ids[status_code] = set(result["identities"])
        district_ids = district_status_ids.get(status_code, set())
        if global_status_ids[status_code] != district_ids:
            global_union_matches = False
            missing = sorted(global_status_ids[status_code] - district_ids, key=lambda value: int(value))
            extra = sorted(district_ids - global_status_ids[status_code], key=lambda value: int(value))
            errors.append(
                f"district union did not match global status={status_code} set "
                f"(missing={missing[:10]}, extra={extra[:10]})"
            )

    rows = list(rows_by_id.values())
    list_complete = not errors and global_union_matches
    detail_enrichment_capped = False
    if list_complete and rows:
        if detail_limit < len(rows):
            detail_enrichment_capped = True
            errors.append(f"detail enrichment capped at {max(0, detail_limit)} of {len(rows)}")
        for row in rows[: max(0, detail_limit)]:
            detail_pages += 1
            try:
                detail_soup = fetch_soup(s, clean_text(row.get("raw_url")), timeout=timeout)
                if not goyang_education_enrich_detail(row, detail_soup):
                    detail_errors += 1
                    errors.append(
                        f"detail parse failed for reservation {(row.get('raw_fields') or {}).get('reservation_id')}"
                    )
            except Exception as exc:
                detail_errors += 1
                logger.debug(
                    "Goyang education detail fetch failed reservation_id=%s error_type=%s",
                    (row.get("raw_fields") or {}).get("reservation_id"),
                    type(exc).__name__,
                )
                errors.append(
                    f"detail fetch failed for reservation {(row.get('raw_fields') or {}).get('reservation_id')} "
                    f"({type(exc).__name__})"
                )

    errors = list(dict.fromkeys(error for error in errors if error))
    complete = not errors and global_union_matches
    meta: dict[str, Any] = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_pages,
        "detail_errors": detail_errors,
        "detail_enrichment_capped": detail_enrichment_capped,
        "discovered_links": len(rows_by_id),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "pagination_detected": pagination_detected,
        "pagination_complete": complete,
        "list_pagination_complete": list_complete,
        "source_cap_reached": source_cap_reached,
        "global_union_matches": global_union_matches,
        "district_counts": district_counts,
        "status_counts": status_counts,
        "global_status_counts": {code: len(values) for code, values in global_status_ids.items()},
        "duplicate_count": duplicate_count,
        "terminal_status_excluded": "1005",
        "no_current_data": complete and not rows,
        "no_current_reason": "official current status scopes are empty" if complete and not rows else "",
        "recursion_depth": 0,
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(errors)
    return dedupe_rows(rows), GOYANG_EDUCATION_PARSER, meta


def collect_suwon_reservation_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    base_query["q_rowPerPage"] = ["100"]
    rows: list[dict[str, Any]] = []
    pages = 0
    status_counts: dict[str, int] = {}
    pagination_exhausted = True

    # 72=접수중, 73=접수준비. Closed historical rows exceed twenty thousand,
    # so current/future education is deliberately collected from these scopes.
    for status_code in ("72", "73"):
        status_rows = 0
        page = 1
        while pages < max_pages:
            query = {key: list(values) for key, values in base_query.items()}
            query["q_progressStatusCd"] = [status_code]
            query["q_currPage"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
            soup = fetch_soup(s, current_url, timeout=timeout)
            pages += 1
            page_rows = 0
            for tr in soup.select("table tbody tr"):
                cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td", recursive=False)]
                link = tr.select_one("a.title[href*='/reserv/edu/view.do']")
                if len(cells) < 8 or not link:
                    continue
                title = clean_text(link.get_text(" ", strip=True))
                raw_url = normalize_link(current_url, link.get("href")) or current_url
                period_parts = [clean_text(value) for value in tr.find_all("td", recursive=False)[2].stripped_strings]
                apply_period = normalize_mixed_date_range(period_parts[0] if period_parts else "")
                period = normalize_mixed_date_range(period_parts[1] if len(period_parts) > 1 else "")
                schedule_raw = clean_text(cells[3])
                capacity_current, capacity_total = parse_capacity_pair(cells[5])
                wait_match = re.search(r"\(\s*([\d,]+)\s*/\s*([\d,]+)\s*\)", cells[5])
                venue = cells[6]
                branch = target.branch
                branch_code = "SUWON_RESERV_EDUCATION"
                status = cells[7]
                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch_code),
                        "title": title,
                        "branch": branch,
                        "branch_code": branch_code,
                        "category": "교육",
                        "collection_category": "교육",
                        "domain_category": "교육",
                        "program_type": "교육",
                        "source_group": "public_reservation",
                        "raw_url": raw_url,
                        "application_url": raw_url,
                        "status": status,
                        "period": period,
                        "apply_period": apply_period,
                        "schedule_raw": schedule_raw or period,
                        "target": cells[4],
                        "room": venue,
                        "venue_name": venue,
                        "fee": "별도 안내",
                        "capacity_current": capacity_current,
                        "capacity_total": capacity_total,
                        "waitlist_current": int(wait_match.group(1).replace(",", "")) if wait_match else None,
                        "waitlist_total": int(wait_match.group(2).replace(",", "")) if wait_match else None,
                        "reservation_available": "접수중" in status,
                        "description": clean_text(" ".join(cells[2:8])),
                        "raw_fields": {"cells": cells, "status_code": status_code, "parser": "suwon_reservation_education_table"},
                    }
                )
                page_rows += 1
                status_rows += 1
            if page_rows == 0 or page_rows < 100:
                break
            page += 1
        else:
            pagination_exhausted = False
        status_counts[status_code] = status_rows

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "pagination_detected": pages > 2,
        "pagination_exhausted": pagination_exhausted,
        "recursion_depth": 0,
        "status_counts": status_counts,
    }
    return dedupe_rows(rows), "suwon_reservation_education_table", meta


def chuncheon_e_types(url: str) -> list[str]:
    query = parse_qs(urlparse(url).query)
    e_type = clean_text((query.get("e_type") or [""])[0])
    return [e_type] if e_type else ["jung", "dan", "etc"]


def post_soup(s: requests.Session, url: str, data: dict[str, Any], timeout: int) -> BeautifulSoup:
    response = s.post(url, data=data, timeout=timeout, verify=True)
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    return BeautifulSoup(response.text, "lxml")


def collect_chuncheon_lifelong(target: CrawlTarget, timeout: int, max_pages: int, detail_limit: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    root_url = "https://clc.chuncheon.go.kr"
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    for e_type in chuncheon_e_types(target.url):
        gisu_url = f"{root_url}/site/edu/edu_gisu_list.do?e_type={e_type}"
        soup = fetch_soup(s, gisu_url, timeout=timeout)
        pages += 1
        gisu_rows: list[dict[str, str]] = []
        for tr in soup.select("table.tbl_bbs tbody tr"):
            cells = tr.find_all("td", recursive=False)
            if len(cells) < 4:
                continue
            link = cells[0].find("a")
            onclick = clean_text(link.get("onclick") if link else "")
            match = re.search(r"fn_classList\('([^']+)'\)", onclick)
            gisu_id = match.group(1) if match else ""
            if not gisu_id:
                continue
            gisu_rows.append(
                {
                    "gisu_id": gisu_id,
                    "gisu_name": clean_text(cells[0].get_text(" ", strip=True)),
                    "apply_period": text_with_image_alts(cells[1]),
                    "period": text_with_image_alts(cells[2]),
                    "status": text_with_image_alts(cells[3]),
                }
            )
        for gisu in gisu_rows[:max_pages]:
            list_soup = post_soup(
                s,
                f"{root_url}/site/edu/edu_class_list.do",
                {"e_type": e_type, "yy": gisu["gisu_id"]},
                timeout,
            )
            pages += 1
            for tr in list_soup.select("table.tbl_bbs tbody tr"):
                cells = tr.find_all("td", recursive=False)
                if len(cells) < 6:
                    continue
                title_link = cells[1].find("a")
                title = clean_text(title_link.get_text(" ", strip=True) if title_link else cells[1].get_text(" ", strip=True))
                if not title or is_low_value_title(title):
                    continue
                onclick = clean_text(title_link.get("onclick") if title_link else "")
                match = re.search(r"fn_classView\('([^']+)'\)", onclick)
                class_no = match.group(1) if match else stable_course_id(target.provider, gisu["gisu_id"], title, target.branch)
                raw_url = f"{root_url}/site/edu/edu_class_view.do?e_type={e_type}&yy={gisu['gisu_id']}&class_no={class_no}"
                method = clean_text((cells[1].select_one(".label") or {}).get_text(" ", strip=True) if cells[1].select_one(".label") else "")
                row = {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, f"{gisu['gisu_id']}:{class_no}", title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": clean_text(cells[0].get_text(" ", strip=True)),
                    "raw_url": raw_url,
                    "application_url": raw_url if "\uc2e0\uccad" in text_with_image_alts(cells[5]) and "\ub9c8\uac10" not in text_with_image_alts(cells[5]) else "",
                    "status": text_with_image_alts(cells[5]),
                    "fee": "",
                    "period": gisu["period"],
                    "apply_period": gisu["apply_period"],
                    "schedule_raw": text_with_image_alts(cells[2]),
                    "target": text_with_image_alts(cells[3]),
                    "capacity": text_with_image_alts(cells[4]),
                    "application_method_raw": method,
                    "description": "",
                    "raw_fields": {"parser": "chuncheon_lifelong", "e_type": e_type, "gisu": gisu, "class_no": class_no},
                }
                if detail_pages < detail_limit and class_no:
                    try:
                        detail_soup = post_soup(
                            s,
                            f"{root_url}/site/edu/edu_class_view.do",
                            {"e_type": e_type, "yy": gisu["gisu_id"], "class_no": class_no},
                            timeout,
                        )
                        pairs = pairs_from_tables(detail_soup)
                        detail = {
                            "category": pairs.get("\ubd84\uc57c", ""),
                            "application_method_raw": pairs.get("\uad50\uc721\ubc29\ubc95", "") or row["application_method_raw"],
                            "title": pairs.get("\uac15\uc88c\uba85", ""),
                            "capacity": pairs.get("\uc811\uc218\ud604\ud669", "") or row["capacity"],
                            "target": pairs.get("\ub300\uc0c1\uc790", "") or row["target"],
                            "apply_period": pairs.get("\uc811\uc218\uae30\uac04", "") or row["apply_period"],
                            "period": pairs.get("\uad50\uc721\uae30\uac04", "") or row["period"],
                            "schedule_raw": pairs.get("\uad50\uc721\uc2dc\uac04", "") or row["schedule_raw"],
                            "fee": pairs.get("\uc218\uac15\ub8cc", ""),
                            "material_fee": pairs.get("\uc7ac\ub8cc\ube44", ""),
                            "instructor": pairs.get("\uac15\uc0ac\uba85", ""),
                            "description": pairs.get("\uad50\uc721\ub0b4\uc6a9", ""),
                            "raw_detail_pairs": pairs,
                        }
                        row = merge_course_rows(row, detail)
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("chuncheon detail fetch failed %s: %s", raw_url, exc)
                rows.append(row)

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "chuncheon_lifelong", meta


def collect_suseong_learningtalk(target: CrawlTarget, timeout: int, max_pages: int, detail_limit: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    detail_urls: list[str] = []
    if "/front/education/details.do" in target.url:
        detail_urls.append(target.url)
    for link in soup.find_all("a", href=True):
        href = normalize_link(target.url, link.get("href"))
        if href and "/front/education/details.do" in href and href not in detail_urls:
            detail_urls.append(href)
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    for raw_url in detail_urls[: max(max_pages * 5, detail_limit, 1)]:
        try:
            detail_soup = soup if raw_url == target.url else fetch_soup(s, raw_url, timeout=timeout)
            pairs = pairs_from_tables(detail_soup)
            title = clean_text(pairs.get("\uac15\uc88c\uba85"))
            if not title or is_low_value_title(title):
                continue
            branch = clean_text(pairs.get("\uad50\uc721\uae30\uad00")) or target.branch
            status = clean_text(pairs.get("\uc2e0\uccad\uc0c1\ud0dc") or pairs.get("\uc624\ud504\ub77c\uc778\ubaa8\uc9d1\uc0c1\ud0dc"))
            method = clean_text(pairs.get("\uc811\uc218\ubc29\ubc95"))
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "category": clean_text(" > ".join(part for part in [pairs.get("\uac15\uc88c\ubd84\ub958"), pairs.get("\ub0b4\uc6a9\ubd84\ub958"), pairs.get("\ub0b4\uc6a9\ubcc4 \ubd84\ub958")] if clean_text(part))),
                "raw_url": raw_url,
                "application_url": raw_url if "\uc2e0\uccad\uc911" in status else "",
                "status": status,
                "fee": pairs.get("\uc218\uac15\ub8cc", ""),
                "material_fee": pairs.get("\uc7ac\ub8cc\ube44", ""),
                "period": pairs.get("\uad50\uc721\uae30\uac04", ""),
                "apply_period": pairs.get("\uc2e0\uccad\uae30\uac04", ""),
                "schedule_raw": pairs.get("\uad50\uc721\uc2dc\uac04", ""),
                "target": pairs.get("\uad50\uc721\ub300\uc0c1", ""),
                "capacity": pairs.get("\ubaa8\uc9d1\uc778\uc6d0", ""),
                "venue_name": pairs.get("\uad50\uc721\uc7a5\uc18c", ""),
                "venue_address": pairs.get("\uc8fc\uc18c", ""),
                "instructor": pairs.get("\uac15\uc0ac", ""),
                "application_method_raw": method,
                "description": pairs.get("\uac15\uc88c\uc18c\uac1c", ""),
                "raw_fields": {"parser": "suseong_learningtalk", "pairs": pairs},
            }
            rows.append(row)
            detail_pages += 1
        except Exception as exc:
            logger.debug("suseong detail fetch failed %s: %s", raw_url, exc)
        if detail_pages >= detail_limit and "/front/education/details.do" not in target.url:
            break

    if not rows:
        parsed = urlparse(target.url)
        query = parse_qs(parsed.query)
        menu_id = clean_text((query.get("menu_id") or [""])[0])
        for tr in soup.select("table.tbl_eduprog tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"], recursive=False)]
            if len(cells) < 7 or cells[0] == "\ubc88\ud638":
                continue
            title_link = tr.find("a", onclick=re.compile(r"fn_learning_details"))
            title = clean_text(title_link.get_text(" ", strip=True) if title_link else cells[1])
            if not title or is_low_value_title(title):
                continue
            onclick = clean_text(title_link.get("onclick") if title_link else "")
            crs_match = re.search(r"fn_learning_details\('([^']+)'", onclick)
            crs_id = clean_text(crs_match.group(1)) if crs_match else clean_text(cells[0])
            detail_query = {"menu_id": menu_id, "menu_link": f"/reservation/learning/details.do?crsId={crs_id}"}
            raw_url = urlunparse((parsed.scheme, parsed.netloc, parsed.path or "/index.do", "", urlencode(detail_query), ""))
            title_cell = clean_text(cells[1])
            branch = clean_text(title_cell.replace(title, "", 1)) or target.branch
            schedule_raw = clean_text(cells[2])
            period_text = clean_text(cells[3])
            apply_period = ""
            period = ""
            apply_match = re.search(r"\uc2e0\uccad\uae30\uac04\s*([0-9. ~:-]+)", period_text)
            if apply_match:
                apply_period = clean_text(apply_match.group(1))
            period_match = re.search(r"\uad50\uc721\uae30\uac04\s*([0-9. ~:-]+)", period_text)
            if period_match:
                period = clean_text(period_match.group(1))
            detail_schedule_match = re.search(r"\uc694\uc77c\s*\uc2dc\uac04\s*(.+)$", period_text)
            if detail_schedule_match and not schedule_raw:
                schedule_raw = clean_text(detail_schedule_match.group(1))
            fee_text = clean_text(cells[4])
            fee_match = re.search(r"\uc218\uac15\ub8cc\s*:\s*([^/]+)", fee_text)
            material_match = re.search(r"\uc7ac\ub8cc\ube44\s*:\s*(.+)$", fee_text)
            status = clean_text(" ".join(part for part in [cells[5] if len(cells) > 5 else "", cells[-1]] if part))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, crs_id or raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "branch_code": target.provider,
                    "raw_url": raw_url,
                    "application_url": raw_url if "\uc2e0\uccad\ud558\uae30" in status or "\uc811\uc218\uc911" in status else "",
                    "status": normalize_status(status, period_text),
                    "fee": clean_text(fee_match.group(1)) if fee_match else "",
                    "material_fee": clean_text(material_match.group(1)) if material_match else "",
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule_raw,
                    "capacity": clean_text(cells[5] if len(cells) > 5 else ""),
                    "application_method_raw": clean_text(cells[6] if len(cells) > 6 else ""),
                    "description": clean_text(" ".join(cells)),
                    "raw_fields": {"parser": "suseong_learningtalk_list", "cells": cells, "onclick": onclick},
                }
            )

    meta = {
        "pages": 1,
        "detail_pages": detail_pages,
        "discovered_links": len(detail_urls),
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "suseong_learningtalk", meta


def extract_jongno_edu_target(description: Any) -> str:
    text = clean_text(description)
    if not text:
        return ""
    match = re.search(r"(\d{1,3}\s*(?:세\s*이상|개월\s*이상|이상)\s*(?:구민|성인|어린이|주민)?)", text)
    if match:
        return clean_text(match.group(1))
    match = re.search(r"(?:대상|교육대상|모집대상)\s*[:：]?\s*([^.\n]+)", text)
    return clean_text(match.group(1)) if match else ""


def normalize_jongno_detail_period(value: Any) -> tuple[str, str]:
    text = clean_text(value).replace("∼", "~").replace("～", "~").replace("-", "~")
    dotted = re.search(
        r"(\d{1,2})[.]\s*(\d{1,2})\s*~\s*(\d{1,2})[.]\s*(\d{1,2})(.*)",
        text,
    )
    if dotted:
        year = datetime.now().year
        period = (
            f"{year}-{int(dotted.group(1)):02d}-{int(dotted.group(2)):02d}"
            f" ~ {year}-{int(dotted.group(3)):02d}-{int(dotted.group(4)):02d}"
        )
        return period, clean_text(dotted.group(5))
    normalized = normalize_korean_month_day_range(text)
    return split_period_and_schedule(normalized)


def collect_jongno_edu_apply(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 7 or not cells[0].isdigit():
                continue
            title = cells[2]
            if not title or is_low_value_title(title):
                continue
            period_text, schedule = split_period_and_schedule(normalize_korean_month_day_range(cells[4]))
            if not schedule:
                schedule_match = re.search(r"([월화수목금토일요일\s,ㆍ~]+\s*\d{1,2}:\d{2}\s*~\s*\d{1,2}:\d{2})", cells[4])
                schedule = clean_text(schedule_match.group(1)) if schedule_match else ""
            apply_period = normalize_korean_month_day_range(cells[3])
            form = tr.find("form")
            form_values = {
                clean_text(input_node.get("name")): clean_text(input_node.get("value"))
                for input_node in form.select("input")
                if clean_text(input_node.get("name"))
            } if form else {}
            edu_open_cd = form_values.get("edu_open_cd") or cells[0]
            raw_url = urljoin(current_url, f"eduApplyview.do?edu_open_cd={edu_open_cd}")

            detail_pairs: dict[str, str] = {}
            if edu_open_cd:
                try:
                    response = s.post(
                        urljoin(current_url, "eduApplyview.do"),
                        data={"edu_open_cd": edu_open_cd, "pageIndex": str(page)},
                        timeout=timeout,
                    )
                    response.raise_for_status()
                    if not response.encoding or response.encoding.lower() == "iso-8859-1":
                        response.encoding = response.apparent_encoding
                    detail_pairs = pairs_from_tables(BeautifulSoup(response.text, "lxml"))
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("jongno edu detail fetch failed %s: %s", edu_open_cd, exc)

            detail_period, detail_schedule = normalize_jongno_detail_period(detail_pairs.get("교육기간"))
            detail_apply_period = normalize_mixed_date_range(detail_pairs.get("접수기간"))
            if detail_apply_period == "~":
                detail_apply_period = ""
            capacity_current, capacity_total = parse_capacity_pair(detail_pairs.get("정원") or cells[5])
            if capacity_current is None or capacity_total is None:
                list_current, list_total = parse_capacity_pair(cells[5])
                capacity_current = capacity_current if capacity_current is not None else list_current
                capacity_total = capacity_total if capacity_total is not None else list_total
            description = detail_pairs.get("내용") or clean_text(tr.get_text(" ", strip=True))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, detail_pairs.get("교육장소") or cells[1]),
                    "title": title,
                    "branch": detail_pairs.get("교육장소") or cells[1],
                    "category": "구민정보화교육",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": detail_pairs.get("상태") or cells[6],
                    "fee": detail_pairs.get("수강료") or "무료",
                    "material_fee": detail_pairs.get("교재비"),
                    "period": detail_period or period_text,
                    "apply_period": detail_apply_period or apply_period,
                    "schedule_raw": detail_schedule or schedule,
                    "target": extract_jongno_edu_target(description),
                    "capacity": detail_pairs.get("정원") or cells[5],
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "venue_name": detail_pairs.get("교육장소") or cells[1],
                    "phone": detail_pairs.get("교육문의"),
                    "description": description,
                    "raw_fields": {"cells": cells, "detail_pairs": detail_pairs, "parser": "jongno_edu_apply"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jongno_edu_apply", meta


