def is_jongno_reserv_owned_url(value: Any) -> bool:
    try:
        parsed = urlparse(clean_text(value))
        port = parsed.port
    except ValueError:
        return False
    if (
        parsed.scheme != "https"
        or parsed.hostname != "www.jongno.go.kr"
        or parsed.username
        or parsed.password
        or port is not None
        or parsed.path != JONGNO_RESERV_LIST_PATH
        or parsed.fragment
    ):
        return False
    query = parse_qs(parsed.query, keep_blank_values=True)
    return set(query) == {"viewType"} and query.get("viewType") == ["2"]


def jongno_reserv_status(value: str) -> str:
    text = clean_text(value)
    if "접수중" in text:
        return "OPEN"
    if "준비" in text or "예정" in text:
        return "SCHEDULED"
    if "마감" in text or "종료" in text:
        return "CLOSED"
    return normalize_status(text) or text


def jongno_reserv_card_pairs(card: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(card, "select"):
        return pairs
    for dl in card.select(".bot-area dl"):
        key = clean_text(dl.select_one("dt").get_text(" ", strip=True) if dl.select_one("dt") else "")
        key = re.sub(r"\s+", "", key).rstrip(":：")
        value = clean_text(dl.select_one("dd").get_text(" ", strip=True) if dl.select_one("dd") else "")
        if key and value:
            pairs[key] = value
    return pairs


def jongno_reserv_declared_total(soup: Any) -> Optional[int]:
    container = soup.select_one("#container") if hasattr(soup, "select_one") else None
    text = clean_text(container.get_text(" ", strip=True) if container else "")
    match = re.search(r"총\s*([0-9,]+)\s*건", text)
    return int(match.group(1).replace(",", "")) if match else None


def jongno_reserv_declared_pages(soup: Any, total_count: int) -> tuple[int, int]:
    linked_pages: list[int] = []
    if hasattr(soup, "select"):
        for link in soup.select("a[href]"):
            match = re.search(r"linkPage\(\s*(\d+)\s*\)", clean_text(link.get("href")))
            if match:
                linked_pages.append(int(match.group(1)))
    linked_total = max(linked_pages, default=1 if total_count else 0)
    computed_total = (
        (total_count + JONGNO_RESERV_PAGE_SIZE - 1) // JONGNO_RESERV_PAGE_SIZE
        if total_count
        else 0
    )
    return max(linked_total, computed_total), linked_total


def jongno_reserv_source_identity(soup: Any) -> tuple[str, str]:
    script_text = "\n".join(
        script.get_text(" ", strip=False)
        for script in soup.select("script")
    )
    site_match = re.search(r"\b(?:let|const|var)\s+siteId\s*=\s*['\"](\d+)['\"]", script_text)
    category_match = re.search(r"\b(?:let|const|var)\s+category\s*=\s*['\"](\d+)['\"]", script_text)
    return (
        site_match.group(1) if site_match else "",
        category_match.group(1) if category_match else "",
    )


def jongno_reserv_application_url(soup: Any, site_id: str, pg_id: str) -> str:
    candidate = ""
    for link in soup.select("a[href]"):
        href = html.unescape(html.unescape(str(link.get("href") or "")))
        match = re.search(r"linkPage\(\s*(['\"])(https://.+?)\1\s*\)", href)
        if match:
            candidate = clean_text(match.group(2))
            break
    if not candidate:
        return ""
    try:
        parsed = urlparse(candidate)
        port = parsed.port
    except ValueError:
        return ""
    if parsed.scheme != "https" or parsed.username or parsed.password or port is not None or parsed.fragment:
        return ""
    query = parse_qs(parsed.query, keep_blank_values=True)
    if site_id == "1":
        if parsed.hostname != "jachi.jongno.go.kr" or parsed.path != "/Program/Default.aspx":
            return ""
        if not {"areaSeq", "programKindSeq", "titleKeyword"}.issubset(query):
            return ""
    elif site_id == "3":
        if parsed.hostname not in {"jfac.or.kr", "www.jfac.or.kr"}:
            return ""
        if not parsed.path.startswith("/site/main/program/"):
            return ""
        if (query.get("pgIdx") or [""])[0] != pg_id.removeprefix("JFAC"):
            return ""
    elif site_id == "5":
        if parsed.hostname != "www.jongno.go.kr" or parsed.path != "/edu/eduApplyview.do":
            return ""
        if (query.get("edu_open_cd") or [""])[0] != pg_id.removeprefix("EDU_"):
            return ""
    else:
        return ""
    return candidate


def jongno_reserv_source_matches_pg_id(site_id: str, pg_id: str) -> bool:
    patterns = {
        "1": r"ACMS_\d+",
        "3": r"JFAC\d+",
        "5": r"EDU_\d+",
    }
    pattern = patterns.get(site_id)
    return bool(pattern and re.fullmatch(pattern, pg_id))


def jongno_reserv_is_education_source(site_id: str, source_category: str) -> bool:
    return site_id == "1" or (site_id, source_category) in JONGNO_RESERV_EDUCATION_SOURCES


def jongno_reserv_fallback_branch(title: Any, site_id: str, fallback: Any) -> str:
    text = clean_text(title)
    if site_id == "1":
        match = re.match(r"^\[([^\]]+)\]", text)
        if match:
            return clean_text(f"{match.group(1)} 자치회관")
    facility_match = re.search(
        r"([가-힣A-Za-z0-9·]{2,}(?:도서관|문화센터|주민센터|자치회관|전시관|학습관|교육장|박물관))",
        text,
    )
    return clean_text(facility_match.group(1) if facility_match else fallback)


def jongno_reserv_detail_fields(
    s: requests.Session,
    url: str,
    pg_id: str,
    timeout: int,
) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    title_node = soup.select_one(".tit-area h3, .view-title, h3.vw-tit2, #container h3")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    pairs = pairs_from_definition_lists(soup)
    site_id, source_category = jongno_reserv_source_identity(soup)
    period = normalize_mixed_date_range(pairs.get("교육기간", ""))
    apply_period = normalize_mixed_date_range(pairs.get("신청기간", ""))
    weekday = clean_text(pairs.get("요일"))
    edu_time = clean_text(pairs.get("교육시간"))
    schedule = clean_text(" ".join(part for part in [weekday, edu_time] if part))
    capacity_total = parse_capacity_number(pairs.get("모집인원"))
    return {
        "title": title,
        "status": jongno_reserv_status(pairs.get("진행상태", "")),
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": schedule,
        "fee": clean_text(pairs.get("수강료")),
        "target": clean_text(pairs.get("신청대상")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "capacity": clean_text(pairs.get("모집인원")),
        "capacity_total": capacity_total,
        "room": clean_text(pairs.get("장소")),
        "venue_name": clean_text(pairs.get("장소")),
        "description": clean_text(soup.select_one("#container").get_text(" ", strip=True) if soup.select_one("#container") else ""),
        "source_site_id": site_id,
        "source_category": source_category,
        "source_label": JONGNO_RESERV_SOURCE_LABELS.get((site_id, source_category), ""),
        "application_url": jongno_reserv_application_url(soup, site_id, pg_id),
        "raw_detail_pairs": pairs,
    }


def collect_jongno_reserv_deadline(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if target.provider != JONGNO_RESERV_PROVIDER or not is_jongno_reserv_owned_url(target.url):
        raise ValueError("Jongno reservation collection requires the canonical provider and owned HTTPS list URL")

    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    detail_attempts = 0
    detail_errors = 0
    source_identity_errors = 0
    application_errors = 0
    duplicate_count = 0
    invalid_count = 0
    expired_count = 0
    excluded_non_education_count = 0
    reservation_discovery_links = 0
    source_counts: dict[str, int] = {}
    education_source_counts: dict[str, int] = {}
    status_counts: dict[str, int] = {}
    errors: list[str] = []
    listed: dict[str, dict[str, Any]] = {}
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    base_query["viewType"] = ["2"]
    pagination_detected = False
    total_count: Optional[int] = None
    total_pages = 0
    linked_total_pages = 0
    page_counts: list[int] = []

    first_url = parsed._replace(path=JONGNO_RESERV_LIST_PATH, query=urlencode(base_query, doseq=True)).geturl()
    first_soup = fetch_soup(s, first_url, timeout=timeout)
    first_total = jongno_reserv_declared_total(first_soup)
    if first_total is None:
        errors.append("official total count was missing")
        first_total = 0
    total_count = first_total
    total_pages, linked_total_pages = jongno_reserv_declared_pages(first_soup, total_count)
    computed_total_pages = (
        (total_count + JONGNO_RESERV_PAGE_SIZE - 1) // JONGNO_RESERV_PAGE_SIZE
        if total_count
        else 0
    )
    if linked_total_pages != computed_total_pages:
        errors.append(
            f"declared pagination disagreed with total count ({linked_total_pages} linked vs {computed_total_pages} computed)"
        )
    pagination_detected = total_pages > 1

    if total_count == 0:
        meta = {
            "pages": 1,
            "detail_pages": 0,
            "detail_attempts": 0,
            "discovered_links": 0,
            "reservation_discovery_links": 0,
            "pagination_detected": False,
            "pagination_complete": not errors,
            "list_pagination_complete": not errors,
            "source_cap_reached": False,
            "recursion_depth": 0,
            "total_count": 0,
            "total_pages": 0,
            "current_count": 0,
            "education_count": 0,
            "excluded_non_education_count": 0,
            "no_current_data": not errors,
            "no_current_reason": "official Jongno deadline list reported zero programs" if not errors else "",
        }
        if errors:
            meta["configured_collection_error"] = "; ".join(errors)
        return [], JONGNO_RESERV_PARSER, meta

    pages_to_fetch = min(max_pages, total_pages)
    if pages_to_fetch < total_pages:
        errors.append(f"max_pages cap reached after {pages_to_fetch} of {total_pages} declared pages")

    for page in range(1, pages_to_fetch + 1):
        query = dict(base_query)
        if page > 1:
            query["pageIndex"] = [str(page)]
        current_url = parsed._replace(path=JONGNO_RESERV_LIST_PATH, query=urlencode(query, doseq=True)).geturl()
        soup = first_soup if page == 1 else fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        current_total = jongno_reserv_declared_total(soup)
        if current_total != total_count:
            errors.append(f"official total changed on page {page} ({total_count} -> {current_total})")
        cards = soup.select("ul.mgs-line > li")
        page_counts.append(len(cards))
        if not cards:
            errors.append(f"declared page {page} contained no program cards")
            continue
        for card in cards:
            link = card.select_one("a[href*='/reserv/detail.do']")
            title_node = card.select_one(".tit")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            raw_url = normalize_link(current_url, link.get("href") if link else "")
            pg_id = clean_text((parse_qs(urlparse(raw_url).query).get("pgId") or [""])[0])
            if (
                not link
                or not title
                or is_low_value_title(title)
                or not re.fullmatch(r"[A-Z][A-Z0-9_]{1,99}", pg_id)
            ):
                invalid_count += 1
                continue
            if pg_id in listed:
                duplicate_count += 1
                continue
            listed[pg_id] = {
                "pg_id": pg_id,
                "title": title,
                "raw_url": raw_url,
                "page_url": current_url,
                "page": page,
                "pairs": jongno_reserv_card_pairs(card),
                "status": jongno_reserv_status(
                    card.select_one(".cp").get_text(" ", strip=True)
                    if card.select_one(".cp")
                    else ""
                ),
                "card_text": clean_text(card.get_text(" ", strip=True)),
            }

    if invalid_count:
        errors.append(f"listed program cards were malformed ({invalid_count})")
    if duplicate_count:
        errors.append(f"listed pgId values were duplicated ({duplicate_count})")
    if len(listed) != total_count:
        errors.append(f"parsed {len(listed)} unique pgId values of {total_count} declared programs")

    detail_enrichment_capped = len(listed) > max(0, detail_limit)
    if detail_enrichment_capped:
        errors.append(f"detail enrichment capped at {max(0, detail_limit)} of {len(listed)} programs")

    for item in list(listed.values())[: max(0, detail_limit)]:
        pg_id = item["pg_id"]
        try:
            detail_attempts += 1
            detail = jongno_reserv_detail_fields(s, item["raw_url"], pg_id, timeout)
            detail_pages += 1
        except Exception as exc:
            detail_errors += 1
            logger.debug("jongno reserv detail fetch failed %s: %s", item["raw_url"], exc)
            continue

        site_id = clean_text(detail.get("source_site_id"))
        source_category = clean_text(detail.get("source_category"))
        source_key = f"{site_id}:{source_category}"
        source_counts[source_key] = source_counts.get(source_key, 0) + 1
        if (
            not site_id
            or not source_category
            or not jongno_reserv_source_matches_pg_id(site_id, pg_id)
        ):
            source_identity_errors += 1
            continue

        application_url = clean_text(detail.get("application_url"))
        if not application_url:
            application_errors += 1
            continue
        reservation_discovery_links += 1

        if not jongno_reserv_is_education_source(site_id, source_category):
            excluded_non_education_count += 1
            continue

        final_status = clean_text(detail.get("status")) or item["status"]
        if final_status == "CLOSED":
            expired_count += 1
            continue
        status_counts[final_status] = status_counts.get(final_status, 0) + 1
        education_source_counts[source_key] = education_source_counts.get(source_key, 0) + 1
        final_title = clean_text(detail.get("title")) or item["title"]
        if is_low_value_title(final_title):
            final_title = item["title"]
        pairs = item["pairs"]
        room = clean_text(detail.get("room")) or clean_text(pairs.get("장소"))
        branch = room or jongno_reserv_fallback_branch(final_title, site_id, target.branch)
        capacity_total = detail.get("capacity_total")
        if capacity_total is None:
            capacity_total = parse_capacity_number(pairs.get("모집"))
        source_label = clean_text(detail.get("source_label")) or JONGNO_RESERV_SOURCE_LABELS.get(
            (site_id, source_category),
            "종로구 통합예약 교육",
        )
        row = {
            "provider": target.provider,
            "provider_course_id": pg_id,
            "prefer_incoming_provider_course_id": True,
            "title": final_title,
            "branch": branch,
            "branch_code": stable_provider(target.provider[:32], branch),
            "category": source_label,
            "program_type": "강좌",
            "raw_url": item["raw_url"],
            "application_url": application_url,
            "reservation_available": final_status in {"OPEN", "SCHEDULED"},
            "status": final_status,
            "period": clean_text(detail.get("period")) or normalize_mixed_date_range(pairs.get("기간", "")),
            "apply_period": clean_text(detail.get("apply_period")) or normalize_mixed_date_range(pairs.get("신청기간", "")),
            "schedule_raw": clean_text(detail.get("schedule_raw")) or normalize_mixed_date_range(pairs.get("기간", "")),
            "target": clean_text(detail.get("target")),
            "fee": clean_text(detail.get("fee")) or clean_text(pairs.get("수강료")),
            "capacity": clean_text(detail.get("capacity")) or clean_text(pairs.get("모집")),
            "capacity_total": capacity_total,
            "room": room,
            "venue_name": clean_text(detail.get("venue_name")) or room,
            "description": clean_text(detail.get("description")) or item["card_text"],
            "application_method_raw": clean_text(detail.get("application_method_raw")),
            "collection_category": "공공예약",
            "domain_category": "교육·강좌",
            "source_group": "municipal_reservation",
            "operator_type": "지자체/공공기관",
            "service_group": "공공강좌",
            "service_group_policy": "locked",
            "raw_fields": {
                "parser": JONGNO_RESERV_PARSER,
                "pg_id": pg_id,
                "page": item["page"],
                "page_url": item["page_url"],
                "source_site_id": site_id,
                "source_category": source_category,
                "source_key": source_key,
                "source_label": source_label,
                "source_prefix": pg_id.split("_", 1)[0] if "_" in pg_id else re.sub(r"\d+$", "", pg_id),
                "application_url_source": "detail_javascript_linkPage",
                "venue_missing": not bool(room),
                "list_pairs": pairs,
                "detail_pairs": detail.get("raw_detail_pairs", {}),
            },
        }
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

    if detail_errors:
        errors.append(f"detail fetch failed for {detail_errors} programs")
    if source_identity_errors:
        errors.append(f"detail source identity was invalid for {source_identity_errors} programs")
    if application_errors:
        errors.append(f"trusted application link was missing for {application_errors} programs")

    classified_count = len(rows) + excluded_non_education_count + expired_count
    if not detail_enrichment_capped and classified_count != len(listed):
        errors.append(f"classified {classified_count} of {len(listed)} listed programs")

    list_error_tokens = (
        "official total",
        "declared pagination",
        "max_pages cap",
        "declared page",
        "listed program",
        "listed pgId",
        "unique pgId",
    )
    list_pagination_complete = not any(
        any(token in error for token in list_error_tokens)
        for error in errors
    )
    collection_complete = not errors
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_errors": detail_errors,
        "discovered_links": len(listed),
        "reservation_discovery_links": reservation_discovery_links,
        "pagination_detected": pagination_detected,
        "pagination_complete": collection_complete,
        "list_pagination_complete": list_pagination_complete,
        "source_cap_reached": pages_to_fetch < total_pages or detail_enrichment_capped,
        "recursion_depth": 0,
        "total_count": total_count,
        "total_pages": total_pages,
        "linked_total_pages": linked_total_pages,
        "page_counts": page_counts,
        "duplicate_count": duplicate_count,
        "invalid_count": invalid_count,
        "detail_enrichment_capped": detail_enrichment_capped,
        "source_identity_errors": source_identity_errors,
        "application_errors": application_errors,
        "source_counts": source_counts,
        "education_source_counts": education_source_counts,
        "status_counts": status_counts,
        "education_count": len(rows),
        "current_count": len(rows),
        "expired_count": expired_count,
        "excluded_non_education_count": excluded_non_education_count,
        "no_current_data": not rows and collection_complete,
        "no_current_reason": "official Jongno list contained no current education programs" if not rows and collection_complete else "",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(errors)
    return dedupe_rows(rows), JONGNO_RESERV_PARSER, meta


def jongno_jachi_status(value: Any) -> str:
    text = clean_text(value)
    if "접수중" in text:
        return "접수중"
    if "방문접수" in text:
        return "방문접수"
    if "대기" in text or "예정" in text:
        return "접수예정"
    if "마감" in text or "종료" in text:
        return "접수마감"
    return normalize_status(text) or text


def jongno_jachi_capacity(value: Any) -> tuple[str, Optional[int], Optional[int]]:
    text = clean_text(value)
    parts: list[str] = []
    current_total = 0
    capacity_total = 0
    found = False
    for label, total, current in re.findall(r"([가-힣]+접수)\s*정원\s*:\s*(\d+)\s*명\s*/\s*접수\s*:\s*(\d+)\s*명", text):
        found = True
        total_int = int(total)
        current_int = int(current)
        capacity_total += total_int
        current_total += current_int
        parts.append(f"{label} {current_int}/{total_int}")
    if found:
        return clean_text(" / ".join(parts)), current_total, capacity_total
    current, total = parse_capacity_pair(text)
    return text, current, total


def jongno_jachi_page_url(base_url: str, page: int) -> str:
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    if page > 1:
        query["pageNo"] = [str(page)]
    else:
        query.pop("pageNo", None)
    return parsed._replace(path="/Program/Default.aspx", query=urlencode(query, doseq=True)).geturl()


def jongno_jachi_detail_pairs(dd: Any) -> dict[str, str]:
    table = dd.select_one("table.table_list") if hasattr(dd, "select_one") else None
    return pairs_from_tables(table) if table else {}


def collect_jongno_jachi_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    seen: set[str] = set()
    pagination_detected = False

    for page in range(1, max(1, max_pages) + 1):
        current_url = jongno_jachi_page_url(target.url, page)
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        nav = soup.select_one("dl#navi")
        if not nav:
            break
        dts = nav.find_all("dt", recursive=False)
        page_rows = 0
        for index, dt in enumerate(dts, start=1):
            summary_table = dt.select_one("table.table_list")
            if not summary_table:
                continue
            summary_cells = [
                clean_text(cell.get_text(" ", strip=True))
                for cell in summary_table.select_one("tr").find_all(["th", "td"])
            ] if summary_table.select_one("tr") else []
            if len(summary_cells) < 8 or not summary_cells[0].isdigit():
                continue
            answer_id = f"answer{index}"
            dd = nav.find("dd", id=answer_id)
            detail_pairs = jongno_jachi_detail_pairs(dd) if dd else {}
            raw_url = f"{current_url}#{answer_id}"
            course_no = summary_cells[0]
            category = summary_cells[1]
            target_text = clean_text(detail_pairs.get("교육대상") or summary_cells[2])
            raw_title = clean_text(detail_pairs.get("강좌명") or summary_cells[3])
            branch_area = clean_text(detail_pairs.get("자치회관"))
            branch = f"{branch_area} 자치회관" if branch_area else "종로구 자치회관"
            title = clean_text(re.sub(r"^\[[^\]]+\]\s*", "", raw_title)) or raw_title
            if not title or is_low_value_title(title):
                continue
            key = f"{page}:{course_no}:{title}:{branch}"
            if key in seen:
                continue
            seen.add(key)
            status = jongno_jachi_status(summary_cells[7])
            period = normalize_month_day_range(summary_cells[6])
            apply_period = normalize_mixed_date_range(detail_pairs.get("접수기간") or normalize_month_day_range(summary_cells[5]))
            schedule = clean_text(detail_pairs.get("교육기간/시간"))
            capacity, capacity_current, capacity_total = jongno_jachi_capacity(
                clean_text(" ".join(part for part in [detail_pairs.get("온라인접수"), detail_pairs.get("방문접수")] if part))
            )
            description = clean_text(
                " ".join(
                    part
                    for part in [
                        detail_pairs.get("강좌소개"),
                        detail_pairs.get("수업준비물"),
                        detail_pairs.get("문의전화"),
                    ]
                    if part
                )
            )
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, key, title, branch),
                "title": title,
                "branch": branch,
                "branch_code": stable_provider(target.provider[:32], branch),
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url if status in {"접수중", "접수예정", "방문접수"} else "",
                "status": status,
                "fee": clean_text(detail_pairs.get("수강료") or "").replace("￦", "").strip(),
                "period": period,
                "apply_period": apply_period,
                "schedule_raw": schedule,
                "target": target_text,
                "instructor": clean_text(detail_pairs.get("강사명") or summary_cells[4]),
                "capacity": capacity,
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "room": clean_text(detail_pairs.get("교육장소")),
                "venue_name": clean_text(detail_pairs.get("교육장소") or branch),
                "phone": clean_text(detail_pairs.get("문의전화")),
                "description": description or clean_text(dd.get_text(" ", strip=True) if dd else ""),
                "application_method_raw": status,
                "program_type": "강좌",
                "collection_category": "체육/스포츠",
                "domain_category": "체육/스포츠",
                "source_group": "sports_facility",
                "operator_type": "지자체/공공기관",
                "collection_type": "static_html",
                "raw_fields": {
                    "parser": "jongno_jachi_program_list",
                    "page_url": current_url,
                    "summary_cells": summary_cells,
                    "detail_pairs": detail_pairs,
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select("a[href*='pageNo=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jongno_jachi_program_list", meta


def guri_reserve_status(value: str) -> str:
    text = clean_text(value)
    if "접수중" in text or "대기자접수" in text:
        return "접수중"
    if "예정" in text:
        return "접수예정"
    if "마감" in text or "종료" in text:
        return "접수마감"
    return normalize_status(text) or text


def guri_capacity(value: str) -> tuple[Optional[int], Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value)
    main = re.search(r"신청\s*(\d+)\s*명\s*/\s*모집정원\s*(\d+)\s*명", text)
    if not main:
        main = re.search(r"(\d+)\s*/\s*(\d+)", text)
    wait = re.search(r"대기신청\s*(\d+)\s*명\s*/\s*대기정원\s*(\d+)\s*명", text)
    return (
        int(main.group(1)) if main else None,
        int(main.group(2)) if main else None,
        int(wait.group(1)) if wait else None,
        int(wait.group(2)) if wait else None,
    )


def guri_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    title = clean_text(soup.select_one(".title_area .tit_text").get_text(" ", strip=True) if soup.select_one(".title_area .tit_text") else "")
    status = clean_text(soup.select_one(".title_area .acc_btn").get_text(" ", strip=True) if soup.select_one(".title_area .acc_btn") else "")
    pairs = pairs_from_tables(soup)
    current, total, wait_current, wait_total = guri_capacity(pairs.get("접수현황", ""))
    fee = clean_text(pairs.get("수강료"))
    if fee in {"0", "0원"}:
        fee = "무료"
    period = bucheon_reservation_datetime_range(pairs.get("교육기간", ""))
    schedule = clean_text(pairs.get("교육시간"))
    return {
        "title": title,
        "status": guri_reserve_status(status),
        "apply_period": bucheon_reservation_datetime_range(pairs.get("접수기간", "")),
        "period": period,
        "schedule_raw": schedule,
        "application_method_raw": clean_text(pairs.get("신청방법")),
        "target": clean_text(pairs.get("교육대상")),
        "capacity": clean_text(pairs.get("접수현황")),
        "capacity_current": current,
        "capacity_total": total,
        "waitlist_current": wait_current,
        "waitlist_total": wait_total,
        "room": clean_text(pairs.get("교육장")),
        "venue_name": clean_text(pairs.get("교육장")),
        "instructor": clean_text(pairs.get("강사명")),
        "fee": fee,
        "phone": clean_text(pairs.get("문의전화")),
        "description": clean_text(" ".join(part for part in [pairs.get("강의소개"), pairs.get("유의사항")] if part)),
        "raw_detail_pairs": pairs,
    }


def collect_guri_user_course_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    base_query.setdefault("pageUnit", ["15"])
    seen: set[str] = set()
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        page_url = parsed._replace(path="/reserve/selectGuriUserCourseList.do", query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        table = soup.select_one("table")
        if not table:
            break
        page_rows = 0
        for tr in table.select("tbody tr"):
            cells = tr.find_all("td", recursive=False)
            if len(cells) < 8:
                continue
            link = cells[1].find("a", href=True)
            title = clean_text(link.get_text(" ", strip=True) if link else cells[1].get_text(" ", strip=True))
            if not link or not title:
                continue
            raw_url = normalize_link(page_url, link.get("href")) or page_url
            course_id = clean_text((parse_qs(urlparse(raw_url).query).get("lctreRcritKey") or [""])[0])
            if course_id and course_id in seen:
                continue
            if course_id:
                seen.add(course_id)
            period_cell = clean_text(cells[2].get_text(" ", strip=True))
            dates = re.findall(r"\d{4}-\d{2}-\d{2}\s*~\s*\d{4}-\d{2}-\d{2}", period_cell)
            apply_period = bucheon_reservation_datetime_range(dates[0]) if len(dates) >= 1 else ""
            period = bucheon_reservation_datetime_range(dates[1]) if len(dates) >= 2 else ""
            schedule = clean_text(cells[3].get_text(" ", strip=True))
            current, total, wait_current, wait_total = guri_capacity(cells[5].get_text(" ", strip=True))
            detail: dict[str, Any] = {}
            if raw_url and detail_pages < detail_limit:
                try:
                    detail = guri_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("guri course detail fetch failed %s: %s", raw_url, exc)
            final_title = clean_text(detail.get("title")) or title
            room = clean_text(detail.get("room"))
            branch = room or target.branch
            final_status = clean_text(detail.get("status")) or guri_reserve_status(cells[7].get_text(" ", strip=True))
            row = {
                "provider": target.provider,
                "provider_course_id": course_id or stable_course_id(target.provider, raw_url, final_title, branch),
                "title": final_title,
                "branch": branch,
                "branch_code": stable_provider(target.provider[:32], branch),
                "category": "구리시 교육강좌",
                "raw_url": raw_url,
                "application_url": raw_url if final_status in {"접수중", "접수예정"} else "",
                "status": final_status,
                "period": clean_text(detail.get("period")) or period,
                "apply_period": clean_text(detail.get("apply_period")) or apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")) or schedule,
                "target": clean_text(detail.get("target")),
                "fee": clean_text(detail.get("fee")),
                "capacity": clean_text(detail.get("capacity")) or clean_text(cells[5].get_text(" ", strip=True)),
                "capacity_current": detail.get("capacity_current") if detail.get("capacity_current") is not None else current,
                "capacity_total": detail.get("capacity_total") if detail.get("capacity_total") is not None else total,
                "waitlist_current": detail.get("waitlist_current") if detail.get("waitlist_current") is not None else wait_current,
                "waitlist_total": detail.get("waitlist_total") if detail.get("waitlist_total") is not None else wait_total,
                "room": room,
                "venue_name": clean_text(detail.get("venue_name")) or room,
                "phone": clean_text(detail.get("phone")),
                "instructor": clean_text(detail.get("instructor")),
                "description": clean_text(detail.get("description")) or clean_text(tr.get_text(" ", strip=True)),
                "application_method_raw": clean_text(detail.get("application_method_raw")) or clean_text(cells[6].get_text(" ", strip=True)),
                "raw_fields": {
                    "parser": "guri_user_course_list+detail",
                    "course_id": course_id,
                    "page_url": page_url,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination a[href], .paging a[href], a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "guri_user_course_list+detail", meta


DONGDAEMUN_EDUCATION_PROVIDER = "MUNI_WWW_DDM_GO_KR_315F4471"
DONGDAEMUN_EDUCATION_HOST = "www.ddm.go.kr"
DONGDAEMUN_EDUCATION_LIST_PATH = "/reserve/selectDongdaemunUserCourseList.do"
DONGDAEMUN_EDUCATION_DETAIL_PATH = "/reserve/selectDongdaemunUserCourseView.do"
DONGDAEMUN_EDUCATION_APPLICATION_PATH = "/reserve/addDongdaemunUserCourseRegistView.do"
DONGDAEMUN_EDUCATION_MENU_KEY = "1529"
DONGDAEMUN_EDUCATION_PAGE_SIZE = 15
DONGDAEMUN_EDUCATION_STATES: tuple[tuple[str, str, str], ...] = (
    ("TBCCPT", "SCHEDULED", "접수예정"),
    ("ACCPT", "OPEN", "접수중"),
    ("WRCPT", "OPEN", "대기자접수"),
)
DONGDAEMUN_EDUCATION_REQUIRED_DETAIL_LABELS = (
    "접수기간",
    "접수현황",
    "선발방법",
    "신청방법",
    "교육대상",
    "교육기간",
    "교육시간",
    "교육장",
    "교육장 주소",
    "수강료",
    "문의전화",
    "강좌소개",
)


def is_dongdaemun_education_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == DONGDAEMUN_EDUCATION_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == DONGDAEMUN_EDUCATION_HOST
        and parsed.path == DONGDAEMUN_EDUCATION_LIST_PATH
        and parse_qs(parsed.query, keep_blank_values=True)
        == {"key": [DONGDAEMUN_EDUCATION_MENU_KEY]}
    )


def dongdaemun_education_list_url(state_code: str, page_index: int) -> str:
    query = urlencode(
        {
            "key": DONGDAEMUN_EDUCATION_MENU_KEY,
            "pageUnit": str(DONGDAEMUN_EDUCATION_PAGE_SIZE),
            "timeBgnde": "",
            "timeEndde": "",
            "receptionStts": clean_text(state_code),
            "searchCnd": "all",
            "searchKrwd": "",
            "searchEduInstSe": "",
            "searchEdcKey": "",
            "pageIndex": str(max(1, page_index)),
        }
    )
    return f"https://{DONGDAEMUN_EDUCATION_HOST}{DONGDAEMUN_EDUCATION_LIST_PATH}?{query}"


def dongdaemun_education_detail_url(lecture_id: str) -> str:
    query = urlencode(
        {
            "key": DONGDAEMUN_EDUCATION_MENU_KEY,
            "lctreRcritKey": clean_text(lecture_id),
        }
    )
    return f"https://{DONGDAEMUN_EDUCATION_HOST}{DONGDAEMUN_EDUCATION_DETAIL_PATH}?{query}"


def dongdaemun_education_application_url(lecture_id: str) -> str:
    query = urlencode(
        {
            "key": DONGDAEMUN_EDUCATION_MENU_KEY,
            "lctreRcritKey": clean_text(lecture_id),
        }
    )
    return f"https://{DONGDAEMUN_EDUCATION_HOST}{DONGDAEMUN_EDUCATION_APPLICATION_PATH}?{query}"


def dongdaemun_education_page_declaration(soup: BeautifulSoup) -> Optional[tuple[int, int, int]]:
    match = re.search(
        r"총\s*게시물\s*:\s*([\d,]+)\s*건\s*페이지\s*:\s*(\d+)\s*/\s*(\d+)",
        clean_text(soup.get_text(" ", strip=True)),
    )
    if not match:
        return None
    return int(match.group(1).replace(",", "")), int(match.group(2)), int(match.group(3))


def dongdaemun_education_capacity(
    value: Any,
) -> tuple[Optional[int], Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value)
    main = re.search(
        r"신청\s*(\d[\d,]*)\s*명\s*/\s*모집정원\s*(\d[\d,]*)\s*명",
        text,
    )
    if not main:
        main = re.search(r"(\d[\d,]*)\s*/\s*(\d[\d,]*)", text)
    wait = re.search(
        r"대기신청\s*(\d[\d,]*)\s*명\s*/\s*대기정원\s*(\d[\d,]*)\s*명",
        text,
    )
    if not wait:
        wait = re.search(r"\(\s*(\d[\d,]*)\s*/\s*(\d[\d,]*)\s*\)", text)
    return (
        int(main.group(1).replace(",", "")) if main else None,
        int(main.group(2).replace(",", "")) if main else None,
        int(wait.group(1).replace(",", "")) if wait else None,
        int(wait.group(2).replace(",", "")) if wait else None,
    )


def dongdaemun_education_address(value: Any, venue_name: Any) -> str:
    address = re.sub(r"^\(\d{5}\)\s*", "", clean_text(value))
    venue = clean_text(venue_name)
    if venue and address.endswith(venue):
        address = clean_text(address[: -len(venue)])
    return address


def dongdaemun_education_list_rows(
    target: CrawlTarget,
    soup: BeautifulSoup,
    *,
    state_code: str,
    normalized_status: str,
    expected_source_status: str,
    page_index: int,
) -> tuple[list[dict[str, Any]], int]:
    rows: list[dict[str, Any]] = []
    invalid_rows = 0
    for tr in soup.select("table tbody tr"):
        cells = tr.find_all("td", recursive=False)
        if not cells:
            continue
        first_text = clean_text(cells[0].get_text(" ", strip=True))
        link = cells[1].find("a", href=True) if len(cells) > 1 else None
        if not first_text.isdigit() and not link:
            continue
        if len(cells) != 9 or not first_text.isdigit() or link is None:
            invalid_rows += 1
            continue

        linked_url = normalize_link(target.url, link.get("href"))
        parsed_link = urlparse(linked_url)
        query = parse_qs(parsed_link.query, keep_blank_values=True)
        lecture_id = clean_text((query.get("lctreRcritKey") or [""])[0])
        title = clean_text(link.get_text(" ", strip=True))
        source_status = clean_text(cells[8].get_text(" ", strip=True))
        dates = re.findall(
            r"\d{4}-\d{2}-\d{2}\s*~\s*\d{4}-\d{2}-\d{2}",
            clean_text(cells[4].get_text(" ", strip=True)),
        )
        capacity_text = clean_text(cells[7].get_text(" ", strip=True))
        current, total, wait_current, wait_total = dongdaemun_education_capacity(capacity_text)
        valid_identity = (
            parsed_link.scheme.lower() == "https"
            and parsed_link.netloc.lower() == DONGDAEMUN_EDUCATION_HOST
            and parsed_link.path == DONGDAEMUN_EDUCATION_DETAIL_PATH
            and lecture_id.isdigit()
        )
        if (
            not valid_identity
            or not title
            or source_status != expected_source_status
            or len(dates) != 2
            or current is None
            or total is None
        ):
            invalid_rows += 1
            continue

        branch = clean_text(cells[2].get_text(" ", strip=True))
        venue = clean_text(cells[3].get_text(" ", strip=True))
        schedule = clean_text(cells[5].get_text(" ", strip=True))
        selection_method = clean_text(cells[6].get_text(" ", strip=True))
        if not branch or not venue or not schedule or not selection_method:
            invalid_rows += 1
            continue
        detail_url = dongdaemun_education_detail_url(lecture_id)
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": f"{target.provider}:lecture:{lecture_id}"[:100],
                "prefer_incoming_provider_course_id": True,
                "title": title,
                "branch": branch,
                "branch_code": stable_provider("DONGDAEMUN_BRANCH", branch),
                "preserve_branch": True,
                "branch_url": target.url,
                "category": "교육·강좌",
                "program_type": "강좌",
                "raw_url": detail_url,
                "application_url": dongdaemun_education_application_url(lecture_id),
                "application_type": "ONLINE_RESERVATION",
                "reservation_available": normalized_status == "OPEN",
                "status": normalized_status,
                "period": bucheon_reservation_datetime_range(dates[1]),
                "apply_period": bucheon_reservation_datetime_range(dates[0]),
                "schedule_raw": schedule,
                "capacity": capacity_text,
                "capacity_current": current,
                "capacity_total": total,
                "waitlist_current": wait_current,
                "waitlist_total": wait_total,
                "room": venue,
                "venue_name": venue,
                "application_method_raw": "인터넷",
                "description": clean_text(tr.get_text(" ", strip=True)),
                "collection_category": "공공예약",
                "domain_category": "교육·강좌",
                "operator_type": "지자체/공공기관",
                "source_group": "municipal_reservation",
                "collection_type": "active_status_filters+detail_html",
                "service_group": "공공강좌",
                "service_group_policy": "locked",
                "raw_fields": {
                    "parser": "dongdaemun_active_course_states+detail",
                    "lecture_id": lecture_id,
                    "state_code": state_code,
                    "source_status": source_status,
                    "list_ordinal": int(first_text),
                    "page_index": page_index,
                    "selection_method": selection_method,
                    "list_cells": [clean_text(cell.get_text(" ", strip=True)) for cell in cells],
                },
            }
        )
    return rows, invalid_rows


def dongdaemun_education_detail_title(soup: BeautifulSoup) -> tuple[str, str]:
    title_box = soup.select_one(".bbs_view_title")
    state_node = soup.select_one(".bbs_view_title .state")
    source_status = clean_text(state_node.get_text(" ", strip=True) if state_node else "")
    combined = clean_text(title_box.get_text(" ", strip=True) if title_box else "")
    title = clean_text(re.sub(rf"\s*{re.escape(source_status)}\s*$", "", combined)) if source_status else combined
    return title, source_status


def dongdaemun_education_application_link(
    soup: BeautifulSoup,
    detail_url: str,
    lecture_id: str,
) -> str:
    for link in soup.select("a[href*='addDongdaemunUserCourseRegistView.do'][href*='lctreRcritKey=']"):
        application_url = normalize_link(detail_url, link.get("href"))
        parsed = urlparse(application_url)
        query = parse_qs(parsed.query, keep_blank_values=True)
        if (
            parsed.scheme.lower() == "https"
            and parsed.netloc.lower() == DONGDAEMUN_EDUCATION_HOST
            and parsed.path == DONGDAEMUN_EDUCATION_APPLICATION_PATH
            and (query.get("key") or [""])[0] == DONGDAEMUN_EDUCATION_MENU_KEY
            and (query.get("lctreRcritKey") or [""])[0] == lecture_id
        ):
            return dongdaemun_education_application_url(lecture_id)
    return ""


def collect_dongdaemun_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    errors: list[str] = []
    if not is_dongdaemun_education_target(target):
        errors.append("target does not match the canonical Dongdaemun education source")

    s = session()
    listed_rows: list[dict[str, Any]] = []
    seen_lecture_ids: set[str] = set()
    pages = 0
    invalid_rows = 0
    duplicate_lectures = 0
    source_cap_reached = False
    status_pages: dict[str, int] = {}
    declared_pages_by_status: dict[str, int] = {}
    declared_totals_by_status: dict[str, int] = {}
    status_complete: dict[str, bool] = {}

    if not errors:
        for state_code, normalized_status, source_status in DONGDAEMUN_EDUCATION_STATES:
            state_error_count = len(errors)
            state_rows: list[dict[str, Any]] = []
            state_pages = 0
            first_url = dongdaemun_education_list_url(state_code, 1)
            try:
                first_soup = fetch_soup(s, first_url, timeout=timeout)
            except Exception as exc:
                errors.append(f"{state_code} page 1: {type(exc).__name__}")
                logger.debug("Dongdaemun education list fetch failed state=%s: %s", state_code, exc)
                status_pages[state_code] = 0
                declared_pages_by_status[state_code] = 0
                declared_totals_by_status[state_code] = 0
                status_complete[state_code] = False
                continue

            declaration = dongdaemun_education_page_declaration(first_soup)
            if declaration is None:
                errors.append(f"{state_code} page declaration missing")
                declared_total, declared_pages = 0, 1
            else:
                declared_total, current_page, declared_pages = declaration
                if current_page != 1:
                    errors.append(f"{state_code} first page declares current page {current_page}")
            expected_pages = max(
                1,
                (declared_total + DONGDAEMUN_EDUCATION_PAGE_SIZE - 1)
                // DONGDAEMUN_EDUCATION_PAGE_SIZE,
            )
            if declared_pages != expected_pages:
                errors.append(
                    f"{state_code} pagination declares {declared_pages} pages for total {declared_total}"
                )
            allowed_pages = max(1, max_pages)
            if declared_pages > allowed_pages:
                source_cap_reached = True
                errors.append(
                    f"{state_code} max_pages cap allows {allowed_pages} of {declared_pages} pages"
                )

            for page_index in range(1, min(declared_pages, allowed_pages) + 1):
                if page_index == 1:
                    soup = first_soup
                else:
                    page_url = dongdaemun_education_list_url(state_code, page_index)
                    try:
                        soup = fetch_soup(s, page_url, timeout=timeout)
                    except Exception as exc:
                        errors.append(f"{state_code} page {page_index}: {type(exc).__name__}")
                        logger.debug(
                            "Dongdaemun education list fetch failed state=%s page=%s: %s",
                            state_code,
                            page_index,
                            exc,
                        )
                        break

                pages += 1
                state_pages += 1
                page_declaration = dongdaemun_education_page_declaration(soup)
                if page_declaration != (declared_total, page_index, declared_pages):
                    errors.append(f"{state_code} page {page_index} declaration changed during snapshot")
                page_rows, page_invalid = dongdaemun_education_list_rows(
                    target,
                    soup,
                    state_code=state_code,
                    normalized_status=normalized_status,
                    expected_source_status=source_status,
                    page_index=page_index,
                )
                invalid_rows += page_invalid
                expected_page_size = min(
                    DONGDAEMUN_EDUCATION_PAGE_SIZE,
                    max(0, declared_total - (page_index - 1) * DONGDAEMUN_EDUCATION_PAGE_SIZE),
                )
                if len(page_rows) != expected_page_size:
                    errors.append(
                        f"{state_code} page {page_index} exposes {len(page_rows)} of "
                        f"{expected_page_size} declared rows"
                    )
                for row_index, row in enumerate(page_rows):
                    raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
                    expected_ordinal = (
                        declared_total
                        - (page_index - 1) * DONGDAEMUN_EDUCATION_PAGE_SIZE
                        - row_index
                    )
                    if int(raw_fields.get("list_ordinal") or 0) != expected_ordinal:
                        errors.append(
                            f"{state_code} page {page_index} has non-contiguous ordinal for lecture "
                            f"{raw_fields.get('lecture_id')}"
                        )
                    lecture_id = clean_text(raw_fields.get("lecture_id"))
                    if lecture_id in seen_lecture_ids:
                        duplicate_lectures += 1
                        continue
                    seen_lecture_ids.add(lecture_id)
                    state_rows.append(row)

            if len(state_rows) != declared_total:
                errors.append(
                    f"{state_code} declared total {declared_total} does not match "
                    f"{len(state_rows)} unique lectures"
                )
            listed_rows.extend(state_rows)
            status_pages[state_code] = state_pages
            declared_pages_by_status[state_code] = declared_pages
            declared_totals_by_status[state_code] = declared_total
            status_complete[state_code] = (
                len(errors) == state_error_count
                and state_pages == declared_pages
                and len(state_rows) == declared_total
            )

    if invalid_rows:
        errors.append(f"{invalid_rows} course rows were missing canonical list fields")
    if duplicate_lectures:
        errors.append(f"{duplicate_lectures} duplicate lecture IDs crossed state/page boundaries")

    allowed_details = max(0, detail_limit)
    if allowed_details < len(listed_rows):
        source_cap_reached = True
        errors.append(
            f"detail_limit cap allows {allowed_details} of {len(listed_rows)} required detail pages"
        )

    detail_pages = 0
    detail_attempts = 0
    detail_errors: list[str] = []
    for row in listed_rows[:allowed_details]:
        detail_attempts += 1
        raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
        lecture_id = clean_text(raw_fields.get("lecture_id"))
        detail_url = clean_text(row.get("raw_url"))
        try:
            soup = fetch_soup(s, detail_url, timeout=timeout)
            detail_pages += 1
            pairs = pairs_from_tables(soup)
            missing_labels = [
                label
                for label in DONGDAEMUN_EDUCATION_REQUIRED_DETAIL_LABELS
                if not clean_text(pairs.get(label))
            ]
            detail_title, detail_status = dongdaemun_education_detail_title(soup)
            expected_source_status = clean_text(raw_fields.get("source_status"))
            if missing_labels:
                detail_errors.append(f"lecture {lecture_id}: missing {','.join(missing_labels)}")
            if detail_title != clean_text(row.get("title")):
                detail_errors.append(f"lecture {lecture_id}: title mismatch")
            if detail_status != expected_source_status:
                detail_errors.append(f"lecture {lecture_id}: state changed during snapshot")

            application_url = dongdaemun_education_application_link(soup, detail_url, lecture_id)
            if not application_url:
                detail_errors.append(f"lecture {lecture_id}: application endpoint missing")

            detail_current, detail_total, detail_wait_current, detail_wait_total = (
                dongdaemun_education_capacity(pairs.get("접수현황"))
            )
            if detail_current is None or detail_total is None:
                detail_errors.append(f"lecture {lecture_id}: detail capacity missing")
            if (
                detail_current != row.get("capacity_current")
                or detail_total != row.get("capacity_total")
            ):
                detail_errors.append(f"lecture {lecture_id}: detail/list capacity mismatch")
            if row.get("waitlist_current") is not None and detail_wait_current != row.get("waitlist_current"):
                detail_errors.append(f"lecture {lecture_id}: detail/list wait count mismatch")
            if row.get("waitlist_total") is not None and detail_wait_total != row.get("waitlist_total"):
                detail_errors.append(f"lecture {lecture_id}: detail/list wait capacity mismatch")

            venue = clean_text(pairs.get("교육장"))
            if venue != clean_text(row.get("venue_name")):
                detail_errors.append(f"lecture {lecture_id}: detail/list venue mismatch")
            period = bucheon_reservation_datetime_range(pairs.get("교육기간"))
            apply_period = bucheon_reservation_datetime_range(pairs.get("접수기간"))
            address = dongdaemun_education_address(pairs.get("교육장 주소"), venue)
            description = clean_text(pairs.get("강좌소개"))
            row.update(
                {
                    "application_url": application_url or row.get("application_url"),
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": clean_text(pairs.get("교육시간")),
                    "target": clean_text(pairs.get("교육대상")),
                    "eligibility_raw": clean_text(pairs.get("교육대상")),
                    "fee": clean_text(pairs.get("수강료")),
                    "capacity": clean_text(pairs.get("접수현황")),
                    "capacity_current": detail_current,
                    "capacity_total": detail_total,
                    "waitlist_current": detail_wait_current,
                    "waitlist_total": detail_wait_total,
                    "room": venue,
                    "venue_name": venue,
                    "venue_address": address,
                    "instructor": clean_instructor_name(pairs.get("강사명")),
                    "phone": clean_text(pairs.get("문의전화")),
                    "contact": clean_text(pairs.get("문의전화")),
                    "description": description or row.get("description"),
                    "application_method_raw": clean_text(pairs.get("신청방법")),
                    "selection_method_raw": clean_text(pairs.get("선발방법")),
                }
            )
            row["start_date"], row["end_date"] = parse_date_range(period)
            row["apply_start"], row["apply_end"] = parse_date_range(apply_period)
            raw_fields["detail_pairs"] = pairs
            raw_fields["application_endpoint"] = application_url
            row["raw_fields"] = raw_fields
        except Exception as exc:
            detail_errors.append(f"lecture {lecture_id}: {type(exc).__name__}")
            logger.debug(
                "Dongdaemun education detail fetch failed %s: %s",
                safe_url_for_log(detail_url),
                exc,
            )

    if detail_errors:
        errors.append(
            f"detail validation failed for {len(detail_errors)} checks "
            f"({'; '.join(detail_errors[:5])})"
        )

    list_complete = (
        bool(status_complete)
        and all(status_complete.values())
        and not invalid_rows
        and not duplicate_lectures
    )
    details_complete = detail_pages == len(listed_rows) and not detail_errors
    snapshot_complete = list_complete and details_complete and not errors
    no_current_data = snapshot_complete and not listed_rows
    rows = [
        {name: value for name, value in row.items() if value not in (None, "", [], {})}
        for row in listed_rows
    ]
    meta: dict[str, Any] = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "status_pages": status_pages,
        "declared_pages_by_status": declared_pages_by_status,
        "declared_totals_by_status": declared_totals_by_status,
        "status_complete": status_complete,
        "discovered_links": len(seen_lecture_ids),
        "reservation_discovery_links": sum(
            bool(clean_text(row.get("application_url"))) for row in rows
        ),
        "reservation_fallback_pages": 0,
        "pagination_detected": any(value > 1 for value in declared_pages_by_status.values()),
        "pagination_complete": list_complete,
        "pagination_exhausted": list_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached,
        "recursion_depth": 0,
        "current_count": len(rows),
        "no_current_data": no_current_data,
        "no_current_reason": "official scheduled/open/waitlist education list is empty" if no_current_data else "",
        "branch_counts": dict(Counter(clean_text(row.get("branch")) for row in rows)),
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(rows), "dongdaemun_active_course_states+detail", meta


