GANGBUK_EDUCATION_PAGE_SIZE = 100
GANGBUK_EDUCATION_MUNICIPALITY_CODE = "1130500000"
GANGBUK_EDUCATION_MUNICIPALITY_NAME = "서울특별시 강북구"
GANGBUK_EDUCATION_PARSER = "gangbuk_current_education_states+detail"
GANGBUK_EDUCATION_STATES: tuple[tuple[str, str, str], ...] = (
    ("5", "OPEN", "접수중"),
    ("3", "SCHEDULED", "접수대기"),
)
