def is_mapo_education_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == MAPO_EDUCATION_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == MAPO_EDUCATION_HOST
        and parsed.path == MAPO_EDUCATION_LIST_PATH
        and not parsed.params
        and not parsed.query
        and not parsed.fragment
    )


def mapo_education_today() -> str:
    return datetime.now(ZoneInfo("Asia/Seoul")).date().isoformat()


def mapo_education_list_url(scope: str, page_index: int, today: str) -> str:
    query: list[tuple[str, str]] = []
    if scope == "future":
        query.extend((("ltEduSday", today), ("ltEduEday", MAPO_EDUCATION_FUTURE_END)))
    elif scope == "ongoing":
        query.append(("lecstate", "L0705"))
    else:
        raise ValueError(f"unsupported Mapo education scope: {scope}")
    query.append(("cp", str(max(1, page_index))))
    return f"https://{MAPO_EDUCATION_HOST}{MAPO_EDUCATION_LIST_PATH}?{urlencode(query)}"


def mapo_education_detail_url(lecture_id: Any) -> str:
    return (
        f"https://{MAPO_EDUCATION_HOST}{MAPO_EDUCATION_DETAIL_PATH}?"
        f"{urlencode((('ltSeq', clean_text(lecture_id)),))}"
    )


def mapo_education_application_url(lecture_id: Any) -> str:
    return (
        f"https://{MAPO_EDUCATION_HOST}{MAPO_EDUCATION_APPLICATION_PATH}?"
        f"{urlencode((('ltSeq', clean_text(lecture_id)),))}"
    )


def mapo_education_selected_value(soup: BeautifulSoup, name: str) -> str:
    node = soup.select_one(f"form#frm [name='{name}']")
    if node is None:
        return ""
    if node.name != "select":
        return clean_text(node.get("value"))
    selected = node.select_one("option[selected]")
    return clean_text(selected.get("value") if selected else "")


def mapo_education_page_link_number(link: Any) -> Optional[int]:
    if link is None:
        return None
    parsed = urlparse(
        normalize_link(
            f"https://{MAPO_EDUCATION_HOST}{MAPO_EDUCATION_LIST_PATH}",
            link.get("href"),
        )
    )
    if (
        parsed.scheme.lower() != "https"
        or parsed.netloc.lower() != MAPO_EDUCATION_HOST
        or parsed.path != MAPO_EDUCATION_LIST_PATH
    ):
        return None
    value = clean_text((parse_qs(parsed.query, keep_blank_values=True).get("cp") or [""])[0])
    return int(value) if value.isdigit() and int(value) > 0 else None


def mapo_education_page_declaration(
    soup: BeautifulSoup,
) -> Optional[tuple[int, int, int]]:
    total_node = soup.select_one(".total-num span")
    total_text = clean_text(total_node.get_text(" ", strip=True) if total_node else "")
    total_digits = re.sub(r"[^0-9]", "", total_text)
    if not total_digits:
        return None
    total = int(total_digits)
    expected_pages = max(1, (total + MAPO_EDUCATION_PAGE_SIZE - 1) // MAPO_EDUCATION_PAGE_SIZE)
    current_link = soup.select_one(".bbs_paging a.now[title='현재 페이지']")
    last_link = soup.select_one(".bbs_paging a[title='마지막 페이지']")
    current_page = mapo_education_page_link_number(current_link)
    last_page = mapo_education_page_link_number(last_link)
    if current_page is None and total == 0:
        current_page = 1
    if last_page is None and expected_pages == 1:
        last_page = 1
    if current_page is None or last_page is None:
        return None
    return total, current_page, last_page


def mapo_education_short_date_ranges(value: Any) -> list[tuple[str, str]]:
    text = clean_text(value)
    matches = list(
        re.finditer(
            r"(?<!\d)(\d{2})[.](\d{2})[.](\d{2})\s*~\s*"
            r"(\d{2})[.](\d{2})[.](\d{2})(?!\d)",
            text,
        )
    )
    ranges: list[tuple[str, str]] = []
    for match in matches:
        try:
            start = datetime.strptime(
                f"20{match.group(1)}-{match.group(2)}-{match.group(3)}", "%Y-%m-%d"
            ).date()
            end = datetime.strptime(
                f"20{match.group(4)}-{match.group(5)}-{match.group(6)}", "%Y-%m-%d"
            ).date()
        except ValueError:
            return []
        ranges.append((start.isoformat(), end.isoformat()))
    return ranges


def mapo_education_detail_date_range(value: Any) -> str:
    text = clean_text(value)
    matches = list(
        re.finditer(r"(?<!\d)(\d{4})-(\d{2})-(\d{2})(?!\d)", text)
    )
    if len(matches) < 2:
        return ""
    values: list[str] = []
    for match in matches[:2]:
        candidate = f"{match.group(1)}-{match.group(2)}-{match.group(3)}"
        try:
            values.append(datetime.strptime(candidate, "%Y-%m-%d").date().isoformat())
        except ValueError:
            return ""
    return f"{values[0]} ~ {values[1]}"


def mapo_education_status(value: Any) -> str:
    mapping = {
        "접수예정": "SCHEDULED",
        "접수중": "OPEN",
        "오늘마감": "OPEN",
        "접수마감": "CLOSED",
        "교육중": "CLOSED",
        "교육완료": "CLOSED",
    }
    return mapping.get(clean_text(value), "")


def mapo_education_list_capacity(
    value: Any,
) -> tuple[Optional[int], Optional[int], Optional[int]]:
    match = re.fullmatch(
        r"\s*(\d[\d,]*)\s*/\s*(\d[\d,]*)\s*/\s*(\d[\d,]*)\s*",
        clean_text(value),
    )
    if not match:
        return None, None, None
    return tuple(int(match.group(index).replace(",", "")) for index in (1, 2, 3))  # type: ignore[return-value]


def mapo_education_detail_capacity(value: Any) -> tuple[Optional[int], Optional[int]]:
    match = re.fullmatch(
        r"\s*(\d[\d,]*)\s*명?\s*/\s*(\d[\d,]*)\s*명?\s*",
        clean_text(value),
    )
    if not match:
        return None, None
    return int(match.group(1).replace(",", "")), int(match.group(2).replace(",", ""))


def mapo_education_table(soup: BeautifulSoup) -> Any:
    return soup.select_one(".page-style.page-style02.on .bbs_list table")


def mapo_education_list_rows(
    target: CrawlTarget,
    soup: BeautifulSoup,
    *,
    scope: str,
    page_index: int,
    declared_total: int,
    today: str,
) -> tuple[list[dict[str, Any]], int, int, int]:
    table = mapo_education_table(soup)
    if table is None:
        return [], 1, 0, 0
    rows: list[dict[str, Any]] = []
    invalid_rows = 0
    invalid_periods = 0
    out_of_scope = 0
    row_position = 0
    for tr in table.select("tbody tr"):
        cells = tr.find_all("td", recursive=False)
        if not cells:
            continue
        if len(cells) == 1 and declared_total == 0:
            continue
        if len(cells) != 10:
            invalid_rows += 1
            continue
        row_position += 1
        ordinal_text = re.sub(r"[^0-9]", "", clean_text(cells[0].get_text(" ", strip=True)))
        expected_ordinal = declared_total - ((page_index - 1) * MAPO_EDUCATION_PAGE_SIZE + row_position - 1)
        link = cells[1].select_one("a[href*='lecture_view']")
        linked_url = normalize_link(target.url, link.get("href")) if link else ""
        parsed_link = urlparse(linked_url)
        linked_query = parse_qs(parsed_link.query, keep_blank_values=True)
        lecture_id = clean_text((linked_query.get("ltSeq") or [""])[0])
        title = clean_text(link.get_text(" ", strip=True) if link else "")
        date_text = clean_text(cells[2].get_text(" ", strip=True))
        date_ranges = mapo_education_short_date_ranges(date_text)
        branch = clean_text(cells[3].get_text(" ", strip=True))
        venue = clean_text(cells[4].get_text(" ", strip=True))
        fee = clean_text(cells[5].get_text(" ", strip=True))
        selection_method = clean_text(cells[6].get_text(" ", strip=True))
        list_capacity = clean_text(cells[7].get_text(" ", strip=True))
        capacity_total, waitlist_total, capacity_current = mapo_education_list_capacity(
            list_capacity
        )
        source_status = clean_text(cells[8].get_text(" ", strip=True))
        status = mapo_education_status(source_status)
        list_application_method = clean_text(cells[9].get_text(" ", strip=True))
        valid_identity = (
            parsed_link.scheme.lower() == "https"
            and parsed_link.netloc.lower() == MAPO_EDUCATION_HOST
            and parsed_link.path == MAPO_EDUCATION_DETAIL_PATH
            and lecture_id.isdigit()
        )
        if (
            not ordinal_text.isdigit()
            or int(ordinal_text) != expected_ordinal
            or not valid_identity
            or not title
            or len(date_ranges) != 2
            or not branch
            or not venue
            or not fee
            or not selection_method
            or capacity_total is None
            or waitlist_total is None
            or capacity_current is None
            or not status
            or (scope == "ongoing" and source_status != "교육중")
        ):
            invalid_rows += 1
            continue

        (apply_start, apply_end), (education_start, education_end) = date_ranges
        if apply_start > apply_end:
            invalid_periods += 1
            continue
        if education_start > education_end:
            invalid_periods += 1
            continue
        in_scope = education_end >= today and (
            (scope == "future" and education_start >= today)
            or (scope == "ongoing" and education_start <= today <= education_end)
        )
        if not in_scope:
            out_of_scope += 1
            continue

        detail_url = mapo_education_detail_url(lecture_id)
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": f"mapo:{lecture_id}",
                "prefer_incoming_provider_course_id": True,
                "title": title,
                "branch": branch,
                "branch_code": stable_provider("MAPO_BRANCH", branch),
                "preserve_branch": True,
                "branch_url": target.url,
                "category": branch,
                "program_type": "강좌",
                "raw_url": detail_url,
                "reservation_available": False,
                "status": status,
                "period": f"{education_start} ~ {education_end}",
                "apply_period": f"{apply_start} ~ {apply_end}",
                "schedule_raw": date_text,
                "fee": fee,
                "capacity": list_capacity,
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "waitlist_total": waitlist_total,
                "room": venue,
                "venue_name": venue,
                "application_method_raw": list_application_method,
                "selection_method_raw": selection_method,
                "description": clean_text(tr.get_text(" ", strip=True)),
                "collection_category": "공공예약",
                "domain_category": "교육·강좌",
                "operator_type": "지자체/공공기관",
                "source_group": "municipal_reservation",
                "collection_type": "current_future_date_status+detail_html",
                "service_group": "공공강좌",
                "service_group_policy": "locked",
                "municipality_code": MAPO_EDUCATION_MUNICIPALITY_CODE,
                "municipality_full_name": MAPO_EDUCATION_MUNICIPALITY_NAME,
                "raw_fields": {
                    "parser": MAPO_EDUCATION_PARSER,
                    "lecture_id": lecture_id,
                    "scope": scope,
                    "source_status": source_status,
                    "page_index": page_index,
                    "ordinal": int(ordinal_text),
                    "list_capacity": list_capacity,
                    "list_application_method": list_application_method,
                    "list_cells": [clean_text(cell.get_text(" ", strip=True)) for cell in cells],
                },
            }
        )
        rows[-1]["start_date"], rows[-1]["end_date"] = parse_date_range(rows[-1]["period"])
        rows[-1]["apply_start"], rows[-1]["apply_end"] = parse_date_range(
            rows[-1]["apply_period"]
        )
    return rows, invalid_rows, invalid_periods, out_of_scope


def mapo_education_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    table = soup.select_one("#contents .dpc-table table")
    if table is None:
        return {}
    pairs: dict[str, str] = {}
    for tr in table.select("tr"):
        key = ""
        for node in tr.find_all(["th", "td"], recursive=False):
            if node.name == "th":
                key = clean_text(node.get_text(" ", strip=True))
            elif key:
                pairs[key] = clean_text(node.get_text(" ", strip=True))
                key = ""
    return pairs


def mapo_education_detail_header(soup: BeautifulSoup) -> tuple[str, str]:
    header = soup.select_one("#contents .dt-page-title")
    if header is None:
        return "", ""
    title_node = header.select_one("p.dpt-p")
    status_node = header.select_one("p.text-btn")
    return (
        clean_text(title_node.get_text(" ", strip=True) if title_node else ""),
        clean_text(status_node.get_text(" ", strip=True) if status_node else ""),
    )


def mapo_education_application_link(
    soup: BeautifulSoup,
    detail_url: str,
    lecture_id: str,
) -> str:
    matches: list[str] = []
    for link in soup.select("#contents a[href*='lecture_inscr_step01']"):
        linked_url = normalize_link(detail_url, link.get("href"))
        parsed = urlparse(linked_url)
        query = parse_qs(parsed.query, keep_blank_values=True)
        if (
            parsed.scheme.lower() == "https"
            and parsed.netloc.lower() == MAPO_EDUCATION_HOST
            and parsed.path == MAPO_EDUCATION_APPLICATION_PATH
            and query == {"ltSeq": [clean_text(lecture_id)]}
            and not parsed.fragment
        ):
            matches.append(mapo_education_application_url(lecture_id))
    return matches[0] if len(matches) == 1 else ""


def collect_mapo_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    errors: list[str] = []
    if not is_mapo_education_target(target):
        errors.append("target does not match the canonical Mapo education source")

    today = mapo_education_today()
    s = session()
    listed_rows: list[dict[str, Any]] = []
    retained_by_id: dict[str, dict[str, Any]] = {}
    pages = 0
    invalid_rows = 0
    invalid_periods = 0
    out_of_scope = 0
    cross_scope_duplicates = 0
    source_cap_reached = False
    scope_pages: dict[str, int] = {}
    declared_pages_by_scope: dict[str, int] = {}
    declared_totals_by_scope: dict[str, int] = {}
    scope_complete: dict[str, bool] = {}

    if not errors:
        for scope, state_code in MAPO_EDUCATION_SCOPES:
            scope_error_count = len(errors)
            scope_rows: list[dict[str, Any]] = []
            scope_ids: set[str] = set()
            scope_exposed_rows = 0
            scope_invalid_rows = 0
            scope_page_count = 0
            first_url = mapo_education_list_url(scope, 1, today)
            try:
                first_soup = fetch_soup(s, first_url, timeout=timeout)
            except Exception as exc:
                errors.append(f"{scope} page 1: {type(exc).__name__}")
                logger.debug("Mapo education list fetch failed scope=%s: %s", scope, exc)
                scope_pages[scope] = 0
                declared_pages_by_scope[scope] = 0
                declared_totals_by_scope[scope] = 0
                scope_complete[scope] = False
                continue

            declaration = mapo_education_page_declaration(first_soup)
            if declaration is None:
                errors.append(f"{scope} page declaration missing")
                declared_total, declared_pages = 0, 1
            else:
                declared_total, current_page, declared_pages = declaration
                expected_pages = max(
                    1,
                    (declared_total + MAPO_EDUCATION_PAGE_SIZE - 1)
                    // MAPO_EDUCATION_PAGE_SIZE,
                )
                if current_page != 1 or declared_pages != expected_pages:
                    errors.append(
                        f"{scope} first page declares {declared_total} rows, "
                        f"current {current_page}, last {declared_pages}"
                    )
            allowed_pages = max(1, max_pages)
            if declared_pages > allowed_pages:
                source_cap_reached = True
                errors.append(
                    f"{scope} max_pages cap allows {allowed_pages} of {declared_pages} pages"
                )

            for page_index in range(1, min(declared_pages, allowed_pages) + 1):
                if page_index == 1:
                    soup = first_soup
                else:
                    try:
                        soup = fetch_soup(
                            s,
                            mapo_education_list_url(scope, page_index, today),
                            timeout=timeout,
                        )
                    except Exception as exc:
                        errors.append(f"{scope} page {page_index}: {type(exc).__name__}")
                        logger.debug(
                            "Mapo education list fetch failed scope=%s page=%s: %s",
                            scope,
                            page_index,
                            exc,
                        )
                        break

                pages += 1
                scope_page_count += 1
                page_declaration = mapo_education_page_declaration(soup)
                if page_declaration != (declared_total, page_index, declared_pages):
                    errors.append(f"{scope} page {page_index} declaration changed during snapshot")
                headers = tuple(
                    clean_text(node.get_text(" ", strip=True))
                    for node in (mapo_education_table(soup).select("tbody tr th") if mapo_education_table(soup) else [])
                )
                if headers != MAPO_EDUCATION_HEADERS:
                    errors.append(f"{scope} page {page_index} table contract changed")
                actual_state = mapo_education_selected_value(soup, "lecstate")
                actual_start = mapo_education_selected_value(soup, "ltEduSday")
                actual_end = mapo_education_selected_value(soup, "ltEduEday")
                if scope == "future":
                    filter_matches = (
                        not actual_state and actual_start == today and actual_end == MAPO_EDUCATION_FUTURE_END
                    )
                else:
                    filter_matches = actual_state == state_code and not actual_start and not actual_end
                if not filter_matches:
                    errors.append(f"{scope} page {page_index} filter state changed")

                page_rows, page_invalid, page_invalid_periods, page_out_of_scope = (
                    mapo_education_list_rows(
                        target,
                        soup,
                        scope=scope,
                        page_index=page_index,
                        declared_total=declared_total,
                        today=today,
                    )
                )
                invalid_rows += page_invalid
                scope_invalid_rows += page_invalid
                invalid_periods += page_invalid_periods
                out_of_scope += page_out_of_scope
                exposed_on_page = len(page_rows) + page_invalid_periods + page_out_of_scope
                scope_exposed_rows += exposed_on_page
                expected_on_page = max(
                    0,
                    min(
                        MAPO_EDUCATION_PAGE_SIZE,
                        declared_total - ((page_index - 1) * MAPO_EDUCATION_PAGE_SIZE),
                    ),
                )
                if exposed_on_page + page_invalid != expected_on_page:
                    errors.append(
                        f"{scope} page {page_index} exposes "
                        f"{exposed_on_page + page_invalid} of {expected_on_page} declared rows"
                    )

                for row in page_rows:
                    raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
                    lecture_id = clean_text(raw_fields.get("lecture_id"))
                    if lecture_id in scope_ids:
                        errors.append(f"{scope} duplicate lecture ID {lecture_id}")
                        continue
                    scope_ids.add(lecture_id)
                    scope_rows.append(row)

            listed_rows.extend(scope_rows)
            scope_pages[scope] = scope_page_count
            declared_pages_by_scope[scope] = declared_pages
            declared_totals_by_scope[scope] = declared_total
            scope_complete[scope] = (
                len(errors) == scope_error_count
                and scope_page_count == declared_pages
                and scope_exposed_rows + scope_invalid_rows == declared_total
            )

    if invalid_rows:
        errors.append(f"{invalid_rows} course rows were missing canonical list fields")

    for row in listed_rows:
        raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
        lecture_id = clean_text(raw_fields.get("lecture_id"))
        previous = retained_by_id.get(lecture_id)
        if previous is None:
            retained_by_id[lecture_id] = row
            continue
        cross_scope_duplicates += 1
        comparable_fields = ("title", "period", "branch", "venue_name", "status")
        if any(clean_text(previous.get(key)) != clean_text(row.get(key)) for key in comparable_fields):
            errors.append(f"lecture {lecture_id} changed across future/ongoing scopes")

    listed_rows = list(retained_by_id.values())
    allowed_details = max(0, detail_limit)
    if allowed_details < len(listed_rows):
        source_cap_reached = True
        errors.append(
            f"detail_limit cap allows {allowed_details} of {len(listed_rows)} required detail pages"
        )

    detail_pages = 0
    detail_attempts = 0
    detail_errors: list[str] = []
    for row in listed_rows[:allowed_details]:
        detail_attempts += 1
        raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
        lecture_id = clean_text(raw_fields.get("lecture_id"))
        detail_url = clean_text(row.get("raw_url"))
        try:
            soup = fetch_soup(s, detail_url, timeout=timeout)
            detail_pages += 1
            pairs = mapo_education_detail_pairs(soup)
            missing_keys = [key for key in MAPO_EDUCATION_DETAIL_KEYS if key not in pairs]
            missing_values = [
                key
                for key in MAPO_EDUCATION_REQUIRED_DETAIL_VALUES
                if not clean_text(pairs.get(key))
            ]
            detail_title, detail_source_status = mapo_education_detail_header(soup)
            if missing_keys:
                detail_errors.append(f"lecture {lecture_id}: missing keys {','.join(missing_keys)}")
            if missing_values:
                detail_errors.append(f"lecture {lecture_id}: empty values {','.join(missing_values)}")
            if detail_title != clean_text(row.get("title")):
                detail_errors.append(f"lecture {lecture_id}: title mismatch")
            if detail_source_status != clean_text(raw_fields.get("source_status")):
                detail_errors.append(f"lecture {lecture_id}: state changed during snapshot")

            detail_period = mapo_education_detail_date_range(pairs.get("교육기간"))
            detail_apply_dates = mapo_education_detail_date_range(pairs.get("접수기간"))
            if detail_period != clean_text(row.get("period")):
                detail_errors.append(f"lecture {lecture_id}: education period mismatch")
            list_apply_dates = clean_text(row.get("apply_period"))
            if detail_apply_dates != list_apply_dates:
                detail_errors.append(f"lecture {lecture_id}: application period mismatch")

            branch = clean_text(pairs.get("강좌분야"))
            venue = clean_text(pairs.get("교육장소"))
            if branch != clean_text(row.get("branch")):
                detail_errors.append(f"lecture {lecture_id}: branch mismatch")
            if venue != clean_text(row.get("venue_name")):
                detail_errors.append(f"lecture {lecture_id}: venue mismatch")

            capacity_current, capacity_total = mapo_education_detail_capacity(
                pairs.get("신청/정원")
            )
            waitlist_current, waitlist_total = mapo_education_detail_capacity(
                pairs.get("신청/대기자")
            )
            if None in (capacity_current, capacity_total, waitlist_current, waitlist_total):
                detail_errors.append(f"lecture {lecture_id}: capacity contract changed")

            application_method = clean_text(pairs.get("접수방법"))
            application_url = mapo_education_application_link(soup, detail_url, lecture_id)
            is_open = clean_text(row.get("status")) == "OPEN"
            is_online = "인터넷" in application_method
            if is_open and is_online and not application_url:
                detail_errors.append(f"lecture {lecture_id}: online application endpoint missing")

            description_node = soup.select_one("#contents .lesson-intro-cont")
            description = clean_text(
                description_node.get_text(" ", strip=True) if description_node else ""
            )
            detail_apply_period = bucheon_reservation_datetime_range(pairs.get("접수기간"))
            row.update(
                {
                    "branch": branch,
                    "branch_code": stable_provider("MAPO_BRANCH", branch),
                    "branch_url": target.url,
                    "category": branch,
                    "period": detail_period,
                    "apply_period": detail_apply_period,
                    "schedule_raw": clean_text(
                        f"{pairs.get('교육요일')} {pairs.get('교육기간')}"
                    ),
                    "target": clean_text(pairs.get("교육대상")),
                    "eligibility_raw": clean_text(pairs.get("교육대상")),
                    "fee": clean_text(pairs.get("수강료")),
                    "capacity": clean_text(pairs.get("신청/정원")),
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "waitlist_current": waitlist_current,
                    "waitlist_total": waitlist_total,
                    "room": venue,
                    "venue_name": venue,
                    "instructor": clean_instructor_name(pairs.get("강사명")),
                    "phone": clean_text(pairs.get("문의처")),
                    "contact": clean_text(pairs.get("문의처")),
                    "description": description or row.get("description"),
                    "application_method_raw": application_method,
                    "selection_method_raw": clean_text(pairs.get("선정방법")),
                    "reservation_available": bool(is_open and application_url),
                    "application_type": (
                        "ONLINE_RESERVATION"
                        if application_url
                        else "OFFLINE_APPLY"
                        if any(token in application_method for token in ("전화", "방문"))
                        else "INFO_ONLY"
                    ),
                }
            )
            if application_url:
                row["application_url"] = application_url
            row["start_date"], row["end_date"] = parse_date_range(detail_period)
            row["apply_start"], row["apply_end"] = parse_date_range(detail_apply_period)
            raw_fields["detail_pairs"] = pairs
            raw_fields["application_endpoint"] = application_url
            raw_fields["detail_description_present"] = bool(description)
            row["raw_fields"] = raw_fields
        except Exception as exc:
            detail_errors.append(f"lecture {lecture_id}: {type(exc).__name__}")
            logger.debug(
                "Mapo education detail fetch failed %s: %s",
                safe_url_for_log(detail_url),
                exc,
            )

    if detail_errors:
        errors.append(
            f"detail validation failed for {len(detail_errors)} checks "
            f"({'; '.join(detail_errors[:5])})"
        )

    list_complete = (
        bool(scope_complete)
        and all(scope_complete.values())
        and not invalid_rows
    )
    details_complete = detail_pages == len(listed_rows) and not detail_errors
    snapshot_complete = list_complete and details_complete and not errors
    no_current_data = snapshot_complete and not listed_rows
    rows = [
        {name: value for name, value in row.items() if value not in (None, "", [], {})}
        for row in listed_rows
    ]
    meta: dict[str, Any] = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "scope_pages": scope_pages,
        "declared_pages_by_scope": declared_pages_by_scope,
        "declared_totals_by_scope": declared_totals_by_scope,
        "declared_total_source": "official .total-num and terminal page row count",
        "scope_complete": scope_complete,
        "invalid_period_count": invalid_periods,
        "out_of_scope_count": out_of_scope,
        "cross_scope_duplicates": cross_scope_duplicates,
        "discovered_links": len(listed_rows),
        "reservation_discovery_links": sum(
            bool(clean_text(row.get("application_url"))) for row in rows
        ),
        "reservation_fallback_pages": 0,
        "pagination_detected": any(value > 1 for value in declared_pages_by_scope.values()),
        "pagination_complete": list_complete,
        "pagination_exhausted": list_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached,
        "recursion_depth": 0,
        "current_count": len(rows),
        "no_current_data": no_current_data,
        "no_current_reason": "official current/future education list is empty" if no_current_data else "",
        "branch_counts": dict(Counter(clean_text(row.get("branch")) for row in rows)),
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(rows), MAPO_EDUCATION_PARSER, meta


