def sdm_public_course_fields(collection_type: str) -> dict[str, Any]:
    return {
        "program_type": "강좌",
        "collection_category": "공공예약",
        "domain_category": "교육·강좌",
        "source_group": "municipal_reservation",
        "operator_type": "지자체/공공기관",
        "collection_type": collection_type,
        "service_group": "공공강좌",
        "service_group_policy": "locked",
        "municipality_code": SDM_MUNICIPALITY_CODE,
        "municipality_full_name": SDM_MUNICIPALITY_NAME,
    }


def sdm_branch_code(prefix: str, branch: Any) -> str:
    name = clean_text(branch)
    digest = hashlib.sha1(name.encode("utf-8")).hexdigest()[:12].upper()
    return f"{prefix}_{digest}"


def sdm_status(value: Any) -> str:
    text = clean_text(value)
    compact = re.sub(r"\s+", "", text)
    if "대기자접수" in compact:
        return "WAITING"
    for raw, normalized in SDM_STATUS_MAP.items():
        if re.sub(r"\s+", "", raw) in compact:
            return normalized
    return text


def sdm_date_range(value: Any) -> str:
    text = clean_text(value).replace("\xa0", " ")
    text = re.sub(
        r"(\d{4})\s*년\s*(\d{1,2})\s*월\s*(\d{1,2})\s*일",
        lambda match: f"{int(match.group(1)):04d}-{int(match.group(2)):02d}-{int(match.group(3)):02d}",
        text,
    )
    matches = re.findall(
        r"(?<!\d)(\d{4})[.\-/](\d{1,2})[.\-/](\d{1,2})(?:\s+(\d{1,2}:\d{2}))?",
        text,
    )
    values: list[str] = []
    for year, month, day, clock in matches[:2]:
        value = f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
        if clock:
            value = f"{value} {clock}"
        values.append(value)
    if len(values) >= 2:
        return values[0] if values[0] == values[1] else f"{values[0]} ~ {values[1]}"
    return values[0] if values else ""


def sdm_period_end(value: Any) -> Optional[datetime]:
    matches = re.findall(r"\b(20\d{2}-\d{2}-\d{2})\b", clean_text(value))
    if not matches:
        return None
    try:
        return datetime.strptime(matches[-1], "%Y-%m-%d")
    except ValueError:
        return None


def sdm_fetch_soups_parallel(
    urls: list[str],
    timeout: int,
    *,
    workers: int = 4,
) -> tuple[dict[int, BeautifulSoup], dict[int, str]]:
    soups: dict[int, BeautifulSoup] = {}
    failures: dict[int, str] = {}
    if not urls:
        return soups, failures
    batches: list[list[tuple[int, str]]] = [
        [] for _ in range(min(max(1, workers), len(urls)))
    ]
    for index, url in enumerate(urls):
        batches[index % len(batches)].append((index, url))

    def fetch_batch(batch: list[tuple[int, str]]) -> tuple[dict[int, BeautifulSoup], dict[int, str]]:
        detail_session = session()
        fetched: dict[int, BeautifulSoup] = {}
        errors: dict[int, str] = {}
        try:
            for index, url in batch:
                try:
                    fetched[index] = fetch_soup(detail_session, url, timeout=timeout)
                except Exception as exc:
                    errors[index] = type(exc).__name__
                    logger.debug(
                        "Seodaemun detail fetch failed url=%s error_type=%s",
                        safe_url_for_log(url),
                        type(exc).__name__,
                    )
        finally:
            closer = getattr(detail_session, "close", None)
            if callable(closer):
                closer()
        return fetched, errors

    with ThreadPoolExecutor(max_workers=len(batches), thread_name_prefix="sdm-detail") as executor:
        for fetched, errors in executor.map(fetch_batch, batches):
            soups.update(fetched)
            failures.update(errors)
    return soups, failures


def is_sdm_apply_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == SDM_APPLY_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == SDM_APPLY_HOST
        and parsed.path == SDM_APPLY_PATH
        and not parsed.query
    )


def is_sdm_lifelong_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    return (
        target.provider == SDM_LIFELONG_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == SDM_LIFELONG_HOST
        and parsed.path == SDM_LIFELONG_PATH
        and query == {"itemCd1": ["04"], "page": ["1"]}
    )


def is_sscmc_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == SSCMC_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == SSCMC_HOST
        and parsed.path == "/"
        and not parsed.query
    )


def sdm_apply_post_soup(
    s: requests.Session,
    scope: str,
    page: int,
    timeout: int,
) -> BeautifulSoup:
    body = urlencode(
        {
            "mode": "list",
            "formSeq": "",
            "seq": "",
            "cp": str(page),
            "schAltMsg": scope,
            "keycol": "",
            "keyword": "",
        },
        encoding="euc-kr",
    ).encode("ascii")
    response = s.post(
        SDM_APPLY_LIST_URL,
        data=body,
        headers={
            "Content-Type": "application/x-www-form-urlencoded",
            "Referer": SDM_APPLY_LIST_URL,
        },
        timeout=timeout,
    )
    response.raise_for_status()
    return BeautifulSoup(response.content.decode("euc-kr"), "lxml")


def sdm_apply_declared_pages(soup: BeautifulSoup, current_page: int = 1) -> int:
    pages = [
        int(match.group(1))
        for anchor in soup.select("a[href]")
        if (match := re.search(r"goPage\(\s*(\d+)\s*\)", clean_text(anchor.get("href"))))
    ]
    # The official pager renders the current page as plain text instead of a
    # goPage() link.  On the terminal page the largest link is therefore one
    # less than the real terminal page unless the requested page is included.
    return max([max(1, current_page), *pages])


def sdm_apply_list_rows(
    target: CrawlTarget,
    soup: BeautifulSoup,
    scope: str,
    page: int,
) -> tuple[list[dict[str, Any]], int]:
    rows: list[dict[str, Any]] = []
    malformed = 0
    for tr in soup.select("table tbody tr"):
        anchor = tr.find("a", href=lambda value: bool(value and "goView" in value))
        identity_match = re.search(r"goView\(\s*['\"]?(\d+)", clean_text(anchor.get("href")) if anchor else "")
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
        if not anchor or not identity_match or len(cells) < 6:
            if cells:
                malformed += 1
            continue
        seq = identity_match.group(1)
        title = clean_text(anchor.get_text(" ", strip=True))
        if not title:
            malformed += 1
            continue
        status_cell = tr.find_all("td")[3] if len(tr.find_all("td")) > 3 else None
        status_image = status_cell.find("img", alt=True) if status_cell else None
        status_raw = clean_text(status_image.get("alt") if status_image else scope)
        has_application_control = bool(
            tr.find(attrs={"onclick": re.compile(r"goYeyakApp", re.IGNORECASE)})
        )
        raw_url = f"{SDM_APPLY_LIST_URL}?{urlencode({'mode': 'view', 'seq': seq})}"
        application_url = (
            f"{SDM_APPLY_LIST_URL}?{urlencode({'mode': 'appRegFrm', 'formSeq': seq})}"
            if scope == "신청" and has_application_control
            else ""
        )
        row: dict[str, Any] = {
            "provider": target.provider,
            "provider_course_id": f"{target.provider}:form:{seq}",
            "prefer_incoming_provider_course_id": True,
            "title": title,
            "branch": target.branch or "서대문구 통합신청",
            "branch_code": sdm_branch_code("SDM_APPLY", target.branch or "서대문구 통합신청"),
            "branch_url": SDM_APPLY_LIST_URL,
            "preserve_branch": True,
            "raw_url": raw_url,
            "status": sdm_status(status_raw or scope),
            "apply_period": sdm_date_range(cells[4]),
            "capacity": cells[2],
            "reservation_available": bool(application_url),
            "application_url": application_url,
            "application_method_raw": clean_text(cells[6] if len(cells) > 6 else ""),
            "description": title,
            **sdm_public_course_fields("euc_kr_post_status+detail_html"),
            "raw_fields": {
                "parser": SDM_APPLY_PARSER,
                "official_form_seq": seq,
                "status_scope": scope,
                "status_raw": status_raw,
                "list_page": page,
                "list_cells": cells,
                "has_application_control": has_application_control,
                "clear_application_url": not bool(application_url),
            },
        }
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
    return rows, malformed


def sdm_apply_detail_fields(
    soup: BeautifulSoup,
    expected_title: str,
    expected_scope: str,
) -> tuple[Optional[dict[str, Any]], str]:
    table = soup.find("table")
    if not table:
        return None, "missing official detail table"
    pairs = pairs_from_tables(table)
    title = clean_text(pairs.get("제목"))
    if title != clean_text(expected_title):
        return None, "detail title did not match the official list title"
    status_raw = clean_text(pairs.get("접수상태"))
    if re.sub(r"\s+", "", expected_scope) not in re.sub(r"\s+", "", status_raw):
        return None, "detail status did not match the requested status scope"
    capacity = clean_text(pairs.get("신청/모집/예비인원"))
    capacity_match = re.search(r"([\d,]+)\s*/\s*([\d,]+)(?:\s*/\s*([\d,]+))?", capacity)
    description_candidates = [
        clean_text(cell.get_text(" ", strip=True))
        for cell in table.find_all("td")
        if len(clean_text(cell.get_text(" ", strip=True))) >= 20
    ]
    description = max(description_candidates, key=len, default=expected_title)[:8000]
    schedule_match = re.search(
        r"(?:운영일시|교육기간|운영기간|일시)\s*[:：]\s*([^○●◆ㅁ※]{4,160})",
        description,
    )
    schedule_raw = clean_text(schedule_match.group(1)) if schedule_match else ""
    period = sdm_date_range(schedule_raw)
    phone = clean_text(pairs.get("문의처"))
    phone_match = re.search(r"(?:0\d{1,2}[)\-\s]?)?\d{3,4}[-\s]\d{4}", phone)
    has_application_control = any(
        "goNext" in clean_text(anchor.get("href"))
        for anchor in soup.select("a[href]")
    )
    return {
        "period": period,
        "schedule_raw": schedule_raw,
        "apply_period": sdm_date_range(status_raw),
        "target": clean_text(pairs.get("신청대상")),
        "room": clean_text(pairs.get("장소")),
        "venue_name": clean_text(pairs.get("장소")),
        "fee": clean_text(pairs.get("비용")),
        "phone": clean_text(phone_match.group(0)) if phone_match else phone,
        "capacity": capacity,
        "capacity_current": int(capacity_match.group(1).replace(",", "")) if capacity_match else None,
        "capacity_total": int(capacity_match.group(2).replace(",", "")) if capacity_match else None,
        "waitlist_total": int(capacity_match.group(3).replace(",", "")) if capacity_match and capacity_match.group(3) else None,
        "description": description,
        "has_application_control": has_application_control,
        "raw_detail_pairs": pairs,
    }, ""


def collect_sdm_apply_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    errors: list[str] = []
    if not is_sdm_apply_target(target):
        errors.append("target does not match the canonical HTTPS integrated-application owner")
    s = session()
    listed_rows: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    pages = 0
    raw_row_count = 0
    invalid_rows = 0
    duplicate_rows = 0
    excluded_counts: Counter[str] = Counter()
    declared_pages_by_scope: dict[str, int] = {}
    declared_totals_by_scope: dict[str, int] = {}
    source_cap_reached = False

    for scope in SDM_APPLY_SCOPES if not errors else ():
        try:
            first_soup = sdm_apply_post_soup(s, scope, 1, timeout)
        except Exception as exc:
            logger.warning(
                "Seodaemun application list fetch failed scope=%s page=1 error_type=%s",
                scope,
                type(exc).__name__,
            )
            errors.append(f"{scope} page 1: {type(exc).__name__}")
            break
        declared_pages = sdm_apply_declared_pages(first_soup)
        declared_pages_by_scope[scope] = declared_pages
        if pages + declared_pages > max(0, max_pages):
            source_cap_reached = True
            errors.append(
                f"max_pages cap allows {max(0, max_pages) - pages} of {declared_pages} {scope} pages"
            )
            break
        scope_count = 0
        for page in range(1, declared_pages + 1):
            try:
                soup = first_soup if page == 1 else sdm_apply_post_soup(s, scope, page, timeout)
            except Exception as exc:
                logger.warning(
                    "Seodaemun application list fetch failed scope=%s page=%s error_type=%s",
                    scope,
                    page,
                    type(exc).__name__,
                )
                errors.append(f"{scope} page {page}: {type(exc).__name__}")
                break
            pages += 1
            if sdm_apply_declared_pages(soup, page) != declared_pages:
                errors.append(f"{scope} page {page} changed the official terminal page")
            page_rows, page_invalid = sdm_apply_list_rows(target, soup, scope, page)
            invalid_rows += page_invalid
            expected_minimum = SDM_APPLY_PAGE_SIZE if page < declared_pages else 0
            if len(page_rows) < expected_minimum or len(page_rows) > SDM_APPLY_PAGE_SIZE:
                errors.append(f"{scope} page {page} exposed an invalid row count ({len(page_rows)})")
            if page < declared_pages and len(page_rows) != SDM_APPLY_PAGE_SIZE:
                errors.append(f"{scope} page {page} was short before the terminal page")
            if page == declared_pages and declared_pages > 1 and not page_rows:
                errors.append(f"{scope} terminal page was unexpectedly empty")
            raw_row_count += len(page_rows)
            scope_count += len(page_rows)
            for row in page_rows:
                seq = clean_text(row.get("raw_fields", {}).get("official_form_seq"))
                if seq in seen_ids:
                    duplicate_rows += 1
                    continue
                seen_ids.add(seq)
                exclusion = SDM_APPLY_EXCLUDED_SEQS.get(seq)
                if exclusion:
                    excluded_counts[exclusion] += 1
                    continue
                listed_rows.append(row)
        declared_totals_by_scope[scope] = scope_count

    if invalid_rows:
        errors.append(f"malformed official application rows ({invalid_rows})")
    if duplicate_rows:
        errors.append(f"duplicated official formSeq values ({duplicate_rows})")
    expected_exclusions = set(SDM_APPLY_EXCLUDED_SEQS) & seen_ids
    if expected_exclusions != set(SDM_APPLY_EXCLUDED_SEQS):
        missing = sorted(set(SDM_APPLY_EXCLUDED_SEQS) - expected_exclusions)
        errors.append(f"expected excluded official records disappeared ({','.join(missing)})")

    allowed_details = max(0, detail_limit)
    detail_attempts = min(allowed_details, len(listed_rows))
    if detail_attempts < len(listed_rows):
        source_cap_reached = True
        errors.append(f"detail_limit cap allows {detail_attempts} of {len(listed_rows)} current details")
    detail_soups, fetch_failures = sdm_fetch_soups_parallel(
        [clean_text(row.get("raw_url")) for row in listed_rows[:detail_attempts]],
        timeout,
    )
    detail_pages = 0
    detail_failures: list[str] = []
    for index, row in enumerate(listed_rows[:detail_attempts]):
        identity = clean_text(row.get("provider_course_id"))
        soup = detail_soups.get(index)
        if soup is None:
            detail_failures.append(identity)
            continue
        detail, reason = sdm_apply_detail_fields(
            soup,
            clean_text(row.get("title")),
            clean_text(row.get("raw_fields", {}).get("status_scope")),
        )
        if detail is None:
            detail_failures.append(f"{identity}:{reason}")
            continue
        detail_has_application = bool(detail.pop("has_application_control", False))
        for key, value in detail.items():
            if key == "raw_detail_pairs" or value in (None, "", [], {}):
                continue
            row[key] = value
        branch = clean_text(row.get("venue_name")) or target.branch or "서대문구 통합신청"
        row["branch"] = branch
        row["branch_code"] = sdm_branch_code("SDM_APPLY", branch)
        row["raw_fields"]["detail_pairs"] = detail.get("raw_detail_pairs", {})
        row["raw_fields"]["detail_url"] = row.get("raw_url")
        if row.get("reservation_available") and not detail_has_application:
            detail_failures.append(f"{identity}:missing official detail application control")
            row.pop("application_url", None)
            row["reservation_available"] = False
            row["raw_fields"]["clear_application_url"] = True
            continue
        detail_pages += 1
    if fetch_failures or detail_failures:
        errors.append(f"detail fetch or parse failed for {len(set(detail_failures))} programs")

    pagination_complete = (
        len(declared_pages_by_scope) == len(SDM_APPLY_SCOPES)
        and pages == sum(declared_pages_by_scope.values())
        and raw_row_count == sum(declared_totals_by_scope.values())
    )
    details_complete = (
        detail_attempts == len(listed_rows)
        and detail_pages == len(listed_rows)
        and not fetch_failures
        and not detail_failures
    )
    snapshot_complete = pagination_complete and details_complete and not errors
    no_current_data = snapshot_complete and not listed_rows
    meta: dict[str, Any] = {
        "pages": pages,
        "declared_pages_by_scope": declared_pages_by_scope,
        "declared_totals_by_scope": declared_totals_by_scope,
        "total_count": raw_row_count,
        "raw_row_count": raw_row_count,
        "current_count": len(listed_rows),
        "excluded_count": sum(excluded_counts.values()),
        "excluded_counts": dict(excluded_counts),
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(seen_ids),
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in listed_rows),
        "invalid_rows": invalid_rows,
        "duplicate_rows": duplicate_rows,
        "pagination_detected": pages > len(SDM_APPLY_SCOPES),
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached or not snapshot_complete,
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": "official application/current scopes are empty" if no_current_data else "",
        "request_encoding": "euc-kr",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(listed_rows), SDM_APPLY_PARSER, meta


def sdm_lifelong_declaration(soup: BeautifulSoup) -> tuple[Optional[int], Optional[int]]:
    total_node = soup.select_one(".total")
    text = clean_text(total_node.get_text(" ", strip=True) if total_node else "")
    total_match = re.search(r"전체\s*건수\s*([\d,]+)\s*건", text)
    page_match = re.search(r"현재페이지\s*:\s*\d+\s*/\s*(\d+)", text)
    if not total_match or not page_match:
        return None, None
    return int(total_match.group(1).replace(",", "")), int(page_match.group(1))


def sdm_lifelong_list_rows(
    target: CrawlTarget,
    soup: BeautifulSoup,
    declared_total: int,
) -> tuple[list[dict[str, Any]], int]:
    rows: list[dict[str, Any]] = []
    malformed = 0
    for row_index, tr in enumerate(soup.select("table tbody tr")):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
        anchor = tr.find("a", href=lambda value: bool(value and "lectureInfoView.do" in value))
        detail_url = normalize_link(SDM_LIFELONG_LIST_URL, anchor.get("href") if anchor else "")
        idx = clean_text((parse_qs(urlparse(detail_url).query).get("idx") or [""])[0])
        if len(cells) < 6 or not cells[0].isdigit() or not anchor or not idx.isdigit():
            if cells:
                malformed += 1
            continue
        expected_ordinal = declared_total - row_index
        if int(cells[0]) != expected_ordinal:
            malformed += 1
            continue
        title = clean_text(anchor.get_text(" ", strip=True))
        status_raw = cells[5]
        application_url = (
            f"https://{SDM_LIFELONG_HOST}/lll/user/lectureinfo/traineeWrite.do?{urlencode({'idx': idx})}"
            if sdm_status(status_raw) in {"OPEN", "WAITING"}
            else ""
        )
        row: dict[str, Any] = {
            "provider": target.provider,
            "provider_course_id": f"{target.provider}:lecture:{idx}",
            "prefer_incoming_provider_course_id": True,
            "title": title,
            "branch": target.branch or "서대문구 평생학습관",
            "branch_code": sdm_branch_code("SDM_LLL", target.branch or "서대문구 평생학습관"),
            "branch_url": SDM_LIFELONG_LIST_URL,
            "preserve_branch": True,
            "raw_url": detail_url,
            "application_url": application_url,
            "reservation_available": bool(application_url),
            "status": sdm_status(status_raw),
            "target": cells[1],
            "capacity": cells[4],
            "apply_period": sdm_date_range(cells[3]),
            "description": title,
            **sdm_public_course_fields("latest_50+current_detail_html"),
            "raw_fields": {
                "parser": SDM_LIFELONG_PARSER,
                "official_lecture_idx": idx,
                "list_ordinal": int(cells[0]),
                "status_raw": status_raw,
                "list_cells": cells,
                "clear_application_url": not bool(application_url),
            },
        }
        capacity_current, capacity_total = parse_capacity_pair(cells[4])
        if capacity_current is not None:
            row["capacity_current"] = capacity_current
        if capacity_total is not None:
            row["capacity_total"] = capacity_total
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
    return rows, malformed


def sdm_lifelong_detail_fields(
    soup: BeautifulSoup,
    expected_title: str,
) -> tuple[Optional[dict[str, Any]], str]:
    if clean_text(expected_title) not in clean_text(soup.get_text(" ", strip=True)):
        return None, "detail title did not match official list title"
    pairs: dict[str, str] = {}
    for item in soup.select("li.item"):
        label = item.select_one("strong.t")
        value = item.find("span")
        key = clean_text(label.get_text(" ", strip=True) if label else "")
        text = clean_text(value.get_text(" ", strip=True) if value else "")
        if key and text:
            pairs[key] = text
    required = ("교육기간", "교육장소", "접수기간")
    missing = [key for key in required if not clean_text(pairs.get(key))]
    if missing:
        return None, f"missing detail labels: {','.join(missing)}"
    period = sdm_date_range(pairs.get("교육기간"))
    if sdm_period_end(period) is None:
        return None, "missing valid education end date"
    content_heading = next(
        (heading for heading in soup.find_all(["h3", "h4", "strong"]) if clean_text(heading.get_text(" ", strip=True)) == "강의내용"),
        None,
    )
    content_group = content_heading.find_parent(class_="group") if content_heading else None
    description = clean_text(content_group.get_text(" ", strip=True) if content_group else expected_title)[:8000]
    material_match = re.search(r"재료비\s*[:：]?\s*([^\[\]\n]{1,80})", description)
    has_application_control = "신청하기" in clean_text(soup.get_text(" ", strip=True))
    return {
        "period": period,
        "apply_period": sdm_date_range(pairs.get("접수기간")),
        "schedule_raw": clean_text(pairs.get("교육요일")),
        "target": clean_text(pairs.get("교육대상")),
        "fee": clean_text(pairs.get("수강료")),
        "room": clean_text(pairs.get("교육장명") or pairs.get("교육장소")),
        "venue_name": clean_text(pairs.get("교육장소")),
        "phone": clean_text(pairs.get("문의전화")),
        "instructor": clean_text(pairs.get("강사명")),
        "application_method_raw": clean_text(pairs.get("신청방법")),
        "material_note": clean_text(material_match.group(1)) if material_match else "",
        "description": description,
        "has_application_control": has_application_control,
        "raw_detail_pairs": pairs,
    }, ""


def collect_sdm_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    errors: list[str] = []
    if not is_sdm_lifelong_target(target):
        errors.append("target does not match the canonical HTTPS lifelong latest-program route")
    source_cap_reached = False
    pages = 0
    official_total = 0
    official_pages = 0
    listed_rows: list[dict[str, Any]] = []
    invalid_rows = 0
    duplicate_rows = 0
    if not errors:
        if max_pages < 1:
            source_cap_reached = True
            errors.append("max_pages cap prevents the official latest-50 request")
        else:
            parsed = urlparse(SDM_LIFELONG_LIST_URL)
            query = parse_qs(parsed.query)
            query["pageLS"] = [str(SDM_LIFELONG_SCAN_SIZE)]
            page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
            try:
                soup = fetch_soup(session(), page_url, timeout=timeout)
                pages = 1
                declared_total, declared_pages = sdm_lifelong_declaration(soup)
                if declared_total is None or declared_pages is None:
                    errors.append("latest-50 page omitted the official total/page declaration")
                else:
                    official_total = declared_total
                    official_pages = declared_pages
                    listed_rows, invalid_rows = sdm_lifelong_list_rows(target, soup, official_total)
                    expected_rows = min(SDM_LIFELONG_SCAN_SIZE, official_total)
                    if len(listed_rows) != expected_rows:
                        errors.append(f"latest-50 page exposed {len(listed_rows)} of {expected_rows} expected rows")
                    ids = [clean_text(row.get("provider_course_id")) for row in listed_rows]
                    duplicate_rows = len(ids) - len(set(ids))
            except Exception as exc:
                logger.warning(
                    "Seodaemun lifelong latest-course list fetch failed error_type=%s",
                    type(exc).__name__,
                )
                errors.append(f"latest-50 page: {type(exc).__name__}")
    if invalid_rows:
        errors.append(f"malformed latest-50 rows ({invalid_rows})")
    if duplicate_rows:
        errors.append(f"duplicated official lecture idx values ({duplicate_rows})")

    detail_attempts = min(max(0, detail_limit), len(listed_rows))
    if detail_attempts < len(listed_rows):
        source_cap_reached = True
        errors.append(f"detail_limit cap allows {detail_attempts} of {len(listed_rows)} latest details")
    detail_soups, fetch_failures = sdm_fetch_soups_parallel(
        [clean_text(row.get("raw_url")) for row in listed_rows[:detail_attempts]],
        timeout,
    )
    detail_pages = 0
    detail_failures: list[str] = []
    detailed_rows: list[dict[str, Any]] = []
    for index, row in enumerate(listed_rows[:detail_attempts]):
        identity = clean_text(row.get("provider_course_id"))
        soup = detail_soups.get(index)
        if soup is None:
            detail_failures.append(identity)
            continue
        detail, reason = sdm_lifelong_detail_fields(soup, clean_text(row.get("title")))
        if detail is None:
            detail_failures.append(f"{identity}:{reason}")
            continue
        has_application_control = bool(detail.pop("has_application_control", False))
        for key, value in detail.items():
            if key == "raw_detail_pairs" or value in (None, "", [], {}):
                continue
            row[key] = value
        branch = clean_text(row.get("venue_name")) or target.branch or "서대문구 평생학습관"
        row["branch"] = branch
        row["branch_code"] = sdm_branch_code("SDM_LLL", branch)
        row["raw_fields"]["detail_pairs"] = detail.get("raw_detail_pairs", {})
        row["raw_fields"]["detail_url"] = row.get("raw_url")
        if row.get("reservation_available") and not has_application_control:
            row.pop("application_url", None)
            row["reservation_available"] = False
            row["raw_fields"]["clear_application_url"] = True
        detail_pages += 1
        detailed_rows.append(row)
    if fetch_failures or detail_failures:
        errors.append(f"detail fetch or parse failed for {len(set(detail_failures))} lectures")

    today = datetime.now().date()
    current_rows = [
        row for row in detailed_rows
        if (sdm_period_end(row.get("period")) or datetime.min).date() >= today
    ]
    expired_count = len(detailed_rows) - len(current_rows)
    pagination_complete = (
        pages == 1
        and official_total >= len(listed_rows)
        and len(listed_rows) == min(SDM_LIFELONG_SCAN_SIZE, official_total)
        and not invalid_rows
        and not duplicate_rows
    )
    details_complete = (
        detail_attempts == len(listed_rows)
        and detail_pages == len(listed_rows)
        and not fetch_failures
        and not detail_failures
    )
    snapshot_complete = pagination_complete and details_complete and not errors
    no_current_data = snapshot_complete and not current_rows
    meta: dict[str, Any] = {
        "pages": pages,
        "official_total_count": official_total,
        "official_pages_at_scan_size": official_pages,
        "scan_size": SDM_LIFELONG_SCAN_SIZE,
        "total_count": len(listed_rows),
        "raw_row_count": len(listed_rows),
        "current_count": len(current_rows),
        "expired_count": expired_count,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(listed_rows),
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in current_rows),
        "invalid_rows": invalid_rows,
        "duplicate_rows": duplicate_rows,
        "pagination_detected": official_pages > 1,
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached or not snapshot_complete,
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": "all programs in the official latest-50 scope have ended" if no_current_data else "",
        "branch_counts": dict(Counter(clean_text(row.get("branch")) for row in current_rows)),
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(current_rows), SDM_LIFELONG_PARSER, meta


def sscmc_detail_url(comcd: str, class_cd: str) -> str:
    route = SSCMC_COMPANIES.get(comcd, ("", ""))[1]
    if not route:
        return ""
    return urljoin(
        SSCMC_ROOT_URL,
        f"{route.lstrip('/')}?{urlencode({'action': 'read', 'comcd': comcd, 'classcd': class_cd})}",
    )


def sscmc_api_row(target: CrawlTarget, item: dict[str, Any]) -> tuple[Optional[dict[str, Any]], str]:
    comcd = clean_text(item.get("comcd"))
    class_cd = clean_text(item.get("class_cd"))
    title = clean_text(item.get("class_nm"))
    branch = clean_text(item.get("comnm"))
    status_code = clean_text(item.get("status")).upper()
    expected_company = SSCMC_COMPANIES.get(comcd)
    if not expected_company or branch != expected_company[0] or not class_cd or not title or not status_code:
        return None, "missing or mismatched official company/class identity"
    raw_url = sscmc_detail_url(comcd, class_cd)
    if not raw_url:
        return None, f"company {comcd} has no verified official detail route"
    capacity_current = fmcs_int(item.get("reg_person"), -1)
    capacity_total = fmcs_int(item.get("capa"), -1)
    row: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:{comcd}:{class_cd}",
        "prefer_incoming_provider_course_id": True,
        "title": title,
        "branch": branch,
        "branch_code": comcd,
        "branch_url": SSCMC_ROOT_URL,
        "preserve_branch": True,
        "category": clean_text(" > ".join(part for part in (clean_text(item.get("category1")), clean_text(item.get("category2"))) if part)),
        "raw_url": raw_url,
        "status": fmcs_status_text(status_code),
        "fee": fmcs_fee_text(item.get("course_fee")),
        "schedule_raw": clean_text(
            " / ".join(
                part for part in (
                    clean_text(item.get("train_day_nm")),
                    clean_text(f"{item.get('train_stime', '')} ~ {item.get('train_etime', '')}"),
                ) if part
            )
        ),
        "target": clean_text(item.get("target_age_name")),
        "instructor": clean_text(item.get("teacher_name")),
        "capacity": f"{capacity_current}/{capacity_total}" if capacity_current >= 0 and capacity_total >= 0 else "",
        "capacity_current": capacity_current if capacity_current >= 0 else None,
        "capacity_total": capacity_total if capacity_total >= 0 else None,
        "venue_name": branch,
        "reservation_available": False,
        "description": title,
        **sdm_public_course_fields("company_lecture_api+detail_html"),
        "raw_fields": {
            "parser": SSCMC_PARSER,
            "official_company_code": comcd,
            "official_class_code": class_cd,
            "status_code": status_code,
            "item": item,
            "clear_application_url": True,
        },
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}, ""


def sscmc_detail_fields(
    soup: BeautifulSoup,
    expected_comcd: str,
    expected_class_cd: str,
    expected_title: str,
) -> tuple[Optional[dict[str, Any]], str]:
    form = soup.select_one("#form_lecture_reg")
    if not form:
        return None, "missing official lecture registration form"
    hidden = {
        clean_text(node.get("name")): clean_text(node.get("value"))
        for node in form.select("input[name]")
    }
    if hidden.get("comcd") != expected_comcd or hidden.get("classcd") != expected_class_cd:
        return None, "detail form identity did not match API company/class"
    pairs = pairs_from_tables(soup)
    for dt in soup.find_all("dt"):
        dd = dt.find_next_sibling("dd")
        key = clean_text(dt.get_text(" ", strip=True)).lstrip("· ").strip()
        value = clean_text(dd.get_text(" ", strip=True) if dd else "")
        if key and value:
            pairs[key] = value
    status_period_node = soup.select_one(".status_box span em")
    if status_period_node and not clean_text(pairs.get("신청기간")):
        pairs["신청기간"] = clean_text(status_period_node.get_text(" ", strip=True))
    title = clean_text(pairs.get("강좌명"))
    branch = clean_text(pairs.get("센터명") or pairs.get("운영센터"))
    if "/" in branch:
        branch = clean_text(branch.split("/", 1)[0])
    if title != clean_text(expected_title):
        return None, "detail title did not match API title"
    expected_branch = SSCMC_COMPANIES.get(expected_comcd, ("", ""))[0]
    if branch != expected_branch:
        return None, "detail center name did not match official company"
    period = sdm_date_range(pairs.get("교육기간") or pairs.get("수강기간"))
    if sdm_period_end(period) is None:
        return None, "detail omitted a valid education end date"
    lines = lines_from_soup(soup)
    intro = fmcs_detail_text(lines, "강좌소개")
    content = fmcs_detail_text(lines, "강좌내용")
    description = clean_text(" ".join(part for part in (intro, content) if part))[:8000]
    combined = clean_text(" ".join((title, description, clean_text(pairs.get("접수방법")))))
    online_forbidden = any(
        token in combined
        for token in ("온라인접수불가", "온라인 접수 불가", "방문접수", "방문 접수", "유선 및 방문", "데스크 방문")
    )
    capacity = clean_text(pairs.get("잔여인원/정원") or pairs.get("신청인원/정원"))
    capacity_current, capacity_total = parse_capacity_pair(capacity)
    status_code = clean_text(hidden.get("status") or hidden.get("type")).upper()
    return {
        "branch": branch,
        "period": period,
        "apply_period": sdm_date_range(pairs.get("신청기간")),
        "schedule_raw": clean_text(pairs.get("교육시간") or pairs.get("시간/요일")),
        "target": clean_text(pairs.get("교육대상")),
        "room": clean_text(pairs.get("교육장소") or pairs.get("강습장소")),
        "venue_name": clean_text(pairs.get("교육장소") or pairs.get("강습장소")) or branch,
        "instructor": clean_text(pairs.get("강사명")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "fee": clean_text(pairs.get("수강료")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "description": description,
        "online_forbidden": online_forbidden,
        "detail_status_code": status_code,
        "raw_detail_pairs": pairs,
        "detail_form": {key: value for key, value in hidden.items() if key != "SecurityToken"},
    }, ""


def collect_sscmc_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    errors: list[str] = []
    if not is_sscmc_target(target):
        errors.append("target does not match the canonical SSCMC HTTPS system owner")
    s = session()
    method = ""
    companies: list[dict[str, Any]] = []
    if not errors:
        try:
            method = fmcs_http_method(s, SSCMC_ROOT_URL, SSCMC_ROOT_URL, timeout)
            companies = fmcs_json_rows(
                fmcs_request_json(
                    s, SSCMC_ROOT_URL, "rest/common/company", {"type": "L"}, method, SSCMC_ROOT_URL, timeout
                )
            )
        except Exception as exc:
            logger.warning(
                "SSCMC company API fetch failed error_type=%s",
                type(exc).__name__,
            )
            errors.append(f"company API: {type(exc).__name__}")
    company_names = {
        clean_text(company.get("comcd")): clean_text(company.get("comnm"))
        for company in companies
        if clean_text(company.get("comcd"))
    }
    expected_names = {code: value[0] for code, value in SSCMC_COMPANIES.items()}
    if not errors and company_names != expected_names:
        errors.append("official company API did not match the three verified SSCMC centers")

    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    pages = 0
    api_requests = 0
    raw_row_count = 0
    malformed_rows = 0
    duplicate_rows = 0
    declared_total = 0
    company_totals: dict[str, int] = {}
    company_pages: dict[str, int] = {}
    status_counts: Counter[str] = Counter()
    source_cap_reached = False

    for comcd in SSCMC_COMPANIES if not errors else ():
        page = 1
        company_total: Optional[int] = None
        expected_pages = 1
        while page <= expected_pages:
            if pages >= max(0, max_pages):
                source_cap_reached = True
                errors.append(f"max_pages cap reached before completing company {comcd}")
                break
            params = {
                "company_code": comcd,
                "category_level": "9",
                "page": str(page),
                "page_size": str(SSCMC_PAGE_SIZE),
            }
            try:
                data = fmcs_request_json(
                    s, SSCMC_ROOT_URL, "rest/lecture/list", params, method, SSCMC_ROOT_URL, timeout
                )
            except Exception as exc:
                logger.warning(
                    "SSCMC lecture API fetch failed company=%s page=%s error_type=%s",
                    comcd,
                    page,
                    type(exc).__name__,
                )
                errors.append(f"company {comcd} page {page}: {type(exc).__name__}")
                break
            api_requests += 1
            pages += 1
            items = fmcs_json_rows(data)
            if not items:
                if page == 1:
                    company_total = 0
                    expected_pages = 1
                else:
                    errors.append(f"company {comcd} page {page} was unexpectedly empty")
                break
            page_total = fmcs_int(items[0].get("total_count"), -1)
            if page_total < 0:
                errors.append(f"company {comcd} page {page} omitted total_count")
                break
            if company_total is None:
                company_total = page_total
                expected_pages = max(1, (company_total + SSCMC_PAGE_SIZE - 1) // SSCMC_PAGE_SIZE)
            elif page_total != company_total:
                errors.append(f"company {comcd} changed total_count from {company_total} to {page_total}")
            expected_rows = (
                SSCMC_PAGE_SIZE
                if page < expected_pages
                else company_total - SSCMC_PAGE_SIZE * (expected_pages - 1)
            )
            if len(items) != expected_rows:
                errors.append(f"company {comcd} page {page} exposed {len(items)} of {expected_rows} rows")
            raw_row_count += len(items)
            for item in items:
                identity = (clean_text(item.get("comcd")), clean_text(item.get("class_cd")))
                row, reason = sscmc_api_row(target, item)
                if row is None or identity[0] != comcd:
                    malformed_rows += 1
                    if reason:
                        logger.debug("SSCMC malformed row reason=%s", reason)
                    continue
                if identity in seen:
                    duplicate_rows += 1
                    continue
                seen.add(identity)
                rows.append(row)
                status_counts[clean_text(item.get("status")).upper()] += 1
            page += 1
        company_total = company_total or 0
        company_totals[comcd] = company_total
        company_pages[comcd] = expected_pages
        declared_total += company_total
        if source_cap_reached:
            break

    if len(seen) != declared_total:
        errors.append(f"parsed {len(seen)} unique company/class IDs of {declared_total} declared rows")
    if malformed_rows:
        errors.append(f"malformed FMCS rows ({malformed_rows})")
    if duplicate_rows:
        errors.append(f"duplicated FMCS company/class IDs ({duplicate_rows})")

    detail_attempts = min(max(0, detail_limit), len(rows))
    if detail_attempts < len(rows):
        source_cap_reached = True
        errors.append(f"detail_limit cap allows {detail_attempts} of {len(rows)} class details")
    detail_soups, fetch_failures = sdm_fetch_soups_parallel(
        [clean_text(row.get("raw_url")) for row in rows[:detail_attempts]],
        timeout,
    )
    detail_pages = 0
    detail_failures: list[str] = []
    detailed_rows: list[dict[str, Any]] = []
    for index, row in enumerate(rows[:detail_attempts]):
        identity = clean_text(row.get("provider_course_id"))
        raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
        soup = detail_soups.get(index)
        if soup is None:
            detail_failures.append(identity)
            continue
        detail, reason = sscmc_detail_fields(
            soup,
            clean_text(raw_fields.get("official_company_code")),
            clean_text(raw_fields.get("official_class_code")),
            clean_text(row.get("title")),
        )
        if detail is None:
            detail_failures.append(f"{identity}:{reason}")
            continue
        online_forbidden = bool(detail.pop("online_forbidden", False))
        detail_status_code = clean_text(detail.pop("detail_status_code", "")).upper()
        for key, value in detail.items():
            if key in {"raw_detail_pairs", "detail_form"} or value in (None, "", [], {}):
                continue
            row[key] = value
        row["raw_fields"]["detail_pairs"] = detail.get("raw_detail_pairs", {})
        row["raw_fields"]["detail_form"] = detail.get("detail_form", {})
        row["raw_fields"]["detail_url"] = row.get("raw_url")
        row["raw_fields"]["online_forbidden"] = online_forbidden
        api_status_code = clean_text(row.get("raw_fields", {}).get("status_code")).upper()
        application_allowed = (
            api_status_code == "R"
            and detail_status_code == "R"
            and not online_forbidden
        )
        row["reservation_available"] = application_allowed
        row["raw_fields"]["clear_application_url"] = not application_allowed
        if application_allowed:
            row["application_url"] = row["raw_url"]
            row["application_type"] = "ONLINE_RESERVATION"
        else:
            row.pop("application_url", None)
        detail_pages += 1
        detailed_rows.append(row)
    if fetch_failures or detail_failures:
        errors.append(f"detail fetch or parse failed for {len(set(detail_failures))} classes")

    today = datetime.now().date()
    current_rows = [
        row for row in detailed_rows
        if (sdm_period_end(row.get("period")) or datetime.min).date() >= today
    ]
    expired_count = len(detailed_rows) - len(current_rows)
    pagination_complete = (
        len(company_totals) == len(SSCMC_COMPANIES)
        and len(seen) == declared_total
        and not malformed_rows
        and not duplicate_rows
    )
    details_complete = (
        detail_attempts == len(rows)
        and detail_pages == len(rows)
        and not fetch_failures
        and not detail_failures
    )
    snapshot_complete = pagination_complete and details_complete and not errors
    no_current_data = snapshot_complete and not current_rows
    meta: dict[str, Any] = {
        "pages": pages,
        "api_requests": api_requests,
        "raw_row_count": raw_row_count,
        "total_count": declared_total,
        "current_count": len(current_rows),
        "expired_count": expired_count,
        "company_count": len(companies),
        "company_totals": company_totals,
        "company_names": company_names,
        "company_pages": company_pages,
        "status_counts": dict(status_counts),
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(seen),
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in current_rows),
        "pagination_detected": any(value > 1 for value in company_pages.values()),
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached or not snapshot_complete,
        "recursion_depth": 0,
        "http_method": method,
        "no_current_data": no_current_data,
        "no_current_reason": "all official SSCMC classes have ended" if no_current_data else "",
        "branch_counts": dict(Counter(clean_text(row.get("branch")) for row in current_rows)),
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(current_rows), SSCMC_PARSER, meta


def geumcheon_normalize_date_text(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    text = text.split("※", 1)[0]
    text = re.sub(r"(\d{4})[.](\d{1,2})[.](\d{1,2})", lambda m: f"{m.group(1)}-{int(m.group(2)):02d}-{int(m.group(3)):02d}", text)
    text = re.sub(r"(\d{4}-\d{2}-\d{2})\([^)]*\)", r"\1", text)
    text = re.sub(r"\s*~\s*", " ~ ", text)
    return clean_text(text)


def geumcheon_description_from_soup(soup: BeautifulSoup) -> str:
    lines = lines_from_soup(soup)
    start = next((index for index, line in enumerate(lines) if line in {"상세정보", "강의소개", "교육안내"}), -1)
    end = next((index for index, line in enumerate(lines) if line == "목록" and (start < 0 or index > start)), len(lines))
    if start >= 0 and end > start:
        return clean_text(" ".join(lines[start + 1 : end]))
    return clean_text(" ".join(lines[:120]))


def web_edc_detail_fields(s: requests.Session, detail_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    pairs = pairs_from_tables(soup)
    # Keep the legacy Geumcheon label priority while accepting Yeoncheon's
    # additional ``모집정원``/``신청인원`` labels.
    capacity = first_by_keys(pairs, ("정원", "모집정원", "신청인원"))
    capacity_total_match = re.search(r"(?:모집정원|모집|정원)\s*[:：]?\s*(\d{1,5})", capacity)
    capacity_total = int(capacity_total_match.group(1)) if capacity_total_match else None
    applicant_text = clean_text(soup.get_text(" ", strip=True))
    applicant_match = re.search(
        r"(\d{1,5})\s*명?\s*(?:접수|신청)\s*/\s*(\d{1,5})\s*명?\s*(?:모집|정원)",
        applicant_text,
    ) or re.search(r"(?:신청자?|접수자?)\s*[:：]?\s*(\d{1,5})\s*/\s*(\d{1,5})", applicant_text)
    capacity_current = int(applicant_match.group(1)) if applicant_match else None
    if capacity_total is None and applicant_match:
        capacity_total = int(applicant_match.group(2))
    if capacity_total is None:
        capacity_total = parse_capacity_number(capacity)

    waitlist_text = first_by_keys(pairs, ("대기접수", "대기정원", "대기인원")) or capacity
    waitlist_pair = re.search(r"(?:가능)?\s*(\d{1,5})\s*/\s*(\d{1,5})", waitlist_text)
    waitlist_current = int(waitlist_pair.group(1)) if waitlist_pair else None
    waitlist_total = int(waitlist_pair.group(2)) if waitlist_pair else None
    if waitlist_total is None:
        waitlist_total_match = re.search(r"(?:대기인원|대기정원|대기)\s*[:：]?\s*(\d{1,5})", waitlist_text)
        waitlist_total = int(waitlist_total_match.group(1)) if waitlist_total_match else None

    room = first_by_keys(pairs, ("강의장소", "교육장소", "장소"))
    venue_address = ""
    province_pattern = (
        r"서울특별시|부산광역시|대구광역시|인천광역시|광주광역시|"
        r"대전광역시|울산광역시|세종특별자치시|경기도|강원특별자치도|"
        r"충청북도|충청남도|전북특별자치도|전라남도|경상북도|경상남도|"
        r"제주특별자치도"
    )
    address_match = re.search(rf"((?:\d{{5}}\s+)?(?:{province_pattern})\s+.+)$", room)
    if not address_match:
        # Geumcheon historically exposes some postal-address strings without
        # an explicit province token.
        address_match = re.search(r"(\d{5}\s+.+)$", room)
    if address_match:
        venue_address = clean_text(address_match.group(1))
        room = clean_text(room[: address_match.start()])

    application_method_text = first_by_keys(pairs, ("수강신청방법", "신청방법", "접수방법"))
    selection_match = re.search(r"선별방법\s*[:：]\s*([^※]+)", application_method_text)
    selection_method = clean_text(selection_match.group(1)) if selection_match else ""
    application_method_raw = application_method_text
    return {
        "category": first_by_keys(pairs, ("강좌영역", "강좌구분", "분류")),
        "status_text": first_by_keys(pairs, ("강좌상태", "진행상태", "상태")),
        "apply_period": geumcheon_normalize_date_text(first_by_keys(pairs, ("신청기간", "접수기간"))),
        "period": geumcheon_normalize_date_text(first_by_keys(pairs, ("교육기간", "강의기간"))),
        "schedule_raw": first_by_keys(pairs, ("강의시간", "교육시간", "요일/시간")),
        "application_method_raw": application_method_raw,
        "selection_method": selection_method,
        "fee": first_by_keys(pairs, ("수강료", "교육비", "이용요금")),
        "room": room,
        "venue_name": room,
        "venue_address": venue_address,
        "target": first_by_keys(pairs, ("수강대상", "교육대상", "이용대상")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_current": waitlist_current,
        "waitlist_total": waitlist_total,
        "provider_organizer": first_by_keys(pairs, ("주최", "운영기관", "기관")),
        "phone": first_by_keys(pairs, ("문의", "문의전화", "전화")),
        "description": geumcheon_description_from_soup(soup),
        "raw_detail_pairs": pairs,
    }


def geumcheon_detail_fields(s: requests.Session, detail_url: str, timeout: int) -> dict[str, Any]:
    return web_edc_detail_fields(s, detail_url, timeout)


def geumcheon_status(value: str) -> str:
    text = clean_text(value).replace(" ", "")
    if any(token in text for token in ("모집중", "접수중")):
        return "접수중"
    if any(token in text for token in ("모집대기", "교육대기", "접수대기")):
        return "접수예정"
    if any(token in text for token in ("모집마감", "접수마감", "마감")):
        return "접수마감"
    return clean_text(value)


def collect_geumcheon_reserve_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    """Collect the complete current/future Geumcheon education snapshot."""

    if municipal_geumcheon_library.is_geumcheon_library_target(target):
        return municipal_geumcheon_library.collect_geumcheon_library_courses(
            target,
            timeout=timeout,
            max_pages=max_pages,
            detail_limit=detail_limit,
            session_factory=session,
            dedupe_rows=dedupe_rows,
        )
    return municipal_geumcheon.collect_geumcheon_current(
        target,
        timeout=timeout,
        max_pages=max_pages,
        detail_limit=detail_limit,
        fetcher=lambda current_session, url, request_timeout: fetch_soup(
            current_session,
            url,
            timeout=request_timeout,
        ),
        session_factory=session,
        dedupe_rows=dedupe_rows,
    )


def legacy_geumcheon_reserve_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    branch = target.branch or "금천구 통합예약"

    for page in range(1, max(1, max_pages) + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 7:
                continue
            link = tr.select_one(".p-subject a[href], a[href*='edcLctreView']")
            title = clean_text(link.get_text(" ", strip=True) if link else "")
            raw_url = normalize_link(page_url, link.get("href") if link else "")
            if not title or not raw_url:
                continue
            venue = clean_text((tr.select_one(".p-subject p") or {}).get_text(" ", strip=True) if tr.select_one(".p-subject p") else "")
            status_text = cells[0]
            target_text = cells[2]
            date_text = cells[3]
            apply_match = re.search(r"신청\s*:\s*([^교육]+?)(?=\s*교육\s*:|$)", date_text)
            period_match = re.search(r"교육\s*:\s*(.+)", date_text)
            list_apply_period = geumcheon_normalize_date_text(apply_match.group(1) if apply_match else "")
            list_period = geumcheon_normalize_date_text(period_match.group(1) if period_match else date_text)
            capacity_current, capacity_total = parse_capacity_pair(cells[4])
            fee = clean_text(cells[5])
            detail: dict[str, Any] = {}
            if detail_pages < detail_limit:
                try:
                    detail = geumcheon_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("geumcheon detail fetch failed %s: %s", raw_url, exc)
            detail_status = clean_text(detail.get("status_text"))
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "branch_code": target.provider,
                "category": clean_text(detail.get("category")),
                "raw_url": raw_url,
                "application_url": raw_url if "모집 중" in status_text or "모집중" in detail_status else "",
                "status": geumcheon_status(detail_status or status_text),
                "period": clean_text(detail.get("period")) or list_period,
                "apply_period": clean_text(detail.get("apply_period")) or list_apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")),
                "target": clean_text(detail.get("target")) or target_text,
                "fee": clean_text(detail.get("fee")) or fee,
                "room": clean_text(detail.get("room")) or venue,
                "venue_name": clean_text(detail.get("venue_name")) or venue,
                "venue_address": clean_text(detail.get("venue_address")),
                "phone": clean_text(detail.get("phone")),
                "capacity": clean_text(detail.get("capacity")) or cells[4],
                "capacity_current": detail.get("capacity_current") if detail.get("capacity_current") is not None else capacity_current,
                "capacity_total": detail.get("capacity_total") if detail.get("capacity_total") is not None else capacity_total,
                "application_method_raw": clean_text(detail.get("application_method_raw")) or clean_text(cells[6]),
                "description": clean_text(detail.get("description")) or clean_text(" ".join(cells)),
                "raw_fields": {
                    "parser": "geumcheon_reserve_lecture_list+detail",
                    "cells": cells,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                    "page_url": page_url,
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, .p-pagination, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "geumcheon_reserve_lecture_list+detail", meta


YEONCHEON_RESERVE_HOST = "www.yeoncheon.go.kr"
YEONCHEON_RESERVE_LIST_PATH = "/reserve/webEdcLctreList.do"
YEONCHEON_RESERVE_DETAIL_PATH = "/reserve/edcLctreView.do"
YEONCHEON_RESERVE_KEY = "4708"
YEONCHEON_RESERVE_PAGE_UNIT = 10


def is_yeoncheon_reserve_target(url: str) -> bool:
    parsed = urlparse(url)
    hostname = clean_text(parsed.hostname).lower()
    if hostname not in {"yeoncheon.go.kr", YEONCHEON_RESERVE_HOST}:
        return False
    if parsed.path != YEONCHEON_RESERVE_LIST_PATH:
        return False
    query = parse_qs(parsed.query)
    key = clean_text((query.get("key") or [""])[0])
    rep = clean_text((query.get("rep") or [""])[0])
    return key == YEONCHEON_RESERVE_KEY and rep in {"", "1"}


def canonical_yeoncheon_reserve_detail_url(page_url: str, href: Any) -> tuple[str, str]:
    candidate = normalize_link(page_url, href)
    parsed_candidate = urlparse(candidate)
    hostname = clean_text(parsed_candidate.hostname).lower()
    if hostname not in {"yeoncheon.go.kr", YEONCHEON_RESERVE_HOST}:
        return "", ""
    query = parse_qs(parsed_candidate.query)
    lecture_key = clean_text((query.get("searchLctreKey") or [""])[0])
    if not lecture_key.isdigit():
        return "", ""
    parsed_page = urlparse(page_url)
    scheme = parsed_page.scheme if parsed_page.scheme in {"http", "https"} else "https"
    netloc = parsed_page.netloc or YEONCHEON_RESERVE_HOST
    detail_url = urlunparse(
        (
            scheme,
            netloc,
            YEONCHEON_RESERVE_DETAIL_PATH,
            "",
            urlencode((("key", YEONCHEON_RESERVE_KEY), ("searchLctreKey", lecture_key))),
            "",
        )
    )
    return detail_url, lecture_key


def yeoncheon_reserve_page_totals(soup: BeautifulSoup) -> tuple[Optional[int], int]:
    text = clean_text(soup.get_text(" ", strip=True))
    total_match = re.search(r"총\s*([\d,]+)\s*건", text)
    total_count = int(total_match.group(1).replace(",", "")) if total_match else None
    page_numbers: list[int] = []
    pager_selector = ", ".join(
        f"{container} a[href*='pageIndex=']"
        for container in (".p-page", ".pagination", ".paging", ".p-pagination")
    )
    for link in soup.select(pager_selector):
        label = clean_text(link.get_text(" ", strip=True))
        if not (
            label.isdigit()
            or "끝 페이지" in label
            or "마지막 페이지" in label
            or label.lower() in {"last", "end"}
        ):
            continue
        query = parse_qs(urlparse(normalize_link("https://example.invalid/", link.get("href"))).query)
        if clean_text((query.get("searchLctreKey") or [""])[0]):
            continue
        value = clean_text((query.get("pageIndex") or [""])[0])
        if value.isdigit():
            page_numbers.append(int(value))
    calculated_pages = (
        max(1, (total_count + YEONCHEON_RESERVE_PAGE_UNIT - 1) // YEONCHEON_RESERVE_PAGE_UNIT)
        if total_count is not None
        else 0
    )
    return total_count, max(calculated_pages, max(page_numbers, default=0))


def yeoncheon_reserve_branch_code(provider: str, branch: str) -> str:
    slug = re.sub(r"[^A-Za-z0-9가-힣]+", "_", clean_text(branch)).strip("_")[:24]
    digest = hashlib.sha1(f"{provider}|{branch}".encode("utf-8")).hexdigest()[:8].upper()
    return f"YEONCHEON_{slug}_{digest}"[:50] if slug else f"YEONCHEON_{digest}"


def yeoncheon_reserve_periods(value: Any) -> tuple[str, str, str]:
    text = clean_text(value)
    apply_match = re.search(r"신청\s*:\s*(.*?)(?=\s*교육\s*:|$)", text)
    period_match = re.search(r"교육\s*:\s*(.*?)(?=\s*(?:요일|강의시간)\s*:|$)", text)
    schedule_match = re.search(r"(?:요일|강의시간)\s*:\s*(.+)", text)
    return (
        geumcheon_normalize_date_text(apply_match.group(1) if apply_match else ""),
        geumcheon_normalize_date_text(period_match.group(1) if period_match else text),
        clean_text(schedule_match.group(1) if schedule_match else ""),
    )


def yeoncheon_reserve_cancelled(value: Any) -> bool:
    return "폐강" in clean_text(value).replace(" ", "")


def collect_yeoncheon_reserve_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    base_query["key"] = [YEONCHEON_RESERVE_KEY]
    base_query["rep"] = ["1"]
    base_query["pageUnit"] = [str(YEONCHEON_RESERVE_PAGE_UNIT)]

    rows: list[dict[str, Any]] = []
    seen_lectures: set[str] = set()
    pages = 0
    detail_pages = 0
    detail_attempts = 0
    total_count: Optional[int] = None
    total_pages = 0
    pagination_exhausted = False
    partial_collection_error = ""
    expired_count = 0
    cancelled_count = 0
    page_cap = max(1, max_pages)

    for page in range(1, page_cap + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1

        page_total_count, page_total_pages = yeoncheon_reserve_page_totals(soup)
        if page_total_count is not None:
            total_count = page_total_count
        total_pages = max(total_pages, page_total_pages)
        links = soup.select("table tbody tr a[href*='searchLctreKey=']")
        page_new_items = 0

        for link in links:
            tr = link.find_parent("tr")
            if tr is None:
                continue
            cells = tr.find_all("td", recursive=False)
            if len(cells) < 7:
                cells = tr.find_all("td")
            if len(cells) < 7:
                continue
            detail_url, lecture_key = canonical_yeoncheon_reserve_detail_url(page_url, link.get("href"))
            if not detail_url or lecture_key in seen_lectures:
                continue
            seen_lectures.add(lecture_key)
            page_new_items += 1

            title = clean_text(link.get_text(" ", strip=True))
            if not title or is_low_value_title(title):
                continue
            subject_cell = link.find_parent("td")
            venue_node = subject_cell.find("p") if subject_cell else None
            list_venue = clean_text(venue_node.get_text(" ", strip=True) if venue_node else "")
            list_branch = list_venue or clean_text(target.branch) or "연천군 통합예약"
            status_text = clean_text(cells[0].get_text(" ", strip=True))
            apply_period, period, list_schedule = yeoncheon_reserve_periods(
                cells[2].get_text(" ", strip=True)
            )
            capacity_current, capacity_total = parse_capacity_pair(cells[3].get_text(" ", strip=True))
            waitlist_current, waitlist_total = parse_capacity_pair(cells[4].get_text(" ", strip=True))
            selection_fee_parts = [
                clean_text(part.get_text(" ", strip=True))
                for part in cells[5].find_all("p")
                if clean_text(part.get_text(" ", strip=True))
            ]
            if not selection_fee_parts:
                selection_fee_parts = [
                    clean_text(part)
                    for part in cells[5].stripped_strings
                    if clean_text(part)
                ]
            selection_method = selection_fee_parts[0] if selection_fee_parts else ""
            fee = selection_fee_parts[1] if len(selection_fee_parts) > 1 else ""
            application_method_raw = clean_text(cells[6].get_text(" ", strip=True))
            start_date, end_date = parse_date_range(period)
            apply_start, apply_end = parse_date_range(apply_period)
            status = normalize_status(status_text, title) or geumcheon_status(status_text)
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": f"{target.provider}:edc:{lecture_key}"[:100],
                "title": title,
                "branch": list_branch,
                "branch_code": yeoncheon_reserve_branch_code(target.provider, list_branch),
                "preserve_branch": True,
                "branch_url": target.url,
                "raw_url": detail_url,
                "status": status,
                "period": period,
                "apply_period": apply_period,
                "start_date": start_date,
                "end_date": end_date,
                "apply_start": apply_start,
                "apply_end": apply_end,
                "schedule_raw": list_schedule,
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "waitlist_current": waitlist_current,
                "waitlist_total": waitlist_total,
                "selection_method": selection_method,
                "fee": fee,
                "application_method_raw": application_method_raw,
                "room": list_venue,
                "venue_name": list_venue,
                "provider_organizer": list_venue,
                "description": clean_text(tr.get_text(" ", strip=True))[:1000],
                "program_type": "강좌",
                "reservation_available": status == "OPEN",
                "raw_fields": {
                    "parser": "yeoncheon_reserve_lecture_list",
                    "search_lctre_key": lecture_key,
                    "list_status": status_text,
                    "list_venue": list_venue,
                    "cells": [clean_text(cell.get_text(" ", strip=True)) for cell in cells],
                    "page_url": page_url,
                },
            }

            if yeoncheon_reserve_cancelled(status_text):
                cancelled_count += 1
                continue
            if should_skip_expired_course(row):
                expired_count += 1
                continue

            detail: dict[str, Any] = {}
            if detail_attempts < max(0, detail_limit):
                detail_attempts += 1
                try:
                    detail = web_edc_detail_fields(s, detail_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug(
                        "Yeoncheon reserve lecture detail fetch failed %s: %s",
                        safe_url_for_log(detail_url),
                        exc,
                    )

            detail_status = clean_text(detail.get("status_text"))
            if yeoncheon_reserve_cancelled(detail_status):
                cancelled_count += 1
                continue
            detail_period = clean_text(detail.get("period"))
            detail_apply_period = clean_text(detail.get("apply_period"))
            if detail_period:
                row["period"] = detail_period
                row["start_date"], row["end_date"] = parse_date_range(detail_period)
            if detail_apply_period:
                row["apply_period"] = detail_apply_period
                row["apply_start"], row["apply_end"] = parse_date_range(detail_apply_period)
            if should_skip_expired_course(row):
                expired_count += 1
                continue

            actual_branch = clean_text(detail.get("venue_name")) or list_branch
            row["branch"] = actual_branch
            row["branch_code"] = yeoncheon_reserve_branch_code(target.provider, actual_branch)
            row["room"] = clean_text(detail.get("room")) or list_venue
            row["venue_name"] = clean_text(detail.get("venue_name")) or list_venue
            venue_address = clean_text(detail.get("venue_address"))
            if venue_address:
                row["address"] = venue_address
                row["venue_address"] = venue_address
            for key in ("category", "schedule_raw", "target", "fee", "phone", "capacity"):
                value = detail.get(key)
                if value not in (None, ""):
                    row[key] = value
            for key in ("capacity_current", "capacity_total", "waitlist_current", "waitlist_total"):
                value = detail.get(key)
                if value is not None:
                    row[key] = value
            row["selection_method"] = clean_text(detail.get("selection_method")) or selection_method
            row["application_method_raw"] = (
                clean_text(detail.get("application_method_raw")) or application_method_raw
            )
            row["provider_organizer"] = clean_text(detail.get("provider_organizer")) or list_venue
            row["description"] = clean_text(detail.get("description"))[:2000] or row["description"]
            row["status"] = normalize_status(detail_status or status_text, title) or status
            row["reservation_available"] = row["status"] == "OPEN"
            if row["reservation_available"]:
                row["application_url"] = detail_url
            row["raw_fields"]["parser"] = "yeoncheon_reserve_lecture_list+detail"
            row["raw_fields"]["detail_pairs"] = detail.get("raw_detail_pairs", {})
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

        if total_pages and page >= total_pages:
            pagination_exhausted = True
            break
        if page_new_items == 0:
            if total_count in {None, 0} and page == 1:
                pagination_exhausted = True
            else:
                partial_collection_error = f"page {page} did not expose new searchLctreKey rows"
            break

    if pagination_exhausted and total_count is not None and len(seen_lectures) != total_count:
        partial_collection_error = (
            f"parsed {len(seen_lectures)} of {total_count} declared searchLctreKey rows"
        )
    collection_complete = pagination_exhausted and not partial_collection_error
    source_cap_reached = bool(not collection_complete and total_pages and pages < total_pages)
    if source_cap_reached and not partial_collection_error:
        partial_collection_error = (
            f"max_pages cap reached after {pages} of {total_pages} declared pages"
        )

    no_current_data = collection_complete and not rows
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_lectures),
        "reservation_discovery_links": len(rows),
        "pagination_detected": total_pages > 1,
        "pagination_complete": collection_complete,
        "pagination_exhausted": collection_complete,
        "source_cap_reached": source_cap_reached,
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": "all listed courses are expired or cancelled" if no_current_data else "",
        "expired_count": expired_count,
        "cancelled_count": cancelled_count,
    }
    if partial_collection_error:
        meta["configured_collection_error"] = partial_collection_error
    return dedupe_rows(rows), "yeoncheon_reserve_lecture_list+detail", meta


def saha_library_title_parts(value: str) -> dict[str, str]:
    text = clean_text(value)
    pattern = (
        r"(?P<title>.*?)\s*도\s*서\s*관\s*:\s*"
        r"(?P<branch>.*?)\s*접수기간\s*:\s*"
        r"(?P<apply>\d{4}-\d{2}-\d{2}\s*~\s*\d{4}-\d{2}-\d{2})\s*"
        r"학습기간\s*:\s*(?P<period>\d{4}-\d{2}-\d{2}\s*~\s*\d{4}-\d{2}-\d{2})"
    )
    match = re.search(pattern, text)
    if not match:
        return {"title": text}
    return {key: clean_text(part) for key, part in match.groupdict().items()}


def saha_library_capacity(value: str) -> tuple[Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    match = re.search(r"(\d+)\s*/\s*(\d+)\s*/\s*(\d+)", text)
    if match:
        return int(match.group(1)), int(match.group(2)), int(match.group(3))
    current, total = parse_capacity_pair(text)
    return current, None, total


def saha_library_status(value: str) -> str:
    text = clean_text(value)
    if "접수중" in text:
        return "접수중"
    if "대기" in text:
        return "접수예정"
    if any(token in text for token in ("마감", "종강", "종료")):
        return "접수마감"
    return text


def saha_library_branch_code(provider: str, branch: str) -> str:
    slug = re.sub(r"[^A-Za-z0-9가-힣]+", "_", branch).strip("_")[:32]
    digest = hashlib.sha1(f"{provider}|{branch}".encode("utf-8")).hexdigest()[:8].upper()
    return f"{slug}_{digest}"[:50] if slug else f"{provider}_{digest}"[:50]


SAHA_LIBRARY_COURSE_TYPES = (
    ("culture", "독서문화"),
    ("deulak", "들락날락"),
)
SAHA_LIBRARY_DETAIL_WORKERS = 4


def saha_library_csrf_token(soup: BeautifulSoup) -> str:
    node = soup.select_one("form#searchForm input[name='_csrf']")
    token = clean_text(node.get("value") if node else "")
    if not token or len(token) > 200:
        raise RuntimeError("Saha library list did not expose a valid CSRF token")
    return token


def saha_library_page_info(soup: BeautifulSoup) -> tuple[int, int, int]:
    node = soup.select_one(".board_edu_page")
    values = re.findall(r"[\d,]+", clean_text(node.get_text(" ", strip=True) if node else ""))
    if len(values) < 3:
        raise RuntimeError("Saha library page summary shape changed")
    current_page, total_pages, total_count = (
        int(value.replace(",", "")) for value in values[:3]
    )
    if current_page < 1 or total_pages < 1 or current_page > total_pages or total_count < 0:
        raise RuntimeError("Saha library page summary is invalid")
    return current_page, total_pages, total_count


def saha_library_post_page(
    list_session: requests.Session,
    url: str,
    *,
    course_type: str,
    page: int,
    csrf_token: str,
    timeout: int,
) -> tuple[BeautifulSoup, str]:
    response = list_session.post(
        url,
        data={
            "page": str(page),
            "searchCourse": course_type,
            "searchLibrary": "",
            "searchTarget": "",
            "searchSdate": "",
            "searchEdate": "",
            "searchFee": "",
            "searchTxt": "",
            "_csrf": csrf_token,
        },
        timeout=timeout,
    )
    response.raise_for_status()
    soup = BeautifulSoup(response.text, "html.parser")
    return soup, saha_library_csrf_token(soup)


def saha_library_list_page_rows(
    soup: BeautifulSoup,
    *,
    course_type: str,
    course_label: str,
) -> list[dict[str, Any]]:
    table = soup.select_one("table")
    headers = [
        clean_text(node.get_text(" ", strip=True))
        for node in (table.select("thead th") if table else [])
    ]
    expected_headers = ["강좌명", "접수/대기/정원", "학습대상", "접수방법", "수강료", "상태"]
    if headers != expected_headers:
        raise RuntimeError("Saha library lecture table headers changed")

    parsed_rows: list[dict[str, Any]] = []
    for tr in table.select("tbody tr"):
        cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
        link = tr.select_one("a[onclick*='fn_view_page']")
        match = re.search(
            r"fn_view_page\(\s*['\"](?P<seq>\d{1,12})['\"]\s*\)",
            clean_text(link.get("onclick") if link else ""),
        )
        if len(cells) != 6 or not match:
            raise RuntimeError("Saha library lecture row shape changed")

        parts = saha_library_title_parts(cells[0])
        title = clean_text(parts.get("title"))
        branch = clean_text(parts.get("branch"))
        apply_period = clean_text(parts.get("apply"))
        period = clean_text(parts.get("period"))
        period_dates = re.findall(r"\b20\d{2}-\d{2}-\d{2}\b", period)
        if (
            not title
            or is_low_value_title(title)
            or not branch
            or len(period_dates) != 2
            or len(re.findall(r"\b20\d{2}-\d{2}-\d{2}\b", apply_period)) != 2
        ):
            raise RuntimeError("Saha library lecture identity or dates changed")

        capacity_current, waitlist_current, capacity_total = saha_library_capacity(cells[1])
        parsed_rows.append(
            {
                "seq": match.group("seq"),
                "course_type": course_type,
                "course_label": course_label,
                "title": title,
                "branch": branch,
                "apply_period": apply_period,
                "period": period,
                "period_end": datetime.strptime(period_dates[-1], "%Y-%m-%d").date(),
                "capacity": cells[1],
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "waitlist_current": waitlist_current,
                "target": cells[2],
                "application_method_raw": cells[3],
                "fee": cells[4],
                "status": saha_library_status(cells[5]),
                "list_cells": cells,
            }
        )
    return parsed_rows


def saha_library_detail_url(list_url: str, seq: str, *, application: bool = False) -> str:
    parsed = urlparse(list_url)
    query = parse_qs(parsed.query)
    m_id = clean_text((query.get("mId") or ["0500000000"])[0])
    endpoint = "write.do" if application else "view.do"
    path = re.sub(r"list\.do\Z", endpoint, parsed.path)
    return urlunparse(
        (
            parsed.scheme,
            parsed.netloc,
            path,
            "",
            urlencode({"mId": m_id, "seq": seq}),
            "",
        )
    )


def saha_library_detail_pairs(soup: BeautifulSoup) -> tuple[str, str, dict[str, str]]:
    table = soup.select_one("table.table_view")
    if table is None:
        raise RuntimeError("Saha library detail table is missing")
    title_node = table.select_one("th.title")
    title = clean_text(
        " ".join(
            str(value)
            for value in (title_node.find_all(string=True, recursive=False) if title_node else [])
        )
    )
    status_node = table.select_one("th.title .state")
    status = saha_library_status(
        clean_text(status_node.get_text(" ", strip=True) if status_node else "")
    )
    pairs: dict[str, str] = {}
    for label_node in table.select("th[scope='row']"):
        value_node = label_node.find_next_sibling("td")
        label = re.sub(r"\s+", "", clean_text(label_node.get_text(" ", strip=True)))
        if label and value_node is not None:
            pairs[label] = clean_text(value_node.get_text(" ", strip=True))
    return title, status, pairs


def saha_library_fee(pairs: dict[str, str], list_fee: str) -> str:
    tuition = clean_text(pairs.get("수강료")) or clean_text(list_fee) or "요금 별도 안내"
    extras: list[str] = []
    for label in ("재료비", "교재비"):
        value = clean_text(pairs.get(label))
        numeric = re.sub(r"[^\d]", "", value)
        if value and (not numeric or int(numeric) > 0):
            extras.append(f"{label} {value}")
    return f"{tuition} ({', '.join(extras)})" if extras else tuition


def saha_fetch_detail_soups_parallel(
    urls: list[str],
    timeout: int,
    *,
    workers: int = SAHA_LIBRARY_DETAIL_WORKERS,
) -> tuple[dict[int, BeautifulSoup], dict[int, str]]:
    soups: dict[int, BeautifulSoup] = {}
    failures: dict[int, str] = {}
    if not urls:
        return soups, failures

    batches: list[list[tuple[int, str]]] = [
        [] for _ in range(min(max(1, workers), len(urls)))
    ]
    for index, url in enumerate(urls):
        batches[index % len(batches)].append((index, url))

    def fetch_batch(
        batch: list[tuple[int, str]],
    ) -> tuple[dict[int, BeautifulSoup], dict[int, str]]:
        detail_session = session()
        fetched: dict[int, BeautifulSoup] = {}
        errors: dict[int, str] = {}
        try:
            for index, url in batch:
                try:
                    fetched[index] = fetch_soup(detail_session, url, timeout=timeout)
                except Exception as exc:
                    errors[index] = type(exc).__name__
                    logger.debug(
                        "Saha library detail fetch failed url=%s error_type=%s",
                        safe_url_for_log(url),
                        type(exc).__name__,
                    )
        finally:
            closer = getattr(detail_session, "close", None)
            if callable(closer):
                closer()
        return fetched, errors

    with ThreadPoolExecutor(
        max_workers=len(batches),
        thread_name_prefix="saha-library-detail",
    ) as executor:
        for fetched, errors in executor.map(fetch_batch, batches):
            soups.update(fetched)
            failures.update(errors)
    return soups, failures


def collect_saha_library_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
    *,
    session_factory: Callable[[], requests.Session] = session,
    today: Optional[date] = None,
    detail_fetcher: Optional[
        Callable[
            [list[str], int],
            tuple[dict[int, BeautifulSoup], dict[int, str]],
        ]
    ] = None,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    list_session = session_factory()
    try:
        seed_soup = fetch_soup(list_session, target.url, timeout=timeout)
        csrf_token = saha_library_csrf_token(seed_soup)
        first_pages: dict[str, BeautifulSoup] = {}
        declared: dict[str, tuple[int, int]] = {}
        for course_type, _course_label in SAHA_LIBRARY_COURSE_TYPES:
            soup, csrf_token = saha_library_post_page(
                list_session,
                target.url,
                course_type=course_type,
                page=1,
                csrf_token=csrf_token,
                timeout=timeout,
            )
            current_page, total_pages, total_count = saha_library_page_info(soup)
            if current_page != 1:
                raise RuntimeError(
                    f"Saha library {course_type} returned page {current_page} for page 1"
                )
            first_pages[course_type] = soup
            declared[course_type] = (total_pages, total_count)

        required_pages = sum(total_pages for total_pages, _total_count in declared.values())
        if required_pages > max_pages:
            raise RuntimeError(
                f"Saha library complete catalogue requires {required_pages} pages; "
                f"max_pages={max_pages}"
            )

        all_list_rows: list[dict[str, Any]] = []
        category_counts: dict[str, int] = {}
        for course_type, course_label in SAHA_LIBRARY_COURSE_TYPES:
            total_pages, total_count = declared[course_type]
            category_rows: list[dict[str, Any]] = []
            for page in range(1, total_pages + 1):
                if page == 1:
                    soup = first_pages[course_type]
                else:
                    soup, csrf_token = saha_library_post_page(
                        list_session,
                        target.url,
                        course_type=course_type,
                        page=page,
                        csrf_token=csrf_token,
                        timeout=timeout,
                    )
                current_page, returned_pages, returned_count = saha_library_page_info(soup)
                if (
                    current_page != page
                    or returned_pages != total_pages
                    or returned_count != total_count
                ):
                    raise RuntimeError(
                        f"Saha library {course_type} pagination changed at page {page}"
                    )
                category_rows.extend(
                    saha_library_list_page_rows(
                        soup,
                        course_type=course_type,
                        course_label=course_label,
                    )
                )
            if len(category_rows) != total_count:
                raise RuntimeError(
                    f"Saha library {course_type} parsed {len(category_rows)} "
                    f"of {total_count} declared rows"
                )
            category_ids = [clean_text(row.get("seq")) for row in category_rows]
            if len(set(category_ids)) != len(category_ids):
                raise RuntimeError(f"Saha library {course_type} exposed duplicate lecture IDs")
            category_counts[course_type] = len(category_rows)
            all_list_rows.extend(category_rows)
    finally:
        closer = getattr(list_session, "close", None)
        if callable(closer):
            closer()

    all_ids = [clean_text(row.get("seq")) for row in all_list_rows]
    if len(set(all_ids)) != len(all_ids):
        raise RuntimeError("Saha library course tabs exposed overlapping lecture IDs")

    current_date = today or date.today()
    current_rows = [
        row for row in all_list_rows if row["period_end"] >= current_date
    ]
    expired_count = len(all_list_rows) - len(current_rows)
    if len(current_rows) > detail_limit:
        raise RuntimeError(
            f"Saha library current details require {len(current_rows)} pages; "
            f"detail_limit={detail_limit}"
        )

    detail_urls = [
        saha_library_detail_url(target.url, clean_text(row.get("seq")))
        for row in current_rows
    ]
    fetch_details = detail_fetcher or saha_fetch_detail_soups_parallel
    detail_soups, detail_failures = fetch_details(detail_urls, timeout)
    if detail_failures or len(detail_soups) != len(detail_urls):
        raise RuntimeError(
            f"Saha library detail fetch failed for "
            f"{max(len(detail_failures), len(detail_urls) - len(detail_soups))} courses"
        )

    rows: list[dict[str, Any]] = []
    branch_alias_count = 0
    for index, list_row in enumerate(current_rows):
        detail_title, detail_status, pairs = saha_library_detail_pairs(detail_soups[index])
        required_pairs = ("작은도서관", "학습기간", "접수기간", "수강료", "교육대상", "교육주기")
        missing_pairs = [label for label in required_pairs if not clean_text(pairs.get(label))]
        if missing_pairs:
            raise RuntimeError(
                f"Saha library detail {list_row['seq']} missing fields: "
                f"{', '.join(missing_pairs)}"
            )
        if (
            detail_title != list_row["title"]
            or pairs["학습기간"] != list_row["period"]
            or pairs["접수기간"] != list_row["apply_period"]
        ):
            raise RuntimeError(
                f"Saha library detail identity mismatch for lecture {list_row['seq']}"
            )
        if pairs["작은도서관"] != list_row["branch"]:
            branch_alias_count += 1

        seq = clean_text(list_row.get("seq"))
        branch = clean_text(pairs.get("작은도서관"))
        status = detail_status or clean_text(list_row.get("status"))
        schedule = clean_text(pairs.get("교육주기"))
        fee = saha_library_fee(pairs, clean_text(list_row.get("fee")))
        detail_url = detail_urls[index]
        application_url = (
            saha_library_detail_url(target.url, seq, application=True)
            if status == "접수중"
            else ""
        )
        description = clean_text(
            " | ".join(
                part
                for part in (
                    clean_text(pairs.get("유의사항"))[:1000],
                    f"강사: {clean_text(pairs.get('강사명'))}"
                    if clean_text(pairs.get("강사명"))
                    else "",
                    f"교육방법: {clean_text(pairs.get('교육방법'))}"
                    if clean_text(pairs.get("교육방법"))
                    else "",
                    f"준비물: {clean_text(pairs.get('준비물'))}"
                    if clean_text(pairs.get("준비물"))
                    else "",
                )
                if part
            )
        )
        row = {
            "provider": target.provider,
            "provider_course_id": stable_course_id(
                target.provider,
                detail_url,
                detail_title,
                branch,
            ),
            "title": detail_title,
            "branch": branch,
            "branch_code": saha_library_branch_code(target.provider, branch),
            "category": f"도서관 프로그램/{list_row['course_label']}",
            "collection_category": "도서관",
            "domain_category": "도서관/독서문화",
            "source_group": "library",
            "service_group": "공공강좌",
            "service_group_policy": "locked",
            "raw_url": detail_url,
            "application_url": application_url,
            "application_type": "ONLINE_APPLY" if application_url else "",
            "status": status,
            "period": pairs["학습기간"],
            "apply_period": pairs["접수기간"],
            "schedule_raw": schedule,
            "target": pairs["교육대상"],
            "capacity": clean_text(pairs.get("교육정원")) or list_row["capacity"],
            "capacity_current": list_row.get("capacity_current"),
            "capacity_total": list_row.get("capacity_total"),
            "waitlist_current": list_row.get("waitlist_current"),
            "application_method_raw": clean_text(pairs.get("접수방법"))
            or list_row["application_method_raw"],
            "fee": fee,
            "instructor": clean_text(pairs.get("강사명")),
            "venue_name": branch,
            "contact": clean_text(pairs.get("문의전화")),
            "description": description,
            "raw_fields": {
                "parser": "saha_library_two_tabs_complete+current_detail",
                "lecture_seq": seq,
                "course_type": list_row["course_type"],
                "course_label": list_row["course_label"],
                "list_branch": list_row["branch"],
                "list_cells": list_row["list_cells"],
                "detail_pairs": pairs,
                "privacy_scope": "table.table_view only; applicant table excluded",
            },
        }
        rows.append(
            {
                key: value
                for key, value in row.items()
                if value not in (None, "", [], {})
            }
        )

    meta = {
        "pages": required_pages,
        "detail_pages": len(detail_urls),
        "discovered_links": len(all_list_rows),
        "reservation_discovery_links": sum(
            1 for row in rows if clean_text(row.get("application_url"))
        ),
        "pagination_detected": required_pages > len(SAHA_LIBRARY_COURSE_TYPES),
        "pagination_complete": True,
        "pagination_exhausted": True,
        "source_cap_reached": False,
        "recursion_depth": 0,
        "no_current_data": not rows,
        "no_current_reason": "all listed library courses have ended" if not rows else "",
        "expired_count": expired_count,
        "category_counts": category_counts,
        "branch_alias_count": branch_alias_count,
        "privacy_scope": "course detail table only; applicant roster excluded",
    }
    return dedupe_rows(rows), "saha_library_two_tabs_complete+current_detail", meta


def ganghwa_lifelong_status(value: str) -> str:
    text = clean_text(value).replace("[", " ").replace("]", " ")
    if "접수중" in text:
        return "접수중"
    if any(token in text for token in ("접수마감", "마감", "종료", "폐강")):
        return "접수마감"
    if any(token in text for token in ("대기", "준비", "예정")):
        return "접수예정"
    return text


def ganghwa_lifelong_periods(value: str) -> tuple[str, str, str]:
    text = clean_text(value)
    apply_match = re.search(r"접수\s*:\s*(.*?)(?=\s*-\s*교육\s*:|$)", text)
    period_match = re.search(r"교육\s*:\s*(.*)$", text)
    apply_raw = clean_text(apply_match.group(1) if apply_match else "")
    period_raw = clean_text(period_match.group(1) if period_match else text)
    methods = " ".join(dict.fromkeys(re.findall(r"([가-힣]+)\s*\(", apply_raw)))
    return normalize_mixed_date_range(apply_raw), normalize_mixed_date_range(period_raw), clean_text(methods)


def ganghwa_lifelong_capacity(value: str) -> Optional[int]:
    text = clean_text(value).replace(",", "")
    match = re.search(r"(\d{1,5})", text)
    return int(match.group(1)) if match else None


def ganghwa_lifelong_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    pairs = pairs_from_definition_lists(soup)
    description = ""
    detail_table = soup.select_one("table")
    if detail_table:
        detail_cells = detail_table.find_all("td")
        if detail_cells:
            description = clean_text(detail_cells[0].get_text(" ", strip=True))
    capacity_total = ganghwa_lifelong_capacity(pairs.get("모집인원", ""))
    return {
        "category": clean_text(pairs.get("분야")),
        "target": clean_text(pairs.get("교육대상")),
        "room": clean_text(pairs.get("교육장소")),
        "venue_name": clean_text(pairs.get("교육기관")),
        "venue_address": clean_text(pairs.get("교육장소")),
        "period": normalize_mixed_date_range(pairs.get("교육기간", "")),
        "apply_period": normalize_mixed_date_range(pairs.get("접수기간", "")),
        "schedule_raw": clean_text(pairs.get("교육요일/시간")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "capacity_total": capacity_total,
        "phone": clean_text(pairs.get("문의전화")),
        "description": description,
        "raw_detail_pairs": pairs,
    }


def collect_ganghwa_lifelong_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    list_url = normalize_link(target.url, "/open_content/main/lecture/lecture.do?act=list") or target.url
    parsed = urlparse(list_url)
    base_query = parse_qs(parsed.query)
    base_query["act"] = ["list"]

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["nowPage"] = [str(page)]
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            title_cell = tr.select_one("th.title") or tr.find("th")
            link = title_cell.select_one("p.lecture a[href], a[href]") if title_cell else None
            title = clean_text(link.get_text(" ", strip=True) if link else "")
            if not title or is_low_value_title(title):
                continue
            time_node = title_cell.select_one("p.time") if title_cell else None
            schedule_raw = clean_text(time_node.get_text(" ", strip=True) if time_node else "").strip("()")
            if not schedule_raw:
                schedule_match = re.search(r"\(([^()]*\d{1,2}:\d{2}[^()]*)\)\s*$", title)
                if schedule_match:
                    schedule_raw = clean_text(schedule_match.group(1))
                    title = clean_text(title[: schedule_match.start()])
            raw_url = normalize_link(page_url, link.get("href") if link else "") or page_url
            branch = clean_text((tr.select_one("td.place") or {}).get_text(" ", strip=True) if tr.select_one("td.place") else "")
            fee = clean_text((tr.select_one("td.price") or {}).get_text(" ", strip=True) if tr.select_one("td.price") else "")
            date_text = clean_text((tr.select_one("td.date") or {}).get_text(" ", strip=True) if tr.select_one("td.date") else "")
            state_text = clean_text((tr.select_one("td.state") or {}).get_text(" ", strip=True) if tr.select_one("td.state") else "")
            apply_period, period, application_method = ganghwa_lifelong_periods(date_text)
            status = ganghwa_lifelong_status(state_text)
            detail: dict[str, Any] = {}
            if raw_url and detail_pages < detail_limit:
                try:
                    detail = ganghwa_lifelong_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("ganghwa lifelong detail fetch failed %s: %s", raw_url, exc)
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": clean_text(detail.get("venue_name")) or branch or target.branch,
                "branch_code": stable_provider(target.provider[:32], clean_text(detail.get("venue_name")) or branch or target.branch),
                "category": clean_text(detail.get("category")) or "평생교육",
                "raw_url": raw_url,
                "application_url": raw_url if status in {"접수중", "접수예정"} else "",
                "status": status,
                "period": clean_text(detail.get("period")) or period,
                "apply_period": clean_text(detail.get("apply_period")) or apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")) or schedule_raw,
                "target": clean_text(detail.get("target")),
                "fee": clean_text(detail.get("fee")) or fee,
                "room": clean_text(detail.get("room")),
                "venue_name": clean_text(detail.get("venue_name")) or branch,
                "venue_address": clean_text(detail.get("venue_address")),
                "capacity_total": detail.get("capacity_total"),
                "application_method_raw": clean_text(detail.get("application_method_raw")) or application_method,
                "phone": clean_text(detail.get("phone")),
                "description": clean_text(detail.get("description")) or clean_text(" ".join([title, branch, fee, date_text, state_text])),
                "raw_fields": {
                    "parser": "ganghwa_lifelong_lecture_table+detail",
                    "list_page_url": page_url,
                    "date_text": date_text,
                    "state_text": state_text,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1

        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='nowPage=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ganghwa_lifelong_lecture_table+detail", meta


def collect_sangju_reserve_list(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    labels = {"분류", "시설명", "운영기간", "주소", "접수기간", "정원", "안내"}
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for section in soup.select("#reserveList section, .list3 section"):
            lines = [clean_text(line) for line in section.get_text("\n", strip=True).splitlines() if clean_text(line)]
            number_index = next((index for index, line in enumerate(lines) if line.isdigit()), -1)
            if number_index < 0 or number_index + 1 >= len(lines):
                continue
            title = lines[number_index + 1]
            if not title or is_low_value_title(title):
                continue
            pairs = sequence_lines_to_pairs(lines, labels)
            detail_id = ""
            detail_link = section.find("a", onclick=re.compile(r"reserveList\.detail"))
            if detail_link:
                match = re.search(r"detail\('([^']+)'\)", clean_text(detail_link.get("onclick")))
                detail_id = match.group(1) if match else ""
            raw_url = f"{current_url}#reserve-{detail_id}" if detail_id else current_url
            status = lines[0] if number_index > 0 and status_has_course_state(lines[0]) else status_from_lines(lines)
            if not status and lines:
                status = lines[-1]
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": clean_text(pairs.get("시설명")) or target.branch,
                    "category": clean_text(pairs.get("교육과정") or pairs.get("분류")),
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "",
                    "period": clean_text(pairs.get("교육기간") or pairs.get("운영기간")),
                    "apply_period": clean_text(pairs.get("접수일시") or pairs.get("접수기간")),
                    "schedule_raw": "",
                    "target": "",
                    "capacity": clean_text(pairs.get("정원")),
                    "capacity_current": clean_text(pairs.get("신청현황")),
                    "venue_address": clean_text(pairs.get("주소")),
                    "description": clean_text(section.get_text(" ", strip=True)),
                    "raw_fields": {"pairs": pairs, "lines": lines, "parser": "sangju_reserve_list"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pager, .pagination, .paging, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "sangju_reserve_list", meta


def collect_naju_course_reception(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 6 or not cells[0].isdigit() or "개설강좌" in " ".join(cells).replace(" ", ""):
                continue
            info = cells[1]
            title = clean_text(re.split(r"강\s*사\s*명\s*:", info)[0])
            if not title or is_low_value_title(title):
                continue
            instructor_match = re.search(r"강\s*사\s*명\s*:\s*(.*?)(?=신청기간\s*:|$)", info)
            apply_match = re.search(r"신청기간\s*:\s*(.*?)(?=교육기간\s*:|$)", info)
            period_match = re.search(r"교육기간\s*:\s*(.*)$", info)
            view_link = tr.find("a", href=re.compile(r"mode=view"))
            reserve_link = tr.find("a", href=re.compile(r"mode=reserve_form"))
            raw_url = normalize_link(current_url, view_link.get("href") if view_link else None) or current_url
            application_url = normalize_link(current_url, reserve_link.get("href") if reserve_link else None) or raw_url
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, cells[2]),
                "title": title,
                "branch": cells[2],
                "category": "",
                "raw_url": raw_url,
                "application_url": application_url,
                "status": cells[5].replace("접수하기", "").strip(),
                "fee": cells[4],
                "period": clean_text(period_match.group(1)) if period_match else "",
                "apply_period": clean_text(apply_match.group(1)) if apply_match else "",
                "schedule_raw": "",
                "target": "",
                "capacity": cells[3],
                "instructor": clean_text(instructor_match.group(1)) if instructor_match else "",
                "description": clean_text(tr.get_text(" ", strip=True)),
                "raw_fields": {"cells": cells, "parser": "naju_course_reception"},
            }
            if raw_url and detail_pages < 30:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    pairs = pairs_from_tables(detail_soup)
                    row["target"] = clean_text(pairs.get("교육대상")) or row["target"]
                    row["category"] = clean_text(pairs.get("교육분류")) or row["category"]
                    row["venue_name"] = clean_text(pairs.get("교육장소")) or row["branch"]
                    row["description"] = clean_text(pairs.get("강좌소개") or pairs.get("강의계획") or row["description"])
                except Exception as exc:
                    logger.debug("Naju detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "naju_course_reception", meta


