def daejeon_ok_detail_url(current_url: str, onclick: str) -> str:
    text = clean_text(onclick)
    match = re.search(r"moveToFcltInfoMngDetail\((.*?)\)", text)
    if not match:
        return current_url
    values = [part.strip().strip("'\"") for part in match.group(1).split(",")]
    if len(values) < 4:
        return current_url
    keys = ("itecd", "fcltSeq", "rsvtSeq", "rsvtDtlSeq", "RSVT_MTHD_TPCD", "statCd", "dgr", "tabNo")
    params = {key: values[index] for index, key in enumerate(keys) if index < len(values)}
    return urljoin(current_url, "/okr2019/eduRsvtDtl.do?" + urlencode(params))


def collect_daejeon_ok_reservation(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False
    no_current_data = False

    for page in range(1, max_pages + 1):
        query = {key: list(value) for key, value in base_query.items()}
        if page > 1:
            query["pageIdx"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        page_text = clean_text(soup.get_text(" ", strip=True))
        no_current_data = no_current_data or "등록된 자료가 존재하지 않습니다" in page_text or bool(re.search(r"총\s*0\s*건", page_text))
        pages += 1
        page_rows = 0

        headers = [clean_text(th.get_text(" ", strip=True)) for th in soup.select("table.ntable_styl thead th")]
        for tr in soup.select("table.ntable_styl tbody tr"):
            cells_el = tr.find_all("td")
            cells = [clean_text(td.get_text(" ", strip=True)) for td in cells_el]
            if len(cells) < 8:
                continue
            by_header = {
                headers[index]: cells[index]
                for index in range(min(len(headers), len(cells)))
                if headers[index]
            }
            title_link = tr.find("a", onclick=re.compile(r"moveToFcltInfoMngDetail")) or tr.find(
                "a", href=re.compile(r"moveToFcltInfoMngDetail")
            )
            title = clean_text(title_link.get_text(" ", strip=True) if title_link else by_header.get("예약명") or cells[2])
            if not title or is_low_value_title(title):
                continue
            branch = clean_text(by_header.get("시설명") or cells[1] or target.branch)
            apply_period = clean_text(by_header.get("접수기간") or cells[4])
            period = clean_text(by_header.get("이용기간") or cells[5])
            fee = clean_text(by_header.get("수강료") or cells[6])
            capacity = clean_text(by_header.get("접수자/정원") or cells[7])
            status = clean_text(by_header.get("접수상태") or (cells[8] if len(cells) > 8 else ""))
            raw_url = daejeon_ok_detail_url(
                current_url,
                (title_link.get("onclick") or title_link.get("href") or "") if title_link else "",
            )
            capacity_current, capacity_total = parse_capacity_pair(capacity)
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": "강좌/교육",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": fee,
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": period,
                    "target": "전체",
                    "capacity": capacity,
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "venue_name": branch,
                    "description": clean_text(" ".join(cells)),
                    "raw_fields": {"headers": headers, "cells": cells, "parser": "daejeon_ok_table"},
                }
            )
            page_rows += 1

        pagination_detected = pagination_detected or bool(
            soup.select(".pagination, .paging, a[onclick*='pageIdx'], a[href*='pageIdx']")
        )
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "no_current_data": no_current_data and not rows,
        "no_current_reason": "no_current_daejeon_ok_reservation" if no_current_data and not rows else "",
    }
    return dedupe_rows(rows), "daejeon_ok_table", meta


def collect_gangneung_unity_reservation(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    pagination_detected = False
    pagination_exhausted = False
    seen_signatures: set[tuple[str, ...]] = set()
    per_target_limit = int(target.extra.get("per_target_limit") or 0)

    for page in range(1, max(1, max_pages) + 1):
        if page > 1:
            query["pageIndex"] = [str(page)]
            query.setdefault("pageUnit", ["8"])
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        cards = soup.select(".edu_list .edu_item")
        if not cards:
            pagination_exhausted = True
            break
        signature = tuple(
            clean_text(
                (item.select_one(".edu_title") or item).get_text(
                    " ",
                    strip=True,
                )
            )
            for item in cards
        )
        if signature in seen_signatures:
            pagination_exhausted = True
            break
        seen_signatures.add(signature)

        for item in cards:
            title_node = item.select_one(".edu_title")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            if not title:
                continue
            link = item.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            pairs: dict[str, str] = {}
            for li in item.select(".edu_content li"):
                label_node = li.select_one(".edu_dt")
                value_node = li.select_one(".edu_dd")
                label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
                value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
                if label and value:
                    pairs[label] = value
            category_node = item.select_one(".edu_type")
            fee_node = item.select_one(".edu_price")
            category = clean_text(category_node.get_text(" ", strip=True) if category_node else "")
            fee = clean_text(fee_node.get_text(" ", strip=True) if fee_node else "")
            status = next(
                (
                    value
                    for value in (clean_text(button.get_text(" ", strip=True)) for button in item.select(".edu_btn_wrap .edu_btn"))
                    if value and "상세" not in value
                ),
                "",
            )
            venue = clean_text(pairs.get("장소"))
            apply_period = normalize_mixed_date_range(pairs.get("접수", ""))
            operation_period = normalize_mixed_date_range(pairs.get("운영", ""))
            text = clean_text(item.get_text(" ", strip=True))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": category,
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": fee,
                    "period": operation_period,
                    "apply_period": apply_period,
                    "schedule_raw": operation_period,
                    "target": clean_text(pairs.get("대상")),
                    "room": venue,
                    "venue_name": venue,
                    "description": text,
                    "image_url": normalize_link(current_url, (item.find("img") or {}).get("src") if item.find("img") else None),
                    "collection_category": "공공예약",
                    "domain_category": "공공예약",
                    "operator_type": "지자체/공공기관",
                    "source_group": "public_reservation",
                    "collection_type": "static_html",
                    "application_type": "ONLINE_RESERVATION",
                    "reservation_available": status in {"접수중", "대기자접수"},
                    "raw_fields": {"list_pairs": pairs, "parser": "gangneung_unity_reservation_card"},
                }
            )
            page_rows += 1
            if per_target_limit > 0 and len(rows) >= per_target_limit:
                break

        pagination_detected = pagination_detected or bool(
            soup.select(".p-pagination, .pagination, .paging, a[href*='pageIndex=']")
        )
        if len(cards) < int((query.get("pageUnit") or ["8"])[0]):
            pagination_exhausted = True
            break
        if per_target_limit > 0 and len(rows) >= per_target_limit:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "source_cap_reached": not pagination_exhausted,
        "recursion_depth": 0,
    }
    if not rows:
        meta["no_current_data"] = True
        meta["no_current_reason"] = "no_reservation_programs"
    return dedupe_rows(rows), "gangneung_unity_reservation_card", meta


GANGNEUNG_UNITY_EDUCATION_PROVIDER = "MUNI_WWW_GN_GO_KR_E6671160"
GANGNEUNG_UNITY_EDUCATION_LIST_PATH = "/yeyak/selectUnityProgrmWebList.do"
GANGNEUNG_UNITY_EDUCATION_DETAIL_PATH = "/yeyak/unityProgrmWebView.do"
GANGNEUNG_UNITY_EDUCATION_APPLY_PATH = "/yeyak/unityProgrmReqCldrWebView.do"
GANGNEUNG_UNITY_EDUCATION_STATES: tuple[tuple[str, str], ...] = (
    ("URORST01", "접수대기"),
    ("URORST02", "접수중"),
    ("URORST03", "대기자접수"),
    ("URORST04", "추가접수"),
    ("URORST05", "접수마감"),
    ("URORST06", "운영중"),
)


def gangneung_declared_page_count(soup: BeautifulSoup, list_path: str) -> int:
    pages = {1}
    for node in soup.select("a[href], a[onclick]"):
        href = clean_text(node.get("href"))
        onclick = clean_text(node.get("onclick"))
        if href:
            parsed = urlparse(href)
            if parsed.scheme.lower() != "javascript" and parsed.path and not parsed.path.endswith(list_path):
                href = ""
        value = f"{href} {onclick}"
        for pattern in (
            r"(?:[?&]pageIndex=)(\d+)",
            r"fn_egov_link_page\s*\(\s*['\"]?(\d+)",
        ):
            pages.update(int(match) for match in re.findall(pattern, value) if int(match) > 0)
    return max(pages)


def gangneung_unity_program_number(base_url: str, href: Any) -> str:
    candidate = normalize_link(base_url, clean_text(href))
    if not candidate:
        return ""
    parsed = urlparse(candidate)
    if parsed.netloc.lower() != "www.gn.go.kr" or parsed.path != GANGNEUNG_UNITY_EDUCATION_DETAIL_PATH:
        return ""
    program_no = clean_text((parse_qs(parsed.query).get("progrmNo") or [""])[0])
    return program_no if program_no.isdigit() else ""


def gangneung_unity_program_url(key: str, program_no: str) -> str:
    return (
        f"https://www.gn.go.kr{GANGNEUNG_UNITY_EDUCATION_DETAIL_PATH}?"
        f"{urlencode({'key': key, 'progrmNo': program_no})}"
    )


def gangneung_unity_application_url(key: str, program_no: str) -> str:
    return (
        f"https://www.gn.go.kr{GANGNEUNG_UNITY_EDUCATION_APPLY_PATH}?"
        f"{urlencode({'key': key, 'progrmNo': program_no})}"
    )


def gangneung_unity_status(state_code: str, status_text: Any) -> str:
    if state_code in {"URORST02", "URORST04"}:
        return "OPEN"
    if state_code == "URORST03":
        return "WAITING"
    if state_code == "URORST01":
        return "SCHEDULED"
    text = clean_text(status_text)
    if "대기자접수" in text or "대기접수" in text:
        return "WAITING"
    if "접수중" in text or "추가접수" in text:
        return "OPEN"
    if "접수대기" in text:
        return "SCHEDULED"
    return "CLOSED"


def gangneung_unity_detail_pairs(soup: BeautifulSoup) -> tuple[dict[str, str], dict[str, str]]:
    pairs: dict[str, str] = {}
    for label_node in soup.select(".info_subject"):
        container = label_node.find_parent("li") or label_node.parent
        value_node = container.select_one(".info_text") if container and hasattr(container, "select_one") else None
        label = clean_text(label_node.get_text(" ", strip=True))
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if label and value:
            pairs[label] = value

    location_pairs: dict[str, str] = {}
    for label_node in soup.select(".dt"):
        container = label_node.find_parent("li") or label_node.parent
        value_node = container.select_one(".dd") if container and hasattr(container, "select_one") else None
        label = clean_text(label_node.get_text(" ", strip=True))
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if label and value:
            location_pairs[label] = value
    return pairs, location_pairs


def gangneung_unity_detail_fields(soup: BeautifulSoup) -> dict[str, Any]:
    pairs, location_pairs = gangneung_unity_detail_pairs(soup)
    capacity_total = parse_capacity_number(pairs.get("모집인원"))
    waitlist_total = parse_capacity_number(pairs.get("대기모집인원"))
    period = normalize_mixed_date_range(pairs.get("운영기간", ""))
    apply_period = normalize_mixed_date_range(pairs.get("접수기간", ""))
    weekday = clean_text(pairs.get("요일"))
    education_time = clean_text(pairs.get("교육시간"))
    description_node = soup.select_one(".tab_content.active pre") or soup.select_one(".tab_content.active")
    description = clean_text(description_node.get_text(" ", strip=True) if description_node else "")
    address = clean_text(location_pairs.get("주소"))
    phone = clean_text(location_pairs.get("전화번호")) or clean_text(pairs.get("문의전화"))
    return {
        "branch": clean_text(pairs.get("운영기관")),
        "venue_name": clean_text(pairs.get("장소")),
        "room": clean_text(pairs.get("장소")),
        "address": address,
        "venue_address": address,
        "phone": phone,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": clean_text(" / ".join(part for part in (weekday, education_time) if part)),
        "target": clean_text(pairs.get("대상")),
        "eligibility_raw": clean_text(
            " / ".join(
                part
                for part in (clean_text(pairs.get("대상")), clean_text(pairs.get("신청(연령)제한")))
                if part
            )
        ),
        "fee": clean_text(pairs.get("이용요금")),
        "capacity_total": capacity_total,
        "waitlist_total": waitlist_total,
        "selection_method": clean_text(pairs.get("선별방법")),
        "application_method_raw": clean_text(pairs.get("신청방법")),
        "payment_method": clean_text(pairs.get("결제방법")),
        "materials": clean_text(pairs.get("준비물")),
        "description": description,
        "raw_fields": {"detail_pairs": pairs, "location_pairs": location_pairs},
    }


def collect_gangneung_unity_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query, keep_blank_values=True)
    key = clean_text((base_query.get("key") or [""])[0])
    instt_type = clean_text((base_query.get("insttTy") or [""])[0])
    errors: list[str] = []
    if (
        target.provider != GANGNEUNG_UNITY_EDUCATION_PROVIDER
        or parsed.netloc.lower() != "www.gn.go.kr"
        or parsed.path != GANGNEUNG_UNITY_EDUCATION_LIST_PATH
        or not key.isdigit()
        or instt_type != "URINTY01"
    ):
        errors.append("target does not match the canonical Gangneung education reservation source")

    s = session()
    listed_rows: list[dict[str, Any]] = []
    seen_programs: set[str] = set()
    pages = 0
    status_pages: dict[str, int] = {}
    declared_pages_by_status: dict[str, int] = {}
    status_complete: dict[str, bool] = {}
    source_cap_reached = False
    invalid_cards = 0
    duplicate_programs = 0

    if not errors:
        for state_code, expected_status in GANGNEUNG_UNITY_EDUCATION_STATES:
            state_complete = False
            state_pages = 0
            state_declared_pages = 1
            for page in range(1, max(1, max_pages) + 1):
                query = {name: list(values) for name, values in base_query.items()}
                query["searchOperSttus"] = [state_code]
                query["pageIndex"] = [str(page)]
                query["pageUnit"] = ["8"]
                query.setdefault("searchCnd", ["all"])
                current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
                try:
                    soup = fetch_soup(s, current_url, timeout=timeout)
                except Exception as exc:
                    errors.append(f"{state_code} page {page}: {type(exc).__name__}")
                    logger.debug("Gangneung unity list fetch failed %s: %s", safe_url_for_log(current_url), exc)
                    break
                pages += 1
                state_pages += 1
                if page == 1:
                    state_declared_pages = gangneung_declared_page_count(
                        soup, GANGNEUNG_UNITY_EDUCATION_LIST_PATH
                    )

                page_new_rows = 0
                for item in soup.select(".edu_list .edu_item"):
                    title_node = item.select_one(".edu_title")
                    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
                    detail_link = item.select_one("a[href*='unityProgrmWebView.do'][href]")
                    program_no = gangneung_unity_program_number(
                        current_url, detail_link.get("href") if detail_link else ""
                    )
                    if not title or not program_no:
                        invalid_cards += 1
                        continue
                    if program_no in seen_programs:
                        duplicate_programs += 1
                        continue
                    seen_programs.add(program_no)
                    page_new_rows += 1
                    raw_url = gangneung_unity_program_url(key, program_no)
                    list_pairs: dict[str, str] = {}
                    for node in item.select(".edu_content li"):
                        label_node = node.select_one(".edu_dt")
                        value_node = node.select_one(".edu_dd")
                        label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
                        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
                        if label and value:
                            list_pairs[label] = value
                    category_node = item.select_one(".edu_type")
                    fee_node = item.select_one(".edu_price")
                    status_text = next(
                        (
                            value
                            for value in (
                                clean_text(button.get_text(" ", strip=True))
                                for button in item.select(".edu_btn_wrap .edu_btn")
                            )
                            if value and "상세" not in value
                        ),
                        expected_status,
                    )
                    status = gangneung_unity_status(state_code, status_text)
                    venue = clean_text(list_pairs.get("장소"))
                    period = normalize_mixed_date_range(list_pairs.get("운영", ""))
                    apply_period = normalize_mixed_date_range(list_pairs.get("접수", ""))
                    start_date, end_date = parse_date_range(period)
                    apply_start, apply_end = parse_date_range(apply_period)
                    image = item.find("img")
                    row: dict[str, Any] = {
                        "provider": target.provider,
                        "provider_course_id": f"{target.provider}:program:{program_no}"[:100],
                        "prefer_incoming_provider_course_id": True,
                        "title": title,
                        "branch": target.branch,
                        "branch_code": stable_provider(target.provider[:32], target.branch),
                        "preserve_branch": True,
                        "branch_url": target.url,
                        "category": clean_text(category_node.get_text(" ", strip=True) if category_node else ""),
                        "program_type": "강좌",
                        "raw_url": raw_url,
                        "status": status,
                        "fee": clean_text(fee_node.get_text(" ", strip=True) if fee_node else ""),
                        "period": period,
                        "apply_period": apply_period,
                        "start_date": start_date,
                        "end_date": end_date,
                        "apply_start": apply_start,
                        "apply_end": apply_end,
                        "target": clean_text(list_pairs.get("대상")),
                        "venue_name": venue,
                        "room": venue,
                        "description": clean_text(item.get_text(" ", strip=True)),
                        "image_url": normalize_link(current_url, image.get("src") if image else None),
                        "collection_category": "공공예약",
                        "domain_category": "교육·강좌",
                        "operator_type": "지자체/공공기관",
                        "source_group": "municipal_reservation",
                        "collection_type": "state_filters+detail_html",
                        "service_group": "공공강좌",
                        "service_group_policy": "locked",
                        "reservation_available": False,
                        "raw_fields": {
                            "list_pairs": list_pairs,
                            "parser": "gangneung_unity_education_state_filters+detail",
                            "program_no": program_no,
                            "state_code": state_code,
                            "list_status": status_text,
                            "page_url": current_url,
                        },
                    }
                    listed_rows.append(
                        {name: value for name, value in row.items() if value not in (None, "", [], {})}
                    )

                if page_new_rows == 0 and (page > 1 or state_declared_pages > 1):
                    errors.append(f"{state_code} page {page} did not expose new progrmNo rows")
                    break
                if page >= state_declared_pages:
                    state_complete = True
                    break

            status_pages[state_code] = state_pages
            declared_pages_by_status[state_code] = state_declared_pages
            status_complete[state_code] = state_complete
            if not state_complete and state_pages >= max(1, max_pages):
                source_cap_reached = True
                errors.append(
                    f"{state_code} max_pages cap reached after {state_pages} of {state_declared_pages} pages"
                )

    if invalid_cards:
        errors.append(f"{invalid_cards} list cards were missing title or canonical progrmNo")
    if duplicate_programs:
        errors.append(f"{duplicate_programs} duplicate progrmNo cards were returned by state pagination")

    allowed_details = max(0, detail_limit)
    if allowed_details < len(listed_rows):
        source_cap_reached = True
        errors.append(
            f"detail_limit cap allows {allowed_details} of {len(listed_rows)} required detail pages"
        )

    detail_pages = 0
    detail_attempts = 0
    detail_errors: list[str] = []
    for row in listed_rows[:allowed_details]:
        detail_attempts += 1
        raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
        program_no = clean_text(raw_fields.get("program_no"))
        detail_url = clean_text(row.get("raw_url"))
        try:
            detail_soup = fetch_soup(s, detail_url, timeout=timeout)
            detail_pages += 1
            detail = gangneung_unity_detail_fields(detail_soup)
            detail_raw = detail.pop("raw_fields", {})
            row.update({name: value for name, value in detail.items() if value not in (None, "", [], {})})
            branch = clean_text(row.get("branch")) or target.branch
            row["branch"] = branch
            row["branch_code"] = stable_provider(target.provider[:32], branch)
            row["preserve_branch"] = True
            row["start_date"], row["end_date"] = parse_date_range(row.get("period"))
            row["apply_start"], row["apply_end"] = parse_date_range(row.get("apply_period"))
            has_apply_route = bool(detail_soup.select_one("a[onclick*='fn_reqChk']")) or (
                GANGNEUNG_UNITY_EDUCATION_APPLY_PATH.rsplit("/", 1)[-1] in str(detail_soup)
            )
            if row.get("status") in {"OPEN", "WAITING"} and has_apply_route:
                row["application_url"] = gangneung_unity_application_url(key, program_no)
                row["application_type"] = "ONLINE_RESERVATION"
                row["reservation_available"] = True
            else:
                row.pop("application_url", None)
                row.pop("application_type", None)
                row["reservation_available"] = False
                raw_fields["clear_application_url"] = True
            row["raw_fields"] = {
                **raw_fields,
                **detail_raw,
                "parser": "gangneung_unity_education_state_filters+detail",
            }
        except Exception as exc:
            detail_errors.append(f"progrmNo {program_no}: {type(exc).__name__}")
            logger.debug("Gangneung unity detail fetch failed %s: %s", safe_url_for_log(detail_url), exc)

    if detail_errors:
        errors.append(
            f"detail fetch failed for {len(detail_errors)} of {len(listed_rows)} programs "
            f"({', '.join(detail_errors[:5])})"
        )

    rows: list[dict[str, Any]] = []
    expired_count = 0
    for row in listed_rows:
        if should_skip_expired_course(row):
            expired_count += 1
            continue
        rows.append({name: value for name, value in row.items() if value not in (None, "", [], {})})

    list_complete = (
        bool(status_complete)
        and all(status_complete.values())
        and not invalid_cards
        and not duplicate_programs
    )
    details_complete = detail_pages == len(listed_rows) and not detail_errors
    snapshot_complete = list_complete and details_complete and not errors
    no_current_data = snapshot_complete and not rows
    meta: dict[str, Any] = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "status_pages": status_pages,
        "declared_pages_by_status": declared_pages_by_status,
        "status_complete": status_complete,
        "discovered_links": len(seen_programs),
        "reservation_discovery_links": sum(
            bool(clean_text(row.get("application_url"))) for row in rows
        ),
        "reservation_fallback_pages": 0,
        "pagination_detected": any(value > 1 for value in declared_pages_by_status.values()),
        "pagination_complete": list_complete,
        "pagination_exhausted": list_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached,
        "recursion_depth": 0,
        "expired_count": expired_count,
        "current_count": len(rows),
        "no_current_data": no_current_data,
        "no_current_reason": "official non-ended education list is empty" if no_current_data else "",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(rows), "gangneung_unity_education_state_filters+detail", meta


