def is_yangju_education_target(target: Any) -> bool:
    parsed = urlparse(clean_text(getattr(target, "url", "")))
    return bool(
        clean_text(getattr(target, "provider", "")) == YANGJU_EDUCATION_PROVIDER
        and parsed.scheme.lower() == "https"
        and clean_text(parsed.hostname).lower() == YANGJU_EDUCATION_HOST
        and parsed.path == YANGJU_EDUCATION_LIST_PATH
        and parse_qs(parsed.query) == {"key": [YANGJU_EDUCATION_KEY]}
    )


def yangju_education_list_url(page: Any) -> str:
    try:
        number = int(page)
    except (TypeError, ValueError) as exc:
        raise ValueError("Yangju page must be an integer") from exc
    if number < 1:
        raise ValueError("Yangju page must be positive")
    return f"{YANGJU_EDUCATION_CANONICAL_URL}&pageIndex={number}"


def canonical_yangju_detail_url(page_url: str, href: Any) -> tuple[str, str]:
    parsed = urlparse(normalize_link(page_url, href))
    query = parse_qs(parsed.query)
    lecture_no = clean_text((query.get("eduLctreNo") or [""])[0])
    if not (
        parsed.scheme.lower() == "https"
        and clean_text(parsed.hostname).lower() == YANGJU_EDUCATION_HOST
        and parsed.path == YANGJU_EDUCATION_DETAIL_PATH
        and lecture_no.isdigit()
        and clean_text((query.get("key") or [YANGJU_EDUCATION_KEY])[0]) == YANGJU_EDUCATION_KEY
    ):
        return "", ""
    return (
        f"https://{YANGJU_EDUCATION_HOST}{YANGJU_EDUCATION_DETAIL_PATH}"
        f"?key={YANGJU_EDUCATION_KEY}&eduLctreNo={lecture_no}",
        lecture_no,
    )


def canonical_yangju_application_url(page_url: str, href: Any, lecture_no: str) -> str:
    parsed = urlparse(normalize_link(page_url, href))
    query = parse_qs(parsed.query)
    if not (
        parsed.scheme.lower() == "https"
        and clean_text(parsed.hostname).lower() == YANGJU_EDUCATION_HOST
        and parsed.path == YANGJU_EDUCATION_APPLICATION_PATH
        and clean_text((query.get("eduLctreNo") or [""])[0]) == lecture_no
        and clean_text((query.get("key") or [YANGJU_EDUCATION_KEY])[0]) == YANGJU_EDUCATION_KEY
    ):
        return ""
    return (
        f"https://{YANGJU_EDUCATION_HOST}{YANGJU_EDUCATION_APPLICATION_PATH}"
        f"?key={YANGJU_EDUCATION_KEY}&eduLctreNo={lecture_no}"
    )


def yangju_page_contract(soup: BeautifulSoup) -> Optional[tuple[int, int, int]]:
    nodes = soup.select("div.bbs_info div.bbs_count")
    if len(nodes) != 1:
        return None
    match = re.fullmatch(
        r"총\s*([\d,]+)\s*건\s*,?\s*\[\s*(\d+)\s*/\s*(\d+)\s*페이지\s*\]",
        clean_text(nodes[0].get_text(" ", strip=True)),
    )
    if not match:
        return None
    return int(match.group(1).replace(",", "")), int(match.group(2)), int(match.group(3))


def yangju_capacity(value: Any) -> tuple[Optional[int], Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    capacity_pair = re.search(r"정원\s*[:：]?\s*(\d+)\s*/\s*(\d+)", text)
    capacity_single = re.search(r"정원\s*[:：]?\s*(\d+)\s*명", text)
    wait_pair = re.search(r"대기\s*[:：]?\s*\(?\s*(\d+)\s*/\s*(\d+)\s*\)?", text)
    wait_single = re.search(r"대기\s*[:：]?\s*(\d+)\s*명", text)
    return (
        int(capacity_pair.group(1)) if capacity_pair else None,
        int(capacity_pair.group(2)) if capacity_pair else int(capacity_single.group(1)) if capacity_single else None,
        int(wait_pair.group(1)) if wait_pair else None,
        int(wait_pair.group(2)) if wait_pair else int(wait_single.group(1)) if wait_single else None,
    )


def yangju_canonical_list_cells(cells: list[Any]) -> tuple[list[Any], str]:
    """Collapse the official desktop/mobile capacity duplicate into nine semantic cells."""
    if len(cells) == len(YANGJU_EDUCATION_HEADERS):
        return cells, ""
    if len(cells) != len(YANGJU_EDUCATION_HEADERS) + 1:
        return [], f"expected 9 or 10 cells, got {len(cells)}"
    desktop_capacity = yangju_capacity(cells[5].get_text(" ", strip=True))
    mobile_capacity = yangju_capacity(cells[6].get_text(" ", strip=True))
    if (
        desktop_capacity[1] is None
        or mobile_capacity[1] is None
        or desktop_capacity != mobile_capacity
    ):
        return [], "responsive capacity columns disagree"
    return [*cells[:6], *cells[7:]], ""


def yangju_branch_code(provider: str, branch: Any) -> str:
    digest = hashlib.sha1(f"{provider}|{clean_text(branch)}".encode("utf-8")).hexdigest()[:10].upper()
    return f"YANGJU_{digest}"


def yangju_source_row_is_current(row: dict[str, Any], today: Optional[date] = None) -> bool:
    raw_fields = row.get("raw_fields") or {}
    source_status = clean_text(raw_fields.get("source_status"))
    if source_status == "교육종료":
        return False
    if raw_fields.get("course_period_undated") is True:
        return source_status in YANGJU_ACTIVE_SOURCE_STATUSES
    current_date = today or date.today()
    if source_status in YANGJU_ACTIVE_SOURCE_STATUSES:
        return True
    end_value = clean_text(row.get("end_date"))
    if source_status == "접수마감":
        try:
            return date.fromisoformat(end_value) >= current_date
        except ValueError:
            return False
    return False


def yangju_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    scope = soup.select_one(".education_request") or soup
    pairs = yangju_detail_pairs(scope)
    title_node = scope.select_one(".titlebox .title") or scope.select_one(".title")
    status_node = scope.select_one(".titlebox .state") or scope.select_one(".state")
    lecture_no = clean_text((parse_qs(urlparse(url).query).get("eduLctreNo") or [""])[0])
    apply_link = scope.select_one('a[href*="selectEduApplcntAgreView"]')
    capacity_current, capacity_total, wait_current, wait_total = yangju_capacity(pairs.get("모집인원"))
    descriptions = [f"{key}: {pairs[key]}" for key in ("강의개요", "유의사항") if pairs.get(key)]
    material = clean_text(pairs.get("교재 및 참고자료"))
    return {
        "title": clean_text(html.unescape(title_node.get_text(" ", strip=True))) if title_node else "",
        "branch": clean_text(pairs.get("교육기관")),
        "venue_name": clean_text(pairs.get("교육장소")),
        "room": clean_text(pairs.get("강의실")) or clean_text(pairs.get("교육장소")),
        "category": clean_text(pairs.get("분류")),
        "target": clean_text(pairs.get("수강대상")),
        "source_status": clean_text(status_node.get_text(" ", strip=True)) if status_node else "",
        "fee": clean_text(pairs.get("수강료")),
        "material_note": material,
        "material_fee": extract_material_fee_amount(material),
        "apply_period": normalize_mixed_date_range(pairs.get("접수기간", "")) or clean_text(pairs.get("접수기간")),
        "period": normalize_mixed_date_range(pairs.get("교육기간", "")) or clean_text(pairs.get("교육기간")),
        "weekday": clean_text(pairs.get("교육요일")),
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_current": wait_current,
        "waitlist_total": wait_total,
        "instructor": clean_instructor_name(pairs.get("강사명")),
        "phone": clean_text(pairs.get("전화번호")),
        "application_url": canonical_yangju_application_url(url, apply_link.get("href"), lecture_no) if apply_link else "",
        "application_link_present": bool(apply_link),
        "application_method_raw": clean_text(" ".join(value for value in (pairs.get("접수방식"), pairs.get("모집방법")) if clean_text(value))),
        "description": clean_text(" ".join(descriptions)),
        "raw_detail_pairs": pairs,
    }


def _yangju_failure(message: str) -> dict[str, Any]:
    return {
        "pages": 0, "list_requests": 0, "detail_pages": 0, "detail_attempts": 0,
        "detail_errors": 0, "discovered_links": 0, "reservation_discovery_links": 0,
        "pagination_detected": False, "pagination_complete": False,
        "pagination_exhausted": False, "details_complete": False,
        "snapshot_complete": False, "source_cap_reached": False,
        "recursion_depth": 0, "no_current_data": False, "no_current_reason": "",
        "configured_collection_error": message,
    }


def collect_yangju_edu_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 0,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if not is_yangju_education_target(target):
        return [], YANGJU_EDUCATION_PARSER, _yangju_failure("invalid canonical Yangju provider or URL")
    allowed_pages, allowed_details = max(0, int(max_pages)), max(0, int(detail_limit))
    if allowed_pages < 1:
        meta = _yangju_failure("max_pages cap allows no catalogue request")
        meta["source_cap_reached"] = True
        return [], YANGJU_EDUCATION_PARSER, meta

    s = session()
    errors: list[str] = []
    all_rows: list[dict[str, Any]] = []
    page_counts: dict[int, int] = {}
    list_requests = detail_attempts = detail_pages = detail_errors = 0
    total = last_page = required_requests = sentinel_pages = 0
    source_cap_reached = False
    try:
        first_soup = fetch_soup(s, yangju_education_list_url(1), timeout=timeout)
        list_requests = 1
    except Exception as exc:
        first_soup = None
        logger.warning(
            "Yangju education first-page fetch failed provider=%s error_type=%s",
            target.provider,
            type(exc).__name__,
        )
        errors.append(f"first page fetch {type(exc).__name__}")
    contract = yangju_page_contract(first_soup) if first_soup else None
    if not errors and contract is None:
        errors.append("missing total/page contract")
    if contract:
        total, current_page, declared_last = contract
        last_page = max(1, (total + YANGJU_EDUCATION_PAGE_UNIT - 1) // YANGJU_EDUCATION_PAGE_UNIT)
        required_requests = last_page + 1
        if (current_page, declared_last) != (1, last_page):
            errors.append("invalid first-page total contract")
        if allowed_pages < required_requests:
            source_cap_reached = True
            errors.append(f"max_pages cap allows {allowed_pages} of {required_requests} required catalogue/sentinel requests")

    if not errors and first_soup:
        for page in range(1, last_page + 1):
            page_url = yangju_education_list_url(page)
            try:
                soup = first_soup if page == 1 else fetch_soup(s, page_url, timeout=timeout)
                list_requests += int(page > 1)
            except Exception as exc:
                logger.warning(
                    "Yangju education list-page fetch failed provider=%s page=%s error_type=%s",
                    target.provider,
                    page,
                    type(exc).__name__,
                )
                errors.append(f"page {page} fetch {type(exc).__name__}")
                break
            if yangju_page_contract(soup) != (total, page, last_page):
                errors.append(f"page {page} total contract changed")
                break
            table = next((node for node in soup.select("table") if node.select_one('a[href*="eduLctreWebView.do"]')), None)
            headers = tuple(clean_text(node.get_text(" ", strip=True)) for node in table.select("thead th")) if table else ()
            if headers != YANGJU_EDUCATION_HEADERS:
                errors.append(f"page {page} education table changed")
                break
            parsed_count = 0
            for row_number, item in enumerate(table.select("tbody > tr"), start=1):
                raw_cells = item.find_all("td", recursive=False)
                cells, cell_error = yangju_canonical_list_cells(raw_cells)
                if cell_error:
                    errors.append(f"page {page} row {row_number}: {cell_error}")
                    continue
                link = cells[1].select_one('a[href*="eduLctreWebView.do"]')
                detail_url, lecture_no = canonical_yangju_detail_url(page_url, link.get("href") if link else "")
                title = clean_text(html.unescape(link.get_text(" ", strip=True))) if link else ""
                sequence = clean_text(cells[0].get_text(" ", strip=True))
                apply_period, period = yangju_split_period_cell(cells[3].get_text(" ", strip=True))
                start, end = parse_date_range(period)
                apply_start, apply_end = parse_date_range(apply_period)
                undated_period = not start and not end
                valid_period = bool(
                    (start and end)
                    or (
                        undated_period
                        and clean_text(period) == "추후협의"
                    )
                )
                source_status = clean_text(cells[7].get_text(" ", strip=True))
                status = YANGJU_SOURCE_STATUSES.get(source_status, "")
                apply_links = cells[8].find_all("a", href=True)
                application_url = canonical_yangju_application_url(page_url, apply_links[0].get("href"), lecture_no) if len(apply_links) == 1 else ""
                if not (sequence.isdigit() and detail_url and lecture_no and title and period and valid_period and status):
                    errors.append(f"page {page} row {row_number}: required fields missing")
                    continue
                if (
                    len(apply_links) > 1
                    or (len(apply_links) == 1 and not application_url)
                ):
                    errors.append(f"page {page} row {row_number}: application contract mismatch")
                cap_now, cap_total, wait_now, wait_total = yangju_capacity(cells[5].get_text(" ", strip=True))
                row = {
                    "provider": target.provider,
                    "provider_course_id": f"{target.provider}:lecture:{lecture_no}"[:100],
                    "prefer_incoming_provider_course_id": True,
                    "title": title, "branch": target.branch,
                    "branch_code": yangju_branch_code(target.provider, target.branch),
                    "branch_url": YANGJU_EDUCATION_CANONICAL_URL, "preserve_branch": True,
                    "raw_url": detail_url, "application_url": application_url,
                    "application_type": "ONLINE_RESERVATION" if application_url else "",
                    "reservation_available": bool(application_url), "status": status,
                    "period": period, "apply_period": apply_period,
                    "start_date": start.isoformat() if start else "",
                    "end_date": end.isoformat() if end else "",
                    "apply_start": apply_start.isoformat() if apply_start else "",
                    "apply_end": apply_end.isoformat() if apply_end else "",
                    "schedule_raw": clean_text(cells[4].get_text(" ", strip=True)),
                    "fee": clean_text(cells[6].get_text(" ", strip=True)),
                    "capacity": clean_text(cells[5].get_text(" ", strip=True)),
                    "capacity_current": cap_now, "capacity_total": cap_total,
                    "waitlist_current": wait_now, "waitlist_total": wait_total,
                    "application_method_raw": clean_text(cells[2].get_text(" ", strip=True)),
                    "description": clean_text(item.get_text(" ", strip=True))[:1000],
                    "program_type": "강좌", "collection_category": "공공예약",
                    "domain_category": "교육·강좌", "source_group": "municipal_reservation",
                    "operator_type": "지자체/공공기관", "service_group": "공공강좌",
                    "service_group_policy": "locked",
                    "municipality_code": "4163000000", "municipality_full_name": "경기도 양주시",
                    "raw_fields": {"parser": YANGJU_EDUCATION_PARSER, "edu_lctre_no": lecture_no,
                                   "source_sequence": int(sequence), "source_status": source_status,
                                   "source_url": page_url,
                                   "course_period_undated": undated_period,
                                   "clear_application_url": not bool(application_url)},
                }
                all_rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
                parsed_count += 1
            expected = min(YANGJU_EDUCATION_PAGE_UNIT, total - (page - 1) * YANGJU_EDUCATION_PAGE_UNIT)
            page_counts[page] = parsed_count
            if parsed_count != expected:
                errors.append(f"page {page} expected {expected} rows, got {parsed_count}")
            if errors:
                break

    if not errors:
        sentinel_page = last_page + 1
        try:
            sentinel = fetch_soup(s, yangju_education_list_url(sentinel_page), timeout=timeout)
            list_requests += 1
            sentinel_pages = 1
            empty_text = clean_text(" ".join(node.get_text(" ", strip=True) for node in sentinel.select("td.empty")))
            if yangju_page_contract(sentinel) != (total, sentinel_page, last_page) or sentinel.select('a[href*="eduLctreWebView.do"]') or "등록된 교육강좌 없습니다." not in empty_text:
                errors.append("immediate sentinel page is not explicitly empty")
            page_counts[sentinel_page] = len(sentinel.select('a[href*="eduLctreWebView.do"]'))
        except Exception as exc:
            logger.warning(
                "Yangju education sentinel fetch failed provider=%s page=%s error_type=%s",
                target.provider,
                sentinel_page,
                type(exc).__name__,
            )
            errors.append(f"sentinel fetch {type(exc).__name__}")

    identities = [clean_text(row["raw_fields"].get("edu_lctre_no")) for row in all_rows]
    duplicate_count = len(identities) - len(set(identities))
    sequences = [int(row["raw_fields"].get("source_sequence") or 0) for row in all_rows]
    if duplicate_count:
        errors.append(f"{duplicate_count} duplicate lecture identities")
    if sequences and sequences != list(range(total, 0, -1)):
        errors.append("source numbering is not continuous")
    if contract and len(all_rows) != total:
        errors.append(f"declared total {total} != parsed rows {len(all_rows)}")
    list_complete = not errors and list_requests == required_requests and page_counts.get(last_page + 1) == 0

    today = date.today()
    current_rows = [row for row in all_rows if yangju_source_row_is_current(row, today)]
    expired_count = len(all_rows) - len(current_rows)
    if len(current_rows) > allowed_details:
        source_cap_reached = True
        errors.append(f"detail_limit cap allows {allowed_details} of {len(current_rows)} required current/future details")

    if not errors:
        for row in current_rows:
            detail_attempts += 1
            lecture_no = row["raw_fields"]["edu_lctre_no"]
            try:
                detail = yangju_detail_fields(s, row["raw_url"], timeout)
                detail_pages += 1
            except Exception as exc:
                detail_errors += 1
                logger.warning(
                    "Yangju education detail fetch failed provider=%s lecture_no=%s error_type=%s",
                    target.provider,
                    lecture_no,
                    type(exc).__name__,
                )
                errors.append(f"{lecture_no}: detail fetch {type(exc).__name__}")
                continue
            if clean_text(detail.get("title")) != clean_text(row["title"]) or not clean_text(detail.get("branch")):
                detail_errors += 1
                errors.append(f"{lecture_no}: detail title or education institution mismatch")
                continue
            branch = clean_text(detail["branch"])
            row.update({"branch": branch, "branch_code": yangju_branch_code(target.provider, branch),
                        "provider_organizer": branch, "venue_name": detail.get("venue_name") or branch,
                        "room": detail.get("room") or "", "category": detail.get("category") or "",
                        "target": detail.get("target") or "", "phone": detail.get("phone") or "",
                        "instructor": detail.get("instructor") or "", "description": detail.get("description") or row["description"]})
            for key in ("fee", "material_note", "material_fee", "period", "apply_period", "application_method_raw", "capacity_total", "waitlist_total"):
                if detail.get(key) not in (None, ""):
                    row[key] = detail[key]
            detail_source_status = clean_text(detail.get("source_status"))
            detail_status = YANGJU_SOURCE_STATUSES.get(detail_source_status, "")
            actual_application = clean_text(detail.get("application_url"))
            if (
                not detail_status
                or (detail.get("application_link_present") and not actual_application)
                or (detail_source_status == "접수중" and not actual_application)
                or (
                    actual_application
                    and detail_source_status not in YANGJU_APPLICATION_SOURCE_STATUSES
                )
            ):
                detail_errors += 1
                errors.append(f"{lecture_no}: detail status/application contract mismatch")
                continue
            row["status"] = detail_status
            if actual_application:
                row["application_url"] = actual_application
                row["application_type"] = "ONLINE_RESERVATION"
            else:
                row.pop("application_url", None)
                row.pop("application_type", None)
            row["reservation_available"] = bool(actual_application)
            row["raw_fields"]["clear_application_url"] = not bool(actual_application)
            row["raw_fields"]["detail_source_status"] = detail_source_status
            row["raw_fields"]["detail_pairs"] = detail.get("raw_detail_pairs") or {}

    details_complete = not errors and detail_attempts == detail_pages == len(current_rows) and detail_errors == 0
    snapshot_complete = list_complete and details_complete and not errors
    result = dedupe_rows(current_rows) if snapshot_complete else []
    if snapshot_complete and len(result) != len(current_rows):
        errors.append("dedupe changed complete current row count")
        result = []
        snapshot_complete = False
    no_current_data = snapshot_complete and not current_rows
    meta = {
        "pages": list_requests, "list_requests": list_requests,
        "physical_requests": list_requests + detail_attempts, "detail_pages": detail_pages,
        "detail_attempts": detail_attempts, "detail_errors": detail_errors,
        "discovered_links": len(all_rows),
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in result),
        "source_total": total, "source_rows": len(all_rows), "source_page_counts": page_counts,
        "data_pages": last_page, "sentinel_pages": sentinel_pages,
        "required_list_requests": required_requests, "current_count": len(current_rows),
        "returned_count": len(result), "expired_count": expired_count,
        "duplicate_count": duplicate_count, "pagination_detected": last_page > 1,
        "pagination_complete": list_complete, "pagination_exhausted": list_complete,
        "details_complete": details_complete, "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached, "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": "all complete official Yangju education lectures have ended" if no_current_data else "",
        "configured_collection_error": "; ".join(dict.fromkeys(errors)),
    }
    if errors:
        return [], YANGJU_EDUCATION_PARSER, meta
    return result, YANGJU_EDUCATION_PARSER, meta


def _legacy_daejeon_donggu_edu(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    if not parsed.path.endswith("/selectUserEduList.do"):
        parsed = urlparse("https://www.donggu.go.kr/lll/www/selectUserEduList.do?key=733&pageUnit=20")
    base_query = parse_qs(parsed.query)
    pagination_detected = False
    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["page"] = [str(page)]
        query.setdefault("pageUnit", ["20"])
        current_url = parsed._replace(path="/lll/www/selectUserEduList.do", query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table.edu_list_table tbody tr"):
            cells = tr.find_all("td")
            if len(cells) < 7:
                continue
            title_node = tr.select_one(".edu_tit")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            if not title or is_low_value_title(title):
                continue
            onclick = clean_text((tr.find("a", onclick=True) or {}).get("onclick"))
            id_match = re.search(r"fn_goView\(['\"]?(\d+)", onclick)
            sch_id = id_match.group(1) if id_match else ""
            detail_query = dict(query)
            if sch_id:
                detail_query["schId"] = [sch_id]
            raw_url = parsed._replace(path="/lll/www/selectUserEduView.do", query=urlencode(detail_query, doseq=True)).geturl()
            location = clean_text((cells[1].find_all("span")[-1].get_text(" ", strip=True) if cells[1].find_all("span") else ""))
            branch = clean_text(cells[2].get_text(" ", strip=True)) or target.branch
            target_text = re.sub(r"^모집대상\s*[:：]?\s*", "", clean_text(cells[3].get_text(" ", strip=True)))
            date_pairs = labeled_pairs_from_named_spans(cells[4], "em")
            capacity_current, capacity_total = parse_capacity_pair(cells[5].get_text(" ", strip=True))
            fee = clean_text(cells[6].get_text(" ", strip=True)).replace("수강료", "").strip()
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": clean_text(cells[0].get_text(" ", strip=True)),
                "fee": fee,
                "period": normalize_yymmdd_range(date_pairs.get("교육기간", "")),
                "apply_period": normalize_yymmdd_range(date_pairs.get("신청기간", "")),
                "schedule_raw": "",
                "target": target_text,
                "room": location,
                "venue_name": location,
                "capacity": capacity_total,
                "capacity_current": capacity_current,
                "description": clean_text(tr.get_text(" ", strip=True)),
                "raw_fields": {"parser": "daejeon_donggu_edu", "sch_id": sch_id, "date_pairs": date_pairs},
            }
            if raw_url and detail_pages < 30:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_tables(detail_soup)
                    detail_capacity_current, detail_capacity_total = parse_capacity_pair(detail_pairs.get("접수인원"))
                    row["category"] = clean_text(detail_pairs.get("강의분류"))
                    row["target"] = clean_text(detail_pairs.get("교육대상")) or row["target"]
                    row["status"] = status_from_lines(lines_from_soup(detail_soup)) or row["status"]
                    row["period"] = normalize_mixed_date_range(detail_pairs.get("교육기간", "")) or row["period"]
                    row["apply_period"] = normalize_mixed_date_range(detail_pairs.get("신청기간", "")) or row["apply_period"]
                    row["schedule_raw"] = clean_text(detail_pairs.get("교육시간"))
                    row["room"] = clean_text(detail_pairs.get("교육장소")) or row["room"]
                    row["venue_name"] = row["room"]
                    row["venue_address"] = clean_text(re.sub(r"^\[[^\]]+\]\s*", "", detail_pairs.get("교육장소주소", "")))
                    row["capacity"] = detail_capacity_total or row["capacity"]
                    row["capacity_current"] = detail_capacity_current or row["capacity_current"]
                    row["target_age_raw"] = clean_text(detail_pairs.get("수강가능연령"))
                    row["material_note"] = clean_text(detail_pairs.get("재료비설명"))
                    row["instructor"] = clean_instructor_name(detail_pairs.get("강사"))
                    row["description"] = clean_text(detail_pairs.get("강의내용") or detail_soup.get_text(" ", strip=True))[:1200]
                    row["raw_fields"] = {
                        "parser": "daejeon_donggu_edu",
                        "sch_id": sch_id,
                        "date_pairs": date_pairs,
                        "detail_pairs": detail_pairs,
                    }
                except Exception as exc:
                    logger.debug("Daejeon Donggu detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='fn_egov_link_page']"))
        if page_rows == 0:
            break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "daejeon_donggu_edu", meta


def collect_bupyeong_lecture_list(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    parsed = urlparse(target.url)
    if not parsed.path.endswith("/lecturelll/lectureList.do"):
        parsed = urlparse("https://www.icbp.go.kr/lecturelll/lectureList.do?sitediv=lll&cd=lll")
    base_query = parse_qs(parsed.query)
    pagination_detected = False
    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["nowPage"] = [str(page)]
        current_url = parsed._replace(path="/lecturelll/lectureList.do", query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for item in soup.select(".lecList > li"):
            link = item.select_one(".tit a[href]")
            title = clean_text(link.get_text(" ", strip=True) if link else "")
            title = re.sub(r"^접수마감", "", title).strip()
            if not title or is_low_value_title(title):
                continue
            pairs = labeled_pairs_from_named_spans(item, "span.wfont")
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": clean_text((item.select_one(".tag_state") or item).get_text(" ", strip=True)),
                "fee": "",
                "material_fee": "",
                "period": normalize_mixed_date_range(pairs.get("수강기간", "") or pairs.get("교육기간", "")),
                "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
                "schedule_raw": "",
                "target": "",
                "room": clean_text(pairs.get("교육장소")),
                "venue_name": clean_text(pairs.get("교육장소")),
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"parser": "bupyeong_lecture_list", "pairs": pairs},
            }
            if raw_url and detail_pages < 30:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_definition_lists(detail_soup)
                    period, schedule = split_period_and_schedule(detail_pairs.get("교육기간", ""))
                    fee_text = clean_text(detail_pairs.get("수강료"))
                    material_match = re.search(r"재료비\s*[:：]?\s*([^)]+)", fee_text)
                    row["target"] = clean_text(detail_pairs.get("교육대상"))
                    row["fee"] = clean_text(re.split(r"\(?재료비", fee_text)[0])
                    row["material_fee"] = clean_text(material_match.group(1)) if material_match else row["material_fee"]
                    row["period"] = period or row["period"]
                    row["schedule_raw"] = schedule
                    row["apply_period"] = normalize_mixed_date_range(detail_pairs.get("접수기간", "")) or row["apply_period"]
                    row["room"] = clean_text(detail_pairs.get("교육장소")) or row["room"]
                    row["venue_name"] = row["room"]
                    row["capacity"] = clean_text(detail_pairs.get("신청정원"))
                    row["application_method_raw"] = clean_text(detail_pairs.get("접수방법"))
                    row["instructor"] = clean_instructor_name(detail_pairs.get("강사"))
                    image = detail_soup.select_one(".photo img")
                    row["image_url"] = normalize_link(raw_url, image.get("src") if image else None)
                    row["description"] = clean_text(detail_pairs.get("안내") or detail_soup.get_text(" ", strip=True))[:1200]
                    row["raw_fields"] = {"parser": "bupyeong_lecture_list", "pairs": pairs, "detail_pairs": detail_pairs}
                except Exception as exc:
                    logger.debug("Bupyeong detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='nowPage=']"))
        if page_rows == 0:
            break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "bupyeong_lecture_list", meta


def collect_ulsan_yes_lecture(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, "https://yes.ulsan.go.kr/lecture", timeout=timeout)
    rows: list[dict[str, Any]] = []
    for item in soup.select(".content_wrap"):
        title_node = item.select_one("h4.blue")
        status_node = title_node.select_one(".ing") if title_node else None
        status = clean_text(status_node.get_text(" ", strip=True) if status_node else "")
        if status_node:
            status_node.extract()
        title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
        if not title or is_low_value_title(title):
            continue
        branch = clean_text((item.select_one(".list_tit h4") or item).get_text(" ", strip=True)) or target.branch
        pairs: dict[str, str] = {}
        for li in item.select("ul.list li"):
            text = clean_text(li.get_text(" ", strip=True))
            if ":" not in text:
                continue
            key, value = text.split(":", 1)
            pairs[normalize_korean_label(key)] = clean_text(value)
        link = item.select_one(".reservation a[href]")
        raw_url = normalize_link(target.url, link.get("href") if link else None) or target.url
        schedule_text = clean_text(pairs.get("교육시간"))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": clean_text(pairs.get("수강료")),
                "period": normalize_yymmdd_range(schedule_text),
                "apply_period": "",
                "schedule_raw": schedule_text,
                "target": clean_text(pairs.get("교육대상")),
                "capacity": clean_text(pairs.get("정원")),
                "application_method_raw": clean_text(pairs.get("접수방법")),
                "contact": clean_text(pairs.get("문의처")),
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"parser": "ulsan_yes_lecture", "pairs": pairs},
            }
        )
    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": bool(soup.select(".pagination, .paging")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ulsan_yes_lecture", meta


ULSAN_BUKGU_LECTURE_URL = "https://crs.ubimc.or.kr/yeyak/new_lecture/lecture"
ULSAN_BUKGU_BRANCH = "울산북구공공시설예약서비스"
ULJU_PUBLIC_RESERVATION_PROVIDER = "MUNI_CRS_ULJUSISEOL_OR_KR_DC828DD7"
ULSAN_PUBLIC_LECTURE_ROUTES = {
    ("crs.ubimc.or.kr", "/yeyak/new_lecture/lecture"),
    ("crs.uljusiseol.or.kr", "/new_lecture/lecture"),
}
ULJU_PUBLIC_FACILITIES: dict[str, tuple[str, str]] = {
    "B0000191": ("온산도서관", "울산광역시 울주군 온산읍 명봉거남로 46"),
    "B0000189": ("온산문화체육센터", "울산광역시 울주군 온산읍 명봉거남로 46"),
    "B0000196": ("울주 남부청소년수련관", "울산광역시 울주군 온양읍 동상로 60"),
    "B0000176": ("울주 서부청소년수련관", "울산광역시 울주군 삼남읍 울산역로 345"),
    "B0000192": ("울주 중부청소년수련관", "울산광역시 울주군 범서읍 구영로 101-20"),
    "B0000188": ("울주군국민체육센터", "울산광역시 울주군 범서읍 구영로 101-16"),
    "B0000199": ("울주종합체육센터", "울산광역시 울주군 삼남읍 향교로 113"),
}
COURSE_NO_DATA_PATTERN = re.compile(
    r"(?:등록|검색|조회|해당|교육|강좌|프로그램|게시).{0,30}(?:없습니다|없음)"
    r"|(?:자료|데이터|내용)(?:이)?(?:가)?\s*(?:없습니다|없음)"
)


def is_ulsan_public_lecture_target(url: str) -> bool:
    parsed = urlparse(url)
    return (
        parsed.scheme.lower() == "https"
        and (parsed.netloc.lower(), parsed.path.rstrip("/")) in ULSAN_PUBLIC_LECTURE_ROUTES
    )


def is_ulju_public_lecture_target(url: str) -> bool:
    parsed = urlparse(url)
    return (
        parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == "crs.uljusiseol.or.kr"
        and parsed.path.rstrip("/") == "/new_lecture/lecture"
    )


def is_explicit_course_no_data_row(row: Any) -> bool:
    cells = row.select("td")
    if len(cells) != 1:
        return False
    return bool(COURSE_NO_DATA_PATTERN.search(clean_text(cells[0].get_text(" ", strip=True))))


def is_confirmed_course_ended_status(status: Any) -> bool:
    status_text = re.sub(r"\s+", "", clean_text(status))
    return "폐강" in status_text or any(
        token in status_text
        for token in ("강습종료", "운영종료", "교육종료", "과정종료", "프로그램종료")
    ) or status_text in {"종료", "종강"}


def public_course_reservation_available(status: Any) -> bool:
    status_text = clean_text(status)
    return any(token in status_text for token in ("접수중", "대기자접수")) and not any(
        token in status_text for token in ("마감", "종료", "폐강")
    )


def ulsan_bukgu_branch_code(url: str) -> str:
    params = parse_qs(urlparse(url).query)
    return clean_text((params.get("mem_id") or [""])[0])


def ulsan_bukgu_facility_links(soup: BeautifulSoup, base_url: str) -> list[tuple[str, str]]:
    links: list[tuple[str, str]] = []
    seen: set[str] = set()
    base = urlparse(base_url)
    for link in soup.select("a[href*='new_lecture/lecture'][href*='mem_id=']"):
        absolute = normalize_link(base_url, link.get("href"))
        parsed = urlparse(absolute)
        branch_code = ulsan_bukgu_branch_code(absolute)
        if (
            not absolute
            or parsed.scheme != base.scheme
            or parsed.netloc.lower() != base.netloc.lower()
            or parsed.path.rstrip("/") != base.path.rstrip("/")
            or not re.fullmatch(r"B\d+", branch_code)
            or branch_code in seen
        ):
            continue
        branch = clean_text(link.get_text(" ", strip=True)) or branch_code
        canonical_url = urlunparse(
            (parsed.scheme, parsed.netloc, parsed.path, "", urlencode({"mem_id": branch_code}), "")
        )
        links.append((branch, canonical_url))
        seen.add(branch_code)
    return links


def ulju_public_facility_links(base_url: str) -> list[tuple[str, str]]:
    parsed = urlparse(base_url)
    return [
        (
            branch,
            urlunparse(
                (
                    parsed.scheme,
                    parsed.netloc,
                    parsed.path,
                    "",
                    urlencode({"mem_id": branch_code}),
                    "",
                )
            ),
        )
        for branch_code, (branch, _address) in ULJU_PUBLIC_FACILITIES.items()
    ]


def canonical_ulsan_public_lecture_detail_url(
    list_url: str,
    href: Any,
) -> tuple[str, str, str]:
    absolute = normalize_link(list_url, href)
    if not absolute:
        return "", "", ""
    base = urlparse(list_url)
    parsed = urlparse(absolute)
    if (
        parsed.scheme != base.scheme
        or parsed.netloc.lower() != base.netloc.lower()
        or parsed.path.rstrip("/") != base.path.rstrip("/")
    ):
        return "", "", ""
    query = parse_qs(parsed.query)
    lecture_id = clean_text((query.get("lec_id") or [""])[0])
    branch_code = clean_text((query.get("mem_id") or [""])[0])
    if not re.fullmatch(r"L\d+", lecture_id) or not re.fullmatch(r"B\d+", branch_code):
        return "", "", ""
    canonical_query = urlencode(
        (("prc", "detail"), ("lec_id", lecture_id), ("mem_id", branch_code))
    )
    canonical_url = urlunparse(
        (parsed.scheme, parsed.netloc, parsed.path, "", canonical_query, "")
    )
    return canonical_url, lecture_id, branch_code


def ulsan_bukgu_subject_pairs(subject: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in subject.select("p"):
        label_node = item.select_one("span")
        if not label_node:
            continue
        label_text = clean_text(label_node.get_text(" ", strip=True)).rstrip(":：")
        value = clean_text(item.get_text(" ", strip=True).replace(label_node.get_text(" ", strip=True), "", 1))
        value = clean_text(value.lstrip(":："))
        if label_text:
            pairs[normalize_korean_label(label_text)] = value
    return pairs


def ulsan_bukgu_fee_value(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    if re.search(r"\d[\d,]*\s*원", text) or "무료" in text:
        return text
    match = re.search(r"\d[\d,]*", text)
    return f"{match.group(0)}원" if match else text


def ulsan_bukgu_fee_text(node: BeautifulSoup | None) -> str:
    return ulsan_bukgu_fee_value(node.get_text(" ", strip=True) if node else "")


def ulsan_bukgu_table_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for row in soup.select("table.table_st2 tr"):
        header = clean_text((row.select_one("th") or "").get_text(" ", strip=True) if row.select_one("th") else "")
        value = clean_text((row.select_one("td") or "").get_text(" ", strip=True) if row.select_one("td") else "")
        if header:
            pairs[normalize_korean_label(header)] = value
    return pairs


def collect_ulsan_bukgu_detail(s: requests.Session, raw_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, raw_url, timeout=timeout)
    pairs = ulsan_bukgu_table_pairs(soup)
    info_text = clean_text((soup.select_one(".info_area") or "").get_text(" ", strip=True) if soup.select_one(".info_area") else "")
    address = ""
    contact = ""
    address_match = re.search(r"주소\s*[:：]\s*(.*?)(?=문의전화\s*[:：]|$)", info_text)
    if address_match:
        address = clean_text(address_match.group(1))
    contact_match = re.search(r"문의전화\s*[:：]\s*([()0-9~\-\s]+)", info_text)
    if contact_match:
        contact = clean_text(contact_match.group(1))
    room = clean_text((soup.select_one(".info_area .s_tit2") or "").get_text(" ", strip=True) if soup.select_one(".info_area .s_tit2") else "")
    status = ""
    status_match = re.search(
        r"(접수\s*준비중|준비중|접수중|대기자접수|접수마감|강습전|강습중|강습종료|마감|폐강)[^.\n]*",
        soup.get_text("\n", strip=True),
    )
    if status_match:
        status = clean_text(status_match.group(0))
    description = clean_text((soup.select_one(".tab_cont#tab2") or "").get_text(" ", strip=True) if soup.select_one(".tab_cont#tab2") else "")
    image_url = ""
    image = soup.select_one(".photo_cont img[src]")
    if image:
        candidate = normalize_link(raw_url, image.get("src"))
        if candidate and "noimage" not in candidate.lower():
            image_url = candidate
    return {
        "target": clean_text(pairs.get("강습대상")),
        "capacity": clean_text(pairs.get("정원")),
        "apply_period": normalize_yymmdd_range(pairs.get("신규회원모집기간", "")),
        "period": normalize_yymmdd_range(pairs.get("강습기간", "")),
        "schedule_raw": clean_text(pairs.get("강습시간")),
        "fee": ulsan_bukgu_fee_value(pairs.get("수강료")),
        "instructor": clean_text(pairs.get("강사")),
        "venue_name": room,
        "room": room,
        "venue_address": address,
        "address": address,
        "contact": contact,
        "status": status,
        "description": description,
        "image_url": image_url,
        "raw_fields": {"detail_parser": "ulsan_bukgu_lecture_detail", "detail_pairs": pairs},
    }


def collect_ulsan_bukgu_lecture(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    first_url = target.url if "/new_lecture/lecture" in urlparse(target.url).path else ULSAN_BUKGU_LECTURE_URL
    is_ulju_target = is_ulju_public_lecture_target(first_url)
    first_soup = fetch_soup(s, first_url, timeout=timeout)
    discovered_facility_links = ulsan_bukgu_facility_links(first_soup, first_url)
    discovered_facility_codes = {
        ulsan_bukgu_branch_code(url) for _branch, url in discovered_facility_links
    }
    if is_ulju_target:
        facility_links = ulju_public_facility_links(first_url)
    else:
        facility_links = discovered_facility_links
    if not facility_links:
        facility_links = [(target.branch or ULSAN_BUKGU_BRANCH, first_url)]

    rows: list[dict[str, Any]] = []
    pages = 0
    seen_lecture_ids: set[str] = set()
    test_rows = 0
    expired_rows = 0
    ended_rows = 0
    invalid_rows = 0
    no_data_placeholders = 0
    structurally_valid_rows = 0
    partial_collection_error = ""
    pagination_detected = len(facility_links) > 1
    for branch, list_url in facility_links[: max(1, max_pages)]:
        try:
            soup = first_soup if pages == 0 and list_url == first_url else fetch_soup(s, list_url, timeout=timeout)
        except Exception as exc:
            logger.warning(
                "Ulsan public lecture facility failed %s: %s",
                safe_url_for_log(list_url),
                exc,
            )
            partial_collection_error = f"facility fetch failed: {type(exc).__name__}"
            continue
        pages += 1
        branch_code = ulsan_bukgu_branch_code(list_url) or re.sub(r"[^A-Za-z0-9가-힣]+", "_", branch).strip("_")[:50]
        fallback_address = ""
        if is_ulju_target and branch_code in ULJU_PUBLIC_FACILITIES:
            branch, fallback_address = ULJU_PUBLIC_FACILITIES[branch_code]
        for row_node in soup.select("table.table_list tbody tr"):
            if is_explicit_course_no_data_row(row_node):
                no_data_placeholders += 1
                continue
            subject = row_node.select_one("td.subject")
            link = subject.select_one("a[href]") if subject else row_node.select_one("a[href]")
            raw_url, lecture_id, detail_branch_code = canonical_ulsan_public_lecture_detail_url(
                list_url,
                link.get("href") if link else None,
            )
            title = clean_text((subject.select_one("p.tit") if subject else None).get_text(" ", strip=True) if subject and subject.select_one("p.tit") else "")
            title = title or clean_text(link.get_text(" ", strip=True) if link else "")
            if not raw_url or not lecture_id or not title or is_low_value_title(title):
                invalid_rows += 1
                continue
            if lecture_id in seen_lecture_ids:
                continue
            seen_lecture_ids.add(lecture_id)
            structurally_valid_rows += 1
            if "테스트" in title:
                test_rows += 1
                continue
            pairs = ulsan_bukgu_subject_pairs(subject) if subject else {}
            status = clean_text((row_node.select_one("td.state") or "").get_text(" ", strip=True) if row_node.select_one("td.state") else "")
            status = status or clean_text((row_node.select_one("td.person") or "").get_text(" ", strip=True) if row_node.select_one("td.person") else "")
            if is_confirmed_course_ended_status(status):
                ended_rows += 1
                continue
            reservation_available = public_course_reservation_available(status)
            period = normalize_yymmdd_range(pairs.get("강습기간", ""))
            start_date, end_date = parse_date_range(period)
            schedule = clean_text(pairs.get("강습시간"))
            category = clean_text((row_node.select_one("td.devide") or "").get_text(" ", strip=True) if row_node.select_one("td.devide") else "")
            fee = ulsan_bukgu_fee_text(row_node.select_one("td.pay"))
            description = clean_text(row_node.get_text(" ", strip=True))
            row = {
                "provider": target.provider,
                "provider_course_id": f"{target.provider}:lecture:{lecture_id}"[:100],
                "title": title,
                "branch": branch,
                "branch_code": detail_branch_code or branch_code,
                "preserve_branch": True,
                "branch_url": list_url,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url if reservation_available else "",
                "application_type": "ONLINE_RESERVATION" if reservation_available else "",
                "reservation_available": reservation_available,
                "status": status,
                "fee": fee,
                "period": period,
                "start_date": start_date,
                "end_date": end_date,
                "apply_period": "",
                "schedule_raw": schedule,
                "target": "",
                "capacity": "",
                "program_type": "강좌",
                "description": description,
                "venue_address": fallback_address,
                "address": fallback_address,
                "domain_category": clean_text(target.extra.get("domain_category") or "공공예약"),
                "collection_category": clean_text(target.extra.get("collection_category") or "공공예약"),
                "source_group": clean_text(target.extra.get("source_group") or "public_reservation"),
                "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
                "collection_type": "static_html+detail_html",
                "raw_fields": {
                    "parser": "ulsan_bukgu_lecture_list",
                    "list_url": list_url,
                    "lecture_id": lecture_id,
                    "mem_id": detail_branch_code or branch_code,
                    "pairs": pairs,
                },
            }
            if should_skip_expired_course(row):
                expired_rows += 1
                continue
            rows.append(row)

    if len(facility_links) > max(1, max_pages):
        partial_collection_error = (
            f"facility fanout capped at {max(1, max_pages)} of {len(facility_links)}"
        )

    if structurally_valid_rows == 0 and invalid_rows > 0 and not partial_collection_error:
        partial_collection_error = (
            f"all listed lecture rows were malformed ({invalid_rows} invalid rows)"
        )

    detail_candidates = len(rows)
    detail_pages = 0
    enriched_rows: list[dict[str, Any]] = []
    for index, row in enumerate(rows):
        raw_url = clean_text(row.get("raw_url"))
        if index < max(0, detail_limit) and raw_url:
            try:
                detail = collect_ulsan_bukgu_detail(s, raw_url, timeout=timeout)
                detail_status = clean_text(detail.get("status"))
                row.update(merge_course_rows(row, detail))
                if detail_status:
                    row["status"] = detail_status
                fallback_address = clean_text(row.get("venue_address") or row.get("address"))
                if is_ulju_target and not fallback_address:
                    branch_code = clean_text(row.get("branch_code"))
                    fallback_address = clean_text((ULJU_PUBLIC_FACILITIES.get(branch_code) or ("", ""))[1])
                if fallback_address:
                    row["venue_address"] = fallback_address
                    row["address"] = fallback_address
                detail_pages += 1
            except Exception as exc:
                logger.debug("Ulsan public lecture detail fetch failed %s: %s", safe_url_for_log(raw_url), exc)
        final_status = clean_text(row.get("status"))
        if is_confirmed_course_ended_status(final_status):
            ended_rows += 1
            continue
        reservation_available = public_course_reservation_available(final_status)
        row["reservation_available"] = reservation_available
        row["application_url"] = raw_url if reservation_available else ""
        row["application_type"] = "ONLINE_RESERVATION" if reservation_available else ""
        enriched_rows.append(row)
    rows = enriched_rows

    collection_complete = not partial_collection_error and pages == len(facility_links)
    no_current_data = collection_complete and not rows
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_lecture_ids),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": collection_complete,
        "pagination_exhausted": collection_complete,
        "recursion_depth": 0,
        "facility_count": len(facility_links),
        "facilities_processed": pages,
        "facility_fanout_source": "official_mapping" if is_ulju_target else "discovered_links",
        "facility_codes_discovered": sorted(discovered_facility_codes),
        "facility_codes_missing": sorted(set(ULJU_PUBLIC_FACILITIES) - discovered_facility_codes) if is_ulju_target else [],
        "test_rows": test_rows,
        "expired_rows": expired_rows,
        "ended_rows": ended_rows,
        "invalid_count": invalid_rows,
        "valid_count": structurally_valid_rows,
        "no_data_placeholders": no_data_placeholders,
        "detail_candidates": detail_candidates,
        "detail_enrichment_capped": max(0, detail_limit) < detail_candidates,
        "no_current_data": no_current_data,
        "no_current_reason": (
            "explicit no-data placeholder"
            if no_current_data and no_data_placeholders and structurally_valid_rows == 0
            else "all listed courses are expired, ended, or test rows"
            if no_current_data
            else ""
        ),
    }
    if partial_collection_error:
        meta["configured_collection_error"] = partial_collection_error
    return dedupe_rows(rows), "ulsan_bukgu_lecture_list+detail", meta


USBL_BUKGU_LIBRARY_LIST_URL = "https://usbl.bukgu.ulsan.kr/main/edusat/list.do"
USBL_BUKGU_BRANCHES = (
    "중앙도서관",
    "매곡도서관",
    "농소1동도서관",
    "명촌어린이도서관",
    "농소3동도서관",
    "기적의도서관",
    "강동바다도서관",
    "염포양정도서관",
    "송정나래도서관",
)


def usbl_bukgu_list_url(target_url: str) -> str:
    parsed = urlparse(target_url)
    if parsed.netloc.endswith("usbl.bukgu.ulsan.kr") and parsed.path.endswith("/edusat/list.do"):
        return target_url
    return USBL_BUKGU_LIBRARY_LIST_URL


def usbl_bukgu_canonical_detail_url(base_url: str, href: str | None) -> str:
    raw_url = normalize_link(base_url, href)
    if not raw_url:
        return ""
    parsed = urlparse(raw_url)
    edu_idx = clean_text((parse_qs(parsed.query).get("edu_idx") or [""])[0])
    if edu_idx:
        return parsed._replace(query=urlencode({"edu_idx": edu_idx}), fragment="").geturl()
    return raw_url


def usbl_bukgu_total_count(soup: BeautifulSoup) -> Optional[int]:
    total_node = soup.select_one(".board_total_left strong")
    total = parse_capacity_number(total_node.get_text(" ", strip=True) if total_node else "")
    if total is not None:
        return total
    text = clean_text(soup.select_one(".board_total_left").get_text(" ", strip=True) if soup.select_one(".board_total_left") else "")
    match = re.search(r"총\s*(\d+)\s*개", text)
    return int(match.group(1)) if match else None


def usbl_bukgu_status(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    if any(token in text for token in ("수강신청", "신청중", "접수중", "신청가능")) and "마감" not in text:
        return "접수중"
    if any(token in text for token in ("신청준비", "접수예정", "준비")):
        return "접수예정"
    if any(token in text for token in ("기간종료", "신청마감", "접수마감", "마감", "종료")):
        return "접수마감"
    return normalize_status(text) or text


def usbl_bukgu_title_and_category(value: Any) -> tuple[str, str]:
    title = clean_text(value)
    category = ""
    while title.startswith("["):
        match = re.match(r"^\[([^\]]+)\]\s*(.*)$", title)
        if not match:
            break
        label = clean_text(match.group(1))
        title = clean_text(match.group(2))
        if not category and not re.search(r"(?:정원|대기|추가|명|마감|신청|접수)", label):
            category = label
    return title, category


def usbl_bukgu_pairs_from_card(card: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in card.select(".sm_box dl"):
        key = clean_text((dl.select_one("dt") or "").get_text(" ", strip=True) if dl.select_one("dt") else "")
        value = clean_text((dl.select_one("dd") or "").get_text(" ", strip=True) if dl.select_one("dd") else "")
        if key:
            pairs[key] = value
    return pairs


def usbl_bukgu_split_period_and_schedule(value: Any) -> tuple[str, str]:
    text = clean_text(value).replace(" 요일", "요일")
    if not text:
        return "", ""
    match = re.search(
        r"(\d{4})[.-](\d{1,2})[.-](\d{1,2})\s*~\s*(\d{4})[.-](\d{1,2})[.-](\d{1,2})(.*)$",
        text,
    )
    if match:
        period = (
            f"{int(match.group(1)):04d}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
            f" ~ {int(match.group(4)):04d}-{int(match.group(5)):02d}-{int(match.group(6)):02d}"
        )
        return period, clean_text(match.group(7))
    return normalize_mixed_date_range(text), ""


def usbl_bukgu_datetime_range(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    matches = list(
        re.finditer(
            r"(\d{4})[.-](\d{1,2})[.-](\d{1,2})\s*(\d{1,2}:\d{2})?",
            text,
        )
    )
    if not matches:
        return normalize_mixed_date_range(text)

    def fmt(match: re.Match[str]) -> str:
        date_text = f"{int(match.group(1)):04d}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
        time_text = clean_text(match.group(4))
        return f"{date_text} {time_text}" if time_text else date_text

    if len(matches) >= 2:
        return f"{fmt(matches[0])} ~ {fmt(matches[1])}"
    return fmt(matches[0])


def usbl_bukgu_capacity(value: Any) -> tuple[str, Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value)
    current, total = parse_capacity_pair(text)
    wait_total = None
    wait_match = re.search(r"대기\s*[:：]?\s*(\d+)", text.replace(",", ""))
    if wait_match:
        wait_total = int(wait_match.group(1))
    return text, current, total, wait_total


def usbl_bukgu_branch_from_place(value: Any, fallback: str) -> tuple[str, str]:
    place = clean_text(value)
    for branch in USBL_BUKGU_BRANCHES:
        if place.startswith(branch):
            room = clean_text(place.replace(branch, "", 1))
            return branch, room
    return clean_text(fallback), place


def usbl_bukgu_detail_fields(s: requests.Session, raw_url: str, timeout: int, fallback_branch: str) -> dict[str, Any]:
    soup = fetch_soup(s, raw_url, timeout=timeout)
    table = soup.select_one("#contents table") or soup.select_one("table") or soup
    pairs = pairs_from_definition_lists(table)
    title = ""
    status = ""
    title_node = table.select_one("thead th") if hasattr(table, "select_one") else None
    if title_node:
        status_node = title_node.select_one("a.btn_sm")
        status = usbl_bukgu_status(status_node.get_text(" ", strip=True) if status_node else "")
        title_text = clean_text(title_node.get_text(" ", strip=True))
        if status_node:
            title_text = clean_text(title_text.replace(clean_text(status_node.get_text(" ", strip=True)), "", 1))
        title, _ = usbl_bukgu_title_and_category(title_text)
    place = clean_text(pairs.get("교육장소"))
    branch, room = usbl_bukgu_branch_from_place(place, fallback_branch)
    capacity, capacity_current, capacity_total, waitlist_total = usbl_bukgu_capacity(pairs.get("모집인원"))
    description = clean_text((table.select_one("td.content") or table).get_text(" ", strip=True) if hasattr(table, "select_one") else "")
    image_url = ""
    image = table.select_one("td.content img[src]") if hasattr(table, "select_one") else None
    if image:
        image_url = normalize_link(raw_url, image.get("src"))
    period = usbl_bukgu_datetime_range(pairs.get("운영기간"))
    schedule = clean_text(pairs.get("운영시간")).replace(" 요일", "요일")
    return {
        "title": title,
        "branch": branch,
        "branch_code": stable_provider("USBL_BUKGU", branch),
        "status": status,
        "period": period,
        "schedule_raw": schedule,
        "apply_period": usbl_bukgu_datetime_range(pairs.get("신청기간")),
        "application_method_raw": clean_text(pairs.get("신청방법")),
        "target": clean_text(pairs.get("참가대상")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_total": waitlist_total,
        "room": room,
        "venue_name": place,
        "fee": clean_text(pairs.get("참가비")),
        "instructor": clean_text(pairs.get("강사")),
        "description": description,
        "image_url": image_url,
        "raw_detail_pairs": pairs,
    }


def collect_usbl_bukgu_library_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    seen_detail_urls: set[str] = set()
    site_total = 0
    base_url = usbl_bukgu_list_url(target.url)
    parsed = urlparse(base_url)
    base_query = parse_qs(parsed.query)

    for page in range(1, max(1, max_pages) + 1):
        query = dict(base_query)
        if page > 1:
            query["v_page"] = [str(page)]
        else:
            query.pop("v_page", None)
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        cards = soup.select("#board .lesson > ul > li")
        pagination_detected = pagination_detected or bool(soup.select("a[href*='v_page=']"))
        site_total = max(site_total, usbl_bukgu_total_count(soup) or 0)
        if not cards:
            break
        pages += 1
        page_rows = 0
        for card in cards:
            link = card.select_one(".tit a[href]")
            title_raw = clean_text(link.get_text(" ", strip=True) if link else "")
            title, category = usbl_bukgu_title_and_category(title_raw)
            if not link or not title or is_low_value_title(title):
                continue
            raw_url = usbl_bukgu_canonical_detail_url(page_url, link.get("href")) or page_url
            if raw_url in seen_detail_urls:
                continue
            seen_detail_urls.add(raw_url)
            branch = clean_text((card.select_one(".cate") or "").get_text(" ", strip=True) if card.select_one(".cate") else "")
            branch = branch or target.branch
            pairs = usbl_bukgu_pairs_from_card(card)
            apply_period = usbl_bukgu_datetime_range(pairs.get("신청기간"))
            period, schedule = usbl_bukgu_split_period_and_schedule(pairs.get("운영기간"))
            capacity, capacity_current, capacity_total, waitlist_total = usbl_bukgu_capacity(pairs.get("모집인원"))
            status_text = clean_text(
                " ".join(
                    node.get_text(" ", strip=True)
                    for node in card.select(".btn_box a")
                    if "등록확인" not in clean_text(node.get_text(" ", strip=True))
                )
            )
            status = usbl_bukgu_status(status_text)
            application_link = card.select_one(".btn_box a[href*='regist.do']")
            application_url = normalize_link(page_url, application_link.get("href") if application_link else None)
            detail: dict[str, Any] = {}
            if raw_url and detail_pages < max(0, detail_limit):
                try:
                    detail = usbl_bukgu_detail_fields(s, raw_url, timeout=timeout, fallback_branch=branch)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("usbl bukgu library detail fetch failed %s: %s", raw_url, exc)
            detail_apply = clean_text(detail.get("apply_period"))
            final_apply_period = detail_apply or apply_period
            if apply_period and ":" in apply_period and ":" not in detail_apply:
                final_apply_period = apply_period
            final_status = clean_text(detail.get("status")) or status
            final_branch = clean_text(detail.get("branch")) or branch
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, final_branch),
                "title": clean_text(detail.get("title")) or title,
                "branch": final_branch,
                "branch_code": clean_text(detail.get("branch_code")) or stable_provider("USBL_BUKGU", final_branch),
                "preserve_branch": True,
                "category": category or "도서관 프로그램",
                "collection_category": "도서관",
                "domain_category": "도서관",
                "source_group": "library",
                "operator_type": "교육청/도서관",
                "collection_type": "static_html+detail",
                "program_type": "강좌",
                "raw_url": raw_url,
                "application_url": application_url if final_status in {"접수중", "접수예정"} else "",
                "reservation_available": final_status == "접수중" and bool(application_url),
                "status": final_status,
                "period": clean_text(detail.get("period")) or period,
                "apply_period": final_apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")) or schedule,
                "target": clean_text(detail.get("target")) or clean_text(pairs.get("참가대상")),
                "fee": clean_text(detail.get("fee")),
                "capacity": clean_text(detail.get("capacity")) or capacity,
                "capacity_current": detail.get("capacity_current") if detail.get("capacity_current") is not None else capacity_current,
                "capacity_total": detail.get("capacity_total") if detail.get("capacity_total") is not None else capacity_total,
                "waitlist_total": detail.get("waitlist_total") if detail.get("waitlist_total") is not None else waitlist_total,
                "room": clean_text(detail.get("room")),
                "venue_name": clean_text(detail.get("venue_name")) or final_branch,
                "instructor": clean_text(detail.get("instructor")),
                "description": clean_text(detail.get("description")) or clean_text(card.get_text(" ", strip=True)),
                "application_method_raw": clean_text(detail.get("application_method_raw")),
                "image_url": clean_text(detail.get("image_url")),
                "raw_fields": {
                    "parser": "usbl_bukgu_library_card+detail",
                    "page_url": page_url,
                    "list_pairs": pairs,
                    "list_status": status_text,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        if page_rows == 0:
            break
        if site_total and len(seen_detail_urls) >= site_total:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_detail_urls),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "total_count": site_total,
    }
    return dedupe_rows(rows), "usbl_bukgu_library_card+detail", meta


