def gugak_status(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    if "신청중" in text or "접수중" in text:
        return "접수중"
    if "신청대기" in text or "접수예정" in text:
        return "접수예정"
    if "신청마감" in text or "접수마감" in text or "마감" in text:
        return "접수마감"
    if "교육중" in text or "진행중" in text:
        return "진행중"
    if "교육종료" in text or "종료" in text:
        return "종료"
    return normalize_status(text) or text


def gugak_datetime_range(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    matches = list(
        re.finditer(
            r"(\d{4})[./-](\d{1,2})[./-](\d{1,2})(?:\s*\([^)]+\))?\s*(\d{1,2}:\d{2})?",
            text,
        )
    )
    if not matches:
        return normalize_mixed_date_range(text)

    def fmt(match: re.Match[str]) -> str:
        date_text = f"{int(match.group(1)):04d}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
        time_text = clean_text(match.group(4))
        return f"{date_text} {time_text}" if time_text else date_text

    if len(matches) >= 2:
        return f"{fmt(matches[0])} ~ {fmt(matches[1])}"
    return fmt(matches[0])


def gugak_date_range_status(period: Any) -> str:
    text = clean_text(period)
    dates = re.findall(r"\d{4}-\d{2}-\d{2}", text)
    if not dates:
        return ""
    today = datetime.now().date()
    try:
        start = datetime.strptime(dates[0], "%Y-%m-%d").date()
        end = datetime.strptime(dates[-1], "%Y-%m-%d").date()
    except ValueError:
        return ""
    if end < today:
        return "종료"
    if start > today:
        return "예정"
    return "진행중"


def gugak_schedule_from_text(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    ranges = []
    for start, end in re.findall(r"(\d{1,2}:\d{2})\s*~\s*(\d{1,2}:\d{2})", text):
        item = f"{start} ~ {end}"
        if item not in ranges:
            ranges.append(item)
    if ranges:
        return ", ".join(ranges[:6])
    singles = []
    for item in re.findall(r"\d{1,2}:\d{2}", text):
        if item not in singles:
            singles.append(item)
    return ", ".join(singles[:6])


def gugak_academy_params(onclick: Any) -> dict[str, str]:
    text = clean_text(onclick)
    params: dict[str, str] = {}
    for key in ("crsseqId", "srchCrscd", "srchTmplId"):
        match = re.search(rf"{re.escape(key)}'\s*:\s*'([^']+)'", text)
        if not match:
            match = re.search(rf'{re.escape(key)}"\s*:\s*"([^"]+)"', text)
        if match:
            params[key] = clean_text(match.group(1))
    return params


def gugak_academy_detail_url(params: dict[str, str]) -> str:
    required = {key: params.get(key, "") for key in ("crsseqId", "srchCrscd", "srchTmplId")}
    if not all(required.values()):
        return ""
    query = urlencode({**required, "currentMenuId": "900005001"})
    return f"{GUGAK_ACADEMY_DETAIL_URL}?{query}"


def gugak_pairs_from_title_spans(node: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(node, "select"):
        return pairs
    for item in node.select("li"):
        label_node = item.select_one("span.title")
        value_node = item.select_one("span.text")
        label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if label and value:
            pairs[label] = value
    return pairs


def gugak_extract_labeled_text(text: Any, label: str, stop_labels: tuple[str, ...]) -> str:
    value = extract_korean_labeled_value(clean_text(text), label, stop_labels)
    value = re.sub(r"\s+", " ", value)
    return clean_text(value)


def gugak_clean_place(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    text = re.split(r"\s*(?:문의안내|문의전화|신청방법|신청문의|담당부서|연락처)\s*", text, maxsplit=1)[0]
    return clean_text(text)


def gugak_description_from_academy_text(text: str) -> str:
    parts = []
    for label in ("교육목표", "교육내용", "신청방법안내"):
        value = gugak_extract_labeled_text(text, label, GUGAK_ACADEMY_LABELS)
        if value:
            parts.append(f"{label}: {value}")
    return clean_text(" | ".join(parts))[:1500]


def gugak_academy_capacity(text: str) -> tuple[str, Optional[int], Optional[int]]:
    pairs = [
        (int(current), int(total))
        for current, total in re.findall(r"신청인원\s*(\d{1,5})명\s*정원\s*(\d{1,5})명", clean_text(text).replace(",", ""))
    ]
    if not pairs:
        return "", None, None
    current_total = sum(current for current, _ in pairs)
    capacity_total = sum(total for _, total in pairs)
    return f"신청 {current_total}명 / 정원 {capacity_total}명", current_total, capacity_total


def gugak_academy_detail_fields(s: requests.Session, raw_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, raw_url, timeout=timeout)
    contents = soup.select_one("#contents") or soup
    text = clean_text(contents.get_text(" ", strip=True))
    info = soup.select_one(".lec_info_top.offline") or soup.select_one(".lec_info_top") or contents
    pairs = gugak_pairs_from_title_spans(info)
    if not pairs:
        pairs = pairs_from_definition_lists(info)
    title = clean_text((contents.select_one("h3") or soup.select_one("h3") or "").get_text(" ", strip=True))
    image_url = ""
    image_node = info.select_one(".ega_ui_bg[style*='url']") if hasattr(info, "select_one") else None
    if image_node:
        style = clean_text(image_node.get("style"))
        match = re.search(r"url\(([^)]+)\)", style)
        if match:
            image_url = normalize_link(raw_url, match.group(1).strip("'\""))
    place = gugak_clean_place(gugak_extract_labeled_text(text, "교육장소", GUGAK_ACADEMY_LABELS))
    schedule_raw = gugak_schedule_from_text(text) or gugak_schedule_from_text(pairs.get("교육기간"))
    capacity, capacity_current, capacity_total = gugak_academy_capacity(text)
    period = gugak_datetime_range(pairs.get("교육기간"))
    return {
        "title": title,
        "target": clean_text(pairs.get("수강대상")),
        "period": period,
        "apply_period": gugak_datetime_range(pairs.get("신청기간")),
        "schedule_raw": schedule_raw,
        "fee": clean_text(pairs.get("교육비")),
        "application_method_raw": clean_text(pairs.get("선정방법")),
        "department": clean_text(pairs.get("담당부서")),
        "phone": clean_text(pairs.get("연락처")),
        "room": place,
        "venue_name": place or GUGAK_BRANCH,
        "address": GUGAK_ADDRESS,
        "venue_address": GUGAK_ADDRESS,
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "description": gugak_description_from_academy_text(text),
        "image_url": image_url,
        "raw_detail_pairs": pairs,
    }


def collect_gugak_academy_courses(
    target: CrawlTarget,
    s: requests.Session,
    timeout: int,
    max_pages: int,
    detail_limit: int,
    page_budget: Optional[PageBudget] = None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    detail_errors = 0
    seen: set[str] = set()
    site_total = 0
    pagination_exhausted = False
    page_cap_reached = False

    page_budget = page_budget or PageBudget(max_pages)
    for page in range(1, max(1, max_pages) + 1):
        if not page_budget.claim():
            page_cap_reached = True
            break
        page_url = f"{GUGAK_ACADEMY_LIST_URL}?{urlencode({'currentPage': page, 'perPage': 8})}"
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        total_node = soup.select_one(".bbs_top")
        total_text = clean_text(total_node.get_text(" ", strip=True) if total_node else "")
        total_match = re.search(r"총\s*(\d+)\s*건", total_text.replace(",", ""))
        if total_match:
            site_total = max(site_total, int(total_match.group(1)))
        cards = soup.select("ul.lec_list.type2 > li")
        if not cards:
            pagination_exhausted = True
            break
        page_rows = 0
        for card in cards:
            link = card.select_one("a[onclick]")
            params = gugak_academy_params(link.get("onclick") if link else "")
            raw_url = gugak_academy_detail_url(params)
            title_node = card.select_one("strong")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            if not raw_url or not title or raw_url in seen:
                continue
            seen.add(raw_url)
            status_node = card.select_one(".stat span")
            status = gugak_status(status_node.get_text(" ", strip=True) if status_node else "")
            tags = [
                clean_text(node.get_text(" ", strip=True))
                for node in card.select(".cate span")
                if clean_text(node.get_text(" ", strip=True))
            ]
            method_node = card.select_one(".how span")
            method = clean_text(method_node.get_text(" ", strip=True) if method_node else "")
            category = clean_text(" / ".join(["오프라인강좌", *tags]))
            detail: dict[str, Any] = {}
            if detail_pages < max(0, detail_limit):
                try:
                    detail = gugak_academy_detail_fields(s, raw_url, timeout=timeout)
                    detail_pages += 1
                except Exception as exc:
                    detail_errors += 1
                    logger.debug("gugak academy detail fetch failed %s: %s", raw_url, exc)
            if not detail:
                continue
            final_title = clean_text(detail.get("title")) or title
            period = clean_text(detail.get("period"))
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, final_title, GUGAK_BRANCH),
                "title": final_title,
                "branch": GUGAK_BRANCH,
                "branch_code": "NATIONAL_GUGAK_CENTER",
                "preserve_branch": True,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url if status in {"접수중", "접수예정"} else "",
                "application_type": "ONLINE_RESERVATION" if status in {"접수중", "접수예정"} else "INFO_ONLY",
                "reservation_available": status == "접수중",
                "status": status,
                "target": clean_text(detail.get("target")) or "별도 안내",
                "fee": clean_text(detail.get("fee")),
                "period": period,
                "apply_period": clean_text(detail.get("apply_period")),
                "schedule_raw": clean_text(detail.get("schedule_raw")),
                "room": clean_text(detail.get("room")),
                "venue_name": clean_text(detail.get("venue_name")) or GUGAK_BRANCH,
                "address": GUGAK_ADDRESS,
                "venue_address": GUGAK_ADDRESS,
                "phone": clean_text(detail.get("phone")),
                "capacity": clean_text(detail.get("capacity")),
                "capacity_current": detail.get("capacity_current"),
                "capacity_total": detail.get("capacity_total"),
                "program_type": "강좌",
                "collection_category": "문화예술교육",
                "domain_category": "문화예술교육",
                "source_group": "generated_review",
                "operator_type": "국가기관",
                "collection_type": "static_html+detail",
                "description": clean_text(detail.get("description")) or clean_text(card.get_text(" ", strip=True)),
                "application_method_raw": clean_text(detail.get("application_method_raw")) or method,
                "department": clean_text(detail.get("department")),
                "image_url": clean_text(detail.get("image_url")),
                "raw_fields": {
                    "parser": "gugak_academy_card+detail",
                    "page_url": page_url,
                    "params": params,
                    "tags": tags,
                    "list_method": method,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        if page_rows == 0:
            break
        if site_total and len(seen) >= site_total:
            pagination_exhausted = True
            break

    pagination_complete = pagination_exhausted and (
        not site_total or len(seen) >= site_total
    )
    details_complete = (
        detail_pages == len(seen)
        and len(rows) == len(seen)
        and detail_errors == 0
    )
    return dedupe_rows(rows), {
        "academy_pages": pages,
        "academy_detail_pages": detail_pages,
        "academy_detail_errors": detail_errors,
        "academy_discovered_links": len(seen),
        "academy_total_count": site_total,
        "academy_pagination_complete": pagination_complete,
        "academy_details_complete": details_complete,
        "academy_page_cap_reached": page_cap_reached,
    }


def gugak_month_list_url(offset: int) -> str:
    today = datetime.now()
    month_index = today.month - 1 + offset
    year = today.year + month_index // 12
    month = month_index % 12 + 1
    query = urlencode({"menuid": "001001001001", "year": year, "month": f"{month:02d}"})
    return f"https://www.gugak.go.kr/site/program/performance/month_list?{query}"


def gugak_performance_title_from_text(text: str, fallback: str) -> str:
    fallback = clean_text(fallback)
    if fallback and fallback != "자세히 보기":
        return fallback
    match = re.search(r"^(.+?)\s+(?:\[[^\]]+\]\s+)?부제목\s+", clean_text(text))
    if match:
        return clean_text(match.group(1))
    return fallback


def gugak_clean_performance_value(value: Any) -> str:
    text = clean_text(value)
    text = text.replace("공연 기간 및 시간 선택", "")
    text = text.replace("공연일시 이동", "")
    return clean_text(text)


def gugak_performance_detail_fields(
    s: requests.Session,
    raw_url: str,
    timeout: int,
    fallback_title: str,
) -> dict[str, Any]:
    soup = fetch_soup(s, raw_url, timeout=timeout)
    content = soup.select_one("#content") or soup
    text = clean_text(content.get_text(" ", strip=True))
    title = gugak_performance_title_from_text(text, fallback_title)
    kind_match = re.search(r"\[([^\]]+)\]", text)
    kind = clean_text(kind_match.group(1) if kind_match else "")
    pairs = {
        label: gugak_clean_performance_value(gugak_extract_labeled_text(text, label, GUGAK_PERFORMANCE_LABELS))
        for label in ("부제목", "공연기간", "공연일시", "공연장소", "관람시간", "주최", "주관", "가격", "할인정보", "문의전화", "관람등급", "상세내용")
    }
    period = gugak_datetime_range(pairs.get("공연기간"))
    schedule_text = pairs.get("공연일시") or ""
    schedule_raw = gugak_schedule_from_text(schedule_text) or schedule_text
    if not period:
        period = gugak_datetime_range(schedule_text)
    status = gugak_date_range_status(period)
    image_url = ""
    image = content.select_one("img[src]") if hasattr(content, "select_one") else None
    if image:
        image_url = normalize_link(raw_url, image.get("src"))
    description = clean_text(pairs.get("상세내용"))[:1500]
    if not description:
        description = clean_text(
            " | ".join(
                part
                for part in (
                    kind,
                    pairs.get("공연기간"),
                    pairs.get("공연일시"),
                    pairs.get("공연장소"),
                    pairs.get("가격"),
                )
                if clean_text(part)
            )
        )
    return {
        "title": title,
        "category": kind,
        "period": period,
        "schedule_raw": schedule_raw,
        "room": pairs.get("공연장소", ""),
        "venue_name": pairs.get("공연장소") or GUGAK_BRANCH,
        "target": pairs.get("관람등급") or "별도 안내",
        "fee": pairs.get("가격") or "별도 안내",
        "phone": pairs.get("문의전화", ""),
        "host": pairs.get("주최", ""),
        "organizer": pairs.get("주관", ""),
        "duration": pairs.get("관람시간", ""),
        "status": status,
        "description": description,
        "image_url": image_url,
        "raw_detail_pairs": pairs,
    }


def collect_gugak_performances(
    target: CrawlTarget,
    s: requests.Session,
    timeout: int,
    max_pages: int,
    detail_limit: int,
    page_budget: Optional[PageBudget] = None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    detail_errors = 0
    seen: dict[str, dict[str, str]] = {}

    page_budget = page_budget or PageBudget(max_pages)
    requested_months = min(
        GUGAK_PERFORMANCE_HORIZON_MONTHS,
        max(0, max_pages),
    )
    page_cap_reached = False
    for offset in range(requested_months):
        if not page_budget.claim():
            page_cap_reached = True
            break
        page_url = gugak_month_list_url(offset)
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        links = soup.select('a[href*="performance_id="]')
        if not links:
            continue
        for link in links:
            raw_url = normalize_link(GUGAK_PERFORMANCE_DETAIL_BASE_URL, link.get("href"))
            parsed = urlparse(raw_url)
            performance_id = clean_text((parse_qs(parsed.query).get("performance_id") or [""])[0])
            if not performance_id:
                continue
            title = clean_text(link.get_text(" ", strip=True))
            current = seen.setdefault(performance_id, {"raw_url": raw_url, "title": ""})
            if title and title != "자세히 보기" and not current["title"]:
                current["title"] = title

    for performance_id, item in seen.items():
        raw_url = clean_text(item.get("raw_url"))
        title = clean_text(item.get("title"))
        detail: dict[str, Any] = {}
        if detail_pages < max(0, detail_limit):
            try:
                detail = gugak_performance_detail_fields(s, raw_url, timeout=timeout, fallback_title=title)
                detail_pages += 1
            except Exception as exc:
                detail_errors += 1
                logger.debug("gugak performance detail fetch failed %s: %s", raw_url, exc)
        if not detail:
            continue
        final_title = clean_text(detail.get("title")) or title
        if not final_title:
            continue
        category = clean_text(detail.get("category"))
        program_type = normalize_program_type("공연", final_title, category)
        if "전시" in final_title or category == "전시":
            program_type = "전시"
        row = {
            "provider": target.provider,
            "provider_course_id": stable_course_id(target.provider, raw_url, final_title, GUGAK_BRANCH),
            "title": final_title,
            "branch": GUGAK_BRANCH,
            "branch_code": "NATIONAL_GUGAK_CENTER",
            "preserve_branch": True,
            "category": category or program_type,
            "raw_url": raw_url,
            "application_url": raw_url,
            "application_type": "ONLINE_RESERVATION",
            "reservation_available": clean_text(detail.get("status")) in {"예정", "진행중"},
            "status": clean_text(detail.get("status")),
            "target": clean_text(detail.get("target")),
            "fee": clean_text(detail.get("fee")),
            "period": clean_text(detail.get("period")),
            "schedule_raw": clean_text(detail.get("schedule_raw")),
            "room": clean_text(detail.get("room")),
            "venue_name": clean_text(detail.get("venue_name")) or GUGAK_BRANCH,
            "address": GUGAK_ADDRESS,
            "venue_address": GUGAK_ADDRESS,
            "phone": clean_text(detail.get("phone")),
            "host": clean_text(detail.get("host")),
            "organizer": clean_text(detail.get("organizer")),
            "duration": clean_text(detail.get("duration")),
            "program_type": program_type,
            "collection_category": "공연전시",
            "domain_category": "공연전시",
            "source_group": "generated_review",
            "operator_type": "국가기관",
            "collection_type": "static_html+detail",
            "description": clean_text(detail.get("description")),
            "image_url": clean_text(detail.get("image_url")),
            "raw_fields": {
                "parser": "gugak_performance_month+detail",
                "performance_id": performance_id,
                "detail_pairs": detail.get("raw_detail_pairs", {}),
            },
        }
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

    pagination_complete = pages == GUGAK_PERFORMANCE_HORIZON_MONTHS
    details_complete = (
        detail_pages == len(seen)
        and len(rows) == len(seen)
        and detail_errors == 0
    )
    return dedupe_rows(rows), {
        "performance_pages": pages,
        "performance_detail_pages": detail_pages,
        "performance_detail_errors": detail_errors,
        "performance_discovered_links": len(seen),
        "performance_horizon_months": GUGAK_PERFORMANCE_HORIZON_MONTHS,
        "performance_pagination_complete": pagination_complete,
        "performance_details_complete": details_complete,
        "performance_page_cap_reached": page_cap_reached,
    }


def collect_gugak_center_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    page_budget = PageBudget(max_pages)
    academy_rows, academy_meta = collect_gugak_academy_courses(
        target,
        s,
        timeout=timeout,
        max_pages=max_pages,
        detail_limit=max(0, detail_limit),
        page_budget=page_budget,
    )
    performance_page_limit = max(0, max_pages - page_budget.used)
    performance_detail_limit = max(
        0,
        detail_limit - int(academy_meta.get("academy_detail_pages") or 0),
    )
    performance_rows, performance_meta = collect_gugak_performances(
        target,
        s,
        timeout=timeout,
        max_pages=performance_page_limit,
        detail_limit=performance_detail_limit,
        page_budget=page_budget,
    )
    rows = dedupe_rows([*academy_rows, *performance_rows])
    pagination_complete = bool(
        academy_meta.get("academy_pagination_complete")
        and performance_meta.get("performance_pagination_complete")
    )
    details_complete = bool(
        academy_meta.get("academy_details_complete")
        and performance_meta.get("performance_details_complete")
    )
    snapshot_complete = pagination_complete and details_complete
    meta = {
        "pages": academy_meta.get("academy_pages", 0) + performance_meta.get("performance_pages", 0),
        "detail_pages": academy_meta.get("academy_detail_pages", 0) + performance_meta.get("performance_detail_pages", 0),
        "discovered_links": academy_meta.get("academy_discovered_links", 0) + performance_meta.get("performance_discovered_links", 0),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": True,
        "pagination_complete": pagination_complete,
        "detail_collection_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "page_cap_reached": bool(
            academy_meta.get("academy_page_cap_reached")
            or performance_meta.get("performance_page_cap_reached")
        ),
        "detail_cap_reached": not details_complete and detail_limit > 0,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        **academy_meta,
        **performance_meta,
    }
    return rows, "gugak_academy_performance+detail", meta


BWB_CHUNCHEON_LIST_URL = "https://bwb.chuncheon.go.kr/enrollment/category/"
BWB_CHUNCHEON_DETAIL_URL = "https://bwb.chuncheon.go.kr/enrollment/detail-view/"
BWB_CHUNCHEON_ADDRESS = "강원특별자치도 춘천시 퇴계농공로 40"


def bwb_chuncheon_fetch_soup(
    s: requests.Session,
    url: str,
    timeout: int,
    *,
    method: str = "GET",
    data: Optional[dict[str, Any]] = None,
) -> BeautifulSoup:
    if method == "POST":
        response = s.post(url, data=data or {}, timeout=timeout, verify=True)
    else:
        response = s.get(url, params=data or {}, timeout=timeout, verify=True)
    response.raise_for_status()
    response.encoding = "utf-8"
    return BeautifulSoup(response.text, "lxml")


def bwb_chuncheon_status(value: Any) -> str:
    text = clean_text(value)
    if "접수중" in text:
        return "접수중"
    if "대기" in text:
        return "접수예정"
    if "마감" in text:
        return "접수마감"
    if "교육중" in text:
        return "진행중"
    if "교육완료" in text or "완료" in text:
        return "종료"
    return normalize_status(text) or text


def bwb_chuncheon_lecture_id(node: Any) -> str:
    if not hasattr(node, "select"):
        return ""
    for button in node.select("button[onclick]"):
        onclick = clean_text(button.get("onclick"))
        match = re.search(r"fn_view\((\d+)\)", onclick)
        if match:
            return match.group(1)
    return ""


def bwb_chuncheon_page_total(soup: BeautifulSoup) -> int:
    max_page = 0
    for node in soup.select("a[onclick*='fn_list']"):
        match = re.search(r"fn_list\((\d+)\)", clean_text(node.get("onclick")))
        if match:
            max_page = max(max_page, int(match.group(1)))
    return max_page


def bwb_chuncheon_detail_fields(
    s: requests.Session,
    lecture_id: str,
    timeout: int,
    fallback_title: str,
) -> dict[str, Any]:
    soup = bwb_chuncheon_fetch_soup(
        s,
        BWB_CHUNCHEON_DETAIL_URL,
        timeout=timeout,
        method="POST",
        data={"lifelongGisuLectureId": lecture_id, "backFlag": "category"},
    )
    view = soup.select_one(".view-wrap") or soup
    pairs = pairs_from_definition_lists(view)
    title_node = view.select_one("h3")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else fallback_title)
    category_node = view.select_one(".view-top span")
    category = clean_text(category_node.get_text(" ", strip=True) if category_node else "")
    status_node = view.select_one(".view-top .label")
    status = bwb_chuncheon_status(status_node.get_text(" ", strip=True) if status_node else "")
    capacity = clean_text(pairs.get("접수인원"))
    capacity_current, capacity_total = parse_capacity_pair(capacity)
    period = gugak_datetime_range(pairs.get("교육기간"))
    apply_period = gugak_datetime_range(pairs.get("일반접수 모집기간") or pairs.get("모집기간"))
    place = clean_text(pairs.get("교육장소"))
    institution = clean_text(pairs.get("교육기관"))
    address = clean_text(pairs.get("주소"))
    if address.startswith("("):
        address = clean_text(re.sub(r"^\(\d{5}\)", "", address))
    description = clean_text(
        " | ".join(
            part
            for part in (
                pairs.get("강의소개"),
                pairs.get("강의목표"),
                pairs.get("교육방법"),
            )
            if clean_text(part)
        )
    )
    return {
        "title": title,
        "category": category,
        "status": status,
        "target": clean_text(pairs.get("대상자")),
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": clean_text(pairs.get("교육시간")),
        "fee": clean_text(pairs.get("수강료")) or "무료",
        "material_fee": clean_text(pairs.get("재료비")),
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "room": place,
        "venue_name": place or institution,
        "venue_address": address or BWB_CHUNCHEON_ADDRESS,
        "address": address or BWB_CHUNCHEON_ADDRESS,
        "branch": institution,
        "instructor": clean_text(pairs.get("강사")),
        "application_method_raw": clean_text(pairs.get("모집방식")),
        "education_type": clean_text(pairs.get("교육유형")),
        "phone": clean_text(pairs.get("전화번호")),
        "description": description[:1500],
        "raw_detail_pairs": pairs,
    }


def collect_bwb_chuncheon_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": BWB_CHUNCHEON_LIST_URL})
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    seen: set[str] = set()
    site_total = 0

    for page in range(1, max(1, max_pages) + 1):
        page_url = f"{BWB_CHUNCHEON_LIST_URL}?{urlencode({'pageIndex': page})}"
        soup = bwb_chuncheon_fetch_soup(s, BWB_CHUNCHEON_LIST_URL, timeout=timeout, data={"pageIndex": page})
        pages += 1
        pagination_detected = pagination_detected or bool(soup.select("a[onclick*='fn_list']"))
        site_total = max(site_total, bwb_chuncheon_page_total(soup) * 9)
        boxes = soup.select(".list-wrap .box")
        if not boxes:
            break
        page_rows = 0
        for box in boxes:
            title_node = box.select_one("h3")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            lecture_id = bwb_chuncheon_lecture_id(box)
            row_key = lecture_id or f"{page}:{title}"
            if not title or not row_key or row_key in seen:
                continue
            seen.add(row_key)
            list_pairs = pairs_from_definition_lists(box)
            detail: dict[str, Any] = {}
            if lecture_id and detail_pages < max(0, detail_limit):
                try:
                    detail = bwb_chuncheon_detail_fields(s, lecture_id, timeout=timeout, fallback_title=title)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("bwb chuncheon detail fetch failed %s: %s", lecture_id, exc)
            raw_url = (
                f"{BWB_CHUNCHEON_DETAIL_URL}?lifelongGisuLectureId={quote(lecture_id)}"
                if lecture_id
                else f"{page_url}#{quote(title)}"
            )
            final_title = clean_text(detail.get("title")) or title
            branch = clean_text(detail.get("branch")) or clean_text(list_pairs.get("교육기관")) or target.branch
            labels = [clean_text(node.get_text(" ", strip=True)) for node in box.select(".label")]
            list_status = next((label for label in labels if label in {"접수중", "대기", "마감", "교육중", "교육완료"}), "")
            status = clean_text(detail.get("status")) or bwb_chuncheon_status(list_status)
            list_capacity = clean_text(list_pairs.get("모집인원"))
            list_capacity_current, list_capacity_total = parse_capacity_pair(list_capacity)
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, final_title, branch),
                "title": final_title,
                "branch": branch,
                "branch_code": stable_provider("BWB_CHUNCHEON", branch),
                "preserve_branch": True,
                "category": clean_text(detail.get("category")) or "평생학습",
                "raw_url": raw_url,
                "application_url": raw_url if status in {"접수중", "접수예정"} else "",
                "application_type": "ONLINE_RESERVATION" if status in {"접수중", "접수예정"} else "INFO_ONLY",
                "reservation_available": status == "접수중",
                "status": status,
                "target": clean_text(detail.get("target")) or clean_text(list_pairs.get("대상자")),
                "fee": clean_text(detail.get("fee")) or "별도 안내",
                "material_fee": clean_text(detail.get("material_fee")),
                "period": clean_text(detail.get("period")) or gugak_datetime_range(list_pairs.get("교육기간")),
                "apply_period": clean_text(detail.get("apply_period")) or gugak_datetime_range(list_pairs.get("접수기간")),
                "schedule_raw": clean_text(detail.get("schedule_raw")) or clean_text(list_pairs.get("교육시간")),
                "capacity": clean_text(detail.get("capacity")) or clean_text(list_pairs.get("모집인원")),
                "capacity_current": detail.get("capacity_current") if detail.get("capacity_current") is not None else list_capacity_current,
                "capacity_total": detail.get("capacity_total") if detail.get("capacity_total") is not None else list_capacity_total,
                "room": clean_text(detail.get("room")),
                "venue_name": clean_text(detail.get("venue_name")) or branch,
                "address": clean_text(detail.get("address")) or BWB_CHUNCHEON_ADDRESS,
                "venue_address": clean_text(detail.get("venue_address")) or BWB_CHUNCHEON_ADDRESS,
                "instructor": clean_text(detail.get("instructor")) or clean_text(list_pairs.get("강사")),
                "phone": clean_text(detail.get("phone")),
                "program_type": "강좌",
                "collection_category": "평생학습",
                "domain_category": "평생학습",
                "source_group": clean_text(target.extra.get("source_group") or "lifelong_learning"),
                "operator_type": "지자체",
                "collection_type": "static_html+detail_post",
                "description": clean_text(detail.get("description")) or clean_text(box.get_text(" ", strip=True)),
                "application_method_raw": clean_text(detail.get("application_method_raw")),
                "education_type": clean_text(detail.get("education_type")),
                "raw_fields": {
                    "parser": "bwb_chuncheon_card+detail_post",
                    "page": page,
                    "lecture_id": lecture_id,
                    "list_pairs": list_pairs,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "total_count_estimate": site_total,
    }
    return dedupe_rows(rows), "bwb_chuncheon_card+detail_post", meta


SOKCHO_EDU_BASE_URL = "https://edu.sokcho.go.kr"
SOKCHO_EDU_ADDRESS = "강원특별자치도 속초시 수복로 46"
SOKCHO_EDU_BRANCH = "속초시평생교육문화센터"
SOKCHO_EDU_PHONE = "033-635-2525"


def sokcho_edu_list_urls() -> list[tuple[str, str]]:
    return [
        ("주간반", f"{SOKCHO_EDU_BASE_URL}/lecture/class_list.php?lc_type=0"),
        ("야간반", f"{SOKCHO_EDU_BASE_URL}/lecture/class_list.php?lc_type=1"),
        ("특별프로그램", f"{SOKCHO_EDU_BASE_URL}/lecture/class_list.php?lco_type=3"),
    ]


def sokcho_status(value: Any) -> str:
    text = clean_text(value)
    if "신청종료" in text or "종료" in text or "마감" in text:
        return "접수마감"
    if "신청" in text or "접수중" in text:
        return "접수중"
    if "대기" in text:
        return "접수예정"
    return normalize_status(text) or text


def sokcho_datetime_range(value: Any) -> str:
    text = clean_text(value)
    text = re.sub(r"(\d{1,2})시", lambda m: f"{int(m.group(1)):02d}:00", text)
    return gugak_datetime_range(text)


def sokcho_fee(value: Any) -> str:
    text = clean_text(value).replace(" ", "")
    if not text:
        return "무료"
    if re.fullmatch(r"\d[\d,]*", text):
        return f"{int(text.replace(',', '')):,}원"
    if re.search(r"\d", text) and "원" not in text:
        text = re.sub(r"(\d[\d,]*)", lambda m: f"{int(m.group(1).replace(',', '')):,}원", text, count=1)
    return clean_text(text)


def sokcho_table_pairs(node: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(node, "select"):
        return pairs
    for tr in node.select("tr"):
        cells = tr.find_all(["th", "td"], recursive=False)
        index = 0
        while index < len(cells):
            cell = cells[index]
            if cell.name != "th":
                index += 1
                continue
            key = clean_text(cell.get_text(" ", strip=True)).rstrip(":：")
            value = ""
            if index + 1 < len(cells):
                value = clean_text(cells[index + 1].get_text(" ", strip=True))
            if key and value:
                pairs[key] = value
            index += 2
    return pairs


def collect_sokcho_education_center(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    discovered = 0
    for category, list_url in sokcho_edu_list_urls():
        soup = fetch_soup(s, list_url, timeout=timeout)
        pages += 1
        for item in soup.select(".list_div"):
            title_node = item.select_one(".list_div_title .title")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            title = clean_text(re.sub(r"^\d+\.\s*", "", title))
            if not title or is_low_value_title(title):
                continue
            discovered += 1
            status_node = item.select_one(".list_div_title .but")
            status = sokcho_status(status_node.get_text(" ", strip=True) if status_node else "")
            pairs = sokcho_table_pairs(item)
            period = sokcho_datetime_range(pairs.get("강의기간"))
            apply_period = sokcho_datetime_range(pairs.get("접수기간"))
            pay_period = sokcho_datetime_range(pairs.get("납부기간"))
            capacity_text = clean_text(pairs.get("정원/신청"))
            capacity_total = None
            capacity_current = None
            cap_match = re.search(r"(\d{1,5})\s*/\s*(\d{1,5})", capacity_text.replace(",", ""))
            if cap_match:
                capacity_total = int(cap_match.group(1))
                capacity_current = int(cap_match.group(2))
            room = clean_text(pairs.get("강의장소"))
            raw_url = f"{list_url}#{clean_text(item.get('id')) or quote(title)}"
            description = clean_text(pairs.get("강의내용"))
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, SOKCHO_EDU_BRANCH),
                "title": title,
                "branch": SOKCHO_EDU_BRANCH,
                "branch_code": "SOKCHO_EDU_CENTER",
                "preserve_branch": True,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url if status in {"접수중", "접수예정"} else "",
                "application_type": "ONLINE_RESERVATION" if status in {"접수중", "접수예정"} else "INFO_ONLY",
                "reservation_available": status == "접수중",
                "status": status,
                "fee": sokcho_fee(pairs.get("수강료")),
                "period": period,
                "apply_period": apply_period,
                "payment_period": pay_period,
                "schedule_raw": clean_text(pairs.get("강의시간")),
                "target": clean_text(pairs.get("모집제한")) or "제한 없음",
                "capacity": capacity_text,
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "room": room,
                "venue_name": clean_text(" ".join(part for part in (SOKCHO_EDU_BRANCH, room) if part)),
                "address": SOKCHO_EDU_ADDRESS,
                "venue_address": SOKCHO_EDU_ADDRESS,
                "instructor": clean_text(pairs.get("강사명")),
                "phone": SOKCHO_EDU_PHONE,
                "program_type": "강좌",
                "collection_category": "평생학습",
                "domain_category": "평생학습",
                "source_group": clean_text(target.extra.get("source_group") or "lifelong_learning"),
                "operator_type": "지자체",
                "collection_type": "static_html",
                "description": description or clean_text(item.get_text(" ", strip=True)),
                "application_method_raw": clean_text(pairs.get("선발기준")),
                "raw_fields": {
                    "parser": "sokcho_education_center_list",
                    "list_url": list_url,
                    "pairs": pairs,
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": discovered,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "sokcho_education_center_list", meta


GUMIGX_BASE_URL = "https://www.gumigx.kr"
GUMIGX_BRANCH = "구미시근로자문화센터"
GUMIGX_ADDRESS = "경북 구미시 해마루공원로 24"
GUMIGX_PHONE = "054-476-4114"


def gumigx_amount_text(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    text = re.sub(
        r"(?<![\d,])(\d{1,3}(?:,\d{3})+|\d{4,6})(?!\s*원)",
        lambda m: f"{int(m.group(1).replace(',', '')):,}원",
        text,
    )
    text = re.sub(r"(\d)\s+원", r"\1원", text)
    return text


def gumigx_cell(value: Any) -> str:
    text = clean_text(value)
    return "" if text.lower() == "nan" else text


def gumigx_base_row(target: CrawlTarget, raw_url: str, title: str, category: str) -> dict[str, Any]:
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, GUMIGX_BRANCH),
        "title": title,
        "branch": GUMIGX_BRANCH,
        "branch_code": "GUMIGX_CENTER",
        "preserve_branch": True,
        "address": GUMIGX_ADDRESS,
        "venue_address": GUMIGX_ADDRESS,
        "phone": GUMIGX_PHONE,
        "category": category,
        "collection_category": "문화센터",
        "domain_category": "문화센터",
        "source_group": clean_text(target.extra.get("source_group") or "arts_culture"),
        "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
        "collection_type": "static_html",
        "application_type": "INFO_ONLY",
        "reservation_available": False,
        "status": "상시 안내",
        "application_method_raw": "온라인 신청은 로그인 필요 / 방문 접수 가능",
    }


def gumigx_table_rows(table: Any) -> list[list[str]]:
    rows: list[list[str]] = []
    for tr in table.select("tr"):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"], recursive=False)]
        if cells:
            rows.append(cells)
    return rows


def gumigx_health_rows(target: CrawlTarget, s: requests.Session, timeout: int) -> list[dict[str, Any]]:
    url = f"{GUMIGX_BASE_URL}/program/health.asp"
    soup = fetch_soup(s, url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    try:
        import pandas as pd

        tables = pd.read_html(url)
    except Exception as exc:
        logger.debug("gumigx pandas table parse failed %s: %s", url, exc)
        tables = []

    if len(tables) >= 4:
        for index, record in tables[3].fillna("").iterrows():
            cells = [gumigx_cell(value) for value in record.tolist()]
            if len(cells) < 8 or not cells[0]:
                continue
            title = f"{cells[0]} 월회원"
            raw_url = stable_list_item_url(
                url,
                target.provider,
                title,
                GUMIGX_BRANCH,
                "health",
                index + 1,
                *cells,
            )
            row = gumigx_base_row(target, raw_url, title, "생활체육")
            row.update(
                {
                    "raw_url": raw_url,
                    "period": "월별 운영",
                    "apply_period": "상시 접수",
                    "schedule_raw": clean_text(f"{cells[3]} {cells[1]}"),
                    "target": "성인 / 청소년 / 군인 / 경로",
                    "fee": gumigx_amount_text(cells[4]),
                    "room": cells[5],
                    "venue_name": cells[5],
                    "description": clean_text(" | ".join(part for part in (cells[6], f"준비물: {cells[7]}") if part)),
                    "program_type": "생활체육",
                    "raw_fields": {"parser": "gumigx_static_programs", "source_url": url, "cells": cells},
                }
            )
            rows.append(row)

    if len(tables) >= 5:
        gx_table = tables[4].fillna("")
        for index, record in gx_table.iterrows():
            cells = [gumigx_cell(value) for value in record.tolist()]
            if len(cells) < 7:
                continue
            title = clean_text(cells[0])
            if not title:
                continue
            raw_url = stable_list_item_url(
                url,
                target.provider,
                title,
                GUMIGX_BRANCH,
                "gx",
                index + 1,
                *cells,
            )
            row = gumigx_base_row(target, raw_url, title, "GX")
            row.update(
                {
                    "raw_url": raw_url,
                    "period": "월별 운영",
                    "apply_period": "상시 접수",
                    "schedule_raw": clean_text(f"월/수/금 {cells[1]}"),
                    "target": "지역주민",
                    "capacity": clean_text(cells[2]),
                    "capacity_total": parse_capacity_number(cells[2]),
                    "room": clean_text(cells[3]),
                    "venue_name": clean_text(cells[3]),
                    "fee": gumigx_amount_text(cells[4]),
                    "description": clean_text(" | ".join(part for part in (cells[5], f"준비물: {cells[6]}") if part)),
                    "program_type": "생활체육",
                    "raw_fields": {"parser": "gumigx_static_programs", "source_url": url, "cells": cells},
                }
            )
            rows.append(row)

    if rows:
        return rows

    tables = soup.select("table")
    if len(tables) < 5:
        return rows

    health_rows = gumigx_table_rows(tables[3])
    health_fee = ""
    health_room = "헬스"
    health_description = ""
    health_prepare = ""
    for cells in health_rows[1:]:
        if len(cells) >= 8:
            health_fee = gumigx_amount_text(cells[4])
            health_room = clean_text(cells[5]) or health_room
            health_description = clean_text(cells[6])
            health_prepare = clean_text(cells[7])
            schedule = clean_text(f"{cells[3]} {cells[1]}")
        elif len(cells) >= 2 and health_fee:
            schedule = clean_text(f"{cells[2] if len(cells) > 2 else ''} {cells[0]}")
        else:
            continue
        title = "헬스 월회원"
        raw_url = stable_list_item_url(
            url,
            target.provider,
            title,
            GUMIGX_BRANCH,
            "health",
            schedule,
            *cells,
        )
        row = gumigx_base_row(target, raw_url, title, "생활체육")
        row.update(
            {
                "raw_url": raw_url,
                "period": "월별 운영",
                "apply_period": "상시 접수",
                "schedule_raw": schedule,
                "target": "성인 / 청소년 / 군인 / 경로",
                "fee": health_fee,
                "room": health_room,
                "venue_name": health_room,
                "description": clean_text(" | ".join(part for part in (health_description, f"준비물: {health_prepare}") if part)),
                "program_type": "생활체육",
                "raw_fields": {"parser": "gumigx_static_programs", "source_url": url, "cells": cells},
            }
        )
        rows.append(row)
    return rows


def gumigx_swim_fee(soup: BeautifulSoup) -> str:
    for table in soup.select("table"):
        rows = gumigx_table_rows(table)
        if len(rows) < 3:
            continue
        if any(row and row[0] == "성인" for row in rows) and any(row and row[0] == "청소년" for row in rows):
            fees: list[str] = []
            for row in rows:
                if len(row) >= 3 and row[0] in {"성인", "청소년", "어린이/경로"}:
                    fees.append(f"{row[0]} 관내 {gumigx_amount_text(row[1])} / 관외 {gumigx_amount_text(row[2])}")
            if fees:
                return "; ".join(fees)
    return ""


def gumigx_swim_rows(target: CrawlTarget, s: requests.Session, timeout: int) -> list[dict[str, Any]]:
    url = f"{GUMIGX_BASE_URL}/program/swim.asp"
    soup = fetch_soup(s, url, timeout=timeout)
    fee = gumigx_swim_fee(soup)
    tables = soup.select("table")
    if len(tables) < 3:
        return []
    lesson_rows = gumigx_table_rows(tables[2])
    rows: list[dict[str, Any]] = []
    level_names = [("초급반", 1), ("중급반", 2), ("상급반", 3)]
    for row_index, cells in enumerate(lesson_rows[1:], start=1):
        if not cells:
            continue
        time_text = clean_text(cells[0]).replace("초등반", "초등반 ")
        if "클리닝" in time_text or time_text in {"이용요금", "구분", "성인", "청소년", "어린이/경로"}:
            continue
        time_match = re.search(r"\d{1,2}:\d{2}\s*~\s*\d{1,2}:\d{2}", time_text)
        if not time_match:
            continue
        schedule = time_match.group(0)
        target_text = "초등 3학년 이상" if "초등반" in time_text else "지역주민"
        combined = clean_text(" ".join(cells[1:4]))
        special_match = re.search(r"(아쿠아세라피|아쿠아로빅)\s*정원\s*(\d+)", combined)
        if special_match:
            title = f"수영 {special_match.group(1)}"
            capacity_total = int(special_match.group(2))
            raw_url = stable_list_item_url(
                url,
                target.provider,
                title,
                GUMIGX_BRANCH,
                "swim",
                row_index,
                "special",
                schedule,
                capacity_total,
            )
            row = gumigx_base_row(target, raw_url, title, "수영")
            row.update(
                {
                    "raw_url": raw_url,
                    "period": "월별 운영",
                    "apply_period": "상시 접수",
                    "schedule_raw": schedule,
                    "target": target_text,
                    "capacity": f"{capacity_total}명",
                    "capacity_total": capacity_total,
                    "fee": fee,
                    "room": "수영장",
                    "venue_name": "수영장",
                    "description": "구미시근로자문화센터 수영 프로그램",
                    "program_type": "생활체육",
                    "raw_fields": {"parser": "gumigx_static_programs", "source_url": url, "cells": cells},
                }
            )
            rows.append(row)
            continue
        for level_name, cell_index in level_names:
            if cell_index >= len(cells):
                continue
            capacity_text = clean_text(cells[cell_index])
            if not capacity_text or capacity_text == "-" or not re.search(r"\d", capacity_text):
                continue
            capacity_total = parse_capacity_number(capacity_text)
            title = f"수영 {level_name}({schedule})"
            raw_url = stable_list_item_url(
                url,
                target.provider,
                title,
                GUMIGX_BRANCH,
                "swim",
                row_index,
                level_name,
                schedule,
                capacity_text,
            )
            row = gumigx_base_row(target, raw_url, title, "수영")
            row.update(
                {
                    "raw_url": raw_url,
                    "period": "월별 운영",
                    "apply_period": "상시 접수",
                    "schedule_raw": schedule,
                    "target": target_text,
                    "capacity": capacity_text,
                    "capacity_total": capacity_total,
                    "fee": fee,
                    "room": "수영장",
                    "venue_name": "수영장",
                    "description": "초급반: 자유형/배영/평영, 중급반: 평영/접영, 상급반: 접영 완성 및 교정",
                    "program_type": "생활체육",
                    "raw_fields": {"parser": "gumigx_static_programs", "source_url": url, "cells": cells},
                }
            )
            rows.append(row)
    return rows


def gumigx_library_rows(target: CrawlTarget, s: requests.Session, timeout: int) -> list[dict[str, Any]]:
    url = f"{GUMIGX_BASE_URL}/library/library_program.asp"
    fetch_soup(s, url, timeout=timeout)
    specs = [
        ("해마루독서회", "작은도서관", "매달", "매달 둘째주 화요일 19:00", "지역주민", "작은도서관", "다양한 분야의 책을 읽고 자유롭게 토론하는 독서모임", "프로그램"),
        ("원화 아트프린팅 전시", "전시", "매달", "상시", "지역주민", "작은도서관 앞", "그림책 원화 아트프린팅 전시", "전시"),
        ("도서관주간 행사", "행사", "4월", "상세 일정 별도 안내", "지역주민", "작은도서관", "기증도서 나눔 및 과월잡지 나눔", "행사"),
        ("만화·장르소설 특화코너", "작은도서관", "상시 운영", "상시", "지역주민", "작은도서관", "웹툰 및 장르소설 특화코너 운영", "프로그램"),
        ("청소년 자원봉사", "작은도서관", "상시 운영", "매주 토요일 10:00, 14:00", "청소년", "작은도서관", "청소년 활동정보서비스를 통한 자원봉사 프로그램", "프로그램"),
    ]
    rows: list[dict[str, Any]] = []
    for index, (title, category, period, schedule, target_text, room, description, program_type) in enumerate(specs, start=1):
        raw_url = stable_list_item_url(
            url,
            target.provider,
            title,
            GUMIGX_BRANCH,
            "library",
            index,
            category,
            schedule,
        )
        row = gumigx_base_row(target, raw_url, title, category)
        row.update(
            {
                "raw_url": raw_url,
                "period": period,
                "apply_period": "전화 및 방문 문의",
                "schedule_raw": schedule,
                "target": target_text,
                "fee": "별도 안내",
                "room": room,
                "venue_name": room,
                "phone": "054-476-6444",
                "description": description,
                "program_type": program_type,
                "raw_fields": {"parser": "gumigx_static_programs", "source_url": url},
            }
        )
        rows.append(row)
    return rows


def collect_gumigx_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    page_collectors = (
        gumigx_swim_rows,
        gumigx_health_rows,
        gumigx_library_rows,
    )
    pages = 0
    for collector in page_collectors[: max(1, min(len(page_collectors), max_pages))]:
        try:
            page_rows = collector(target, s, timeout)
            pages += 1
            rows.extend(page_rows)
        except Exception as exc:
            logger.debug("gumigx program collector failed %s: %s", collector.__name__, exc)
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gumigx_static_programs", meta


ULSAN_EDU_BOOKING_LIST_URL = "https://use.go.kr/booking/user/reservation/Edu/BD_selectReservationMngList.do"
ULSAN_EDU_BOOKING_DETAIL_URL = "https://use.go.kr/booking/user/reservation/Edu/BD_selectReservationMng.do"


def normalize_ulsan_booking_datetime_range(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""

    def repl(match: re.Match[str]) -> str:
        year = int(match.group(1))
        month = int(match.group(2))
        day = int(match.group(3))
        time_text = clean_text(match.group(4))
        return f"{year:04d}-{month:02d}-{day:02d}" + (f" {time_text}" if time_text else "")

    text = re.sub(r"(\d{4})\s*년\s*(\d{1,2})\s*월\s*(\d{1,2})\s*일\s*(\d{1,2}:\d{2})?", repl, text)
    text = re.sub(r"\s+-\s+", " ~ ", text)
    return clean_text(text)


def ulsan_booking_info_pairs(item: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select("ul.info > li"):
        label_node = li.select_one(".tit")
        if not label_node:
            continue
        label_text = clean_text(label_node.get_text(" ", strip=True))
        value = clean_text(li.get_text(" ", strip=True).replace(label_text, "", 1))
        if label_text:
            pairs[label_text] = value
    return pairs


def parse_ulsan_booking_onclick(onclick: Any) -> str:
    text = clean_text(onclick)
    match = re.search(r"opViewReservation\(\s*'([^']+)'", text)
    return clean_text(match.group(1)) if match else ""


def ulsan_booking_institution_metadata(branch: Any) -> dict[str, str]:
    """Classify only rows owned by an explicit museum/science/library branch."""

    branch_name = clean_text(branch)
    source_group = infer_experience_institution_source_group(
        branch_name=branch_name,
    )
    if not source_group:
        return {}
    if source_group == "library":
        category = "도서관"
    else:
        category = next(
            (
                keyword
                for keyword in ("과학관", "미술관", "박물관")
                if keyword in branch_name
            ),
            "체험",
        )
    return {
        "collection_category": category,
        "domain_category": category,
        "source_group": source_group,
        "service_group": SERVICE_GROUP_EXPERIENCE,
        "service_group_policy": "locked",
    }


def extract_ulsan_detail_section(text: str) -> str:
    lines = [clean_text(line) for line in text.splitlines() if clean_text(line)]
    stop_labels = {"위치정보", "유의사항", "예약현황", "목록", "TOP"}
    for index, line in enumerate(lines):
        if line == "소개":
            values: list[str] = []
            for value in lines[index + 1 :]:
                if value in stop_labels:
                    break
                values.append(value)
            return clean_text(" ".join(values))
    return ""


def collect_ulsan_booking_detail(
    s: requests.Session,
    raw_url: str,
    timeout: int,
) -> dict[str, Any]:
    response = s.get(raw_url, verify=True, timeout=timeout)
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    soup = BeautifulSoup(response.text, "lxml")
    text = soup.get_text("\n", strip=True)
    description = extract_ulsan_detail_section(text)
    material_note = ""
    if description:
        material_lines = [
            clean_text(part)
            for part in re.split(r"[.\n]", description)
            if any(keyword in part for keyword in ("준비물", "재료", "재료비", "교재비"))
        ]
        material_note = clean_text(" ".join(material_lines))
    image_url = ""
    for image in soup.select("img"):
        src = clean_text(image.get("src"))
        if not src or "logo" in src.lower() or "footer" in src.lower() or "banner" in src.lower():
            continue
        candidate = normalize_link(raw_url, src)
        if candidate:
            image_url = candidate
            break
    return {
        "description": description,
        "material_note": material_note,
        "image_url": image_url,
        "raw_fields": {"detail_parser": "ulsan_edu_booking_detail", "detail_text_sample": clean_text(text)[:1000]},
    }


def collect_ulsan_edu_booking(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    pagination_complete = False

    for page in range(1, max_pages + 1):
        response = s.get(
            ULSAN_EDU_BOOKING_LIST_URL,
            params={"type": "Edu", "q_currPage": str(page)},
            verify=True,
            timeout=timeout,
        )
        response.raise_for_status()
        if not response.encoding or response.encoding.lower() == "iso-8859-1":
            response.encoding = response.apparent_encoding
        soup = BeautifulSoup(response.text, "lxml")
        pages += 1
        items = soup.select(".prgr-booking-list ul.list > li.item")
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[onclick*='opMovePage']"))
        page_rows = 0
        for item in items:
            link = item.select_one("a[onclick*='opViewReservation']")
            reservation_id = parse_ulsan_booking_onclick(link.get("onclick") if link else "")
            title = clean_text((item.select_one(".tit_wrap .title") or item).get_text(" ", strip=True))
            if not reservation_id or not title or is_low_value_title(title):
                continue
            pairs = ulsan_booking_info_pairs(item)
            status = clean_text((item.select_one(".tit_wrap .status") or "").get_text(" ", strip=True) if item.select_one(".tit_wrap .status") else "")
            branch = clean_text(pairs.get("기관")) or target.branch
            apply_period = normalize_ulsan_booking_datetime_range(pairs.get("신청기간"))
            period = normalize_ulsan_booking_datetime_range(pairs.get("운영기간"))
            venue = clean_text(pairs.get("장소"))
            raw_url = ULSAN_EDU_BOOKING_DETAIL_URL + "?" + urlencode({"q_rsvtRegSn": reservation_id})
            image = item.select_one("img")
            image_url = normalize_link(ULSAN_EDU_BOOKING_LIST_URL, image.get("src") if image else None)
            row = {
                "provider": target.provider,
                "provider_course_id": reservation_id,
                "title": title,
                "branch": branch,
                "branch_code": branch,
                "category": "평생교육",
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": "",
                "period": period,
                "apply_period": apply_period,
                "schedule_raw": period,
                "target": clean_text(pairs.get("대상") or pairs.get("교육대상") or pairs.get("이용대상")),
                "capacity": clean_text(pairs.get("모집인원")),
                "venue_name": venue,
                "venue_address": venue if re.search(r"\(\d{5}\)|[가-힣]+(?:로|길)\s*\d+", venue) else "",
                "contact": clean_text(pairs.get("문의전화")),
                "application_method_raw": clean_text(pairs.get("접수방법") or pairs.get("신청방법") or pairs.get("접수구분")),
                "image_url": image_url,
                "description": clean_text(item.get_text(" ", strip=True)),
                "domain_category": clean_text(target.extra.get("domain_category") or "평생학습"),
                "collection_category": clean_text(target.extra.get("collection_category") or "평생학습"),
                "source_group": clean_text(target.extra.get("source_group") or "lifelong_learning"),
                "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
                "collection_type": clean_text(target.extra.get("collection_type") or "static_html"),
                "raw_fields": {"parser": "ulsan_edu_booking_list", "pairs": pairs, "reservation_id": reservation_id},
            }
            row.update(ulsan_booking_institution_metadata(branch))
            rows.append(row)
            page_rows += 1
        if page_rows == 0 or not soup.select(f"a[onclick*='opMovePage({page + 1})']"):
            pagination_complete = True
            break

    source_rows = dedupe_rows(rows)
    rows = [row for row in source_rows if not should_skip_expired_course(row)]
    expired_count = len(source_rows) - len(rows)

    detail_pages = 0
    if detail_limit > 0:
        for row in rows[:detail_limit]:
            try:
                detail = collect_ulsan_booking_detail(s, clean_text(row.get("raw_url")), timeout=timeout)
            except Exception as exc:
                logger.debug("ulsan edu booking detail fetch failed %s: %s", row.get("provider_course_id"), exc)
                continue
            detail_raw = detail.pop("raw_fields", {})
            row.setdefault("raw_fields", {}).update(detail_raw)
            for key, value in detail.items():
                if value:
                    row[key] = value
            detail_pages += 1

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_complete,
        "source_total": len(source_rows),
        "expired_count": expired_count,
        "no_current_data": pagination_complete and not rows,
        "no_current_reason": (
            "official catalogue was exhausted and contains no current or future programs"
            if pagination_complete and not rows
            else ""
        ),
        "recursion_depth": 0,
    }
    return rows, "ulsan_edu_booking_list+detail", meta


MOKPO_LIFELONG_LIST_URL = "https://lifelong.mokpo.go.kr/lecture/lecture_list_program.php?me_id=sub222"


def collect_mokpo_lifelong_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_url = target.url
    parsed = urlparse(list_url)
    if parsed.netloc.endswith("lifelong.mokpo.go.kr") and parsed.path in {"", "/"}:
        list_url = MOKPO_LIFELONG_LIST_URL
        parsed = urlparse(list_url)
    base_query = parse_qs(parsed.query)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, .pg_wrap, a[href*='page=']"))

        for tr in soup.select("table tbody tr"):
            cells = tr.find_all("td", recursive=False)
            if len(cells) < 7:
                continue
            texts = [clean_text(cell.get_text(" ", strip=True)) for cell in cells]
            branch = texts[0]
            link = cells[1].find("a", href=True)
            title = clean_text(link.get_text(" ", strip=True) if link else texts[1])
            if not title or is_low_value_title(title):
                continue
            raw_url = urljoin(current_url, link.get("href") if link else "") if link else current_url
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch or "목포시 평생학습포털",
                "category": "평생학습",
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": texts[6],
                "fee": texts[5],
                "period": normalize_mixed_date_range(texts[3]),
                "apply_period": normalize_mixed_date_range(texts[4]),
                "schedule_raw": "",
                "instructor": texts[2],
                "description": clean_text(tr.get_text(" ", strip=True)),
                "domain_category": clean_text(target.extra.get("domain_category") or "평생학습"),
                "collection_category": clean_text(target.extra.get("collection_category") or "평생학습"),
                "source_group": clean_text(target.extra.get("source_group") or "lifelong_learning"),
                "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
                "collection_type": clean_text(target.extra.get("collection_type") or "static_html"),
                "raw_fields": {"parser": "mokpo_lifelong_table_detail", "cells": texts},
            }

            if raw_url and detail_pages < detail_limit:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    pairs = pairs_from_tables(detail_soup)
                    current_capacity, total_capacity = parse_capacity_pair(pairs.get("접수/정원"))
                    detail_title = clean_text(pairs.get("강좌명"))
                    detail_branch = clean_text(pairs.get("교육기관"))
                    row["title"] = detail_title or row["title"]
                    row["branch"] = detail_branch or row["branch"]
                    row["category"] = clean_text(pairs.get("분야") or pairs.get("강의분야")) or row["category"]
                    row["status"] = clean_text(pairs.get("강좌상태")) or row["status"]
                    row["fee"] = clean_text(pairs.get("수강료")) or row["fee"]
                    row["material_fee"] = clean_text(pairs.get("재료비"))
                    row["period"] = normalize_mixed_date_range(pairs.get("교육기간", "")) or row["period"]
                    row["apply_period"] = normalize_mixed_date_range(pairs.get("신청기간", "")) or row["apply_period"]
                    row["schedule_raw"] = clean_text(pairs.get("교육일시")) or row["schedule_raw"]
                    row["target"] = clean_text(pairs.get("교육대상"))
                    row["capacity"] = clean_text(pairs.get("접수/정원"))
                    row["capacity_current"] = current_capacity
                    row["capacity_total"] = total_capacity
                    row["venue_name"] = clean_text(pairs.get("교육장소"))
                    row["contact"] = clean_text(pairs.get("문의"))
                    row["application_method_raw"] = clean_text(pairs.get("신청방법"))
                    row["instructor"] = clean_text(pairs.get("강사명")) or row["instructor"]
                    description = clean_text(" ".join(part for part in [pairs.get("강좌소개"), pairs.get("기타")] if clean_text(part)))
                    row["description"] = description or clean_text(detail_soup.get_text(" ", strip=True))[:1000]
                    row["provider_course_id"] = stable_course_id(target.provider, raw_url, row["title"], row["branch"])
                    row["raw_fields"] = {**row["raw_fields"], "detail_pairs": pairs}
                except Exception as exc:
                    logger.debug("Mokpo lifelong detail fetch failed %s: %s", raw_url, exc)

            rows.append(row)
            page_rows += 1

        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "pagination_detected": pagination_detected or pages > 1,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "mokpo_lifelong_table_detail", meta


def _legacy_collect_yuseong_lifelong_classes(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    page_heading = clean_text((soup.select_one("h2") or soup.select_one("h1") or soup).get_text(" ", strip=True))
    rows: list[dict[str, Any]] = []
    for item in soup.select(".item-inner"):
        title = clean_text((item.select_one(".title") or item).get_text(" ", strip=True))
        if not title or is_low_value_title(title):
            continue
        status_nodes = item.select(".status-wrap .status")
        place_node = item.select_one(".status-wrap .status.place")
        branch = clean_text(place_node.get_text(" ", strip=True)) if place_node else page_heading
        status = ""
        for node in status_nodes:
            if place_node is not None and node is place_node:
                continue
            status = clean_text(node.get_text(" ", strip=True))
            if status:
                break
        if not branch:
            branch = clean_text(target.branch) or "유성구 평생학습센터"
        pairs: dict[str, str] = {}
        for li in item.select(".list-1st li"):
            key = normalize_korean_label((li.select_one(".tit") or li).get_text(" ", strip=True))
            value_node = li.select_one(".txt")
            value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
            if key:
                pairs[key] = value
        key_no = clean_text((item.select_one("a[data-key-no]") or {}).get("data-key-no"))
        group_id = clean_text((item.select_one("a[data-group-id]") or {}).get("data-group-id"))
        raw_query = urlencode({"groupId": group_id, "keyNo": key_no}) if key_no else urlparse(target.url).query
        raw_url = urlparse(target.url)._replace(query=raw_query).geturl()
        capacity_current = parse_capacity_number(pairs.get("접수인원"))
        capacity_total = parse_capacity_number(pairs.get("모집인원"))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": clean_text(pairs.get("수강료")),
                "period": normalize_mixed_date_range(pairs.get("수강기간", "") or pairs.get("교육기간", "")),
                "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
                "schedule_raw": clean_text(pairs.get("요일/시간") or pairs.get("교육시간") or pairs.get("교육일시")),
                "target": clean_text(pairs.get("교육대상")),
                "capacity": capacity_total,
                "capacity_current": capacity_current,
                "application_method_raw": clean_text(pairs.get("접수방법")),
                "contact": clean_text(pairs.get("문의처")),
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"parser": "yuseong_lifelong_classes", "pairs": pairs, "key_no": key_no, "group_id": group_id},
            }
        )
    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": bool(soup.select(".pagination, .paging, .page-item")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "yuseong_lifelong_classes", meta


def collect_dobong_course_boxes(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False
    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["Page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for item in soup.select(".course_box"):
            title_node = item.select_one(".tit_area .tit")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            if not title or is_low_value_title(title):
                continue
            onclick = clean_text(title_node.get("onclick") if title_node else "")
            id_match = re.search(r"goDesc\(['\"]?(\d+)", onclick)
            course_id = id_match.group(1) if id_match else ""
            raw_url = current_url
            if course_id:
                raw_url = parsed._replace(query=urlencode({**base_query, "Idx": [course_id]}, doseq=True)).geturl()
            periods = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".tit_area .period")]
            period_pairs = pairs_from_lines(periods)
            tags = [clean_text(node.get_text(" ", strip=True)).lstrip("#") for node in item.select(".has_tag span")]
            image = item.select_one(".img_area img")
            status = clean_text((item.select_one(".course_btn_area .btn") or item).get_text(" ", strip=True))
            fee = clean_text((item.select_one(".price") or item).get_text(" ", strip=True))
            target_text = next((tag for tag in tags if any(token in tag for token in ("초등", "중등", "고등", "성인", "청소년", "유아"))), "")
            category = next((tag for tag in tags if tag in {"기타", "문화", "체육", "예술", "과학"}), "")
            venue = tags[0] if tags else target.branch
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, venue),
                    "title": title,
                    "branch": venue,
                    "category": category,
                    "raw_url": raw_url,
                    "application_url": raw_url if "마감" not in status else "",
                    "status": status,
                    "fee": fee,
                    "period": normalize_yymmdd_range(period_pairs.get("교육기간", "")),
                    "apply_period": normalize_yymmdd_range(period_pairs.get("접수기간", "")),
                    "schedule_raw": "",
                    "target": target_text,
                    "room": venue,
                    "venue_name": venue,
                    "image_url": normalize_link(current_url, image.get("src") if image else None),
                    "description": clean_text((item.select_one(".info_list .txt") or item).get_text(" ", strip=True)),
                    "raw_fields": {"parser": "dobong_course_boxes", "tags": tags, "course_id": course_id},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination"))
        if page_rows == 0:
            break
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "dobong_course_boxes", meta


DOBONG_INTEGRATED_PROVIDER = "MUNI_YEYAK_DOBONG_GO_KR_C2700A4B"
DOBONG_INTEGRATED_HOST = "yeyak.dobong.go.kr"
DOBONG_INTEGRATED_LIST_PATH = "/recruit/Education.asp"
DOBONG_INTEGRATED_DETAIL_PATH = "/recruit/EducationDesc.asp"
DOBONG_INTEGRATED_LIST_URL = (
    f"https://{DOBONG_INTEGRATED_HOST}{DOBONG_INTEGRATED_LIST_PATH}"
    "?Gnb=GnbTp1&MCode=UMA1001"
)
DOBONG_INTEGRATED_PAGE_SIZE = 100
DOBONG_INTEGRATED_PARSER = "dobong_integrated_current_education+detail"


def is_dobong_integrated_education_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query, keep_blank_values=True)
    return bool(
        target.provider == DOBONG_INTEGRATED_PROVIDER
        and parsed.scheme == "https"
        and parsed.netloc.lower() == DOBONG_INTEGRATED_HOST
        and parsed.path == DOBONG_INTEGRATED_LIST_PATH
        and query.get("Gnb") == ["GnbTp1"]
        and query.get("MCode") == ["UMA1001"]
    )


def dobong_integrated_today() -> date:
    return datetime.now(ZoneInfo("Asia/Seoul")).date()


def dobong_integrated_list_url(page: int) -> str:
    return (
        f"https://{DOBONG_INTEGRATED_HOST}{DOBONG_INTEGRATED_LIST_PATH}?"
        + urlencode(
            {
                "Gnb": "GnbTp1",
                "MCode": "UMA1001",
                "PageSize": str(DOBONG_INTEGRATED_PAGE_SIZE),
                "Page": str(page),
            }
        )
    )


def dobong_integrated_detail_url(detail_id: str) -> str:
    return (
        f"https://{DOBONG_INTEGRATED_HOST}{DOBONG_INTEGRATED_DETAIL_PATH}?"
        + urlencode({"Gnb": "GnbTp1", "Idx": detail_id, "MCode": "UMA1001"})
    )


def dobong_integrated_status(value: Any) -> str:
    source_status = clean_text(value)
    if source_status == "안내중":
        return "SCHEDULED"
    if source_status in {"접수중", "상시접수", "접수가능"}:
        return "OPEN"
    if source_status in {"대기접수", "대기신청"}:
        return "WAITING"
    if any(token in source_status for token in ("마감", "종료", "폐강", "취소")):
        return "CLOSED"
    return normalize_status(source_status) or source_status


def dobong_integrated_fee(value: Any, description: Any = "") -> str:
    text = clean_text(value)
    detail_text = clean_text(description)
    if "무료" in text or "전액 무료" in detail_text:
        return "무료"
    match = re.search(r"(\d[\d,]*)\s*원", text)
    if match:
        return f"{int(match.group(1).replace(',', '')):,}원"
    return text


def dobong_integrated_capacity(value: Any) -> tuple[Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value)
    match = re.search(r"정원\s*:\s*\(\s*(\d[\d,]*)\s*/\s*(\d[\d,]*)\s*명?\s*가능", text)
    if not match:
        return None, None, None
    total = int(match.group(1).replace(",", ""))
    remaining = int(match.group(2).replace(",", ""))
    return max(0, total - remaining), total, remaining


def dobong_integrated_location_parts(value: Any) -> tuple[str, str]:
    text = clean_text(value).replace("\xa0", " ")
    if "/" not in text:
        return "", text
    area, venue = text.split("/", 1)
    return clean_text(area), clean_text(venue)


def dobong_integrated_branch(agency: Any, location: Any, fallback: str) -> str:
    agency_text = clean_text(agency)
    area, _venue = dobong_integrated_location_parts(location)
    if agency_text == "자치회관" and area:
        return f"{area} 자치회관"
    if agency_text == "교육포털":
        return "도봉구 교육포털"
    return agency_text or area or clean_text(fallback) or "도봉구 통합예약"


def dobong_integrated_description_value(description: Any, label: str) -> str:
    text = clean_text(description)
    if not text:
        return ""
    label_pattern = r"\s*".join(re.escape(character) for character in label if not character.isspace())
    match = re.search(
        rf"{label_pattern}\s*[:：]\s*(.*?)(?=\s*○\s*[가-힣A-Za-z0-9()·/\s]{{1,40}}\s*[:：]|$)",
        text,
        re.DOTALL,
    )
    return clean_text(match.group(1)) if match else ""


def dobong_integrated_external_detail(soup: BeautifulSoup) -> dict[str, Any]:
    pairs = pairs_from_tables(soup)
    description = clean_text(pairs.get("설명"))
    venue = dobong_integrated_description_value(description, "위치")
    target_text = dobong_integrated_description_value(description, "교육대상")
    schedule_raw = dobong_integrated_description_value(description, "교육시간")
    capacity_text = dobong_integrated_description_value(description, "인원")
    application_method = dobong_integrated_description_value(description, "접수방법")
    contact = dobong_integrated_description_value(description, "문의")
    capacity_total = parse_capacity_number(capacity_text)
    return {
        "title": clean_text(pairs.get("예약명")),
        "schedule_raw": schedule_raw,
        "target": target_text,
        "capacity": capacity_text,
        "capacity_total": capacity_total,
        "room": venue,
        "venue_name": venue,
        "fee": dobong_integrated_fee("", description),
        "application_method_raw": application_method,
        "phone": contact,
        "description": description,
        "raw_fields": {"external_detail_pairs": pairs},
    }


def dobong_integrated_native_detail(soup: BeautifulSoup, fallback_agency: str) -> dict[str, Any]:
    pairs = pairs_from_tables(soup)
    source_status = clean_text(pairs.get("상태"))
    period = normalize_yymmdd_range(pairs.get("진행기간", ""))
    apply_period = normalize_yymmdd_range(pairs.get("접수기간", ""))
    start_date, end_date = parse_date_range(period)
    apply_start, apply_end = parse_date_range(apply_period)
    location = clean_text(pairs.get("지역/장소"))
    _area, venue = dobong_integrated_location_parts(location)
    agency = clean_text(pairs.get("기관명")) or fallback_agency
    capacity_current, capacity_total, capacity_remaining = dobong_integrated_capacity(
        pairs.get("수강인원")
    )
    description_node = soup.select_one(".view_contents")
    description = clean_text(
        description_node.get_text(" ", strip=True) if description_node else ""
    )
    return {
        "title": clean_text(pairs.get("모집접수명")),
        "branch": dobong_integrated_branch(agency, location, agency),
        "category": clean_text(pairs.get("카테고리")),
        "status": dobong_integrated_status(source_status),
        "period": period,
        "apply_period": apply_period,
        "start_date": start_date,
        "end_date": end_date,
        "apply_start": apply_start,
        "apply_end": apply_end,
        "schedule_raw": clean_text(pairs.get("강의시간")),
        "target": clean_text(pairs.get("교육대상")),
        "capacity": clean_text(pairs.get("수강인원")),
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "capacity_remaining": capacity_remaining,
        "selection_method": clean_text(pairs.get("선정방식")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "fee": dobong_integrated_fee(pairs.get("수강료"), description),
        "material_fee": extract_material_fee_amount(description),
        "room": venue,
        "venue_name": venue,
        "phone": clean_text(pairs.get("문의")),
        "provider_organizer": agency,
        "description": description,
        "raw_fields": {
            "native_detail_pairs": pairs,
            "detail_source_status": source_status,
        },
    }


def dobong_integrated_page_rows(
    target: CrawlTarget,
    page_url: str,
    soup: BeautifulSoup,
) -> tuple[list[dict[str, Any]], list[str]]:
    rows: list[dict[str, Any]] = []
    errors: list[str] = []
    table_rows = soup.select("table tbody tr")
    index = 0
    while index < len(table_rows):
        tr = table_rows[index]
        cells = tr.find_all("td", recursive=False)
        if len(cells) < 8:
            index += 1
            continue
        values = [clean_text(cell.get_text(" ", strip=True)) for cell in cells]
        list_id = values[0]
        period_text = ""
        if index + 1 < len(table_rows):
            period_cells = table_rows[index + 1].find_all("td", recursive=False)
            if len(period_cells) == 1:
                period_text = clean_text(period_cells[0].get_text(" ", strip=True))
                index += 1
        index += 1

        title_link = cells[3].find("a") or tr.find("a")
        title = clean_text(cells[3].get_text(" ", strip=True))
        if not list_id.isdigit() or not title or is_low_value_title(title) or not title_link:
            errors.append(f"invalid list row id={list_id or 'missing'}")
            continue
        onclick = clean_text(title_link.get("onclick"))
        arguments = re.findall(r"'([^']*)'", onclick)
        link_type = ""
        record_id = ""
        detail_source_url = ""
        if onclick.startswith("goDesc(") and arguments:
            link_type = "native"
            record_id = clean_text(arguments[0])
            detail_source_url = dobong_integrated_detail_url(record_id)
        elif onclick.startswith("goLinkAjax(") and len(arguments) >= 2:
            link_type = "linked_external"
            detail_source_url = normalize_link(page_url, arguments[0])
            record_id = clean_text(arguments[1])
        if not record_id or not detail_source_url:
            errors.append(f"unsupported detail action list_id={list_id}")
            continue

        agency = clean_text(values[2])
        list_venue = clean_text(values[4])
        source_status = clean_text(values[6])
        status = dobong_integrated_status(source_status)
        period = normalize_yymmdd_range(period_text)
        apply_period = normalize_yymmdd_range(values[5])
        start_date, end_date = parse_date_range(period)
        apply_start, apply_end = parse_date_range(apply_period)
        branch = dobong_integrated_branch(agency, "", target.branch)
        raw_url = detail_source_url
        if link_type == "linked_external":
            raw_url = stable_list_item_url(
                detail_source_url,
                target.provider,
                title,
                branch,
                record_id,
            )
        raw_fields: dict[str, Any] = {
            "parser": DOBONG_INTEGRATED_PARSER,
            "list_id": list_id,
            "record_id": record_id,
            "link_type": link_type,
            "detail_source_url": detail_source_url,
            "list_source_status": source_status,
            "list_cells": values,
            "list_period": period_text,
            "page_url": page_url,
        }
        reservation_available = status in {"OPEN", "WAITING"}
        if not reservation_available:
            raw_fields["clear_application_url"] = True
        row: dict[str, Any] = {
            "provider": target.provider,
            "provider_course_id": f"{target.provider}:education:{record_id}"[:100],
            "prefer_incoming_provider_course_id": True,
            "title": title,
            "branch": branch,
            "branch_code": stable_provider(target.provider[:32], branch),
            "preserve_branch": True,
            "branch_url": target.url,
            "category": clean_text(values[1]),
            "raw_url": raw_url,
            "status": status,
            "period": period,
            "apply_period": apply_period,
            "start_date": start_date,
            "end_date": end_date,
            "apply_start": apply_start,
            "apply_end": apply_end,
            "application_method_raw": clean_text(values[7]),
            "room": list_venue,
            "venue_name": list_venue,
            "provider_organizer": agency,
            "reservation_available": reservation_available,
            "application_type": "ONLINE_RESERVATION" if reservation_available else "INFO_ONLY",
            "description": clean_text(tr.get_text(" ", strip=True)),
            "collection_category": clean_text(
                target.extra.get("collection_category") or "공공예약"
            ),
            "domain_category": clean_text(target.extra.get("domain_category") or "교육·강좌"),
            "operator_type": clean_text(
                target.extra.get("operator_type") or "지자체/공공기관"
            ),
            "source_group": clean_text(target.extra.get("source_group") or "municipal_reservation"),
            "service_group": "공공강좌",
            "service_group_policy": "locked",
            "municipality_code": clean_text(target.extra.get("municipality_code") or "1132000000"),
            "municipality_full_name": clean_text(
                target.extra.get("municipality_full_name") or "서울특별시 도봉구"
            ),
            "program_type": "강좌",
            "raw_fields": raw_fields,
        }
        if reservation_available:
            row["application_url"] = detail_source_url
        rows.append(row)
    return rows, errors


def collect_dobong_integrated_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if not is_dobong_integrated_education_target(target):
        raise ValueError("Dobong integrated education target must use the canonical HTTPS list")
    s = session()
    candidates: list[dict[str, Any]] = []
    errors: list[str] = []
    seen_record_ids: set[str] = set()
    seen_list_ids: set[str] = set()
    page_signatures: set[tuple[str, ...]] = set()
    declared_total = 0
    declared_pages = 0
    pages = 0
    pagination_exhausted = False

    for page in range(1, max(1, max_pages) + 1):
        page_url = dobong_integrated_list_url(page)
        soup = fetch_soup(s, page_url, timeout=timeout)
        page_rows, page_errors = dobong_integrated_page_rows(target, page_url, soup)
        pages += 1
        errors.extend(page_errors)
        signature = tuple(clean_text((row.get("raw_fields") or {}).get("list_id")) for row in page_rows)
        if page == 1:
            declared_total = int(signature[0]) if signature and signature[0].isdigit() else 0
            declared_pages = (
                max(1, (declared_total + DOBONG_INTEGRATED_PAGE_SIZE - 1) // DOBONG_INTEGRATED_PAGE_SIZE)
                if declared_total
                else 1
            )
        if not signature:
            if declared_total:
                errors.append(f"page {page} returned no education rows before declared terminal page")
            else:
                pagination_exhausted = True
            break
        if signature in page_signatures:
            errors.append(f"page {page} repeated an earlier list signature")
            break
        page_signatures.add(signature)
        for row in page_rows:
            raw_fields = row.get("raw_fields") or {}
            list_id = clean_text(raw_fields.get("list_id"))
            record_id = clean_text(raw_fields.get("record_id"))
            if list_id in seen_list_ids:
                errors.append(f"duplicate list id {list_id}")
                continue
            if record_id in seen_record_ids:
                errors.append(f"duplicate education record id {record_id}")
                continue
            seen_list_ids.add(list_id)
            seen_record_ids.add(record_id)
            candidates.append(row)
        if declared_pages and page >= declared_pages:
            pagination_exhausted = True
            break

    list_complete = bool(
        pagination_exhausted
        and declared_total >= 0
        and len(seen_list_ids) == declared_total
        and not errors
    )
    if declared_pages and pages < declared_pages:
        errors.append(f"max_pages cap reached after {pages} of {declared_pages} declared pages")
    if declared_total and len(seen_list_ids) != declared_total:
        errors.append(f"parsed {len(seen_list_ids)} of {declared_total} declared education rows")

    current_rows: list[dict[str, Any]] = []
    expired_count = 0
    unknown_period_count = 0
    today = dobong_integrated_today()
    for row in candidates:
        if row.get("end_date") is None:
            unknown_period_count += 1
        if row.get("end_date") is not None and row["end_date"] < today:
            expired_count += 1
            continue
        current_rows.append(row)

    detail_sources: dict[str, str] = {}
    for row in current_rows:
        raw_fields = row.get("raw_fields") or {}
        detail_source_url = clean_text(raw_fields.get("detail_source_url"))
        link_type = clean_text(raw_fields.get("link_type"))
        if detail_source_url:
            detail_sources.setdefault(detail_source_url, link_type)
    detail_cap = max(0, detail_limit)
    detail_enrichment_capped = list_complete and detail_cap < len(detail_sources)
    if detail_enrichment_capped:
        errors.append(f"detail_limit cap reached at {detail_cap} of {len(detail_sources)} unique details")
    detail_cache: dict[str, dict[str, Any]] = {}
    detail_errors: list[str] = []
    for detail_source_url, link_type in list(detail_sources.items())[:detail_cap]:
        try:
            detail_soup = fetch_soup(s, detail_source_url, timeout=timeout)
            detail_cache[detail_source_url] = (
                dobong_integrated_external_detail(detail_soup)
                if link_type == "linked_external"
                else dobong_integrated_native_detail(detail_soup, "")
            )
        except Exception as exc:
            detail_errors.append(detail_source_url)
            logger.debug(
                "Dobong integrated detail fetch failed %s: %s",
                safe_url_for_log(detail_source_url),
                type(exc).__name__,
            )
    if detail_errors:
        errors.append(f"detail fetch failed for {len(detail_errors)} unique details")

    rows: list[dict[str, Any]] = []
    detail_expired_count = 0
    for row in current_rows:
        raw_fields = row.get("raw_fields") or {}
        detail_source_url = clean_text(raw_fields.get("detail_source_url"))
        detail = detail_cache.get(detail_source_url, {})
        if detail:
            for key, value in detail.items():
                if value in (None, "", [], {}):
                    continue
                if key == "raw_fields" and isinstance(value, dict):
                    row["raw_fields"] = {**raw_fields, **value}
                    continue
                if key == "title" and not is_low_value_title(row.get("title")):
                    continue
                row[key] = value
        branch = clean_text(row.get("branch")) or target.branch
        row["branch"] = branch
        row["branch_code"] = stable_provider(target.provider[:32], branch)
        period = clean_text(row.get("period"))
        apply_period = clean_text(row.get("apply_period"))
        if period:
            row["start_date"], row["end_date"] = parse_date_range(period)
        if apply_period:
            row["apply_start"], row["apply_end"] = parse_date_range(apply_period)
        if row.get("end_date") is not None and row["end_date"] < today:
            detail_expired_count += 1
            continue
        status = clean_text(row.get("status"))
        reservation_available = status in {"OPEN", "WAITING"}
        row["reservation_available"] = reservation_available
        if reservation_available:
            row["application_url"] = detail_source_url
            row["application_type"] = "ONLINE_RESERVATION"
            row.setdefault("raw_fields", {}).pop("clear_application_url", None)
        else:
            row.pop("application_url", None)
            row["application_type"] = "INFO_ONLY"
            row.setdefault("raw_fields", {})["clear_application_url"] = True
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

    rows = dedupe_rows(rows)
    if len(rows) != len(current_rows) - detail_expired_count:
        errors.append("current education dedupe changed the expected row count")
    details_complete = bool(
        list_complete
        and not detail_enrichment_capped
        and not detail_errors
        and len(detail_cache) == len(detail_sources)
    )
    snapshot_complete = bool(list_complete and details_complete and not errors)
    no_current_data = snapshot_complete and not rows
    status_counts = dict(Counter(clean_text(row.get("status")) for row in rows))
    branch_counts = dict(Counter(clean_text(row.get("branch")) for row in rows))
    linked_external_count = sum(
        1
        for row in rows
        if clean_text((row.get("raw_fields") or {}).get("link_type")) == "linked_external"
    )
    meta: dict[str, Any] = {
        "pages": pages,
        "declared_pages": declared_pages,
        "declared_total": declared_total,
        "detail_pages": len(detail_cache),
        "detail_attempts": min(detail_cap, len(detail_sources)),
        "detail_candidates": len(detail_sources),
        "detail_errors": len(detail_errors),
        "detail_error_urls": detail_errors,
        "detail_enrichment_capped": detail_enrichment_capped,
        "details_complete": details_complete,
        "discovered_links": len(seen_list_ids),
        "reservation_discovery_links": sum(
            1 for row in rows if clean_text(row.get("application_url"))
        ),
        "reservation_fallback_pages": 0,
        "pagination_detected": declared_pages > 1,
        "pagination_complete": list_complete,
        "pagination_exhausted": pagination_exhausted,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": bool(
            (declared_pages and pages < declared_pages) or detail_enrichment_capped
        ),
        "recursion_depth": 0,
        "expired_count": expired_count + detail_expired_count,
        "unknown_period_count": unknown_period_count,
        "current_count": len(rows),
        "status_counts": status_counts,
        "branch_counts": branch_counts,
        "linked_external_count": linked_external_count,
        "linked_external_unique_details": sum(
            1 for link_type in detail_sources.values() if link_type == "linked_external"
        ),
        "native_count": len(rows) - linked_external_count,
        "no_current_data": no_current_data,
        "no_current_reason": "all declared education rows are expired" if no_current_data else "",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return rows, DOBONG_INTEGRATED_PARSER, meta


def collect_sd_booking_programs(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    list_url = target.url
    if "webExcursionsProgramList.do" not in list_url:
        list_url = "https://www.sd.go.kr/booking/webExcursionsProgramList.do?key=4836"
    soup = fetch_soup(s, list_url, timeout=timeout)

    for tr in soup.select("table tbody tr"):
        cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
        if len(cells) < 10 or not cells[0].isdigit():
            continue
        title = cells[2]
        if not title or is_low_value_title(title):
            continue
        link = tr.find("a", href=True)
        raw_url = normalize_link(list_url, link.get("href") if link else None) or list_url
        row: dict[str, Any] = {
            "provider": target.provider,
            "provider_course_id": stable_course_id(target.provider, raw_url, title, cells[4]),
            "title": title,
            "branch": cells[4],
            "category": "체험견학",
            "raw_url": raw_url,
            "application_url": raw_url,
            "status": cells[9],
            "fee": cells[6],
            "period": "",
            "apply_period": "",
            "schedule_raw": "",
            "target": cells[5],
            "capacity": cells[7],
            "application_method_raw": cells[8],
            "description": clean_text(tr.get_text(" ", strip=True)),
            "raw_fields": {"cells": cells, "parser": "sd_booking_programs"},
        }
        if raw_url and detail_pages < 30:
            try:
                detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                detail_pages += 1
                pairs = pairs_from_tables(detail_soup)
                row["branch"] = clean_text(pairs.get("장소") or pairs.get("운영기관")) or row["branch"]
                row["target"] = clean_text(pairs.get("대상")) or row["target"]
                row["period"] = normalize_mixed_date_range(pairs.get("운영기간", ""))
                row["apply_period"] = normalize_mixed_date_range(pairs.get("접수기간", ""))
                row["schedule_raw"] = clean_text(" ".join(part for part in [pairs.get("운영요일"), pairs.get("운영시간")] if part))
                row["capacity"] = clean_text(pairs.get("모집인원(회차별)")) or row["capacity"]
                row["fee"] = clean_text(pairs.get("이용요금")) or row["fee"]
                row["material_fee"] = clean_text(pairs.get("재료비/교재비"))
                row["description"] = clean_text(pairs.get("예약방법") or detail_soup.get_text(" ", strip=True))[:1000]
            except Exception as exc:
                logger.debug("Seongdong booking detail fetch failed %s: %s", raw_url, exc)
        rows.append(row)

    meta = {
        "pages": 1,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": bool(soup.select(".pagination, .paging")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "sd_booking_programs", meta


def sd_booking_edu_ranges(text: str) -> tuple[str, str]:
    dates = re.findall(r"\d{4}[-.]\d{1,2}[-.]\d{1,2}", clean_text(text))
    normalized = [date.replace(".", "-") for date in dates]
    if len(normalized) >= 4:
        return f"{normalized[0]} ~ {normalized[1]}", f"{normalized[2]} ~ {normalized[3]}"
    if len(normalized) >= 2:
        return f"{normalized[0]} ~ {normalized[1]}", ""
    return "", ""


def collect_sd_booking_edu_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pages = 0
    pagination_detected = False
    list_url = target.url
    if "webEduList" not in list_url:
        list_url = "https://www.sd.go.kr/booking/webEduList2.do?key=4916"
    parsed = urlparse(list_url)
    base_query = parse_qs(parsed.query)

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, .p-pagination"))
        for tr in soup.select("table.p-table tbody tr"):
            cells = tr.find_all("td", recursive=False)
            if len(cells) < 7:
                continue
            number = clean_text(cells[0].get_text(" ", strip=True))
            if not number.isdigit():
                continue
            link = cells[1].find("a", href=True)
            title = clean_text(link.get_text(" ", strip=True) if link else cells[1].get_text(" ", strip=True))
            if not title or is_low_value_title(title):
                continue
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            apply_period, period = sd_booking_edu_ranges(cells[2].get_text(" ", strip=True))
            venue = clean_text(cells[3].get_text(" ", strip=True))
            target_text = clean_text(cells[4].get_text(" ", strip=True))
            capacity = clean_text(cells[5].get_text(" ", strip=True))
            status = clean_text(cells[6].get_text(" ", strip=True))
            current_capacity, total_capacity = parse_capacity_pair(capacity)
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, venue or target.branch),
                "title": title,
                "branch": target.branch or "성동구 평생학습관",
                "category": "평생교육",
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": "",
                "period": period,
                "apply_period": apply_period,
                "schedule_raw": "",
                "target": target_text,
                "capacity": capacity,
                "capacity_current": current_capacity,
                "capacity_total": total_capacity,
                "venue_name": venue,
                "description": clean_text(tr.get_text(" ", strip=True)),
                "raw_fields": {"cells": [clean_text(cell.get_text(" ", strip=True)) for cell in cells], "parser": "sd_booking_edu_list_detail"},
            }
            if raw_url and detail_pages < detail_limit:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    pairs = pairs_from_tables(detail_soup)
                    row["branch"] = clean_text(pairs.get("운영기관")) or row["branch"]
                    row["target"] = clean_text(pairs.get("대상")) or row["target"]
                    row["venue_name"] = clean_text(pairs.get("장소")) or row["venue_name"]
                    row["venue_address"] = clean_text(pairs.get("주소"))
                    row["period"] = normalize_mixed_date_range(pairs.get("운영기간", "")) or row["period"]
                    row["apply_period"] = normalize_mixed_date_range(pairs.get("접수기간", "")) or row["apply_period"]
                    row["schedule_raw"] = clean_text(" ".join(part for part in [pairs.get("운영요일"), pairs.get("운영시간")] if part))
                    row["capacity"] = clean_text(pairs.get("모집인원")) or row["capacity"]
                    row["waitlist_capacity"] = clean_text(pairs.get("대기모집인원"))
                    row["fee"] = clean_text(pairs.get("이용요금")) or row["fee"]
                    row["material_fee"] = clean_text(pairs.get("재료비/교재비"))
                    row["application_method_raw"] = clean_text(pairs.get("예약방법"))
                    row["contact"] = clean_text(pairs.get("문의전화"))
                    row["description"] = clean_text(" ".join(part for part in [pairs.get("선별방법"), pairs.get("예약방법"), pairs.get("문의전화")] if part))
                    row["raw_fields"] = {**row["raw_fields"], "detail_pairs": pairs}
                except Exception as exc:
                    logger.debug("Seongdong edu detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected or pages > 1,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "sd_booking_edu_list_detail", meta


def chungju_reserve_categories(base_url: str, soup: BeautifulSoup) -> list[tuple[str, str]]:
    categories: list[tuple[str, str]] = []
    for link in soup.select(".modules_lecture .category a[href*='document_category_srl']"):
        name = clean_text(link.get_text(" ", strip=True))
        if not name or name == "전체보기":
            continue
        url = normalize_link(base_url, link.get("href"))
        if url:
            categories.append((name, url))
    return categories


def chungju_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs = pairs_from_tables(soup)
    return {clean_text(key).replace(" ", ""): clean_text(value) for key, value in pairs.items()}


def collect_chungju_reserve_lecture(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 20,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    first_soup = fetch_soup(s, target.url, timeout=timeout)
    category_urls = chungju_reserve_categories(target.url, first_soup) or [(target.branch, target.url)]
    pages = 0
    detail_pages = 0
    discovered_links = 0
    pagination_detected = False

    for category_name, category_url in category_urls:
        parsed = urlparse(category_url)
        base_query = parse_qs(parsed.query)
        for page in range(1, max(1, max_pages) + 1):
            query = dict(base_query)
            query["page"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
            soup = fetch_soup(s, current_url, timeout=timeout)
            pages += 1
            page_rows = 0
            for item in soup.select(".modules_lecture .list > ul > li"):
                link = item.find("a", href=True)
                list_pairs = pairs_from_definition_lists(item)
                title = clean_text(list_pairs.get("제목"))
                if not title or is_low_value_title(title):
                    continue
                raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
                discovered_links += 1

                detail_pairs: dict[str, str] = {}
                detail_text = ""
                if detail_pages < max(0, detail_limit):
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        detail_pairs = chungju_detail_pairs(detail_soup)
                        detail_root = detail_soup.select_one(".modules_lecture")
                        detail_text = clean_text((detail_root or detail_soup).get_text(" ", strip=True))
                    except Exception as exc:
                        logger.debug("Chungju detail fetch failed %s: %s", raw_url, exc)

                branch = clean_text(detail_pairs.get("\uC6B4\uC601\uAE30\uAD00") or list_pairs.get("기관") or category_name or target.branch)
                period = normalize_mixed_date_range(clean_text(detail_pairs.get("교육기간") or list_pairs.get("교육 기간") or list_pairs.get("교육기간")))
                if period and should_skip_expired_course({"period": period}):
                    continue
                apply_period = normalize_mixed_date_range(clean_text(detail_pairs.get("접수기간") or list_pairs.get("접수기간")))
                weekday = clean_text(detail_pairs.get("교육요일"))
                class_time = clean_text(detail_pairs.get("수업시간"))
                schedule_raw = clean_text(" / ".join(part for part in [period, weekday, class_time] if part))
                age = clean_text(detail_pairs.get("모집연령"))
                priority_target = clean_text(detail_pairs.get("우선접수대상"))
                target_text = clean_text(" · ".join(part for part in [priority_target, age] if part)) or clean_text(list_pairs.get("대상"))
                status = clean_text(detail_pairs.get("접수여부") or list_pairs.get("접수여부") or list_pairs.get("상태"))

                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                        "title": title,
                        "branch": branch,
                        "branch_code": branch,
                        "preserve_branch": True,
                        "category": "주민자치센터강좌",
                        "category_raw": category_name,
                        "collection_category": "공공예약",
                        "domain_category": "공공예약",
                        "source_group": "public_reservation",
                        "operator_type": "지자체/공공기관",
                        "collection_type": "static_html",
                        "raw_url": raw_url,
                        "application_url": raw_url,
                        "status": status,
                        "fee": clean_text(detail_pairs.get("\uC218\uAC15\uB8CC") or list_pairs.get("\uC218\uAC15\uB8CC")),
                        "period": period,
                        "apply_period": apply_period,
                        "schedule_raw": schedule_raw,
                        "target": target_text,
                        "eligibility_raw": target_text,
                        "capacity": clean_text(detail_pairs.get("정원") or list_pairs.get("정원") or list_pairs.get("모집")),
                        "capacity_current": clean_text(list_pairs.get("신청자수") or list_pairs.get("접수인원")),
                        "instructor": clean_instructor_name(detail_pairs.get("\uAC15\uC0AC\uBA85")),
                        "room": clean_text(detail_pairs.get("교육실")),
                        "venue_name": clean_text(detail_pairs.get("\uC7A5\uC18C")) or branch,
                        "address": clean_text(detail_pairs.get("교육장주소")),
                        "venue_address": clean_text(detail_pairs.get("교육장주소")),
                        "contact": clean_text(detail_pairs.get("문의연락처")),
                        "application_method_raw": clean_text(detail_pairs.get("\uC811\uC218\uBC29\uBC95") or list_pairs.get("\uC811\uC218\uBC29\uBC95")),
                        "description": detail_text or clean_text(item.get_text(" ", strip=True)),
                        "reservation_available": "접수" in status and "마감" not in status,
                        "raw_fields": {"list_pairs": list_pairs, "detail_pairs": detail_pairs, "category": category_name, "parser": "chungju_reserve_category+detail"},
                    }
                )
                page_rows += 1
            pagination_detected = pagination_detected or bool(soup.select(".pagejump, .pagination, .paging"))
            if page_rows == 0:
                break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": discovered_links,
        "reservation_discovery_links": discovered_links,
        "reservation_fallback_pages": 0,
        "discovered_categories": len(category_urls),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "chungju_reserve_category+detail", meta


SEOCHEON_LIFE_LIST_URL = "https://www.seocheon.go.kr/prog/lctr/life/sub03_01/list.do"


def seocheon_life_pairs(item: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(item, "select"):
        return pairs
    for li in item.select(".c-info-list li"):
        key = clean_text((li.select_one(".subjact") or li.find("strong") or li).get_text(" ", strip=True))
        value = clean_text((li.select_one(".con") or li).get_text(" ", strip=True))
        if key and value:
            pairs[key] = value
    return pairs


def seocheon_life_view_url(base_url: str, lctr_sn: str) -> str:
    parsed = urlparse(base_url)
    return parsed._replace(path="/prog/lctr/life/sub03_01/view.do", query=urlencode({"lctrSn": lctr_sn})).geturl()


def seocheon_life_card_row(target: CrawlTarget, current_url: str, item: Any) -> dict[str, Any] | None:
    link = item.select_one("a[href*='fn_search_view']") if hasattr(item, "select_one") else None
    href = clean_text(link.get("href") if link else "")
    match = re.search(r"fn_search_view\(['\"]?(\d+)", href)
    lctr_sn = match.group(1) if match else ""
    title = clean_text((item.select_one(".c-tit .span") or item.select_one(".c-tit") or item).get_text(" ", strip=True))
    if not lctr_sn or not title or is_low_value_title(title):
        return None
    pairs = seocheon_life_pairs(item)
    badges = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".card-top .pe-badge")]
    status = next((badge for badge in badges if badge in {"모집중", "대기접수", "접수마감", "교육중", "종료"}), "")
    target_text = badges[0] if badges else clean_text(pairs.get("교육대상"))
    category = clean_text(pairs.get("강좌구분") or (badges[1] if len(badges) > 1 else ""))
    raw_url = seocheon_life_view_url(current_url, lctr_sn)
    capacity = clean_text(pairs.get("신청/모집인원(명)") or pairs.get("최대정원"))
    capacity_current, capacity_total = parse_capacity_pair(capacity)
    waitlist_match = re.search(r"대기\s*(\d+)\s*/\s*(\d+)", capacity)
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
        "title": title,
        "branch": "서천군 평생학습포털",
        "branch_code": "SEOCHEON_LIFE",
        "category": category,
        "raw_url": raw_url,
        "application_url": raw_url if status == "모집중" else "",
        "status": status,
        "fee": "",
        "period": clean_text(pairs.get("교육기간")),
        "apply_period": clean_text(pairs.get("접수기간")),
        "schedule_raw": "",
        "target": target_text,
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_current": int(waitlist_match.group(1)) if waitlist_match else None,
        "waitlist_total": int(waitlist_match.group(2)) if waitlist_match else None,
        "instructor": clean_instructor_name(pairs.get("강사명")),
        "description": clean_text(item.get_text(" ", strip=True)),
        "raw_fields": {"pairs": pairs, "badges": badges, "lctrSn": lctr_sn, "parser": "seocheon_life_lctr_card"},
    }


def enrich_seocheon_life_detail(row: dict[str, Any], detail_soup: BeautifulSoup) -> None:
    pairs = pairs_from_tables(detail_soup)
    if not pairs:
        return
    row["title"] = clean_text(pairs.get("강좌명") or row.get("title"))
    row["category"] = clean_text(pairs.get("강좌구분") or pairs.get("강좌분야") or row.get("category"))
    row["target"] = clean_text(pairs.get("교육대상") or row.get("target"))
    row["apply_period"] = clean_text(pairs.get("접수기간") or row.get("apply_period"))
    row["period"] = clean_text(pairs.get("교육기간") or row.get("period"))
    row["schedule_raw"] = clean_text(pairs.get("교육일정") or pairs.get("교육요일") or row.get("schedule_raw"))
    row["capacity_total"] = parse_capacity_number(pairs.get("최대모집인원(명)")) or row.get("capacity_total")
    row["instructor"] = clean_instructor_name(pairs.get("강사명")) or row.get("instructor")
    row["room"] = clean_text(pairs.get("교육장소명") or row.get("room"))
    row["venue_name"] = clean_text(pairs.get("교육장소명") or row.get("venue_name"))
    row["branch"] = clean_text(pairs.get("교육기관명") or row.get("branch"))
    row["fee"] = clean_text(pairs.get("수업료(원)") or row.get("fee"))
    row["phone"] = clean_text(pairs.get("문의처") or row.get("phone"))
    row["description"] = clean_text(pairs.get("강좌내용") or row.get("description"))
    raw_fields = row.setdefault("raw_fields", {})
    if isinstance(raw_fields, dict):
        raw_fields["detail_pairs"] = pairs


def collect_seocheon_life_lctr(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False

    for page in range(1, max(1, max_pages) + 1):
        current_url = url_with_query(target.url, {"pageIndex": page})
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for item in soup.select(".pe-structured-list .structured-item"):
            row = seocheon_life_card_row(target, current_url, item)
            if not row:
                continue
            raw_url = clean_text(row.get("raw_url"))
            if raw_url and detail_pages < detail_limit:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    enrich_seocheon_life_detail(row, detail_soup)
                except Exception as exc:
                    logger.debug("Seocheon life detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='pageIndex=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "seocheon_life_lctr_card+detail", meta


def collect_gongju_nurim_courses(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    list_url = target.url
    if "/prog/nurimLeaEducate/" not in list_url:
        list_url = "https://www.gongju.go.kr/prog/nurimLeaEducate/E01/nurim/sub03_01/list.do"
    parsed = urlparse(list_url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for link in soup.select("a[href*='view.do'][href*='eduNo=']"):
            raw_url = normalize_link(current_url, link.get("href")) or current_url
            title = ""
            status = ""
            item_text = clean_text(link.get_text(" ", strip=True))
            if item_text:
                status_match = re.match(r"(접수\w+|신청\w+|마감\w*)\s+", item_text)
                status = clean_text(status_match.group(1)) if status_match else ""
            try:
                detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                detail_pages += 1
                pairs = pairs_from_tables(detail_soup)
                detail_text = clean_text(detail_soup.get_text(" ", strip=True))
            except Exception as exc:
                logger.debug("Gongju detail fetch failed %s: %s", raw_url, exc)
                pairs = {}
                detail_text = ""
            title = clean_text(pairs.get("강좌명")) or item_text[:120]
            if not title or is_low_value_title(title):
                continue
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, pairs.get("교육기관") or target.branch),
                    "title": title,
                    "branch": clean_text(pairs.get("교육기관")) or target.branch,
                    "category": clean_text(pairs.get("\uAD50\uC721\uACFC\uC815")),
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": clean_text(pairs.get("수강료")),
                    "period": normalize_mixed_date_range(pairs.get("수강기간", "") or pairs.get("교육기간", "")),
                    "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "") or pairs.get("접수기간", "")),
                    "schedule_raw": clean_text(pairs.get("요일/시간") or pairs.get("교육시간")),
                    "target": clean_text(pairs.get("교육대상")),
                    "room": clean_text(pairs.get("교육장소")),
                    "venue_name": clean_text(pairs.get("교육장소")),
                    "instructor": clean_text(pairs.get("\uAC15\uC0AC\uBA85")),
                    "description": clean_text(pairs.get("교육내용") or detail_text or item_text),
                    "raw_fields": {"pairs": pairs, "parser": "gongju_nurim_courses"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, .page"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gongju_nurim_courses", meta


def collect_jntle_damoa(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        path = re.sub(r"/uDamoaLecture/\d+", f"/uDamoaLecture/{page}", parsed.path)
        current_url = parsed._replace(path=path, query=urlencode(base_query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for item in soup.select(".cardBox li.row-3"):
            title = clean_text((item.select_one(".tit") or item.find("h3")).get_text(" ", strip=True) if (item.select_one(".tit") or item.find("h3")) else "")
            if not title or is_low_value_title(title):
                continue
            pairs: dict[str, str] = {}
            for li in item.select(".info_list li"):
                span = li.find("span")
                key = clean_text(span.get_text(" ", strip=True)) if span else ""
                if span:
                    span.extract()
                value = clean_text(li.get_text(" ", strip=True))
                if key:
                    pairs[key] = value
            link = item.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            branch_name = first_by_keys(pairs, ("기관명", "교육기관", "운영기관", "장소")) or target.branch
            period_raw = first_by_keys(pairs, ("교육기간", "수강기간", "강좌기간", "운영기간", "기간"))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch_name),
                    "title": title,
                    "branch": clean_text(branch_name) or target.branch,
                    "category": "",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": clean_text((item.select_one(".state") or item.find("span")).get_text(" ", strip=True) if (item.select_one(".state") or item.find("span")) else ""),
                    "fee": first_by_keys(pairs, ("수강료", "교육비", "비용")),
                    "period": normalize_mixed_date_range(period_raw),
                    "schedule_raw": first_by_keys(pairs, ("교육시간", "수강시간", "강의시간", "시간")),
                    "target": first_by_keys(pairs, ("교육대상", "수강대상", "대상")),
                    "description": title,
                    "raw_fields": {"pairs": pairs, "parser": "jntle_damoa"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .boardPage, a[href*='uDamoaLecture/']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jntle_damoa", meta


YONGSAN_EDUCATION_PROVIDER = "MUNI_YEDU_YONGSAN_GO_KR_4E97CC33"
YONGSAN_EDUCATION_HOST = "yedu.yongsan.go.kr"
YONGSAN_EDUCATION_LIST_PATH = "/site/edtotal/lesson/userlist.do"
YONGSAN_EDUCATION_DETAIL_PATH = "/site/edtotal/lesson/form.do"
YONGSAN_EDUCATION_SITE_CODE = "S0000500"
YONGSAN_EDUCATION_MENU_CODE = "02020000"
YONGSAN_EDUCATION_DECORATOR = "user27EdTotal"
YONGSAN_EDUCATION_PAGE_SIZE = 16
YONGSAN_EDUCATION_STATES: tuple[tuple[str, str, str, str], ...] = (
    ("E0820100", "SCHEDULED", "모집예정", "접수대기"),
    ("E0820110", "OPEN", "모집중", "접수중"),
)


def is_yongsan_education_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query, keep_blank_values=True)
    return (
        target.provider == YONGSAN_EDUCATION_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == YONGSAN_EDUCATION_HOST
        and parsed.path == YONGSAN_EDUCATION_LIST_PATH
        and query
        == {
            "sitecdv": [YONGSAN_EDUCATION_SITE_CODE],
            "decorator": [YONGSAN_EDUCATION_DECORATOR],
            "menucdv": [YONGSAN_EDUCATION_MENU_CODE],
        }
    )


def yongsan_education_list_payload(state_code: str, page_index: int) -> dict[str, str]:
    return {
        "sitecdv": YONGSAN_EDUCATION_SITE_CODE,
        "decorator": YONGSAN_EDUCATION_DECORATOR,
        "menucdv": YONGSAN_EDUCATION_MENU_CODE,
        "currentPage": str(max(0, page_index)),
        "edutypecdv": "",
        "lesseqn": "",
        "searchProvince": "",
        "searchEdutypecdv": "",
        "searchAge": "",
        "searchSex": "",
        "searchRecsta": "",
        "searchRecend": "",
        "searchState": state_code,
        "searchWord": "",
    }


def yongsan_education_declared_pages(soup: BeautifulSoup) -> int:
    indexes = {0}
    for node in soup.select("a[onclick*='doSearch']"):
        indexes.update(
            int(value)
            for value in re.findall(r"doSearch\s*\(\s*(\d+)\s*\)", clean_text(node.get("onclick")))
        )
    return max(indexes) + 1


def yongsan_education_list_rows(
    target: CrawlTarget,
    soup: BeautifulSoup,
    *,
    state_code: str,
    normalized_status: str,
    expected_list_status: str,
    page_index: int,
) -> tuple[list[dict[str, Any]], int]:
    rows: list[dict[str, Any]] = []
    invalid_rows = 0
    for tr in soup.select("table tbody tr"):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td", recursive=False)]
        if not cells:
            continue
        link = tr.select_one("a[href*='goWrite']")
        looks_like_course = len(cells) == 7 and bool(cells[0].isdigit() or link)
        if not looks_like_course:
            continue
        href = clean_text(link.get("href") if link else "")
        match = re.search(r"goWrite\s*\(\s*(\d+)\s*,\s*['\"]([^'\"]+)['\"]\s*\)", href)
        if len(cells) != 7 or not match or not clean_text(cells[1]):
            invalid_rows += 1
            continue
        lesson_seq, education_type = match.groups()
        list_status = clean_text(cells[6])
        if list_status != expected_list_status:
            invalid_rows += 1
            continue
        capacity_match = re.search(
            r"(\d[\d,]*)\s*/\s*(\d[\d,]*)\s*/\s*(\d[\d,]*)",
            clean_text(cells[4]),
        )
        if not capacity_match:
            invalid_rows += 1
            continue
        capacity_current, capacity_total, waitlist_total = (
            int(value.replace(",", "")) for value in capacity_match.groups()
        )
        detail_url = yongsan_education_detail_url(lesson_seq, education_type)
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": f"{target.provider}:lesson:{lesson_seq}"[:100],
                "prefer_incoming_provider_course_id": True,
                "title": clean_text(cells[1]),
                "branch": target.branch,
                "branch_code": "YONGSAN_EDUCATION_PORTAL",
                "preserve_branch": True,
                "branch_url": target.url,
                "category": "교육·강좌",
                "program_type": "강좌",
                "raw_url": detail_url,
                "application_url": detail_url,
                "application_type": "ONLINE_RESERVATION",
                "application_method_raw": "인터넷",
                "reservation_available": normalized_status == "OPEN",
                "status": normalized_status,
                "fee": clean_text(cells[5]),
                "apply_period": normalize_mixed_date_range(cells[2]),
                "capacity": clean_text(cells[4]),
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "waitlist_total": waitlist_total,
                "venue_name": clean_text(cells[3]),
                "room": clean_text(cells[3]),
                "description": clean_text(tr.get_text(" ", strip=True)),
                "collection_category": "공공예약",
                "domain_category": "교육·강좌",
                "operator_type": "지자체/공공기관",
                "source_group": "municipal_reservation",
                "collection_type": "state_filters+detail_html",
                "service_group": "공공강좌",
                "service_group_policy": "locked",
                "raw_fields": {
                    "parser": "yongsan_education_state_filters+detail",
                    "lesson_seq": lesson_seq,
                    "education_type": education_type,
                    "state_code": state_code,
                    "list_status": list_status,
                    "list_ordinal": int(cells[0]),
                    "list_cells": cells,
                    "page_index": page_index,
                },
            }
        )
    return rows, invalid_rows


def yongsan_education_detail_url(lesson_seq: str, education_type: str) -> str:
    query = urlencode(
        {
            "sitecdv": YONGSAN_EDUCATION_SITE_CODE,
            "decorator": YONGSAN_EDUCATION_DECORATOR,
            "menucdv": YONGSAN_EDUCATION_MENU_CODE,
            "edutypecdv": clean_text(education_type),
            "lesseqn": clean_text(lesson_seq),
        }
    )
    return f"https://{YONGSAN_EDUCATION_HOST}{YONGSAN_EDUCATION_DETAIL_PATH}?{query}"


def yongsan_education_venue_address(value: Any) -> str:
    text = clean_text(value)
    match = re.search(r"\((?:서울(?:특별시)?\s+)?(용산구\s+[^)]+)\)", text)
    return clean_text(match.group(1)) if match else ""


def collect_yongsan_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    errors: list[str] = []
    if not is_yongsan_education_target(target):
        errors.append("target does not match the canonical Yongsan education source")

    s = session()
    listed_rows: list[dict[str, Any]] = []
    seen_lesson_ids: set[str] = set()
    pages = 0
    invalid_rows = 0
    duplicate_lessons = 0
    source_cap_reached = False
    status_pages: dict[str, int] = {}
    declared_pages_by_status: dict[str, int] = {}
    declared_totals_by_status: dict[str, int] = {}
    status_complete: dict[str, bool] = {}

    if not errors:
        for state_code, normalized_status, list_status, detail_status in YONGSAN_EDUCATION_STATES:
            state_error_count = len(errors)
            state_rows: list[dict[str, Any]] = []
            state_pages = 0
            try:
                first_soup = post_soup(
                    s,
                    target.url,
                    yongsan_education_list_payload(state_code, 0),
                    timeout,
                )
            except Exception as exc:
                errors.append(f"{state_code} page 0: {type(exc).__name__}")
                logger.debug("Yongsan education list fetch failed state=%s: %s", state_code, exc)
                status_pages[state_code] = 0
                declared_pages_by_status[state_code] = 0
                declared_totals_by_status[state_code] = 0
                status_complete[state_code] = False
                continue

            declared_pages = yongsan_education_declared_pages(first_soup)
            first_rows, first_invalid = yongsan_education_list_rows(
                target,
                first_soup,
                state_code=state_code,
                normalized_status=normalized_status,
                expected_list_status=list_status,
                page_index=0,
            )
            invalid_rows += first_invalid
            declared_total = int(first_rows[0]["raw_fields"]["list_ordinal"]) if first_rows else 0
            expected_pages = max(1, (declared_total + YONGSAN_EDUCATION_PAGE_SIZE - 1) // YONGSAN_EDUCATION_PAGE_SIZE)
            if declared_pages != expected_pages:
                errors.append(
                    f"{state_code} pagination declares {declared_pages} pages for total {declared_total}"
                )
            if declared_pages > max(1, max_pages):
                source_cap_reached = True
                errors.append(
                    f"{state_code} max_pages cap allows {max(1, max_pages)} of {declared_pages} pages"
                )

            for page_index in range(min(declared_pages, max(1, max_pages))):
                if page_index == 0:
                    page_rows = first_rows
                else:
                    try:
                        soup = post_soup(
                            s,
                            target.url,
                            yongsan_education_list_payload(state_code, page_index),
                            timeout,
                        )
                    except Exception as exc:
                        errors.append(f"{state_code} page {page_index}: {type(exc).__name__}")
                        logger.debug(
                            "Yongsan education list fetch failed state=%s page=%s: %s",
                            state_code,
                            page_index,
                            exc,
                        )
                        break
                    page_rows, page_invalid = yongsan_education_list_rows(
                        target,
                        soup,
                        state_code=state_code,
                        normalized_status=normalized_status,
                        expected_list_status=list_status,
                        page_index=page_index,
                    )
                    invalid_rows += page_invalid
                pages += 1
                state_pages += 1
                expected_page_size = min(
                    YONGSAN_EDUCATION_PAGE_SIZE,
                    max(0, declared_total - page_index * YONGSAN_EDUCATION_PAGE_SIZE),
                )
                if len(page_rows) != expected_page_size:
                    errors.append(
                        f"{state_code} page {page_index} exposes {len(page_rows)} of {expected_page_size} declared rows"
                    )
                for row_index, row in enumerate(page_rows):
                    raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
                    expected_ordinal = declared_total - page_index * YONGSAN_EDUCATION_PAGE_SIZE - row_index
                    if int(raw_fields.get("list_ordinal") or 0) != expected_ordinal:
                        errors.append(
                            f"{state_code} page {page_index} has non-contiguous ordinal for lesson "
                            f"{raw_fields.get('lesson_seq')}"
                        )
                    lesson_seq = clean_text(raw_fields.get("lesson_seq"))
                    if lesson_seq in seen_lesson_ids:
                        duplicate_lessons += 1
                        continue
                    seen_lesson_ids.add(lesson_seq)
                    raw_fields["expected_detail_status"] = detail_status
                    state_rows.append(row)

            if len(state_rows) != declared_total:
                errors.append(
                    f"{state_code} declared total {declared_total} does not match {len(state_rows)} unique lessons"
                )
            listed_rows.extend(state_rows)
            status_pages[state_code] = state_pages
            declared_pages_by_status[state_code] = declared_pages
            declared_totals_by_status[state_code] = declared_total
            status_complete[state_code] = (
                len(errors) == state_error_count
                and state_pages == declared_pages
                and len(state_rows) == declared_total
            )

    if invalid_rows:
        errors.append(f"{invalid_rows} course rows were missing canonical list fields")
    if duplicate_lessons:
        errors.append(f"{duplicate_lessons} duplicate lesson_seq rows crossed state/page boundaries")

    allowed_details = max(0, detail_limit)
    if allowed_details < len(listed_rows):
        source_cap_reached = True
        errors.append(
            f"detail_limit cap allows {allowed_details} of {len(listed_rows)} required detail pages"
        )

    detail_pages = 0
    detail_attempts = 0
    detail_errors: list[str] = []
    for row in listed_rows[:allowed_details]:
        detail_attempts += 1
        raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
        lesson_seq = clean_text(raw_fields.get("lesson_seq"))
        detail_url = clean_text(row.get("raw_url"))
        try:
            soup = fetch_soup(s, detail_url, timeout=timeout)
            detail_pages += 1
            pairs = pairs_from_tables(soup)
            required_labels = (
                "강좌명",
                "교육장",
                "장소",
                "접수기간",
                "교육시간",
                "교육기간",
                "수업요일",
                "접수나이",
                "수강료",
                "정원",
                "접수상태",
                "강좌소개",
                "담당부서",
            )
            missing_labels = [label for label in required_labels if not clean_text(pairs.get(label))]
            expected_detail_status = clean_text(raw_fields.get("expected_detail_status"))
            if missing_labels:
                detail_errors.append(f"lesson {lesson_seq}: missing {','.join(missing_labels)}")
            if clean_text(pairs.get("강좌명")) != clean_text(row.get("title")):
                detail_errors.append(f"lesson {lesson_seq}: title mismatch")
            if clean_text(pairs.get("접수상태")) != expected_detail_status:
                detail_errors.append(f"lesson {lesson_seq}: state changed during snapshot")
            if not soup.select_one("#btnSubmit"):
                detail_errors.append(f"lesson {lesson_seq}: application control missing")

            detail_capacity = parse_capacity_number(pairs.get("정원"))
            if detail_capacity is None or detail_capacity != row.get("capacity_total"):
                detail_errors.append(f"lesson {lesson_seq}: detail/list capacity mismatch")

            branch = clean_text(pairs.get("교육장")) or clean_text(row.get("branch")) or target.branch
            venue = clean_text(pairs.get("장소")) or branch
            period = normalize_mixed_date_range(clean_text(pairs.get("교육기간")))
            apply_period = normalize_mixed_date_range(clean_text(pairs.get("접수기간")))
            schedule_raw = clean_text(
                " / ".join(
                    value
                    for value in (
                        clean_text(pairs.get("수업요일")),
                        clean_text(pairs.get("교육시간")),
                    )
                    if value
                )
            )
            description = clean_text(
                " ".join(
                    value
                    for value in (
                        clean_text(pairs.get("강좌소개")),
                        clean_text(pairs.get("강좌계획서")),
                    )
                    if value
                )
            )
            row.update(
                {
                    "branch": branch,
                    "branch_code": stable_provider("YONGSAN_BRANCH", branch),
                    "venue_name": venue,
                    "room": venue,
                    "venue_address": yongsan_education_venue_address(venue),
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule_raw,
                    "target": clean_text(pairs.get("접수나이")),
                    "eligibility_raw": clean_text(pairs.get("접수나이")),
                    "fee": clean_text(pairs.get("수강료")) or row.get("fee"),
                    "capacity_total": detail_capacity,
                    "instructor": clean_instructor_name(pairs.get("강사명")),
                    "description": description or row.get("description"),
                    "contact": clean_text(pairs.get("담당부서")),
                    "application_method_raw": clean_text(pairs.get("접수방법")) or "인터넷",
                }
            )
            row["start_date"], row["end_date"] = parse_date_range(period)
            row["apply_start"], row["apply_end"] = parse_date_range(apply_period)
            raw_fields["detail_pairs"] = pairs
            raw_fields["application_control"] = "btnSubmit"
            row["raw_fields"] = raw_fields
        except Exception as exc:
            detail_errors.append(f"lesson {lesson_seq}: {type(exc).__name__}")
            logger.debug("Yongsan education detail fetch failed %s: %s", safe_url_for_log(detail_url), exc)

    if detail_errors:
        errors.append(
            f"detail validation failed for {len(detail_errors)} checks "
            f"({'; '.join(detail_errors[:5])})"
        )

    list_complete = (
        bool(status_complete)
        and all(status_complete.values())
        and not invalid_rows
        and not duplicate_lessons
    )
    details_complete = detail_pages == len(listed_rows) and not detail_errors
    snapshot_complete = list_complete and details_complete and not errors
    no_current_data = snapshot_complete and not listed_rows
    rows = [
        {name: value for name, value in row.items() if value not in (None, "", [], {})}
        for row in listed_rows
    ]
    meta: dict[str, Any] = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "status_pages": status_pages,
        "declared_pages_by_status": declared_pages_by_status,
        "declared_totals_by_status": declared_totals_by_status,
        "status_complete": status_complete,
        "discovered_links": len(seen_lesson_ids),
        "reservation_discovery_links": sum(bool(clean_text(row.get("application_url"))) for row in rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": any(value > 1 for value in declared_pages_by_status.values()),
        "pagination_complete": list_complete,
        "pagination_exhausted": list_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached,
        "recursion_depth": 0,
        "current_count": len(rows),
        "no_current_data": no_current_data,
        "no_current_reason": "official upcoming/open education list is empty" if no_current_data else "",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(rows), "yongsan_education_state_filters+detail", meta


def collect_yongsan_lessons(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    list_url = target.url
    parsed = urlparse(list_url)
    if (
        parsed.scheme != "https"
        or not parsed.netloc.endswith("yongsan.go.kr")
        or not parsed.path.endswith("/lesson/userlist.do")
    ):
        raise ValueError("Yongsan lesson collector requires its canonical HTTPS lesson URL")
    base_query = parse_qs(parsed.query)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        if page > 1:
            query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 7 or not cells[0].isdigit():
                continue
            title = cells[1]
            link = tr.find("a", href=True)
            raw_url = current_url
            if link and "goWrite" in link.get("href", ""):
                match = re.search(r"goWrite\((\d+),'([^']+)'\)", link.get("href"))
                if match:
                    raw_url = f"{current_url}#lesson-{match.group(1)}-{match.group(2)}"
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, cells[3]),
                    "title": title,
                    "branch": cells[3],
                    "category": "",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": cells[6],
                    "fee": cells[5],
                    "period": normalize_mixed_date_range(cells[2]),
                    "apply_period": "",
                    "schedule_raw": cells[2],
                    "target": "",
                    "capacity": cells[4],
                    "description": clean_text(tr.get_text(" ", strip=True)),
                    "raw_fields": {"cells": cells, "parser": "yongsan_lessons"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "yongsan_lessons", meta


def collect_sll_online_courses(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"X-Requested-With": "XMLHttpRequest", "Referer": target.url})
    rows: list[dict[str, Any]] = []
    params = {"main_se": "lie"}
    if "course_category_id=" in target.url:
        query = parse_qs(urlparse(target.url).query)
        params.update({key: value[0] for key, value in query.items() if value})
    response = s.post("https://sll.seoul.go.kr/lms/requestCourse/doListLieCourse.do", data=params, timeout=timeout, verify=True)
    response.raise_for_status()
    data = response.json()
    for item in data.get("rows", [])[: max_pages * 50]:
        title = clean_text(item.get("course_nm"))
        if not title or is_low_value_title(title):
            continue
        raw_url = (
            "https://sll.seoul.go.kr/lms/requestCourse/doDetailInfo.do"
            f"?main_se=lie&course_id={item.get('course_id')}&class_no={item.get('class_no')}"
            f"&course_gubun={item.get('course_gubun')}&asp_id={item.get('asp_id')}"
            f"&sub_course_category_id={item.get('sub_category_id') or ''}&mnid=202412426668"
        )
        category = clean_text(item.get("sub_category_nm") or item.get("category_nm") or item.get("category_nm2"))
        image_url = normalize_link("https://sll.seoul.go.kr", item.get("course_image_file_path"))
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, item.get("dept_name") or target.branch),
                "title": title,
                "branch": clean_text(item.get("dept_name")) or target.branch,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": clean_text(item.get("status") or item.get("course_request_state")),
                "fee": clean_text(item.get("fee")),
                "period": clean_text(item.get("course_dt") or item.get("course_request_dt")),
                "apply_period": clean_text(item.get("course_request_dt") or item.get("request_dt")),
                "schedule_raw": "온라인",
                "target": "",
                "description": clean_text(item.get("tag_list") or category or title),
                "image_url": image_url,
                "raw_fields": {"item": item, "parser": "sll_online_courses"},
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": len(rows) > 50,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "sll_online_courses", meta


def collect_sll_offline_district_learning(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_url = "https://sll.seoul.go.kr/main/doLifeLongEduInstListView.do?main_se=lie&mnid=202501953013"
    soup = fetch_soup(s, list_url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    discovered_links = 0

    for card in soup.select(".course-item-detail"):
        link = card.select_one("a[href]")
        if not link:
            continue
        application_url = normalize_link(list_url, link.get("href"))
        if not application_url:
            continue
        text_lines = [clean_text(line) for line in card.get_text("\n", strip=True).splitlines()]
        text_lines = [line for line in text_lines if line and line != "바로가기"]
        branch = text_lines[0] if text_lines else clean_text(link.get_text(" ", strip=True))
        if not branch or branch in {"바로가기", "기관정보"}:
            continue
        title = clean_text(text_lines[1] if len(text_lines) > 1 else f"{branch} 평생학습")
        if not title.endswith("평생학습"):
            title = f"{branch} 평생학습"
        discovered_links += 1
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, application_url, title, branch),
                "title": title,
                "branch": branch,
                "branch_code": re.sub(r"[^A-Za-z0-9가-힣]+", "_", branch).strip("_")[:80],
                "category": "자치구평생학습",
                "raw_url": application_url,
                "application_url": application_url,
                "status": "기관 링크",
                "fee": "",
                "period": "",
                "apply_period": "",
                "schedule_raw": "",
                "target": "지역 주민",
                "description": clean_text(card.get_text(" ", strip=True)),
                "collection_category": "공공예약",
                "domain_category": "평생교육",
                "operator_type": "지자체/공공기관",
                "source_group": "lifelong_learning",
                "collection_type": "static_html",
                "program_type": "강좌",
                "application_type": "OFFLINE_APPLY",
                "application_method_raw": "자치구 평생학습 사이트 바로가기",
                "reservation_available": False,
                "discovery_status": "district_learning_portal_link",
                "raw_fields": {
                    "parser": "sll_offline_district_links",
                    "source_url": list_url,
                    "application_url": application_url,
                    "card_text": clean_text(card.get_text(" ", strip=True)),
                },
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": discovered_links,
        "reservation_discovery_links": discovered_links,
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "sll_offline_district_links", meta


def gseek_text(value: Any) -> str:
    return clean_text(html.unescape(str(value or "")))


def gseek_money(value: Any) -> str:
    text = gseek_text(value).replace(",", "")
    if not text or text == "0":
        return "무료"
    if re.fullmatch(r"\d+", text):
        return f"{int(text):,}원"
    return gseek_text(value)


def gseek_date(value: Any) -> str:
    text = gseek_text(value)
    match = re.search(r"(\d{4})[.\-/](\d{1,2})[.\-/](\d{1,2})", text)
    if not match:
        return ""
    return f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"


def gseek_period(start_value: Any, end_value: Any) -> str:
    start = gseek_date(start_value)
    end = gseek_date(end_value)
    if start and end and start != end:
        return f"{start} ~ {end}"
    return start or end


def gseek_schedule(item: dict[str, Any], period: str) -> str:
    weekday = gseek_text(item.get("d_edu_wday_cd_nm") or item.get("d_edu_bgng_dayofweek"))
    start_time = gseek_text(item.get("d_edu_start_time"))
    end_time = gseek_text(item.get("d_edu_end_time"))
    time_text = f"{start_time}-{end_time}" if start_time and end_time else start_time or end_time
    parts = [period]
    if weekday:
        parts.append(weekday)
    if time_text:
        parts.append(time_text)
    return clean_text(" ".join(parts))


def gseek_image_url(value: Any) -> str:
    return normalize_link("https://www.gseek.kr", gseek_text(value))


