def gseek_offline_row(target: CrawlTarget, item: dict[str, Any]) -> dict[str, Any]:
    title = gseek_text(item.get("d_sbjct_nm"))
    subject_id = gseek_text(item.get("d_sbjct_sn"))
    cycle_id = gseek_text(item.get("d_sbjct_cycl_sn"))
    raw_url = (
        "https://www.gseek.kr/user/course/offline/view"
        f"?s_sbjct_sn={subject_id}&s_sbjct_cycl_sn={cycle_id}"
    )
    branch = gseek_text(item.get("d_edu_gvmnfc") or item.get("d_rgn") or target.branch)
    region = gseek_text(item.get("d_rgn"))
    category = " > ".join(
        part
        for part in [
            gseek_text(item.get("d_clsf_depth1_nm")),
            gseek_text(item.get("d_clsf_depth2_nm")),
            gseek_text(item.get("d_clsf_depth3_nm")),
        ]
        if part
    )
    period = gseek_period(item.get("d_edu_bgng_dt"), item.get("d_edu_end_dt"))
    material_fee = gseek_money(item.get("d_prepar_cmdty_amt"))
    if material_fee == "무료":
        material_fee = ""
    description = gseek_text(item.get("d_sbjct_intrd_cn"))
    tags = [gseek_text(token) for token in gseek_text(item.get("d_rel_srch_nm")).split(",") if gseek_text(token)]
    capacity_total = gseek_text(item.get("d_edu_nope"))
    capacity_current = gseek_text(item.get("d_aply_cnt"))

    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
        "title": title,
        "branch": branch,
        "branch_code": re.sub(r"[^A-Za-z0-9\uAC00-\uD7A3_]+", "_", branch).strip("_")[:80],
        "category": category or gseek_text(item.get("d_head_rel_srch_nm")) or "오프라인학습",
        "raw_url": raw_url,
        "application_url": raw_url,
        "status": gseek_text(item.get("d_recrut_stts_nm")),
        "fee": gseek_money(item.get("d_sbjct_amt")),
        "material_fee": material_fee,
        "period": period,
        "schedule_raw": gseek_schedule(item, period),
        "target": gseek_text(item.get("d_sbjct_trgt_nm_1")),
        "capacity": capacity_total,
        "capacity_total": capacity_total,
        "capacity_current": capacity_current,
        "instructor": "",
        "description": description or gseek_text(item.get("d_sbjct_img_ttl")) or title,
        "image_url": gseek_image_url(item.get("d_file_url")),
        "collection_category": "공공예약",
        "domain_category": "평생교육",
        "operator_type": "지자체/공공기관",
        "source_group": "lifelong_learning",
        "collection_type": "json_api",
        "program_type": "강좌",
        "venue_name": branch,
        "venue_address": region,
        "application_type": "ONLINE_RESERVATION",
        "application_method_raw": gseek_text(item.get("d_stdnt_chice_mthd_cd_nm")),
        "reservation_available": gseek_text(item.get("d_recrut_stts_nm")) in {"모집중", "마감임박", "모집예정"},
        "tags": tags,
        "raw_fields": {
            "parser": "gseek_offline_api",
            "item": item,
            "region": region,
        },
    }


def collect_gyeonggi_gseek_offline(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update(
        {
            "Referer": "https://www.gseek.kr/user/course/offline/list",
            "X-Requested-With": "XMLHttpRequest",
        }
    )
    rows: list[dict[str, Any]] = []
    pages = 0
    total_count = 0
    page_size = 9
    dedicated_owner_exclusions: Counter[str] = Counter()
    endpoint = "https://www.gseek.kr/user/course/offline/list/search"
    parsed_url = urlparse(target.url)
    region_code = "4131000000" if target.provider == "MUNI_GURI_GSEEK_KR_2E5F409F" or parsed_url.netloc.startswith("guri.") else ""

    for page in range(max(1, max_pages)):
        start = page * page_size + 1
        end = start + page_size
        response = s.post(
            endpoint,
            data={"s_sort_by": "1", "s_row_start": str(start), "s_row_end": str(end), "resion": region_code},
            timeout=timeout,
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, list) or not payload:
            break
        pages += 1
        if payload[0].get("d_total_cnt"):
            try:
                total_count = int(str(payload[0].get("d_total_cnt")).replace(",", ""))
            except ValueError:
                total_count = total_count or 0
        for item in payload:
            if not isinstance(item, dict):
                continue
            co_sponsor_id = gseek_text(item.get("d_co_sprvsn_id"))
            if (
                target.provider == "GYEONGGI_GSEEK"
                and co_sponsor_id in GYEONGGI_GSEEK_DEDICATED_OWNER_CO_SPONSORS
            ):
                dedicated_owner_exclusions[co_sponsor_id] += 1
                continue
            row = gseek_offline_row(target, item)
            if row.get("title"):
                rows.append(row)
        if total_count and len(rows) >= total_count:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": bool(total_count and total_count > page_size),
        "recursion_depth": 0,
        "total_count": total_count,
        "region_code": region_code,
        "excluded_dedicated_owner_count": sum(dedicated_owner_exclusions.values()),
        "excluded_dedicated_owner_counts": dict(dedicated_owner_exclusions),
    }
    return dedupe_rows(rows), "gseek_offline_api", meta


def collect_gyeongsan_lifelong(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    visited_pages = 0
    pagination_detected = False
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    current_url = target.url
    stop_labels = ("수강기간", "수강시간", "접수기간", "신청/정원", "교육장소", "수강료")

    for page in range(1, max_pages + 1):
        if page > 1:
            query["pageIndex"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        visited_pages += 1
        page_rows = 0
        for node in soup.select("ul.content_list"):
            text = clean_text(node.get_text(" ", strip=True))
            if "수강기간" not in text or "수강시간" not in text:
                continue
            title_line = clean_text(node.get_text("\n", strip=True).splitlines()[0])
            branch_name = ""
            title_match = re.match(r"\[([^\]]+)\]\s*(.+)", title_line)
            if title_match:
                branch_name = clean_text(title_match.group(1))
                title = clean_text(title_match.group(2))
            else:
                title = re.split(r"\s*수강기간\s*:", title_line, maxsplit=1)[0]
            if not title:
                continue
            raw_url = normalize_link(current_url, (node.find("a", href=True) or {}).get("href")) or current_url
            period = extract_korean_labeled_value(text, "수강기간", stop_labels)
            schedule = extract_korean_labeled_value(text, "수강시간", stop_labels)
            apply_period = extract_korean_labeled_value(text, "접수기간", stop_labels)
            capacity = extract_korean_labeled_value(text, "신청/정원", stop_labels)
            room = extract_korean_labeled_value(text, "교육장소", stop_labels)
            fee = extract_korean_labeled_value(text, "수강료", stop_labels)
            status_node = node.find_next_sibling("li")
            status_text = clean_text(status_node.get_text(" ", strip=True) if status_node else "")
            status = next(
                (token for token in ("접수중", "신청가능", "접수예정", "신청마감", "접수마감") if token in f"{text} {status_text}"),
                "",
            )
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch_name or target.branch),
                    "title": title,
                    "branch": branch_name or target.branch,
                    "category": "읍면동학습관",
                    "raw_url": raw_url,
                    "status": status,
                    "fee": fee,
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule,
                    "target": "",
                    "room": room,
                    "venue_name": room,
                    "capacity": capacity,
                    "description": text,
                    "raw_fields": {"text": text, "parser": "gyeongsan_content_list"},
                }
            )
            page_rows += 1
        if page_rows == 0:
            break
        pagination_detected = pagination_detected or bool(soup.select(".paginate, .paging, .pagination, a[href*='pageIndex=']"))

    meta = {
        "pages": visited_pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gyeongsan_content_list", meta


GYERYONG_LIFELONG_LIST_URL = "https://farm.gyeryong.go.kr/lll/html/sub03/030102.html"


def gyeryong_label(value: Any) -> str:
    return re.sub(r"\s+", "", clean_text(value))


def gyeryong_program_pairs(node: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(node, "select"):
        return pairs
    for li in node.select(".list_con li"):
        key_node = li.find("span")
        key = gyeryong_label(key_node.get_text(" ", strip=True) if key_node else "")
        value_nodes = li.find_all("em", recursive=False)
        value = clean_text(" ".join(value_node.get_text(" ", strip=True) for value_node in value_nodes))
        if key and value:
            pairs[key] = value
    return pairs


def gyeryong_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs = gyeryong_program_pairs(soup.select_one(".program_con.program_view") or soup)
    for key, value in pairs_from_tables(soup).items():
        normalized_key = gyeryong_label(key)
        if normalized_key and value:
            pairs[normalized_key] = value
    return pairs


def gyeryong_course_title(view: Any) -> tuple[str, str]:
    title_node = view.select_one(".in_top .tit") if hasattr(view, "select_one") else None
    if not title_node:
        return "", ""
    state_node = title_node.select_one(".cond")
    education_state = clean_text(state_node.get_text(" ", strip=True) if state_node else "")
    for node in title_node.select(".cond"):
        node.extract()
    return clean_text(title_node.get_text(" ", strip=True)), education_state


def gyeryong_capacity_numbers(value: str) -> tuple[Optional[int], Optional[int]]:
    current, total = parse_capacity_pair(value)
    if current is not None or total is not None:
        return current, total
    numbers = [int(match) for match in re.findall(r"\d{1,5}", clean_text(value).replace(",", ""))]
    if len(numbers) >= 2:
        return numbers[0], numbers[-1]
    if len(numbers) == 1:
        return None, numbers[0]
    return None, None


def gyeryong_row_from_detail(
    target: CrawlTarget,
    detail_url: str,
    soup: BeautifulSoup,
    fallback_pairs: Optional[dict[str, str]] = None,
    fallback_title: str = "",
    fallback_status: str = "",
) -> dict[str, Any] | None:
    view = soup.select_one(".program_con.program_view")
    if not view:
        return None
    pairs = {**(fallback_pairs or {}), **gyeryong_detail_pairs(soup)}
    title, education_state = gyeryong_course_title(view)
    title = title or clean_text(fallback_title)
    if not title or is_low_value_title(title):
        return None
    status = clean_text(view.select_one(".accept span").get_text(" ", strip=True) if view.select_one(".accept span") else "")
    status = status or fallback_status
    accept_method_node = view.select_one(".accept em")
    accept_method = clean_text(accept_method_node.get_text(" ", strip=True) if accept_method_node else "")
    method = clean_text(pairs.get("신청방법") or accept_method)
    category = clean_text(view.select_one(".cate").get_text(" ", strip=True) if view.select_one(".cate") else "")
    period = clean_text(pairs.get("교육기간", ""))
    apply_period = clean_text(pairs.get("접수기간", ""))
    weekday = clean_text(pairs.get("교육주기", ""))
    time_text = clean_text(pairs.get("교육시간", ""))
    schedule = clean_text(" ".join(part for part in [weekday, time_text] if part))
    room = clean_text(pairs.get("교육장소", ""))
    target_text = clean_text(pairs.get("교육대상", ""))
    capacity = clean_text(pairs.get("신청/정원", ""))
    capacity_current, capacity_total = gyeryong_capacity_numbers(capacity)
    fee = clean_text(pairs.get("수강료", ""))
    description = clean_text(pairs.get("강좌상세설명", ""))
    application_url = detail_url if "인터넷" in method and not any(token in status for token in ("마감", "종료")) else ""
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, detail_url, title, target.branch),
        "title": title,
        "branch": target.branch,
        "branch_code": target.provider,
        "category": category,
        "raw_url": detail_url,
        "application_url": application_url,
        "status": status,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": schedule or time_text,
        "target": target_text,
        "fee": fee,
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "instructor": clean_instructor_name(pairs.get("담당강사", "")),
        "room": room,
        "venue_name": room or target.branch,
        "application_method_raw": method,
        "application_type": "ONLINE_RESERVATION" if "인터넷" in method else "",
        "reservation_available": any(token in status for token in ("접수중", "접수예정")),
        "description": description or clean_text(" ".join([category, title, period, schedule, target_text, fee])),
        "collection_category": "평생교육",
        "domain_category": "평생교육",
        "operator_type": "지자체/공공기관",
        "source_group": "lifelong_learning",
        "collection_type": "static_html+detail_html",
        "program_type": "강좌",
        "raw_fields": {
            "parser": "gyeryong_lifelong_card_detail",
            "pairs": pairs,
            "education_state": education_state,
            "semester": pairs.get("학기명", ""),
            "cancel_period": pairs.get("취소기간", ""),
            "contact": pairs.get("문의", ""),
        },
    }


def collect_gyeryong_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    discovered_links = 0
    last_page = max_pages

    for page in range(1, max(1, max_pages) + 1):
        if page == 1:
            soup = fetch_soup(s, target.url, timeout=timeout)
        else:
            response = s.post(
                target.url,
                data={"sch_edu_ty": "0102", "skey": "", "sval": "", "GotoPage": str(page)},
                timeout=timeout,
            )
            response.raise_for_status()
            if not response.encoding or response.encoding.lower() == "iso-8859-1":
                response.encoding = response.apparent_encoding
            soup = BeautifulSoup(response.text, "lxml")
        pages += 1
        for onclick in re.findall(r"postPrintPage\((\d+)\)", str(soup.select_one(".pagination") or "")):
            try:
                last_page = max(last_page, int(onclick))
            except ValueError:
                pass

        page_rows = 0
        for card in soup.select(".program_con.edu_list .col"):
            link = card.select_one('a[href*="mode=V"][href*="mng_no"]')
            if not link:
                continue
            detail_url = normalize_link(target.url, link.get("href"))
            if not detail_url:
                continue
            discovered_links += 1
            fallback_pairs = gyeryong_program_pairs(card)
            fallback_title = clean_text(card.select_one(".tit").get_text(" ", strip=True) if card.select_one(".tit") else "")
            fallback_status = clean_text(card.select_one(".accept span").get_text(" ", strip=True) if card.select_one(".accept span") else "")
            row = None
            if detail_pages < detail_limit:
                try:
                    detail_soup = fetch_soup(s, detail_url, timeout=timeout)
                    row = gyeryong_row_from_detail(
                        target,
                        detail_url,
                        detail_soup,
                        fallback_pairs=fallback_pairs,
                        fallback_title=fallback_title,
                        fallback_status=fallback_status,
                    )
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("gyeryong detail fetch failed %s: %s", detail_url, exc)
            if row:
                rows.append(row)
                page_rows += 1
        if page_rows == 0 or page >= last_page:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": discovered_links,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": last_page > 1 or bool(rows and len(rows) >= 10),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gyeryong_lifelong_card_detail", meta


def collect_gangjin_school_courses(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    discovered_links = 0

    for card in soup.select(".new_edu_plan .tabbox .slider li a[href]"):
        title_node = card.select_one("h3")
        title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
        if not title or is_low_value_title(title):
            continue
        raw_url = normalize_link(target.url, card.get("href"))
        if not raw_url:
            continue
        discovered_links += 1
        status_node = card.select_one(".state")
        status = clean_text(status_node.get_text(" ", strip=True) if status_node else "")
        info_items = [clean_text(li.get_text(" ", strip=True)) for li in card.select(".cont_box li")]
        info_items = [item for item in info_items if item]
        period = next((item for item in info_items if re.search(r"\d{4}[.-]\d{1,2}[.-]\d{1,2}\s*~", item)), "")
        room = next((item for item in info_items if item != period), "")
        description = clean_text(" ".join([status, title, *info_items]))
        branch = "전라남도 강진군"
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "category": "교육과정",
                "raw_url": raw_url,
                "status": status,
                "fee": "",
                "period": period,
                "apply_period": "",
                "schedule_raw": "",
                "target": "",
                "room": room,
                "venue_name": room or branch,
                "description": description,
                "raw_fields": {"parser": "gangjin_school_card", "items": info_items},
            }
        )
        if max_pages > 0 and len(rows) >= max_pages * 30:
            break

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": discovered_links,
        "reservation_discovery_links": discovered_links,
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gangjin_school_card", meta


def cheongdo_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in soup.select("#ajaxContent dl, dl"):
        key_node = dl.select_one("dt")
        value_node = dl.select_one("dd")
        key = clean_text(key_node.get_text(" ", strip=True) if key_node else "")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if key and value and key not in pairs:
            pairs[key] = value
    return pairs


def collect_cheongdo_reservation_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": target.url, "X-Requested-With": "XMLHttpRequest"})
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    mid = (query.get("mid") or [""])[0]
    aidx_match = re.search(r"/reservation/edu/(\d+)/lecture/list\.do$", parsed.path)
    aidx = aidx_match.group(1) if aidx_match else ""
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    category = "교육/강좌"
    branch = "경상북도 청도군"

    for page in range(1, max(1, max_pages) + 1):
        page_query = dict(query)
        if page > 1:
            page_query["page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(page_query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        title_text = clean_text(soup.title.get_text(" ", strip=True) if soup.title else "")
        title_parts = [part.strip() for part in title_text.split("|") if part.strip()]
        if len(title_parts) >= 2:
            category = title_parts[1]

        page_rows = 0
        for tr in soup.select("table.woman-edu-list tbody tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.select("th,td")]
            title_link = tr.select_one("[data-bc-idx]")
            title = clean_text(title_link.get_text(" ", strip=True) if title_link else (cells[1] if len(cells) > 1 else ""))
            if not title or is_low_value_title(title):
                continue
            course_idx = clean_text(title_link.get("data-bc-idx") if title_link else "")
            list_category = clean_text(tr.select_one("em.cate").get_text(" ", strip=True) if tr.select_one("em.cate") else "")
            apply_period = clean_text(tr.select_one(".list-date01").get_text(" ", strip=True) if tr.select_one(".list-date01") else (cells[2] if len(cells) > 2 else ""))
            schedule = clean_text(tr.select_one(".list-date02").get_text(" ", strip=True) if tr.select_one(".list-date02") else (cells[3] if len(cells) > 3 else ""))
            capacity = clean_text(tr.select_one(".list-people01").get_text(" ", strip=True) if tr.select_one(".list-people01") else (cells[4] if len(cells) > 4 else ""))
            waitlist = clean_text(tr.select_one(".list-people02").get_text(" ", strip=True) if tr.select_one(".list-people02") else (cells[5] if len(cells) > 5 else ""))
            status = clean_text(tr.select_one(".list-state").get_text(" ", strip=True) if tr.select_one(".list-state") else (cells[7] if len(cells) > 7 else ""))
            detail_url = current_url
            detail_pairs: dict[str, str] = {}
            if aidx and mid and course_idx:
                detail_url = f"{parsed.scheme}://{parsed.netloc}/reservation/edu/{aidx}/lecture/view.do?mid={quote(mid)}&idx={quote(course_idx)}"
                if detail_pages < detail_limit:
                    detail_soup = fetch_soup(s, detail_url, timeout=timeout)
                    detail_pairs = cheongdo_detail_pairs(detail_soup)
                    detail_pages += 1
            period = clean_text(detail_pairs.get("교육일시", ""))
            fee = clean_text(detail_pairs.get("수강료", ""))
            material_fee = clean_text(detail_pairs.get("재료비", ""))
            room = clean_text(detail_pairs.get("교육장소", ""))
            target_text = clean_text(detail_pairs.get("교육대상", ""))
            instructor = clean_instructor_name(detail_pairs.get("강사명", ""))
            detail_capacity = clean_text(detail_pairs.get("정원", ""))
            capacity_current, capacity_total = parse_capacity_pair(capacity)
            if capacity_total is None:
                capacity_total = parse_capacity_number(detail_capacity)
            waitlist_current, waitlist_total = parse_capacity_pair(waitlist)
            description = clean_text(
                " ".join(
                    item
                    for item in [
                        list_category,
                        title,
                        status,
                        period,
                        apply_period,
                        schedule,
                        room,
                        target_text,
                        fee,
                        material_fee,
                        detail_pairs.get("문의처", ""),
                    ]
                    if item
                )
            )
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, detail_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": category,
                    "raw_url": detail_url,
                    "status": status,
                    "fee": fee,
                    "material_fee": material_fee,
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule,
                    "target": target_text,
                    "room": room,
                    "venue_name": room or branch,
                    "capacity": capacity or detail_capacity,
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "waitlist_current": waitlist_current,
                    "waitlist_total": waitlist_total,
                    "instructor": instructor,
                    "application_method_raw": list_category,
                    "description": description,
                    "raw_fields": {
                        "parser": "cheongdo_reservation_lecture_table",
                        "cells": cells,
                        "detail_pairs": detail_pairs,
                    },
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".bod_page a, .paging a, .pagination a"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "cheongdo_reservation_lecture_table", meta


def esongpa_parse_yyyymmdd(value: Any) -> Optional[datetime]:
    text = clean_text(value)
    if not text:
        return None
    for fmt in ("%Y%m%d", "%Y-%m-%d", "%Y.%m.%d"):
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            continue
    return None


def esongpa_first_program_item(item: dict[str, Any]) -> dict[str, Any]:
    values = item.get("programItem") or []
    if isinstance(values, list) and values:
        first = values[0]
        return first if isinstance(first, dict) else {}
    return {}


def esongpa_add_months(value: datetime, months: int) -> datetime:
    month_index = value.month - 1 + months
    year = value.year + month_index // 12
    month = month_index % 12 + 1
    day = min(value.day, calendar.monthrange(year, month)[1])
    return value.replace(year=year, month=month, day=day)


def esongpa_course_period(item: dict[str, Any]) -> str:
    direct_start = esongpa_parse_yyyymmdd(item.get("tcSdate") or item.get("repSdate"))
    direct_end = esongpa_parse_yyyymmdd(item.get("tcEdate") or item.get("repEdate"))
    if direct_start and direct_end:
        return f"{direct_start:%Y-%m-%d} ~ {direct_end:%Y-%m-%d}"

    group = item.get("grpcd") or {}
    rec_end = esongpa_parse_yyyymmdd(group.get("recEdate") or group.get("recSdate"))
    if not rec_end:
        return ""
    try:
        start_day = int(clean_text(group.get("startdate")) or "1")
    except ValueError:
        start_day = 1
    start_day = max(1, min(start_day, 31))
    start_day = min(start_day, calendar.monthrange(rec_end.year, rec_end.month)[1])
    period_start = rec_end.replace(day=start_day)
    if period_start <= rec_end:
        period_start = esongpa_add_months(period_start, 1)
    first_program = esongpa_first_program_item(item)
    try:
        month_count = int(first_program.get("monthCnt") or 1)
    except (TypeError, ValueError):
        month_count = 1
    month_count = max(1, month_count)
    period_end = esongpa_add_months(period_start, month_count) - timedelta(days=1)
    return f"{period_start:%Y-%m-%d} ~ {period_end:%Y-%m-%d}"


def collect_esongpa_lecture(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": target.url})
    soup = fetch_soup(s, target.url, timeout=timeout)
    csrf = soup.select_one("meta[name='_csrf']")
    csrf_header = soup.select_one("meta[name='_csrf_header']")
    if csrf and csrf_header:
        s.headers.update({clean_text(csrf_header.get("content")): clean_text(csrf.get("content"))})
    s.headers.update({"X-Requested-With": "XMLHttpRequest"})

    centers = []
    for li in soup.select("#selectComInfo li[value]"):
        code = clean_text(li.get("value"))
        name = clean_text(li.get_text(" ", strip=True))
        if code:
            centers.append((code, name))
    if not centers:
        centers = [("SONGPA01", target.branch or target.name)]

    rows: list[dict[str, Any]] = []
    pages = 0
    total_count = 0
    for com_code, com_name in centers:
        for page in range(1, max_pages + 1):
            payload = {
                "msportsCd": "all",
                "sportsCd": "all",
                "comcd": com_code,
                "searchValue": "null",
                "yoil": "null",
                "sugang": "YES",
                "pageIndex": str(page),
                "pageSize": "10",
                "startRow": str((page - 1) * 10),
            }
            response = s.post(urljoin(target.url, "/data/getLectureList"), data=payload, timeout=timeout, verify=True)
            response.raise_for_status()
            data = response.json()
            items = data.get("resultList") or []
            total_count = max(total_count, int(data.get("totalCount") or 0))
            if not items:
                break
            pages += 1
            for item in items:
                title = clean_text(item.get("classNm"))
                if not title:
                    continue
                class_cd = clean_text(item.get("classCd"))
                sports_cd = clean_text(item.get("sportsCd"))
                msports_cd = clean_text(item.get("msportsCd"))
                raw_url = urljoin(
                    target.url,
                    f"/lecture/lectureDetail?COMCD={com_code}&SPORTS_CD={sports_cd}&MSPORTS_CD={msports_cd}&CLASS_CD={class_cd}&RETRAIN_YN=YN_N&lecType=lec",
                )
                train_start = format_hhmm(item.get("trainStime") or item.get("trainStimeNm"))
                train_end = format_hhmm(item.get("trainEtime") or item.get("trainEtimeNm"))
                schedule = clean_text(
                    " ".join(
                        part
                        for part in [
                            clean_text(item.get("trainDayNm")),
                            f"{train_start}~{train_end}" if train_start and train_end else clean_text(item.get("trainTimeNm")),
                        ]
                        if part
                    )
                )
                rec_start = format_yyyymmdd((item.get("grpcd") or {}).get("recSdate"))
                rec_end = format_yyyymmdd((item.get("grpcd") or {}).get("recEdate"))
                fee_min = clean_text(item.get("minCost"))
                fee_max = clean_text(item.get("maxCost"))
                fee = ""
                if fee_min and fee_max and fee_min != fee_max:
                    fee = f"{int(float(fee_min)):,}~{int(float(fee_max)):,}원"
                elif fee_min:
                    fee = f"{int(float(fee_min)):,}원"
                period = esongpa_course_period(item)
                description = "\n".join(
                    part
                    for part in [
                        clean_text(item.get("classDesc")),
                        clean_text(item.get("classNote")),
                        clean_text(item.get("classReady")),
                        clean_text(item.get("bigo")),
                    ]
                    if part
                )
                status = "마감" if clean_text(item.get("webAcceptFinishYn")) == "Y" else "접수가능"
                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, raw_url, title, com_name or target.branch),
                        "title": title,
                        "branch": com_name or target.branch,
                        "category": clean_text(item.get("sportsCdNm")) or clean_text(item.get("msportsCdNm")),
                        "raw_url": raw_url,
                        "application_url": raw_url,
                        "status": status,
                        "fee": fee,
                        "period": period,
                        "apply_period": f"{rec_start} ~ {rec_end}" if rec_start and rec_end else "",
                        "schedule_raw": schedule,
                        "target": clean_text(item.get("classObj") or item.get("classTarget") or item.get("targetNm")),
                        "room": clean_text(item.get("placeCdNm")),
                        "venue_name": clean_text(item.get("placeCdNm")),
                        "capacity": clean_text(item.get("capa") or item.get("webCapa")),
                        "capacity_remaining": clean_text(item.get("remainCapa")),
                        "description": description,
                        "material_note": clean_text(item.get("matTeach")) or clean_text(item.get("matCost")),
                        "raw_fields": public_raw_fields(item),
                    }
                )
            if total_count and page * 10 >= total_count:
                break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": total_count > 10,
        "recursion_depth": 0,
        "total_count": total_count,
    }
    return dedupe_rows(rows), "esongpa_lecture_api", meta


BUSAN_EXPRN_PAGE_SIZE = 50
BUSAN_EXPRN_PARSER = "busan_experience_table+detail"


def busan_exprn_compact_label(value: Any) -> str:
    return re.sub(r"\s+", "", clean_text(value)).rstrip(":：")


def busan_exprn_labeled_value(lines: list[str], aliases: tuple[str, ...]) -> str:
    compact_aliases = tuple(busan_exprn_compact_label(alias) for alias in aliases)
    for index, line in enumerate(lines):
        text = clean_text(line)
        compact = busan_exprn_compact_label(text)
        for alias in compact_aliases:
            if compact == alias:
                for candidate in lines[index + 1 :]:
                    value = clean_text(candidate).lstrip(":：").strip()
                    if not value or value in {":", "：", "|"}:
                        continue
                    if busan_exprn_compact_label(value) in compact_aliases:
                        break
                    return value
            elif compact.startswith(f"{alias}:") or compact.startswith(f"{alias}："):
                value = clean_text(text[len(text.split(":", 1)[0]) + 1 :])
                if value:
                    return value
    return ""


def busan_exprn_rich_fee(value: Any) -> str:
    text = clean_text(value)
    label = (
        r"(?:\uc774\s*\uc6a9\s*\ub8cc|\ucc38\s*\uac00\s*\ube44|"
        r"\uccb4\s*\ud5d8\s*\ube44|\uc7ac\s*\ub8cc\s*\ube44|\ube44\s*\uc6a9)"
    )
    segment_match = re.search(
        rf"{label}\s*[:：]?\s*([^○ㅇ※▷▶]{{1,240}})",
        text,
    )
    if not segment_match:
        return ""
    segment = clean_text(segment_match.group(1))
    free_match = re.search(r"(\ubb34\s*\ub8cc|\uc720\s*\ub8cc)", segment)
    if free_match:
        return re.sub(r"\s+", "", free_match.group(1))
    amounts: list[str] = []
    for number, man_unit in re.findall(
        r"(\d[\d,]*)\s*(\ub9cc\s*)?\uc6d0",
        segment,
    ):
        amount = int(number.replace(",", ""))
        if man_unit:
            amount *= 10_000
        rendered = f"{amount:,}\uc6d0"
        if rendered not in amounts:
            amounts.append(rendered)
    if amounts:
        suffix = "/\uc778" if "/\uc778" in segment.replace(" ", "") else ""
        if len(amounts) == 1:
            return f"{amounts[0]}{suffix}"
        return f"{' ~ '.join(amounts)}{suffix} (\uc870\uac74\ubcc4 \uc0c1\uc774)"
    return ""


def busan_exprn_rich_place(value: Any) -> str:
    text = clean_text(value)
    match = re.search(
        r"(?:\ud589\s*\uc0ac\s*\uc7a5\s*\uc18c|\uccb4\s*\ud5d8\s*\uc7a5\s*\uc18c|"
        r"\uc6b4\s*\uc601\s*\uc7a5\s*\uc18c|\uc7a5\s*\uc18c)"
        r"\s*[:：]\s*([^○ㅇ※]{2,160}?)"
        r"(?=\s+(?:\uc774\s*\uc6a9\s*\ub8cc|\ucc38\s*\uac00\s*\ube44|"
        r"\uccb4\s*\ud5d8\s*\ube44|\uc7ac\s*\ub8cc\s*\ube44|"
        r"\uc624\uc804|\uc624\ud6c4|\d{1,2}\s*(?:\uc2dc|:))|[○ㅇ※]|$)",
        text,
    )
    if not match:
        return ""
    return clean_text(match.group(1)).rstrip(".,; ")


def busan_exprn_program_section(soup: BeautifulSoup) -> Any:
    expected = {"\uc18c\uac1c", "\uc0c1\uc138\uc815\ubcf4"}
    for heading in soup.find_all(["h3", "h4"]):
        if clean_text(heading.get_text(" ", strip=True)) not in expected:
            continue
        container = heading.find_parent(class_="tabCont")
        if container is not None:
            return container
    return None


def busan_exprn_location(soup: BeautifulSoup) -> tuple[str, str]:
    location_heading = "\uc704\uce58\uc815\ubcf4"
    address_label = "\uc8fc\uc18c"
    for heading in soup.find_all(["h3", "h4"]):
        if clean_text(heading.get_text(" ", strip=True)) != location_heading:
            continue
        container = heading.find_parent(class_="tabCont")
        if container is None:
            continue
        for label in container.find_all(["h5", "dt", "th"]):
            if busan_exprn_compact_label(label.get_text(" ", strip=True)) != address_label:
                continue
            value_node = label.find_next_sibling()
            if value_node is not None:
                address = clean_text(value_node.get_text(" ", strip=True))
                if address:
                    return address, address
        lines = [clean_text(value) for value in container.stripped_strings if clean_text(value)]
        address = busan_exprn_labeled_value(lines, (address_label,))
        if address:
            return address, address
    return "", ""


def busan_exprn_date_range(value: Any) -> str:
    text = re.sub(
        r"(?<=\d)\s*\([^)]{1,8}\)",
        "",
        clean_text(value),
    )
    return normalize_mixed_date_range(text)


def busan_exprn_clock(meridiem: str, hour: str, minute: str) -> str:
    hour_value = int(hour)
    minute_value = int(minute or "0")
    if meridiem == "\uc624\ud6c4" and hour_value < 12:
        hour_value += 12
    elif meridiem == "\uc624\uc804" and hour_value == 12:
        hour_value = 0
    return f"{hour_value:02d}:{minute_value:02d}"


def busan_exprn_time_ranges(value: Any) -> list[str]:
    text = clean_text(value)
    pattern = re.compile(
        r"(?:(\uc624\uc804|\uc624\ud6c4)\s*)?"
        r"(\d{1,2})\s*(?::\s*(\d{2})|\uc2dc\s*(\d{0,2})\s*\ubd84?)"
        r"\s*(?:~|\uff5e|-|\ubd80\ud130)\s*"
        r"(?:(\uc624\uc804|\uc624\ud6c4)\s*)?"
        r"(\d{1,2})\s*(?::\s*(\d{2})|\uc2dc\s*(\d{0,2})\s*\ubd84?)"
    )
    ranges: list[str] = []
    for match in pattern.finditer(text):
        start_meridiem = clean_text(match.group(1))
        end_meridiem = clean_text(match.group(5)) or start_meridiem
        start = busan_exprn_clock(
            start_meridiem,
            match.group(2),
            match.group(3) or match.group(4),
        )
        end = busan_exprn_clock(
            end_meridiem,
            match.group(6),
            match.group(7) or match.group(8),
        )
        value = f"{start}~{end}"
        if value not in ranges:
            ranges.append(value)
    return ranges


def busan_exprn_enrich_row(row: dict[str, Any], soup: BeautifulSoup) -> None:
    pairs = pairs_from_definition_lists(soup)
    program_section = busan_exprn_program_section(soup)
    program_lines = (
        [clean_text(value) for value in program_section.stripped_strings if clean_text(value)]
        if program_section is not None
        else []
    )
    program_text = clean_text(" ".join(program_lines))
    specific_fee = busan_exprn_rich_fee(program_text) or busan_exprn_labeled_value(
        program_lines,
        (
            "\uc774\uc6a9\ub8cc",
            "\ucc38\uac00\ube44",
            "\uccb4\ud5d8\ube44",
            "\uc7ac\ub8cc\ube44",
            "\ube44\uc6a9",
        ),
    )
    if busan_exprn_compact_label(specific_fee) in {"\ubb34\ub8cc", "\uc720\ub8cc"}:
        specific_fee = busan_exprn_compact_label(specific_fee)
    fee = specific_fee or clean_text(pairs.get("\uc218\uac15\ub8cc"))
    day_text = clean_text(
        pairs.get("\ud504\ub85c\uadf8\ub7a8 \uc6b4\uc601\uc694\uc77c")
        or pairs.get("\uc6b4\uc601\uc694\uc77c")
    )
    time_ranges = busan_exprn_time_ranges(program_text)
    if time_ranges:
        schedule = clean_text(
            " ".join(part for part in [day_text, " / ".join(time_ranges[:8])] if part)
        )
    elif day_text:
        schedule = f"{day_text} \uc2dc\uac04 \ubcc4\ub3c4 \uc548\ub0b4"
    else:
        schedule = "\uc2dc\uac04 \ubcc4\ub3c4 \uc548\ub0b4"

    rich_place = busan_exprn_rich_place(program_text) or busan_exprn_labeled_value(
        program_lines,
        ("\uc7a5\uc18c", "\uccb4\ud5d8\uc7a5\uc18c", "\uc6b4\uc601\uc7a5\uc18c"),
    )
    location_name, address = busan_exprn_location(soup)
    branch = clean_text(pairs.get("\uc6b4\uc601\uae30\uad00")) or clean_text(row.get("branch"))
    target_text = clean_text(pairs.get("\ub300\uc0c1")) or clean_text(row.get("target"))
    period = busan_exprn_date_range(
        clean_text(pairs.get("\uc6b4\uc601\uae30\uac04"))
    ) or clean_text(row.get("period"))
    apply_period = busan_exprn_date_range(
        clean_text(pairs.get("\uc2e0\uccad\uae30\uac04"))
    ) or clean_text(row.get("apply_period"))
    venue = rich_place or clean_text(row.get("venue_name")) or branch or location_name
    application_method = clean_text(pairs.get("\uc2e0\uccad\ubc29\ubc95"))
    raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
    raw_fields.update(
        {
            "detail_pairs": pairs,
            "detail_address": address,
            "detail_time_ranges": time_ranges,
            "parser": BUSAN_EXPRN_PARSER,
        }
    )
    row.update(
        {
            "branch": branch,
            "fee": fee or "\uc694\uae08 \ubcc4\ub3c4 \uc548\ub0b4",
            "period": period or "\uc77c\uc815 \ubcc4\ub3c4 \uc548\ub0b4",
            "apply_period": apply_period,
            "schedule_raw": schedule,
            "target": target_text or "\uc804\uccb4",
            "room": rich_place,
            "venue_name": venue or "\uc7a5\uc18c \ubcc4\ub3c4 \uc548\ub0b4",
            "address": address,
            "venue_address": address,
            "application_method_raw": application_method,
            "description": program_text,
            "raw_fields": raw_fields,
        }
    )


def busan_experience_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    query["srchList"] = ["Y"]
    listed_rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    seen_signatures: set[tuple[tuple[str, str], ...]] = set()
    errors: list[str] = []
    pages = 0
    declared_total = 0
    pagination_complete = False
    malformed_rows = 0
    duplicate_rows = 0

    for page in range(1, max(1, max_pages) + 1):
        query["curPage"] = [str(page)]
        current_url = parsed._replace(
            path="/exprn/list",
            query=urlencode(query, doseq=True),
        ).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        source_rows = [
            tr
            for tr in soup.select("table.boardList tbody tr")
            if tr.select_one("a.reserveItem[onclick*='fn_viewProgrm']")
        ]
        if not source_rows:
            pagination_complete = True
            break

        page_entries: list[tuple[tuple[str, str], dict[str, Any]]] = []
        for tr in source_rows:
            cells = tr.find_all("td", recursive=False)
            link = tr.select_one("a.reserveItem[onclick*='fn_viewProgrm']")
            match = re.search(
                r"fn_viewProgrm\('([^']+)'\s*,\s*'([^']+)'\)",
                clean_text(link.get("onclick") if link else ""),
            )
            if len(cells) < 8 or link is None or match is None:
                malformed_rows += 1
                continue
            title = clean_text(link.get_text(" ", strip=True))
            if not title:
                malformed_rows += 1
                continue
            group_id, program_id = match.groups()
            identity = (group_id, program_id)
            branch = clean_text(cells[2].get_text(" ", strip=True)) or target.branch
            apply_period = busan_exprn_date_range(cells[4].get_text(" ", strip=True))
            period = busan_exprn_date_range(cells[5].get_text(" ", strip=True))
            raw_url = (
                "https://reserve.busan.go.kr/exprn/view?"
                f"{urlencode({'resveGroupSn': group_id, 'progrmSn': program_id})}"
            )
            status = clean_text(cells[7].get_text(" ", strip=True))
            branch_digest = hashlib.sha1(branch.encode("utf-8")).hexdigest()[:12].upper()
            row = {
                "provider": target.provider,
                "provider_course_id": f"{target.provider}:exprn:{group_id}:{program_id}",
                "prefer_incoming_provider_course_id": True,
                "title": title,
                "branch": branch,
                "branch_code": f"BUSAN_EXPRN_{branch_digest}",
                "category": "\uacac\ud559/\uccb4\ud5d8",
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": "\uc694\uae08 \ubcc4\ub3c4 \uc548\ub0b4",
                "period": period or "\uc77c\uc815 \ubcc4\ub3c4 \uc548\ub0b4",
                "apply_period": apply_period,
                "schedule_raw": "\uc2dc\uac04 \ubcc4\ub3c4 \uc548\ub0b4",
                "target": clean_text(cells[3].get_text(" ", strip=True)) or "\uc804\uccb4",
                "venue_name": branch or "\uc7a5\uc18c \ubcc4\ub3c4 \uc548\ub0b4",
                "application_method_raw": clean_text(cells[6].get_text(" ", strip=True)),
                "collection_category": "\uacf5\uacf5\uc608\uc57d",
                "domain_category": "\uccb4\ud5d8\u00b7\uacac\ud559",
                "operator_type": "\uc9c0\uc790\uccb4/\uacf5\uacf5\uae30\uad00",
                "source_group": "public_reservation",
                "service_group": "\uccb4\ud5d8",
                "service_group_policy": "locked",
                "collection_type": "static_html+detail_html",
                "program_type": "\uccb4\ud5d8",
                "reservation_available": not any(
                    token in status for token in ("\ub9c8\uac10", "\uc885\ub8cc")
                ),
                "application_type": "ONLINE_RESERVATION",
                "raw_fields": {
                    "official_reservation_group_id": group_id,
                    "official_program_id": program_id,
                    "list_url": current_url,
                    "parser": BUSAN_EXPRN_PARSER,
                },
            }
            page_entries.append((identity, row))
            serial_text = clean_text(cells[0].get_text(" ", strip=True)).replace(",", "")
            if serial_text.isdigit():
                declared_total = max(declared_total, int(serial_text))

        signature = tuple(identity for identity, _row in page_entries)
        if not signature or signature in seen_signatures:
            errors.append(f"page {page} repeated or omitted its official program identities")
            break
        seen_signatures.add(signature)
        for identity, row in page_entries:
            if identity in seen:
                duplicate_rows += 1
                continue
            seen.add(identity)
            listed_rows.append(row)

        if declared_total and len(seen) >= declared_total:
            pagination_complete = True
            break
        if len(source_rows) < BUSAN_EXPRN_PAGE_SIZE:
            pagination_complete = True
            break
    else:
        errors.append("max_pages cap reached before the official experience list completed")

    if malformed_rows:
        errors.append(f"malformed experience list rows ({malformed_rows})")
    if duplicate_rows:
        errors.append(f"duplicated experience identities ({duplicate_rows})")
    if declared_total and len(seen) != declared_total:
        errors.append(
            f"parsed {len(seen)} unique experiences of {declared_total} declared rows"
        )

    today = datetime.now(ZoneInfo("Asia/Seoul")).date()
    current_rows: list[dict[str, Any]] = []
    expired_count = 0
    for row in listed_rows:
        _start_date, end_date = parse_date_range(clean_text(row.get("period")))
        if end_date and end_date < today:
            expired_count += 1
            continue
        current_rows.append(row)

    detail_attempts = min(max(0, detail_limit), len(current_rows))
    detail_failures: list[str] = []
    detail_pages = 0
    for row in current_rows[:detail_attempts]:
        try:
            detail_soup = fetch_soup(s, clean_text(row.get("raw_url")), timeout=timeout)
            busan_exprn_enrich_row(row, detail_soup)
            detail_pages += 1
        except Exception as exc:
            detail_failures.append(clean_text(row.get("provider_course_id")))
            logger.debug(
                "Busan experience detail failed url=%s error_type=%s",
                safe_url_for_log(row.get("raw_url")),
                type(exc).__name__,
            )

    details_complete = (
        detail_attempts == len(current_rows)
        and not detail_failures
    )
    if detail_attempts < len(current_rows):
        errors.append(
            f"detail enrichment capped at {detail_attempts} of {len(current_rows)} current experiences"
        )
    if detail_failures:
        errors.append(f"detail fetch or parse failed for {len(detail_failures)} experiences")

    missing_required: dict[str, list[str]] = {}
    for row in current_rows:
        missing = [
            field
            for field in (
                "target",
                "fee",
                "period",
                "venue_name",
                "category",
                "schedule_raw",
            )
            if not clean_text(row.get(field))
        ]
        if missing:
            missing_required[clean_text(row.get("provider_course_id"))] = missing
    if missing_required:
        errors.append(f"required fields missing for {len(missing_required)} experiences")

    snapshot_complete = pagination_complete and details_complete and not errors
    meta: dict[str, Any] = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(seen),
        "reservation_discovery_links": len(current_rows),
        "reservation_fallback_pages": 0,
        "total_count": declared_total or len(seen),
        "current_count": len(current_rows),
        "expired_count": expired_count,
        "pagination_detected": pages > 1 or (declared_total > BUSAN_EXPRN_PAGE_SIZE),
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "missing_required": missing_required,
        "no_current_data": snapshot_complete and not current_rows,
        "no_current_reason": (
            "official experience list contains no current/future programs"
            if snapshot_complete and not current_rows
            else ""
        ),
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(current_rows), BUSAN_EXPRN_PARSER, meta


def collect_busan_reserve_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 20,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if urlparse(target.url).path.startswith("/exprn"):
        return busan_experience_list(
            target,
            timeout=timeout,
            max_pages=max_pages,
            detail_limit=detail_limit,
        )
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)

    for page in range(1, max_pages + 1):
        query["curPage"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for item in soup.select("ul.reserveList > li"):
            title_el = item.select_one(".tit")
            title = clean_text(title_el.get("title") if title_el else "") or clean_text(title_el.get_text(" ", strip=True) if title_el else "")
            if not title:
                continue
            link = item.select_one("a.reserveItem")
            onclick = clean_text(link.get("onclick") if link else "")
            match = re.search(r"fn_viewProgrm\('([^']+)'\s*,\s*'([^']+)'\)", onclick)
            if match:
                raw_url = urljoin(target.url, f"/lctre/view?resveGroupSn={match.group(1)}&progrmSn={match.group(2)}")
            else:
                raw_url = current_url
            pairs = pairs_from_definition_lists(item)
            detail_pairs: dict[str, str] = {}
            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pairs = pairs_from_definition_lists(detail_soup)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("Busan reserve detail fetch failed %s: %s", raw_url, exc)
            date_text = clean_text(pairs.get("일자") or "")
            apply_match = re.search(r"\[신청\]\s*([0-9.\-~\s]+)", date_text)
            period_match = re.search(r"\[행사\]\s*([0-9.\-~\s]+)", date_text)
            period = normalize_mixed_date_range(detail_pairs.get("운영기간", ""))
            if not period and period_match:
                period = normalize_mixed_date_range(clean_text(period_match.group(1)))
            apply_period = normalize_mixed_date_range(detail_pairs.get("신청기간", ""))
            if not apply_period and apply_match:
                apply_period = normalize_mixed_date_range(clean_text(apply_match.group(1)))
            time_text = clean_text(detail_pairs.get("요일 / 시간") or detail_pairs.get("요일/시간"))
            schedule_raw = clean_text(" ".join(part for part in [period, time_text] if part))
            branch = clean_text(detail_pairs.get("\uC6B4\uC601\uAE30\uAD00") or pairs.get("\uC6B4\uC601\uAE30\uAD00") or target.branch)
            image = item.find("img")
            image_url = normalize_link(current_url, image.get("src") if image else None)
            if image_url and "reserve_noimg" in image_url:
                image_url = ""
            status = clean_text((item.select_one(".statusMark") or {}).get_text(" ", strip=True) if item.select_one(".statusMark") else "")
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "branch_code": re.sub(r"[^A-Za-z0-9가-힣]+", "_", branch).strip("_")[:80],
                    "category": "강좌/교육",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": clean_text(detail_pairs.get("\uC218\uAC15\uB8CC") or pairs.get("\uC218\uAC15\uB8CC")),
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule_raw,
                    "target": clean_text(detail_pairs.get("\uAD50\uC721\uB300\uC0C1") or pairs.get("\uAD50\uC721\uB300\uC0C1") or pairs.get("대상")),
                    "room": clean_text(pairs.get("장소")),
                    "venue_name": clean_text(pairs.get("장소")),
                    "application_method_raw": clean_text(detail_pairs.get("\uC811\uC218\uBC29\uBC95") or pairs.get("\uC811\uC218\uBC29\uBC95")),
                    "description": clean_text(item.get_text(" ", strip=True)),
                    "image_url": image_url,
                    "collection_category": "공공예약",
                    "domain_category": "평생교육",
                    "operator_type": "지자체/공공기관",
                    "source_group": "public_reservation",
                    "collection_type": "static_html",
                        "program_type": "\uAC15\uC88C",
                    "reservation_available": "접수" in status and "마감" not in status,
                    "application_type": "ONLINE_RESERVATION",
                    "raw_fields": {"pairs": pairs, "detail_pairs": detail_pairs, "parser": "busan_reserve_list+detail"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='curPage=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "busan_reserve_list+detail", meta


GEOJE_LIBRARY_LIST_URL = "https://lib.geoje.go.kr/com/requestPage.do?selMenuNo=104030200&returnUrl=/culture/d030200.do"
GEOJE_LIBRARY_BRANCHES = {
    "하청": {"name": "거제시립하청도서관", "phone": "055-639-3921"},
    "아주": {"name": "거제시립아주도서관", "phone": "055-639-7320"},
    "옥포": {"name": "거제시립옥포도서관", "phone": "055-639-3881"},
    "장승포": {"name": "거제시립장승포도서관", "phone": "055-639-3871"},
    "장평": {"name": "거제시립장평도서관", "phone": "055-639-3861"},
    "수양": {"name": "거제시립수양도서관", "phone": "055-639-3891"},
}


def geoje_library_branch(label: str) -> dict[str, str]:
    key = clean_text(label)
    return GEOJE_LIBRARY_BRANCHES.get(key, {"name": f"거제시립{key}도서관" if key else "거제시립도서관", "phone": ""})


def geoje_library_branch_from_detail(label: str) -> dict[str, str]:
    text = clean_text(label)
    key = re.sub(r"^(?:거제)?(?:시립)?", "", text)
    key = re.sub(r"도서관$", "", key)
    return geoje_library_branch(key)


def geoje_status_code_from_onclick(onclick: str) -> str:
    match = re.search(r"couDetail\('([^']+)'\s*,\s*'([^']+)'\)", clean_text(onclick))
    return match.group(2) if match else ""


def geoje_course_id_from_onclick(onclick: str) -> str:
    match = re.search(r"couDetail\('([^']+)'\s*,\s*'([^']+)'\)", clean_text(onclick))
    return match.group(1) if match else ""


def geoje_capacity_parts(value: str) -> tuple[str, str, str]:
    text = clean_text(value)
    capacity = ""
    waitlist = ""
    current = ""
    match = re.search(r"(\d+)\s*/\s*(\d+)", text)
    if match:
        capacity, waitlist = match.group(1), match.group(2)
    current_match = re.search(r"(?:신청|접수|현재)\s*인원\s*:\s*(\d+)", text)
    if current_match:
        current = current_match.group(1)
    return capacity, waitlist, current


def geoje_calendar_start_year_month(
    target_url: str,
    *,
    reference_date: date | None = None,
) -> tuple[int, int]:
    """Return the current Geoje calendar month in its zero-based format.

    The official route embeds ``year``/``month`` in ``returnUrl``.  Those
    values are only the month that happened to be open when the target was
    registered; treating them as configuration makes the six-month crawl
    window permanently stale.  Keep ``target_url`` in the signature because
    it identifies the calendar route, but anchor every operational crawl to
    today's month in Korea.
    """

    _ = target_url
    current = reference_date or datetime.now(ZoneInfo("Asia/Seoul")).date()
    return current.year, current.month - 1


def geoje_calendar_url(year: int, zero_based_month: int) -> str:
    while zero_based_month > 11:
        year += 1
        zero_based_month -= 12
    while zero_based_month < 0:
        year -= 1
        zero_based_month += 12
    return (
        "https://lib.geoje.go.kr/com/requestPage.do?selMenuNo=104010000"
        f"&returnUrl=/culture/d010200.do?year={year}&month={zero_based_month}"
    )


def normalize_geoje_calendar_period(value: str) -> str:
    text = clean_text(value)
    match = re.search(
        r"(\d{4})-(\d{1,2})-(\d{1,2})\s*부터\s*(\d{4})-(\d{1,2})-(\d{1,2})\s*까지",
        text,
    )
    if match:
        return (
            f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
            f" ~ {match.group(4)}-{int(match.group(5)):02d}-{int(match.group(6)):02d}"
        )
    return normalize_mixed_date_range(text)


def normalize_geoje_calendar_time(value: str) -> str:
    text = clean_text(value)
    match = re.search(r"(\d{1,2}:\d{2})\s*부터\s*(\d{1,2}:\d{2})\s*까지", text)
    if match:
        return f"{match.group(1)} ~ {match.group(2)}"
    return text


def geoje_calendar_target_from_text(*values: str) -> str:
    text = clean_text(" ".join(clean_text(value) for value in values if clean_text(value)))
    common = clean_text(extract_target_text(text) or "")
    if common:
        return common
    patterns = (
        r"\d{4}\s*~\s*\d{4}\s*년생",
        r"\d{2}\s*~\s*\d{2}\s*년생",
        r"\d+\s*~\s*\d+\s*세",
        r"초등\s*\d\s*~\s*\d\s*학년",
        r"초등\s*\d\s*-\s*\d\s*학년",
        r"초등\s*\d\s*학년",
        r"성인",
        r"어린이",
        r"유아",
        r"청소년",
    )
    matches: list[str] = []
    for pattern in patterns:
        for match in re.finditer(pattern, text):
            value = clean_text(match.group(0))
            value = re.sub(r"\s*([~-])\s*", r"\1", value)
            if value and value not in matches:
                matches.append(value)
    return clean_text(", ".join(matches[:4]))


def geoje_calendar_detail_row(
    target: CrawlTarget,
    s: requests.Session,
    raw_url: str,
    fallback_title: str,
    timeout: int,
) -> dict[str, Any]:
    soup = fetch_soup(s, raw_url, timeout=timeout)
    table = soup.select_one("table.boardView") or soup.select_one("table")
    pairs = pairs_from_tables(table or soup)
    title = fallback_title
    if table:
        first_row = table.select_one("tr")
        if first_row:
            first_text = clean_text(first_row.get_text(" ", strip=True))
            if first_text and first_text not in pairs:
                title = first_text
    library_label = clean_text(pairs.get("도서관명"))
    branch_info = geoje_library_branch_from_detail(library_label)
    branch = branch_info["name"]
    period = normalize_geoje_calendar_period(pairs.get("행사기간", ""))
    time_text = normalize_geoje_calendar_time(pairs.get("행사시간", ""))
    description = clean_text(pairs.get("행사내용"))
    target_text = geoje_calendar_target_from_text(description, title)
    schedule_raw = clean_text(" ".join(part for part in [period, time_text] if part))
    raw_query = parse_qs(urlparse(raw_url).query)
    nested_query = parse_qs(urlparse(clean_text((raw_query.get("returnUrl") or [""])[0])).query)
    event_id = clean_text((raw_query.get("schdulId") or nested_query.get("schdulId") or [""])[0])
    return {
        "provider": target.provider,
        "provider_course_id": event_id or stable_course_id(target.provider, raw_url, title, period),
        "title": title,
        "branch": branch,
        "branch_code": branch,
        "preserve_branch": True,
        "category": "도서관 행사",
        "category_raw": "이달의 행사",
        "collection_category": "도서관",
        "domain_category": "도서관",
        "source_group": "library",
        "operator_type": "지자체/도서관",
        "collection_type": "calendar_html+detail",
        "program_type": "행사",
        "raw_url": raw_url,
        "application_url": raw_url,
        "status": "",
        "fee": "",
        "period": period,
        "schedule_raw": schedule_raw,
        "target": target_text,
        "room": clean_text(pairs.get("행사장소")),
        "venue_name": clean_text(pairs.get("행사장소")) or branch,
        "description": description,
        "contact": branch_info.get("phone", ""),
        "raw_fields": {"detail_pairs": pairs, "event_id": event_id, "parser": "geoje_library_calendar+detail"},
    }


def collect_geoje_calendar_events(
    target: CrawlTarget,
    s: requests.Session,
    timeout: int,
    max_months: int,
    *,
    reference_date: date | None = None,
) -> tuple[list[dict[str, Any]], int, int]:
    start_year, start_month = geoje_calendar_start_year_month(
        target.url,
        reference_date=reference_date,
    )
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    seen: set[str] = set()
    for offset in range(max(1, max_months)):
        current_url = geoje_calendar_url(start_year, start_month + offset)
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        for link in soup.select("table.calendar a[href]"):
            raw_url = normalize_link(current_url, link.get("href"))
            title = clean_text(link.get_text(" ", strip=True))
            if not raw_url or "d010200_view.do" not in raw_url or raw_url in seen:
                continue
            seen.add(raw_url)
            try:
                rows.append(geoje_calendar_detail_row(target, s, raw_url, title, timeout=timeout))
                detail_pages += 1
            except Exception as exc:
                logger.debug("Geoje calendar detail fetch failed %s: %s", raw_url, exc)
    return rows, pages, detail_pages


def collect_geoje_library_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    calendar_pages = 0
    detail_pages = 0
    pagination_detected = False
    pagination_exhausted = False
    page_limit = max(1, max_pages)

    calendar_rows, calendar_pages, detail_pages = collect_geoje_calendar_events(
        target,
        s,
        timeout=timeout,
        max_months=min(page_limit, 6),
    )
    rows.extend(calendar_rows)

    for page in range(1, page_limit + 1):
        data = {
            "currentPageNo": str(page),
            "cou_lib": "",
            "COURSE_ID": "",
            "searchStartDate": "",
            "searchEndDate": "",
            "cou_search": "b_subject",
            "search_txt": "",
            "cou_all": "전체",
        }
        response = s.post(GEOJE_LIBRARY_LIST_URL, data=data, timeout=timeout)
        response.raise_for_status()
        response.encoding = response.encoding or "utf-8"
        soup = BeautifulSoup(response.text, "lxml")
        pages += 1
        page_rows = 0
        for tr in soup.select("table.tbl-type01 tbody tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
            if len(cells) < 7:
                continue
            branch_label, title, target_text, capacity_text, period, apply_period, status = cells[:7]
            title_link = tr.select_one("td.td_left a") or tr.find("a")
            onclick = clean_text(title_link.get("href") if title_link else "")
            course_id = geoje_course_id_from_onclick(onclick) or stable_course_id(target.provider, str(page), title, branch_label)
            status_code = geoje_status_code_from_onclick(onclick)
            branch_info = geoje_library_branch(branch_label)
            branch = branch_info["name"]
            capacity, waitlist, current = geoje_capacity_parts(capacity_text)
            raw_url = f"{GEOJE_LIBRARY_LIST_URL}#course={course_id}"
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": course_id,
                    "title": title,
                    "branch": branch,
                    "branch_code": branch,
                    "preserve_branch": True,
                    "category": "도서관 문화강좌",
                    "category_raw": branch_label,
                    "collection_category": "도서관",
                    "domain_category": "도서관",
                    "source_group": "library",
                    "operator_type": "지자체/도서관",
                    "collection_type": "static_html",
                    "raw_url": raw_url,
                    "application_url": GEOJE_LIBRARY_LIST_URL,
                    "status": status,
                    "period": normalize_mixed_date_range(period),
                    "apply_period": normalize_mixed_date_range(apply_period),
                    "schedule_raw": period,
                    "target": target_text,
                    "eligibility_raw": target_text,
                    "fee": "무료",
                    "capacity": capacity,
                    "waitlist_capacity": waitlist,
                    "capacity_current": current,
                    "contact": branch_info.get("phone", ""),
                    "venue_name": branch,
                    "description": clean_text(tr.get_text(" ", strip=True)),
                    "reservation_available": "접수" in status and "마감" not in status,
                    "raw_fields": {"cells": cells, "course_id": course_id, "status_code": status_code, "parser": "geoje_library_course_table"},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(re.search(r"paging\(\s*\d+\s*\)", response.text))
        if page_rows == 0:
            pagination_exhausted = True
            break

    complete = pagination_exhausted
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_exhausted": pagination_exhausted,
        "pagination_complete": complete,
        "recursion_depth": 0,
        "calendar_pages": calendar_pages,
        "calendar_events": len(calendar_rows),
        "no_current_data": not rows and complete,
        "no_current_reason": (
            "no_current_geoje_library_courses_or_calendar_events"
            if not rows and complete
            else ""
        ),
    }
    return dedupe_rows(rows), "geoje_library_calendar+course_table", meta


def yeonsu_edu_status(value: str) -> str:
    text = clean_text(value)
    if any(token in text for token in ("접수가능", "접수중", "방문접수중", "대기접수중")):
        return "접수중"
    if any(token in text for token in ("신청예정", "접수예정")):
        return "접수예정"
    if any(token in text for token in ("신청마감", "접수마감", "마감", "종료")):
        return "접수마감"
    return text


def yeonsu_edu_normalize_range(value: str, reference_period: str = "") -> str:
    text = clean_text(value).lstrip(":").strip()
    normalized = normalize_mixed_date_range(text)
    if normalized != text:
        return normalized
    match = re.search(r"(\d{1,2})[.](\d{1,2})\s*~\s*(\d{1,2})[.](\d{1,2})", text)
    if not match:
        return text
    reference_match = re.search(r"(\d{4})-(\d{1,2})-(\d{1,2})", reference_period)
    reference_year = int(reference_match.group(1)) if reference_match else datetime.now().year
    reference_month = int(reference_match.group(2)) if reference_match else 0
    start_month = int(match.group(1))
    start_day = int(match.group(2))
    end_month = int(match.group(3))
    end_day = int(match.group(4))
    start_year = reference_year + 1 if reference_month >= 10 and start_month < reference_month else reference_year
    end_year = start_year + 1 if end_month < start_month else start_year
    return f"{start_year}-{start_month:02d}-{start_day:02d} ~ {end_year}-{end_month:02d}-{end_day:02d}"


def yeonsu_edu_period_and_schedule(value: str, reference_period: str = "") -> tuple[str, str]:
    text = clean_text(value)
    schedule = ""
    schedule_match = re.search(r"\(([^)]*(?:매주|월|화|수|목|금|토|일|\d{1,2}:\d{2})[^)]*)\)", text)
    if schedule_match:
        schedule = clean_text(schedule_match.group(1))
        text = clean_text(text.replace(schedule_match.group(0), ""))
    return yeonsu_edu_normalize_range(text, reference_period), schedule


def yeonsu_edu_card_pairs(card: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in card.select("dd li"):
        key_node = item.select_one(".q")
        value_node = item.select_one(".a")
        key = clean_text(key_node.get_text(" ", strip=True) if key_node else "")
        if not key or not value_node:
            continue
        status_node = value_node.select_one(".lec_state")
        status = clean_text(status_node.get_text(" ", strip=True) if status_node else "")
        value = clean_text(value_node.get_text(" ", strip=True)).replace(status, "", 1)
        pairs[key] = clean_text(value.lstrip(":").strip())
        if status:
            pairs["상태"] = status
    return pairs


def yeonsu_edu_capacity(value: str) -> tuple[Optional[int], Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    current = total = wait_current = wait_total = None
    for label, used, limit in re.findall(r"([가-힣]+)\s*\[\s*(\d+)\s*/\s*(\d+)\s*\]", text):
        used_int = int(used)
        limit_int = int(limit)
        if "대기" in label:
            wait_current = (wait_current or 0) + used_int
            wait_total = (wait_total or 0) + limit_int
        else:
            current = (current or 0) + used_int
            total = (total or 0) + limit_int
    return current, total, wait_current, wait_total


def yeonsu_edu_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    board = soup.select_one(".board_view") or soup.select_one("#detail_con") or soup
    pairs = pairs_from_definition_lists(board)
    title_node = board.select_one(".board_title")
    status_node = title_node.select_one(".state") if title_node else None
    status_text = clean_text(status_node.get_text(" ", strip=True) if status_node else "")
    title_text = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    title = clean_text(title_text.replace(status_text, "", 1))
    apply_period = yeonsu_edu_normalize_range(pairs.get("신청기간", ""))
    period, schedule = yeonsu_edu_period_and_schedule(pairs.get("교육기간", ""), apply_period)
    capacity_current, capacity_total, wait_current, wait_total = yeonsu_edu_capacity(pairs.get("신청현황", ""))
    return {
        "title": title,
        "status": yeonsu_edu_status(status_text),
        "target": clean_text(pairs.get("교육대상")),
        "course_round": clean_text(pairs.get("기수")),
        "fee": clean_text(pairs.get("수강료")),
        "capacity": clean_text(pairs.get("신청현황")),
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_current": wait_current,
        "waitlist_total": wait_total,
        "apply_period": apply_period,
        "period": period,
        "schedule_raw": schedule,
        "branch": clean_text(pairs.get("교육기관")),
        "venue_name": clean_text(pairs.get("교육기관")),
        "room": clean_text(pairs.get("교육장소")),
        "venue_address": clean_text(pairs.get("찾아오시는길")),
        "phone": clean_text(pairs.get("문의전화")),
        "sessions": parse_capacity_number(pairs.get("총수강일수")),
        "description": clean_text(pairs.get("강좌소개")),
        "instructor": clean_text(pairs.get("강사명")),
        "application_method_raw": clean_text(pairs.get("인원제한방법")),
        "raw_detail_pairs": pairs,
    }


def yeonsu_edu_list_url(target_url: str) -> str:
    parsed = urlparse(target_url)
    query = parse_qs(parsed.query)
    if query.get("page") == ["v"] or "lec_idx" in query:
        return (
            f"{parsed.scheme}://{parsed.netloc}/edu/sub/apply.asp?"
            "gotopage=1&edu_kind=&team_idx=&strMode=&strCode=0&strKind=&strSearch=&strSearch01=&strSearch02=&s_target=&s_date=&e_date="
        )
    return target_url


def collect_yeonsu_edu_apply(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    base_url = yeonsu_edu_list_url(target.url)
    parsed = urlparse(base_url)
    base_query = parse_qs(parsed.query)

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["gotopage"] = [str(page)]
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_rows = 0
        list_root = soup.select_one(".donglec_list")
        if not list_root:
            break
        for card in list_root.select(":scope > ul > li"):
            link = card.find("a", href=True)
            title_node = card.select_one("dt p")
            title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
            if not link or not title:
                continue
            raw_url = normalize_link(page_url, link.get("href")) or page_url
            pairs = yeonsu_edu_card_pairs(card)
            status = yeonsu_edu_status(pairs.get("상태", ""))
            apply_period = yeonsu_edu_normalize_range(pairs.get("신청기간", ""))
            period, schedule = yeonsu_edu_period_and_schedule(pairs.get("교육기간", ""), apply_period)
            branch = clean_text(pairs.get("교육기관")) or target.branch
            detail: dict[str, Any] = {}
            if raw_url and detail_pages < detail_limit:
                try:
                    detail = yeonsu_edu_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("yeonsu edu detail fetch failed %s: %s", raw_url, exc)
            detail_status = clean_text(detail.get("status"))
            final_status = detail_status or status
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": clean_text(detail.get("title")) or title,
                "branch": clean_text(detail.get("branch")) or branch,
                "branch_code": stable_provider(target.provider[:32], clean_text(detail.get("branch")) or branch),
                "category": "주민자치센터 프로그램",
                "raw_url": raw_url,
                "application_url": raw_url if final_status in {"접수중", "접수예정"} else "",
                "status": final_status,
                "period": clean_text(detail.get("period")) or period,
                "apply_period": clean_text(detail.get("apply_period")) or apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")) or schedule,
                "target": clean_text(detail.get("target")),
                "fee": clean_text(detail.get("fee")) or clean_text(pairs.get("수강료")),
                "capacity": clean_text(detail.get("capacity")),
                "capacity_current": detail.get("capacity_current"),
                "capacity_total": detail.get("capacity_total"),
                "waitlist_current": detail.get("waitlist_current"),
                "waitlist_total": detail.get("waitlist_total"),
                "room": clean_text(detail.get("room")),
                "venue_name": clean_text(detail.get("venue_name")) or branch,
                "venue_address": clean_text(detail.get("venue_address")),
                "phone": clean_text(detail.get("phone")),
                "sessions": detail.get("sessions"),
                "description": clean_text(detail.get("description")) or clean_text(card.get_text(" ", strip=True)),
                "instructor": clean_text(detail.get("instructor")),
                "application_method_raw": clean_text(detail.get("application_method_raw")),
                "raw_fields": {
                    "parser": "yeonsu_edu_apply_list+detail",
                    "list_pairs": pairs,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                    "page_url": page_url,
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(list_root.select(".paging a[href], a[href*='gotopage=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "yeonsu_edu_apply_list+detail", meta


def bucheon_reservation_status(value: str) -> str:
    text = clean_text(value)
    if not text:
        return ""
    if "접수중" in text or "접수가능" in text or "신청중" in text or "신청가능" in text:
        return "접수중"
    if "교육중" in text or "운영중" in text or "진행중" in text:
        return "진행중"
    if "예정" in text or "대기" in text:
        return "접수예정"
    if "마감" in text or "종료" in text or "신청종료" in text:
        return "접수마감"
    return normalize_status(text) or text


def bucheon_reservation_datetime_range(value: str) -> str:
    text = clean_text(value)
    if not text:
        return ""
    matches = list(
        re.finditer(
            r"(\d{4})[.-](\d{1,2})[.-](\d{1,2})[.]?\s*(?:\([^)]+\))?\s*(\d{1,2}:\d{2})?",
            text,
        )
    )
    if not matches:
        return normalize_mixed_date_range(text)

    def fmt(match: re.Match[str]) -> str:
        date_text = f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
        time_text = clean_text(match.group(4))
        return f"{date_text} {time_text}" if time_text else date_text

    if len(matches) >= 2:
        return f"{fmt(matches[0])} ~ {fmt(matches[1])}"
    return fmt(matches[0])


