def bcl_branch_name(value: str) -> str:
    text = clean_text(value)
    if not text:
        return "부천시립도서관"
    text = clean_text(re.sub(r"^\s*(?:대면|비대면|온라인)\s*[_-]?", "", text))
    text = clean_text(re.sub(r"^\(?직영\)?", "", text))
    text = text.strip("[]() ")
    if "/" in text:
        text = clean_text(text.split("/", 1)[0])
    if text in BCL_BRANCH_ALIASES:
        return BCL_BRANCH_ALIASES[text]
    if text.endswith("도서관"):
        return text
    return f"{text}도서관"


def bcl_branch_hint_from_title(title: str, fallback: str) -> str:
    text = clean_text(title)
    match = re.match(r"^\[([^\]]+)\]", text)
    if not match:
        return fallback
    label = clean_text(match.group(1))
    for token in ("신흥어울마당작은", "행복한", "별빛마루", "역곡밝은"):
        if token in label:
            return token
    label = re.sub(r"^(?:대면|비대면|온라인)\s*[_-]?", "", label)
    label = clean_text(label.replace("(직영)", "").replace("직영", ""))
    return label or fallback


def bcl_split_periods(value: str) -> tuple[str, str]:
    text = clean_text(value)
    apply_period = ""
    period = ""
    apply_match = re.search(r"신청\s*[:：]\s*(.*?)(?=\s*교육\s*[:：]|$)", text)
    period_match = re.search(r"교육\s*[:：]\s*(.*)$", text)
    if apply_match:
        apply_period = bucheon_reservation_datetime_range(apply_match.group(1))
    if period_match:
        period = bucheon_reservation_datetime_range(period_match.group(1))
    if not apply_period and not period:
        period = bucheon_reservation_datetime_range(text)
    return apply_period, period


def bcl_capacity_pair(value: str) -> tuple[Optional[int], Optional[int]]:
    numbers = re.findall(r"\d+", clean_text(value).replace(",", ""))
    if len(numbers) >= 2:
        return int(numbers[0]), int(numbers[1])
    if len(numbers) == 1:
        return int(numbers[0]), None
    return None, None


def bcl_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    table = soup.select_one("table")
    pairs = pairs_from_tables(table or soup)
    room_raw = clean_text(pairs.get("강의실"))
    branch_hint = clean_text(room_raw.split("/", 1)[0]) if room_raw else ""
    room = clean_text(room_raw.split("/", 1)[1]) if "/" in room_raw else room_raw
    if not branch_hint:
        contact = clean_text(pairs.get("문의"))
        contact_match = re.search(r"([가-힣A-Za-z0-9]+도서관)", contact)
        branch_hint = clean_text(contact_match.group(1)) if contact_match else ""
    capacity_total, waitlist_total = bcl_capacity_pair(pairs.get("정원/대기", ""))
    capacity_current, waitlist_current = bcl_capacity_pair(pairs.get("신청자/대기자", ""))
    period = bucheon_reservation_datetime_range(pairs.get("운영시간", ""))
    schedule_time = clean_text(pairs.get("요일/시간"))
    phone_match = re.search(r"\d{2,3}-\d{3,4}-\d{4}", clean_text(pairs.get("문의")))
    return {
        "title": clean_text(pairs.get("강좌명")),
        "status": bucheon_reservation_status(pairs.get("상태", "")),
        "apply_period": bucheon_reservation_datetime_range(pairs.get("신청기간", "")),
        "period": period,
        "schedule_raw": clean_text(" ".join(part for part in [period, schedule_time] if part)),
        "target": clean_text(pairs.get("수강대상")),
        "fee": clean_text(pairs.get("수강료")),
        "material_fee": clean_text(pairs.get("재료비 및 교재비")),
        "capacity_total": capacity_total,
        "waitlist_total": waitlist_total,
        "capacity_current": capacity_current,
        "waitlist_current": waitlist_current,
        "application_method_raw": clean_text(pairs.get("모집방법")),
        "branch": bcl_branch_name(branch_hint),
        "room": room,
        "venue_name": bcl_branch_name(branch_hint),
        "phone": clean_text(phone_match.group(0)) if phone_match else clean_text(pairs.get("문의")),
        "description": clean_text(" | ".join(f"{key}: {value}" for key, value in pairs.items() if clean_text(value))),
        "raw_detail_pairs": pairs,
    }


def collect_bcl_library_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    pagination_exhausted = False
    parsed = urlparse(target.url)
    base_query = parse_qs(parsed.query)

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["currentpage"] = [str(page)]
        query["pagesize"] = [clean_text((base_query.get("pagesize") or base_query.get("pageSize") or ["10"])[0]) or "10"]
        page_size = int(query["pagesize"][0])
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        table = None
        for candidate in soup.select("table"):
            headers = [clean_text(th.get_text(" ", strip=True)) for th in candidate.select("th")]
            if {"강좌명", "운영도서관", "대상", "기간", "정원", "상태"}.issubset(set(headers)):
                table = candidate
                break
        if not table:
            break
        page_rows = 0
        for tr in table.select("tbody tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td", recursive=False)]
            if len(cells) < 6:
                continue
            link = tr.find("a", href=True)
            title = clean_text(link.get_text(" ", strip=True) if link else cells[0])
            if not title or title == "강좌명":
                continue
            raw_url = normalize_link(page_url, link.get("href") if link else None) or page_url
            branch_hint = bcl_branch_hint_from_title(title, cells[1])
            branch = bcl_branch_name(branch_hint)
            apply_period, period = bcl_split_periods(cells[3])
            status = bucheon_reservation_status(cells[5])
            capacity_total = parse_capacity_number(cells[4])
            detail: dict[str, Any] = {}
            if raw_url and detail_pages < max(0, detail_limit):
                try:
                    detail = bcl_detail_fields(s, raw_url, timeout=timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("bcl lecture detail fetch failed %s: %s", raw_url, exc)
            final_branch = clean_text(detail.get("branch")) or branch
            final_status = clean_text(detail.get("status")) or status
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, final_branch),
                "title": clean_text(detail.get("title")) or title,
                "branch": final_branch,
                "branch_code": stable_provider(target.provider[:32], final_branch),
                "preserve_branch": True,
                "category": "도서관 문화강좌",
                "collection_category": "도서관",
                "domain_category": "도서관",
                "source_group": "library",
                "operator_type": "교육청/도서관",
                "collection_type": "static_html+detail",
                "program_type": "강좌",
                "raw_url": raw_url,
                "application_url": raw_url if final_status in {"접수중", "접수예정"} else "",
                "status": final_status,
                "period": clean_text(detail.get("period")) or period,
                "apply_period": clean_text(detail.get("apply_period")) or apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")),
                "target": clean_text(detail.get("target")) or cells[2],
                "fee": clean_text(detail.get("fee")),
                "material_fee": clean_text(detail.get("material_fee")),
                "capacity": cells[4],
                "capacity_total": detail.get("capacity_total") if detail.get("capacity_total") is not None else capacity_total,
                "capacity_current": detail.get("capacity_current"),
                "waitlist_total": detail.get("waitlist_total"),
                "waitlist_current": detail.get("waitlist_current"),
                "room": clean_text(detail.get("room")),
                "venue_name": clean_text(detail.get("venue_name")) or final_branch,
                "phone": clean_text(detail.get("phone")),
                "description": clean_text(detail.get("description")) or clean_text(tr.get_text(" ", strip=True)),
                "application_method_raw": clean_text(detail.get("application_method_raw")),
                "raw_fields": {
                    "parser": "bcl_library_lecture_table+detail",
                    "cells": cells,
                    "page_url": page_url,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination a[href], .paging a[href], a[href*='currentpage=']"))
        if page_rows == 0:
            pagination_exhausted = True
            break
        if len(table.select("tbody tr")) < page_size:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "bcl_library_lecture_table+detail", meta


