def is_sacheon_education_target(url: str) -> bool:
    parsed = urlparse(clean_text(url))
    if (
        parsed.scheme.lower() != "https"
        or parsed.netloc.lower() != SACHEON_EDU_HOST
        or parsed.path != SACHEON_EDU_LIST_PATH
        or parsed.params
        or parsed.fragment
    ):
        return False
    query = parse_qs(parsed.query, keep_blank_values=True)
    if not set(query).issubset({"cpage"}) or any(len(values) != 1 for values in query.values()):
        return False
    if "cpage" in query and not re.fullmatch(r"[1-9]\d*", clean_text(query["cpage"][0])):
        return False
    return True


def sacheon_education_list_url(page: int) -> str:
    return f"{SACHEON_EDU_LIST_URL}?{urlencode({'cpage': max(1, int(page))})}"


def sacheon_education_detail_url(
    lecture_idx: Any,
    route_path: Any = SACHEON_EDU_LIST_PATH,
) -> str:
    value = clean_text(lecture_idx)
    path = clean_text(route_path)
    if not re.fullmatch(r"\d{1,12}", value) or path not in SACHEON_EDU_OWNED_LECTURE_PATHS:
        return ""
    return f"https://{SACHEON_EDU_HOST}{path}?{urlencode({'amode': 'view', 'idx': value})}"


def sacheon_education_application_url(
    lecture_idx: Any,
    route_path: Any = SACHEON_EDU_LIST_PATH,
    application_mode: Any = "",
) -> str:
    value = clean_text(lecture_idx)
    path = clean_text(route_path)
    mode = clean_text(application_mode) or (
        "ins" if path == SACHEON_EDU_LIFELONG_PATH else "ins_realname"
    )
    if (
        not re.fullmatch(r"\d{1,12}", value)
        or path not in SACHEON_EDU_OWNED_LECTURE_PATHS
        or mode not in SACHEON_EDU_APPLICATION_MODES[path]
    ):
        return ""
    return f"https://{SACHEON_EDU_HOST}{path}?{urlencode({'amode': mode, 'lecIdx': value})}"


def sacheon_education_link_identity(
    page_url: str,
    href: Any,
    *,
    application: bool = False,
) -> tuple[str, str, str]:
    linked_url = urljoin(page_url, clean_text(href))
    parsed = urlparse(linked_url)
    query = parse_qs(parsed.query, keep_blank_values=True)
    identity_key = "lecIdx" if application else "idx"
    allowed_keys = {"amode", identity_key, "cpage", "facCode"}
    mode = clean_text((query.get("amode") or [""])[0])
    if (
        parsed.scheme.lower() != "https"
        or parsed.netloc.lower() != SACHEON_EDU_HOST
        or parsed.path not in SACHEON_EDU_OWNED_LECTURE_PATHS
        or parsed.params
        or parsed.fragment
        or not set(query).issubset(allowed_keys)
        or any(len(values) != 1 for values in query.values())
        or (application and mode not in SACHEON_EDU_APPLICATION_MODES[parsed.path])
        or (not application and mode != "view")
    ):
        return "", "", ""
    value = clean_text((query.get(identity_key) or [""])[0])
    if not re.fullmatch(r"\d{1,12}", value):
        return "", "", ""
    page_value = clean_text((query.get("cpage") or [""])[0])
    if page_value and not re.fullmatch(r"[1-9]\d*", page_value):
        return "", "", ""
    facility_code = clean_text((query.get("facCode") or [""])[0])
    if facility_code and not re.fullmatch(r"\d{1,12}", facility_code):
        return "", "", ""
    return value, parsed.path, mode


def sacheon_education_link_idx(page_url: str, href: Any, *, application: bool = False) -> str:
    value, _path, _mode = sacheon_education_link_identity(
        page_url,
        href,
        application=application,
    )
    return value


def sacheon_education_page_declaration(
    soup: BeautifulSoup,
) -> tuple[Optional[int], Optional[int], Optional[int]]:
    info = soup.select_one("#body_content .infomenu1 .info1")
    text = clean_text(info.get_text(" ", strip=True) if info else "")
    match = re.search(
        r"총\s*([\d,]+)\s*건[^()]*\(\s*(\d+)\s*/\s*(\d+)\s*페이지\s*\)",
        text,
    )
    if not match:
        return None, None, None
    return (
        int(match.group(1).replace(",", "")),
        int(match.group(2)),
        int(match.group(3)),
    )


def sacheon_education_status(value: Any) -> str:
    text = clean_text(value)
    if text in {"신청하기", "접수중"}:
        return "OPEN"
    if text in {"대기자신청", "대기접수"}:
        return "WAITING"
    if text in {"접수대기", "접수예정"}:
        return "SCHEDULED"
    if text in {"접수마감", "신청마감"}:
        return "CLOSED"
    # Old archived rows expose no button at all. They are retained in the
    # declared census and then removed by their education end date.
    if not text:
        return "CLOSED"
    return ""


def sacheon_education_labeled_pairs(card: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for node in card.select(".texts > span.t2"):
        text = clean_text(node.get_text(" ", strip=True))
        match = re.match(r"^([^:：]+)\s*[:：]\s*(.*)$", text)
        if match:
            pairs[clean_text(match.group(1))] = clean_text(match.group(2))
    return pairs


def sacheon_education_normalize_venue(value: Any) -> str:
    text = clean_text(value)
    alias_key = re.sub(r"\s+", "", text)
    return SACHEON_EDU_VENUE_ALIASES.get(alias_key, text)


def sacheon_education_normalize_address(value: Any, venue_name: Any = "") -> str:
    venue = sacheon_education_normalize_venue(venue_name)
    canonical = SACHEON_EDU_CANONICAL_ADDRESSES.get(venue)
    if canonical:
        return canonical
    text = clean_text(value)
    if not text:
        return ""
    text = re.sub(r"(로|길)(\d+)", r"\1 \2", text)
    text = clean_text(text)
    if text.startswith("경상남도 사천시 "):
        return "경남 사천시 " + text.removeprefix("경상남도 사천시 ")
    if text.startswith("경남 사천시 "):
        return text
    if text.startswith("사천시 "):
        return f"경남 {text}"
    return f"경남 사천시 {text}"


def sacheon_education_branch_code(venue_name: Any, address: Any) -> str:
    identity = f"{SACHEON_EDU_PROVIDER}|{clean_text(venue_name)}|{clean_text(address)}"
    return f"SACHEON_{hashlib.sha1(identity.encode('utf-8')).hexdigest()[:12].upper()}"


def sacheon_education_list_row(
    target: CrawlTarget,
    card: Any,
    page_url: str,
) -> Optional[dict[str, Any]]:
    link = card.select_one("a.col.a1[href]")
    lecture_idx, lecture_route_path, _detail_mode = sacheon_education_link_identity(
        page_url,
        link.get("href") if link else "",
    )
    title_node = card.select_one(".texts > strong.t1")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    category_node = card.select_one(".texts > span.t2 strong")
    category = clean_text(category_node.get_text(" ", strip=True) if category_node else "").strip("[]")
    pairs = sacheon_education_labeled_pairs(card)
    period = normalize_mixed_date_range(pairs.get("교육기간", ""))
    apply_period = normalize_mixed_date_range(pairs.get("모집기간", ""))
    start_date, end_date = parse_date_range(period)
    apply_start, apply_end = parse_date_range(apply_period)
    status_node = card.select_one(".btns .t1") or card.select_one(".btns a")
    list_status = clean_text(status_node.get_text(" ", strip=True) if status_node else "")
    status = sacheon_education_status(list_status)
    capacity_total = parse_capacity_number(pairs.get("모집인원"))
    archived_by_end_date = bool(
        end_date is not None and should_skip_expired_course({"end_date": end_date})
    )
    application_link = card.select_one(".btns a[href]")
    listed_application_idx = ""
    listed_application_path = ""
    listed_application_mode = ""
    application_href = clean_text(application_link.get("href") if application_link else "")
    # Archived/closed cards use a JavaScript alert link with ``href="#"``.
    # It is a disabled status control, not an application route.  Actionable
    # rows still fail below unless they expose an owned application URL.
    if application_link is not None and application_href not in {"", "#"}:
        (
            listed_application_idx,
            listed_application_path,
            listed_application_mode,
        ) = sacheon_education_link_identity(
            page_url,
            application_href,
            application=True,
        )
        if not listed_application_idx:
            return None
    reservation_available = status in {"OPEN", "WAITING"}
    if (
        not lecture_idx
        or not title
        or not category
        or not period
        or start_date is None
        or end_date is None
        or not apply_period
        or apply_start is None
        or apply_end is None
        or not status
        or capacity_total is None
        or (not archived_by_end_date and not clean_text(pairs.get("접수방법")))
        or (
            reservation_available
            and (
                listed_application_idx != lecture_idx
                or listed_application_path != lecture_route_path
            )
        )
        or (not reservation_available and bool(listed_application_idx))
    ):
        return None

    raw_url = sacheon_education_detail_url(lecture_idx, lecture_route_path)
    application_url = (
        sacheon_education_application_url(
            lecture_idx,
            lecture_route_path,
            listed_application_mode,
        )
        if reservation_available
        else ""
    )
    branch = category
    raw_fields: dict[str, Any] = {
        "parser": SACHEON_EDU_PARSER,
        "lecture_idx": lecture_idx,
        "page_url": page_url,
        "list_status": list_status,
        "list_category": category,
        "list_title": title,
        "list_pairs": pairs,
        "lecture_route_path": lecture_route_path,
        "listed_application_idx": listed_application_idx,
        "listed_application_path": listed_application_path,
        "listed_application_mode": listed_application_mode,
    }
    if not reservation_available:
        raw_fields["clear_application_url"] = True
    row: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:lecture:{lecture_idx}"[:100],
        "title": title,
        "branch": branch,
        "branch_code": sacheon_education_branch_code(branch, ""),
        "preserve_branch": True,
        "branch_url": SACHEON_EDU_LIST_URL,
        "category": category,
        "provider_organizer": category,
        "raw_url": raw_url,
        "status": status,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": clean_text(pairs.get("교육시간")),
        "start_date": start_date,
        "end_date": end_date,
        "apply_start": apply_start,
        "apply_end": apply_end,
        "target": clean_text(pairs.get("모집대상")),
        "capacity": capacity_total,
        "capacity_total": capacity_total,
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "reservation_available": reservation_available,
        "application_type": "ONLINE_RESERVATION" if reservation_available else "INFO_ONLY",
        "description": clean_text(card.get_text(" ", strip=True))[:2000],
        "collection_category": clean_text(target.extra.get("collection_category") or "공공예약"),
        "domain_category": clean_text(target.extra.get("domain_category") or "교육·강좌"),
        "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
        "source_group": clean_text(target.extra.get("source_group") or "municipal_reservation"),
        "service_group": "공공강좌",
        "service_group_policy": "locked",
        "collection_type": "static_html+detail_html",
        "program_type": "강좌",
        "raw_fields": raw_fields,
    }
    if application_url:
        row["application_url"] = application_url
    return row


def sacheon_lifelong_detail_pairs(container: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in container.select(".tg1 > ul > li"):
        label_node = item.select_one(":scope > .t1")
        label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
        if not label:
            continue
        clone = BeautifulSoup(str(item), "lxml")
        for node in clone.select(".t1"):
            node.decompose()
        value = clean_text(clone.get_text(" ", strip=True))
        if label in pairs and pairs[label] != value:
            raise ValueError(f"Sacheon lifelong detail duplicated label {label!r}")
        pairs[label] = value
    return pairs


def sacheon_education_detail_fields(
    s: requests.Session,
    detail_url: str,
    timeout: int,
    expected_title: Any = "",
    expected_lecture_idx: Any = "",
    expected_status: Any = "",
) -> dict[str, Any]:
    parsed_detail = urlparse(clean_text(detail_url))
    detail_query = parse_qs(parsed_detail.query, keep_blank_values=True)
    detail_idx = clean_text((detail_query.get("idx") or [""])[0])
    expected_idx = clean_text(expected_lecture_idx)
    if (
        parsed_detail.scheme.lower() != "https"
        or parsed_detail.netloc.lower() != SACHEON_EDU_HOST
        or parsed_detail.path not in SACHEON_EDU_OWNED_LECTURE_PATHS
        or parsed_detail.params
        or parsed_detail.fragment
        or set(detail_query) != {"amode", "idx"}
        or any(len(values) != 1 for values in detail_query.values())
        or detail_query.get("amode") != ["view"]
        or not re.fullmatch(r"\d{1,12}", detail_idx)
        or (expected_idx and detail_idx != expected_idx)
    ):
        raise ValueError("Sacheon detail URL did not match the requested owned lecture identity")

    soup = fetch_soup(s, detail_url, timeout=timeout)
    is_lifelong_detail = parsed_detail.path == SACHEON_EDU_LIFELONG_PATH
    container = soup.select_one(
        "#body_content .edu1view1"
        if is_lifelong_detail
        else "#body_content .view1pic1info1"
    )
    title_node = (
        container.select_one("h3.hb2.h1")
        if container and is_lifelong_detail
        else container.select_one(".texts > h1.h1")
        if container
        else None
    )
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    list_title = clean_text(expected_title)
    if not title or (
        list_title
        and title != list_title
        and not list_title.startswith(f"{title} -")
    ):
        raise ValueError("Sacheon detail response did not match the requested lecture title")
    if is_lifelong_detail:
        pairs = sacheon_lifelong_detail_pairs(container)
        pairs["교육장소"] = "사천시 평생학습관"
        detail_status_node = container.select_one(".cate")
        detail_status_text = clean_text(
            detail_status_node.get_text(" ", strip=True) if detail_status_node else ""
        )
        detail_status = sacheon_education_status(detail_status_text)
        expected_status_text = clean_text(expected_status)
        if not detail_status or (
            expected_status_text and detail_status != expected_status_text
        ):
            raise ValueError("Sacheon lifelong detail status did not match its aggregate card")
        owned_application_identities = [
            sacheon_education_link_identity(detail_url, link.get("href"), application=True)
            for link in soup.select("#body_content .infomenu1 a[href]")
        ]
        owned_application_identities = [
            identity for identity in owned_application_identities if identity[0]
        ]
        if detail_status in {"OPEN", "WAITING"}:
            if not any(
                identity[0] == detail_idx and identity[1] == parsed_detail.path
                for identity in owned_application_identities
            ):
                raise ValueError("Sacheon lifelong detail omitted its owned application identity")
        elif owned_application_identities:
            raise ValueError("Sacheon closed lifelong detail exposed an actionable application link")
    else:
        table = container.select_one("table.t3.ttvam") if container else None
        if table is None:
            raise ValueError("Sacheon detail response did not expose the official lecture table")
        pairs = pairs_from_tables(table)
        detail_status_text = ""
    required = ("교육기간", "접수기간", "교육장소", "주소", "접수방법")
    missing = [key for key in required if not clean_text(pairs.get(key))]
    if missing:
        raise ValueError(f"Sacheon detail response omitted required fields: {', '.join(missing)}")
    period = normalize_mixed_date_range(pairs.get("교육기간", ""))
    apply_period = normalize_mixed_date_range(pairs.get("접수기간", ""))
    start_date, end_date = parse_date_range(period)
    apply_start, apply_end = parse_date_range(apply_period)
    if start_date is None or end_date is None or apply_start is None or apply_end is None:
        raise ValueError("Sacheon detail response exposed malformed date ranges")
    raw_venue = clean_text(pairs.get("교육장소"))
    raw_address = clean_text(pairs.get("주소"))
    venue_name = sacheon_education_normalize_venue(raw_venue)
    venue_address = sacheon_education_normalize_address(raw_address, venue_name)
    if not venue_name or not venue_address:
        raise ValueError("Sacheon detail response omitted its venue identity")
    return {
        "title": title,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": clean_text(pairs.get("교육시간")),
        "start_date": start_date,
        "end_date": end_date,
        "apply_start": apply_start,
        "apply_end": apply_end,
        "target": clean_text(pairs.get("모집대상")),
        "eligibility_raw": clean_text(pairs.get("모집지역")),
        "fee": clean_text(pairs.get("수강료")),
        "preparation": clean_text(pairs.get("준비물")),
        "room": venue_name,
        "venue_name": venue_name,
        "venue_address": venue_address,
        "address": venue_address,
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "phone": clean_text(pairs.get("이용문의")),
        "raw_venue": raw_venue,
        "raw_address": raw_address,
        "detail_status_raw": detail_status_text,
        "raw_detail_pairs": pairs,
    }


def collect_sacheon_education_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if target.provider != SACHEON_EDU_PROVIDER or not is_sacheon_education_target(target.url):
        raise ValueError("Sacheon education target must use the owned official HTTPS aggregate route")
    s = session()
    candidates: list[dict[str, Any]] = []
    seen_lecture_idxs: set[str] = set()
    seen_page_fingerprints: set[tuple[str, ...]] = set()
    pages = 0
    declared_total: Optional[int] = None
    declared_pages = 0
    detail_pages = 0
    detail_attempts = 0
    detail_errors = 0
    invalid_rows = 0
    duplicate_rows = 0
    repeated_pages = 0
    no_data_placeholders = 0
    expired_rows = 0
    list_pagination_exhausted = False
    errors: list[str] = []

    def add_error(message: str) -> None:
        if message and message not in errors:
            errors.append(message)

    for page in range(1, max(1, max_pages) + 1):
        page_url = sacheon_education_list_url(page)
        try:
            soup = fetch_soup(s, page_url, timeout=timeout)
        except Exception as exc:
            logger.debug(
                "Sacheon education list fetch failed page=%s error_type=%s",
                page,
                type(exc).__name__,
            )
            add_error(f"page {page} fetch failed ({type(exc).__name__})")
            break
        pages += 1
        official_form = soup.select_one("form#frmLecture")
        action_url = urlparse(
            urljoin(page_url, clean_text(official_form.get("action") if official_form else ""))
        )
        if (
            official_form is None
            or clean_text(official_form.get("method")).lower() != "get"
            or action_url.scheme.lower() != "https"
            or action_url.netloc.lower() != SACHEON_EDU_HOST
            or action_url.path != SACHEON_EDU_LIST_PATH
        ):
            add_error(f"page {page} did not expose the official lecture search form")
            break

        page_total, current_page, page_total_pages = sacheon_education_page_declaration(soup)
        calculated_pages = (
            max(1, (page_total + SACHEON_EDU_PAGE_SIZE - 1) // SACHEON_EDU_PAGE_SIZE)
            if page_total is not None
            else 0
        )
        if (
            page_total is None
            or current_page != page
            or page_total_pages is None
            or page_total_pages < 1
            or calculated_pages != page_total_pages
        ):
            add_error(f"page {page} did not expose a valid current/total page declaration")
            break
        if declared_total is None:
            declared_total = page_total
            declared_pages = page_total_pages
        elif page_total != declared_total or page_total_pages != declared_pages:
            add_error(
                f"page {page} changed the declaration from {declared_total}/{declared_pages} "
                f"to {page_total}/{page_total_pages}"
            )
            break

        list_container = soup.select_one("#body_content .list1f1t2b2 > ul.lst1")
        cards = list_container.select(":scope > li.li1") if list_container else []
        if not cards:
            if page == 1 and page_total == 0 and page_total_pages == 1 and list_container is not None:
                no_data_placeholders += 1
                list_pagination_exhausted = True
            else:
                add_error(f"page {page} did not expose declared lecture cards")
            break

        page_idxs: list[str] = []
        for card in cards:
            row = sacheon_education_list_row(target, card, page_url)
            if not row:
                invalid_rows += 1
                continue
            lecture_idx = clean_text((row.get("raw_fields") or {}).get("lecture_idx"))
            page_idxs.append(lecture_idx)
            if lecture_idx in seen_lecture_idxs:
                duplicate_rows += 1
                continue
            seen_lecture_idxs.add(lecture_idx)
            candidates.append(row)

        fingerprint = tuple(page_idxs)
        if fingerprint and fingerprint in seen_page_fingerprints:
            repeated_pages += 1
        elif fingerprint:
            seen_page_fingerprints.add(fingerprint)
        if page >= declared_pages:
            list_pagination_exhausted = True
            break

    if invalid_rows:
        add_error(f"listed lecture cards were malformed ({invalid_rows} invalid rows)")
    if duplicate_rows:
        add_error(f"listed lecture IDs were duplicated ({duplicate_rows} duplicate rows)")
    if repeated_pages:
        add_error(f"pagination repeated {repeated_pages} previously discovered page(s)")
    if declared_total is None and not errors:
        add_error("lecture list did not declare its total count")
    if declared_pages and pages < declared_pages:
        add_error(f"max_pages cap reached after {pages} of {declared_pages} declared pages")
    if declared_total is not None and len(seen_lecture_idxs) != declared_total:
        add_error(f"parsed {len(seen_lecture_idxs)} of {declared_total} declared lecture rows")

    current_rows: list[dict[str, Any]] = []
    for row in candidates:
        if should_skip_expired_course(row):
            expired_rows += 1
            continue
        current_rows.append(row)

    list_collection_complete = bool(
        list_pagination_exhausted
        and declared_total is not None
        and declared_pages > 0
        and len(seen_lecture_idxs) == declared_total
        and invalid_rows == 0
        and duplicate_rows == 0
        and repeated_pages == 0
        and not errors
    )
    detail_cap = max(0, detail_limit)
    detail_enrichment_capped = list_collection_complete and detail_cap < len(current_rows)
    if detail_enrichment_capped:
        add_error(f"detail enrichment capped at {detail_cap} of {len(current_rows)} current rows")
    detail_error_ids: list[str] = []
    core_missing_fields_by_id: dict[str, list[str]] = {}
    rows: list[dict[str, Any]] = []
    for index, row in enumerate(current_rows):
        list_raw_fields = row.get("raw_fields") or {}
        lecture_idx = clean_text(list_raw_fields.get("lecture_idx"))
        lecture_route_path = clean_text(list_raw_fields.get("lecture_route_path"))
        listed_application_mode = clean_text(list_raw_fields.get("listed_application_mode"))
        detail: dict[str, Any] = {}
        if list_collection_complete and index < detail_cap:
            detail_attempts += 1
            try:
                detail = sacheon_education_detail_fields(
                    s,
                    clean_text(row.get("raw_url")),
                    timeout,
                    row.get("title"),
                    lecture_idx,
                    row.get("status"),
                )
                detail_pages += 1
            except Exception as exc:
                detail_errors += 1
                detail_error_ids.append(lecture_idx)
                logger.debug(
                    "Sacheon education detail fetch failed idx=%s error_type=%s",
                    lecture_idx,
                    type(exc).__name__,
                )

        for key in (
            "title",
            "period",
            "apply_period",
            "schedule_raw",
            "start_date",
            "end_date",
            "apply_start",
            "apply_end",
            "target",
            "eligibility_raw",
            "fee",
            "preparation",
            "room",
            "venue_name",
            "venue_address",
            "address",
            "application_method_raw",
            "phone",
        ):
            if detail.get(key) not in (None, "", [], {}):
                row[key] = detail[key]

        venue_name = sacheon_education_normalize_venue(row.get("venue_name"))
        venue_address = sacheon_education_normalize_address(
            row.get("venue_address") or row.get("address"),
            venue_name,
        )
        if detail:
            missing_fields = [
                field
                for field, value in (
                    ("venue_name", venue_name),
                    ("venue_address", venue_address),
                    ("period", row.get("period")),
                    ("apply_period", row.get("apply_period")),
                    ("application_method_raw", row.get("application_method_raw")),
                )
                if not clean_text(value)
            ]
            if missing_fields:
                core_missing_fields_by_id[lecture_idx] = missing_fields
            row["branch"] = venue_name
            row["branch_code"] = sacheon_education_branch_code(venue_name, venue_address)
            row["preserve_branch"] = True
            row["room"] = venue_name
            row["venue_name"] = venue_name
            row["venue_address"] = venue_address
            row["address"] = venue_address
            raw_fields = row.setdefault("raw_fields", {})
            raw_fields["detail_title"] = detail.get("title")
            raw_fields["detail_pairs"] = detail.get("raw_detail_pairs", {})
            raw_fields["detail_venue_raw"] = detail.get("raw_venue")
            raw_fields["detail_address_raw"] = detail.get("raw_address")
            raw_fields["detail_status_raw"] = detail.get("detail_status_raw")

        reservation_available = row.get("status") in {"OPEN", "WAITING"}
        application_url = sacheon_education_application_url(
            lecture_idx,
            lecture_route_path,
            listed_application_mode,
        )
        row["reservation_available"] = bool(reservation_available and application_url)
        if row["reservation_available"]:
            row["application_url"] = application_url
            row["application_type"] = "ONLINE_RESERVATION"
            row.setdefault("raw_fields", {}).pop("clear_application_url", None)
        else:
            row.pop("application_url", None)
            row["application_type"] = "INFO_ONLY"
            row.setdefault("raw_fields", {})["clear_application_url"] = True
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

    if detail_errors:
        add_error(f"detail fetch failed for {detail_errors} current rows")
    if core_missing_fields_by_id:
        add_error(f"detail core fields were missing for {len(core_missing_fields_by_id)} current rows")
    rows = dedupe_rows(rows)
    if len(rows) != len(current_rows):
        add_error(f"current course dedupe reduced {len(current_rows)} rows to {len(rows)}")

    collection_complete = bool(
        list_collection_complete
        and not detail_enrichment_capped
        and detail_errors == 0
        and not core_missing_fields_by_id
        and not errors
    )
    no_current_data = collection_complete and not rows
    status_counts: dict[str, int] = {}
    for row in current_rows:
        status = clean_text(row.get("status"))
        status_counts[status] = status_counts.get(status, 0) + 1
    logical_venues = {
        (clean_text(row.get("venue_name")), clean_text(row.get("venue_address")))
        for row in rows
        if clean_text(row.get("venue_name")) and clean_text(row.get("venue_address"))
    }
    meta: dict[str, Any] = {
        "pages": pages,
        "total_pages": declared_pages,
        "total_count": declared_total or 0,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_errors": detail_errors,
        "detail_error_ids": detail_error_ids,
        "detail_candidates": len(current_rows),
        "detail_enrichment_capped": detail_enrichment_capped,
        "detail_enrichment_complete": (
            collection_complete and detail_pages == len(current_rows)
        ),
        "core_missing_fields_by_id": core_missing_fields_by_id,
        "discovered_links": len(seen_lecture_idxs),
        "reservation_discovery_links": sum(
            1 for row in rows if clean_text(row.get("application_url"))
        ),
        "reservation_fallback_pages": 0,
        "pagination_detected": declared_pages > 1,
        "pagination_complete": collection_complete,
        "list_pagination_complete": list_collection_complete,
        "pagination_exhausted": list_pagination_exhausted,
        "source_cap_reached": bool(
            (declared_pages and pages < declared_pages) or detail_enrichment_capped
        ),
        "valid_count": len(seen_lecture_idxs),
        "invalid_count": invalid_rows,
        "duplicate_count": duplicate_rows,
        "repeated_pages": repeated_pages,
        "expired_count": expired_rows,
        "current_count": len(current_rows),
        "status_counts": status_counts,
        "logical_venue_count": len(logical_venues),
        "no_data_placeholders": no_data_placeholders,
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": (
            "explicit zero total"
            if no_current_data and no_data_placeholders
            else "all listed courses are expired"
            if no_current_data
            else ""
        ),
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(errors)
    return rows, SACHEON_EDU_PARSER, meta


DALSEO_LEARNING_PROVIDER = "MUNI_EDU_DALSEO_DAEGU_KR_14975995"
DALSEO_LEARNING_HOST = "edu.dalseo.daegu.kr"
DALSEO_LEARNING_HOME_URL = f"https://{DALSEO_LEARNING_HOST}/"
DALSEO_LEARNING_LIST_PATH = "/yeyak/ilms/learning/learningList.do"
DALSEO_LEARNING_DETAIL_PATH = "/yeyak/ilms/learning/learningDetail.do"
DALSEO_LEARNING_LIST_URL = f"https://{DALSEO_LEARNING_HOST}{DALSEO_LEARNING_LIST_PATH}"
DALSEO_LEARNING_PAGE_SIZE = 50
DALSEO_LEARNING_PARSER = "dalseo_learning_native_list+detail"
DALSEO_LEARNING_ID_RE = re.compile(r"LEARNING_\d{8}")

DALSEO_LEARNING_CANONICAL_ADDRESSES = {
    "달서평생학습관": "대구 달서구 조암로5길 5-12 4층 달서평생학습관",
    "디지털정보과 공공데이터팀": "대구 달서구 학산로 45 4층 디지털정보과",
    "더케이평생교육원": "대구 달서구 용산서로 4-22 3층",
    "달서구 평생교육과": "대구 달서구 학산로 45 보건소 6층, 평생교육과",
    "달서목재문화관": "대구 달서구 앞산순환로 248 달서목재문화관",
    "달서50플러스센터": "대구 달서구 성당로 17",
    "달서구청소년문화의집": "대구 달서구 조암로 129 3층",
}


def is_dalseo_learning_target(url: str) -> bool:
    parsed = urlparse(clean_text(url))
    return bool(
        parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == DALSEO_LEARNING_HOST
        and parsed.path == "/"
        and not parsed.params
        and not parsed.query
        and not parsed.fragment
    )


def dalseo_learning_detail_url(learning_id: Any) -> str:
    value = clean_text(learning_id)
    if not DALSEO_LEARNING_ID_RE.fullmatch(value):
        return ""
    return f"{DALSEO_LEARNING_LIST_URL.rsplit('/', 1)[0]}/learningDetail.do?{urlencode({'lctr_id': value})}"


def dalseo_learning_list_payload(page: int) -> dict[str, str]:
    return {
        "inst_id": "",
        "searchCondition3": "",
        "search_rgn_dong": "",
        "display_type": "2",
        "pageIndex": str(max(1, int(page))),
        "card_pageIndex": "1",
        "ctz_uni_cd": "",
        "out_inst_yn": "N",
        "k_search_arr": "",
        "searchCondition": "0",
        "searchKeyword": "",
        "dong_cd": "",
        "a_search_ch": "",
        "b_search_ch": "",
        "c_search_ch": "",
        "d_search_ch": "",
        "e_search_ch": "",
        "f_search_ch": "",
        "g_search_ch": "",
        "o_search_ch": "",
        "l_search_ch": "",
        "learning_state": "",
        "card_pageUnit": "12",
        "pageUnit": str(DALSEO_LEARNING_PAGE_SIZE),
    }


def dalseo_learning_post_soup(
    s: requests.Session,
    page: int,
    timeout: int,
) -> BeautifulSoup:
    response = s.post(
        DALSEO_LEARNING_LIST_URL,
        data=dalseo_learning_list_payload(page),
        timeout=timeout,
    )
    response.raise_for_status()
    return BeautifulSoup(response.text, "lxml")


def dalseo_learning_owned_form_action(form: Any, page_url: str, expected_path: str) -> bool:
    if form is None or clean_text(form.get("method")).lower() != "post":
        return False
    parsed = urlparse(urljoin(page_url, clean_text(form.get("action"))))
    if (
        parsed.scheme.lower() != "https"
        or parsed.netloc.lower() != DALSEO_LEARNING_HOST
        or parsed.path != expected_path
        or parsed.fragment
    ):
        return False
    if parsed.params and not re.fullmatch(
        r"jsessionid=[A-Za-z0-9._-]{1,200}", parsed.params, re.IGNORECASE
    ):
        return False
    return True


def dalseo_learning_page_declaration(
    soup: BeautifulSoup,
) -> tuple[Optional[int], Optional[int], Optional[int]]:
    node = soup.select_one("#pageInfo_list")
    text = clean_text(node.get_text(" ", strip=True) if node else "")
    match = re.search(
        r"총\s*([\d,]+)\s*건\s*\(\s*(\d+)\s*/\s*(\d+)\s*페이지\s*\)",
        text,
    )
    if not match:
        return None, None, None
    return int(match.group(1).replace(",", "")), int(match.group(2)), int(match.group(3))


def dalseo_learning_status(value: Any) -> str:
    text = clean_text(value)
    mapping = {
        "접수중": "OPEN",
        "접수예정": "SCHEDULED",
        "대기접수": "WAITING",
        "마감": "CLOSED",
        "교육중": "CLOSED",
        "교육완료": "CLOSED",
        "접수종료": "CLOSED",
    }
    return mapping.get(text, "")


def dalseo_learning_external_url(page_url: str, href: Any) -> str:
    value = clean_text(href)
    if not value or len(value) > 4096:
        return ""
    linked = urljoin(page_url, value)
    parsed = urlparse(linked)
    if (
        parsed.scheme.lower() not in {"http", "https"}
        or not parsed.hostname
        or parsed.username
        or parsed.password
        or parsed.hostname.lower() == DALSEO_LEARNING_HOST
    ):
        return ""
    return linked


def dalseo_learning_branch_address(organizer: Any, value: Any) -> str:
    branch = clean_text(organizer)
    canonical = DALSEO_LEARNING_CANONICAL_ADDRESSES.get(branch)
    if canonical:
        return canonical
    text = clean_text(value).replace("대구광역시 달서구", "대구 달서구")
    text = re.sub(r"\s+([,.])", r"\1", text)
    return clean_text(text).rstrip(" .")


def dalseo_learning_branch_code(organizer: Any, address: Any) -> str:
    identity = f"{DALSEO_LEARNING_PROVIDER}|{clean_text(organizer)}|{clean_text(address)}"
    return f"DALSEO_{hashlib.sha1(identity.encode('utf-8')).hexdigest()[:12].upper()}"


def dalseo_learning_list_entry(
    target: CrawlTarget,
    row_node: Any,
    page_url: str,
) -> Optional[dict[str, Any]]:
    cells = row_node.select(":scope > td")
    if len(cells) != 7:
        return None
    number_text = clean_text(cells[0].get_text(" ", strip=True))
    if not re.fullmatch(r"[1-9]\d*", number_text):
        return None
    row_number = int(number_text)
    link = cells[1].select_one("a")
    title_node = cells[1].select_one(".tit")
    organizer_node = cells[1].select_one(".org")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    organizer = clean_text(organizer_node.get_text(" ", strip=True) if organizer_node else "")
    if not link or not title or not organizer:
        return None
    onclick = clean_text(link.get("onclick"))
    native_match = re.fullmatch(
        r"fn_learning_detail\(\s*'(?P<id>LEARNING_\d{8})'\s*\);\s*return\s+false;?",
        onclick,
    )
    if native_match:
        learning_id = native_match.group("id")
        href = clean_text(link.get("href")).lower()
        if href not in {"javascript:;", "javascript:void(0);", "#"}:
            return None
    else:
        external_url = dalseo_learning_external_url(page_url, link.get("href"))
        if onclick or not external_url:
            return None
        return {
            "kind": "external",
            "row_number": row_number,
            "title": title,
            "organizer": organizer,
            "external_url": external_url,
        }

    period_node = cells[3].select_one("span.s_type.blue")
    if period_node is None:
        return None
    period_clone = BeautifulSoup(str(period_node), "lxml")
    for hidden in period_clone.select("em.hidden"):
        hidden.decompose()
    period_text = clean_text(period_clone.get_text(" ", strip=True))
    period = normalize_mixed_date_range(period_text)
    start_date, end_date = parse_date_range(period)
    schedule_raw = clean_text(
        " ".join(node.get_text(" ", strip=True) for node in period_node.select("pre"))
    )

    application_node = cells[4].select_one("span.s_type.red1")
    if application_node is None:
        return None
    application_clone = BeautifulSoup(str(application_node), "lxml")
    for hidden in application_clone.select("em.hidden"):
        hidden.decompose()
    application_text = clean_text(application_clone.get_text(" ", strip=True))
    apply_period = normalize_mixed_date_range(application_text)
    apply_start, apply_end = parse_date_range(apply_period)
    capacity_total = parse_capacity_number(
        clean_text(cells[4].select_one("span.s_type.indigo1").get_text(" ", strip=True))
        if cells[4].select_one("span.s_type.indigo1")
        else ""
    )
    status_text = clean_text(
        cells[5].select_one(".s_btn").get_text(" ", strip=True)
        if cells[5].select_one(".s_btn")
        else ""
    )
    status = dalseo_learning_status(status_text)
    selection_method_node = cells[5].select_one("span.tit.s_type2 em.hidden")
    selection_method = clean_text(
        selection_method_node.get_text(" ", strip=True) if selection_method_node else ""
    )
    status_inference = ""
    if (
        not status
        and not status_text
        and selection_method in {"선착순", "추첨"}
        and apply_end is not None
        and apply_end < datetime.now().astimezone().date()
    ):
        status = "CLOSED"
        status_inference = "missing status badge after application period ended"
    if (
        start_date is None
        or end_date is None
        or apply_start is None
        or apply_end is None
        or capacity_total is None
        or not status
    ):
        return None

    raw_url = dalseo_learning_detail_url(learning_id)
    reservation_available = status in {"OPEN", "WAITING"}
    raw_fields: dict[str, Any] = {
        "parser": DALSEO_LEARNING_PARSER,
        "learning_id": learning_id,
        "official_row_number": row_number,
        "page_url": page_url,
        "list_title": title,
        "list_organizer": organizer,
        "list_status": status_text,
        "list_period_raw": period_text,
        "list_application_raw": application_text,
    }
    if selection_method:
        raw_fields["list_selection_method"] = selection_method
    if status_inference:
        raw_fields["list_status_inference"] = status_inference
    if not reservation_available:
        raw_fields["clear_application_url"] = True
    course: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:{learning_id}"[:100],
        "title": title,
        "branch": organizer,
        "branch_code": dalseo_learning_branch_code(organizer, ""),
        "preserve_branch": True,
        "branch_url": DALSEO_LEARNING_HOME_URL,
        "category": organizer,
        "provider_organizer": organizer,
        "raw_url": raw_url,
        "status": status,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": schedule_raw,
        "start_date": start_date,
        "end_date": end_date,
        "apply_start": apply_start,
        "apply_end": apply_end,
        "capacity": capacity_total,
        "capacity_total": capacity_total,
        "fee": clean_text(cells[2].select_one("span").get_text(" ", strip=True))
        if cells[2].select_one("span")
        else "",
        "reservation_available": reservation_available,
        "application_type": "ONLINE_RESERVATION" if reservation_available else "INFO_ONLY",
        "description": clean_text(row_node.get_text(" ", strip=True))[:2000],
        "collection_category": clean_text(target.extra.get("collection_category") or "공공예약"),
        "domain_category": clean_text(target.extra.get("domain_category") or "교육·강좌"),
        "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
        "source_group": clean_text(target.extra.get("source_group") or "municipal_reservation"),
        "service_group": "공공강좌",
        "service_group_policy": "locked",
        "collection_type": "static_html+detail_html",
        "program_type": "강좌",
        "raw_fields": raw_fields,
    }
    if reservation_available:
        course["application_url"] = raw_url
    return {"kind": "native", "row_number": row_number, "learning_id": learning_id, "row": course}


def dalseo_learning_detail_pairs(container: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in container.select(".form_group dl"):
        label_node = dl.select_one(":scope > dt")
        value_node = dl.select_one(":scope > dd")
        label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if not label:
            continue
        if label in pairs and pairs[label] != value:
            raise ValueError(f"Dalseo detail duplicated label {label!r}")
        pairs[label] = value
    return pairs


def dalseo_learning_detail_fields(
    s: requests.Session,
    detail_url: str,
    timeout: int,
    learning_id: str,
    expected_title: Any,
    expected_organizer: Any,
    expected_status: Any,
) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    form = soup.select_one("form#learningVO")
    if not dalseo_learning_owned_form_action(form, detail_url, DALSEO_LEARNING_DETAIL_PATH):
        raise ValueError("Dalseo detail did not expose the owned learning form")
    action_query = parse_qs(
        urlparse(urljoin(detail_url, clean_text(form.get("action")))).query,
        keep_blank_values=True,
    )
    form_id_node = form.select_one("input[name='lctr_id']")
    form_id = clean_text(form_id_node.get("value") if form_id_node else "")
    if form_id != learning_id or action_query.get("lctr_id") != [learning_id]:
        raise ValueError("Dalseo detail response did not match the requested learning id")

    container = soup.select_one("#content .conWrap")
    title_node = container.select_one("h2.enrolTit") if container else None
    full_title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    expected_full_title = f"[{clean_text(expected_organizer)}] {clean_text(expected_title)}"
    if not full_title or full_title != expected_full_title:
        raise ValueError("Dalseo detail response did not match the requested title and organizer")
    pairs = dalseo_learning_detail_pairs(container)
    required = (
        "강좌분류",
        "교육대상",
        "문의전화",
        "교육장소",
        "교육기간",
        "교육시간",
        "수강료",
        "재료비",
        "접수인원",
        "일반신청기간",
        "모집방법",
        "신청상태",
        "교육상태",
        "결제방법",
        "주소",
    )
    missing = [key for key in required if not clean_text(pairs.get(key))]
    if missing:
        raise ValueError(f"Dalseo detail omitted required fields: {', '.join(missing)}")
    period = normalize_mixed_date_range(pairs["교육기간"])
    apply_period = normalize_mixed_date_range(pairs["일반신청기간"])
    start_date, end_date = parse_date_range(period)
    apply_start, apply_end = parse_date_range(apply_period)
    if start_date is None or end_date is None or apply_start is None or apply_end is None:
        raise ValueError("Dalseo detail exposed malformed date ranges")

    status = clean_text(expected_status)
    apply_button = soup.select_one("#learning_aply_btn")
    apply_button_text = clean_text(
        apply_button.get_text(" ", strip=True) if apply_button else ""
    )
    expected_button = {
        "OPEN": "일반모집신청",
        "WAITING": "대기자신청",
    }.get(status, "")
    if apply_button_text != expected_button:
        raise ValueError("Dalseo detail application control did not match the list status")

    organizer = clean_text(expected_organizer)
    address = dalseo_learning_branch_address(organizer, pairs["주소"])
    if not organizer or not address:
        raise ValueError("Dalseo detail omitted its branch identity")
    capacity_values = [
        int(value.replace(",", ""))
        for value in re.findall(r"정원\s*([\d,]+)\s*명", pairs["접수인원"])
    ]
    waitlist_match = re.search(
        r"대기\s*:\s*([\d,]+)\s*/\s*([\d,]+)", pairs["접수인원"]
    )
    description = clean_text(pairs.get("강좌소개"))
    return {
        "title": clean_text(expected_title),
        "category": clean_text(pairs["강좌분류"]),
        "target": clean_text(pairs["교육대상"]),
        "phone": clean_text(pairs["문의전화"]),
        "room": clean_text(pairs["교육장소"]),
        "venue_name": clean_text(pairs["교육장소"]),
        "venue_address": address,
        "address": address,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": clean_text(pairs["교육시간"]),
        "start_date": start_date,
        "end_date": end_date,
        "apply_start": apply_start,
        "apply_end": apply_end,
        "fee": clean_text(pairs["수강료"]),
        "material_fee": clean_text(pairs["재료비"]),
        "application_method_raw": f"온라인 접수 / {clean_text(pairs['모집방법'])}",
        "eligibility_raw": clean_text(pairs.get("강좌제한")),
        "description": description,
        "capacity_total": sum(capacity_values) if capacity_values else None,
        "waitlist_current": int(waitlist_match.group(1).replace(",", ""))
        if waitlist_match
        else None,
        "waitlist_total": int(waitlist_match.group(2).replace(",", ""))
        if waitlist_match
        else None,
        "raw_detail_pairs": pairs,
        "detail_title": full_title,
        "application_button_text": apply_button_text,
    }


def collect_dalseo_learning_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if target.provider != DALSEO_LEARNING_PROVIDER or not is_dalseo_learning_target(target.url):
        raise ValueError("Dalseo learning target must use the owned official HTTPS portal root")
    s = session()
    native_candidates: list[dict[str, Any]] = []
    seen_native_ids: set[str] = set()
    seen_row_numbers: set[int] = set()
    seen_page_fingerprints: set[tuple[int, ...]] = set()
    external_hosts: dict[str, int] = {}
    external_samples: list[str] = []
    pages = 0
    declared_total: Optional[int] = None
    declared_pages = 0
    classified_count = 0
    external_count = 0
    invalid_rows = 0
    duplicate_rows = 0
    duplicate_native_ids = 0
    repeated_pages = 0
    expired_rows = 0
    detail_pages = 0
    detail_attempts = 0
    detail_errors = 0
    detail_error_ids: list[str] = []
    list_pagination_exhausted = False
    errors: list[str] = []

    def add_error(message: str) -> None:
        if message and message not in errors:
            errors.append(message)

    for page in range(1, max(1, max_pages) + 1):
        try:
            soup = dalseo_learning_post_soup(s, page, timeout)
        except Exception as exc:
            logger.debug(
                "Dalseo learning list fetch failed page=%s error_type=%s",
                page,
                type(exc).__name__,
            )
            add_error(f"page {page} fetch failed ({type(exc).__name__})")
            break
        pages += 1
        form = soup.select_one("form#learningVO")
        if not dalseo_learning_owned_form_action(form, DALSEO_LEARNING_LIST_URL, DALSEO_LEARNING_LIST_PATH):
            add_error(f"page {page} did not expose the official learning search form")
            break
        page_input = form.select_one("input[name='pageIndex']")
        selected_page_units = [
            clean_text(option.get("value"))
            for option in form.select("select[name='pageUnit'] option[selected]")
        ]
        if (
            clean_text(page_input.get("value") if page_input else "") != str(page)
            or selected_page_units != [str(DALSEO_LEARNING_PAGE_SIZE)]
        ):
            add_error(f"page {page} did not retain the requested bounded pagination")
            break

        page_total, current_page, page_total_pages = dalseo_learning_page_declaration(soup)
        calculated_pages = (
            max(1, (page_total + DALSEO_LEARNING_PAGE_SIZE - 1) // DALSEO_LEARNING_PAGE_SIZE)
            if page_total is not None
            else 0
        )
        if (
            page_total is None
            or current_page != page
            or page_total_pages is None
            or page_total_pages < 1
            or calculated_pages != page_total_pages
        ):
            add_error(f"page {page} did not expose a valid current/total page declaration")
            break
        if declared_total is None:
            declared_total = page_total
            declared_pages = page_total_pages
        elif page_total != declared_total or page_total_pages != declared_pages:
            add_error(
                f"page {page} changed the declaration from {declared_total}/{declared_pages} "
                f"to {page_total}/{page_total_pages}"
            )
            break

        table = soup.select_one("table.tbl.lecture")
        row_nodes = table.select("tbody > tr") if table else []
        expected_rows = min(
            DALSEO_LEARNING_PAGE_SIZE,
            max(0, page_total - (page - 1) * DALSEO_LEARNING_PAGE_SIZE),
        )
        if len(row_nodes) != expected_rows:
            add_error(f"page {page} exposed {len(row_nodes)} of {expected_rows} declared rows")
            break
        if not row_nodes and page_total == 0 and page == 1:
            list_pagination_exhausted = True
            break

        page_numbers: list[int] = []
        for row_node in row_nodes:
            entry = dalseo_learning_list_entry(target, row_node, DALSEO_LEARNING_LIST_URL)
            if not entry:
                invalid_rows += 1
                continue
            row_number = int(entry["row_number"])
            page_numbers.append(row_number)
            if row_number in seen_row_numbers:
                duplicate_rows += 1
                continue
            seen_row_numbers.add(row_number)
            classified_count += 1
            if entry["kind"] == "external":
                external_count += 1
                external_url = clean_text(entry["external_url"])
                host = clean_text(urlparse(external_url).hostname).lower()
                external_hosts[host] = external_hosts.get(host, 0) + 1
                if len(external_samples) < 10:
                    external_samples.append(external_url)
                continue
            learning_id = clean_text(entry["learning_id"])
            if learning_id in seen_native_ids:
                duplicate_native_ids += 1
                continue
            seen_native_ids.add(learning_id)
            native_candidates.append(entry["row"])

        expected_numbers = list(
            range(
                page_total - (page - 1) * DALSEO_LEARNING_PAGE_SIZE,
                page_total - (page - 1) * DALSEO_LEARNING_PAGE_SIZE - expected_rows,
                -1,
            )
        )
        if page_numbers != expected_numbers:
            add_error(f"page {page} did not expose the official descending row sequence")
        fingerprint = tuple(page_numbers)
        if fingerprint and fingerprint in seen_page_fingerprints:
            repeated_pages += 1
        elif fingerprint:
            seen_page_fingerprints.add(fingerprint)
        if page >= declared_pages:
            list_pagination_exhausted = True
            break

    if invalid_rows:
        add_error(f"listed learning rows were malformed ({invalid_rows} invalid rows)")
    if duplicate_rows:
        add_error(f"official row numbers were duplicated ({duplicate_rows} duplicate rows)")
    if duplicate_native_ids:
        add_error(f"native learning IDs were duplicated ({duplicate_native_ids} duplicate IDs)")
    if repeated_pages:
        add_error(f"pagination repeated {repeated_pages} previously discovered page(s)")
    if declared_total is None and not errors:
        add_error("learning list did not declare its total count")
    if declared_pages and pages < declared_pages:
        add_error(f"max_pages cap reached after {pages} of {declared_pages} declared pages")
    if declared_total is not None and classified_count != declared_total:
        add_error(f"classified {classified_count} of {declared_total} declared learning rows")
    if classified_count != len(native_candidates) + external_count:
        add_error("native/external ownership classification did not cover every official row")

    current_rows: list[dict[str, Any]] = []
    for row in native_candidates:
        if should_skip_expired_course(row):
            expired_rows += 1
            continue
        current_rows.append(row)
    list_collection_complete = bool(
        list_pagination_exhausted
        and declared_total is not None
        and declared_pages > 0
        and classified_count == declared_total
        and classified_count == len(native_candidates) + external_count
        and invalid_rows == 0
        and duplicate_rows == 0
        and duplicate_native_ids == 0
        and repeated_pages == 0
        and not errors
    )
    detail_cap = max(0, detail_limit)
    detail_enrichment_capped = list_collection_complete and detail_cap < len(current_rows)
    if detail_enrichment_capped:
        add_error(f"detail enrichment capped at {detail_cap} of {len(current_rows)} current rows")

    rows: list[dict[str, Any]] = []
    for index, row in enumerate(current_rows):
        learning_id = clean_text((row.get("raw_fields") or {}).get("learning_id"))
        detail: dict[str, Any] = {}
        if list_collection_complete and index < detail_cap:
            detail_attempts += 1
            try:
                detail = dalseo_learning_detail_fields(
                    s,
                    clean_text(row.get("raw_url")),
                    timeout,
                    learning_id,
                    row.get("title"),
                    row.get("provider_organizer"),
                    row.get("status"),
                )
                detail_pages += 1
            except Exception as exc:
                detail_errors += 1
                detail_error_ids.append(learning_id)
                logger.debug(
                    "Dalseo learning detail failed id=%s error_type=%s",
                    learning_id,
                    type(exc).__name__,
                )
        for key in (
            "title",
            "category",
            "target",
            "phone",
            "room",
            "venue_name",
            "venue_address",
            "address",
            "period",
            "apply_period",
            "schedule_raw",
            "start_date",
            "end_date",
            "apply_start",
            "apply_end",
            "fee",
            "material_fee",
            "application_method_raw",
            "eligibility_raw",
            "description",
            "capacity_total",
            "waitlist_current",
            "waitlist_total",
        ):
            if detail.get(key) not in (None, "", [], {}):
                row[key] = detail[key]
        if detail:
            organizer = clean_text(row.get("provider_organizer"))
            address = dalseo_learning_branch_address(organizer, row.get("address"))
            row["branch"] = organizer
            row["branch_code"] = dalseo_learning_branch_code(organizer, address)
            row["preserve_branch"] = True
            row["venue_address"] = address
            row["address"] = address
            raw_fields = row.setdefault("raw_fields", {})
            raw_fields["detail_title"] = detail.get("detail_title")
            raw_fields["detail_pairs"] = detail.get("raw_detail_pairs", {})
            raw_fields["application_button_text"] = detail.get("application_button_text")

        reservation_available = row.get("status") in {"OPEN", "WAITING"}
        application_url = dalseo_learning_detail_url(learning_id)
        row["reservation_available"] = bool(reservation_available and application_url)
        if row["reservation_available"]:
            row["application_url"] = application_url
            row["application_type"] = "ONLINE_RESERVATION"
            row.setdefault("raw_fields", {}).pop("clear_application_url", None)
        else:
            row.pop("application_url", None)
            row["application_type"] = "INFO_ONLY"
            row.setdefault("raw_fields", {})["clear_application_url"] = True
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

    if detail_errors:
        add_error(f"detail fetch failed for {detail_errors} current rows")
    rows = dedupe_rows(rows)
    if len(rows) != len(current_rows):
        add_error(f"current course dedupe reduced {len(current_rows)} rows to {len(rows)}")
    collection_complete = bool(
        list_collection_complete
        and not detail_enrichment_capped
        and detail_errors == 0
        and detail_pages == len(current_rows)
        and not errors
    )
    no_current_data = collection_complete and not rows
    no_current_reason = ""
    if no_current_data:
        if declared_total == 0:
            no_current_reason = "official learning list is empty"
        elif native_candidates and expired_rows == len(native_candidates):
            no_current_reason = "all owned native courses are expired"
        elif not native_candidates and external_count == declared_total:
            no_current_reason = "official list contains no owned native courses"
        else:
            no_current_reason = "official learning list has no current owned native courses"
    status_counts: dict[str, int] = {}
    for row in current_rows:
        status = clean_text(row.get("status"))
        status_counts[status] = status_counts.get(status, 0) + 1
    logical_branches = {
        (clean_text(row.get("branch")), clean_text(row.get("address")))
        for row in rows
        if clean_text(row.get("branch")) and clean_text(row.get("address"))
    }
    meta: dict[str, Any] = {
        "pages": pages,
        "total_pages": declared_pages,
        "total_count": declared_total or 0,
        "valid_count": classified_count,
        "native_count": len(native_candidates),
        "external_count": external_count,
        "excluded_external_count": external_count,
        "external_hosts": dict(sorted(external_hosts.items())),
        "external_url_samples": external_samples,
        "external_scope_policy": "excluded_shared_owner_candidates",
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_errors": detail_errors,
        "detail_error_ids": detail_error_ids,
        "detail_candidates": len(current_rows),
        "detail_enrichment_capped": detail_enrichment_capped,
        "detail_enrichment_complete": collection_complete and detail_pages == len(current_rows),
        "discovered_links": classified_count,
        "native_detail_links": len(seen_native_ids),
        "reservation_discovery_links": sum(
            1 for row in rows if clean_text(row.get("application_url"))
        ),
        "reservation_fallback_pages": 0,
        "pagination_detected": declared_pages > 1,
        "pagination_complete": collection_complete,
        "list_pagination_complete": list_collection_complete,
        "pagination_exhausted": list_pagination_exhausted,
        "collection_complete": collection_complete,
        "source_cap_reached": bool(
            (declared_pages and pages < declared_pages) or detail_enrichment_capped
        ),
        "invalid_count": invalid_rows,
        "duplicate_count": duplicate_rows + duplicate_native_ids,
        "repeated_pages": repeated_pages,
        "expired_count": expired_rows,
        "current_count": len(current_rows),
        "status_counts": status_counts,
        "logical_branch_count": len(logical_branches),
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": no_current_reason,
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(errors)
    return rows, DALSEO_LEARNING_PARSER, meta


def jangsu_reserve_status(value: str) -> str:
    text = clean_text(value)
    if not text:
        return ""
    if "접수중" in text or "신청가능" in text:
        return "접수중"
    if "예정" in text:
        return "접수예정"
    if "마감" in text:
        return "접수마감"
    if "강좌중" in text:
        return "강좌중"
    return normalize_status(text) or text


def jangsu_education_list_url(target_url: str) -> str:
    parsed = urlparse(target_url)
    query = parse_qs(parsed.query)
    query["menuCd"] = ["DOM_000000503001000000"]
    query.pop("reUniqId", None)
    query.pop("pageIndex", None)
    return parsed._replace(path="/reserve/index.jangsu", query=urlencode(query, doseq=True)).geturl()


def jangsu_title_branch(title: str, fallback_branch: str) -> tuple[str, str]:
    text = clean_text(title)
    match = re.match(r"^\[([^\]]+)\]\s*(.+)$", text)
    if match:
        return clean_text(match.group(2)), clean_text(match.group(1))
    return text, clean_text(fallback_branch)


def jangsu_periods_from_list(value: str) -> tuple[str, str]:
    text = clean_text(value)
    apply_match = re.search(r"신청\s*[:：]\s*(.+?)(?=\s*교육\s*[:：]|$)", text)
    period_match = re.search(r"교육\s*[:：]\s*(.+)$", text)
    apply_period = bucheon_reservation_datetime_range(apply_match.group(1)) if apply_match else ""
    period = bucheon_reservation_datetime_range(period_match.group(1)) if period_match else ""
    return apply_period, period


def jangsu_capacity(value: str) -> tuple[Optional[int], Optional[int]]:
    text = clean_text(value)
    match = re.search(r"(\d+)\s*명?\s*/\s*(\d+)\s*명?", text)
    if not match:
        return None, None
    return int(match.group(1)), int(match.group(2))


def jangsu_detail_fields(s: requests.Session, url: str, timeout: int, fallback_branch: str) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    view = soup.select_one(".boardViewWrap") or soup.select_one(".bbs_skin") or soup
    title_node = view.select_one(".bdvTit")
    title, branch_from_title = jangsu_title_branch(
        clean_text(title_node.get_text(" ", strip=True) if title_node else ""),
        fallback_branch,
    )
    pairs = pairs_from_definition_lists(view)
    capacity_current, capacity_total = jangsu_capacity(pairs.get("수강인원", ""))
    description = clean_text(view.select_one(".bdvCntWrap").get_text(" ", strip=True) if view.select_one(".bdvCntWrap") else "")
    return {
        "title": title,
        "branch": branch_from_title or fallback_branch,
        "category": clean_text(pairs.get("분야")),
        "status": jangsu_reserve_status(pairs.get("상태", "")),
        "fee": clean_text(pairs.get("수강료")),
        "material_fee": clean_text(pairs.get("교재비용")),
        "capacity": clean_text(pairs.get("수강인원")),
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "period": bucheon_reservation_datetime_range(pairs.get("교육기간", "")),
        "schedule_raw": clean_text(pairs.get("강의시간")),
        "apply_period": bucheon_reservation_datetime_range(pairs.get("접수기간", "")),
        "target": clean_text(pairs.get("대상")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "room": clean_text(pairs.get("교육장소")),
        "venue_name": clean_text(pairs.get("교육장소")) or branch_from_title,
        "phone": clean_text(pairs.get("문의처")),
        "instructor": clean_text(pairs.get("강사명")),
        "description": description,
        "raw_detail_pairs": pairs,
    }


def collect_jangsu_reserve_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    list_url = jangsu_education_list_url(target.url)
    parsed = urlparse(list_url)
    base_query = parse_qs(parsed.query)
    seen_urls: set[str] = set()

    for page in range(1, max_pages + 1):
        query = dict(base_query)
        query["pageIndex"] = [str(page)]
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        table = soup.select_one(".board-list table")
        if not table:
            break
        page_rows = 0
        for tr in table.select("tbody tr"):
            cells = tr.find_all("td")
            if len(cells) < 5:
                continue
            link = tr.select_one("td.title a[href]")
            title_raw = clean_text(link.get_text(" ", strip=True) if link else cells[3].get_text(" ", strip=True))
            if not link or not title_raw:
                continue
            raw_url = normalize_link(page_url, link.get("href")) or page_url
            if raw_url in seen_urls:
                continue
            seen_urls.add(raw_url)
            status = jangsu_reserve_status(cells[1].get_text(" ", strip=True))
            category = clean_text(cells[2].get_text(" ", strip=True))
            apply_period, period = jangsu_periods_from_list(cells[4].get_text(" ", strip=True))
            title, branch = jangsu_title_branch(title_raw, target.branch)
            waitlist_total = parse_capacity_number(cells[5].get_text(" ", strip=True)) if len(cells) > 5 else None
            detail: dict[str, Any] = {}
            if raw_url and detail_pages < detail_limit:
                try:
                    detail = jangsu_detail_fields(s, raw_url, timeout, branch or target.branch)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("jangsu reserve detail fetch failed %s: %s", raw_url, exc)
            final_title = clean_text(detail.get("title")) or title
            final_branch = clean_text(detail.get("branch")) or branch or target.branch
            final_status = clean_text(detail.get("status")) or status
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, final_title, final_branch),
                "title": final_title,
                "branch": final_branch,
                "branch_code": stable_provider(target.provider[:32], final_branch),
                "category": clean_text(detail.get("category")) or category,
                "raw_url": raw_url,
                "application_url": raw_url if final_status in {"접수중", "접수예정"} else "",
                "status": final_status,
                "period": clean_text(detail.get("period")) or period,
                "apply_period": clean_text(detail.get("apply_period")) or apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")),
                "target": clean_text(detail.get("target")),
                "fee": clean_text(detail.get("fee")),
                "material_fee": clean_text(detail.get("material_fee")),
                "capacity": clean_text(detail.get("capacity")),
                "capacity_current": detail.get("capacity_current"),
                "capacity_total": detail.get("capacity_total"),
                "waitlist_total": waitlist_total,
                "room": clean_text(detail.get("room")),
                "venue_name": clean_text(detail.get("venue_name")) or final_branch,
                "phone": clean_text(detail.get("phone")),
                "instructor": clean_text(detail.get("instructor")),
                "description": clean_text(detail.get("description")) or clean_text(tr.get_text(" ", strip=True)),
                "application_method_raw": clean_text(detail.get("application_method_raw")),
                "raw_fields": {
                    "parser": "jangsu_reserve_education_list+detail",
                    "page_url": page_url,
                    "list_period_text": clean_text(cells[4].get_text(" ", strip=True)),
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": bool(pages > 1 or soup.select(".bbs_page a[onclick*='linkPage']")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jangsu_reserve_education_list+detail", meta


BSDONGGU_LIFELONG_LIST_URL = (
    "https://www.bsdonggu.go.kr/index.donggu?"
    "menuCd=DOM_000000701001000000&dummy_Data_Gbn=LifeLong&search_Status=T&data_Title="
)
BSDONGGU_LIFELONG_DEFAULT_BRANCH = "부산 동구 통합예약"
BSDONGGU_LIFELONG_DEFAULT_ADDRESS = "부산광역시 동구 구청로 1"


def bsdonggu_lifelong_list_url(target_url: str) -> str:
    parsed = urlparse(target_url)
    query = parse_qs(parsed.query)
    query["menuCd"] = ["DOM_000000701001000000"]
    query.setdefault("edu_Start_Date_From", [""])
    query.setdefault("edu_Start_Date_To", [""])
    query.setdefault("accept_Start_Date_From", [""])
    query.setdefault("accept_Start_Date_To", [""])
    query.setdefault("data_Title", [""])
    query["search_Status"] = ["T"]
    query.pop("data_Sid", None)
    query.pop("page_no", None)
    query.setdefault("gubun_l", [""])
    return parsed._replace(path="/index.donggu", query=urlencode(query, doseq=True)).geturl()


def bsdonggu_lifelong_page_url(list_url: str, page: int) -> str:
    parsed = urlparse(list_url)
    query = parse_qs(parsed.query)
    query["page_no"] = [str(page)]
    return parsed._replace(query=urlencode(query, doseq=True)).geturl()


def bsdonggu_normalize_date(value: str) -> str:
    text = clean_text(value).replace("\xa0", " ")
    if not text:
        return ""
    text = re.sub(
        r"\b(\d{4})(\d{2})(\d{2})\b",
        lambda match: f"{match.group(1)}-{match.group(2)}-{match.group(3)}",
        text,
    )
    text = re.sub(
        r"(\d{4})[./](\d{1,2})[./](\d{1,2})",
        lambda match: f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}",
        text,
    )
    text = re.sub(r"(\d{1,2})\s*:\s*(\d{2})", lambda match: f"{int(match.group(1)):02d}:{match.group(2)}", text)
    text = re.sub(r"\s*~\s*", " ~ ", text)
    return clean_text(text)


def bsdonggu_date_range(start: str, end: str) -> str:
    start_text = bsdonggu_normalize_date(start)
    end_text = bsdonggu_normalize_date(end)
    if start_text and end_text:
        return f"{start_text} ~ {end_text}"
    return start_text or end_text


def bsdonggu_status(value: str) -> str:
    text = clean_text(value)
    if "접수가능" in text or "접수중" in text:
        return "접수중"
    if "접수대기" in text or "대기" in text:
        return "접수예정"
    if "마감" in text or "종료" in text:
        return "접수마감"
    return normalize_status(text) or text


def bsdonggu_fee(value: str) -> str:
    text = clean_text(value)
    if not text:
        return ""
    if text in {"무료", "없음", "0", "0원"} or "무료" in text:
        return "무료"
    amount = extract_krw_amount(text)
    if amount is not None:
        return f"{amount:,}원"
    return text


def bsdonggu_list_pairs(card: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(card, "select"):
        return pairs
    for item in card.select("dd li"):
        label_node = item.select_one(".name")
        if not label_node:
            continue
        key = clean_text(label_node.get_text(" ", strip=True))
        label_node.extract()
        pairs[key] = clean_text(item.get_text(" ", strip=True))
    return pairs


def bsdonggu_capacity(value: str) -> tuple[Optional[int], Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value)
    current = total = wait_current = wait_total = None
    main = re.search(r"신청자\s*\((\d[\d,]*)\s*/\s*(\d[\d,]*)\)", text)
    if not main:
        main = re.search(r"(\d[\d,]*)\s*/\s*(\d[\d,]*)", text)
    if main:
        current = int(main.group(1).replace(",", ""))
        total = int(main.group(2).replace(",", ""))
    wait = re.search(r"대기자\s*\((\d[\d,]*)\s*/\s*(\d[\d,]*)\)", text)
    if wait:
        wait_current = int(wait.group(1).replace(",", ""))
        wait_total = int(wait.group(2).replace(",", ""))
    return current, total, wait_current, wait_total


def bsdonggu_extract_data_sid(url: str) -> str:
    return clean_text((parse_qs(urlparse(url).query).get("data_Sid") or [""])[0])


def bsdonggu_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    pairs = pairs_from_tables(soup)
    period = bsdonggu_date_range(pairs.get("교육시작일", ""), pairs.get("교육종료일", ""))
    apply_period = bsdonggu_date_range(pairs.get("접수시작일", ""), pairs.get("접수종료일", ""))
    schedule = clean_text(" ".join(part for part in [period, bsdonggu_normalize_date(pairs.get("교육시간", ""))] if part))
    current, total, wait_current, wait_total = bsdonggu_capacity(
        clean_text(f"{pairs.get('신청가능인원', '')} / 대기자 ({pairs.get('대기가능인원', '')})")
    )
    room = clean_text(pairs.get("교육장소"))
    address = clean_text(pairs.get("교육장소주소")) or (
        f"부산광역시 동구 {room}" if room and room not in {"온라인", "비대면"} else BSDONGGU_LIFELONG_DEFAULT_ADDRESS
    )
    fee_text = clean_text(pairs.get("기타경비"))
    description = clean_text(pairs.get("강좌내용"))
    return {
        "title": clean_text(pairs.get("강좌명")),
        "category": clean_text(pairs.get("강좌구분")),
        "description": description,
        "period": period,
        "schedule_raw": schedule,
        "target": clean_text(pairs.get("교육대상")),
        "apply_period": apply_period,
        "capacity": clean_text(pairs.get("신청가능인원")),
        "capacity_current": current,
        "capacity_total": total,
        "waitlist_current": wait_current,
        "waitlist_total": wait_total,
        "room": room,
        "venue_name": room,
        "venue_address": address,
        "phone": clean_text(pairs.get("교육문의전화")),
        "fee": bsdonggu_fee(fee_text),
        "material_fee": extract_material_fee_amount(fee_text, description),
        "material_note": fee_text if fee_text and fee_text not in {"무료", "없음"} else "",
        "raw_detail_pairs": pairs,
    }


def collect_bsdonggu_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    seen: set[str] = set()
    list_url = bsdonggu_lifelong_list_url(target.url)
    pagination_detected = False

    for page in range(1, max_pages + 1):
        page_url = bsdonggu_lifelong_page_url(list_url, page)
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        cards = soup.select(".bbs_ltype2 > dl")
        if not cards:
            break
        page_rows = 0
        for card in cards:
            title_link = None
            for candidate in card.select("dt a[href]"):
                href = clean_text(candidate.get("href"))
                if "data_Sid=" in href:
                    title_link = candidate
                    break
            if not title_link:
                continue
            raw_url = normalize_link(page_url, title_link.get("href")) or page_url
            data_sid = bsdonggu_extract_data_sid(raw_url)
            if data_sid and data_sid in seen:
                continue
            if data_sid:
                seen.add(data_sid)
            title = clean_text(title_link.get_text(" ", strip=True))
            pairs = bsdonggu_list_pairs(card)
            status = bsdonggu_status(card.select_one(".mark").get_text(" ", strip=True) if card.select_one(".mark") else "")
            period = bsdonggu_normalize_date(pairs.get("교육기간", ""))
            apply_period = bsdonggu_normalize_date(pairs.get("접수기간", ""))
            current, total, wait_current, wait_total = bsdonggu_capacity(pairs.get("신청/모집", ""))
            fee = bsdonggu_fee(pairs.get("기타경비", ""))
            room = clean_text(pairs.get("교육장소"))
            detail: dict[str, Any] = {}
            if raw_url and detail_pages < detail_limit:
                try:
                    detail = bsdonggu_detail_fields(s, raw_url, timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("bsdonggu lifelong detail fetch failed %s: %s", raw_url, exc)
            final_title = clean_text(detail.get("title")) or title
            final_room = clean_text(detail.get("room")) or room
            branch = final_room or BSDONGGU_LIFELONG_DEFAULT_BRANCH
            final_status = status
            row = {
                "provider": target.provider,
                "provider_course_id": data_sid or stable_course_id(target.provider, raw_url, final_title, branch),
                "title": final_title,
                "branch": branch,
                "branch_code": stable_provider(target.provider[:32], branch),
                "category": clean_text(detail.get("category")) or "평생학습",
                "raw_url": raw_url,
                "application_url": raw_url if final_status in {"접수중", "접수예정"} else "",
                "status": final_status,
                "period": clean_text(detail.get("period")) or period,
                "apply_period": clean_text(detail.get("apply_period")) or apply_period,
                "schedule_raw": clean_text(detail.get("schedule_raw")) or period,
                "target": clean_text(detail.get("target")) or clean_text(pairs.get("교육대상")),
                "fee": clean_text(detail.get("fee")) or fee,
                "material_fee": detail.get("material_fee"),
                "material_note": clean_text(detail.get("material_note")),
                "capacity": clean_text(detail.get("capacity")) or clean_text(pairs.get("신청/모집")),
                "capacity_current": detail.get("capacity_current") if detail.get("capacity_current") is not None else current,
                "capacity_total": detail.get("capacity_total") if detail.get("capacity_total") is not None else total,
                "waitlist_current": detail.get("waitlist_current") if detail.get("waitlist_current") is not None else wait_current,
                "waitlist_total": detail.get("waitlist_total") if detail.get("waitlist_total") is not None else wait_total,
                "room": final_room,
                "venue_name": clean_text(detail.get("venue_name")) or final_room,
                "venue_address": clean_text(detail.get("venue_address")),
                "phone": clean_text(detail.get("phone")),
                "description": clean_text(detail.get("description")) or clean_text(card.get_text(" ", strip=True)),
                "raw_fields": {
                    "parser": "bsdonggu_lifelong_list+detail",
                    "data_sid": data_sid,
                    "page_url": page_url,
                    "list_pairs": pairs,
                    "detail_pairs": detail.get("raw_detail_pairs", {}),
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".bbs_page a[onclick], a[href*='page_no=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "bsdonggu_lifelong_list+detail", meta


BSJUNGGU_LIFELONG_LIST_URL = (
    "https://www.bsjunggu.go.kr/yeyak/board/list.junggu?"
    "boardId=BBS_0000078&menuCd=DOM_000001001002000000"
)
BSJUNGGU_LIFELONG_CATEGORY_CODES = ("G1", "B1", "A1", "D1", "H1", "C1")
BSJUNGGU_DEFAULT_BRANCH = "부산 중구 통합예약"
BSJUNGGU_DEFAULT_ADDRESS = "부산광역시 중구 대청로116번길 13"


def bsjunggu_fetch_soup(s: requests.Session, url: str, timeout: int) -> BeautifulSoup:
    response = s.get(url, timeout=timeout)
    response.raise_for_status()
    response.encoding = "utf-8"
    return BeautifulSoup(response.text, "lxml")


def bsjunggu_lifelong_page_url(category_code: str, page: int) -> str:
    parsed = urlparse(BSJUNGGU_LIFELONG_LIST_URL)
    query = parse_qs(parsed.query)
    query["categoryCode1"] = [category_code]
    query["nowPage"] = [str(page)]
    return parsed._replace(path="/yeyak/board/list.junggu", query=urlencode(query, doseq=True)).geturl()


def bsjunggu_status(value: str) -> str:
    text = clean_text(value)
    if "접수중" in text:
        return "접수중"
    if "대기" in text:
        return "접수예정"
    if "마감" in text or "종료" in text:
        return "접수마감"
    return normalize_status(text) or text


def bsjunggu_clean_title(value: str) -> str:
    text = clean_text(value)
    text = re.sub(r"^\s*(?:접수중|접수마감|마감|대기중|접수대기)\s*", "", text)
    text = re.sub(r"^\[\s*\d{4}년\s*\]\s*", "", text)
    return clean_text(text)


def bsjunggu_title_branch(value: str, fallback_branch: str = BSJUNGGU_DEFAULT_BRANCH) -> tuple[str, str, str]:
    title = bsjunggu_clean_title(value)
    labels = re.findall(r"\[([^\]]+)\]", title)
    category = clean_text(labels[0]) if labels else ""
    branch = category or fallback_branch
    if category and category in {
        "정보화교육",
        "평생학습프로그램",
        "주민자치프로그램",
        "40계단문화관",
        "보건소 건강아카데미",
        "희망교육",
        "국제화센터프로그램",
        "보수동책방골목문화관",
    }:
        title = clean_text(title.replace(f"[{category}]", "", 1))
    return title, branch, category or "평생학습"


def bsjunggu_pairs(node: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(node, "select"):
        return pairs
    for label_node in node.select("span.name"):
        key = clean_text(label_node.get_text(" ", strip=True))
        parent = label_node.find_parent("li")
        if not key or parent is None:
            continue
        clone = BeautifulSoup(str(parent), "html.parser")
        cloned_label = clone.select_one("span.name")
        if cloned_label:
            cloned_label.extract()
        pairs[key] = clean_text(clone.get_text(" ", strip=True))
    return pairs


def bsjunggu_datasid(url: str) -> str:
    query = parse_qs(urlparse(url).query)
    return clean_text((query.get("dataSid") or query.get("INTNUM") or [""])[0])


def bsjunggu_capacity(value: str, applied: str = "") -> tuple[Optional[int], Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value)
    current = parse_capacity_number(applied)
    total = wait_current = wait_total = None
    total_match = re.search(r"총\s*:?\s*(\d[\d,]*)\s*명", text)
    if total_match:
        total = int(total_match.group(1).replace(",", ""))
    wait_total_match = re.search(r"대기\s*:?\s*(\d[\d,]*)\s*명", text)
    if wait_total_match:
        wait_total = int(wait_total_match.group(1).replace(",", ""))
    split_match = re.search(r"(\d[\d,]*)\s*/\s*(\d[\d,]*)\s*명?", text)
    if split_match:
        current = int(split_match.group(1).replace(",", ""))
        wait_current = int(split_match.group(2).replace(",", ""))
    if total is None:
        number = parse_capacity_number(text)
        if number is not None:
            total = number
    return current, total, wait_current, wait_total


def bsjunggu_extract_place(description: str) -> str:
    text = clean_text(description)
    match = re.search(r"(?:수업|교육)장소\s*[:：]\s*(.+?)(?:\s*○|$)", text)
    return clean_text(match.group(1)) if match else ""


def bsjunggu_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = bsjunggu_fetch_soup(s, url, timeout=timeout)
    detail = soup.select_one(".bbs_vtype.edu") or soup
    info = detail.select_one("dl.infor") or detail
    title_node = info.select_one("dt")
    status = bsjunggu_status(title_node.select_one(".state").get_text(" ", strip=True) if title_node and title_node.select_one(".state") else "")
    title_text = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    title, branch, category = bsjunggu_title_branch(title_text)
    pairs = bsjunggu_pairs(info.select_one("dd.edu") or info)
    institution_pairs = bsjunggu_pairs(detail.select_one("ul.edu_infor") or soup)
    if institution_pairs.get("기관명"):
        branch = clean_text(institution_pairs.get("기관명")) or branch
        category = branch
    description = clean_text((detail.select_one(".contents") or detail).get_text(" ", strip=True))
    description = re.sub(r"^\s*강좌소개\s*", "", description)
    application_link = detail.select_one("a[href*='write.junggu']")
    application_url = normalize_link(url, application_link.get("href") if application_link else None) or ""
    capacity_current, capacity_total, wait_current, wait_total = bsjunggu_capacity(
        pairs.get("수강인원", ""),
        pairs.get("접수인원", ""),
    )
    period = bsdonggu_normalize_date(pairs.get("교육기간", ""))
    time_text = bsdonggu_normalize_date(pairs.get("교육시간", ""))
    schedule = clean_text(" ".join(part for part in (period, time_text) if part))
    room = bsjunggu_extract_place(description)
    return {
        "title": title,
        "branch": branch,
        "category": category or "평생학습",
        "status": status,
        "apply_period": bsdonggu_normalize_date(pairs.get("접수기간", "")),
        "period": period,
        "schedule_raw": schedule,
        "target": clean_text(pairs.get("교육대상")),
        "fee": bsdonggu_fee(pairs.get("수강료", "")),
        "capacity": clean_text(pairs.get("수강인원")),
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_current": wait_current,
        "waitlist_total": wait_total,
        "instructor": clean_text(pairs.get("강사명")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "room": room,
        "venue_name": room or branch,
        "venue_address": clean_text(institution_pairs.get("주소")) or BSJUNGGU_DEFAULT_ADDRESS,
        "phone": clean_text(institution_pairs.get("전화번호")),
        "description": description,
        "application_url": application_url,
        "raw_detail_pairs": pairs,
        "raw_institution_pairs": institution_pairs,
    }


def bsjunggu_card_row(
    target: CrawlTarget,
    page_url: str,
    card: Any,
    s: requests.Session,
    timeout: int,
    detail_pages: int,
    detail_limit: int,
) -> tuple[Optional[dict[str, Any]], int]:
    title_link = card.select_one(".tit a[href]") or card.select_one("a[href*='view.junggu'][href*='dataSid']")
    if not title_link:
        return None, detail_pages
    raw_url = normalize_link(page_url, title_link.get("href")) or page_url
    datasid = bsjunggu_datasid(raw_url)
    title, branch, category = bsjunggu_title_branch(title_link.get_text(" ", strip=True))
    status = bsjunggu_status(card.select_one(".state .txt").get_text(" ", strip=True) if card.select_one(".state .txt") else "")
    target_text = clean_text(card.select_one(".state .targ").get_text(" ", strip=True) if card.select_one(".state .targ") else "")
    apply_period = bsdonggu_normalize_date(card.select_one(".data").get_text(" ", strip=True) if card.select_one(".data") else "")
    pairs = bsjunggu_pairs(card)
    period = bsdonggu_normalize_date(pairs.get("교육기간", ""))
    capacity_current, capacity_total, wait_current, wait_total = bsjunggu_capacity(
        pairs.get("수강인원", ""),
        pairs.get("신청/대기", ""),
    )
    application_link = card.select_one("a[href*='write.junggu']")
    application_url = normalize_link(page_url, application_link.get("href") if application_link else None) or ""
    detail: dict[str, Any] = {}
    if raw_url and detail_pages < detail_limit:
        try:
            detail = bsjunggu_detail_fields(s, raw_url, timeout)
            detail_pages += 1
        except Exception as exc:
            logger.debug("bsjunggu lifelong detail fetch failed %s: %s", raw_url, exc)
    final_title = clean_text(detail.get("title")) or title
    final_branch = clean_text(detail.get("branch")) or branch
    final_status = clean_text(detail.get("status")) or status
    final_application_url = clean_text(detail.get("application_url")) or application_url
    if final_status not in {"접수중", "접수예정"} and final_application_url:
        final_application_url = ""
    row = {
        "provider": target.provider,
        "provider_course_id": datasid or stable_course_id(target.provider, raw_url, final_title, final_branch),
        "title": final_title,
        "branch": final_branch,
        "branch_code": stable_provider(target.provider[:32], final_branch),
        "category": clean_text(detail.get("category")) or category or "평생학습",
        "raw_url": raw_url,
        "application_url": final_application_url,
        "status": final_status,
        "period": clean_text(detail.get("period")) or period,
        "apply_period": clean_text(detail.get("apply_period")) or apply_period,
        "schedule_raw": clean_text(detail.get("schedule_raw")) or period,
        "target": clean_text(detail.get("target")) or target_text,
        "fee": clean_text(detail.get("fee")),
        "capacity": clean_text(detail.get("capacity")) or clean_text(pairs.get("수강인원")),
        "capacity_current": detail.get("capacity_current") if detail.get("capacity_current") is not None else capacity_current,
        "capacity_total": detail.get("capacity_total") if detail.get("capacity_total") is not None else capacity_total,
        "waitlist_current": detail.get("waitlist_current") if detail.get("waitlist_current") is not None else wait_current,
        "waitlist_total": detail.get("waitlist_total") if detail.get("waitlist_total") is not None else wait_total,
        "instructor": clean_text(detail.get("instructor")),
        "application_method_raw": clean_text(detail.get("application_method_raw")) or clean_text(pairs.get("접수방법")),
        "room": clean_text(detail.get("room")),
        "venue_name": clean_text(detail.get("venue_name")) or final_branch,
        "venue_address": clean_text(detail.get("venue_address")),
        "phone": clean_text(detail.get("phone")),
        "description": clean_text(detail.get("description")) or clean_text(card.get_text(" ", strip=True)),
        "raw_fields": {
            "parser": "bsjunggu_lifelong_list+detail",
            "data_sid": datasid,
            "page_url": page_url,
            "list_pairs": pairs,
            "detail_pairs": detail.get("raw_detail_pairs", {}),
            "institution_pairs": detail.get("raw_institution_pairs", {}),
        },
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}, detail_pages


def collect_bsjunggu_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    seen: set[str] = set()
    pagination_detected = False

    home_url = "https://www.bsjunggu.go.kr/lll/index.junggu"
    home_soup = bsjunggu_fetch_soup(s, home_url, timeout=timeout)
    pages += 1
    for card in home_soup.select(".mClass li.swiper-slide .box"):
        row, detail_pages = bsjunggu_card_row(target, home_url, card, s, timeout, detail_pages, detail_limit)
        if not row:
            continue
        key = clean_text(row.get("provider_course_id")) or clean_text(row.get("raw_url"))
        if key in seen:
            continue
        seen.add(key)
        rows.append(row)

    for category_code in BSJUNGGU_LIFELONG_CATEGORY_CODES:
        for page in range(1, max_pages + 1):
            page_url = bsjunggu_lifelong_page_url(category_code, page)
            soup = bsjunggu_fetch_soup(s, page_url, timeout=timeout)
            pages += 1
            cards = soup.select(".bbsEdu > ul > li .box")
            if not cards:
                break
            page_rows = 0
            for card in cards:
                row, detail_pages = bsjunggu_card_row(target, page_url, card, s, timeout, detail_pages, detail_limit)
                if not row:
                    continue
                key = clean_text(row.get("provider_course_id")) or clean_text(row.get("raw_url"))
                if key in seen:
                    continue
                seen.add(key)
                rows.append(row)
                page_rows += 1
            pagination_detected = pagination_detected or bool(soup.select(".pagination a[href*='nowPage'], .paging a[href*='nowPage'], a[href*='nowPage=2']"))
            if page_rows == 0:
                break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "bsjunggu_lifelong_list+detail", meta


def parse_yeonsu_performance_datetime(value: str) -> tuple[str, str]:
    text = clean_text(value)
    date_match = re.search(r"(\d{4})-(\d{1,2})-(\d{1,2})", text)
    if not date_match:
        return "", text
    date_text = f"{date_match.group(1)}-{int(date_match.group(2)):02d}-{int(date_match.group(3)):02d}"
    time_text = ""
    time_match = re.search(r"(오전|오후)\s*(\d{1,2}):(\d{2})(?::\d{2})?", text)
    if time_match:
        hour = int(time_match.group(2))
        minute = int(time_match.group(3))
        if time_match.group(1) == "오후" and hour < 12:
            hour += 12
        elif time_match.group(1) == "오전" and hour == 12:
            hour = 0
        time_text = f"{hour:02d}:{minute:02d}"
    return date_text, time_text


def yeonsu_list_pairs(card: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in card.select(".con > ul > li"):
        label_node = item.select_one("span")
        if not label_node:
            continue
        label = clean_text(label_node.get_text(" ", strip=True))
        label_node.extract()
        value = clean_text(item.get_text(" ", strip=True))
        if label and value:
            pairs[label] = value
    return pairs


def yeonsu_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    container = soup.select_one("#contents .reservation_view") or soup.select_one("#contents") or soup
    pairs = pairs_from_definition_lists(container)
    title_node = container.select_one(".reser_detail .tit") or container.select_one(".tit")
    title = clean_text(title_node.get_text(" ", strip=True)) if title_node else ""
    performance_raw = clean_text(pairs.get("공연일시"))
    date_text, time_text = parse_yeonsu_performance_datetime(performance_raw)
    description_parts: list[str] = []
    for section in container.select(".reser_view_info > div"):
        section_title_node = section.select_one(".tit, h3, h4")
        section_title = clean_text(section_title_node.get_text(" ", strip=True)) if section_title_node else ""
        body_node = section.select_one(".con") or section
        body = clean_text(body_node.get_text(" ", strip=True))
        if body:
            description_parts.append(f"{section_title}: {body}" if section_title else body)

    image_node = container.select_one(".reser_detail .poster img, .poster img")
    image_url = normalize_link(url, image_node.get("src")) if image_node else ""
    reservation_node = next(
        (a for a in container.select("a[href]") if "예매" in clean_text(a.get_text(" ", strip=True))),
        None,
    )
    application_url = normalize_link(url, reservation_node.get("href")) if reservation_node else ""
    capacity_remaining = clean_text(pairs.get("잔여좌석"))
    status = "접수마감" if "마감" in capacity_remaining else ("접수가능" if capacity_remaining else "")
    return {
        "title": title,
        "period": f"{date_text} ~ {date_text}" if date_text else performance_raw,
        "schedule_raw": " ".join(part for part in [date_text, time_text] if part) or performance_raw,
        "schedule_dates": [date_text] if date_text else [],
                    "apply_period": clean_text(pairs.get("\uC811\uC218\uC77C\uC2DC")),
        "sessions": 1 if date_text else None,
        "status": status,
        "capacity_remaining": capacity_remaining,
                    "instructor": clean_text(pairs.get("\uAC15\uC0AC\uBA85")),
        "venue_name": "연수아트홀",
        "branch": "연수아트홀",
        "target": "전체",
        "fee": "무료",
        "description": clean_text(" ".join(description_parts)),
        "image_url": image_url,
        "application_url": application_url,
        "application_type": "online" if application_url else "notice",
        "reservation_available": bool(application_url and status != "접수마감"),
        "raw_fields": {"detail_pairs": pairs, "parser": "yeonsu_friday_art_detail"},
    }


def collect_yeonsu_friday_art(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    visited: set[str] = set()
    queue = [target.url]
    detail_pages = 0
    detail_attempts = 0
    detail_errors = 0
    pagination_detected = False
    pagination_complete = False
    expired_count = 0
    seen_row_urls: set[str] = set()
    today = datetime.now().astimezone().date()

    while queue and len(visited) < max_pages:
        url = queue.pop(0)
        if url in visited:
            continue
        visited.add(url)
        soup = fetch_soup(s, url, timeout=timeout)
        list_root = soup.select_one("#contents .reservation_list") or soup.select_one("#contents") or soup
        cards = list_root.select(":scope > ul > li")
        valid_cards = 0
        expired_on_page = 0
        for card in cards:
            title_node = card.select_one(".con .tit") or card.select_one(".tit")
            title = clean_text(title_node.get_text(" ", strip=True)) if title_node else ""
            if not title:
                continue
            valid_cards += 1
            pairs = yeonsu_list_pairs(card)
            performance_raw = clean_text(pairs.get("공연일시"))
            date_text, time_text = parse_yeonsu_performance_datetime(performance_raw)
            detail_node = next(
                (a for a in card.select("a[href]") if "상세" in clean_text(a.get_text(" ", strip=True))),
                None,
            )
            reserve_node = next(
                (a for a in card.select("a[href]") if "예매" in clean_text(a.get_text(" ", strip=True))),
                None,
            )
            raw_url = normalize_link(url, detail_node.get("href")) if detail_node else url
            if raw_url in seen_row_urls:
                continue
            seen_row_urls.add(raw_url)
            application_url = normalize_link(url, reserve_node.get("href")) if reserve_node else ""
            image_node = card.select_one(".poster img")
            image_url = normalize_link(url, image_node.get("src")) if image_node else ""
            capacity_remaining = clean_text(pairs.get("잔여좌석"))
            status = "접수마감" if "마감" in capacity_remaining else ("접수가능" if capacity_remaining else "")
            row: dict[str, Any] = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, "연수아트홀"),
                "title": title,
                "branch": "연수아트홀",
                "venue_name": "연수아트홀",
                "category": "공연/전시",
                "category_raw": "금요예술무대",
                "period": f"{date_text} ~ {date_text}" if date_text else performance_raw,
                "schedule_raw": " ".join(part for part in [date_text, time_text] if part) or performance_raw,
                "schedule_dates": [date_text] if date_text else [],
                    "apply_period": clean_text(pairs.get("\uC811\uC218\uC77C\uC2DC")),
                "sessions": 1 if date_text else None,
                "target": "전체",
                "fee": "무료",
                "status": status,
                "capacity_remaining": capacity_remaining,
                "raw_url": raw_url,
                "application_url": application_url,
                "application_type": "online" if application_url else "notice",
                "reservation_available": bool(application_url and status != "접수마감"),
                "image_url": image_url,
                "description": clean_text(card.get_text(" ", strip=True)),
                "raw_fields": {"list_pairs": pairs, "parser": "yeonsu_friday_art_cards"},
            }
            _, end_date = parse_date_range(row["period"])
            if end_date and end_date < today:
                expired_count += 1
                expired_on_page += 1
                continue
            if raw_url and raw_url != url and detail_pages < detail_limit:
                detail_attempts += 1
                try:
                    detail = yeonsu_detail_fields(s, raw_url, timeout)
                    detail_raw = detail.pop("raw_fields", {})
                    row.update({key: value for key, value in detail.items() if value not in (None, "", [])})
                    row.setdefault("raw_fields", {})["detail"] = detail_raw
                    detail_pages += 1
                except Exception as exc:
                    detail_errors += 1
                    logger.debug("yeonsu detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)

        if valid_cards and expired_on_page == valid_cards:
            pagination_complete = True
            queue.clear()
            break

        for a in list_root.select(".paging a[href]"):
            link = normalize_link(url, a.get("href"))
            if link and link not in visited and link not in queue:
                queue.append(link)
                pagination_detected = True

    if not queue:
        pagination_complete = True
    details_complete = (
        detail_attempts == len(rows)
        and detail_pages == detail_attempts
        and detail_errors == 0
    )
    snapshot_complete = pagination_complete and details_complete
    meta = {
        "pages": len(visited),
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_errors": detail_errors,
        "discovered_links": len(rows),
        "expired_count": expired_count,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_complete,
        "detail_collection_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "no_current_data": snapshot_complete and not rows,
        "no_current_reason": (
            "official Yeonsu Friday Art list has no current programs"
            if snapshot_complete and not rows
            else ""
        ),
    }
    return dedupe_rows(rows), "yeonsu_friday_art_cards+detail", meta


def gwe_library_list_url(target_url: str, start_soup: BeautifulSoup) -> str:
    parsed = urlparse(target_url)
    match = re.search(r"(/[^/]+/menu/)(\d+)(?:/|$)", parsed.path)
    if match:
        return f"{parsed.scheme}://{parsed.netloc}{match.group(1)}{match.group(2)}/lecture-event/list/all"
    for link in start_soup.find_all("a", href=True):
        href = normalize_link(target_url, link.get("href"))
        if href and "/lecture-event/list/" in urlparse(href).path:
            return href
    return target_url


def gwe_library_dl_pairs(root: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in root.select("dl"):
        children = [child for child in dl.children if getattr(child, "name", None) in {"dt", "dd"}]
        i = 0
        while i < len(children) - 1:
            if children[i].name == "dt" and children[i + 1].name == "dd":
                label = clean_text(children[i].get_text(" ", strip=True)).rstrip(":")
                value = clean_text(children[i + 1].get_text(" ", strip=True))
                if label:
                    pairs[label] = value
                i += 2
            else:
                i += 1
    return pairs


def gwe_library_style_image(base_url: str, node: Any) -> str:
    style = clean_text(node.get("style") if node else "")
    match = re.search(r"url\(['\"]?([^'\")]+)", style)
    return normalize_link(base_url, match.group(1)) if match else ""


def gwe_library_fee_text(value: Any) -> str:
    text = clean_text(value)
    if not text or text in {"-", "없음", "해당없음"}:
        return "무료"
    return text


def gwe_library_row_expired(row: dict[str, Any]) -> bool:
    _start, end = parse_date_range(row.get("period"))
    return bool(end and end < datetime.now().astimezone().date())


def gwe_library_course_id(provider: str, raw_url: str, title: str, branch: str) -> str:
    match = re.search(r"/lecture-event/(\d+)", urlparse(raw_url).path)
    if match:
        return match.group(1)
    return stable_course_id(provider, raw_url, title, branch)


def gwe_library_footer_contact(soup: BeautifulSoup, library_name: str) -> tuple[str, str]:
    name = clean_text(library_name)
    area = re.sub(r"(교육도서관|교육문화관|도서관|문화관)$", "", name).strip()
    for dl in soup.select("dl"):
        pairs = gwe_library_dl_pairs(dl)
        address = clean_text(re.sub(r"^\d+\)?\s*", "", pairs.get("주소", "")))
        phone = clean_text(pairs.get("TEL"))
        if not address:
            text = clean_text(dl.get_text(" | ", strip=True))
            if (name and name in text) or (area and area in text):
                address_match = re.search(r"주소\s*\|?\s*(.*?)(?:\s*\|\s*TEL|\s+TEL\s+|$)", text)
                phone_match = re.search(r"TEL\s*\|?\s*(.*?)(?:\s*\|\s*FAX|\s+FAX\s+|$)", text)
                address = clean_text(address_match.group(1) if address_match else "")
                phone = clean_text(phone_match.group(1) if phone_match else "")
                if not phone and "|" in text:
                    parts = [clean_text(part) for part in text.split("|")]
                    for index, part in enumerate(parts[:-1]):
                        if part == "TEL":
                            phone = parts[index + 1]
                            break
                address = clean_text(re.sub(r"^우\s*\d{5}\)?\s*", "", address))
        if not address:
            continue
        if (name and name in address) or (area and area in address):
            if not phone:
                page_text = clean_text(soup.get_text(" ", strip=True))
                phone_match = re.search(re.escape(address) + r".{0,120}?TEL\s+(.+?)(?:\s+FAX\s+|$)", page_text)
                phone = clean_text(phone_match.group(1) if phone_match else "")
            return address, phone
    return "", ""


def gwe_library_detail_fields(s: requests.Session, raw_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, raw_url, timeout=timeout)
    detail_root = soup.select_one(".lecture_detail") or soup
    pairs = gwe_library_dl_pairs(detail_root)
    library_name = clean_text(pairs.get("도서관"))
    address, phone = gwe_library_footer_contact(soup, library_name)
    day_period = normalize_mixed_date_range(clean_text(pairs.get("운영기간")))
    time_text = clean_text(pairs.get("운영시간"))
    description = clean_text(pairs.get("안내사항") or pairs.get("강좌소개") or pairs.get("상세내용"))
    if not description:
        text = clean_text(detail_root.get_text(" ", strip=True))
        if "안내사항" in text:
            description = clean_text(text.split("안내사항", 1)[1])
    image_node = detail_root.select_one("img[src*='/uploads/lectureEvent/'], img[src*='/uploads/editor/']")
    return {
        "category": clean_text(pairs.get("교육과정")),
        "instructor": clean_text(pairs.get("강사명")),
        "period": day_period,
        "schedule_raw": time_text,
        "apply_period": normalize_mixed_date_range(pairs.get("접수일시", "")),
        "target": clean_text(pairs.get("교육대상")),
        "capacity": clean_text(pairs.get("모집인원")),
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "room": clean_text(pairs.get("장소")),
        "venue_name": clean_text(pairs.get("장소")),
        "fee": gwe_library_fee_text(pairs.get("참가비")),
        "material_fee": "" if clean_text(pairs.get("재료비")) in {"-", "없음", "해당없음"} else clean_text(pairs.get("재료비")),
        "material_note": clean_text(pairs.get("준비물")).replace("-", ""),
        "description": description,
        "address": address,
        "venue_address": address,
        "phone": phone,
        "image_url": normalize_link(raw_url, image_node.get("src")) if image_node else "",
        "raw_detail_pairs": pairs,
    }


def collect_gwe_library_events_detail(target: CrawlTarget, timeout: int, max_pages: int, detail_limit: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    start_soup = fetch_soup(s, target.url, timeout=timeout)
    list_url = target.url if "/lecture-event/list/" in urlparse(target.url).path else gwe_library_list_url(target.url, start_soup)
    parsed = urlparse(list_url)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    no_current_data = False

    for page in range(1, max_pages + 1):
        current_url = list_url
        if page > 1:
            query = parse_qs(parsed.query)
            query["page"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        page_text = clean_text(soup.get_text(" ", strip=True))
        no_current_data = no_current_data or "조회되는 문화강좌가 없습니다" in page_text or bool(re.search(r"전체\s*0\s*건", page_text))
        pages += 1
        page_rows = 0
        for item in soup.select(".lecture_item"):
            page_rows += 1
            title_el = item.select_one(".lecture_item__title a[href]")
            title = clean_text(title_el.get_text(" ", strip=True) if title_el else "")
            if not title:
                continue
            raw_url = normalize_link(current_url, title_el.get("href")) or current_url
            branch = clean_text((item.select_one(".lecture_item__library") or {}).get_text(" ", strip=True) if item.select_one(".lecture_item__library") else "") or target.branch
            status_el = item.select_one(".applyStatusButton, .registrationCheckButton")
            status = clean_text(status_el.get_text(" ", strip=True) if status_el else "")
            pairs = gwe_library_dl_pairs(item)
            image_url = gwe_library_style_image(current_url, item.select_one(".lecture_item__poster"))
            capacity = clean_text(pairs.get("모집인원"))
            capacity_current, capacity_total = parse_capacity_pair(capacity)
            row = {
                "provider": target.provider,
                "provider_course_id": gwe_library_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "branch_code": urlparse(target.url).path.strip("/").split("/", 1)[0],
                "category": clean_text((status_el or {}).get("data-category-name") if status_el else ""),
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": "",
                "period": normalize_mixed_date_range(pairs.get("운영기간", "")),
                "apply_period": normalize_mixed_date_range(pairs.get("신청기간", "")),
                "schedule_raw": clean_text(pairs.get("운영기간", "")),
                "target": clean_text(pairs.get("신청대상")),
                "capacity": capacity,
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "application_method_raw": clean_text(pairs.get("모집방법")),
                "description": clean_text(item.get_text(" ", strip=True)),
                "image_url": image_url,
                "collection_category": "도서관",
                "domain_category": "도서관",
                "operator_type": "교육청/도서관",
                "source_group": "library",
                "collection_type": "static_html",
                "application_type": "ONLINE_RESERVATION",
                "reservation_available": status in {"접수중", "대기자접수"},
                "raw_fields": {"list_pairs": pairs, "parser": "gwe_library_lecture_event+detail"},
            }
            if gwe_library_row_expired(row):
                continue
            if raw_url and detail_pages < max(0, detail_limit):
                try:
                    detail = gwe_library_detail_fields(s, raw_url, timeout=timeout)
                    raw_detail_pairs = detail.pop("raw_detail_pairs", {})
                    row.update({key: value for key, value in detail.items() if value not in (None, "", [])})
                    row["raw_fields"]["detail_pairs"] = raw_detail_pairs
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("GWE library detail fetch failed %s: %s", raw_url, exc)
            if gwe_library_row_expired(row):
                continue
            rows.append(row)
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "pagination_detected": bool(rows) and pages >= max_pages,
        "recursion_depth": 0,
        "no_current_data": no_current_data and not rows,
        "no_current_reason": "no_current_gwe_library_events" if no_current_data and not rows else "",
    }
    if not rows and not no_current_data:
        logger.info("GWE detail-layout parser returned no rows; trying the bounded list-layout parser.")
        return collect_gwe_library_events(target, timeout=timeout, max_pages=max_pages)
    return dedupe_rows(rows), "gwe_library_lecture_event+detail", meta


def collect_gwe_library_events(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    start_soup = fetch_soup(s, target.url, timeout=timeout)
    list_url = target.url
    if "/lecture-event/list/" not in urlparse(target.url).path:
        for link in start_soup.find_all("a", href=True):
            href = normalize_link(target.url, link.get("href"))
            if href and "/lecture-event/list/" in urlparse(href).path:
                list_url = href
                break
    parsed = urlparse(list_url)
    rows: list[dict[str, Any]] = []
    pages = 0
    stop_labels = ("신청기간", "운영기간", "신청대상", "모집방법", "모집인원")

    for page in range(1, max_pages + 1):
        current_url = list_url
        if page > 1:
            query = parse_qs(parsed.query)
            query["page"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = start_soup if current_url == target.url and list_url == target.url else fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for item in soup.select(".lecture_item"):
            title_el = item.select_one(".lecture_item__title")
            title = clean_text(title_el.get_text(" ", strip=True) if title_el else "")
            if not title:
                link = item.find("a", href=True)
                title = clean_text(link.get_text(" ", strip=True) if link else "")
            if not title:
                continue
            link = item.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            text = clean_text(item.get_text(" ", strip=True))
            branch = clean_text((item.select_one(".lecture_item__library") or {}).get_text(" ", strip=True) if item.select_one(".lecture_item__library") else "") or target.branch
            status_el = item.select_one(".applyStatusButton, .registrationCheckButton")
            status = clean_text(status_el.get_text(" ", strip=True) if status_el else "")
            capacity = extract_korean_labeled_value(text, "모집인원", stop_labels)
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": clean_text((status_el or {}).get("data-category-name") if status_el else ""),
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "",
                    "period": extract_korean_labeled_value(text, "운영기간", stop_labels),
                    "apply_period": extract_korean_labeled_value(text, "신청기간", stop_labels),
                    "schedule_raw": extract_korean_labeled_value(text, "운영기간", stop_labels),
                    "target": extract_korean_labeled_value(text, "신청대상", stop_labels),
                    "capacity": capacity,
                    "application_method_raw": extract_korean_labeled_value(text, "모집방법", stop_labels),
                    "description": text,
                    "image_url": normalize_link(current_url, (item.find("img") or {}).get("src") if item.find("img") else None),
                    "raw_fields": {"text": text, "parser": "gwe_library_lecture_event"},
                }
            )
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": bool(rows) and pages >= max_pages,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gwe_library_lecture_event", meta


SEOGU_LIBRARY_BRANCHES = {
    "galmalib": ("갈마도서관", "대전광역시 서구 신갈마로127번길 138"),
    "gasuwonlib": ("가수원도서관", "대전광역시 서구 가수원로 91-11"),
    "dunsanlib": ("둔산도서관", "대전광역시 서구 청사로 263"),
    "wolpyeonglib": ("월평도서관", "대전광역시 서구 월평서로 13"),
    "childlib": ("어린이도서관", "대전광역시 서구 정림동로 25"),
}


def seogu_library_branch_from_url(url: str) -> tuple[str, str, str]:
    path = urlparse(url).path
    match = re.search(r"/library/([^/]+)/", path)
    key = match.group(1) if match else "wolpyeonglib"
    name, address = SEOGU_LIBRARY_BRANCHES.get(key, ("대전 서구 도서관", "대전광역시 서구"))
    return key, name, address


def seogu_library_list_url(url: str) -> str:
    parsed = urlparse(url)
    if parsed.path.endswith("/index.do"):
        base_path = parsed.path.rsplit("/", 1)[0] + "/contents/learning/lib/02/lib.02.001.motion"
        return parsed._replace(path=base_path, query="mnucd=MENU0600030").geturl()
    if "lib.02.001.motion" in parsed.path and "bmode=detail" in parsed.query:
        query = parse_qs(parsed.query)
        query.pop("bmode", None)
        query.pop("lecId", None)
        query["mnucd"] = [query.get("mnucd", ["MENU0600030"])[0]]
        return parsed._replace(query=urlencode(query, doseq=True)).geturl()
    return url


def seogu_library_detail_url(list_url: str, lec_id: str) -> str:
    parsed = urlparse(list_url)
    query = parse_qs(parsed.query)
    mnucd = query.get("mnucd", ["MENU0600030"])[0]
    detail_query = {
        "bmode": "detail",
        "lecId": lec_id,
        "mnucd": mnucd,
    }
    return parsed._replace(query=urlencode(detail_query)).geturl()


def seogu_library_pairs_from_detail(soup: BeautifulSoup) -> dict[str, str]:
    table = soup.select_one("table.tbl_basic_view")
    if not table:
        return {}
    pairs: dict[str, str] = {}
    for tr in table.select("tr"):
        cells = [cell for cell in tr.find_all(["th", "td"], recursive=False)]
        if len(cells) == 2:
            key = clean_text(cells[0].get_text(" ", strip=True))
            value = clean_text(cells[1].get_text(" ", strip=True))
            if key and value:
                pairs[key] = value
        elif len(cells) >= 4:
            key1 = clean_text(cells[0].get_text(" ", strip=True))
            val1 = clean_text(cells[1].get_text(" ", strip=True))
            key2 = clean_text(cells[2].get_text(" ", strip=True))
            val2 = clean_text(cells[3].get_text(" ", strip=True))
            if key1 and val1:
                pairs[key1] = val1
            if key2 and val2:
                pairs[key2] = val2
        elif len(cells) == 1 and clean_text(cells[0].get_text(" ", strip=True)) == "강의내용":
            next_row = tr.find_next_sibling("tr")
            if next_row:
                content = next_row.select_one(".content_box") or next_row.find("td")
                if content:
                    pairs["강의내용"] = clean_text(content.get_text(" ", strip=True))
                    image = content.find("img")
                    if image:
                        pairs["image_url"] = normalize_link(soup.base.get("href") if soup.base else "", image.get("src"))
    return pairs


def seogu_library_status(capacity: str, apply_period: str) -> str:
    current, total = parse_capacity_pair(capacity)
    if current is not None and total is not None and total > 0 and current >= total:
        return "접수마감"
    _, apply_end = parse_date_range(apply_period)
    if apply_end and apply_end < datetime.now().date():
        return "접수마감"
    return "접수가능" if apply_period or capacity else ""


def _legacy_collect_seogu_library_classes(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_url = seogu_library_list_url(target.url)
    parsed = urlparse(list_url)
    branch_code, branch_name, branch_address = seogu_library_branch_from_url(list_url)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False

    for page in range(1, max_pages + 1):
        current_url = list_url
        if page > 1:
            query = parse_qs(parsed.query)
            query["pageIndex"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        table = soup.select_one("table.tbl_basic")
        if not table:
            break
        page_rows = 0
        for tr in table.select("tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) < 7:
                continue
            link = tr.select_one("td.left a[onclick], td a[onclick]")
            onclick = clean_text(link.get("onclick")) if link else ""
            lec_match = re.search(r"'(LEC_[^']+)'", onclick)
            lec_id = lec_match.group(1) if lec_match else cells[0]
            title = clean_text(link.get_text(" ", strip=True)) if link else cells[2]
            detail_url = seogu_library_detail_url(list_url, lec_id)
            category = cells[1]
            target_text = cells[3]
            period = normalize_mixed_date_range(cells[4])
            schedule_raw = " ".join(part for part in [period, cells[5]] if part)
            capacity = cells[6]
            detail_pairs: dict[str, str] = {}
            if detail_pages < detail_limit:
                try:
                    detail_soup = fetch_soup(s, detail_url, timeout=timeout)
                    detail_pairs = seogu_library_pairs_from_detail(detail_soup)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("seogu library detail fetch failed %s: %s", detail_url, exc)

            detail_title = clean_text(detail_pairs.get("제목"))
            if detail_title:
                bracket_match = re.search(r"\]\s*(.+)$", detail_title)
                title = clean_text(bracket_match.group(1) if bracket_match else detail_title)
            period = normalize_mixed_date_range(detail_pairs.get("일시") or period)
            schedule_raw = " ".join(
                part
                for part in [
                    period,
                    clean_text(detail_pairs.get("요일")),
                    clean_text(detail_pairs.get("시간")) or cells[5],
                ]
                if part
            )
            apply_period = clean_text(detail_pairs.get("신청기간"))
            capacity = clean_text(detail_pairs.get("모집인원") or capacity)
            description = clean_text(detail_pairs.get("강의내용")) or clean_text(tr.get_text(" ", strip=True))
            image_url = clean_text(detail_pairs.get("image_url"))

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, detail_url, title, branch_name),
                    "title": title,
                    "branch": branch_name,
                    "branch_code": branch_code,
                    "address": branch_address,
                    "venue_name": branch_name,
                    "venue_address": branch_address,
                    "category": category,
                    "category_raw": category,
                    "raw_url": detail_url,
                    "application_url": detail_url,
                    "application_type": "online",
                    "status": seogu_library_status(capacity, apply_period),
                    "fee": "무료",
                    "period": period,
                    "schedule_raw": schedule_raw,
                    "apply_period": apply_period,
                        "target": clean_text(detail_pairs.get("\uAD50\uC721\uB300\uC0C1")) or target_text,
                    "capacity": capacity,
                    "waitlist_total": clean_text(detail_pairs.get("예비인원")),
                    "instructor": clean_text(detail_pairs.get("강사")),
                    "description": description,
                    "image_url": image_url,
                    "reservation_available": "접수" in seogu_library_status(capacity, apply_period),
                    "raw_fields": {
                        "cells": cells,
                        "detail_pairs": detail_pairs,
                        "parser": "seogu_library_classes",
                    },
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination a.pagenum"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "seogu_library_classes+detail", meta


YJLIB_BRANCH_ALIASES = {
    "여주": "여주도서관",
    "세종": "세종도서관",
    "점동": "점동도서관",
    "여흥": "여흥작은도서관",
    "북내": "북내작은도서관",
    "여주기적": "여주기적의도서관",
    "흥천": "흥천도서관",
    "금사": "금사도서관",
}


def yjlib_normalize_branch(raw_branch: Any, title: Any = "", venue_name: Any = "") -> str:
    branch = clean_text(raw_branch)
    title_text = clean_text(title)
    venue_text = clean_text(venue_name)
    for value in (venue_text, title_text):
        match = re.search(r"([가-힣A-Za-z0-9]+(?:기적의도서관|작은도서관|도서관))", value)
        if match:
            return clean_text(match.group(1))
    if branch in YJLIB_BRANCH_ALIASES:
        return YJLIB_BRANCH_ALIASES[branch]
    if branch and not branch.endswith("도서관"):
        return f"{branch}도서관"
    return branch or "여주시립도서관"


def yjlib_detail_pairs(view: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for block in view.select(".info > div"):
        label_el = block.find("strong", recursive=False)
        value_el = block.find("div", recursive=False)
        label = clean_text(label_el.get_text(" ", strip=True) if label_el else "")
        if not label or not value_el:
            continue
        pairs[label] = clean_text(value_el.get_text(" ", strip=True))
    return pairs


def yjlib_clean_period(value: Any) -> str:
    return clean_text(re.sub(r"\b(?:교육예정|교육중|교육종료|접수예정|접수중|접수종료|대기접수)\b", " ", clean_text(value)))


def fetch_yjlib_detail(s: requests.Session, raw_url: str, timeout: int) -> dict[str, Any]:
    detail: dict[str, Any] = {}
    try:
        soup = fetch_soup(s, raw_url, timeout=timeout)
    except RequestException as exc:
        logger.debug("YJLIB detail fetch failed %s: %s", raw_url, exc)
        return detail
    view = soup.select_one(".article-view")
    if not view:
        return detail

    title_el = view.select_one("h6.title")
    raw_branch = clean_text((title_el.select_one(".lib") or {}).get_text(" ", strip=True) if title_el and title_el.select_one(".lib") else "")
    if title_el:
        for child in title_el.select(".lib"):
            child.extract()
    title = clean_text(title_el.get_text(" ", strip=True) if title_el else "")
    pairs = yjlib_detail_pairs(view)
    venue_name = clean_text(pairs.get("장소"))
    weekday = clean_text(pairs.get("강좌요일"))
    time_text = clean_text(pairs.get("강좌시간"))
    schedule_raw = clean_text(" ".join(part for part in (weekday, time_text) if part))
    con_area = view.select_one(".conArea")
    description = clean_text(con_area.get_text(" ", strip=True) if con_area else view.get_text(" ", strip=True))
    image_el = con_area.select_one("img[src]") if con_area else None
    fee_text = clean_text(pairs.get("수강료 및 재료비"))
    material_note = clean_text(" / ".join(part for part in (fee_text, pairs.get("준비물")) if clean_text(part) and clean_text(part) != "-"))

    detail.update(
        {
            "title": title,
            "branch": yjlib_normalize_branch(raw_branch, title, venue_name),
            "period": yjlib_clean_period(pairs.get("강좌기간")),
            "schedule_raw": schedule_raw,
            "target": clean_text(pairs.get("교육대상")),
            "room": venue_name,
            "venue_name": venue_name,
            "instructor": clean_instructor_name(pairs.get("강사명")),
            "fee": fee_text or "무료",
            "material_note": material_note,
            "material_fee": extract_material_fee_amount(fee_text, material_note, description),
            "apply_period": clean_text(pairs.get("접수일시")),
            "status": clean_text(
                (view.select_one(".status") or view.select_one(".eduStat") or {}).get_text(" ", strip=True)
                if (view.select_one(".status") or view.select_one(".eduStat"))
                else ""
            ),
            "capacity": clean_text(pairs.get("접수현황")),
            "phone": clean_text(pairs.get("문의전화")),
            "description": description,
            "image_url": urljoin(raw_url, image_el.get("src")) if image_el else "",
            "raw_fields": {"pairs": pairs, "parser": "yjlib_article_detail"},
        }
    )
    return {key: value for key, value in detail.items() if value not in (None, "")}


def collect_yjlib_lecture_list(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 0,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    pagination_exhausted = False

    for page in range(1, max_pages + 1):
        query["currentPageNo"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='currentPageNo']"))

        for item in soup.select(".article-item"):
            title_el = item.select_one(".info-title .title")
            title = clean_text(title_el.get_text(" ", strip=True) if title_el else "")
            if not title:
                continue
            onclick = clean_text(title_el.get("onclick") if title_el else "")
            detail_id = ""
            match = re.search(r"fnDetail\('([^']+)'\)", onclick)
            if match:
                detail_id = match.group(1)
            detail_query = parse_qs(parsed.query)
            detail_query["lectureIdx"] = [detail_id or "0"]
            raw_url = parsed._replace(path="/web/menu/10071/program/30020/lectureDetail.do", query=urlencode(detail_query, doseq=True)).geturl()

            category = clean_text((item.select_one(".info-cate .type") or {}).get_text(" ", strip=True) if item.select_one(".info-cate .type") else "")
            raw_branch = clean_text((item.select_one(".info-cate .lib") or {}).get_text(" ", strip=True) if item.select_one(".info-cate .lib") else "") or target.branch
            status = clean_text((item.select_one(".item-status .status") or {}).get_text(" ", strip=True) if item.select_one(".item-status .status") else "")
            if not status:
                status = clean_text((item.select_one(".eduStat") or {}).get_text(" ", strip=True) if item.select_one(".eduStat") else "")

            pairs: dict[str, str] = {}
            for p in item.select(".info-info p"):
                label_el = p.find("b")
                label = clean_text(label_el.get_text(" ", strip=True) if label_el else "")
                if not label:
                    continue
                if label_el:
                    label_el.extract()
                pairs[label] = clean_text(p.get_text(" ", strip=True).lstrip(":"))

            capacity_text = clean_text((item.select_one(".apply-num") or {}).get_text(" ", strip=True) if item.select_one(".apply-num") else "")
            venue_name = clean_text(pairs.get("장소"))
            branch = yjlib_normalize_branch(raw_branch, title, venue_name)
            row = {
                "provider": target.provider,
                "title": title,
                "branch": branch,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "fee": "무료",
                "period": clean_text(pairs.get("\uAD50\uC721\uAE30\uAC04")),
                "apply_period": clean_text(pairs.get("\uC811\uC218\uC77C\uC2DC")),
                "schedule_raw": clean_text(pairs.get("\uC694\uC77C/\uC2DC\uAC04") or pairs.get("\uAD50\uC721\uAE30\uAC04")),
                "target": clean_text(pairs.get("\uAD50\uC721\uB300\uC0C1") or pairs.get("대상")),
                "room": venue_name,
                "venue_name": venue_name,
                "capacity": capacity_text,
                "description": clean_text(item.get_text(" ", strip=True)),
                "raw_fields": {"pairs": pairs, "capacity": capacity_text, "detail_id": detail_id, "parser": "yjlib_article_cards"},
            }
            if detail_id and detail_pages < max(0, detail_limit):
                detail = fetch_yjlib_detail(s, raw_url, timeout)
                detail_pages += 1
                if detail:
                    raw_fields = dict(row.get("raw_fields") or {})
                    raw_fields["detail"] = detail.get("raw_fields")
                    row.update({key: value for key, value in detail.items() if key != "raw_fields"})
                    row["raw_fields"] = raw_fields
            row["provider_course_id"] = stable_course_id(target.provider, raw_url, row.get("title"), row.get("branch"))
            rows.append(row)
            page_rows += 1
        if page_rows == 0:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "source_cap_reached": not pagination_exhausted,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "yjlib_article_cards+detail", meta


CNALL_BRANCH_ALIASES = {
    "학생교육문화원": "충청남도교육청학생교육문화원",
    "평생교육원": "충청남도교육청평생교육원",
    "남부평생교육원": "충청남도교육청남부평생교육원",
    "서부평생교육원": "충청남도교육청서부평생교육원",
    "진로융합교육원": "충청남도교육청진로융합교육원",
}


def cnall_normalize_branch(value: Any) -> str:
    branch = clean_text(value)
    return CNALL_BRANCH_ALIASES.get(branch, branch)


def cnall_clean_target(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    parts = [clean_text(part) for part in re.split(r"\s*(?:/|,|쨌)\s*", text) if clean_text(part)]
    if not parts:
        return text
    return " 쨌 ".join(dict.fromkeys(parts))


def cnall_branch_from_organ_name(value: Any) -> str:
    name = clean_text(value)
    if not name:
        return ""
    if "교육지원청" in name:
        return cnall_normalize_branch(name.split("교육지원청", 1)[1])
    return cnall_normalize_branch(name)


def cnall_fetch_organ_map(s: requests.Session, base_url: str, timeout: int) -> dict[str, dict[str, str]]:
    url = urljoin(base_url, "/organ/organList.do")
    try:
        soup = fetch_soup(s, url, timeout=timeout)
    except RequestException as exc:
        logger.debug("CNALL organ list fetch failed %s: %s", url, exc)
        return {}

    organ_map: dict[str, dict[str, str]] = {}
    for tr in soup.select("table.board-list tr"):
        tds = tr.select("td")
        if len(tds) < 4:
            continue
        region = clean_text(tds[0].get_text(" ", strip=True))
        organ_name = clean_text(tds[1].get_text(" ", strip=True))
        branch = cnall_branch_from_organ_name(organ_name)
        address = clean_text(tds[2].get_text(" ", strip=True))
        phone = clean_text(tds[3].get_text(" ", strip=True))
        website_url = ""
        organ_idx = ""
        for link in tds[1].select("a[href]"):
            href = clean_text(link.get("href"))
            if href and "#none" not in href:
                website_url = urljoin(url, href)
                break
        for link in tr.select("a[href]"):
            href = clean_text(link.get("href"))
            match = re.search(r"organIdxArr=(\d+)", href)
            if match:
                organ_idx = match.group(1)
                break
        if not branch:
            continue
        data = {
            "branch": branch,
            "branch_code": f"organ_{organ_idx}" if organ_idx else "",
            "organ_name": organ_name,
            "region": region,
            "address": address,
            "phone": phone,
            "website_url": website_url,
        }
        for key in {branch, organ_name, cnall_normalize_branch(branch)}:
            if key:
                organ_map[key] = data
    return organ_map


def cnall_apply_organ_data(row: dict[str, Any], organ_map: dict[str, dict[str, str]]) -> dict[str, Any]:
    branch = cnall_normalize_branch(row.get("branch"))
    data = organ_map.get(branch) or organ_map.get(clean_text(row.get("venue_name")))
    if not data:
        return row
    row["branch"] = data["branch"]
    row["venue_name"] = data["branch"]
    if data.get("branch_code"):
        row["branch_code"] = data["branch_code"]
    if data.get("address"):
        row["address"] = data["address"]
        row["venue_address"] = data["address"]
    if data.get("phone") and not clean_text(row.get("phone")):
        row["phone"] = data["phone"]
    if data.get("website_url") and not clean_text(row.get("website_url")):
        row["website_url"] = data["website_url"]
    raw_fields = dict(row.get("raw_fields") or {})
    raw_fields["organ"] = {
        "organ_name": data.get("organ_name"),
        "region": data.get("region"),
        "address_source": "/organ/organList.do",
    }
    row["raw_fields"] = raw_fields
    return row


def cnall_list_url(base_url: str, page: int) -> str:
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    query.update(
        {
            "organAllYn": ["Y"],
            "organAllChk": ["Y"],
            "currentPageNo": [str(page)],
            "recordCountPerPage": [query.get("recordCountPerPage", ["20"])[0] or "20"],
        }
    )
    return parsed._replace(path="/lecture/lectureList.do", query=urlencode(query, doseq=True)).geturl()


def cnall_detail_url(base_url: str, lecture_idx: str) -> str:
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    query.update({"lectureIdx": [lecture_idx], "organAllYn": ["Y"], "organAllChk": ["Y"]})
    return parsed._replace(path="/lecture/lectureDetail.do", query=urlencode(query, doseq=True)).geturl()


def cnall_pairs_from_detail(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for table in soup.select("table.board-view"):
        for tr in table.select("tr"):
            th = tr.find("th")
            td = tr.find("td")
            key = clean_text(th.get_text(" ", strip=True) if th else "")
            value = clean_text(td.get_text(" ", strip=True) if td else "")
            if key and value:
                pairs[key] = value
    return pairs


def cnall_extract_homepage(soup: BeautifulSoup) -> str:
    for table in soup.select("table.board-view"):
        for link in table.select("a[href]"):
            text = clean_text(link.get_text(" ", strip=True))
            href = clean_text(link.get("href"))
            if text == "홈페이지" and href:
                return href
    return ""


def cnall_extract_phone(value: Any) -> str:
    text = clean_text(value)
    match = re.search(r"(?:대표전화|전화번호)\s*:\s*([0-9)(내선\s\-]+)", text)
    return clean_text(match.group(1)) if match else ""


def cnall_split_period_schedule(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    parts = [clean_text(part) for part in re.split(r"\s*/\s*", text) if clean_text(part)]
    period = parts[0] if parts else text
    schedule = clean_text(" ".join(parts[1:]))
    return period, schedule


def cnall_extract_description(soup: BeautifulSoup) -> str:
    node = soup.select_one("td.content")
    if not node:
        return ""
    return clean_text(node.get_text(" ", strip=True))[:4000]


def cnall_extract_image_url(raw_url: str, soup: BeautifulSoup) -> str:
    node = soup.select_one("td.content img[src]")
    src = clean_text(node.get("src") if node else "")
    if not src or "ico_down" in src:
        return ""
    return urljoin(raw_url, src)


def cnall_detail_data(s: requests.Session, raw_url: str, timeout: int) -> dict[str, Any]:
    try:
        soup = fetch_soup(s, raw_url, timeout=timeout)
    except RequestException as exc:
        logger.debug("CNALL detail fetch failed %s: %s", raw_url, exc)
        return {}

    pairs = cnall_pairs_from_detail(soup)
    period, schedule = cnall_split_period_schedule(pairs.get("강좌기간"))
    branch = cnall_normalize_branch(clean_text(str(pairs.get("기관정보") or "").split("|", 1)[0]))
    phone = cnall_extract_phone(pairs.get("기관정보")) or cnall_extract_phone(pairs.get("담당부서"))
    capacity_text = clean_text(pairs.get("신청/대기"))
    capacity_current, capacity_total = parse_capacity_pair(capacity_text)
    wait_current, wait_total = parse_capacity_pair(cnall_text_after_label(capacity_text, "대기신청자"))
    description = cnall_extract_description(soup)
    status_raw = clean_text(" ".join(part for part in (pairs.get("접수기간"), capacity_text) if part))
    return {
        "branch": branch,
        "venue_name": branch,
        "phone": phone,
        "website_url": cnall_extract_homepage(soup),
        "period": period,
        "schedule_raw": schedule,
        "apply_period": clean_text(pairs.get("접수일시") or pairs.get("접수기간")),
        "target": cnall_clean_target(pairs.get("대상")),
        "fee": clean_text(pairs.get("수강료")) or "무료",
        "description": description,
        "image_url": cnall_extract_image_url(raw_url, soup),
        "capacity": capacity_total,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_total": wait_total or wait_current,
        "status": status_raw,
        "application_url": raw_url,
        "raw_fields": {"detail_pairs": pairs, "parser": "cnall_lecture_detail"},
    }


def cnall_text_after_label(value: str, label: str) -> str:
    text = clean_text(value)
    return clean_text(text.split(label, 1)[1].lstrip(":")) if label in text else ""


def parse_cnall_list_item(target: CrawlTarget, page_url: str, item: BeautifulSoup) -> dict[str, Any] | None:
    title_link = item.select_one(".title a")
    title = clean_text(title_link.get_text(" ", strip=True) if title_link else "")
    onclick = clean_text(title_link.get("href") if title_link else "")
    match = re.search(r"fnDetail\('([^']+)'\)", onclick)
    lecture_idx = match.group(1) if match else ""
    if not title or not lecture_idx:
        return None

    raw_url = cnall_detail_url(page_url, lecture_idx)
    icons = [clean_text(icon.get_text(" ", strip=True)) for icon in item.select(".title i")]
    area = clean_text((item.select_one(".title i.etc") or {}).get_text(" ", strip=True) if item.select_one(".title i.etc") else "")
    target_values = [clean_text(icon.get_text(" ", strip=True)) for icon in item.select(".title i.target") if clean_text(icon.get_text(" ", strip=True))]
    fee_icon = item.select_one(".title i.nCharge, .title i.charge")
    fee = clean_text(fee_icon.get_text(" ", strip=True) if fee_icon else "")

    info_blocks = item.select(".info")
    first_spans = [clean_text(span.get_text(" ", strip=True)) for span in info_blocks[0].select("span")] if info_blocks else []
    second_spans = [clean_text(span.get_text(" ", strip=True)) for span in info_blocks[1].select("span")] if len(info_blocks) > 1 else []
    branch = ""
    period = ""
    schedule_parts: list[str] = []
    for span in first_spans:
        if "기관" in span and ":" in span:
            branch = cnall_normalize_branch(cnall_text_after_label(span, "기관"))
        elif "강좌기간" in span:
            period = cnall_text_after_label(span, "강좌기간")
        else:
            schedule_parts.append(span)
    apply_period = ""
    capacity_text = ""
    wait_text = ""
    for span in second_spans:
        if "접수기간" in span:
            apply_period = cnall_text_after_label(span, "접수기간")
        elif "온라인신청자" in span or "모집인원" in span:
            capacity_text = span
        elif "대기신청자" in span:
            wait_text = span
        elif "수강료" in span and not fee:
            fee = cnall_text_after_label(span, "수강료")
    capacity_current, capacity_total = parse_capacity_pair(capacity_text)
    wait_current, wait_total = parse_capacity_pair(wait_text)
    status = clean_text((item.select_one(".info_r") or {}).get_text(" ", strip=True) if item.select_one(".info_r") else "")
    return {
        "provider": target.provider,
        "provider_course_id": lecture_idx,
        "title": title,
        "branch": branch or target.branch,
        "category": " / ".join(icon for icon in icons if icon and icon not in {fee, *target_values}),
        "collection_category": target.extra.get("collection_category") or "도서관",
        "domain_category": target.extra.get("domain_category") or "도서관",
        "source_group": target.extra.get("source_group") or "library",
        "operator_type": target.extra.get("operator_type") or "교육청 도서관",
        "collection_type": "static_html",
        "raw_url": raw_url,
        "application_url": raw_url,
        "status": status,
        "fee": fee or "무료",
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": clean_text(" ".join(schedule_parts)),
        "target": cnall_clean_target(" 쨌 ".join(dict.fromkeys(target_values))),
        "capacity": capacity_total,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_total": wait_total or wait_current,
        "venue_name": branch or target.branch,
        "raw_fields": {"area": area, "capacity_text": capacity_text, "wait_text": wait_text, "parser": "cnall_lecture_list"},
    }


def collect_cnall_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    pagination_exhausted = False
    max_page_seen = 0
    organ_map = cnall_fetch_organ_map(s, target.url, timeout)

    for page in range(1, max(1, max_pages) + 1):
        page_url = cnall_list_url(target.url, page)
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select(".paging"))
        for link in soup.select(".paging a[onclick]"):
            match = re.search(r"fnList\((\d+)\)", clean_text(link.get("onclick")))
            if match:
                max_page_seen = max(max_page_seen, int(match.group(1)))
        for item in soup.select(".lecture-list > li"):
            row = parse_cnall_list_item(target, page_url, item)
            if not row:
                continue
            if detail_pages < max(0, detail_limit):
                detail = cnall_detail_data(s, row["raw_url"], timeout)
                if detail:
                    raw_fields = dict(row.get("raw_fields") or {})
                    raw_fields["detail"] = detail.get("raw_fields")
                    row.update({key: value for key, value in detail.items() if key != "raw_fields" and value not in (None, "")})
                    row["raw_fields"] = raw_fields
                detail_pages += 1
            row = cnall_apply_organ_data(row, organ_map)
            row["provider_course_id"] = clean_text(row.get("provider_course_id")) or stable_course_id(
                target.provider, row.get("raw_url"), row.get("title"), row.get("branch")
            )
            rows.append(row)
            page_rows += 1
        if page_rows == 0:
            pagination_exhausted = True
            break
        if max_page_seen and page >= max_page_seen and page >= 10:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected or max_page_seen > 1,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "declared_last_page": max_page_seen,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "cnall_lecture_cards+detail", meta


