def namwon_api_session() -> requests.Session:
    s = session()
    s.headers.update(
        {
            "Accept": "application/json, text/javascript, */*; q=0.01",
            "X-Requested-With": "XMLHttpRequest",
            "Referer": "https://www.namwon.go.kr/reserve/",
        }
    )
    return s


def namwon_status(value: Any, item: dict[str, Any]) -> str:
    status = clean_text(value)
    label_map = {
        "SCHEDULED": "진행예정",
        "PROCEEDING": "접수중",
        "DEADLINE": "접수마감",
        "DAYOFF": "예약불가",
    }
    label = label_map.get(status, status)
    try:
        max_capacity = int(item.get("maxCapacity") or 0)
        applied = int(item.get("applyCount") or 0) + int(item.get("waitCount") or 0)
    except (TypeError, ValueError):
        max_capacity = 0
        applied = 0
    if max_capacity > 0 and applied >= max_capacity:
        return "접수마감"
    if label:
        return label
    for tag in item.get("tags") or []:
        group_id = clean_text((tag.get("tagGroup") or {}).get("groupId"))
        if group_id == "OP_STATUS":
            return clean_text(tag.get("tagName"))
    return "예약가능"


def namwon_fee(item: dict[str, Any]) -> str:
    item_fee = item.get("itemFee") if isinstance(item.get("itemFee"), dict) else {}
    fee_values = [
        item.get("baseFee"),
        item_fee.get("weekdayFee"),
        item_fee.get("weekendFee"),
        item_fee.get("fee"),
    ]
    amounts = []
    for value in fee_values:
        try:
            if value is not None:
                amounts.append(int(value))
        except (TypeError, ValueError):
            continue
    if not amounts:
        return "무료"
    positive = [amount for amount in amounts if amount > 0]
    if not positive:
        return "무료"
    unique = sorted(set(positive))
    if len(unique) == 1:
        return f"{unique[0]:,}원"
    return " / ".join(f"{amount:,}원" for amount in unique)


def namwon_tags(item: dict[str, Any], excluded_groups: set[str] | None = None) -> list[str]:
    excluded = excluded_groups or set()
    tags = []
    for tag in item.get("tags") or []:
        group_id = clean_text((tag.get("tagGroup") or {}).get("groupId"))
        name = clean_text(tag.get("tagName"))
        if name and group_id not in excluded:
            tags.append(name)
    return list(dict.fromkeys(tags))


def namwon_normalize_place_name(value: Any) -> str:
    text = clean_text(value)
    text = re.sub(r"\s*,\s*$", "", text)
    text = text.replace("남원시립김병종미술관관", "남원시립김병종미술관")
    text = text.replace("춘향문화예술원", "춘향문화예술회관")
    text = re.sub(r"\s+", " ", text).strip()
    return text


def namwon_complete_address(address_hint: str) -> str:
    address = clean_text(address_hint)
    if not address:
        return ""
    if re.search(r"^(전북|전라북도|전북특별자치도|남원시)", address):
        return address
    return f"{NAMWON_DEFAULT_REGION} {address}"


def namwon_address_for_branch(branch: str, facility_code: str = "", detail_addr: str = "") -> str:
    code_address = {
        "LIFELONG": NAMWON_FACILITY_ADDRESS_HINTS["평생학습관"],
        "NKAM": NAMWON_FACILITY_ADDRESS_HINTS["남원시립김병종미술관"],
        "HONBUL_MUSEUM": NAMWON_FACILITY_ADDRESS_HINTS["혼불문학관"],
        "ECOCUBE": NAMWON_FACILITY_ADDRESS_HINTS["백두대간생태교육장"],
        "WORKATION": NAMWON_FACILITY_ADDRESS_HINTS["백두대간생태교육장"],
        "TRANS_PARK": NAMWON_FACILITY_ADDRESS_HINTS["어린이교통공원"],
        "ECO": NAMWON_FACILITY_ADDRESS_HINTS["백두대간생태교육장"],
        "ECOCAMP": NAMWON_FACILITY_ADDRESS_HINTS["백두대간생태교육장"],
        "TREE": NAMWON_FACILITY_ADDRESS_HINTS["백두대간생태교육장"],
        "TREECAMP": NAMWON_FACILITY_ADDRESS_HINTS["백두대간생태교육장"],
        "CAMP_FCLT1": NAMWON_FACILITY_ADDRESS_HINTS["교룡공원 국민여가캠핑장"],
        "CAMP_FCLT2": NAMWON_FACILITY_ADDRESS_HINTS["교룡공원 국민여가캠핑장"],
        "CAMP_FCLT3": NAMWON_FACILITY_ADDRESS_HINTS["교룡공원 국민여가캠핑장"],
        "CAMP_FCLT4": NAMWON_FACILITY_ADDRESS_HINTS["교룡공원 국민여가캠핑장"],
        "PUBLIC_SPORTS": NAMWON_FACILITY_ADDRESS_HINTS["남원종합스포츠타운"],
        "SUPPORT": NAMWON_FACILITY_ADDRESS_HINTS["남원시립김병종미술관"],
    }
    if facility_code in code_address:
        return code_address[facility_code]
    candidates = [
        namwon_normalize_place_name(branch),
        namwon_normalize_place_name(detail_addr),
        namwon_normalize_place_name(branch).replace(" ", ""),
        namwon_normalize_place_name(detail_addr).replace(" ", ""),
    ]
    compact_map = {key.replace(" ", ""): value for key, value in NAMWON_FACILITY_ADDRESS_HINTS.items()}
    for candidate in candidates:
        if candidate in NAMWON_FACILITY_ADDRESS_HINTS:
            return NAMWON_FACILITY_ADDRESS_HINTS[candidate]
        if candidate in compact_map:
            return compact_map[candidate]
    return ""


def namwon_split_venue(value: Any) -> tuple[str, str]:
    text = namwon_normalize_place_name(value)
    if not text:
        return "", ""
    match = re.match(r"(.+?)\(([^)]{2,80})\)\s*$", text)
    if match:
        name = namwon_normalize_place_name(match.group(1))
        address_hint = clean_text(match.group(2))
        if re.search(r"(대로|번길|로|길|면)\s*\d", address_hint):
            return name, namwon_complete_address(address_hint)
        road_match = NAMWON_ROAD_ADDRESS_PATTERN.match(name)
        if road_match:
            road_name = namwon_normalize_place_name(road_match.group("name"))
            road_address = clean_text(road_match.group("addr"))
            if re.search(r"\d+\s*층", address_hint):
                road_address = f"{road_address}, {address_hint}"
            return road_name, namwon_complete_address(road_address)
        return text, ""
    match = NAMWON_ROAD_ADDRESS_PATTERN.match(text)
    if match:
        name = namwon_normalize_place_name(match.group("name"))
        address_hint = clean_text(match.group("addr")).replace("(", ", ").replace(")", "")
        return name, namwon_complete_address(address_hint)
    return text, ""


def namwon_branch_and_address(item: dict[str, Any], config: dict[str, str], target: CrawlTarget) -> tuple[str, str]:
    facility = item.get("facilityInfo") if isinstance(item.get("facilityInfo"), dict) else {}
    facility_name = namwon_normalize_place_name(facility.get("fcltName"))
    facility_code = clean_text(facility.get("fcltCode"))
    rsvt_type = clean_text(item.get("rsvtType") or facility.get("rsvtType") or config.get("rsvt_type"))
    item_info3 = namwon_normalize_place_name(item.get("itemInfo3"))
    detail_addr = namwon_normalize_place_name(item.get("itemDetailAddr"))

    venue_name = ""
    venue_address = ""
    if item_info3 and item_info3 not in {"남원시", "전지역"}:
        venue_name, venue_address = namwon_split_venue(item_info3)
    elif detail_addr and not re.fullmatch(r"[A-Z0-9_\\-]{6,}", detail_addr):
        venue_name, venue_address = namwon_split_venue(detail_addr)

    parent_branch = NAMWON_FACILITY_BRANCH_BY_CODE.get(facility_code, "")
    if not parent_branch and facility_name in NAMWON_FACILITY_ADDRESS_HINTS:
        parent_branch = facility_name

    if facility_code == "LIFELONG":
        if venue_address:
            return venue_name, venue_address
        branch = parent_branch or facility_name or clean_text(config.get("label")) or target.branch
        return branch, namwon_address_for_branch(branch, facility_code, detail_addr)

    if facility_code == "FESTIVAL":
        for candidate in (venue_name, detail_addr, item_info3, facility_name):
            normalized = namwon_normalize_place_name(candidate)
            if "청아원" in normalized:
                return "청아원", namwon_address_for_branch("청아원", facility_code, detail_addr)
            if "춘향문화예술회관" in normalized or "춘향문화예술원" in normalized:
                return "춘향문화예술회관", namwon_address_for_branch("춘향문화예술회관", facility_code, detail_addr)

    if rsvt_type == "LODGMENT" and parent_branch:
        return parent_branch, namwon_address_for_branch(parent_branch, facility_code, detail_addr)
    if rsvt_type in {"EXPERIENCE", "RENTAL", "SUPPORT"} and parent_branch:
        return parent_branch, namwon_address_for_branch(parent_branch, facility_code, detail_addr)

    if venue_address:
        return venue_name, venue_address
    branch = venue_name or facility_name or parent_branch or clean_text(config.get("label")) or target.branch
    return branch, namwon_address_for_branch(branch, facility_code, detail_addr)


def namwon_course_venue_name(item: dict[str, Any], branch: str) -> str:
    facility = item.get("facilityInfo") if isinstance(item.get("facilityInfo"), dict) else {}
    facility_name = namwon_normalize_place_name(facility.get("fcltName"))
    facility_code = clean_text(facility.get("fcltCode"))
    item_info3 = namwon_normalize_place_name(item.get("itemInfo3"))
    detail_addr = namwon_normalize_place_name(item.get("itemDetailAddr"))
    if item_info3 and item_info3 not in {"남원시", "전지역"}:
        venue_name, _ = namwon_split_venue(item_info3)
        if venue_name and venue_name != branch:
            return venue_name
    if facility_code in {"ECO", "ECOCAMP", "TREE", "TREECAMP", "CAMP_FCLT1", "CAMP_FCLT2", "CAMP_FCLT3", "CAMP_FCLT4"}:
        return facility_name
    if detail_addr and detail_addr != branch and not re.fullmatch(r"[A-Z0-9_\-]{6,}", detail_addr):
        return detail_addr
    return branch


def namwon_detail_url(config: dict[str, str], item_uid: str) -> str:
    return (
        "https://www.namwon.go.kr/reserve/index.do?"
        + urlencode({"menuUid": config["detail_menu_uid"], "itemUid": item_uid, "historyPage": "1", "keyword": ""})
    )


def namwon_extract_detail_info(s: requests.Session, url: str, timeout: int) -> dict[str, str]:
    try:
        soup = fetch_soup(s, url, timeout=timeout)
    except RequestException as exc:
        logger.debug("Namwon detail fetch failed %s: %s", url, exc)
        return {}
    main = soup.select_one("main") or soup
    text = clean_text(main.get_text(" ", strip=True))
    description = ""
    if "상세정보" in text:
        description = clean_text(text.split("상세정보", 1)[1].split("위치정보", 1)[0].split("환불규정", 1)[0])
    address = ""
    match = re.search(r"주소\s*:\s*([^:]{4,120}?)(?:상세주소|환불규정|목록|$)", text)
    if match:
        address = clean_text(match.group(1))
    return {"description": description[:4000], "venue_address": address}


def namwon_row_from_item(
    target: CrawlTarget,
    config: dict[str, str],
    item: dict[str, Any],
    detail: dict[str, str] | None = None,
) -> dict[str, Any]:
    detail = detail or {}
    facility = item.get("facilityInfo") if isinstance(item.get("facilityInfo"), dict) else {}
    item_uid = clean_text(item.get("itemUid"))
    title = clean_text(item.get("itemTitle"))
    branch, venue_address = namwon_branch_and_address(item, config, target)
    course_venue_name = namwon_course_venue_name(item, branch)
    detail_address = clean_text(detail.get("venue_address"))
    if detail_address:
        venue_address = detail_address

    category_tags = namwon_tags(item, excluded_groups={"DAY", "OP_STATUS"})
    day_tags = namwon_tags(item, excluded_groups={"LECTURE_CATEGORY", "SHOWLECTURE", "NKAM", "STUDYEXCURSIONS", "PUBLIC_SPORTS", "OP_STATUS"})
    schedule_raw = clean_text(" ".join(part for part in [", ".join(day_tags), item.get("timeInfo")] if clean_text(part)))
    begin_date = clean_text(item.get("beginDate"))
    end_date = clean_text(item.get("endDate"))
    period = " ~ ".join(part for part in [begin_date, end_date] if part)
    apply_period = " ~ ".join(
        part for part in [clean_text(item.get("applyBeginDate")), clean_text(item.get("applyEndDate"))] if part
    )
    rsvt_type = clean_text(item.get("rsvtType") or facility.get("rsvtType") or config.get("rsvt_type"))
    rsvt_method = clean_text(facility.get("rsvtMthd"))
    op_tags = namwon_tags(item, excluded_groups={"DAY", "LECTURE_CATEGORY", "SHOWLECTURE", "NKAM", "STUDYEXCURSIONS", "PUBLIC_SPORTS"})
    offline = any("추첨" in tag or "전화" in tag for tag in op_tags)
    raw_url = namwon_detail_url(config, item_uid)

    return {
        "provider": target.provider,
        "provider_course_id": item_uid,
        "title": title,
        "branch": branch,
        "preserve_branch": True,
        "category": " / ".join(dict.fromkeys([clean_text(config.get("label")), *category_tags])),
        "collection_category": target.extra.get("collection_category") or "공공예약",
        "domain_category": target.extra.get("domain_category") or "공공예약",
        "source_group": target.extra.get("source_group") or "public_reservation",
        "operator_type": target.extra.get("operator_type") or "지자체/공공기관",
        "collection_type": "api_json",
        "raw_url": raw_url,
        "application_url": raw_url,
        "application_type": "OFFLINE_APPLY" if offline else "ONLINE_RESERVATION",
        "application_method_raw": "추첨예약" if offline else rsvt_method,
        "reservation_available": False if offline else namwon_status(item.get("itemProgress"), item) not in {"접수마감", "예약불가"},
        "discovery_status": "namwon_reserve_api",
        "program_type": "강좌",
        "status": namwon_status(item.get("itemProgress"), item),
        "fee": namwon_fee(item) or "별도 안내",
        "period": period or apply_period or "일정 별도 안내",
        "apply_period": apply_period,
        "schedule_raw": schedule_raw or "시간 별도 안내",
        "target": clean_text(item.get("itemInfo4")) or "전체",
        "eligibility_raw": clean_text(item.get("itemInfo4")),
        "description": clean_text(detail.get("description")) or clean_text(item.get("explanation")) or clean_text(facility.get("explanation")),
        "image_url": urljoin("https://www.namwon.go.kr", clean_text(item.get("imageUrl"))),
        "instructor": "",
        "phone": clean_text(item.get("itemInfo2")),
        "capacity": item.get("maxCapacity"),
        "capacity_total": item.get("maxCapacity"),
        "capacity_current": item.get("applyCount"),
        "waitlist_total": item.get("waitCapacity") or item.get("waitCount"),
        "venue_name": course_venue_name,
        "venue_address": venue_address,
        "address": venue_address,
        "raw_fields": {
            "parser": "namwon_reserve_api",
            "config_label": config.get("label"),
            "rsvt_type": rsvt_type,
            "fclt_uid": clean_text(item.get("fcltUid")),
            "fclt_name": clean_text(facility.get("fcltName")),
            "fclt_code": clean_text(facility.get("fcltCode")),
            "rsvt_method": rsvt_method,
            "item_detail_addr": clean_text(item.get("itemDetailAddr")),
            "tags": [
                {
                    "name": clean_text(tag.get("tagName")),
                    "group": clean_text((tag.get("tagGroup") or {}).get("groupId")),
                }
                for tag in item.get("tags") or []
            ],
        },
    }


def collect_namwon_reserve_api(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = namwon_api_session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    detail_attempts = 0
    pagination_detected = False
    exhausted_configs = 0
    discovered_items = 0
    today = datetime.now().date()
    lodging_begin = today + timedelta(days=1)
    lodging_end = lodging_begin
    target_menu_uid = clean_text(parse_qs(urlparse(target.url).query).get("menuUid", [""])[0])
    configs = [
        config
        for config in NAMWON_LIST_CONFIGS
        if clean_text(config.get("rsvt_type")) in NAMWON_PROGRAM_RESERVATION_TYPES
        and (not target_menu_uid or clean_text(config.get("menu_uid")) == target_menu_uid)
    ]
    excluded_config_count = sum(
        clean_text(config.get("rsvt_type")) not in NAMWON_PROGRAM_RESERVATION_TYPES
        for config in NAMWON_LIST_CONFIGS
    )

    for config in configs:
        for page in range(1, max(1, max_pages) + 1):
            params: dict[str, Any] = {
                "page": page,
                "size": 50,
                "rsvtType": config["rsvt_type"],
                "itemTitle": "",
                "menuUid": config["menu_uid"],
            }
            if config.get("fclt_codes"):
                params["fcltCodes"] = config["fclt_codes"]
            if config.get("inst_uid"):
                params["instUid"] = config["inst_uid"]
            if config["rsvt_type"] == "LODGMENT":
                params["beginDate"] = lodging_begin.isoformat()
                params["endDate"] = lodging_end.isoformat()
                params["beginDateStr"] = lodging_begin.isoformat()
                params["endDateStr"] = (lodging_begin + timedelta(days=1)).isoformat()

            response = s.get(NAMWON_RESERVE_API, params=params, timeout=timeout)
            response.raise_for_status()
            payload = response.json()
            result = payload.get("result") or {}
            items = result.get("content") or []
            pages += 1
            total_pages = int(result.get("totalPages") or 0)
            pagination_detected = pagination_detected or total_pages > 1
            if not items:
                exhausted_configs += 1
                break

            for item in items:
                item_uid = clean_text(item.get("itemUid"))
                title = clean_text(item.get("itemTitle"))
                if not item_uid or not title:
                    continue
                discovered_items += 1
                detail: dict[str, str] = {}
                if detail_limit > 0 and detail_pages < detail_limit:
                    detail_attempts += 1
                    detail = namwon_extract_detail_info(s, namwon_detail_url(config, item_uid), timeout)
                    detail_pages += 1
                rows.append(namwon_row_from_item(target, config, item, detail=detail))

            if total_pages and page >= total_pages:
                exhausted_configs += 1
                break
            if not total_pages and len(items) < 50:
                exhausted_configs += 1
                break

    pagination_complete = exhausted_configs == len(configs)
    details_complete = (
        detail_attempts == discovered_items
        and detail_pages == detail_attempts
    )
    snapshot_complete = pagination_complete and details_complete
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "discovered_links": discovered_items,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_complete,
        "detail_collection_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "target_menu_uid": target_menu_uid,
        "program_reservation_types": sorted(NAMWON_PROGRAM_RESERVATION_TYPES),
        "excluded_non_program_config_count": excluded_config_count,
        "no_current_data": snapshot_complete and not rows,
        "no_current_reason": (
            "official Namwon reservation scope has no current rows"
            if snapshot_complete and not rows
            else ""
        ),
    }
    return dedupe_rows(rows), "namwon_reserve_api", meta


def collect_yeongtong_welfare_api(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": target.url, "Accept": "application/json,text/plain,*/*"})
    endpoint = "https://edu.ytsw.or.kr/api/userprog/1.0/reg/prgList"
    rows: list[dict[str, Any]] = []
    total_count = 0
    pages = 0
    for page in range(1, max_pages + 1):
        params = {
            "PROGRM_NM": "",
            "CL_NO": 0,
            "EDC_TRGET_CD": "0",
            "EDC_TXT": "",
            "LRGE_DIV": 1,
            "PAGE_NO": page,
            "PAGE_SIZE": 20,
        }
        response = s.get(endpoint, params=params, timeout=timeout, verify=True)
        response.raise_for_status()
        payload = response.json()
        items = payload.get("items") or []
        page_info = payload.get("page") or {}
        total_count = int(page_info.get("TOTAL_COUNT") or total_count or len(items))
        if not items:
            break
        pages += 1
        for item in items:
            title = clean_text(item.get("PROGRM_NM"))
            if not title:
                continue
            program_no = clean_text(item.get("PROGRM_NO"))
            raw_url = urljoin(target.url, f"/prog/req/eduDtl.do?PROGRM_NO={program_no}") if program_no else target.url
            days = clean_text("".join(clean_text(item.get(key)) for key in ("MON", "TUES", "WED", "THUR", "FRI", "SAT", "SUN")))
            time_range = " ~ ".join(part for part in [clean_text(item.get("STRT_TIME")), clean_text(item.get("END_TIME"))] if part)
            duration_parts = []
            if item.get("MT_CNT"):
                duration_parts.append(f"{item.get('MT_CNT')}개월")
            if item.get("DD_CNT"):
                duration_parts.append(f"{item.get('DD_CNT')}일")
            period = clean_text(item.get("EDC_STRT_DT"))
            if duration_parts:
                period = clean_text(f"{period} ({' '.join(duration_parts)})")
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": clean_text(item.get("EDC_TRGET_NM")),
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": clean_text(item.get("RCPT_STATUS")),
                    "fee": clean_text(item.get("PRICE")) or clean_text(item.get("AMT")),
                    "period": period,
                    "apply_period": " ~ ".join(part for part in [clean_text(item.get("RCPT_STRT_DT")), clean_text(item.get("RCPT_END_DT"))] if part),
                    "schedule_raw": clean_text(" ".join(part for part in [days, time_range] if part)),
                    "target": clean_text(item.get("EDC_TRGET_NM")),
                    "capacity": f"{clean_text(item.get('HIP_COUNT'))}/{clean_text(item.get('NMPR'))}",
                    "room": clean_text(item.get("PLACE")),
                    "venue_name": clean_text(item.get("PLACE")),
                    "description": clean_text(item.get("PROGRM_NM")),
                    "raw_fields": public_raw_fields(item) | {"parser": "yeongtong_welfare_api"},
                }
            )
        if total_count and page * 20 >= total_count:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": total_count > 20,
        "recursion_depth": 0,
        "total_count": total_count,
    }
    return dedupe_rows(rows), "yeongtong_welfare_api", meta


DAEGU_228_LIBRARY_PROVIDER = "MUNI_LIBRARY_DAEGU_GO_KR_89EAABA5"
DAEGU_228_LIBRARY_BRANCH = "대구2ㆍ28민주운동기념도서관"
DAEGU_228_LIBRARY_BRANCH_CODE = "DAEGU_228_LIBRARY"
DAEGU_228_LIBRARY_ADDRESS = "대구 중구 2.28길 9 (남산동)"
DAEGU_228_LIBRARY_TOKEN_URL = "https://library.daegu.go.kr/token.do"
DAEGU_228_LIBRARY_API_URL = (
    "https://library-ssl.daegu.go.kr/apply/api/v1/cul/apply/h2/courses?"
    "menu_idx=30&prntCd=15"
)
DAEGU_228_LIBRARY_DETAIL_URL = (
    "https://library.daegu.go.kr/228lib/module/course/detail.do?"
    "menu_idx=30&homepage_id=h2&crsUid={course_uid}"
)
DAEGU_228_LIBRARY_STATUS = {
    "0": "OPEN",
    "1": "OPEN",
    "2": "CLOSED",
    "3": "CLOSED",
    "4": "CLOSED",
    "5": "CLOSED",
    "6": "SCHEDULED",
    "9": "CLOSED",
    "10": "CLOSED",
    "11": "OPEN",
    "12": "CLOSED",
}
DAEGU_228_LIBRARY_OPEN_STATUS_CODES = {"0", "1", "11"}


def daegu_228_library_text(value: Any) -> str:
    return clean_text(html.unescape(str(value or "")))


def daegu_228_library_integer(value: Any) -> int:
    match = re.search(r"\d+", daegu_228_library_text(value).replace(",", ""))
    return int(match.group(0)) if match else 0


def daegu_228_library_period(start_value: Any, end_value: Any) -> str:
    start = daegu_228_library_text(start_value)
    end = daegu_228_library_text(end_value)
    if start and end and start != end:
        return f"{start} ~ {end}"
    return start or end


def daegu_228_library_date_time(date_value: Any, time_value: Any) -> str:
    return clean_text(
        " ".join(
            part
            for part in [
                daegu_228_library_text(date_value),
                daegu_228_library_text(time_value),
            ]
            if part
        )
    )


def daegu_228_library_schedule(item: dict[str, Any], period: str) -> str:
    weekday = daegu_228_library_text(item.get("lctrDowDrctInpt"))
    if not weekday:
        weekday_names = {
            "1": "일요일",
            "2": "월요일",
            "3": "화요일",
            "4": "수요일",
            "5": "목요일",
            "6": "금요일",
            "7": "토요일",
        }
        values = item.get("crsDowArr") if isinstance(item.get("crsDowArr"), list) else []
        weekday = ", ".join(weekday_names.get(str(value), "") for value in values)
        weekday = clean_text(weekday.strip(", "))
    start_time = daegu_228_library_text(item.get("crsBgngTm"))
    end_time = daegu_228_library_text(item.get("crsEndTm"))
    time_range = f"{start_time} ~ {end_time}" if start_time and end_time else start_time or end_time
    sessions = daegu_228_library_integer(item.get("crsNmtm"))
    session_text = f"총 {sessions}회" if sessions else ""
    return clean_text(" ".join(part for part in [period, weekday, time_range, session_text] if part))


def daegu_228_library_detail_url(course_uid: Any) -> str:
    normalized = daegu_228_library_text(course_uid)
    if not re.fullmatch(r"[A-Za-z0-9_-]{1,80}", normalized):
        return ""
    return DAEGU_228_LIBRARY_DETAIL_URL.format(course_uid=quote(normalized, safe=""))


def daegu_228_library_public_token(
    s: requests.Session,
    timeout: int,
) -> tuple[str, int]:
    response = s.get(DAEGU_228_LIBRARY_TOKEN_URL, timeout=timeout, verify=True)
    response.raise_for_status()
    payload = response.json()
    if not isinstance(payload, dict):
        raise ValueError("Daegu library token response must be an object")
    token = payload.get("jwt")
    expires_at = payload.get("expiresAt")
    if not isinstance(token, str) or not token.strip():
        raise ValueError("Daegu library token response is missing jwt")
    if not isinstance(expires_at, int) or isinstance(expires_at, bool):
        raise ValueError("Daegu library token response has an invalid expiresAt")
    return token.strip(), expires_at


def daegu_228_library_token_expiring(expires_at: int) -> bool:
    return expires_at <= int(time.time() * 1000) + 3_000


def daegu_228_library_course_items(
    s: requests.Session,
    timeout: int,
) -> list[dict[str, Any]]:
    token, expires_at = daegu_228_library_public_token(s, timeout)
    if daegu_228_library_token_expiring(expires_at):
        token, _expires_at = daegu_228_library_public_token(s, timeout)

    response = s.get(
        DAEGU_228_LIBRARY_API_URL,
        headers={"Authorization": f"Bearer {token}"},
        timeout=timeout,
        verify=True,
    )
    if response.status_code == 401:
        token, _expires_at = daegu_228_library_public_token(s, timeout)
        response = s.get(
            DAEGU_228_LIBRARY_API_URL,
            headers={"Authorization": f"Bearer {token}"},
            timeout=timeout,
            verify=True,
        )
    response.raise_for_status()
    payload = response.json()
    if not isinstance(payload, dict) or payload.get("result") is not True:
        raise ValueError("Daegu library course API returned an unsuccessful response")
    data = payload.get("data")
    if not isinstance(data, dict):
        raise ValueError("Daegu library course API response is missing data")
    course_list = data.get("courseList")
    if course_list is None:
        return []
    if not isinstance(course_list, list) or not all(isinstance(item, dict) for item in course_list):
        raise ValueError("Daegu library course API courseList must be a list of objects")
    return course_list


def daegu_228_library_course_row(
    target: CrawlTarget,
    item: dict[str, Any],
) -> dict[str, Any]:
    course_uid = daegu_228_library_text(item.get("crsUid"))
    raw_url = daegu_228_library_detail_url(course_uid)
    title = daegu_228_library_text(item.get("crsNm"))
    if not raw_url or not title:
        return {}

    period = daegu_228_library_period(item.get("crsBgngYmd"), item.get("crsEndYmd"))
    apply_period = daegu_228_library_period(
        daegu_228_library_date_time(item.get("rcptBgngYmd"), item.get("rcptBgngTm")),
        daegu_228_library_date_time(item.get("rcptEndYmd"), item.get("rcptEndTm")),
    )
    start_date, end_date = parse_date_range(period)
    capacity_total = daegu_228_library_integer(item.get("crsRcrtNope"))
    capacity_current = daegu_228_library_integer(item.get("crsRcrtCnt"))
    waitlist_total = daegu_228_library_integer(item.get("crsRcrtRsrvNope"))
    waitlist_current = daegu_228_library_integer(item.get("crsRsrvCnt"))
    status_code = daegu_228_library_text(item.get("crsStatus"))
    status = DAEGU_228_LIBRARY_STATUS.get(status_code, "CLOSED")
    category = " · ".join(
        dict.fromkeys(
            part
            for part in [
                daegu_228_library_text(item.get("groupNm")),
                daegu_228_library_text(item.get("ctgryNm")),
            ]
            if part
        )
    )
    extra_note = daegu_228_library_text(item.get("crsEtc"))
    description = daegu_228_library_text(item.get("crsExpln"))
    is_free = "무료" in extra_note
    reservation_available = status_code in DAEGU_228_LIBRARY_OPEN_STATUS_CODES

    row = {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:crs:{course_uid}"[:100],
        "title": title,
        "branch": DAEGU_228_LIBRARY_BRANCH,
        "branch_code": DAEGU_228_LIBRARY_BRANCH_CODE,
        "preserve_branch": True,
        "category": category,
        "raw_url": raw_url,
        "application_type": "ONLINE_RESERVATION",
        "application_method_raw": "온라인 수강신청",
        "reservation_available": reservation_available,
        "status": status,
        "fee": "무료" if is_free else "",
        "material_fee": extract_material_fee_amount(extra_note),
        "material_note": extra_note,
        "period": period,
        "start_date": start_date,
        "end_date": end_date,
        "apply_period": apply_period,
        "schedule_raw": daegu_228_library_schedule(item, period),
        "sessions": daegu_228_library_integer(item.get("crsNmtm")),
        "target": daegu_228_library_text(item.get("crsTrgt")),
        "eligibility_raw": daegu_228_library_text(item.get("crsTrgt")),
        "instructor": clean_instructor_name(daegu_228_library_text(item.get("instrNm"))),
        "capacity_total": capacity_total,
        "capacity_current": capacity_current,
        "capacity_remaining": max(capacity_total - capacity_current, 0) if capacity_total else 0,
        "waitlist_total": waitlist_total,
        "waitlist_current": waitlist_current,
        "room": daegu_228_library_text(item.get("crsPlc")),
        "venue_name": DAEGU_228_LIBRARY_BRANCH,
        "address": DAEGU_228_LIBRARY_ADDRESS,
        "venue_address": DAEGU_228_LIBRARY_ADDRESS,
        "phone": daegu_228_library_text(item.get("crsPicTelno") or item.get("managerPhone")),
        "description": description,
        "collection_type": "api_json",
        "program_type": "강좌",
        "discovery_status": "daegu_228_library_course_api",
        "raw_fields": {
            "parser": "daegu_228_library_course_api",
            "course_uid": course_uid,
            "status_code": status_code,
            "course_state_code": daegu_228_library_text(item.get("crsStts")),
            "deleted": daegu_228_library_text(item.get("delYn")),
            "enabled": daegu_228_library_text(item.get("useYn")),
            "homepage_uid": daegu_228_library_text(item.get("hmpgUid")),
            "homepage_name": daegu_228_library_text(item.get("hmpgNm")),
            "category_uid": daegu_228_library_text(item.get("ctgryUid")),
            "group_name": daegu_228_library_text(item.get("groupNm")),
            "course_weekdays": [
                str(value)
                for value in (
                    item.get("crsDowArr")
                    if isinstance(item.get("crsDowArr"), list)
                    else []
                )[:7]
            ],
            "course_times": clean_text(
                " ~ ".join(
                    part
                    for part in [
                        daegu_228_library_text(item.get("crsBgngTm")),
                        daegu_228_library_text(item.get("crsEndTm")),
                    ]
                    if part
                )
            ),
        },
    }
    if reservation_available:
        row["application_url"] = raw_url
    return row


def collect_daegu_228_library_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if max_pages < 1:
        raise ValueError("max_pages must be at least 1")
    s = session()
    items = daegu_228_library_course_items(s, timeout)
    rows: list[dict[str, Any]] = []
    expired_count = 0
    invalid_count = 0
    ended_status_count = 0
    hidden_count = 0
    for item in items:
        if (
            daegu_228_library_text(item.get("delYn")) != "N"
            or daegu_228_library_text(item.get("useYn")) != "Y"
        ):
            hidden_count += 1
            continue
        if daegu_228_library_text(item.get("crsStatus")) == "9":
            ended_status_count += 1
            continue
        row = daegu_228_library_course_row(target, item)
        if not row:
            invalid_count += 1
            continue
        if should_skip_expired_course(row):
            expired_count += 1
            continue
        rows.append(row)

    rows = dedupe_rows(rows)
    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": len(items),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "pagination_complete": True,
        "source_cap_reached": False,
        "recursion_depth": 0,
        "total_count": len(items),
        "expired_count": expired_count,
        "invalid_count": invalid_count,
        "ended_status_count": ended_status_count,
        "hidden_count": hidden_count,
        "no_current_data": not rows,
        "no_current_reason": (
            "all API courses are ended, hidden, or expired"
            if items and not rows and not invalid_count
            else ""
        ),
    }
    return rows, "daegu_228_library_course_api", meta


def collect_daegu_expr_reservation(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": target.url, "Accept": "application/json", "Content-Type": "application/json"})
    endpoint = "https://yeyak.daegu.go.kr/api/v1/res/expr/user/expr-prod-list"
    rows: list[dict[str, Any]] = []
    total_count = 0
    pages = 0
    status_map = {"ING": "접수중", "WAIT": "접수예정", "END": "접수마감", "CLOSE": "접수마감"}

    for page in range(1, max_pages + 1):
        payload = {
            "instId": "",
            "ftrPrgrmDcd": "DSS_0078_02",
            "searchText": "",
            "searchGbn": "",
            "pageIndex": page,
            "pageSize": 32,
        }
        response = s.post(endpoint, json=payload, timeout=timeout, verify=True)
        response.raise_for_status()
        data = (response.json().get("data") or {})
        items = data.get("items") or []
        total_count = int(data.get("totalElements") or total_count or len(items))
        if not items:
            break
        pages += 1
        for item in items:
            title = clean_text(item.get("ftrPrgrmNm"))
            if not title:
                continue
            inst_id = clean_text(item.get("instId"))
            program_id = clean_text(item.get("ftrPrgrmId"))
            raw_url = f"https://yeyak.daegu.go.kr/expr/detail/{inst_id}/{program_id}" if inst_id and program_id else target.url
            fee = "무료" if clean_text(item.get("chrgYn")) == "N" else normalize_site_fee(item.get("ntslAmt"))
            target_text = clean_text(
                item.get("trgtNm")
                or item.get("ftrPrgrmTrgt")
                or item.get("exprTrgt")
                or item.get("useTrgtNm")
                or item.get("ageLmtCn")
                or item.get("ftrPrgrmCn")
            )
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, clean_text(item.get("instNm")) or target.branch),
                    "title": title,
                    "branch": clean_text(item.get("instNm")) or target.branch,
                    "category": clean_text(item.get("ftrPrgrmDcdNm")),
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status_map.get(clean_text(item.get("rcptStatus")), clean_text(item.get("rcptStatus"))),
                    "fee": fee,
                    "period": " ~ ".join(part for part in [clean_text(item.get("prgrmBgngYmd")), clean_text(item.get("prgrmEndYmd"))] if part),
                    "apply_period": " ~ ".join(part for part in [clean_text(item.get("rcptBgngYmd")), clean_text(item.get("rcptEndYmd"))] if part),
                    "schedule_raw": " ~ ".join(part for part in [clean_text(item.get("prgrmBgngYmd")), clean_text(item.get("prgrmEndYmd"))] if part),
                    "target": target_text,
                    "room": clean_text(item.get("plcNm")),
                    "venue_name": clean_text(item.get("plcNm")),
                    "phone": clean_text(item.get("inqryTelNo")),
                    "description": clean_text(item.get("ftrPrgrmNm")),
                    "raw_fields": public_raw_fields(item) | {"parser": "daegu_expr_reservation"},
                }
            )
        if total_count and page * 32 >= total_count:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": total_count > 32,
        "recursion_depth": 0,
        "total_count": total_count,
    }
    return dedupe_rows(rows), "daegu_expr_reservation", meta


def collect_daegu_reservation(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    target = CrawlTarget(
        provider=target.provider,
        name=target.name,
        branch=target.branch,
        url="https://yeyak.daegu.go.kr/expr/list",
        source=target.source,
        priority=target.priority,
        region=target.region,
        extra=target.extra,
    )
    return collect_daegu_expr_reservation(target, timeout=timeout, max_pages=max_pages)


ICHEON_EDU_LIST_URL = "https://www.icheon.go.kr/edu/eduLctr/lecture/list.do?mid=0101000000"
ICHEON_EDU_VIEW_URL = "https://www.icheon.go.kr/edu/eduLctr/lecture/view.do?mid=0101000000"


def icheon_detail_fields(s: requests.Session, idx: str, timeout: int) -> dict[str, Any]:
    if not idx:
        return {}
    response = s.post(ICHEON_EDU_VIEW_URL, data={"idx": idx}, timeout=timeout, verify=True)
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    soup = BeautifulSoup(response.text, "lxml")
    pairs = pairs_from_tables(soup.select_one("#contents") or soup)
    content = clean_text(pairs.get("교육내용") or pairs.get("강좌소개"))
    if not content:
        content_node = soup.select_one(".board_view, .view, #contents")
        content = clean_text(content_node.get_text(" ", strip=True) if content_node else "")
    return {
        "title": clean_text(pairs.get("강좌명")),
        "category": clean_text(pairs.get("교육영역")),
        "period": normalize_mixed_date_range(pairs.get("교육기간", "")),
        "apply_period": normalize_mixed_date_range(pairs.get("접수기간", "")),
        "schedule_raw": clean_text(pairs.get("교육시간")),
        "target": clean_text(pairs.get("교육대상")),
        "venue_name": clean_text(pairs.get("교육장소")),
        "fee": clean_text(pairs.get("수강료")),
        "capacity": clean_text(pairs.get("모집정원")),
        "phone": clean_text(pairs.get("문의처")),
        "instructor": clean_text(pairs.get("강사명")),
        "description": content,
        "raw_detail_pairs": pairs,
    }


def collect_icheon_education_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    pagination_exhausted = False
    seen: set[str] = set()

    for page in range(1, max_pages + 1):
        current_url = f"{ICHEON_EDU_LIST_URL}&page={page}&mode=list"
        soup = fetch_soup(s, current_url, timeout=timeout)
        trs = soup.select("table tbody tr")
        pagination_detected = pagination_detected or bool(soup.select("a[href*='page='], .pagination, .paging"))
        if not trs:
            pagination_exhausted = True
            break
        pages += 1
        page_rows = 0
        for tr in trs:
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.select("td")]
            if len(cells) < 9 or cells[0] == "번호":
                continue
            link = tr.select_one("a[data-req-get-p-idx]")
            idx = clean_text(link.get("data-req-get-p-idx") if link else cells[0])
            title = clean_text(link.get_text(" ", strip=True) if link else cells[1])
            if not title or is_low_value_title(title):
                continue
            raw_url = f"{ICHEON_EDU_VIEW_URL}&idx={idx}" if idx else current_url
            if raw_url in seen:
                continue
            seen.add(raw_url)
            detail: dict[str, Any] = {}
            if idx and detail_pages < max(0, detail_limit):
                try:
                    detail = icheon_detail_fields(s, idx, timeout=timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("Icheon education detail fetch failed %s: %s", idx, exc)
            capacity = clean_text(detail.get("capacity")) or cells[8]
            capacity_current, capacity_total = parse_capacity_pair(capacity)
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": clean_text(detail.get("title")) or title,
                    "branch": target.branch,
                    "category": clean_text(detail.get("category")) or "교육/강좌",
                    "raw_url": raw_url,
                    "application_url": raw_url if "접수" in cells[7] else "",
                    "reservation_available": "접수중" in cells[7],
                    "status": normalize_status(cells[7]) or cells[7],
                    "fee": clean_text(detail.get("fee")) or cells[6],
                    "period": clean_text(detail.get("period")) or normalize_mixed_date_range(cells[3]),
                    "apply_period": clean_text(detail.get("apply_period")) or normalize_mixed_date_range(cells[2]),
                    "schedule_raw": clean_text(detail.get("schedule_raw")) or cells[4],
                    "target": clean_text(detail.get("target")) or "전체",
                    "capacity": capacity,
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "venue_name": clean_text(detail.get("venue_name")) or cells[5],
                    "room": clean_text(detail.get("venue_name")) or cells[5],
                    "phone": clean_text(detail.get("phone")),
                    "instructor": clean_text(detail.get("instructor")),
                    "description": clean_text(detail.get("description")) or clean_text(tr.get_text(" ", strip=True)),
                    "collection_type": "static_html+detail_html",
                    "source_group": "lifelong_learning",
                    "raw_fields": {
                        "parser": "icheon_education_table+detail",
                        "list_cells": cells,
                        "detail_pairs": detail.get("raw_detail_pairs", {}),
                    },
                }
            )
            page_rows += 1
        if page_rows == 0:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen),
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "source_cap_reached": not pagination_exhausted,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "icheon_education_table+detail", meta


