MIRYANG_YEYAK_EDU_API = "https://yeyak.miryang.go.kr/yeyak/json/yeyak/edu/lecture/list_main.do"


def collect_miryang_yeyak_education(
    target: CrawlTarget,
    timeout: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": "https://yeyak.miryang.go.kr/yeyak/main.web", "Accept": "application/json"})
    response = s.get(MIRYANG_YEYAK_EDU_API, timeout=timeout, verify=True)
    response.raise_for_status()
    items = response.json()
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    for item in items:
        title = clean_text(item.get("title"))
        if not title:
            continue
        link = clean_text(item.get("link"))
        lecture_id = clean_text(item.get("lecture_id"))
        fcd = clean_text(item.get("fcd"))
        raw_url = normalize_link(
            "https://yeyak.miryang.go.kr/yeyak/main.web",
            f"/yeyak{link}?amode=view&lectureId={quote(lecture_id)}&fcd={quote(fcd)}" if link and lecture_id else "",
        ) or "https://yeyak.miryang.go.kr/yeyak/main.web"
        detail_pairs: dict[str, str] = {}
        if detail_pages < max(0, detail_limit):
            try:
                detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                detail_pairs = pairs_from_tables(detail_soup.select_one("#contents") or detail_soup)
                detail_pages += 1
            except Exception as exc:
                logger.debug("Miryang yeyak detail fetch failed %s: %s", raw_url, exc)
        period = normalize_mixed_date_range(
            clean_text(detail_pairs.get("교육기간"))
            or f"{clean_text(item.get('edu_sdate'))} ~ {clean_text(item.get('edu_edate'))}"
        )
        apply_period = normalize_mixed_date_range(
            clean_text(detail_pairs.get("접수기간") or detail_pairs.get("접수일시"))
            or f"{clean_text(item.get('rcept_stime'))} ~ {clean_text(item.get('rcept_etime'))}"
        )
        capacity = clean_text(detail_pairs.get("온라인 정원/대기정원")) or clean_text(item.get("nmpr_capa"))
        capacity_current, capacity_total = parse_capacity_pair(capacity)
        if capacity_total is None:
            capacity_total = parse_capacity_number(capacity)
        fee = clean_text(detail_pairs.get("수강료") or item.get("isFreeText")) or "별도 안내"
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, clean_text(item.get("facility_nm")) or target.branch),
                "title": title,
                "branch": target.branch,
                "category": clean_text(detail_pairs.get("교육분류") or item.get("facility_nm") or "교육강좌"),
                "raw_url": raw_url,
                "application_url": raw_url if clean_text(item.get("status")) in {"접수중", "접수대기"} else "",
                "reservation_available": clean_text(item.get("status")) == "접수중",
                "status": normalize_status(item.get("status") or item.get("rcept_pos")) or clean_text(item.get("status") or item.get("rcept_pos")),
                "fee": fee,
                "period": period,
                "apply_period": apply_period,
                "schedule_raw": clean_text(detail_pairs.get("요일시간") or item.get("edu_time")) or "별도 안내",
                "target": clean_text(detail_pairs.get("교육대상") or item.get("target")) or "전체",
                "capacity": capacity,
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "venue_name": clean_text(detail_pairs.get("교육장소") or item.get("place") or target.branch),
                "room": clean_text(detail_pairs.get("교육장소") or item.get("place")),
                "description": clean_text(detail_pairs.get("교육내용") or title),
                "collection_type": "api_json+detail_html",
                "source_group": "public_reservation",
                "raw_fields": public_raw_fields(item) | {"parser": "miryang_yeyak_edu_api+detail", "detail_pairs": detail_pairs},
            }
        )

    meta = {
        "pages": 1 if items else 0,
        "detail_pages": detail_pages,
        "discovered_links": len(items),
        "pagination_detected": False,
        "recursion_depth": 0,
        "total_count": len(items),
    }
    return dedupe_rows(rows), "miryang_yeyak_edu_api+detail", meta


def taean_card_pairs(card: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in card.select("ul.info li"):
        label_node = li.find("b")
        if not label_node:
            continue
        label = clean_text(label_node.get_text(" ", strip=True))
        label_node.extract()
        value = clean_text(li.get_text(" ", strip=True))
        if label:
            pairs[label] = value
    return pairs


def collect_taean_education_cards(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    seen: set[str] = set()
    page_budget = PageBudget(max_pages)

    for list_index, list_url in enumerate(TAEAN_EDU_LIST_URLS):
        parsed = urlparse(list_url)
        base_query = parse_qs(parsed.query)
        remaining_sources = len(TAEAN_EDU_LIST_URLS) - list_index
        remaining_budget = max(0, page_budget.limit - page_budget.used)
        source_page_limit = max(1, remaining_budget // max(remaining_sources, 1))
        for page in range(1, min(max_pages, source_page_limit) + 1):
            if not page_budget.claim():
                break
            query = dict(base_query)
            query["pageIndex"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
            soup = fetch_soup(s, current_url, timeout=timeout)
            cards = soup.select("div.list")
            pagination_detected = pagination_detected or bool(soup.select("a[href*='pageIndex='], .pagination, .paging"))
            if not cards:
                break
            pages += 1
            page_rows = 0
            for card in cards:
                title_link = card.select_one(".tit a[href]")
                title = clean_text(title_link.get_text(" ", strip=True) if title_link else "")
                if not title or is_low_value_title(title):
                    continue
                raw_url = normalize_link(current_url, title_link.get("href") if title_link else None) or current_url
                if raw_url in seen:
                    continue
                seen.add(raw_url)
                category = clean_text((card.select_one(".tit .cate") or "").get_text(" ", strip=True) if card.select_one(".tit .cate") else "")
                pairs = taean_card_pairs(card)
                status = clean_text((card.select_one(".state_btn b") or "").get_text(" ", strip=True) if card.select_one(".state_btn b") else "")
                detail_pairs: dict[str, str] = {}
                if raw_url and detail_pages < max(0, detail_limit):
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pairs = pairs_from_tables(detail_soup.select_one("#contents") or detail_soup)
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("Taean education detail fetch failed %s: %s", raw_url, exc)
                capacity = clean_text(detail_pairs.get("정원") or pairs.get("신청/정원"))
                capacity_current, capacity_total = parse_capacity_pair(capacity)
                if capacity_total is None:
                    capacity_total = parse_capacity_number(capacity)
                fee = clean_text(detail_pairs.get("수강료") or pairs.get("수강료"))
                if fee == "0":
                    fee = "무료"
                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, raw_url, title, clean_text(pairs.get("교육기관")) or target.branch),
                        "title": clean_text(detail_pairs.get("강좌명")) or title,
                        "branch": target.branch,
                        "category": category or "교육",
                        "raw_url": raw_url,
                        "application_url": raw_url if "접수가능" in status else "",
                        "reservation_available": "접수가능" in status,
                        "status": normalize_status(status) or status,
                        "fee": fee or "별도 안내",
                        "period": normalize_mixed_date_range(detail_pairs.get("교육기간") or pairs.get("교육기간", "")),
                        "apply_period": normalize_mixed_date_range(detail_pairs.get("접수기간") or pairs.get("접수기간", "")),
                        "schedule_raw": clean_text(detail_pairs.get("교육시간") or pairs.get("교육시간")) or "별도 안내",
                        "target": clean_text(detail_pairs.get("교육대상")) or "전체",
                        "capacity": capacity,
                        "capacity_current": capacity_current,
                        "capacity_total": capacity_total,
                        "venue_name": clean_text(detail_pairs.get("교육장소") or pairs.get("교육기관") or target.branch),
                        "room": clean_text(detail_pairs.get("교육장소")),
                        "instructor": clean_text(detail_pairs.get("강사명")),
                        "phone": clean_text(detail_pairs.get("문의전화")),
                        "description": clean_text(detail_pairs.get("교육내용") or card.get_text(" ", strip=True)),
                        "collection_type": "static_html+detail_html",
                        "source_group": "lifelong_learning",
                        "raw_fields": {
                            "parser": "taean_education_cards+detail",
                            "list_url": current_url,
                            "list_pairs": pairs,
                            "detail_pairs": detail_pairs,
                        },
                    }
                )
                page_rows += 1
            if page_rows == 0:
                break
        if page_budget.exhausted:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "taean_education_cards+detail", meta


def mmca_money(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return "무료"
    digits = re.sub(r"[^\d]", "", text)
    if digits and int(digits) == 0:
        return "무료"
    if digits and "원" not in text:
        return f"{int(digits):,}원"
    return text


def mmca_json_post(s: requests.Session, endpoint: str, data: dict[str, Any], timeout: int) -> dict[str, Any]:
    response = s.post(endpoint, data=data, timeout=timeout, verify=True)
    response.raise_for_status()
    return response.json()


def mmca_expired(period: str) -> bool:
    _, end_date = parse_date_range(period)
    return bool(end_date and end_date < datetime.now().astimezone().date())


def mmca_schedule_quality(value: Any, period: Any) -> tuple[int, int]:
    text = clean_text(value)
    if not text:
        return (0, 0)
    has_clock_time = bool(re.search(r"(?<!\d)\d{1,2}:\d{2}", text))
    differs_from_period = text != clean_text(period)
    return (int(has_clock_time) * 2 + int(differs_from_period), len(text))


def mmca_period_quality(value: Any) -> tuple[int, int]:
    text = clean_text(value)
    if not text:
        return (0, 0)
    start_date, end_date = parse_date_range(text)
    normalized_dates = len(re.findall(r"\d{4}-\d{2}-\d{2}", text))
    return (int(start_date is not None) + int(end_date is not None) + normalized_dates, len(text))


def coalesce_mmca_program_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Merge MMCA sections that publish the same official education identity."""

    merged: dict[str, dict[str, Any]] = {}
    for source_row in rows:
        raw_url = clean_text(source_row.get("raw_url"))
        key = raw_url or clean_text(source_row.get("provider_course_id"))
        existing = merged.get(key)
        if existing is None:
            row = dict(source_row)
            row["raw_fields"] = dict(source_row.get("raw_fields") or {})
            row["raw_fields"]["merged_source_rows"] = 1
            merged[key] = row
            continue

        existing_raw = existing.setdefault("raw_fields", {})
        incoming_raw = dict(source_row.get("raw_fields") or {})
        existing_raw["merged_source_rows"] = int(existing_raw.get("merged_source_rows") or 1) + 1
        sections = {
            clean_text(existing_raw.get("child_section")),
            clean_text(incoming_raw.get("child_section")),
            clean_text(existing.get("collection_type")),
            clean_text(source_row.get("collection_type")),
        }
        existing_raw["merged_sections"] = sorted(value for value in sections if value)

        for field in (
            "application_url",
            "capacity",
            "capacity_current",
            "capacity_total",
            "image_url",
            "room",
            "target",
        ):
            if not clean_text(existing.get(field)) and clean_text(source_row.get(field)):
                existing[field] = source_row[field]

        for field in ("branch", "venue_name", "description"):
            if len(clean_text(source_row.get(field))) > len(clean_text(existing.get(field))):
                existing[field] = source_row[field]

        if mmca_schedule_quality(
            source_row.get("schedule_raw"),
            source_row.get("period"),
        ) > mmca_schedule_quality(existing.get("schedule_raw"), existing.get("period")):
            existing["schedule_raw"] = source_row.get("schedule_raw")

        if mmca_period_quality(source_row.get("period")) > mmca_period_quality(existing.get("period")):
            existing["period"] = source_row.get("period")

        incoming_status = clean_text(source_row.get("status"))
        if incoming_status and clean_text(existing.get("status")) in {"", "\uac8c\uc2dc"}:
            existing["status"] = source_row.get("status")
        existing["reservation_available"] = bool(
            existing.get("reservation_available") or source_row.get("reservation_available")
        )
        existing["provider_course_id"] = stable_course_id(
            clean_text(existing.get("provider")),
            raw_url,
            clean_text(existing.get("title")),
            clean_text(existing.get("branch")),
        )

    return list(merged.values())


def collect_mmca_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 100,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": target.url, "Accept": "application/json", "X-Requested-With": "XMLHttpRequest"})
    rows: list[dict[str, Any]] = []
    pages = 0
    total_counts: dict[str, int] = {}
    page_budget = PageBudget(max_pages)
    section_page_limit = max_pages
    child_detail_pages = 0

    for child_code, child_label in (("01", "어린이 교육"), ("05", "과천 어린이미술관")):
        for page in range(1, section_page_limit + 1):
            if not page_budget.claim():
                break
            payload = mmca_json_post(
                s,
                "https://www.mmca.go.kr/educations/ajaxEduChildList.do",
                {
                    "pageIndex": str(page),
                    "eduBigCd": child_code,
                    "searchText": "",
                    "searchFrom": "",
                    "searchTo": "",
                    "searchBigType": "",
                    "searchSmlType": "",
                    "searchPlaCd": "",
                    "eduOrderType": "",
                },
                timeout,
            )
            items = payload.get("eduList") or []
            count_key = "children" if child_code == "01" else "gwacheon_children_museum"
            total_counts[count_key] = int((payload.get("paginationInfo") or {}).get("totalRecordCount") or len(items))
            if not items:
                break
            pages += 1
            for item in items:
                title = clean_text(item.get("eduTitle"))
                if not title:
                    continue
                edu_id = clean_text(item.get("eduId"))
                raw_url = f"https://www.mmca.go.kr/educations/educationsDetail.do?eduId={edu_id}" if edu_id else target.url
                period = normalize_mixed_date_range(
                    f"{clean_text(item.get('eduStDt'))} ~ {clean_text(item.get('eduEdDt'))}"
                )
                if mmca_expired(period):
                    continue
                description = ""
                schedule = ""
                if edu_id and child_detail_pages < max(0, detail_limit):
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        child_detail_pages += 1
                        detail = detail_soup.select_one(".detailCont")
                        description = clean_text(detail.get_text(" ", strip=True) if detail else "")[:2000]
                        pairs = pairs_from_definition_lists(detail_soup)
                        pairs.update(pairs_from_tables(detail_soup))
                        schedule = first_by_keys(pairs, ("교육시간", "시간", "일시"))
                    except Exception as exc:
                        logger.debug("MMCA child education detail fetch failed %s: %s", raw_url, exc)
                venue_name = clean_text(
                    " ".join(part for part in [item.get("eduPlaNm"), item.get("eduPlaDtl")] if clean_text(part))
                )
                branch = (
                    "과천 어린이미술관"
                    if child_code == "05"
                    else clean_text(item.get("eduPlaNm")) or target.branch
                )
                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                        "title": title,
                        "branch": branch,
                        "category": child_label,
                        "program_type": "어린이 교육",
                        "raw_url": raw_url,
                        "application_url": raw_url,
                        "reservation_available": True,
                        "status": "게시",
                        "fee": mmca_money(item.get("eduPrice")),
                        "period": period,
                        "schedule_raw": schedule or period,
                        "target": clean_text(item.get("eduTarget")) or "어린이",
                        "room": clean_text(item.get("eduPlaDtl")),
                        "venue_name": venue_name,
                        "description": description or clean_text(
                            " | ".join(
                                part
                                for part in (
                                    child_label,
                                    clean_text(item.get("eduTarget")),
                                    venue_name,
                                    period,
                                )
                                if part
                            )
                        ),
                        "image_url": normalize_link(target.url, item.get("eduThumbImg")),
                        "collection_type": "api_json+detail_html",
                        "source_group": "museum_science",
                        "raw_fields": public_raw_fields(item)
                        | {
                            "parser": "mmca_exhibition_education_event_api",
                            "child_section": child_label,
                        },
                    }
                )
            if total_counts[count_key] and page * 8 >= total_counts[count_key]:
                break

    for page in range(1, section_page_limit + 1):
        if not page_budget.claim():
            break
        payload = mmca_json_post(
            s,
            "https://www.mmca.go.kr/exhibitions/AjaxExhibitionList.do",
            {"exhFlag": "1", "searchExhPlaCd": "", "searchExhCd": "", "sort": "1", "pageIndex": str(page)},
            timeout,
        )
        items = payload.get("exhibitionsList") or []
        total_counts["exhibitions"] = int((payload.get("paginationInfo") or {}).get("totalRecordCount") or len(items))
        if not items:
            break
        pages += 1
        for item in items:
            title = clean_text(item.get("exhTitle"))
            if not title:
                continue
            raw_url = f"https://www.mmca.go.kr/exhibitions/exhibitionsDetail.do?exhFlag=1&exhId={clean_text(item.get('exhId'))}"
            venue = clean_text(" ".join(part for part in [item.get("exhPlaNm"), item.get("exhPlaDtl")] if clean_text(part)))
            period = normalize_mixed_date_range(f"{clean_text(item.get('exhStDt'))} ~ {clean_text(item.get('exhEdDt'))}")
            if mmca_expired(period):
                continue
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, venue),
                    "title": title,
                    "branch": clean_text(item.get("exhPlaNm")) or target.branch,
                    "category": clean_text(item.get("exhCd") or item.get("exhTpCd") or "전시"),
                    "program_type": "전시",
                    "raw_url": raw_url,
                    "application_url": clean_text(item.get("bookingUrl")),
                    "reservation_available": bool(clean_text(item.get("bookingUrl"))),
                    "status": clean_text(item.get("exhTimeStatus")) or "현재전시",
                    "fee": mmca_money(item.get("exhAdm")),
                    "period": period,
                    "schedule_raw": clean_text(item.get("exhTime") or item.get("exhTimeStatus") or "전시 운영시간"),
                    "target": "전체",
                    "venue_name": venue,
                    "description": html_to_text(item.get("exhContentsSumm") or item.get("exhContents") or title),
                    "image_url": normalize_link(target.url, item.get("exhThumbImg") or item.get("exhDidImg")),
                    "collection_type": "api_json",
                    "source_group": "museum_science",
                    "raw_fields": public_raw_fields(item) | {"parser": "mmca_exhibition_education_event_api"},
                }
            )
        if total_counts["exhibitions"] and page * 8 >= total_counts["exhibitions"]:
            break

    for page in range(1, section_page_limit + 1):
        if not page_budget.claim():
            break
        payload = mmca_json_post(
            s,
            "https://www.mmca.go.kr/educations/ajaxEduParticipation.do",
            {"pageIndex": str(page), "searchEduPlaCd": "", "searchText": "", "eduTp": "06"},
            timeout,
        )
        items = payload.get("eduList") or []
        total_counts["education"] = int((payload.get("paginationInfo") or {}).get("totalRecordCount") or len(items))
        if not items:
            break
        pages += 1
        for item in items:
            title = clean_text(item.get("eduTitle"))
            if not title:
                continue
            edu_id = clean_text(item.get("eduId"))
            raw_url = f"https://www.mmca.go.kr/educations/educationsDetail.do?eduId={edu_id}" if edu_id else target.url
            venue = clean_text(" ".join(part for part in [item.get("eduPlaNm"), item.get("eduPlaDtl")] if clean_text(part)))
            period = normalize_mixed_date_range(item.get("eduTerm") or f"{clean_text(item.get('eduStDt'))} ~ {clean_text(item.get('eduEdDt'))}")
            if mmca_expired(period):
                continue
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, venue),
                    "title": title,
                    "branch": clean_text(item.get("eduPlaNm")) or target.branch,
                    "category": clean_text(item.get("eduBigNm") or "교육"),
                    "program_type": "교육",
                    "raw_url": raw_url,
                    "application_url": raw_url if clean_text(item.get("eduTicketYn")) == "Y" else "",
                    "reservation_available": clean_text(item.get("eduTicketYn")) == "Y",
                    "status": clean_text(item.get("stat") or item.get("stat2")),
                    "fee": mmca_money(item.get("eduPrice")),
                    "period": period,
                    "schedule_raw": clean_text(item.get("eduTm") or item.get("eduTerm")),
                    "target": clean_text(item.get("eduTarget")) or "전체",
                    "capacity": clean_text(item.get("eduPersonCnt")),
                    "venue_name": venue,
                    "description": html_to_text(item.get("eduContents") or title),
                    "image_url": normalize_link(target.url, item.get("eduThumbImg")),
                    "collection_type": "api_json",
                    "source_group": "museum_science",
                    "raw_fields": public_raw_fields(item) | {"parser": "mmca_exhibition_education_event_api"},
                }
            )
        if total_counts["education"] and page * 8 >= total_counts["education"]:
            break

    for page in range(1, section_page_limit + 1):
        if not page_budget.claim():
            break
        payload = mmca_json_post(
            s,
            "https://www.mmca.go.kr/events/AjaxEventsList.do",
            {"searchEduPlaCd": "", "sort": "1", "pageIndex": str(page), "eduLangCd": "01"},
            timeout,
        )
        items = payload.get("eventsList") or []
        total_counts["events"] = int((payload.get("paginationInfo") or {}).get("totalRecordCount") or len(items))
        if not items:
            break
        pages += 1
        for item in items:
            title = clean_text(item.get("eduTitle"))
            if not title:
                continue
            edu_id = clean_text(item.get("eduId"))
            raw_url = f"https://www.mmca.go.kr/events/eventsDetail.do?eduId={edu_id}" if edu_id else target.url
            venue = clean_text(" ".join(part for part in [item.get("eduPlaNmKor") or item.get("eduPlaNm"), item.get("eduPlaDtl")] if clean_text(part)))
            period = normalize_mixed_date_range(f"{clean_text(item.get('eduStDt'))} ~ {clean_text(item.get('eduEdDt'))}")
            if mmca_expired(period):
                continue
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, venue),
                    "title": title,
                    "branch": clean_text(item.get("eduPlaNmKor") or item.get("eduPlaNm")) or target.branch,
                    "category": "이벤트",
                    "program_type": "행사",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": "게시",
                    "fee": mmca_money(item.get("eduPrice")),
                    "period": period,
                    "schedule_raw": clean_text(item.get("eduTm") or f"{clean_text(item.get('eduStDt'))} ~ {clean_text(item.get('eduEdDt'))}"),
                    "target": clean_text(item.get("eduTarget")) or "전체",
                    "venue_name": venue,
                    "description": html_to_text(item.get("eduContents") or title),
                    "image_url": normalize_link(target.url, item.get("eduOriginThumbImg")),
                    "collection_type": "api_json",
                    "source_group": "museum_science",
                    "raw_fields": public_raw_fields(item) | {"parser": "mmca_exhibition_education_event_api"},
                }
            )
        if total_counts["events"] and page * 8 >= total_counts["events"]:
            break

    expected_sections = {
        "children",
        "gwacheon_children_museum",
        "exhibitions",
        "education",
        "events",
    }
    required_pages = (
        sum(max(1, (count + 7) // 8) for count in total_counts.values())
        if set(total_counts) == expected_sections
        else max_pages + 1
    )
    pagination_complete = (
        set(total_counts) == expected_sections
        and required_pages <= max_pages
        and page_budget.used >= required_pages
    )
    source_row_count = len(rows)
    rows = coalesce_mmca_program_rows(rows)
    meta = {
        "pages": pages,
        "detail_pages": child_detail_pages,
        "discovered_links": len(rows),
        "pagination_detected": any(count > 8 for count in total_counts.values()),
        "pagination_complete": pagination_complete,
        "source_cap_reached": not pagination_complete,
        "recursion_depth": 0,
        "total_count": sum(total_counts.values()),
        "section_counts": total_counts,
        "required_pages": required_pages,
        "page_budget_used": page_budget.used,
        "child_detail_pages": child_detail_pages,
        "source_rows": source_row_count,
        "semantic_duplicate_count": source_row_count - len(rows),
    }
    return dedupe_rows(rows), "mmca_exhibition_education_event_api", meta


def collect_geochang_lifelong_cards(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False

    for page in range(1, max_pages + 1):
        if page > 1:
            query["page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select("a[href*='page=']"))
        for item in soup.select(".listover"):
            title_el = item.select_one(".lec_title")
            status = clean_text((title_el.find("span") if title_el else None).get_text(" ", strip=True) if title_el and title_el.find("span") else "")
            if title_el and title_el.find("span"):
                title_el.find("span").extract()
            title = clean_text(title_el.get_text(" ", strip=True) if title_el else "")
            if not title:
                continue
            link = item.find("a", href=True)
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            pairs = {
                clean_text(li.find("b").get_text(" ", strip=True)): clean_text(li.find("span").get_text(" ", strip=True))
                for li in item.select(".lec_left_wrap li")
                if li.find("b") and li.find("span")
            }
            image = item.find("img")
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": "",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": "무료",
                    "period": clean_text(pairs.get("\uAD50\uC721\uAE30\uAC04")),
                    "apply_period": clean_text(pairs.get("\uC811\uC218\uC77C\uC2DC")),
                    "schedule_raw": clean_text(pairs.get("\uC694\uC77C/\uC2DC\uAC04") or pairs.get("\uAD50\uC721\uAE30\uAC04")),
                    "target": clean_text(pairs.get("\uAD50\uC721\uB300\uC0C1") or pairs.get("대상")),
                    "room": clean_text(pairs.get("장소")),
                    "venue_name": clean_text(pairs.get("장소")),
                    "phone": clean_text(pairs.get("문의")),
                    "description": clean_text(item.get_text(" ", strip=True)),
                    "image_url": normalize_link(current_url, image.get("src") if image else None),
                    "raw_fields": {"pairs": pairs, "parser": "geochang_lifelong_cards"},
                }
            )
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "geochang_lifelong_cards", meta


INJE_LIFELONG_BASE_URL = "https://lifelong.inje.go.kr"
INJE_LIFELONG_LIST_URLS = (
    f"{INJE_LIFELONG_BASE_URL}/lct/course/list",
    f"{INJE_LIFELONG_BASE_URL}/lct/edu/list",
)
INJE_LIFELONG_FACILITIES_URL = f"{INJE_LIFELONG_BASE_URL}/facilities/list"
INJE_LIFELONG_DEFAULT_BRANCH = "인제군평생학습센터"
INJE_LIFELONG_DEFAULT_ADDRESS = "강원특별자치도 인제군 인제읍 인제로 187번길 6, 인제군청 제2별관 1층"


def inje_lifelong_fetch_soup(
    s: requests.Session,
    url: str,
    timeout: int,
    params: dict[str, Any] | None = None,
) -> BeautifulSoup:
    response = s.get(url, params=params, timeout=timeout, verify=True)
    response.raise_for_status()
    response.encoding = response.apparent_encoding or response.encoding or "utf-8"
    return BeautifulSoup(response.text, "html.parser")


def inje_lifelong_title_category(title_node: BeautifulSoup | None) -> tuple[str, str]:
    if not title_node:
        return "", ""
    category_node = title_node.find("span")
    category = clean_text(category_node.get_text(" ", strip=True) if category_node else "").strip("[]")
    if category_node:
        category_node.extract()
    return clean_text(title_node.get_text(" ", strip=True)), category


def inje_lifelong_kv_from_list_text(text: str, key: str) -> str:
    text = clean_text(text)
    marker = f"{key}:"
    start = text.find(marker)
    if start < 0:
        return ""
    start += len(marker)
    end = len(text)
    for next_key in ("교육기간:", "신청기간:", "교육대상:", "접수상태:", "수강료/재료비:", "모집인원:"):
        if next_key == marker:
            continue
        index = text.find(next_key, start)
        if index >= 0:
            end = min(end, index)
    return clean_text(text[start:end])


def inje_lifelong_fee_parts(value: str) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    parts = [clean_text(part) for part in text.split("/", 1)]
    return (parts[0] if parts else ""), (parts[1] if len(parts) > 1 else "")


def inje_lifelong_status(value: str) -> str:
    text = clean_text(value)
    if any(token in text for token in ("신청중", "대기접수중", "접수중")):
        return "접수중"
    if any(token in text for token in ("교육중", "진행중")):
        return "교육중"
    return text


def inje_lifelong_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for tr in soup.select("table tr"):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
        cells = [cell for cell in cells if cell]
        if len(cells) == 1 and "title" not in pairs:
            pairs["title"] = cells[0]
        elif len(cells) >= 2:
            pairs[cells[0]] = cells[1]
    return pairs


def inje_lifelong_facility_map(s: requests.Session, timeout: int, max_pages: int) -> dict[str, dict[str, str]]:
    facilities: dict[str, dict[str, str]] = {}
    for page in range(1, max(1, max_pages) + 1):
        soup = inje_lifelong_fetch_soup(s, INJE_LIFELONG_FACILITIES_URL, timeout, params={"page.page": page})
        items = soup.select(".facList li")
        if not items:
            break
        for item in items:
            name = clean_text((item.select_one(".facTitle") or item).get_text(" ", strip=True))
            if not name:
                continue
            info: dict[str, str] = {}
            for p in item.find_all("p"):
                text = clean_text(p.get_text(" ", strip=True))
                if text.startswith("주소:"):
                    address = clean_text(text.split(":", 1)[1])
                    if address and address != ".":
                        info["address"] = address
                elif text.startswith("전화번호:"):
                    phone = clean_text(text.split(":", 1)[1])
                    if phone and phone != ".":
                        info["phone"] = phone
                elif text.startswith("기관유형"):
                    info["facility_type"] = clean_text(text.split(":", 1)[1] if ":" in text else text)
            if info:
                facilities.setdefault(name, info)
        if len(items) < 10:
            break
    return facilities


def inje_lifelong_extract_address(*values: str) -> str:
    text = clean_text(" ".join(value for value in values if value))
    if not text:
        return ""

    def normalize_fragment(candidate: str) -> str:
        candidate = clean_text(candidate)
        if not candidate:
            return ""
        if not (any(token in candidate for token in ("로", "길", "읍", "면")) and re.search(r"\d", candidate)):
            return ""
        if not candidate.startswith(("강원", "인제")):
            candidate = f"강원특별자치도 인제군 {candidate}"
        elif candidate.startswith("인제군"):
            candidate = f"강원특별자치도 {candidate}"
        elif re.match(r"인제(?:읍|남면|북면|기린면|상남면|서화면)", candidate):
            candidate = f"강원특별자치도 인제군 {candidate}"
        return candidate

    for candidate in re.findall(r"[\[(]([^\]\)]+)[\]\)]", text):
        normalized = normalize_fragment(candidate)
        if normalized:
            return normalized
    road_match = re.search(
        r"((?:강원(?:특별자치도)?\s*)?(?:인제군\s*)?(?:[가-힣A-Za-z0-9]+\s+)*(?:[가-힣A-Za-z0-9]+(?:로|길|번길)\s*\d+(?:-\d+)?(?:,\s*\d층)?))",
        text,
    )
    if road_match:
        return normalize_fragment(road_match.group(1))
    return ""


def inje_lifelong_venue_name(place: str, branch: str) -> str:
    text = clean_text(place)
    if not text:
        return branch
    if "/" in text:
        tail = clean_text(text.rsplit("/", 1)[-1])
        if tail:
            return re.sub(r"\[[^\]]+\]", "", tail).strip() or tail
    return re.sub(r"\[[^\]]+\]", "", text).strip() or branch


def inje_lifelong_image_url(soup: BeautifulSoup, raw_url: str) -> str:
    for hidden in soup.select("input[type=hidden][id^=attach_]"):
        value = clean_text(hidden.get("value"))
        if re.search(r"\.(?:jpg|jpeg|png|gif|webp)(?:$|\?)", value, re.I):
            return urldefrag(urljoin(raw_url, value))[0]
    for img in soup.select("img"):
        value = clean_text(img.get("src"))
        if value and not any(token in value for token in ("/logo", "/btn_", "/icon", "/common/")):
            return urldefrag(urljoin(raw_url, value))[0]
    return ""


def inje_lifelong_row_from_card(
    target: CrawlTarget,
    card: BeautifulSoup,
    list_url: str,
    facility_map: dict[str, dict[str, str]],
    detail_soup: BeautifulSoup | None = None,
) -> dict[str, Any] | None:
    raw_url = urldefrag(urljoin(list_url, card.get("href")))[0]
    branch = clean_text((card.select_one(".eduCenter") or card).get_text(" ", strip=True))
    if card.select_one(".eduCenter"):
        branch = clean_text(card.select_one(".eduCenter").get_text(" ", strip=True))
    branch = branch or INJE_LIFELONG_DEFAULT_BRANCH
    title_node = card.select_one(".eduTitle")
    title, category = inje_lifelong_title_category(BeautifulSoup(str(title_node), "html.parser").select_one(".eduTitle") if title_node else None)
    text = clean_text(card.get_text(" ", strip=True))
    if not title:
        title = text
    period = inje_lifelong_kv_from_list_text(text, "교육기간")
    apply_period = inje_lifelong_kv_from_list_text(text, "신청기간")
    target_text = inje_lifelong_kv_from_list_text(text, "교육대상")
    status = inje_lifelong_status(inje_lifelong_kv_from_list_text(text, "접수상태"))
    fee, material_fee = inje_lifelong_fee_parts(inje_lifelong_kv_from_list_text(text, "수강료/재료비"))
    capacity = inje_lifelong_kv_from_list_text(text, "모집인원")
    detail_pairs: dict[str, str] = {}
    description = ""
    place = ""
    schedule_raw = ""
    instructor = ""
    phone = ""
    image_url = ""
    if detail_soup:
        detail_pairs = inje_lifelong_detail_pairs(detail_soup)
        period = detail_pairs.get("교육기간") or period
        target_text = detail_pairs.get("교육대상") or target_text
        place = detail_pairs.get("교육장소") or ""
        schedule_raw = detail_pairs.get("교육일시") or ""
        phone = detail_pairs.get("연락처") or facility_map.get(branch, {}).get("phone", "")
        instructor = detail_pairs.get("강사명") or ""
        description = detail_pairs.get("내용") or ""
        image_url = inje_lifelong_image_url(detail_soup, raw_url)
    facility = facility_map.get(branch, {})
    venue_address = inje_lifelong_extract_address(description, place) or clean_text(facility.get("address")) or INJE_LIFELONG_DEFAULT_ADDRESS
    venue_name = inje_lifelong_venue_name(place, branch)
    map_branch = branch
    if venue_name and venue_name != branch and place:
        map_branch = f"{branch} - {venue_name}"
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, map_branch),
        "title": title,
        "branch": map_branch,
        "branch_code": map_branch,
        "preserve_branch": True,
        "category": category,
        "collection_category": "평생교육",
        "domain_category": "평생교육",
        "source_group": "lifelong_learning",
        "operator_type": "지자체/공공기관",
        "collection_type": "static_html",
        "raw_url": raw_url,
        "application_url": raw_url,
        "application_method_raw": "온라인/전화/방문 접수",
        "status": status,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": schedule_raw or period,
        "target": target_text,
        "eligibility_raw": target_text,
        "fee": fee,
        "material_fee": material_fee,
        "capacity": capacity,
        "venue_name": venue_name,
        "room": place or venue_name,
        "address": venue_address,
        "venue_address": venue_address,
        "phone": phone,
        "instructor": instructor,
        "description": description,
        "image_url": image_url,
        "program_type": "강좌",
        "reservation_available": status in {"접수중", "대기접수중"},
        "raw_fields": {
            "list_text": text,
            "detail_pairs": detail_pairs,
            "facility": facility,
            "original_branch": branch,
            "parser": "inje_lifelong_course_cards",
        },
    }


def collect_inje_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    seen_urls: set[str] = set()
    facility_map = inje_lifelong_facility_map(s, timeout=timeout, max_pages=max_pages)
    for list_url in INJE_LIFELONG_LIST_URLS:
        for page in range(1, max(1, max_pages) + 1):
            soup = inje_lifelong_fetch_soup(s, list_url, timeout, params={"page.page": page})
            cards = soup.select(".eduList2 a[href*='courseSeq=']")
            if not cards:
                break
            pages += 1
            for card in cards:
                raw_url = urldefrag(urljoin(list_url, card.get("href")))[0]
                if raw_url in seen_urls:
                    continue
                seen_urls.add(raw_url)
                detail_soup = None
                if detail_pages < max(0, detail_limit):
                    try:
                        detail_soup = inje_lifelong_fetch_soup(s, raw_url, timeout)
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("inje lifelong detail fetch failed %s: %s", raw_url, exc)
                row = inje_lifelong_row_from_card(target, card, list_url, facility_map, detail_soup)
                if row:
                    rows.append(row)
            if len(cards) < 10:
                break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": len(seen_urls),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > len(INJE_LIFELONG_LIST_URLS),
        "recursion_depth": 0,
        "facilities": len(facility_map),
    }
    return dedupe_rows(rows), "inje_lifelong_course_cards", meta


def collect_ydct_lecture2(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    soup = fetch_soup(session(), target.url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    for tr in soup.select("tbody tr"):
        title_el = tr.select_one(".td_tit h2")
        title = clean_text(title_el.get_text(" ", strip=True) if title_el else "")
        subtitle = clean_text((tr.select_one(".td_tit p") or {}).get_text(" ", strip=True) if tr.select_one(".td_tit p") else "")
        if subtitle:
            title = clean_text(f"{title} {subtitle}")
        if not title:
            continue
        category = clean_text((tr.select_one(".list_tag") or {}).get_text(" ", strip=True) if tr.select_one(".list_tag") else "")
        detail = tr.select_one(".detail_btn")
        idx = clean_text(detail.get("data-index-number") if detail else "")
        apply_link = tr.select_one(".td_apply a[href]")
        raw_url = normalize_link(target.url, apply_link.get("href") if apply_link else None) or target.url
        if idx:
            raw_url = normalize_link(target.url, f"/lecture2/request/{idx}") or raw_url
        day = clean_text((tr.select_one(".td_day") or {}).get_text(" ", strip=True) if tr.select_one(".td_day") else "")
        time_text = clean_text((tr.select_one(".td_time") or {}).get_text(" ", strip=True) if tr.select_one(".td_time") else "")
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": clean_text(apply_link.get_text(" ", strip=True) if apply_link else ""),
                "fee": "",
                "period": "",
                "schedule_raw": clean_text(" ".join(part for part in [day, time_text] if part)),
                "target": "",
                "capacity": clean_text((tr.select_one(".td_person") or {}).get_text(" ", strip=True) if tr.select_one(".td_person") else ""),
                "room": clean_text((tr.select_one(".td_room") or {}).get_text(" ", strip=True) if tr.select_one(".td_room") else ""),
                "venue_name": clean_text((tr.select_one(".td_room") or {}).get_text(" ", strip=True) if tr.select_one(".td_room") else ""),
                "instructor": clean_text((tr.select_one(".td_teacher") or {}).get_text(" ", strip=True) if tr.select_one(".td_teacher") else ""),
                "description": clean_text(tr.get_text(" ", strip=True)),
                "raw_fields": {"idx": idx, "parser": "ydct_lecture2_table"},
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": bool(soup.select(".pagination, .paging, a[href*='page=']")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ydct_lecture2_table", meta


def anyang_learning_target(branch: Any) -> str:
    text = clean_text(branch)
    if "노인" in text:
        return "어르신"
    return "일반/전체"


def collect_anyang_learning_search(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    for page in range(1, max(1, max_pages) + 1):
        query = parse_qs(parsed.query)
        if page > 1:
            query["Page"] = [str(page)]
        else:
            query.pop("Page", None)
        page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["td", "th"])]
            if len(cells) < 7 or not re.fullmatch(r"\d+", cells[0] or ""):
                continue
            link = tr.find("a", href=True)
            raw_url = normalize_link(page_url, link.get("href") if link else None) or page_url
            branch = cells[1]
            title = cells[2]
            target_text = anyang_learning_target(branch)
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": gwe_library_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "branch_code": stable_provider("ANYANG_LEARNING", branch),
                    "category": "평생학습",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": cells[-1],
                    "fee": "별도 안내",
                    "period": normalize_mixed_date_range(cells[4]),
                    "apply_period": normalize_mixed_date_range(cells[3]),
                    "schedule_raw": cells[5],
                    "target": target_text,
                    "venue_name": branch,
                    "program_type": "강좌",
                    "collection_category": "평생학습",
                    "domain_category": "평생학습",
                    "source_group": clean_text(target.extra.get("source_group") or "lifelong_learning"),
                    "operator_type": "지자체",
                    "collection_type": "static_html",
                    "description": clean_text(tr.get_text(" ", strip=True)),
                    "raw_fields": {"cells": cells, "parser": "anyang_learning_search_table", "page_url": page_url},
                }
            )
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select("a[href*='Page='], a[href*='page=']"))
        if page_rows == 0:
            pagination_exhausted = True
            break
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "anyang_learning_search_table", meta


BUSAN_LIFELONG_PROVIDER = "MUNI_LLL_BUSAN_GO_KR_944C621B"
BUKGU_DAEGU_PROVIDER = "MUNI_WWW_BUK_DAEGU_KR_RESERVATION"


def busan_lifelong_offices(soup: BeautifulSoup) -> list[dict[str, str]]:
    offices: dict[str, dict[str, str]] = {}
    for option in soup.select("#o_search_ch option[value]"):
        code = clean_text(option.get("value"))
        name = clean_text(option.get_text(" ", strip=True))
        if code:
            offices.setdefault(code, {"code": code, "name": name, "phone": "", "office_status": ""})

    for link in soup.select("a[onclick*='fn_learning_list']"):
        onclick = clean_text(link.get("onclick"))
        match = re.search(r"fn_learning_list\('([^']+)'\)", onclick)
        if not match:
            continue
        code = clean_text(match.group(1))
        text = clean_text(link.get_text(" ", strip=True))
        office = offices.setdefault(code, {"code": code, "name": "", "phone": "", "office_status": ""})
        status_pattern = "|".join(re.escape(status) for status in ("접수중", "접수대기", "접수종료"))
        parsed = re.match(rf"^({status_pattern})\s+(.+?)(?:\s+전화\s+([0-9-]+))?$", text)
        if parsed:
            office["office_status"] = clean_text(parsed.group(1))
            office["name"] = office["name"] or clean_text(parsed.group(2))
            office["phone"] = clean_text(parsed.group(3) or "")
        elif text and not office["name"]:
            office["name"] = text

    return [office for office in offices.values() if office.get("code") and office.get("name")]


def collect_busan_lifelong_learning(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    office_code = clean_text((query.get("inst_id") or [""])[0]) or clean_text(target.extra.get("branch_code"))
    if office_code:
        query["inst_id"] = [office_code]
        query.setdefault("searchCondition", ["0"])
        query.setdefault("searchKeyword", [""])
        query.setdefault("out_inst_yn", ["N"])
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False

    def span_value(node: Any) -> str:
        if not node:
            return ""
        clone = BeautifulSoup(str(node), "lxml")
        for hidden in clone.select("em.hidden"):
            hidden.extract()
        return clean_text(clone.get_text(" ", strip=True))

    def title_time(title: str) -> str:
        match = re.search(r"(?:(?:오전|오후)\s*)?\d{1,2}:\d{2}\s*~\s*(?:(?:오전|오후)\s*)?\d{1,2}:\d{2}", title)
        return clean_text(match.group(0)) if match else ""

    for page in range(1, max_pages + 1):
        query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select("a[onclick*='fn_list'], a[href*='pageIndex=']"))

        for tr in soup.select("table tr"):
            title_el = tr.select_one("td.subject span.tit")
            title = clean_text(title_el.get_text(" ", strip=True) if title_el else "")
            if not title:
                continue
            link = tr.select_one("td.subject a[href]")
            raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
            branch = clean_text((tr.select_one("td.subject span.org") or {}).get_text(" ", strip=True) if tr.select_one("td.subject span.org") else "") or target.branch
            type_spans = tr.select("td.type span")
            fee = clean_text(type_spans[0].get_text(" ", strip=True)) if type_spans else ""
            instructor = clean_text(type_spans[1].get_text(" ", strip=True)) if len(type_spans) > 1 else ""
            period = normalize_yymmdd_range(span_value(tr.select_one("td .s_type.blue")))
            apply_period = normalize_yymmdd_range(span_value(tr.select_one("td .s_type.red1")))
            capacity = span_value(tr.select_one("td .s_type.indigo1"))
            status = clean_text((tr.select_one("td .s_btn") or {}).get_text(" ", strip=True) if tr.select_one("td .s_btn") else "")
            schedule = clean_text(" ".join(part for part in [period, title_time(title)] if part))
            row_text = clean_text(tr.get_text(" ", strip=True))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "branch_code": office_code,
                    "category": "평생학습",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": fee,
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule,
                    "target": "",
                    "capacity": capacity,
                    "instructor": instructor,
                    "description": row_text,
                    "raw_fields": {
                        "office_code": office_code,
                        "row_text": row_text,
                        "parser": "busan_lifelong_learning_table",
                    },
                }
            )
            page_rows += 1
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "busan_lifelong_learning_table", meta


def collect_busan_lifelong_office_cycle(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    offices = busan_lifelong_offices(soup)
    base_url = urljoin(target.url, "/yeyak/ilms/learning/learningList.do")
    rows: list[dict[str, Any]] = []
    pages = 1
    detail_pages = 0
    pagination_detected = False
    row_limit = 0
    try:
        row_limit = max(0, int(target.extra.get("per_target_limit") or 0))
    except (TypeError, ValueError):
        row_limit = 0

    for office in offices:
        if row_limit > 0 and len(rows) >= row_limit:
            break
        list_url = (
            f"{base_url}?{urlencode({'inst_id': office['code'], 'pageIndex': 1, 'searchCondition': 0, 'searchKeyword': '', 'out_inst_yn': 'N'})}"
        )
        branch_target = CrawlTarget(
            provider=target.provider,
            name=target.name,
            branch=office["name"],
            url=list_url,
            source=target.source,
            priority=target.priority,
            region=target.region,
            extra={**target.extra, "branch_code": office["code"], "branch_phone": office.get("phone", "")},
        )
        branch_rows, _parser, meta = collect_busan_lifelong_learning(branch_target, timeout=timeout, max_pages=max_pages)
        pages += int(meta.get("pages") or 0)
        detail_pages += int(meta.get("detail_pages") or 0)
        pagination_detected = pagination_detected or bool(meta.get("pagination_detected"))
        for row in branch_rows:
            if row_limit > 0 and len(rows) >= row_limit:
                break
            row["branch"] = office["name"]
            row["branch_code"] = office["code"]
            row["phone"] = office.get("phone", "")
            row["venue_name"] = office["name"]
            row["collection_category"] = "공공예약"
            row["domain_category"] = "평생교육"
            row["source_group"] = "public_reservation"
            row["operator_type"] = "지자체/공공기관"
            row.setdefault("raw_fields", {})
            row["raw_fields"].update(
                {
                    "office_code": office["code"],
                    "office_name": office["name"],
                    "office_phone": office.get("phone", ""),
                    "office_status": office.get("office_status", ""),
                    "parser": "busan_lifelong_office_cycle",
                }
            )
            rows.append(row)

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(offices),
        "reservation_discovery_links": len(rows),
        "pagination_detected": pagination_detected,
        "recursion_depth": 1,
        "branches": len(offices),
    }
    return dedupe_rows(rows), "busan_lifelong_office_cycle", meta


def michuhol_dl_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in soup.select("dl"):
        dt = dl.find("dt")
        dd = dl.find("dd")
        if dt and dd:
            label = clean_text(dt.get_text(" ", strip=True))
            value = clean_text(dd.get_text(" ", strip=True))
        else:
            parts = [clean_text(part) for part in dl.get_text("\n", strip=True).splitlines() if clean_text(part)]
            label = parts[0] if parts else ""
            value = clean_text(" ".join(parts[1:])) if len(parts) > 1 else ""
        if label:
            pairs[label.rstrip(":")] = value
    return pairs


def michuhol_detail_description(soup: BeautifulSoup) -> str:
    heading = None
    for node in soup.find_all(["h3", "h4", "strong", "p", "dt"]):
        if clean_text(node.get_text(" ", strip=True)) == "강좌소개":
            heading = node
            break
    if not heading:
        return ""
    chunks: list[str] = []
    for sibling in heading.find_all_next():
        text = clean_text(sibling.get_text(" ", strip=True))
        if not text:
            continue
        if text in {"강의계획서", "참고사항", "신청하기", "목록"}:
            break
        if text != "강좌소개":
            chunks.append(text)
        if len(chunks) >= 4:
            break
    return clean_text(" ".join(chunks))


def michuhol_sq_from_url(url: str) -> str:
    query = parse_qs(urlparse(url).query)
    return clean_text((query.get("sq") or query.get("edu_sq") or [""])[0])


def collect_michuhol_education_apply(target: CrawlTarget, timeout: int, max_pages: int, detail_limit: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    address = "인천광역시 미추홀구 독정이로 95"

    for page in range(1, max(1, max_pages) + 1):
        query["page"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        page_rows = 0
        pages += 1
        for tr in soup.select("tbody tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
            if len(cells) < 8:
                continue
            title_link = tr.select_one("a[href*='step1.do']")
            if not title_link:
                continue
            title = clean_text(title_link.get_text(" ", strip=True))
            if not title or is_low_value_title(title):
                continue
            raw_url = normalize_link(current_url, title_link.get("href")) or current_url
            apply_link = tr.select_one("a[href*='step2.do']")
            application_url = normalize_link(current_url, apply_link.get("href") if apply_link else None) or raw_url
            category, _list_title, branch, apply_period, period, target_text, capacity, status = cells[:8]
            sq = michuhol_sq_from_url(raw_url)

            detail: dict[str, str] = {}
            description = ""
            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail = michuhol_dl_pairs(detail_soup)
                    description = michuhol_detail_description(detail_soup)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("Michuhol detail fetch failed %s: %s", raw_url, exc)

            detail_branch = clean_text(detail.get("기관") or branch or target.branch)
            detail_period = normalize_mixed_date_range(clean_text(detail.get("수강기간") or period))
            schedule = clean_text(" ".join(part for part in [detail.get("수강기간", ""), detail.get("교육시간", "")] if part))
            schedule = clean_text(re.sub(r"\d{4}-\d{2}-\d{2}\s*~\s*\d{4}-\d{2}-\d{2}", "", schedule).strip())
            schedule = clean_text(re.sub(r"\(\s*\)", "", schedule))

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, detail_branch),
                    "title": title,
                    "branch": detail_branch,
                    "branch_code": clean_text((parse_qs(parsed.query).get("organ_cd") or [""])[0]) or re.sub(r"[^A-Za-z0-9가-힣]+", "_", detail_branch).strip("_"),
                    "category": clean_text(detail.get("분류") or category),
                    "raw_url": raw_url,
                    "application_url": application_url,
                    "status": clean_text(status),
                    "fee": clean_text(detail.get("수강료")),
                    "material_fee": clean_text(detail.get("재료비")),
                    "period": detail_period,
                    "apply_period": normalize_mixed_date_range(detail.get("접수일시") or apply_period),
                    "schedule_raw": schedule,
                    "target": clean_text(detail.get("교육대상")) or target_text,
                    "capacity": clean_text(detail.get("정원") or capacity),
                    "room": clean_text(detail.get("강의실")),
                    "venue_name": clean_text(detail.get("강의실") or detail_branch),
                    "address": address,
                    "venue_address": address,
                    "phone": clean_text(detail.get("문의처")),
                    "application_method_raw": clean_text(detail.get("접수방법")),
                    "description": description or clean_text(" ".join(cells)),
                    "collection_category": "공공예약",
                    "domain_category": "평생교육",
                    "operator_type": "지자체/공공기관",
                    "source_group": "public_reservation",
                    "collection_type": "static_html",
                    "program_type": "강좌",
                    "application_type": "ONLINE_RESERVATION",
                    "reservation_available": "신청" in clean_text(status),
                    "raw_fields": {"cells": cells, "detail_pairs": detail, "sq": sq, "parser": "michuhol_education_apply_table"},
                }
            )
            page_rows += 1

        pagination_detected = pagination_detected or page_rows >= 30
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "michuhol_education_apply_table", meta


def collect_ansan_reserve_cards(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    pagination_complete = False
    row_cap_reached = False
    row_limit = 0
    try:
        row_limit = max(0, int(target.extra.get("per_target_limit") or 0))
    except (TypeError, ValueError):
        row_limit = 0

    view_path = parsed.path.split(";jsessionid", 1)[0].replace("List.do", "View.do")
    current_menu_no = clean_text((query.get("currentMenuNo") or [""])[0])

    for page in range(1, max_pages + 1):
        if row_limit > 0 and len(rows) >= row_limit:
            row_cap_reached = True
            break
        query["pageIndex"] = [str(page)]
        clean_path = parsed.path.split(";jsessionid", 1)[0]
        current_url = parsed._replace(path=clean_path, params="", query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        pagination_detected = pagination_detected or bool(soup.select("a[onclick*='fnSearch'], a[href*='pageIndex=']"))

        for item in soup.select("ul.blog.reserv > li"):
            if row_limit > 0 and len(rows) >= row_limit:
                row_cap_reached = True
                break
            link = item.select_one("a[onclick*='fnView']")
            title = clean_text((item.select_one(".txtW .tit") or {}).get_text(" ", strip=True) if item.select_one(".txtW .tit") else "")
            if not link or not title:
                continue
            onclick = clean_text(link.get("onclick"))
            match = re.search(r"fnView\('([^']+)'", onclick)
            reservation_id = clean_text(match.group(1) if match else "")
            detail_query = {"resrId": reservation_id}
            if current_menu_no:
                detail_query["currentMenuNo"] = current_menu_no
            raw_url = parsed._replace(path=view_path, params="", query=urlencode(detail_query)).geturl() if reservation_id else current_url

            pairs: dict[str, str] = {}
            for line in item.select(".txtW .etc li"):
                label_node = line.select_one(".em")
                label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
                if label_node:
                    label_node.extract()
                value = clean_text(line.get_text(" ", strip=True))
                if label:
                    pairs[label] = value

            status = clean_text((item.select_one(".label") or {}).get_text(" ", strip=True) if item.select_one(".label") else "")
            badges = [clean_text(node.get_text(" ", strip=True)) for node in item.select(".addLabel span")]
            fee = clean_text(pairs.get("\uC218\uAC15\uB8CC")) or next((badge for badge in badges if "원" in badge or badge in {"무료", "유료"}), "")
            branch = clean_text(pairs.get("기관/부서")) or target.branch
            period = normalize_mixed_date_range(clean_text(pairs.get("교육기간") or pairs.get("체험/견학기간") or pairs.get("예약기간")))
            apply_period = normalize_mixed_date_range(clean_text(pairs.get("접수기간") or pairs.get("신청기간")))
            weekday = clean_text(pairs.get("요일"))
            schedule_raw = clean_text(" ".join(part for part in [period, f"요일 {weekday}" if weekday else ""] if part))
            row_text = clean_text(item.get_text(" ", strip=True))

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "category": "공공예약",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "fee": fee,
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule_raw,
                    "target": clean_text(pairs.get("대상")),
                    "room": clean_text(pairs.get("위치")),
                    "venue_name": clean_text(pairs.get("위치")),
                    "description": row_text,
                    "raw_fields": {
                        "reservation_id": reservation_id,
                        "badges": badges,
                        "pairs": pairs,
                        "parser": "ansan_reserve_cards",
                    },
                }
            )
            page_rows += 1
        if page_rows == 0:
            pagination_complete = True
            break

    page_cap_reached = bool(
        not pagination_complete
        and not row_cap_reached
        and pages >= max_pages
    )
    snapshot_complete = bool(
        pagination_complete
        and not row_cap_reached
        and not page_cap_reached
    )
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "pagination_detected": pagination_detected,
        "pagination_complete": snapshot_complete,
        "pagination_exhausted": snapshot_complete,
        "page_cap_reached": page_cap_reached,
        "source_cap_reached": row_cap_reached or page_cap_reached,
        "details_complete": snapshot_complete,
        "snapshot_complete": snapshot_complete,
        "no_current_data": snapshot_complete and not rows,
        "no_current_reason": (
            "complete Ansan reservation category contains no rows"
            if snapshot_complete and not rows
            else ""
        ),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ansan_reserve_cards", meta


