def collect_ansan_education_categories(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    category_counts: dict[str, int] = {}
    categories_completed = 0
    source_cap_reached = False
    row_limit = 0
    try:
        row_limit = max(0, int(target.extra.get("per_target_limit") or 0))
    except (TypeError, ValueError):
        row_limit = 0

    for category_code, category_name, menu_no in ANSAN_EDU_CATEGORIES:
        if row_limit > 0 and len(rows) >= row_limit:
            break
        category_url = f"https://reserve.ansan.go.kr/edu/{category_code}/eduList.do?currentMenuNo={menu_no}"
        category_target = CrawlTarget(
            provider=target.provider,
            name=target.name,
            branch=target.branch,
            url=category_url,
            source=target.source,
            priority=target.priority,
            region=target.region,
            extra=target.extra,
        )
        category_rows, _, meta = collect_ansan_reserve_cards(category_target, timeout=timeout, max_pages=max_pages)
        pages += int(meta.get("pages") or 0)
        pagination_detected = pagination_detected or bool(meta.get("pagination_detected"))
        if bool(meta.get("snapshot_complete")):
            categories_completed += 1
        source_cap_reached = source_cap_reached or bool(meta.get("source_cap_reached"))
        category_counts[category_name] = len(category_rows)
        for row in category_rows:
            if row_limit > 0 and len(rows) >= row_limit:
                break
            row["category"] = category_name
            row["category_raw"] = category_code
            branch_slug = re.sub(r"[^A-Za-z0-9가-힣]+", "_", clean_text(row.get("branch") or category_name)).strip("_")
            row["branch_code"] = branch_slug[:80] or category_code
            row["collection_category"] = "공공예약"
            row["domain_category"] = "교육/강좌"
            row["operator_type"] = "지자체/공공기관"
            row["source_group"] = "public_reservation"
            row["collection_type"] = "static_html"
            row["program_type"] = infer_program_type(row.get("title"), category_name, "교육 강좌") or "교육"
            row["reservation_available"] = "접수중" in clean_text(row.get("status"))
            row["application_type"] = "ONLINE_RESERVATION"
            row["application_method_raw"] = "안산시 통합예약 온라인 신청"
            row.setdefault("raw_fields", {})
            row["raw_fields"]["category_code"] = category_code
            row["raw_fields"]["category_name"] = category_name
            row["raw_fields"]["parser"] = "ansan_edu_category_cards"
            rows.append(row)

    snapshot_complete = bool(
        categories_completed == len(ANSAN_EDU_CATEGORIES)
        and not source_cap_reached
    )
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": snapshot_complete,
        "pagination_exhausted": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "details_complete": snapshot_complete,
        "snapshot_complete": snapshot_complete,
        "no_current_data": snapshot_complete and not rows,
        "no_current_reason": (
            "complete Ansan education categories contain no rows"
            if snapshot_complete and not rows
            else ""
        ),
        "recursion_depth": 0,
        "category_counts": category_counts,
        "categories_completed": categories_completed,
        "categories_expected": len(ANSAN_EDU_CATEGORIES),
    }
    return dedupe_rows(rows), "ansan_edu_category_cards", meta


