UIWANG_RESERVE_PROVIDER = "MUNI_WWW_UIWANG_GO_KR_2A9DF9A4"
UIWANG_RESERVE_ROOT_URL = "https://www.uiwang.go.kr/reserve/"
UIWANG_RESERVE_AGGREGATE_PATH = "/reserve/EDU/E01/eduList.do"
UIWANG_NON_EDUCATION_PATH_PREFIXES = (
    "/reserve/FEV/",
    "/reserve/EHN/",
    "/reserve/EXP/",
)


def uiwang_discover_edu_categories(s: requests.Session, timeout: int) -> list[dict[str, str]]:
    start_url = UIWANG_RESERVE_ROOT_URL
    soup = fetch_soup(s, start_url, timeout=timeout)
    categories: list[dict[str, str]] = []
    seen: set[str] = set()

    for link in soup.select("a[href*='/reserve/'][href*='eduList.do']"):
        href = normalize_link(start_url, link.get("href"))
        if not href:
            continue
        parsed = urlparse(href)
        clean_path = parsed.path.split(";jsessionid", 1)[0]
        if not clean_path.endswith("/eduList.do"):
            continue
        if any(clean_path.startswith(prefix) for prefix in UIWANG_NON_EDUCATION_PATH_PREFIXES):
            continue
        # This is the all-dong roll-up of E11-E16. Crawling it together with
        # those six owner pages produces the same reservation IDs twice.
        if clean_path == UIWANG_RESERVE_AGGREGATE_PATH:
            continue
        query = parse_qs(parsed.query)
        menu_no = clean_text((query.get("currentMenuNo") or [""])[0])
        key = f"{clean_path}?currentMenuNo={menu_no}"
        if key in seen:
            continue
        seen.add(key)
        title = clean_text(link.get("title") or link.get_text(" ", strip=True))
        if not title:
            title = clean_text(clean_path.strip("/").split("/")[-2])
        categories.append(
            {
                "title": title,
                "url": urlunparse((parsed.scheme, parsed.netloc, clean_path, "", urlencode({"currentMenuNo": menu_no}) if menu_no else "", "")),
                "current_menu_no": menu_no,
                "path": clean_path,
            }
        )
    return categories


def uiwang_pair_map(item: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for node in item.select(".txtW .etc li"):
        label_node = node.select_one(".em")
        label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
        if label_node:
            label_node.extract()
        value = clean_text(node.get_text(" ", strip=True))
        if label:
            pairs[label] = value
    return pairs


def uiwang_page_declaration(soup: BeautifulSoup) -> tuple[Optional[int], int]:
    total: Optional[int] = None
    total_pages = 0
    page_text = ""
    total_label = soup.find(string=lambda value: value and "총게시물" in value)
    if total_label:
        container = total_label.parent.parent if total_label.parent else None
        page_text = clean_text(container.get_text(" ", strip=True) if container else total_label)
        total_match = re.search(r"총게시물\s*([\d,]+)\s*건", page_text)
        if total_match:
            total = int(total_match.group(1).replace(",", ""))
        page_match = re.search(r"현재페이지\s*\d+\s*/\s*(\d+)", page_text)
        if page_match:
            total_pages = int(page_match.group(1))
    for link in soup.select("a[onclick*='fnSearch']"):
        match = re.search(r"fnSearch\(\s*(\d+)\s*\)", clean_text(link.get("onclick")))
        if match:
            total_pages = max(total_pages, int(match.group(1)))
    cards = soup.select("ul.blog.reserv > li")
    if total_pages == 0 and (cards or total == 0):
        total_pages = 1
    return total, total_pages


def uiwang_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in soup.select(".listInfoBtm .infoArea .itemList > li, .infoArea .itemList > li"):
        label = item.select_one(".em")
        value = item.select_one(".txt")
        key = clean_text(label.get_text(" ", strip=True) if label else "").rstrip(":：")
        text = clean_text(value.get_text(" ", strip=True) if value else "")
        if key and text:
            pairs[key] = text

    # Recruitment tables use one header row followed by one value row rather
    # than alternating th/td cells, so zip adjacent homogeneous rows.
    for table in soup.select("table"):
        table_rows = table.select("tr")
        for index in range(len(table_rows) - 1):
            labels = table_rows[index].find_all("th", recursive=False)
            values = table_rows[index + 1].find_all("td", recursive=False)
            if labels and len(labels) == len(values):
                for label, value in zip(labels, values):
                    key = clean_text(label.get_text(" ", strip=True)).rstrip(":：")
                    text = clean_text(value.get_text(" ", strip=True))
                    if key and text:
                        pairs[key] = text
    pairs.update({key: value for key, value in pairs_from_definition_lists(soup).items() if key not in pairs})
    return pairs


def uiwang_status(value: Any) -> str:
    text = clean_text(value).replace(" ", "")
    if any(token in text for token in ("결원보충", "추가접수", "접수중")):
        return "OPEN"
    if "접수예정" in text:
        return "SCHEDULED"
    if any(token in text for token in ("접수마감", "교육종료", "교육중", "폐강", "종료")):
        return "CLOSED"
    return normalize_status(text) or text


def uiwang_image_url(soup: BeautifulSoup, detail_url: str) -> str:
    image = soup.select_one(".listInfoBtm img[src*='getResrImg.do'], .imgSlide img[src]")
    source = clean_text(image.get("src") if image else "")
    if not source:
        return ""
    parsed = urlparse(normalize_link(detail_url, source))
    clean_path = parsed.path.split(";jsessionid", 1)[0]
    return urlunparse((parsed.scheme, parsed.netloc, clean_path, "", parsed.query, ""))


def uiwang_detail_description(soup: BeautifulSoup) -> str:
    values: list[str] = []
    for node in soup.select(".contWrap"):
        text = clean_text(node.get_text(" ", strip=True))
        if text and text not in values:
            values.append(text)
    return clean_text(" ".join(values))[:20_000]


def uiwang_application_action(soup: BeautifulSoup, detail_url: str) -> tuple[str, str]:
    button = soup.select_one("a[onclick*='fnResvRqst'], button[onclick*='fnResvRqst']")
    if button:
        return detail_url, clean_text(button.get("onclick"))
    external_form = soup.select_one("form[action*='loginReserve.do'], form[action*='/reserve/']")
    if external_form:
        action = normalize_link(detail_url, external_form.get("action"))
        return detail_url, safe_url_for_log(action)
    return "", ""


def collect_siheung_edu_programs(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    per_target_limit = int(target.extra.get("per_target_limit") or 0)
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)

    for page in range(1, max_pages + 1):
        if per_target_limit > 0 and len(rows) >= per_target_limit:
            break
        query["pageIndex"] = [str(page)]
        current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        table = soup.select_one("table.tbl.app")
        if not table:
            break
        trs = table.select("tbody tr")
        if not trs:
            break
        index = 0
        page_rows = 0
        while index < len(trs):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in trs[index].select("td")]
            if len(cells) < 6 or "등록된 강의가 없습니다" in " ".join(cells):
                index += 1
                continue
            detail_cells: list[str] = []
            if index + 1 < len(trs):
                maybe_detail = [clean_text(td.get_text(" ", strip=True)) for td in trs[index + 1].select("td")]
                if len(maybe_detail) <= 3:
                    detail_cells = maybe_detail
                    index += 1
            title = cells[0]
            branch_match = re.match(r"^\[([^\]]+)\]", title)
            branch = clean_text(branch_match.group(1) if branch_match else target.branch)
            instructor = detail_cells[0] if len(detail_cells) > 0 else ""
            schedule_raw = detail_cells[1] if len(detail_cells) > 1 else ""
            fee = detail_cells[2] if len(detail_cells) > 2 else ""
            status = cells[5]
            raw_url = f"{current_url}#{stable_course_id(target.provider, current_url, title, branch)}"
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                "title": title,
                "branch": branch,
                "branch_code": re.sub(r"[^A-Za-z0-9가-힣]+", "_", branch).strip("_")[:80] or "siheung",
                "category": "평생교육",
                "raw_url": raw_url,
                "application_url": raw_url if any(token in status for token in ("접수중", "대기접수", "모집대기")) else "",
                "status": status_from_lines([status]) or status,
                "fee": fee,
                "period": normalize_mixed_date_range(cells[2]),
                "apply_period": normalize_mixed_date_range(cells[1]),
                "schedule_raw": schedule_raw,
                "target": cells[4],
                "capacity": cells[3],
                "capacity_current": cells[3].split("/")[0] if "/" in cells[3] else "",
                "capacity_total": cells[3].split("/")[-1] if "/" in cells[3] else "",
                "instructor": instructor,
                "description": clean_text(" ".join(cells + detail_cells)),
                "collection_category": "평생학습",
                "domain_category": "평생학습",
                "operator_type": "지자체/공공기관",
                "source_group": "lifelong_learning",
                "collection_type": "static_html",
                "program_type": "강좌",
                "application_type": "ONLINE_RESERVATION" if any(token in status for token in ("접수중", "대기접수", "모집대기")) else "INFO_ONLY",
                "raw_fields": {"parser": "siheung_edu_program_table", "cells": cells, "detail_cells": detail_cells},
            }
            rows.append({key: value for key, value in row.items() if value})
            page_rows += 1
            index += 1
            if per_target_limit > 0 and len(rows) >= per_target_limit:
                break
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "siheung_edu_program_table", meta


def collect_uiwang_reserve_categories(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    categories = uiwang_discover_edu_categories(s, timeout=timeout)
    per_target_limit = int(target.extra.get("per_target_limit") or 0)
    rows: list[dict[str, Any]] = []
    seen_reservation_ids: set[str] = set()
    pages = 0
    detail_pages = 0
    declared_pages = 0
    declared_rows = 0
    duplicate_rows = 0
    rejected_rows = 0
    pagination_detected = False
    category_counts: dict[str, int] = {}
    status_counts: Counter[str] = Counter()
    errors: list[str] = []
    stop_collection = False

    for category in categories:
        if stop_collection or (per_target_limit > 0 and len(rows) >= per_target_limit):
            break
        parsed = urlparse(category["url"])
        base_query = parse_qs(parsed.query)
        category_rows = 0
        page = 1
        total_pages = 1
        view_path = parsed.path.replace("eduList.do", "eduView.do")

        while page <= total_pages:
            if pages >= max_pages:
                errors.append(
                    f"max_pages cap reached after {pages} list pages while collecting {category['title']}"
                )
                stop_collection = True
                break
            if per_target_limit > 0 and len(rows) >= per_target_limit:
                stop_collection = True
                break

            query = {key: list(values) for key, values in base_query.items()}
            query["pageIndex"] = [str(page)]
            current_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
            soup = fetch_soup(s, current_url, timeout=timeout)
            pages += 1
            cards = soup.select("ul.blog.reserv > li")
            declared_total, page_count = uiwang_page_declaration(soup)
            if page == 1:
                total_pages = max(1, page_count)
                declared_pages += total_pages
                if declared_total is not None:
                    declared_rows += declared_total
                pagination_detected = pagination_detected or total_pages > 1
            if not cards:
                if declared_total not in (None, 0) or page < total_pages:
                    errors.append(
                        f"declared category page returned no cards: {category['title']} page={page}"
                    )
                break

            for item in cards:
                title_node = item.select_one(".txtW .tit, .titW .tit, p.tit")
                title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
                view_link = item.select_one("a[onclick*='fnView']")
                onclick = clean_text(view_link.get("onclick") if view_link else "")
                match = re.search(r"fnView\('([^']+)'", onclick)
                reservation_id = clean_text(match.group(1) if match else "")
                if not title or is_low_value_title(title) or not reservation_id:
                    rejected_rows += 1
                    errors.append(
                        f"card missing stable title/resrId: {category['title']} page={page}"
                    )
                    continue
                if reservation_id in seen_reservation_ids:
                    duplicate_rows += 1
                    continue
                seen_reservation_ids.add(reservation_id)

                detail_query = urlencode(
                    (
                        ("currentMenuNo", clean_text(category["current_menu_no"])),
                        ("resrId", reservation_id),
                    )
                )
                detail_url = urlunparse(
                    (parsed.scheme, parsed.netloc, view_path, "", detail_query, "")
                )
                list_pairs = uiwang_pair_map(item)
                status_parts = [
                    clean_text(node.get_text(" ", strip=True))
                    for node in item.select(".label, .addLabel span")
                ]
                status_raw = clean_text(" ".join(dict.fromkeys(part for part in status_parts if part)))
                detail_pairs: dict[str, str] = {}
                detail_description = ""
                image_url = ""
                application_url = ""
                application_action = ""
                detail_fetched = False

                if detail_limit > 0:
                    if detail_pages >= detail_limit:
                        if not any(error.startswith("detail_limit cap") for error in errors):
                            errors.append(
                                f"detail_limit cap reached after {detail_pages} of at least {len(seen_reservation_ids)} reservations"
                            )
                    else:
                        try:
                            detail_soup = fetch_soup(s, detail_url, timeout=timeout)
                            detail_pages += 1
                            detail_fetched = True
                            detail_pairs = uiwang_detail_pairs(detail_soup)
                            detail_description = uiwang_detail_description(detail_soup)
                            image_url = uiwang_image_url(detail_soup, detail_url)
                            application_url, application_action = uiwang_application_action(
                                detail_soup, detail_url
                            )
                            detail_status_parts = [
                                clean_text(node.get_text(" ", strip=True))
                                for node in detail_soup.select(
                                    ".listInfoTop .label, .listInfoTop .addLabel span"
                                )
                            ]
                            detail_status = clean_text(
                                " ".join(dict.fromkeys(part for part in detail_status_parts if part))
                            )
                            status_raw = detail_status or status_raw
                        except Exception as exc:
                            logger.debug(
                                "Uiwang reservation detail fetch failed reservation_id=%s error_type=%s",
                                reservation_id,
                                type(exc).__name__,
                            )
                            errors.append(
                                f"detail fetch failed for {reservation_id}: {type(exc).__name__}"
                            )

                pairs = {**list_pairs, **detail_pairs}
                category_name = clean_text(category["title"])
                agency = first_by_keys(pairs, ("기관/부서", "기관", "운영기관"))
                branch = clean_text(agency or category_name or target.branch)
                venue_name = first_by_keys(pairs, ("교육장소", "이용장소", "행사장소", "위치"))
                period_raw = first_by_keys(pairs, ("교육기간", "이용기간", "행사기간"))
                apply_period_raw = first_by_keys(pairs, ("접수기간", "신청기간"))
                period = normalize_mixed_date_range(period_raw)
                apply_period = normalize_mixed_date_range(apply_period_raw)
                schedule_raw = clean_text(
                    " ".join(
                        part
                        for part in (
                            first_by_keys(pairs, ("교육시간", "이용시간", "행사시간")),
                            first_by_keys(pairs, ("교육요일", "요일")),
                        )
                        if part
                    )
                )
                capacity_text = first_by_keys(
                    pairs,
                    ("예약현황", "신청/정원", "정원/접수인원/대기자정원", "정원/대기정원"),
                )
                capacity_current, capacity_total = parse_capacity_pair(capacity_text)
                if capacity_total is None:
                    capacity_total = parse_capacity_number(
                        first_by_keys(pairs, ("모집정원", "정원", "모집인원"))
                    )
                status = uiwang_status(status_raw)
                is_open = status == "OPEN"
                if not detail_fetched and is_open:
                    application_url = detail_url
                reservation_available = is_open and bool(application_url)
                status_counts[status] += 1
                raw_text = clean_text(item.get_text(" ", strip=True))
                fee = first_by_keys(pairs, ("수강료", "사용료", "이용료")) or next(
                    (part for part in status_parts if "원" in part or part in {"무료", "유료"}),
                    "",
                )
                branch_code = re.sub(r"[^A-Za-z0-9가-힣]+", "_", branch).strip("_")[:80]

                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": f"uiwang:{reservation_id}",
                        "prefer_incoming_provider_course_id": True,
                        "title": title,
                        "branch": branch,
                        "branch_code": branch_code or category_name,
                        "preserve_branch": True,
                        "category": category_name,
                        "category_raw": category["path"],
                        "raw_url": detail_url,
                        "application_url": application_url if reservation_available else "",
                        "status": status,
                        "fee": fee,
                        "period": period,
                        "apply_period": apply_period,
                        "schedule_raw": schedule_raw or period,
                        "target": first_by_keys(pairs, ("교육대상", "대상", "이용대상")),
                        "eligibility_raw": first_by_keys(pairs, ("신청조건", "교육대상", "대상")),
                        "capacity": capacity_text or clean_text(capacity_total),
                        "capacity_total": capacity_total,
                        "capacity_current": capacity_current,
                        "capacity_remaining": (
                            max(capacity_total - capacity_current, 0)
                            if capacity_total is not None and capacity_current is not None
                            else None
                        ),
                        "room": venue_name,
                        "venue_name": venue_name,
                        "phone": first_by_keys(pairs, ("문의처", "연락처", "전화번호")),
                        "description": detail_description or raw_text,
                        "image_url": image_url,
                        "collection_category": "공공예약",
                        "domain_category": "교육·강좌",
                        "operator_type": "지자체/공공기관",
                        "source_group": "municipal_reservation",
                        "service_group": "공공강좌",
                        "service_group_policy": "locked",
                        "collection_type": "static_html",
                        "program_type": "강좌",
                        "application_type": (
                            "ONLINE_RESERVATION" if reservation_available else "INFO_ONLY"
                        ),
                        "application_method_raw": first_by_keys(
                            pairs, ("예약방식", "접수방법", "신청방법")
                        )
                        or "의왕시 통합예약 온라인 신청",
                        "reservation_available": reservation_available,
                        "raw_fields": {
                            "parser": "uiwang_reserve_category_detail",
                            "list_pairs": list_pairs,
                            "detail_pairs": detail_pairs,
                            "category": category,
                            "reservation_id": reservation_id,
                            "status_raw": status_raw,
                            "application_action": application_action,
                            "detail_fetched": detail_fetched,
                        },
                    }
                )
                category_rows += 1
                if per_target_limit > 0 and len(rows) >= per_target_limit:
                    stop_collection = True
                    break
            page += 1
        category_counts[category["title"]] = category_rows

    bounded_sample = per_target_limit > 0 and len(rows) >= per_target_limit
    accounted_declared_rows = len(seen_reservation_ids) + duplicate_rows
    if (
        categories
        and not bounded_sample
        and pages == declared_pages
        and accounted_declared_rows != declared_rows
        and not errors
    ):
        errors.append(
            "declared reservation count mismatch: "
            f"declared={declared_rows} accounted={accounted_declared_rows}"
        )
    if seen_reservation_ids and detail_pages != len(seen_reservation_ids) and not errors:
        errors.append(
            "detail collection incomplete: "
            f"details={detail_pages} reservations={len(seen_reservation_ids)}"
        )

    list_collection_complete = bool(categories) and not bounded_sample and not errors and (
        pages == declared_pages and accounted_declared_rows == declared_rows
    )
    detail_collection_complete = not errors and detail_pages == len(seen_reservation_ids)
    collection_complete = list_collection_complete and detail_collection_complete
    no_current_data = collection_complete and declared_rows == 0
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(
            1 for row in rows if row.get("reservation_available")
        ),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": collection_complete,
        "pagination_exhausted": list_collection_complete,
        "list_pagination_complete": list_collection_complete,
        "detail_collection_complete": detail_collection_complete,
        "fanout_cap_reached": bounded_sample,
        "recursion_depth": 0,
        "category_counts": category_counts,
        "status_counts": dict(status_counts),
        "categories": len(categories),
        "declared_pages": declared_pages,
        "declared_rows": declared_rows,
        "accounted_declared_rows": accounted_declared_rows,
        "duplicate_reservation_ids": duplicate_rows,
        "semantic_rejected_rows": rejected_rows,
        "skipped_aggregate_path": UIWANG_RESERVE_AGGREGATE_PATH,
        "main_discovery_pages": 1,
        "main_discovered_links": len(categories),
        "main_candidate_pages": len(categories),
        "main_discovery_complete": bool(categories),
        "configured_collection_error": "; ".join(dict.fromkeys(errors)),
        "no_current_data": no_current_data,
        "no_current_reason": "all discovered education categories are empty" if no_current_data else "",
    }
    return dedupe_rows(rows), "uiwang_reserve_category_detail", meta


def busan_science_image_url(item: dict[str, Any]) -> str:
    files = item.get("filelist") or []
    if not isinstance(files, list):
        return ""
    image_file = None
    for file_row in files:
        if not isinstance(file_row, dict):
            continue
        extension = clean_text(file_row.get("file_exe")).lower()
        if clean_text(file_row.get("main_file")) == "Y" and extension in {"jpg", "jpeg", "png", "gif", "webp"}:
            image_file = file_row
            break
    if image_file is None:
        for file_row in files:
            if not isinstance(file_row, dict):
                continue
            extension = clean_text(file_row.get("file_exe")).lower()
            if extension in {"jpg", "jpeg", "png", "gif", "webp"}:
                image_file = file_row
                break
    if not image_file:
        return ""
    path = clean_text(image_file.get("file_path"))
    name = clean_text(image_file.get("file_physical_name"))
    if not path or not name:
        return ""
    return urljoin("https://www.sciport.or.kr", path + name)


def busan_science_target_from_title(title: str) -> str:
    for match in re.finditer(r"\(([^()]*)\)", clean_text(title)):
        value = clean_text(match.group(1))
        if any(token in value for token in ("개월", "세", "초", "중", "고", "성인", "청소년")):
            return value
    return ""


def busan_science_schedule_from_description(text: str) -> str:
    stop_labels = (
        "교육장소",
        "교육대상",
        "교 육 비",
        "교육비",
        "모집인원",
        "접수일정",
        "교육문의",
        "문의",
    )
    for label in ("교육날짜", "교육일시", "교육시간", "교육일자", "교육일"):
        value = extract_korean_labeled_value(text, label, stop_labels)
        if value:
            return value[:200]
    return ""


def collect_busan_indivcurri(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": target.url, "X-Requested-With": "XMLHttpRequest"})
    endpoint = "https://www.sciport.or.kr/kor/CMS/IndivCurriMgr/list/default/std_A/MG/{page}.json"
    status_map = {"A": "예약예정", "B": "진행중", "C": "예약마감", "D": "종료"}

    rows: list[dict[str, Any]] = []
    max_count = 0
    pages = 0
    source_items = 0
    first_page_items = 0
    pagination_exhausted = False
    for page in range(1, max_pages + 1):
        response = s.post(endpoint.format(page=page), data={"mCode": "MN038"}, timeout=timeout, verify=True)
        response.raise_for_status()
        payload = response.json().get("result") or {}
        items = payload.get("event_info_list") or []
        max_count = int(payload.get("Max_cnt") or max_count or 0)
        if not items:
            pagination_exhausted = True
            break
        pages += 1
        source_items += len(items)
        if page == 1:
            first_page_items = len(items)
        for item in items:
            title = clean_text(item.get("curri_title"))
            if not title or "유의사항" in title:
                continue
            curri_seq = clean_text(item.get("curri_seq"))
            raw_url = urljoin(target.url, f"/kor/CMS/IndivCurriMgr/curriView.do?curri_seq={curri_seq}&mCode=MN038")
            start_date = clean_text(item.get("curri_s_date")).split(" ", 1)[0]
            end_date = clean_text(item.get("curri_e_date")).split(" ", 1)[0]
            fee = "유료" if clean_text(item.get("pay_type")) == "Y" else "무료"
            schedule = clean_text(item.get("class_time") or item.get("lecture_time") or item.get("curri_time"))
            target_text = clean_text(item.get("target_kind") or item.get("class_age") or item.get("curri_target"))
            if not target_text:
                target_text = busan_science_target_from_title(title)
            description = html_to_text(item.get("contents"))
            period = f"{start_date} ~ {end_date}" if start_date and end_date else ""
            if not schedule:
                schedule = busan_science_schedule_from_description(description) or period
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": clean_text(item.get("category_gb_f")) or "개인교육",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "reservation_available": clean_text(item.get("apply_yn")) == "Y",
                    "status": status_map.get(clean_text(item.get("state_f")), clean_text(item.get("state_f"))),
                    "fee": fee,
                    "period": period,
                    "schedule_raw": schedule,
                    "target": target_text,
                    "description": description,
                    "image_url": busan_science_image_url(item),
                    "raw_fields": {
                        "curri_seq": curri_seq,
                        "curri_s_date": item.get("curri_s_date"),
                        "curri_e_date": item.get("curri_e_date"),
                        "pay_type": item.get("pay_type"),
                        "state_f": item.get("state_f"),
                    },
                }
            )
        if max_count and source_items >= max_count:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1 or max_count > first_page_items,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "source_cap_reached": not pagination_exhausted,
        "recursion_depth": 0,
        "total_count": max_count,
        "source_items": source_items,
    }
    return dedupe_rows(rows), "busan_indivcurri_api", meta


GWACHEON_SCIENCE_ADDRESS = "경기도 과천시 상하벌로 110 국립과천과학관"
GWACHEON_SCIENCE_LOOKAHEAD_MONTHS = 18


def gwacheon_scipia_url_from_onclick(onclick: Any) -> str:
    text = clean_text(onclick)
    match = re.search(r"goPost\('([^']+)'\)", text)
    if match:
        return clean_text(match.group(1))
    match = re.search(r"ShowList\('([^']+)'\s*,\s*'([^']+)'\s*,\s*'([^']*)'\s*,\s*'([^']*)'\s*,\s*'([^']*)'\s*,\s*'([^']*)'\)", text)
    if match:
        course_cd, semester_cd, type_value, flag, owner_limit_flag, class_cd = match.groups()
        query = {
            "ACADEMY_CD": "ACD006",
            "CLASS_CD": class_cd,
            "COURSE_CD": course_cd,
            "SEMESTER_CD": semester_cd,
            "TYPE": type_value,
            "FLAG": flag,
            "OWNER_LIMIT_FLAG": owner_limit_flag,
        }
        return "https://www.sciencecenter.go.kr/scipia/schedules/" + course_cd + "?" + urlencode(query)
    return ""


def gwacheon_scipia_period_schedule(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    if text == "상시":
        return "상시", "상시"
    if re.search(r"\d{4}-\d{1,2}-\d{1,2}\s*~\s*\d{4}-\d{1,2}-\d{1,2}", text):
        return sb_normalize_range(text), ""
    if re.search(r"\d{4}-\d{1,2}-\d{1,2}", text):
        return sb_normalize_range(text), text
    if re.search(r"\d{1,2}[.]\d{1,2}\s*~\s*\d{1,2}[.]\d{1,2}", text):
        matches = re.findall(r"(\d{1,2})[.](\d{1,2})", text)
        if len(matches) >= 2:
            year = datetime.now().year
            start = f"{year}-{int(matches[0][0]):02d}-{int(matches[0][1]):02d}"
            end = f"{year}-{int(matches[1][0]):02d}-{int(matches[1][1]):02d}"
            return f"{start} ~ {end}", ""
    return text, text


def collect_gwacheon_scipia(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_url = "https://www.sciencecenter.go.kr/edu/user/edu/eduList.do"
    api_url = "https://www.sciencecenter.go.kr/edu/user/edu/eduList.json"
    s.get(list_url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    pages = 0
    total_count = 0
    current = datetime.now()
    try:
        configured_lookahead = int(
            target.extra.get("lookahead_months")
            or GWACHEON_SCIENCE_LOOKAHEAD_MONTHS
        )
    except (TypeError, ValueError):
        configured_lookahead = GWACHEON_SCIENCE_LOOKAHEAD_MONTHS
    lookahead_months = max(1, min(configured_lookahead, 36))
    scanned_months = min(max(1, max_pages), lookahead_months)
    scope_complete = max_pages >= lookahead_months
    for offset in range(scanned_months):
        month_index = current.month + offset - 1
        year = current.year + month_index // 12
        month = month_index % 12 + 1
        response = s.post(
            api_url,
            data={
                "srchYear": str(year),
                "srchMonth": f"{month:02d}",
                "srchCtgry": "0",
                "srchCtgry2": "0",
                "srchCtgry3": "0",
            },
            headers={
                "Referer": list_url,
                "X-Requested-With": "XMLHttpRequest",
                "Accept": "application/json, text/javascript, */*; q=0.01",
            },
            timeout=timeout,
        )
        response.raise_for_status()
        data = response.json()
        items = data.get("lctreList") or []
        total_count += len(items)
        pages += 1
        for item in items:
            title = clean_text(item.get("eduNm"))
            if not title or is_low_value_title(title):
                continue
            edu_seq = clean_text(item.get("eduSeq"))
            raw_url = f"https://www.sciencecenter.go.kr/edu/user/edu/eduView.do?eduSeq={edu_seq}" if edu_seq else list_url
            status = clean_text(item.get("addStatusNm"))
            fee_amount = item.get("fee")
            fee = "무료" if fee_amount in (None, "", 0, "0") else f"{int(fee_amount):,}원" if str(fee_amount).isdigit() else clean_text(fee_amount)
            period = " ~ ".join(part for part in [clean_text(item.get("eduPeriodBegin")), clean_text(item.get("eduPeriodEnd"))] if part)
            time_range = " ~ ".join(part for part in [format_hhmm(item.get("startTm")), format_hhmm(item.get("endTm"))] if part)
            schedule_raw = clean_text(" ".join(part for part in [period, time_range] if part))
            apply_period = " ~ ".join(
                part
                for part in [format_yyyymmdd(clean_text(item.get("rceptPeriodBegin"))[:8]), format_yyyymmdd(clean_text(item.get("rceptPeriodEnd"))[:8])]
                if part
            )
            target_text = clean_text(
                " ".join(part for part in [item.get("addTargetsStr"), item.get("targetEtc")] if clean_text(part))
            )
            venue = clean_text(item.get("addrDetail") or item.get("addrEtc") or item.get("roomNm"))
            address = clean_text(" ".join(part for part in [item.get("addr"), item.get("addrDetail")] if clean_text(part)))
            capacity_total = parse_capacity_number(item.get("personnel"))
            capacity_current = parse_capacity_number(item.get("rceptCnt"))
            capacity = f"{capacity_current}/{capacity_total}" if capacity_current is not None and capacity_total is not None else clean_text(capacity_total)
            image_url = ""
            if clean_text(item.get("imgUseYn")) == "Y" and clean_text(item.get("imgRename")):
                image_url = "https://www.sciencecenter.go.kr/edu/DATA/upload/lctreThum/" + clean_text(item.get("imgRename"))
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "branch_code": target.provider,
                "category": clean_text(item.get("detailCtgryNm") or item.get("eduCtgryNm")),
                "collection_category": "박물관/과학관",
                "domain_category": "박물관/과학관",
                "source_group": "museum_science",
                "operator_type": "국립/공공기관",
                "collection_type": "json_api",
                "raw_url": raw_url,
                "application_url": raw_url,
                "application_type": "ONLINE_RESERVATION",
                "reservation_available": "접수중" in status,
                "status": status,
                "fee": fee,
                "period": period,
                "schedule_raw": schedule_raw,
                "apply_period": apply_period,
                "target": target_text,
                "room": venue,
                "venue_name": venue,
                "venue_address": address or GWACHEON_SCIENCE_ADDRESS,
                "address": address or GWACHEON_SCIENCE_ADDRESS,
                "description": html_to_text(item.get("cn"))[:1000],
                "application_method_raw": clean_text(item.get("lctreTypeNm") or "온라인 예약"),
                "capacity": capacity,
                "capacity_total": capacity_total,
                "capacity_current": capacity_current,
                "waitlist_total": parse_capacity_number(item.get("waitCnt")),
                "phone": clean_text(item.get("tel")),
                "instructor": clean_text(item.get("instrctrNm")),
                "image_url": image_url,
                "program_type": "강좌",
                "raw_fields": {
                    "parser": "gwacheon_edu_list_json",
                    "api_url": api_url,
                    "eduSeq": edu_seq,
                    "eduCtgryNm": clean_text(item.get("eduCtgryNm")),
                    "detailCtgryNm": clean_text(item.get("detailCtgryNm")),
                    "rceptPeriodBegin": clean_text(item.get("rceptPeriodBegin")),
                    "rceptPeriodEnd": clean_text(item.get("rceptPeriodEnd")),
                },
            }
            rows.append(row)

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": scanned_months > 1,
        "pagination_complete": scope_complete,
        "pagination_exhausted": scope_complete,
        "source_cap_reached": not scope_complete,
        "recursion_depth": 0,
        "lookahead_months": lookahead_months,
        "time_window_complete": scope_complete,
        "total_source_rows": total_count,
        "no_current_data": scope_complete and not rows,
        "no_current_reason": (
            "no_current_gwacheon_science_programs"
            if scope_complete and not rows
            else ""
        ),
    }
    return dedupe_rows(rows), "gwacheon_edu_list_json", meta


def values_after_line(lines: list[str], label: str, stop_labels: set[str]) -> str:
    if label not in lines:
        return ""
    index = lines.index(label) + 1
    values: list[str] = []
    while index < len(lines) and lines[index] not in stop_labels:
        values.append(lines[index])
        index += 1
    return clean_text(" ".join(values))


def labeled_span_value(node: BeautifulSoup, selector: str, label: str = "") -> str:
    target = node.select_one(selector)
    if not target:
        return ""
    value = clean_text(target.get_text(" ", strip=True))
    if label and value.startswith(label):
        value = clean_text(value[len(label):].lstrip(":："))
    return value


def gjcf_detail_target(description: str) -> str:
    match = re.search(
        r"(?:\uad00\ub78c)?\ub300\uc0c1\s*[:\uff1a]\s*(.{1,120}?)(?=\s+(?:\uc77c\uc2dc|\uc7a5\uc18c|\ub0b4\uc6a9|\ubb38\uc758)\s*[:\uff1a]|$)",
        clean_text(description),
    )
    return clean_text(match.group(1)) if match else ""


def cnc_culture_pairs(scope: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if scope is None or not hasattr(scope, "select"):
        return pairs
    for item in scope.select("ul.listbox > li"):
        label_node = item.find("b")
        label = clean_text(
            label_node.get_text(" ", strip=True) if label_node else ""
        )
        if not label:
            continue
        value = clean_text(item.get_text(" ", strip=True))
        if value.startswith(label):
            value = clean_text(value[len(label) :])
        if value:
            pairs[label] = value
    return pairs


def collect_cnc_culture_events(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    list_url = parsed._replace(query="", fragment="").geturl()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    detail_attempts = 0
    detail_errors = 0
    expired_count = 0
    pagination_exhausted = False
    pagination_detected = False
    seen_ids: set[str] = set()
    seen_signatures: set[tuple[str, ...]] = set()
    today = datetime.now().astimezone().date()

    for page in range(1, max(1, max_pages) + 1):
        current_url = url_with_query(list_url, {"GotoPage": page})
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        anchors = [
            anchor
            for anchor in soup.select(
                "a[href*='mode=V'][href*='mng_no=']"
            )
            if anchor.select_one(".listcont .listbox")
        ]
        if not anchors:
            pagination_exhausted = True
            break

        signature = tuple(clean_text(anchor.get("href")) for anchor in anchors)
        if signature in seen_signatures:
            pagination_exhausted = True
            break
        seen_signatures.add(signature)

        page_candidates: list[dict[str, Any]] = []
        page_expired = 0
        for anchor in anchors:
            raw_url = normalize_link(current_url, anchor.get("href"))
            query = parse_qs(urlparse(raw_url).query)
            event_id = clean_text((query.get("mng_no") or [""])[0])
            if event_id and event_id in seen_ids:
                continue
            if event_id:
                seen_ids.add(event_id)

            box = anchor.select_one(".listbox")
            info_items = box.select(":scope > ul > li") if box else []
            image = anchor.select_one("img")
            title = clean_text(image.get("alt") if image else "")
            region = ""
            if info_items:
                region_node = info_items[0].find("span")
                region = clean_text(
                    region_node.get_text(" ", strip=True)
                    if region_node
                    else ""
                )
                if not title:
                    title = clean_text(
                        info_items[0].get_text(" ", strip=True)
                    )
                    if region and title.startswith(region):
                        title = clean_text(title[len(region) :])
            if not title:
                continue

            category_node = anchor.select_one(".cate")
            category = clean_text(
                category_node.get_text(" ", strip=True)
                if category_node
                else ""
            ) or "문화행사"
            date_time = clean_text(
                info_items[1].get_text(" ", strip=True)
                if len(info_items) > 1
                else ""
            )
            period = normalize_mixed_date_range(date_time)
            time_match = re.search(r"\b(\d{1,2}:\d{2})\b", date_time)
            schedule_raw = (
                clean_text(time_match.group(1))
                if time_match
                else "시간 별도 안내"
            )
            place = clean_text(
                info_items[2].get_text(" ", strip=True)
                if len(info_items) > 2
                else ""
            )
            _, end_date = parse_date_range(period)
            if end_date and end_date < today:
                expired_count += 1
                page_expired += 1
                continue

            page_candidates.append(
                {
                    "event_id": event_id,
                    "title": title,
                    "region": region,
                    "category": category,
                    "period": period,
                    "schedule_raw": schedule_raw,
                    "place": place,
                    "raw_url": raw_url,
                    "image_url": normalize_link(
                        current_url,
                        image.get("src") if image else None,
                    ),
                }
            )

        if anchors and page_expired == len(anchors):
            pagination_exhausted = True
            break

        for candidate in page_candidates:
            pairs: dict[str, str] = {}
            description = ""
            application_url = ""
            if detail_attempts < max(0, detail_limit):
                detail_attempts += 1
                try:
                    detail_soup = fetch_soup(
                        s,
                        candidate["raw_url"],
                        timeout=timeout,
                    )
                    detail_pages += 1
                    detail_root = detail_soup.select_one("#contents") or detail_soup
                    pairs = cnc_culture_pairs(detail_root)
                    description = clean_text(
                        detail_root.get_text(" ", strip=True)
                    )[:2000]
                    home_link = next(
                        (
                            link
                            for link in detail_root.select("a[href]")
                            if "홈페이지" in clean_text(
                                link.get_text(" ", strip=True)
                            )
                        ),
                        None,
                    )
                    application_url = normalize_link(
                        candidate["raw_url"],
                        home_link.get("href") if home_link else None,
                    )
                except Exception as exc:
                    detail_errors += 1
                    logger.debug(
                        "CNC culture detail fetch failed %s: %s",
                        candidate["raw_url"],
                        exc,
                    )

            free_type = clean_text(pairs.get("유/무료 여부"))
            cost = clean_text(pairs.get("비용"))
            fee = (
                "무료"
                if "무료" in free_type and "유료" not in free_type
                else cost or free_type or "별도 안내"
            )
            title = clean_text(pairs.get("행사명")) or candidate["title"]
            category = clean_text(pairs.get("분야")) or candidate["category"]
            period = normalize_mixed_date_range(
                pairs.get("기간") or candidate["period"]
            )
            schedule_raw = (
                clean_text(pairs.get("시작 시간"))
                or candidate["schedule_raw"]
            )
            place = clean_text(pairs.get("장소")) or candidate["place"]
            target_text = clean_text(pairs.get("대상")) or "전체"
            status = (
                "OPEN"
                if not parse_date_range(period)[1]
                or parse_date_range(period)[1] >= today
                else "CLOSED"
            )
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": candidate["event_id"]
                    or stable_course_id(
                        target.provider,
                        candidate["raw_url"],
                        title,
                        place,
                    ),
                    "title": title,
                    "branch": candidate["region"]
                    or target.branch
                    or "충청남도",
                    "category": category,
                    "raw_url": candidate["raw_url"],
                    "application_url": application_url,
                    "application_type": (
                        "ONLINE_RESERVATION"
                        if application_url
                        else "INFO_ONLY"
                    ),
                    "reservation_available": bool(application_url),
                    "status": status,
                    "fee": fee,
                    "period": period,
                    "apply_period": "",
                    "schedule_raw": schedule_raw,
                    "target": target_text,
                    "venue_name": place or target.branch or "충청남도",
                    "address": place,
                    "capacity": clean_text(pairs.get("인원")),
                    "organizer": clean_text(pairs.get("주최/주관")),
                    "phone": clean_text(pairs.get("관련 문의")),
                    "description": description or title,
                    "image_url": candidate["image_url"],
                    "raw_fields": {
                        "parser": "cnc_culture_list_detail",
                        "source_page": page,
                        "detail_pairs": pairs,
                    },
                }
            )

        pagination_detected = pagination_detected or bool(
            soup.select("a[href*='GotoPage=']")
        )

    details_complete = (
        detail_attempts == len(rows)
        and detail_pages == detail_attempts
        and detail_errors == 0
    )
    snapshot_complete = pagination_exhausted and details_complete
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_errors": detail_errors,
        "discovered_links": len(seen_ids),
        "expired_count": expired_count,
        "reservation_discovery_links": sum(
            bool(clean_text(row.get("application_url"))) for row in rows
        ),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_exhausted,
        "detail_collection_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "no_current_data": snapshot_complete and not rows,
        "no_current_reason": (
            "official Chungnam culture list has no current events"
            if snapshot_complete and not rows
            else ""
        ),
    }
    return dedupe_rows(rows), "cnc_culture_list_detail", meta


HFCT_PROGRAM_PAGE_SIZE = 9


def hfct_program_pairs(scope: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if scope is None or not hasattr(scope, "select"):
        return pairs
    for item in scope.select("ul.info_list > li, ul.info > li"):
        label_node = item.select_one(".tit")
        value_node = item.select_one(".txt")
        label = clean_text(
            label_node.get_text(" ", strip=True) if label_node else ""
        )
        value = clean_text(
            value_node.get_text(" ", strip=True) if value_node else ""
        )
        if label and value:
            pairs[label] = value
    return pairs


def collect_hfct_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    detail_attempts = 0
    detail_errors = 0
    source_rows = 0
    expired_count = 0
    pagination_exhausted = False
    seen_page_signatures: set[tuple[str, ...]] = set()
    seen_urls: set[str] = set()
    today = datetime.now().astimezone().date()

    for page in range(1, max(1, max_pages) + 1):
        current_url = url_with_query(
            target.url,
            {
                "b_list": HFCT_PROGRAM_PAGE_SIZE,
                "nPage": page,
            },
        )
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        items = [
            item
            for item in soup.select("li.item")
            if item.select_one(".pg_tit a[href*='edu.do'][href*='list_no=']")
        ]
        if not items:
            pagination_exhausted = True
            break

        signature = tuple(
            clean_text(
                item.select_one(".pg_tit a").get("href")
                if item.select_one(".pg_tit a")
                else ""
            )
            for item in items
        )
        if signature in seen_page_signatures:
            pagination_exhausted = True
            break
        seen_page_signatures.add(signature)
        source_rows += len(items)

        for item in items:
            title_link = item.select_one(
                ".pg_tit a[href*='edu.do'][href*='list_no=']"
            )
            title = clean_text(
                title_link.get_text(" ", strip=True) if title_link else ""
            )
            raw_url = normalize_link(
                current_url,
                title_link.get("href") if title_link else None,
            )
            if not title or not raw_url or raw_url in seen_urls:
                continue
            seen_urls.add(raw_url)

            pairs = hfct_program_pairs(item)
            period = normalize_mixed_date_range(pairs.get("일시"))
            _, end_date = parse_date_range(period)
            if end_date is not None and end_date < today:
                expired_count += 1
                continue

            category_node = item.select_one(".pro_tp")
            category = clean_text(
                category_node.get_text(" ", strip=True)
                if category_node
                else ""
            ) or "문화예술교육"
            status_node = item.select_one(".state")
            status_raw = clean_text(
                status_node.get_text(" ", strip=True) if status_node else ""
            )
            place = clean_text(pairs.get("장소"))
            target_text = clean_text(pairs.get("참여대상")) or "전체"
            schedule_raw = "시간 별도 안내"
            fee = "별도 안내"
            phone = ""
            description = ""
            application_url = ""

            if detail_attempts < max(0, detail_limit):
                detail_attempts += 1
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_root = detail_soup.select_one(".pro_view_wp")
                    detail_pairs = hfct_program_pairs(detail_root or detail_soup)
                    period = normalize_mixed_date_range(
                        detail_pairs.get("일시") or period
                    )
                    schedule_raw = (
                        clean_text(detail_pairs.get("시간")) or schedule_raw
                    )
                    place = clean_text(detail_pairs.get("장소")) or place
                    target_text = (
                        clean_text(detail_pairs.get("참여대상")) or target_text
                    )
                    phone = clean_text(detail_pairs.get("문의"))
                    description_node = detail_soup.select_one(
                        ".pro_view_wp .view_bd"
                    )
                    description = clean_text(
                        description_node.get_text(" ", strip=True)
                        if description_node
                        else ""
                    )[:2000]
                    apply_link = next(
                        (
                            link
                            for link in detail_soup.select(
                                ".pro_view_wp a.app_btn[href]"
                            )
                            if "신청" in clean_text(
                                link.get_text(" ", strip=True)
                            )
                        ),
                        None,
                    )
                    candidate_url = normalize_link(
                        raw_url,
                        apply_link.get("href") if apply_link else None,
                    )
                    if candidate_url and candidate_url != raw_url:
                        application_url = candidate_url
                except Exception as exc:
                    detail_errors += 1
                    logger.debug(
                        "HFCT program detail fetch failed %s: %s",
                        raw_url,
                        exc,
                    )

            image = item.select_one(".img_box img[src]")
            image_url = normalize_link(
                current_url,
                image.get("src") if image else None,
            )
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(
                    target.provider,
                    raw_url,
                    title,
                    place,
                ),
                "title": title,
                "branch": target.branch or "화순군문화관광재단",
                "category": category,
                "raw_url": raw_url,
                "application_url": application_url,
                "application_type": (
                    "ONLINE_RESERVATION" if application_url else "INFO_ONLY"
                ),
                "reservation_available": bool(application_url),
                "status": normalize_status(status_raw) or status_raw or "OPEN",
                "fee": fee,
                "period": period,
                "apply_period": normalize_mixed_date_range(
                    pairs.get("신청기간")
                ),
                "schedule_raw": schedule_raw,
                "target": target_text,
                "venue_name": place or target.branch or "화순군",
                "address": place,
                "phone": phone,
                "image_url": image_url,
                "description": description or clean_text(
                    item.get_text(" ", strip=True)
                ),
                "raw_fields": {
                    "parser": "hfct_program_list_detail",
                    "source_page": page,
                    "status_raw": status_raw,
                    "list_pairs": pairs,
                },
            }
            rows.append(
                {
                    key: value
                    for key, value in row.items()
                    if value not in (None, "", [], {})
                }
            )

        if len(items) < HFCT_PROGRAM_PAGE_SIZE:
            pagination_exhausted = True
            break

    details_complete = (
        detail_attempts == len(rows)
        and detail_pages == detail_attempts
        and detail_errors == 0
    )
    snapshot_complete = pagination_exhausted and details_complete
    no_current_data = snapshot_complete and not rows
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_errors": detail_errors,
        "source_rows": source_rows,
        "expired_count": expired_count,
        "current_count": len(rows),
        "discovered_links": len(seen_urls),
        "reservation_discovery_links": sum(
            bool(clean_text(row.get("application_url"))) for row in rows
        ),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1,
        "pagination_complete": pagination_exhausted,
        "detail_collection_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": (
            "all official HFCT programs have ended" if no_current_data else ""
        ),
    }
    return dedupe_rows(rows), "hfct_program_list_detail", meta


def collect_gjcf_calendar(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    pagination_exhausted = False
    seen_urls: set[str] = set()

    for page in range(1, max_pages + 1):
        current_url = url_with_query(target.url, {"PageIndex": page})
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        items = soup.select("ul.calendarContentsUl > li")
        pagination_detected = pagination_detected or bool(
            soup.select("a[onclick*='pf_LinkPage']")
        )
        if not items:
            pagination_exhausted = True
            break

        page_rows = 0
        for item in items:
            title_link = item.select_one(
                ".letterBox .ph1 a[href*='/calendar/'][href*='/view.do']"
            ) or item.select_one("a[href*='/calendar/'][href*='/view.do']")
            title = clean_text(
                title_link.get_text(" ", strip=True) if title_link else ""
            )
            raw_url = normalize_link(
                current_url, title_link.get("href") if title_link else None
            )
            if not title or not raw_url or raw_url in seen_urls:
                continue
            seen_urls.add(raw_url)

            category_node = item.select_one(".letterBox .ph1 .cate")
            category = clean_text(
                category_node.get_text(" ", strip=True) if category_node else ""
            ) or "\ubb38\ud654\ud589\uc0ac"
            place_node = item.select_one(".boTitle .place")
            place = clean_text(
                place_node.get_text(" ", strip=True) if place_node else ""
            )
            period_node = item.select_one(".boTitle .date")
            period = normalize_mixed_date_range(
                period_node.get_text(" ", strip=True) if period_node else ""
            )
            image_node = item.select_one(".imgBox")
            image_style = clean_text(image_node.get("style") if image_node else "")
            image_match = re.search(r"url\(\s*['\"]?([^)'\"\s]+)", image_style)
            image_url = (
                urljoin(current_url, image_match.group(1))
                if image_match
                else ""
            )
            description = ""
            fee = "\ubcc4\ub3c4 \uc548\ub0b4"
            schedule_raw = "\uc2dc\uac04 \ubcc4\ub3c4 \uc548\ub0b4"
            target_text = "\uc804\uccb4"
            organizer = ""
            phone = ""

            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_tables(detail_soup)
                    detail_node = detail_soup.select_one(".detailViewContentsBox")
                    description = clean_text(
                        detail_node.get_text(" ", strip=True)
                        if detail_node
                        else ""
                    )[:2000]
                    title = clean_text(detail_pairs.get("\ud589\uc0ac\uba85")) or title
                    place = clean_text(
                        detail_pairs.get("\ud589\uc0ac\uc7a5\uc18c")
                        or detail_pairs.get("\uacf5\uc5f0\uc7a5\uc18c")
                        or place
                    )
                    period = normalize_mixed_date_range(
                        detail_pairs.get("\ud589\uc0ac\uae30\uac04") or period
                    )
                    schedule_raw = clean_text(
                        detail_pairs.get("\uad00\ub78c\uc2dc\uac04")
                        or detail_pairs.get("\ud589\uc0ac\uc77c\uc2dc")
                    ) or schedule_raw
                    fee = clean_text(
                        detail_pairs.get("\uad00\ub78c\ub8cc")
                        or detail_pairs.get("\uc785\uc7a5\ub8cc")
                    ) or fee
                    target_text = (
                        clean_text(
                            detail_pairs.get("\uad00\ub78c\ub300\uc0c1")
                            or detail_pairs.get("\ud589\uc0ac\ub300\uc0c1")
                        )
                        or gjcf_detail_target(description)
                        or target_text
                    )
                    organizer = clean_text(
                        detail_pairs.get("\uc8fc\ucd5c/\uc8fc\uad00")
                    )
                    phone = clean_text(detail_pairs.get("\ubb38\uc758\uc804\ud654"))
                except Exception as exc:
                    logger.debug("GJCF calendar detail fetch failed %s: %s", raw_url, exc)

            _, end_date = parse_date_range(period)
            status = (
                "CLOSED"
                if end_date and end_date < datetime.now().astimezone().date()
                else "OPEN"
            )
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(
                        target.provider, raw_url, title, place
                    ),
                    "title": title,
                    "branch": target.branch or "\uad11\uc8fc\ubb38\ud654\uc7ac\ub2e8",
                    "category": category,
                    "raw_url": raw_url,
                    "status": status,
                    "fee": fee,
                    "period": period,
                    "apply_period": "",
                    "schedule_raw": schedule_raw,
                    "target": target_text,
                    "venue_name": place,
                    "address": place,
                    "image_url": image_url,
                    "description": description,
                    "organizer": organizer,
                    "phone": phone,
                    "raw_fields": {
                        "parser": "gjcf_calendar",
                        "source_page": page,
                    },
                }
            )
            page_rows += 1
        if page_rows == 0:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_urls),
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_exhausted,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "gjcf_calendar", meta


def dmgj_detail_target(description: str) -> str:
    for label in ("\uad00\ub78c\ub300\uc0c1", "\ub300\uc0c1", "\uad00\ub78c"):
        match = re.search(
            rf"{label}\s*[:\uff1a]\s*(.{{1,120}}?)(?=\s+(?:\uc77c\uc2dc|\uc7a5\uc18c|\uc6b4\uc601|\ub0b4\uc6a9|\ubb38\uc758)\s*[:\uff1a]|$)",
            clean_text(description),
        )
        if match:
            return clean_text(match.group(1))
    return ""


def collect_dmgj_events(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_exhausted = False
    expired_rows = 0
    seen_page_signatures: set[tuple[str, ...]] = set()
    seen_urls: set[str] = set()

    for page in range(1, max_pages + 1):
        current_url = url_with_query(target.url, {"nPage": page})
        soup = fetch_soup(s, current_url, timeout=timeout)
        items = soup.select(
            "ul.grid-view > li > a[href*='event.es'][href*='act=view'][href*='seq=']"
        )
        pages += 1
        if not items:
            pagination_exhausted = True
            break
        signature = tuple(clean_text(item.get("href")) for item in items)
        if signature in seen_page_signatures:
            pagination_exhausted = True
            break
        seen_page_signatures.add(signature)
        page_expired_rows = 0

        for item in items:
            title_node = item.select_one(".info_tit")
            title = clean_text(
                title_node.get_text(" ", strip=True) if title_node else ""
            )
            raw_url = normalize_link(current_url, item.get("href"))
            if not title or not raw_url or raw_url in seen_urls:
                continue
            seen_urls.add(raw_url)
            category_node = item.select_one(".list_cate")
            category = clean_text(
                category_node.get_text(" ", strip=True) if category_node else ""
            ) or "\ubb38\ud654\ud589\uc0ac"
            status_node = item.select_one(".list_label")
            status_raw = clean_text(
                status_node.get_text(" ", strip=True) if status_node else ""
            )
            status = (
                "OPEN"
                if status_raw == "D-DAY"
                or any(
                    token in status_raw
                    for token in ("\uc9c4\ud589\uc911", "\uc784\ubc15", "\uc608\uc815")
                )
                else normalize_status(status_raw)
            )
            place_node = item.select_one(".place")
            place = clean_text(
                place_node.get_text(" ", strip=True) if place_node else ""
            )
            period_node = item.select_one(".period")
            period = normalize_mixed_date_range(
                period_node.get_text(" ", strip=True) if period_node else ""
            )
            _, list_end_date = parse_date_range(period)
            if (
                list_end_date is not None
                and list_end_date < datetime.now().astimezone().date()
            ):
                expired_rows += 1
                page_expired_rows += 1
                continue
            image = item.select_one("img")
            image_src = clean_text(image.get("src") if image else "")
            image_url = urljoin(current_url, image_src) if image_src else ""
            schedule_raw = "\uc2dc\uac04 \ubcc4\ub3c4 \uc548\ub0b4"
            fee = "\ubcc4\ub3c4 \uc548\ub0b4"
            target_text = "\uc804\uccb4"
            phone = ""
            organizer = ""
            description = ""

            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    pairs = pairs_from_definition_lists(detail_soup)
                    detail_title = detail_soup.select_one(".detail_tit")
                    title = clean_text(
                        detail_title.get_text(" ", strip=True)
                        if detail_title
                        else ""
                    ) or title
                    period = normalize_mixed_date_range(
                        pairs.get("\uae30\uac04") or period
                    )
                    schedule_raw = clean_text(pairs.get("\uc2dc\uac04")) or schedule_raw
                    place = clean_text(pairs.get("\uc7a5\uc18c")) or place
                    fee = clean_text(
                        pairs.get("\uc694\uae08\uc815\ubcf4")
                        or pairs.get("\uc694\uae08")
                    ) or fee
                    phone = clean_text(pairs.get("\uc5f0\ub77d\ucc98"))
                    organizer = clean_text(pairs.get("\uc8fc\ucd5c"))
                    detail_node = detail_soup.select_one(".detail_con")
                    description = clean_text(
                        detail_node.get_text(" ", strip=True)
                        if detail_node
                        else ""
                    )[:2000]
                    target_text = dmgj_detail_target(description) or target_text
                except Exception as exc:
                    logger.debug("DMGJ event detail fetch failed %s: %s", raw_url, exc)

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(
                        target.provider, raw_url, title, place
                    ),
                    "title": title,
                    "branch": target.branch or "\ub514\uc5b4\ub9c8\uc774\uad11\uc8fc",
                    "category": category,
                    "raw_url": raw_url,
                    "status": status or "OPEN",
                    "fee": fee,
                    "period": period,
                    "apply_period": "",
                    "schedule_raw": schedule_raw,
                    "target": target_text,
                    "venue_name": place,
                    "address": place,
                    "image_url": image_url,
                    "description": description,
                    "phone": phone,
                    "organizer": organizer,
                    "raw_fields": {
                        "parser": "dmgj_event_list_detail",
                        "source_page": page,
                        "status_raw": status_raw,
                    },
                }
            )
        if page_expired_rows == len(items):
            pagination_exhausted = True
            break
        if len(items) < 20:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_urls),
        "expired_count": expired_rows,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1 or not pagination_exhausted,
        "pagination_complete": pagination_exhausted,
        "no_current_data": pagination_exhausted and not rows,
        "no_current_reason": (
            "no_current_dmgj_events"
            if pagination_exhausted and not rows
            else ""
        ),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "dmgj_event_list_detail", meta


def honam_bio_text_after_marker(text: str, marker: str) -> str:
    lines = [clean_text(line) for line in text.splitlines()]
    for index, line in enumerate(lines):
        if marker not in line:
            continue
        value = clean_text(line.split(marker, 1)[-1].lstrip("):： "))
        if value:
            return value
        for next_line in lines[index + 1 : index + 4]:
            if next_line:
                return next_line
    match = re.search(re.escape(marker) + r"\s*[\):：]*\s*([^\n\r*]+)", text)
    return clean_text(match.group(1)) if match else ""


def honam_bio_normalize_period(value: str) -> str:
    text = clean_text(value).replace("\u2018", "").replace("\u2019", "").replace("`", "")
    slash_dates = re.findall(r"(?:(\d{2,4})[./])?(\d{1,2})/(\d{1,2})", text)
    if slash_dates:
        fallback_year = datetime.now().year
        dates: list[str] = []
        for year_text, month_text, day_text in slash_dates:
            year = int(year_text) if year_text else fallback_year
            if year < 100:
                year += 2000
            dates.append(f"{year:04d}-{int(month_text):02d}-{int(day_text):02d}")
        return " ~ ".join(dates) if len(dates) > 1 else dates[0]
    match = re.search(r"(\d{2,4})[.\uB144]\s*(\d{1,2})[.\uC6D4]\s*(\d{1,2})", text)
    if not match:
        return normalize_mixed_date_range(text) or text
    year = int(match.group(1))
    if year < 100:
        year += 2000
    return f"{year:04d}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"


def honam_bio_description(text: str) -> str:
    source = clean_text(text)
    detail_marker = "\uC0C1\uC138\uC124\uBA85"
    if detail_marker in source:
        source = source.split(detail_marker, 1)[-1]
    for stop in ("\uC774\uC6A9\uC694\uAE08", "\uC608\uC57D\uC548\uB0B4", "\uD658\uBD88\uC548\uB0B4", "\uBB38\uC758\uCC98", "\uC7A5\uC18C\uC548\uB0B4"):
        if stop in source:
            source = source.split(stop, 1)[0]
    return clean_text(source)[:2000]


def collect_honam_bio_resources(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_url = "https://resve.hnibr.re.kr/front/edu/eduFrontList.do"
    branch_name = "\uad6d\ub9bd\ud638\ub0a8\uad8c\uc0dd\ubb3c\uc790\uc6d0\uad00"
    branch_address = "\uc804\ub77c\ub0a8\ub3c4 \ubaa9\ud3ec\uc2dc \uace0\ud558\ub3c4\uc548\uae38 99"
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    detail_attempts = 0
    detail_errors = 0
    expired_count = 0
    pagination_exhausted = False
    seen_signatures: set[tuple[str, ...]] = set()
    seen_ids: set[str] = set()
    today = datetime.now().astimezone().date()
    for page in range(1, max_pages + 1):
        soup = fetch_soup(s, f"{list_url}?menu_id=00000440&pageIndex={page}", timeout=timeout)
        items = [
            item for item in soup.select("ul.lst.type_card > li")
            if "등록된 교육프로그램이 없습니다" not in clean_text(
                item.get_text(" ", strip=True)
            )
        ]
        pages += 1
        if not items:
            pagination_exhausted = True
            break
        signature = tuple(
            clean_text((item.find("a") or {}).get("onclick"))
            for item in items
        )
        if signature in seen_signatures:
            pagination_exhausted = True
            break
        seen_signatures.add(signature)

        archived_page = True
        for item in items:
            status = labeled_span_value(item, ".type1")
            apply_period = normalize_mixed_date_range(
                labeled_span_value(item, ".n2", "접수기간")
            )
            _, apply_end = parse_date_range(apply_period)
            if "마감" not in status or not apply_end or apply_end >= today:
                archived_page = False
                break
        if archived_page:
            expired_count += len(items)
            pagination_exhausted = True
            break

        for item in items:
            title = labeled_span_value(item, ".tit")
            if not title or is_low_value_title(title):
                continue
            onclick = clean_text((item.find("a") or {}).get("onclick"))
            match = re.search(r"fn_detail\('([^']+)'\)", onclick)
            edu_id = match.group(1) if match else ""
            if edu_id and edu_id in seen_ids:
                continue
            if edu_id:
                seen_ids.add(edu_id)
            raw_url = (
                f"https://resve.hnibr.re.kr/index.do?menu_id=00000440&menu_link=front/edu/eduFrontDetail.do&edu_id={edu_id}"
                if edu_id
                else target.url
            )
            image = item.find("img")
            image_url = normalize_link(target.url, image.get("src") if image else None)
            status = labeled_span_value(item, ".type1")
            fee = labeled_span_value(item, ".type2") or "별도 안내"
            row = {
                "provider": target.provider,
                "provider_course_id": edu_id or stable_course_id(
                    target.provider,
                    raw_url,
                    title,
                    target.branch,
                ),
                "title": title,
                "branch": branch_name,
                "address": branch_address,
                "category": "생물·생태 체험",
                "raw_url": raw_url,
                "application_url": raw_url if "접수중" in status else "",
                "status": status,
                "fee": fee,
                "period": "",
                "apply_period": normalize_mixed_date_range(
                    labeled_span_value(item, ".n2", "접수기간")
                ),
                "schedule_raw": labeled_span_value(item, ".n3", "교육시간") or "시간 별도 안내",
                "target": labeled_span_value(item, ".n1", "이용대상") or "전체",
                "application_method_raw": labeled_span_value(item, ".n4", "접수방법"),
                "image_url": image_url,
                "description": "",
                "raw_fields": {"edu_id": edu_id, "parser": "honam_bio_card"},
            }
            if edu_id and detail_pages < max(0, detail_limit):
                detail_attempts += 1
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_definition_lists(detail_soup)
                    detail_pairs.update(pairs_from_tables(detail_soup))
                    detail_text_raw = detail_soup.get_text("\n", strip=True)
                    detail_text = clean_text(detail_text_raw)
                    detail_title = first_title_candidate(detail_soup)
                    if detail_title and len(detail_title) < 100 and not is_low_value_title(detail_title):
                        row["description"] = honam_bio_description(detail_text_raw) or clean_text(detail_text.split(detail_title, 1)[-1])[:2000]
                    education_date = honam_bio_text_after_marker(detail_text_raw, "(교육일)") or honam_bio_text_after_marker(detail_text_raw, "교육일")
                    venue = honam_bio_text_after_marker(detail_text_raw, "(교육장소)") or honam_bio_text_after_marker(detail_text_raw, "교육장소")
                    row["period"] = first_by_keys(detail_pairs, PERIOD_KEYS) or row["period"]
                    row["period"] = honam_bio_normalize_period(education_date) or row["period"]
                    row["fee"] = first_by_keys(detail_pairs, FEE_KEYS) or row["fee"]
                    row["room"] = first_by_keys(detail_pairs, ROOM_KEYS) or row.get("room", "")
                    row["venue_name"] = venue or row.get("room", "") or branch_name
                    row["venue_address"] = branch_address
                except Exception as exc:
                    detail_errors += 1
                    logger.debug("honam detail fetch failed %s: %s", raw_url, exc)
            row["venue_name"] = clean_text(row.get("venue_name")) or branch_name
            row["period"] = clean_text(row.get("period")) or row["apply_period"]
            rows.append(row)
        if len(items) < 9:
            pagination_exhausted = True
            break

    details_complete = (
        detail_attempts == len(rows)
        and detail_pages == detail_attempts
        and detail_errors == 0
    )
    snapshot_complete = pagination_exhausted and details_complete
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_errors": detail_errors,
        "discovered_links": len(seen_ids),
        "expired_count": expired_count,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1,
        "pagination_complete": pagination_exhausted,
        "detail_collection_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "no_current_data": snapshot_complete and not rows,
        "no_current_reason": (
            "official HNIBR education list has no current programs"
            if snapshot_complete and not rows
            else ""
        ),
    }
    return dedupe_rows(rows), "honam_bio_cards", meta


def national_ecology_fee_text(*values: Any) -> str:
    for value in values:
        text = clean_text(value)
        if not text:
            continue
        if text in {"무료", "유료"}:
            return text
        amounts = [int(amount.replace(",", "")) for amount in re.findall(r"(\d[\d,]*)\s*원", text)]
        if amounts:
            if all(amount == 0 for amount in amounts):
                return "무료"
            return f"{min(amount for amount in amounts if amount > 0):,}원"
    return ""


def collect_national_ecology(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_url = "https://www.nie.re.kr/nieResve/pgm/eclgyEdc/list2.do?menuNo=600010"
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    for page in range(1, max_pages + 1):
        url = f"{list_url}&pageIndex={page}"
        soup = fetch_soup(s, url, timeout=timeout)
        items = [item for item in soup.select("ul.list > li") if item.select_one("h5")]
        if not items:
            break
        pages += 1
        for item in items:
            title = clean_text((item.select_one("h5") or item).get_text(" ", strip=True))
            if not title or is_low_value_title(title):
                continue
            categories = [clean_text(li.get_text(" ", strip=True)) for li in item.select(".cate > li") if clean_text(li.get_text(" ", strip=True))]
            status = next((value for value in categories if value in {"접수중", "마감", "준비중", "예약마감"}), "")
            target_text = next((value for value in categories if value in {"유아", "초등", "중등", "고등", "성인"}), "")
            pairs = pairs_from_definition_lists(item)
            onclick = clean_text((item.find("a") or {}).get("href"))
            match = re.search(r"fnProgrmView\('([^']+)'\)", onclick)
            edc_id = match.group(1) if match else ""
            raw_url = f"https://www.nie.re.kr/nieResve/pgm/eclgyEdc/view2.do?menuNo=600010&edcId={edc_id}" if edc_id else url
            image = item.find("img")
            image_url = normalize_link(url, image.get("src") if image else None)
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "category": " / ".join([value for value in categories if value != status]),
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "period": first_by_keys(pairs, ("교육기간",)),
                "apply_period": first_by_keys(pairs, ("접수기간",)),
                "schedule_raw": first_by_keys(pairs, ("교육요일",)),
                "target": target_text,
                "capacity": first_by_keys(pairs, ("모집인원", "모집정원")),
                "capacity_total": first_by_keys(pairs, ("모집인원", "모집정원")),
                "image_url": image_url,
                "description": "",
                "raw_fields": {"edc_id": edc_id, "categories": categories, "parser": "national_ecology_card"},
            }
            if edc_id and detail_pages < max_pages * 2:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = pairs_from_definition_lists(detail_soup)
                    detail_pairs.update(pairs_from_tables(detail_soup))
                    row["fee"] = national_ecology_fee_text(
                        first_by_keys(detail_pairs, FEE_KEYS),
                        first_by_keys(detail_pairs, ("예약인원", "2 예약인원")),
                        detail_soup.get_text(" ", strip=True),
                    ) or row.get("fee", "")
                    row["room"] = first_by_keys(detail_pairs, ROOM_KEYS) or row.get("room", "")
                    row["venue_name"] = row.get("room", "")
                    description = first_by_keys(detail_pairs, DESCRIPTION_KEYS)
                    if not description:
                        text = clean_text(detail_soup.get_text(" ", strip=True))
                        marker = "상세설명"
                        if marker in text:
                            description = clean_text(text.split(marker, 1)[1])[:2000]
                    row["description"] = description
                except Exception as exc:
                    logger.debug("national ecology detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": len(rows) >= 10,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "national_ecology_cards", meta


NIHC_BASE_URL = "https://www.nihc.go.kr"
NIHC_BOARD_UID = "ff8080816ecaefcf016ecfc31e210243"
NIHC_ADDRESS = "전북특별자치도 전주시 완산구 서학로 95(동서학동 896-1)"
NIHC_PHONE = "063-280-1400"
NIHC_CONTENTS = (
    ("전문교육", "ff8080816eee4ad5016eee8e465400c6"),
    ("사회교육", "ff8080816eee4ad5016ef8eb5793085b"),
)


def nihc_list_url(content_uid: str, page: int = 1) -> str:
    query = {
        "page": str(page),
        "boardUid": NIHC_BOARD_UID,
        "contentUid": content_uid,
        "layoutUid": "",
        "searchType": "",
        "keyword": "",
        "categoryUid1": "",
        "categoryUid2": "",
        "cateogryUid3": "",
    }
    return f"{NIHC_BASE_URL}/planweb/board/list.9is?{urlencode(query)}"


def nihc_clean_date_text(value: str) -> str:
    text = clean_text(value)
    text = re.sub(r"\([^)]*\)", "", text)
    text = re.sub(r"(\d{4})\s*년", r"\1.", text)
    text = re.sub(r"(\d{1,2})\s*월", r"\1.", text)
    text = re.sub(r"(\d{1,2})\s*일", r"\1", text)
    text = text.replace("∼", "~").replace("~", " ~ ")
    return clean_text(text)


def nihc_normalize_date_range(value: Any, fallback_year: int | None = None) -> str:
    text = clean_text(value)
    if not text:
        return ""
    cleaned = nihc_clean_date_text(text)
    match = re.search(
        r"(\d{4})\s*[.-]\s*(\d{1,2})\s*[.-]\s*(\d{1,2})\s*[.]?\s*~\s*(?:(\d{4})\s*[.-]\s*)?(\d{1,2})\s*[.-]\s*(\d{1,2})",
        cleaned,
    )
    if match:
        start_year = int(match.group(1))
        end_year = int(match.group(4) or start_year)
        return (
            f"{start_year:04d}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
            f" ~ {end_year:04d}-{int(match.group(5)):02d}-{int(match.group(6)):02d}"
        )
    match = re.search(r"(\d{1,2})\s*[.-]\s*(\d{1,2})\s*[.]?\s*~\s*(\d{1,2})\s*[.-]\s*(\d{1,2})", cleaned)
    if match and fallback_year:
        return (
            f"{fallback_year:04d}-{int(match.group(1)):02d}-{int(match.group(2)):02d}"
            f" ~ {fallback_year:04d}-{int(match.group(3)):02d}-{int(match.group(4)):02d}"
        )
    return normalize_mixed_date_range(text)


def nihc_period_and_schedule_from_card(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    bracket = ""
    bracket_match = re.search(r"\[([^\]]+)\]", text)
    if bracket_match:
        bracket = clean_text(bracket_match.group(1))
    period = nihc_normalize_date_range(re.sub(r"\[[^\]]+\]", "", text))
    return period, bracket


def nihc_info_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in soup.select(".infoBox li"):
        key_node = item.find("strong")
        value_node = item.find("span")
        key = clean_text(key_node.get_text(" ", strip=True) if key_node else "")
        if not key or not value_node:
            continue
        value = clean_text(value_node.get_text(" ", strip=True))
        marker = clean_text((value_node.find("em") or {}).get_text(" ", strip=True) if value_node.find("em") else "")
        if marker and value.startswith(marker):
            value = clean_text(value[len(marker) :])
        if value:
            pairs[key] = value
    return pairs


def nihc_detail_description(soup: BeautifulSoup) -> str:
    view = soup.select_one(".viewList .view-con")
    if not view:
        return ""
    return clean_text(view.get_text(" ", strip=True))[:3000]


def nihc_labeled_value(text: str, labels: tuple[str, ...]) -> str:
    source = clean_text(text)
    stop_labels = (
        "모집기간",
        "모집인원",
        "모집대상",
        "교육명",
        "교육목적",
        "교육기간",
        "교육장소",
        "교육대상",
        "교육내용",
        "운영일수",
        "운영 시간",
        "신청기간",
        "신청방법",
        "전화 문의",
        "교육비",
        "교재비",
        "참가비",
        "수강료",
        "기타사항",
        "문의전화",
    )
    stop_pattern = "|".join(rf"(?:[ㆍ·\-*]\s*)?{re.escape(label)}\s*(?:[:：]|\s)" for label in stop_labels)
    for label in labels:
        pattern = rf"(?:^|\s)(?:[ㆍ·\-*]\s*)?{re.escape(label)}\s*[:：]?\s*(.*?)(?=\s*(?:{stop_pattern})|$)"
        match = re.search(pattern, source, re.DOTALL)
        if match:
            return clean_text(match.group(1))
    return ""


def nihc_application_link(detail_url: str, soup: BeautifulSoup) -> str:
    candidates: list[str] = []
    for a in soup.select(".view-con a[href], #boardWrap a[href]"):
        text = clean_text(a.get_text(" ", strip=True))
        href = normalize_link(detail_url, a.get("href"))
        if not href:
            continue
        haystack = f"{text} {href}".lower()
        if any(token in haystack for token in ("support.nihc.go.kr", "apply", "crse", "edu", "신청", "접수", "예약")):
            candidates.append(href)
    return candidates[0] if candidates else ""


def nihc_image_url(base_url: str, *nodes: Any) -> str:
    for node in nodes:
        if not node:
            continue
        for image in node.select("img[src]") if hasattr(node, "select") else []:
            raw_src = clean_text(image.get("src"))
            if not raw_src or raw_src.startswith(("data:", "javascript:")):
                continue
            src = urldefrag(urljoin(base_url, raw_src))[0]
            parsed = urlparse(src)
            if parsed.scheme not in {"http", "https"} or not parsed.netloc:
                continue
            if src and not any(token in src.lower() for token in ("logo", "favicon", "blank")):
                return src
    return ""


def nihc_material_note(description: str) -> str:
    lines = [clean_text(line) for line in re.split(r"[\r\n]|(?=\s*[ㆍ·\-*]\s*)", description) if clean_text(line)]
    notes = [line for line in lines if any(token in line for token in ("재료비", "재료", "준비물", "체험 키트", "꾸러미"))]
    return clean_text(" ".join(notes))[:500]


def nihc_should_skip_expired(period: str) -> bool:
    _, end_date = parse_date_range(period)
    return bool(end_date and end_date < datetime.now().astimezone().date())


def collect_national_intangible_heritage_center(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    detail_attempts = 0
    detail_errors = 0
    pagination_detected = False
    seen_urls: set[str] = set()
    exhausted_sections = 0
    effective_max_pages = max(1, max_pages)
    page_budget = PageBudget(max_pages)

    for section_index, (section_name, content_uid) in enumerate(NIHC_CONTENTS):
        stop_section = False
        remaining_sections = len(NIHC_CONTENTS) - section_index
        remaining_budget = max(0, page_budget.limit - page_budget.used)
        section_page_limit = max(1, remaining_budget // max(remaining_sections, 1))
        for page in range(1, min(effective_max_pages, section_page_limit) + 1):
            if not page_budget.claim():
                break
            current_url = nihc_list_url(content_uid, page)
            soup = fetch_soup(s, current_url, timeout=timeout)
            items = soup.select("ul.type-thumb > li")
            course_items = [item for item in items if item.select_one("dt")]
            if not course_items:
                exhausted_sections += 1
                stop_section = True
                break
            pages += 1
            pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='page=']"))

            for item in course_items:
                title = clean_text((item.select_one("dt") or item).get_text(" ", strip=True))
                if not title or is_low_value_title(title):
                    continue

                dds = [clean_text(dd.get_text(" ", strip=True)) for dd in item.select("dd") if clean_text(dd.get_text(" ", strip=True))]
                period, card_schedule = nihc_period_and_schedule_from_card(dds[0] if dds else "")
                if nihc_should_skip_expired(period):
                    continue

                status = next((value for value in reversed(dds) if status_has_course_state(value) or "신청가능" in value), "")
                link = item.select_one(".btn_rev a[href]") or item.find("a", href=True)
                raw_url = normalize_link(current_url, link.get("href") if link else None) or current_url
                if raw_url in seen_urls:
                    continue
                seen_urls.add(raw_url)

                image_url = nihc_image_url(current_url, item)
                info_pairs: dict[str, str] = {}
                description = ""
                application_url = ""
                material_note = ""
                material_fee = None
                detail_pairs_from_text: dict[str, str] = {}
                detail_image_url = ""
                if raw_url and detail_pages < max(0, detail_limit):
                    detail_attempts += 1
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        info_pairs = nihc_info_pairs(detail_soup)
                        description = nihc_detail_description(detail_soup)
                        application_url = nihc_application_link(raw_url, detail_soup)
                        detail_image_url = nihc_image_url(raw_url, detail_soup.select_one(".thumbnail"), detail_soup.select_one(".view-con"))
                        material_note = nihc_material_note(description)
                        material_fee = extract_material_fee_amount(material_note, description)
                        detail_pairs_from_text = {
                            "period": nihc_labeled_value(description, ("교육기간",)),
                            "apply_period": nihc_labeled_value(description, ("신청기간", "모집기간", "접수기간")),
                            "target": nihc_labeled_value(description, ("교육대상", "모집대상", "참여대상", "대상")),
                            "fee": nihc_labeled_value(description, ("교육비", "교재비", "참가비", "수강료")),
                            "application_method": nihc_labeled_value(description, ("신청방법",)),
                            "capacity": nihc_labeled_value(description, ("모집인원", "모집인원 및 일수")),
                            "room": nihc_labeled_value(description, ("교육장소",)),
                        }
                    except Exception as exc:
                        detail_errors += 1
                        logger.debug("NIHC detail fetch failed %s: %s", raw_url, exc)

                info_title = clean_text(info_pairs.get("제목"))
                if info_title:
                    title = info_title
                info_period = clean_text(info_pairs.get("일정"))
                if info_period:
                    period = nihc_normalize_date_range(info_period) or period
                fallback_year = None
                parsed_start, _ = parse_date_range(period)
                if parsed_start:
                    fallback_year = parsed_start.year
                detail_period = nihc_normalize_date_range(detail_pairs_from_text.get("period"), fallback_year=fallback_year)
                if detail_period:
                    period = detail_period
                if nihc_should_skip_expired(period):
                    continue

                schedule_parts = []
                detail_period_raw = clean_text(detail_pairs_from_text.get("period"))
                weekday_tail = re.sub(r".*?~\s*(?:\d{4}[.\-]\s*)?\d{1,2}[.\-]\s*\d{1,2}[.]?\s*,?", "", nihc_clean_date_text(detail_period_raw))
                if weekday_tail and weekday_tail != detail_period_raw:
                    schedule_parts.append(weekday_tail)
                for value in (clean_text(info_pairs.get("교육시간")), card_schedule):
                    if value and value not in schedule_parts:
                        schedule_parts.append(value)

                apply_period = clean_text(info_pairs.get("접수기간"))
                detail_apply_period = nihc_normalize_date_range(detail_pairs_from_text.get("apply_period"), fallback_year=fallback_year)
                if detail_apply_period:
                    apply_period = detail_apply_period
                elif apply_period:
                    apply_period = nihc_normalize_date_range(apply_period) or apply_period

                category = clean_text(info_pairs.get("교육구분")) or section_name
                target_text = clean_text(info_pairs.get("교육대상") or detail_pairs_from_text.get("target")) or "전체"
                room = clean_text(info_pairs.get("교육장소") or detail_pairs_from_text.get("room"))
                fee = clean_text(detail_pairs_from_text.get("fee"))
                if "무료" in fee and any(token in fee for token in ("재료비", "재료", "준비물")):
                    material_note = clean_text(" ".join(part for part in [material_note, fee] if part))[:500]
                    material_fee = material_fee or extract_material_fee_amount(material_note)
                    fee = "무료"
                if not fee and "무료" in description:
                    fee = "무료"
                if not fee:
                    fee = "별도 안내"
                application_method = clean_text(detail_pairs_from_text.get("application_method"))
                contact = clean_text(info_pairs.get("담당자 연락처")) or NIHC_PHONE

                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                        "title": title,
                        "branch": target.branch,
                        "branch_code": target.provider,
                        "category": category,
                        "raw_url": raw_url,
                        "application_url": application_url,
                        "status": status,
                        "fee": fee,
                        "material_fee": material_fee,
                        "material_note": material_note,
                        "period": period,
                        "apply_period": apply_period,
                        "schedule_raw": clean_text(" ".join(schedule_parts)),
                        "target": target_text,
                        "capacity": clean_text(detail_pairs_from_text.get("capacity")),
                        "room": room,
                        "venue_name": room or target.branch,
                        "venue_address": NIHC_ADDRESS,
                        "address": NIHC_ADDRESS,
                        "phone": contact,
                        "instructor": clean_text(info_pairs.get("담당자")),
                        "application_method_raw": application_method,
                        "description": description or clean_text(" ".join(dds)) or clean_text(" ".join([title, period, card_schedule])),
                        "image_url": detail_image_url or image_url,
                        "program_type": "강좌",
                        "collection_category": "박물관/과학관",
                        "domain_category": "문화유산/체험",
                        "source_group": "national_institution",
                        "operator_type": "국립/공공기관",
                        "collection_type": "static_html",
                        "preserve_branch": True,
                        "raw_fields": {
                            "parser": "nihc_type_thumb_detail",
                            "section": section_name,
                            "content_uid": content_uid,
                            "card_dds": dds,
                            "info_pairs": info_pairs,
                            "detail_pairs_from_text": detail_pairs_from_text,
                            "robots_disallow_all": True,
                        },
                    }
                )
            if stop_section:
                break
        if page_budget.exhausted:
            break

    pagination_complete = exhausted_sections == len(NIHC_CONTENTS)
    details_complete = (
        detail_attempts == len(seen_urls)
        and detail_pages == detail_attempts
        and detail_errors == 0
    )
    snapshot_complete = pagination_complete and details_complete
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_errors": detail_errors,
        "discovered_links": len(seen_urls),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_complete,
        "detail_collection_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "robots_disallow_all": True,
        "no_current_data": snapshot_complete and not rows,
        "no_current_reason": (
            "official NIHC education sections have no current programs"
            if snapshot_complete and not rows
            else ""
        ),
    }
    return dedupe_rows(rows), "nihc_type_thumb_detail", meta


def national_ocean_schedule_text(value: Any) -> str:
    text = clean_text(value)
    ranges = [
        clean_text(match.group(0))
        for match in re.finditer(r"\d{1,2}:\d{2}\s*(?:~|-|–)\s*\d{1,2}:\d{2}", text)
    ]
    if ranges:
        return clean_text(" / ".join(dict.fromkeys(ranges[:6])))
    for label in ("교육시간", "운영시간"):
        if label not in text:
            continue
        tail = clean_text(text.split(label, 1)[-1]).lstrip(":： ")
        for token in ("교육 대상", "교육기간", "운영 기간", "참여인원", "문의", "📅", "📝", "📞", "👥", "🌊"):
            if token in tail:
                tail = clean_text(tail.split(token, 1)[0])
        if tail:
            return tail[:80]
    return ""


def collect_national_ocean_science(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 100,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": target.url, "X-Requested-With": "XMLHttpRequest"})
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    for page in range(1, max_pages + 1):
        response = s.get(
            "https://www.kosm.or.kr/kosm/bbs/boardAjax.do",
            params={"bbsId": "BSD0008", "type": "r", "pageIndex": page},
            timeout=timeout,
        )
        response.raise_for_status()
        payload = response.json()
        items = payload.get("list") or []
        if not items:
            break
        pages += 1
        for item in items:
            title = clean_text(item.get("sj"))
            if not title or is_low_value_title(title):
                continue
            bbs_seq = clean_text(item.get("bbsSeq"))
            raw_url = f"https://www.kosm.or.kr/kosm/bbs/boardView.do?idx={bbs_seq}&pageNo=1&bbsId=BSD0008"
            reserve_url = f"https://www.kosm.or.kr/kosm/reserve/smartReserve.do?bbsSeq={bbs_seq}&bbsId=BSD0008"
            file_row = item.get("file") if isinstance(item.get("file"), dict) else {}
            image_url = ""
            if file_row:
                image_url = normalize_link(target.url, f"/upload/M0060/{clean_text(file_row.get('streFileNm'))}")
            description = clean_text(item.get("rsvtReference"))
            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    text = clean_text(detail_soup.get_text(" ", strip=True))
                    if "문의처" in text:
                        description = clean_text(text.split("문의처", 1)[-1])[:2000]
                    detail_image = detail_soup.select_one(".view_cont img, .board_view img, img")
                    if detail_image:
                        image_url = image_url or normalize_link(raw_url, detail_image.get("src"))
                except Exception as exc:
                    logger.debug("national ocean detail fetch failed %s: %s", raw_url, exc)
            schedule = clean_text(item.get("rsvtTime") or item.get("timeInfo")) or national_ocean_schedule_text(description)
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "category": clean_text(item.get("rsvtCateg") or item.get("bbsNm")),
                    "raw_url": raw_url,
                    "application_url": reserve_url if clean_text(item.get("rsvtTypek")) == "온라인" else raw_url,
                    "status": clean_text(item.get("rsvtStatusk")),
                    "fee": "무료" if clean_text(item.get("rsvtCost")) in {"0", "0.0"} else clean_text(item.get("rsvtCost")),
                    "period": f"{clean_text(item.get('startDatef'))} ~ {clean_text(item.get('endDatef'))}",
                    "apply_period": f"{clean_text(item.get('rsvtStartDatef'))} ~ {clean_text(item.get('rsvtEndDatef'))}",
                    "schedule_raw": schedule,
                    "target": clean_text(item.get("rsvtTarget") or item.get("rsvtTargetk")),
                    "capacity": clean_text(item.get("rsvtPeopleLimit")),
                    "room": clean_text(item.get("rsvtPlace")),
                    "venue_name": clean_text(item.get("rsvtPlace")),
                    "application_method_raw": clean_text(item.get("rsvtTypek")),
                    "program_type": "강좌",
                    "description": description,
                    "image_url": image_url,
                    "raw_fields": {"bbsSeq": bbs_seq, "parser": "national_ocean_board_ajax"},
                }
            )
        if page >= int(payload.get("pageCount") or page):
            break
    page_count = int((locals().get("payload") or {}).get("pageCount") or pages)
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": page_count > 1,
        "pagination_complete": pages >= page_count,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "national_ocean_board_ajax", meta


def collect_national_park_reservation(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Referer": target.url, "X-Requested-With": "XMLHttpRequest"})
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pages = 0
    groups = [("G", "해설탐방/환경교육"), ("H", "치유탐방 프로그램"), ("PET", "반려견 동반")]
    for orgnzt_gbn, group_name in groups:
        for page in range(1, max_pages + 1):
            response = s.post(
                "https://res.knps.or.kr/trprogram/trprogramList.do",
                data={
                    "dept_id": "",
                    "dept_name": "전체",
                    "orgnzt_gbn": orgnzt_gbn,
                    "pageNo": page,
                    "listScale": 10,
                },
                timeout=timeout,
            )
            response.raise_for_status()
            soup = BeautifulSoup(response.text, "lxml")
            body_rows = soup.select("table tbody tr") or soup.select("tr")[1:]
            if not body_rows:
                break
            pages += 1
            for tr in body_rows:
                cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
                if len(cells) < 5:
                    continue
                park_name = cells[1]
                venue = cells[2]
                title = cells[3]
                period = cells[4]
                link = tr.find("a", href=True)
                raw_url = normalize_link("https://res.knps.or.kr", link.get("href") if link else None) or target.url
                row = {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": park_name or target.branch,
                    "category": group_name,
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": "예약가능",
                    "period": period,
                    "schedule_raw": period,
                    "room": venue,
                    "venue_name": venue,
                    "description": "",
                    "raw_fields": {"orgnzt_gbn": orgnzt_gbn, "parser": "national_park_trprogram"},
                }
                if raw_url and detail_pages < max_pages * 4:
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        pairs = pairs_from_definition_lists(detail_soup)
                        description = first_by_keys(pairs, ("주요내용", "주의사항", "내용"))
                        row["description"] = description
                        row["target"] = first_by_keys(pairs, ("참가대상", "대상")) or row.get("target", "")
                        row["capacity"] = first_by_keys(pairs, ("참가인원", "정원")) or row.get("capacity", "")
                        row["application_method_raw"] = first_by_keys(pairs, ("참가방법", "예약방법")) or row.get("application_method_raw", "")
                    except Exception as exc:
                        logger.debug("national park detail fetch failed %s: %s", raw_url, exc)
                rows.append(row)
            if page >= 1 and len(body_rows) < 10:
                break
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages >= max_pages,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "national_park_trprogram", meta


