def modu_extract_total_pages(soup: BeautifulSoup) -> int:
    scripts_text = "\n".join(script.get_text(" ", strip=True) for script in soup.find_all("script"))
    match = re.search(r"var\s+totalPages\s*=\s*(\d+)", scripts_text)
    return max(1, int(match.group(1))) if match else 1


def modu_detail_id(node: Any) -> str:
    onclick_values = " ".join(
        clean_text(tag.get("onclick"))
        for tag in node.select("[onclick]")
        if clean_text(tag.get("onclick"))
    )
    match = re.search(r"goDetail\((\d+)\)", onclick_values)
    return match.group(1) if match else ""


def modu_card_pairs(card: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in card.select("dl.info_text"):
        key = clean_text((dl.find("dt") or dl).get_text(" ", strip=True))
        value_node = dl.find("dd")
        value = clean_text(value_node.get_text(" ", strip=True)) if value_node else ""
        if key and value:
            pairs[key] = value
    return pairs


def modu_rows_from_list_soup(target: CrawlTarget, soup: BeautifulSoup) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for li in soup.select("#listUl > li, li"):
        if not li.select_one(".card.type02"):
            continue
        detail_id = modu_detail_id(li)
        title = clean_text((li.select_one(".title") or li).get_text(" ", strip=True))
        if not title or not detail_id:
            continue
        branch = clean_text((li.select_one(".writer") or {}).get_text(" ", strip=True) if li.select_one(".writer") else "")
        museum_info = next((info for info in MODU_MUSEUMS.values() if info["name"] == branch), {})
        raw_url = f"https://modu.museum.go.kr/learn/detail/{detail_id}"
        badges = [clean_text(span.get_text(" ", strip=True)) for span in li.select(".badge span")]
        pairs = modu_card_pairs(li)
        image_node = li.select_one("img.thumb_img")
        image_url = normalize_link(MODU_LEARN_URL, image_node.get("src") if image_node else "")
        period = clean_text(pairs.get("교육기간"))
        target_text = clean_text(pairs.get("신청대상자") or pairs.get("신청대상"))
        status = next((badge for badge in badges if "접수" in badge or "운영" in badge or "마감" in badge), "")
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, branch or target.branch),
                "title": title,
                "branch": branch or target.branch,
                "branch_code": branch or target.provider,
                "preserve_branch": True,
                "category": clean_text(" ".join(badge for badge in badges if badge != status)),
                "collection_category": "박물관/과학관",
                "domain_category": "박물관/과학관",
                "source_group": "museum_science",
                "operator_type": "국립/공공기관",
                "collection_type": "ajax_api",
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "period": period,
                "schedule_raw": period,
                "target": target_text,
                "eligibility_raw": target_text,
                "fee": "",
                "room": "",
                "venue_name": branch or target.branch,
                "address": museum_info.get("address", ""),
                "venue_address": museum_info.get("address", ""),
                "image_url": image_url,
                "description": "",
                "program_type": "강좌",
                "reservation_available": "접수중" in status,
                "raw_fields": {"detail_id": detail_id, "badges": badges, "list_pairs": pairs, "parser": "modu_learn_list"},
            }
        )
    return rows


def modu_round_schedule(soup: BeautifulSoup, limit: int = 8) -> str:
    for table in soup.select("table"):
        headers = [clean_text(cell.get_text(" ", strip=True)) for cell in table.select("th")]
        if "교육일시" not in headers:
            continue
        values: list[str] = []
        for tr in table.select("tbody tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
            if len(cells) >= 2 and cells[1] and cells[1] not in values:
                values.append(cells[1])
            if len(values) >= limit:
                break
        return clean_text(" / ".join(values))
    return ""


def modu_detail_description(soup: BeautifulSoup) -> str:
    candidates: list[str] = []
    for selector in (".detail_cont", ".learn_detail", ".detail_info", ".editor", ".cont"):
        for node in soup.select(selector):
            text = clean_text(node.get_text(" ", strip=True))
            if text and len(text) > 30:
                candidates.append(text)
    if candidates:
        return max(candidates, key=len)[:4000]
    return clean_text(soup.get_text(" ", strip=True))[:4000]


def modu_merge_detail(row: dict[str, Any], soup: BeautifulSoup) -> None:
    pairs = pairs_from_tables(soup)
    title_node = soup.select_one(".detail_title")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    if title and len(title) < 255:
        row["title"] = title
    branch = clean_text(pairs.get("박물관") or row.get("branch"))
    if branch:
        row["branch"] = branch
        row["branch_code"] = branch
    row["period"] = clean_text(pairs.get("교육기간") or row.get("period"))
    row["apply_period"] = clean_text(pairs.get("접수기간") or row.get("apply_period", ""))
    row["target"] = clean_text(pairs.get("교육대상") or row.get("target"))
    row["eligibility_raw"] = row["target"]
    row["fee"] = clean_text(pairs.get("참가비") or pairs.get("수강료") or row.get("fee"))
    row["room"] = clean_text(pairs.get("교육장소") or row.get("room"))
    row["venue_name"] = clean_text(row.get("room") or row.get("venue_name") or row.get("branch"))
    row["instructor"] = clean_text(pairs.get("담당자") or row.get("instructor"))
    row["application_method_raw"] = clean_text(pairs.get("접수방법") or row.get("application_method_raw"))
    row["category"] = clean_text(pairs.get("교육그룹") or row.get("category"))
    schedule = modu_round_schedule(soup)
    row["schedule_raw"] = clean_text(" / ".join(part for part in [row.get("period", ""), schedule] if part))
    row["description"] = modu_detail_description(soup)
    if not row.get("image_url"):
        image = soup.select_one(".thumb_img") or soup.select_one(".detail_top img") or soup.select_one("img")
        row["image_url"] = normalize_link(row.get("raw_url", ""), image.get("src") if image else "")
    row["raw_fields"] = {**row.get("raw_fields", {}), "detail_pairs": pairs, "parser": "modu_learn_list+detail"}


def collect_national_museum_of_korea(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pages = 0
    discovered_museums = 0
    pagination_detected = False
    page_limit = max(1, max_pages)
    parsed_target = urlparse(target.url)
    target_museum_id = (parse_qs(parsed_target.query).get("museum") or [""])[0]
    target_branch = clean_text(target.branch)
    museum_items = [
        (museum_id, museum_info)
        for museum_id, museum_info in MODU_MUSEUMS.items()
        if (not target_museum_id or museum_id == target_museum_id)
        and (not target_branch or target_branch == target.name or museum_info["name"] == target_branch)
    ]
    if not museum_items:
        museum_items = list(MODU_MUSEUMS.items())

    for museum_id, museum_info in museum_items:
        discovered_museums += 1
        params = {"museum": museum_id, "searchApplyStatus": "ONGOING", "sort": "createdDateTime,desc", "sortBy": "createdDateTime"}
        first_response = s.get(MODU_LEARN_URL, params=params, timeout=timeout)
        first_response.raise_for_status()
        first_soup = BeautifulSoup(first_response.text, "lxml")
        total_pages = modu_extract_total_pages(first_soup)
        pagination_detected = pagination_detected or total_pages > 1
        museum_rows = modu_rows_from_list_soup(target, first_soup)
        pages += 1

        for page in range(2, min(total_pages, page_limit) + 1):
            append_params = {
                "sort": "createdDateTime,desc",
                "sortBy": "createdDateTime",
                "isFolded": "",
                "contact": "",
                "group": "",
                "searchKeyword": "",
                "startDate": "",
                "endDate": "",
                "searchApplyStatus": "ONGOING",
                "museum": museum_id,
                "page": page,
                "size": 8,
            }
            response = s.get(MODU_LEARN_APPEND_URL, params=append_params, timeout=timeout)
            response.raise_for_status()
            page_soup = BeautifulSoup(f'<ul id="listUl">{response.text}</ul>', "lxml")
            page_rows = modu_rows_from_list_soup(target, page_soup)
            if not page_rows:
                break
            museum_rows.extend(page_rows)
            pages += 1

        for row in museum_rows:
            if not row.get("address") and row.get("branch") == museum_info["name"]:
                row["address"] = museum_info["address"]
                row["venue_address"] = museum_info["address"]
            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, row["raw_url"], timeout=timeout)
                    modu_merge_detail(row, detail_soup)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("MODU detail fetch failed %s: %s", row.get("raw_url"), exc)
            rows.append(row)

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_museums": discovered_museums,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "no_current_data": bool(museum_items) and not rows,
        "no_current_reason": (
            "no_current_modu_museum_programs"
            if museum_items and not rows
            else ""
        ),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "modu_learn_list+detail", meta


def national_science_labeled_value(text: str, labels: tuple[str, ...]) -> str:
    stop_labels = (
        "교육시작일",
        "교육종료일",
        "교육대상",
        "교육기간",
        "접수시기",
        "교육시간",
        "교육비",
        "참가비",
        "비용",
        "재료비",
        "모집인원",
        "인원",
        "구성",
        "주제",
        "장소",
        "교육장소",
        "신청방법",
        "접수기간",
        "문의",
        "첨부파일",
        "파일",
    )
    for label in labels:
        value = extract_korean_labeled_value(text, label, stop_labels)
        if value:
            return value
    return ""


def national_science_time_ranges(text: str) -> str:
    ranges = [
        clean_text(match.group(0))
        for match in re.finditer(r"\d{1,2}:\d{2}\s*(?:~|-|–)\s*\d{1,2}:\d{2}", text)
    ]
    return clean_text(" / ".join(dict.fromkeys(ranges[:5])))


def national_science_core_text(value: Any) -> str:
    text = clean_text(value)
    for token in ("□ 문의", "○ 문의", "문의 :", "문의:", "교육 취소", "환불기준", "취소 일자별", "사전예약", "음성 중지"):
        if token in text:
            text = clean_text(text.split(token, 1)[0])
    return text


def national_science_trim_value(value: Any) -> str:
    text = clean_text(value)
    for token in (" □", " ○", " 【", " ※", " 신청하기", " 사전예약", " 음성", " 목록", " 이전글", " 다음글", " 첨부파일", " 파일 "):
        if token in text:
            text = clean_text(text.split(token, 1)[0])
    return text.strip(" -")


def national_science_schedule_text(value: Any, fallback_text: str = "") -> str:
    text = national_science_trim_value(value)
    ranges = national_science_time_ranges(text) or national_science_time_ranges(fallback_text)
    return ranges or text[:120]


def national_science_fee_text(value: Any) -> str:
    text = national_science_trim_value(value)
    if not text:
        return ""
    if "환불" in text and "무료" not in text and not re.search(r"\d{1,3}(?:,\d{3})+\s*원|\d+\s*원", text):
        return ""
    fees = re.findall(r"\d{1,3}(?:,\d{3})+\s*원(?:\([^)]{1,30}\))?|\d+\s*원", text)
    if fees:
        return clean_text(" / ".join(dict.fromkeys(fee.replace(" ", "") for fee in fees[:4])))
    if "무료" in text:
        return "무료 (재료비 별도)" if "재료비" in text else "무료"
    return text[:120]


def national_science_capacity_text(value: Any) -> str:
    text = national_science_trim_value(value)
    if not text:
        return ""
    for pattern in (
        r"선착순\s*\d+\s*명",
        r"\d+\s*가족(?:\([^)]{1,40}\))?",
        r"\d+\s*명(?:\s*\([^)]{1,40}\))?",
        r"\d+\s*팀(?:\s*\([^)]{1,40}\))?",
    ):
        match = re.search(pattern, text)
        if match:
            return clean_text(match.group(0))
    return text[:120]


def national_science_room_text(value: Any) -> str:
    text = national_science_trim_value(value)
    if not text:
        return ""
    if "/" in text and re.search(r"\d{1,2}:\d{2}|\d{4}[.]", text.split("/", 1)[0]):
        text = clean_text(text.split("/", 1)[-1])
    for token in (" - 모집", " * ", " ○", " □"):
        if token in text:
            text = clean_text(text.split(token, 1)[0])
    if " o " in text:
        text = clean_text(text.split(" o ", 1)[0])
    return text[:120]


def collect_national_science_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int = 100,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    for tr in soup.select("table tbody tr") or soup.select("tr")[1:]:
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
        if len(cells) < 6:
            continue
        status = cells[1]
        title = cells[2]
        target_text = cells[3]
        period = cells[4]
        apply_period = cells[5]
        onclick = clean_text(tr.get("onclick") or "")
        match = re.search(r"fn_moveEduBbsNttDetail\('([^']+)'\s*,\s*'([^']+)'\)", onclick)
        raw_url = target.url
        if match:
            raw_url = f"https://www.science.go.kr/mps/1092/bbs/{match.group(1)}/moveBbsNttDetail.do?nttSn={match.group(2)}"
        row = {
            "provider": target.provider,
            "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
            "title": title,
            "branch": target.branch,
            "raw_url": raw_url,
            "application_url": raw_url,
            "status": status,
            "period": period,
            "apply_period": apply_period,
            "schedule_raw": "",
            "target": target_text,
            "description": "",
            "raw_fields": {"parser": "national_science_table"},
        }
        image = tr.find("img")
        if image:
            row["image_url"] = normalize_link(target.url, image.get("src"))
        if raw_url != target.url and detail_pages < max(0, detail_limit):
            try:
                detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                detail_pages += 1
                pairs = pairs_from_definition_lists(detail_soup)
                pairs.update(pairs_from_tables(detail_soup))
                text = clean_text(detail_soup.get_text(" ", strip=True))
                content_text = clean_text(text.split(title, 1)[-1] if title in text else text)
                content_core = national_science_core_text(content_text)
                schedule = (
                    first_by_keys(pairs, ("교육시간", "시간", "일시"))
                    or national_science_time_ranges(row.get("period", ""))
                    or national_science_time_ranges(content_core)
                    or national_science_labeled_value(content_core, ("교육시간", "시간", "일시"))
                )
                row["schedule_raw"] = national_science_schedule_text(schedule, content_core) or row["schedule_raw"]
                row["period"] = first_by_keys(pairs, ("교육기간", "기간")) or row["period"]
                row["target"] = first_by_keys(pairs, ("교육대상", "대상")) or row["target"]
                row["fee"] = national_science_fee_text(
                    first_by_keys(pairs, ("교육비", "참가비", "비용", "재료비"))
                    or national_science_labeled_value(content_core, ("교육비", "참가비", "비용", "재료비"))
                )
                row["capacity"] = national_science_capacity_text(
                    first_by_keys(pairs, ("모집인원", "인원", "정원"))
                    or national_science_labeled_value(content_core, ("모집인원", "인원", "정원"))
                )
                row["room"] = national_science_room_text(
                    first_by_keys(pairs, ("교육장소", "장소"))
                    or national_science_labeled_value(content_core, ("교육장소", "장소"))
                )
                row["venue_name"] = row.get("room") or target.branch
                row["description"] = content_text[:2000]
                row["raw_fields"] = {**row.get("raw_fields", {}), "detail_pairs": pairs}
            except Exception as exc:
                logger.debug("national science detail fetch failed %s: %s", raw_url, exc)
        rows.append(row)
    meta = {
        "pages": 1,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "pagination_complete": True,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "national_science_table", meta


HANGEUL_BASE_URL = "https://www.hangeul.go.kr"
HANGEUL_EDUCATION_LIST_URL = f"{HANGEUL_BASE_URL}/education"
HANGEUL_EVENT_LIST_URL = f"{HANGEUL_BASE_URL}/eduCul/event/reservList.do"
HANGEUL_EDUCATION_VIEW_URL = f"{HANGEUL_BASE_URL}/education/view"
HANGEUL_EVENT_VIEW_URL = f"{HANGEUL_BASE_URL}/eduCul/event/onlineReservDetail.do"
HANGEUL_BRANCH = "국립한글박물관"
HANGEUL_ADDRESS = "서울특별시 용산구 서빙고로 139"


def hangeul_image_url(base_url: str, src: str | None) -> str:
    if not src:
        return ""
    src = clean_text(src)
    if not src or src.startswith(("javascript:", "mailto:", "tel:", "#", "data:")):
        return ""
    absolute = urldefrag(urljoin(base_url, src))[0]
    parsed = urlparse(absolute)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return ""
    if any(token in parsed.path for token in ("/logo", "/ico_", "/btn_", "/header_flag")):
        return ""
    return absolute


def hangeul_date_token(token: str):
    text = re.sub(r"\([^)]*\)", "", clean_text(token)).strip(" .")
    match = re.search(r"(20\d{2})\s*[.\-]\s*(\d{1,2})\s*[.\-]\s*(\d{1,2})", text)
    if not match:
        return None
    try:
        return datetime(int(match.group(1)), int(match.group(2)), int(match.group(3))).date()
    except ValueError:
        return None


def normalize_hangeul_period(value: str) -> str:
    text = clean_text(value)
    if not text:
        return ""
    dates = []
    for match in re.finditer(r"20\d{2}\s*[.\-]\s*\d{1,2}\s*[.\-]\s*\d{1,2}", text):
        parsed = hangeul_date_token(match.group(0))
        if parsed:
            dates.append(parsed)
    if not dates:
        return text
    if len(dates) == 1:
        return dates[0].isoformat()
    return f"{dates[0].isoformat()} ~ {dates[-1].isoformat()}"


def hangeul_schedule_dates(*values: str) -> list[str]:
    dates: list[str] = []
    seen: set[str] = set()
    for value in values:
        for match in re.finditer(r"20\d{2}\s*[.\-]\s*\d{1,2}\s*[.\-]\s*\d{1,2}", clean_text(value)):
            parsed = hangeul_date_token(match.group(0))
            if not parsed:
                continue
            iso = parsed.isoformat()
            if iso not in seen:
                seen.add(iso)
                dates.append(iso)
    return dates


def hangeul_status_text(scope: BeautifulSoup) -> str:
    node = scope.select_one(".status-box, .status")
    return clean_text(node.get_text(" ", strip=True) if node else "")


def hangeul_pairs_from_table(table: BeautifulSoup | None) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not table:
        return pairs
    for tr in table.select("tr"):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
        cells = [cell for cell in cells if cell]
        if len(cells) == 2:
            pairs[cells[0]] = cells[1]
        elif len(cells) >= 4:
            for index in range(0, len(cells) - 1, 2):
                if len(cells[index]) <= 20 and cells[index + 1]:
                    pairs[cells[index]] = cells[index + 1]
    return pairs


def hangeul_detail_info_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    edu_info = soup.select_one(".edu-info")
    if edu_info:
        pairs.update(pairs_from_definition_lists(edu_info))
    first_group = soup.select_one(".sub-cont .group")
    if first_group:
        pairs.update(hangeul_pairs_from_table(first_group.find("table")))
    return pairs


def hangeul_reservation_rows(soup: BeautifulSoup) -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    tables = soup.select(".sub-cont .group table")
    if len(tables) < 2:
        return rows
    schedule_table = tables[1]
    headers = [clean_text(cell.get_text(" ", strip=True)) for cell in schedule_table.select("tr th")]
    for tr in schedule_table.select("tr")[1:]:
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
        if not cells:
            continue
        row = {headers[index] if index < len(headers) else f"cell_{index}": value for index, value in enumerate(cells)}
        rows.append(row)
    return rows


def hangeul_detail_description(soup: BeautifulSoup) -> str:
    groups = soup.select(".sub-cont .group")
    if len(groups) >= 2:
        parts = [clean_text(group.get_text(" ", strip=True)) for group in groups[1:]]
        parts = [part for part in parts if part and part != "목록"]
        return clean_text(" ".join(parts))[:2000]
    return ""


def hangeul_detail_image(soup: BeautifulSoup, raw_url: str) -> str:
    for img in soup.select(".sub-cont img, .group img, img"):
        image_url = hangeul_image_url(raw_url, img.get("src"))
        if image_url:
            return image_url
    return ""


def hangeul_fee_from_text(*values: str) -> str:
    text = clean_text(" ".join(value for value in values if value))
    if not text:
        return ""
    if "무료" in text:
        return "무료"
    amount = extract_krw_amount(text)
    return f"{amount:,}원" if amount else ""


def hangeul_detail_url(kind: str, item_id: str, page: int, target: str = "", event_type: str = "1") -> str:
    if kind == "education":
        query = {
            "curr_menu_cd": "0103010000",
            "programNo": item_id,
            "target": target or "0",
            "showGubun": "0",
            "page": str(page),
        }
        return f"{HANGEUL_EDUCATION_VIEW_URL}?{urlencode(query)}"
    query = {
        "curr_menu_cd": "0103030200" if event_type == "2" else "0103030100",
        "eventNo": item_id,
        "eventType": event_type,
        "showGubun": "0",
        "page": str(page),
    }
    return f"{HANGEUL_EVENT_VIEW_URL}?{urlencode(query)}"


def hangeul_common_row(
    target: CrawlTarget,
    *,
    raw_url: str,
    title: str,
    status: str,
    category: str,
    labels: list[str],
    pairs: dict[str, str],
    kind: str,
    image_url: str = "",
    item_id: str = "",
) -> dict[str, Any]:
    target_text = pairs.get("교육 대상") or pairs.get("행사 대상") or ""
    apply_period = pairs.get("신청 기간") or ""
    period_raw = pairs.get("교육 기간") or pairs.get("행사 기간") or ""
    venue = pairs.get("교육 장소") or pairs.get("행사 장소") or ""
    method_parts = [label for label in labels if "접수" in label or "선착순" in label or "추첨" in label or "개별" in label]
    application_method = clean_text(" ".join(dict.fromkeys(method_parts)))
    normalized_period = normalize_hangeul_period(period_raw)
    schedule_raw = period_raw
    dates = hangeul_schedule_dates(period_raw)
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, HANGEUL_BRANCH),
        "title": title,
        "branch": HANGEUL_BRANCH,
        "branch_code": HANGEUL_BRANCH,
        "preserve_branch": True,
        "category": category,
        "collection_category": "박물관/과학관",
        "domain_category": "박물관/과학관",
        "source_group": "museum_science",
        "operator_type": "국립/공공기관",
        "collection_type": "static_html",
        "raw_url": raw_url,
        "application_url": raw_url,
        "application_method_raw": application_method,
        "status": status,
        "period": normalized_period,
        "apply_period": normalize_hangeul_period(apply_period),
        "schedule_raw": schedule_raw,
        "schedule_dates": dates,
        "target": target_text,
        "eligibility_raw": target_text,
        "venue_name": venue or HANGEUL_BRANCH,
        "room": venue,
        "address": HANGEUL_ADDRESS,
        "venue_address": HANGEUL_ADDRESS,
        "image_url": image_url,
        "program_type": "강좌",
        "fee": "",
        "description": "",
        "reservation_available": "접수중" in status,
        "raw_fields": {"item_id": item_id, "labels": labels, "list_pairs": pairs, "parser": "national_hangeul_list"},
    }


def hangeul_merge_detail(row: dict[str, Any], soup: BeautifulSoup) -> None:
    title = clean_text((soup.find("h1") or soup).get_text(" ", strip=True))
    if title and len(title) < 255:
        row["title"] = title
    pairs = hangeul_detail_info_pairs(soup)
    if pairs:
        target_text = pairs.get("교육 대상") or pairs.get("행사 대상") or row.get("target", "")
        apply_period = pairs.get("신청 기간") or row.get("apply_period", "")
        period_raw = pairs.get("교육 기간") or pairs.get("행사 기간") or row.get("schedule_raw", "")
        venue = pairs.get("교육 장소") or pairs.get("행사 장소") or row.get("venue_name", "")
        row["target"] = target_text
        row["eligibility_raw"] = target_text
        row["apply_period"] = normalize_hangeul_period(apply_period)
        row["period"] = normalize_hangeul_period(period_raw) or row.get("period", "")
        row["schedule_raw"] = period_raw
        row["venue_name"] = venue
        row["room"] = venue
        row["capacity"] = pairs.get("교육 정원") or pairs.get("행사 정원") or row.get("capacity", "")
        row["fee"] = hangeul_fee_from_text(pairs.get("참가비")) or row.get("fee", "")
        row["phone"] = pairs.get("문의") or row.get("phone", "")
        row["application_method_raw"] = pairs.get("참가 방법") or row.get("application_method_raw", "")
        row["raw_fields"]["detail_pairs"] = pairs

    reservation_rows = hangeul_reservation_rows(soup)
    if reservation_rows:
        schedule_values = []
        status_values = []
        apply_values = []
        capacity_values = []
        for reservation in reservation_rows:
            date_value = next((value for key, value in reservation.items() if "일자" in key), "")
            if date_value:
                schedule_values.append(date_value)
            apply_value = next((value for key, value in reservation.items() if "신청 기간" in key or "신청기간" in key), "")
            if apply_value:
                apply_values.append(apply_value)
            status_value = next((value for key, value in reservation.items() if key in {"신청", "신청 현황"}), "")
            if status_value:
                status_values.append(status_value)
            capacity_value = next((value for key, value in reservation.items() if "정원" in key), "")
            if capacity_value:
                capacity_values.append(capacity_value)
        if schedule_values:
            row["schedule_raw"] = " | ".join(schedule_values[:5])
            row["schedule_dates"] = hangeul_schedule_dates(*schedule_values)
            if row["schedule_dates"]:
                row["period"] = (
                    row["schedule_dates"][0]
                    if len(row["schedule_dates"]) == 1
                    else f"{row['schedule_dates'][0]} ~ {row['schedule_dates'][-1]}"
                )
        if apply_values:
            row["apply_period"] = normalize_hangeul_period(apply_values[0])
        if capacity_values:
            row["capacity"] = capacity_values[0]
        if status_values and row.get("status") == "접수중" and all("마감" in value for value in status_values):
            row["status"] = "접수마감"
            row["reservation_available"] = False
        row["raw_fields"]["reservation_rows"] = reservation_rows

    description = hangeul_detail_description(soup)
    if description:
        row["description"] = description
        row["fee"] = row.get("fee") or hangeul_fee_from_text(description)
    image_url = hangeul_detail_image(soup, row.get("raw_url", ""))
    if image_url:
        row["image_url"] = image_url


def hangeul_row_from_education_item(target: CrawlTarget, item: BeautifulSoup, page: int) -> dict[str, Any] | None:
    link = item.select_one(".go-view-page[data-program-no]")
    if not link:
        return None
    program_no = clean_text(link.get("data-program-no"))
    target_code = clean_text(link.get("data-target"))
    title = clean_text(link.get_text(" ", strip=True))
    if not program_no or not title or is_low_value_title(title):
        return None
    labels = [clean_text(label.get_text(" ", strip=True)) for label in item.select(".head .label")]
    labels = [label for label in labels if label]
    pairs = pairs_from_definition_lists(item)
    status = hangeul_status_text(item)
    category = next((label for label in reversed(labels) if "교육" in label), "교육")
    raw_url = hangeul_detail_url("education", program_no, page, target=target_code)
    return hangeul_common_row(
        target,
        raw_url=raw_url,
        title=title,
        status=status,
        category=category,
        labels=labels,
        pairs=pairs,
        kind="교육",
        item_id=program_no,
    )


def hangeul_row_from_event_item(target: CrawlTarget, item: BeautifulSoup, page: int, event_type: str) -> dict[str, Any] | None:
    link = item.select_one(".go-view-page[data-event-no]")
    if not link:
        return None
    event_no = clean_text(link.get("data-event-no"))
    title_node = item.select_one(".tit-mid, h3")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else link.get_text(" ", strip=True))
    if not event_no or not title or is_low_value_title(title):
        return None
    labels = [clean_text(label.get_text(" ", strip=True)) for label in item.select(".head .label")]
    labels = [label for label in labels if label]
    pairs = pairs_from_definition_lists(item)
    status = hangeul_status_text(item)
    category = next((label for label in labels if "행사" in label), "행사")
    image = item.select_one(".thumb img, img")
    image_url = hangeul_image_url(HANGEUL_EVENT_LIST_URL, image.get("src") if image else None)
    raw_url = hangeul_detail_url("event", event_no, page, event_type=event_type)
    return hangeul_common_row(
        target,
        raw_url=raw_url,
        title=title,
        status=status,
        category=category,
        labels=labels,
        pairs=pairs,
        kind="행사",
        image_url=image_url,
        item_id=event_no,
    )


def collect_national_hangeul_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    exhausted_scopes = 0

    for page in range(1, max_pages + 1):
        current_url = f"{HANGEUL_EDUCATION_LIST_URL}?{urlencode({'page': page, 'target': 0, 'showGubun': 0, 'curr_menu_cd': '0103010000', 'searchKeyword': ''})}"
        soup = fetch_soup(s, current_url, timeout=timeout)
        items = [item for item in soup.select(".apply-list > ul > li") if item.select_one(".go-view-page[data-program-no]")]
        if not items:
            if soup.select_one(".apply-list"):
                exhausted_scopes += 1
            break
        pages += 1
        pagination_detected = pagination_detected or page > 1 or bool(soup.select(".page-link.go-page, .pagination, .paging"))
        for item in items:
            row = hangeul_row_from_education_item(target, item, page)
            if not row:
                continue
            if detail_pages < max(0, detail_limit):
                try:
                    detail_soup = fetch_soup(s, row["raw_url"], timeout=timeout)
                    detail_pages += 1
                    hangeul_merge_detail(row, detail_soup)
                    row["raw_fields"]["detail_fetched"] = True
                except Exception as exc:
                    row["raw_fields"]["detail_error"] = str(exc)[:300]
                    logger.debug("national hangeul education detail fetch failed %s: %s", row.get("raw_url"), exc)
            rows.append(row)

    for event_type in ("1", "2"):
        for page in range(1, max_pages + 1):
            current_url = f"{HANGEUL_EVENT_LIST_URL}?{urlencode({'page': page, 'eventType': event_type, 'showGubun': 0, 'curr_menu_cd': '0103030100' if event_type == '1' else '0103030200', 'searchKeyword': ''})}"
            soup = fetch_soup(s, current_url, timeout=timeout)
            items = [item for item in soup.select(".gall-list > ul > li") if item.select_one(".go-view-page[data-event-no]")]
            if not items:
                if soup.select_one(".gall-list"):
                    exhausted_scopes += 1
                break
            pages += 1
            pagination_detected = pagination_detected or page > 1 or bool(soup.select(".page-link.go-page, .pagination, .paging"))
            for item in items:
                row = hangeul_row_from_event_item(target, item, page, event_type)
                if not row:
                    continue
                if detail_pages < max(0, detail_limit):
                    try:
                        detail_soup = fetch_soup(s, row["raw_url"], timeout=timeout)
                        detail_pages += 1
                        hangeul_merge_detail(row, detail_soup)
                        row["raw_fields"]["detail_fetched"] = True
                    except Exception as exc:
                        row["raw_fields"]["detail_error"] = str(exc)[:300]
                        logger.debug("national hangeul event detail fetch failed %s: %s", row.get("raw_url"), exc)
                rows.append(row)

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": exhausted_scopes == 3,
        "pagination_exhausted": exhausted_scopes == 3,
        "source_cap_reached": exhausted_scopes != 3,
        "exhausted_scopes": exhausted_scopes,
        "no_current_data": exhausted_scopes == 3 and not rows,
        "no_current_reason": (
            "official Hangeul Museum education and event lists are empty"
            if exhausted_scopes == 3 and not rows
            else ""
        ),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "national_hangeul_education_event", meta


NATIONAL_LIGHTHOUSE_EVENT_LIST_URL = "https://www.lighthouse-museum.or.kr/prog/evntPrgrm/kor/sub01_02/list.do"
NATIONAL_LIGHTHOUSE_EVENT_VIEW_URL = "https://www.lighthouse-museum.or.kr/prog/evntPrgrm/kor/sub01_02/view.do"
NATIONAL_LIGHTHOUSE_BRANCH = "국립등대박물관"
NATIONAL_LIGHTHOUSE_ADDRESS = "경상북도 포항시 남구 호미곶면 해맞이해안로150번길 20"


def lighthouse_list_url(page: int) -> str:
    if page <= 1:
        return NATIONAL_LIGHTHOUSE_EVENT_LIST_URL
    return f"{NATIONAL_LIGHTHOUSE_EVENT_LIST_URL}?{urlencode({'pageIndex': page})}"


def lighthouse_detail_url(prgrm_no: str) -> str:
    return f"{NATIONAL_LIGHTHOUSE_EVENT_VIEW_URL}?{urlencode({'prgrmNo': prgrm_no})}"


def lighthouse_label(value: str) -> str:
    return re.sub(r"[\s·:：\-_/]+", "", clean_text(value))


def lighthouse_get_pair(pairs: dict[str, str], *labels: str) -> str:
    normalized_labels = [lighthouse_label(label) for label in labels if label]
    for key, value in pairs.items():
        normalized_key = lighthouse_label(key)
        if any(label == normalized_key or label in normalized_key for label in normalized_labels):
            return clean_text(value)
    return ""


def lighthouse_pairs_from_scope(scope: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in scope.select(".list-1st li, ul.list2 li"):
        key_node = li.select_one(".tit")
        value_node = li.select_one(".con")
        key = clean_text(key_node.get_text(" ", strip=True) if key_node else "")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if not key or not value:
            cells = [clean_text(child.get_text(" ", strip=True)) for child in li.find_all(["span", "em", "strong"], recursive=False)]
            cells = [cell for cell in cells if cell]
            if len(cells) >= 2:
                key = key or cells[0]
                value = value or clean_text(" ".join(cells[1:]))
        if key and value:
            pairs[key] = value
    return pairs


def lighthouse_parse_date_token(token: str, default_year: int | None = None):
    text = re.sub(r"\([^)]*\)", "", clean_text(token)).strip(" .")
    numbers = re.findall(r"\d+", text)
    if len(numbers) >= 3 and len(numbers[0]) == 4:
        year, month, day = int(numbers[0]), int(numbers[1]), int(numbers[2])
    elif len(numbers) >= 2 and default_year:
        year, month, day = int(default_year), int(numbers[0]), int(numbers[1])
    else:
        return None
    try:
        return datetime(year, month, day).date()
    except ValueError:
        return None


def lighthouse_default_year(apply_period: str, raw_period: str) -> int | None:
    apply_start, _ = parse_date_range(apply_period)
    if apply_start:
        return apply_start.year
    match = re.search(r"(20\d{2})", clean_text(raw_period))
    return int(match.group(1)) if match else None


def normalize_lighthouse_period(raw_period: str, apply_period: str = "") -> str:
    text = clean_text(raw_period)
    if not text:
        return ""
    default_year = lighthouse_default_year(apply_period, text)
    month_range = re.search(r"(?<!\d)(\d{1,2})\s*월\s*[~\-]\s*(\d{1,2})\s*월", text)
    if month_range and default_year:
        start_month = int(month_range.group(1))
        end_month = int(month_range.group(2))
        end_year = default_year + 1 if end_month < start_month else default_year
        try:
            start = datetime(default_year, start_month, 1).date()
            end = datetime(end_year, end_month, calendar.monthrange(end_year, end_month)[1]).date()
            return f"{start.isoformat()} ~ {end.isoformat()}"
        except ValueError:
            pass

    date_tokens = re.findall(r"(?:20\d{2}\s*[.\-]\s*)?\d{1,2}\s*[.\-]\s*\d{1,2}", text)
    dates = []
    rolling_year = default_year
    for token in date_tokens:
        parsed = lighthouse_parse_date_token(token, rolling_year)
        if not parsed:
            continue
        if re.match(r"\s*20\d{2}", token):
            rolling_year = parsed.year
        if dates and parsed < dates[-1] and not re.match(r"\s*20\d{2}", token):
            try:
                parsed = datetime(dates[-1].year + 1, parsed.month, parsed.day).date()
            except ValueError:
                pass
        dates.append(parsed)
    if dates:
        if len(dates) == 1:
            return dates[0].isoformat()
        return f"{dates[0].isoformat()} ~ {dates[-1].isoformat()}"
    return text


def lighthouse_status_from_apply_period(apply_period: str) -> str:
    start, end = parse_date_range(apply_period)
    if not start and not end:
        return ""
    today = datetime.now().date()
    if start and today < start:
        return "접수예정"
    if end and today > end:
        return "접수마감"
    return "접수중"


def lighthouse_detail_description(soup: BeautifulSoup) -> str:
    view = soup.select_one(".list-wrap.view")
    if not view:
        text = clean_text(soup.get_text(" ", strip=True))
        if "상세내용" in text:
            return clean_text(text.split("상세내용", 1)[-1])[:2000]
        return ""

    parts: list[str] = []
    node = view.find_next_sibling()
    while node and len(parts) < 5:
        if getattr(node, "name", None):
            text = clean_text(node.get_text(" ", strip=True))
            if text:
                if "상세내용" in text:
                    text = clean_text(text.split("상세내용", 1)[-1])
                if text and not re.fullmatch(r"(목록|이전|다음|상단으로).*", text):
                    parts.append(text)
        node = node.find_next_sibling()
    return clean_text(" ".join(parts))[:2000]


def lighthouse_description_value(description: str, label: str) -> str:
    text = clean_text(description)
    if not text:
        return ""
    stop_labels = "대상|행사기간|교육기간|신청방법|준비물|재료비|문의|장소|시간"
    match = re.search(rf"{re.escape(label)}\s*[:：]?\s*(.+?)(?:\s+(?:{stop_labels})\s*[:：]?|$)", text)
    return clean_text(match.group(1)) if match else ""


def lighthouse_material_note(description: str) -> str:
    text = clean_text(description)
    if not text:
        return ""
    matches = re.findall(r"[^.?!]*?(?:준비물|재료비|재료|교재비)[^.?!]*(?:[.?!]|$)", text)
    return clean_text(" ".join(matches))[:500]


def lighthouse_image_url(base_url: str, src: str | None) -> str:
    if not src:
        return ""
    src = clean_text(src)
    if not src or src.startswith(("javascript:", "mailto:", "tel:", "#")):
        return ""
    absolute = urldefrag(urljoin(base_url, src))[0]
    parsed = urlparse(absolute)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return ""
    return absolute


def lighthouse_fee_from_description(description: str) -> str:
    text = clean_text(description)
    if not text:
        return ""
    match = re.search(r"(?:참가비|교육비|수강료|체험비|비용)\s*[:：]?\s*([^.,?!]+)", text)
    if not match:
        return ""
    value = clean_text(match.group(1))
    if "무료" in value:
        return "무료"
    amount = extract_krw_amount(value)
    return f"{amount:,}원" if amount else value[:80]


def lighthouse_row_from_item(target: CrawlTarget, item: BeautifulSoup, current_url: str) -> dict[str, Any] | None:
    button = item.select_one("[data-prgrm-no]")
    prgrm_no = clean_text(button.get("data-prgrm-no") if button else "")
    raw_url = lighthouse_detail_url(prgrm_no) if prgrm_no else current_url
    title_node = item.select_one(".title em, strong.title, .title")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    if not title or is_low_value_title(title):
        return None

    pairs = lighthouse_pairs_from_scope(item)
    tags = [clean_text(tag.get_text(" ", strip=True)) for tag in item.select(".tag span") if clean_text(tag.get_text(" ", strip=True))]
    application_method = next((tag for tag in tags if "예약" in tag or "접수" in tag), "")
    category = next((tag for tag in tags if tag != application_method), "") or "교육/행사"
    image = item.select_one(".thum img, img")
    image_url = lighthouse_image_url(current_url, image.get("src") if image else None)
    period_raw = lighthouse_get_pair(pairs, "교육/행사일시", "행사일시", "교육일시")
    apply_period = lighthouse_get_pair(pairs, "접수기간", "신청기간")
    venue = lighthouse_get_pair(pairs, "교육/행사장소", "행사장소", "교육장소", "장소")
    target_text = lighthouse_get_pair(pairs, "대상", "교육대상")
    status = lighthouse_status_from_apply_period(apply_period)

    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, NATIONAL_LIGHTHOUSE_BRANCH),
        "title": title,
        "branch": NATIONAL_LIGHTHOUSE_BRANCH,
        "branch_code": target.provider,
        "category": category,
        "raw_url": raw_url,
        "application_url": raw_url if application_method else "",
        "application_method_raw": application_method,
        "status": status,
        "period": normalize_lighthouse_period(period_raw, apply_period),
        "apply_period": apply_period,
        "schedule_raw": period_raw,
        "target": target_text,
        "room": venue,
        "venue_name": venue or NATIONAL_LIGHTHOUSE_BRANCH,
        "address": NATIONAL_LIGHTHOUSE_ADDRESS,
        "venue_address": NATIONAL_LIGHTHOUSE_ADDRESS,
        "image_url": image_url,
        "phone": lighthouse_get_pair(pairs, "문의", "전화"),
        "program_type": "강좌",
        "fee": "",
        "description": "",
        "reservation_available": "접수중" in status,
        "raw_fields": {"prgrm_no": prgrm_no, "list_url": current_url, "list_pairs": pairs, "tags": tags, "parser": "national_lighthouse_list"},
    }


def lighthouse_merge_detail(row: dict[str, Any], soup: BeautifulSoup) -> None:
    view = soup.select_one(".list-wrap.view") or soup
    pairs = lighthouse_pairs_from_scope(view)
    if pairs:
        period_raw = lighthouse_get_pair(pairs, "교육/행사일시", "행사일시", "교육일시") or row.get("schedule_raw", "")
        apply_period = lighthouse_get_pair(pairs, "접수기간", "신청기간") or row.get("apply_period", "")
        row["period"] = normalize_lighthouse_period(period_raw, apply_period) or row.get("period", "")
        row["apply_period"] = apply_period
        row["schedule_raw"] = period_raw
        row["room"] = lighthouse_get_pair(pairs, "교육/행사장소", "행사장소", "교육장소", "장소") or row.get("room", "")
        row["venue_name"] = row.get("room") or row.get("venue_name")
        row["target"] = lighthouse_get_pair(pairs, "대상", "교육대상") or row.get("target", "")
        row["phone"] = lighthouse_get_pair(pairs, "문의", "전화") or row.get("phone", "")
        row["raw_fields"]["detail_pairs"] = pairs

    title_node = view.select_one(".title em, strong.title, .title")
    detail_title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    if detail_title:
        row["title"] = detail_title

    detail_image = view.select_one(".thum img, img")
    detail_image_url = lighthouse_image_url(row.get("raw_url", ""), detail_image.get("src") if detail_image else None)
    if detail_image_url:
        row["image_url"] = detail_image_url

    description = lighthouse_detail_description(soup)
    if description:
        row["description"] = description
        detail_target = lighthouse_description_value(description, "대상")
        if detail_target:
            row["target"] = detail_target
            row["eligibility_raw"] = detail_target
        material_note = lighthouse_material_note(description)
        if material_note:
            row["material_note"] = material_note
        material_fee = extract_material_fee_amount(description)
        if material_fee:
            row["material_fee"] = material_fee
        fee = lighthouse_fee_from_description(description)
        if fee:
            row["fee"] = fee
        capacity = lighthouse_description_value(description, "정원") or lighthouse_description_value(description, "인원")
        if not capacity:
            capacity_match = re.search(r"(?:차수\s*당\s*)?\d+\s*(?:명|가구)(?:\s*/\s*[^,.)]+)?", description)
            capacity = clean_text(capacity_match.group(0)) if capacity_match else ""
        if capacity:
            row["capacity"] = capacity


def collect_national_lighthouse_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    pagination_exhausted = False

    for page in range(1, max_pages + 1):
        current_url = lighthouse_list_url(page)
        soup = fetch_soup(s, current_url, timeout=timeout)
        items = soup.select(".list-wrap .item")
        if not items:
            pagination_exhausted = True
            break
        pages += 1
        pagination_detected = pagination_detected or page > 1 or bool(soup.select(".pagination, .paging, a[href*='pageIndex']"))
        for item in items:
            row = lighthouse_row_from_item(target, item, current_url)
            if not row:
                continue
            if detail_pages < max(0, detail_limit) and row.get("raw_url"):
                try:
                    detail_soup = fetch_soup(s, row["raw_url"], timeout=timeout)
                    detail_pages += 1
                    lighthouse_merge_detail(row, detail_soup)
                    row["raw_fields"]["detail_fetched"] = True
                except Exception as exc:
                    row["raw_fields"]["detail_error"] = str(exc)[:300]
                    logger.debug("national lighthouse detail fetch failed %s: %s", row.get("raw_url"), exc)
            rows.append(row)
        if len(items) < 20:
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "national_lighthouse_event_programs", meta


PALACE_MUSEUM_EDU_LIST_URL = "https://www.gogung.go.kr/gogung/pgm/cultureEventReg/edu/list.do"
PALACE_MUSEUM_EDU_VIEW_URL = "https://www.gogung.go.kr/gogung/pgm/cultureEventReg/edu/updtView.do"
PALACE_MUSEUM_ADDRESS = "서울특별시 종로구 효자로 12"


def palace_museum_status(value: str) -> str:
    text = clean_text(value)
    if not text:
        return ""
    if any(token in text for token in ("마감", "종료", "완료")):
        return "CLOSED"
    if "대기" in text:
        return "WAITING"
    if any(token in text for token in ("준비", "예정")):
        return "SCHEDULED"
    if any(token in text for token in ("접수", "신청", "모집")):
        return "OPEN"
    return text


def palace_museum_card_pairs(item: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select("ul.list > li"):
        key = clean_text((li.select_one(".title") or li.find("span")).get_text(" ", strip=True) if li.select_one(".title") or li.find("span") else "")
        value_node = li.select_one(".text")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if key and value:
            pairs[key] = value
    return pairs


def palace_museum_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for tr in soup.select("table tr"):
        cells = tr.find_all(["th", "td"], recursive=False)
        if len(cells) != 2:
            continue
        key = clean_text(cells[0].get_text(" ", strip=True))
        value = clean_text(cells[1].get_text(" ", strip=True))
        if key and value:
            pairs[key] = value
    return pairs


def palace_museum_session_rows(soup: BeautifulSoup) -> list[dict[str, Any]]:
    sessions: list[dict[str, Any]] = []
    for tr in soup.select("table tr"):
        text = clean_text(tr.get_text(" ", strip=True))
        if "교육일자" not in text or "교육시간" not in text:
            continue
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
        if len(cells) < 8:
            continue
        current, total = parse_capacity_pair(cells[5])
        wait_current, wait_total = parse_capacity_pair(cells[6])
        date_match = re.search(r"교육일자\s*(\d{4})-(\d{1,2})-(\d{1,2})", cells[2])
        time_match = re.search(r"교육시간\s*([0-9:]{4,5}\s*[~-]\s*[0-9:]{4,5})", cells[3])
        apply_match = re.search(
            r"교육신청기간\s*(\d{4})-(\d{1,2})-(\d{1,2})\s*~\s*(\d{4})-(\d{1,2})-(\d{1,2})",
            cells[4],
        )
        session_date = f"{date_match.group(1)}-{int(date_match.group(2)):02d}-{int(date_match.group(3)):02d}" if date_match else ""
        apply_period = (
            f"{apply_match.group(1)}-{int(apply_match.group(2)):02d}-{int(apply_match.group(3)):02d}"
            f" ~ {apply_match.group(4)}-{int(apply_match.group(5)):02d}-{int(apply_match.group(6)):02d}"
            if apply_match
            else ""
        )
        session_no_match = re.search(r"\d+", cells[0])
        sessions.append(
            {
                "session_no": session_no_match.group(0) if session_no_match else str(len(sessions) + 1),
                "session_title": clean_text(re.sub(r"^교육명\s*", "", cells[1])),
                "date": session_date,
                "time": clean_text(time_match.group(1).replace("~", "-")) if time_match else clean_text(re.sub(r"^교육시간\s*", "", cells[3])),
                "apply_period": apply_period,
                "capacity_current": current,
                "capacity_total": total,
                "waitlist_current": wait_current,
                "waitlist_total": wait_total,
                "status": clean_text(re.sub(r"^접수현황\s*", "", cells[7])),
                "raw_cells": cells,
            }
        )
    return sessions


def palace_museum_detail_description(soup: BeautifulSoup, title: str, pairs: dict[str, str]) -> str:
    parts = []
    for key in ("기타사항", "신청방법", "문의"):
        if pairs.get(key):
            parts.append(f"{key}: {pairs[key]}")
    content = soup.select_one(".view-content, .board-view, .edu-view, .content")
    if content:
        content_text = clean_text(content.get_text(" ", strip=True))
        if content_text and title in content_text:
            content_text = clean_text(content_text.split(title, 1)[-1])
        if content_text:
            parts.append(content_text[:1600])
    return clean_text(" ".join(parts))[:2000]


def collect_palace_museum_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    seen_courses: set[str] = set()
    base_query = parse_qs(urlparse(target.url).query)
    menu_no = (base_query.get("menuNo") or ["800212"])[0]
    search_edu_div = (base_query.get("searchEduDiv") or [""])[0]

    for page in range(1, max_pages + 1):
        query = {"menuNo": menu_no, "pageIndex": str(page)}
        if search_edu_div:
            query["searchEduDiv"] = search_edu_div
        current_url = f"{PALACE_MUSEUM_EDU_LIST_URL}?{urlencode(query)}"
        soup = fetch_soup(s, current_url, timeout=timeout)
        items = soup.select("ul.board-gallery.type5 > li, .board-gallery.type5 > li")
        if not items:
            break
        pages += 1
        pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='pageIndex']"))

        for item in items:
            link = item.find("a")
            href = clean_text(link.get("href") if link else "")
            match = re.search(r"modify\('([^']+)'\)", href)
            culture_seq = match.group(1) if match else ""
            if not culture_seq or culture_seq in seen_courses:
                continue
            seen_courses.add(culture_seq)

            title = clean_text((item.select_one("p.subject") or item).get_text(" ", strip=True))
            if not title or is_low_value_title(title):
                continue
            tags = [clean_text(tag.get_text(" ", strip=True)) for tag in item.select(".category .sort") if clean_text(tag.get_text(" ", strip=True))]
            status_raw = next((tag for tag in tags if any(token in tag for token in ("접수", "마감", "준비", "신청"))), "")
            category = next((tag for tag in tags if tag != status_raw and tag not in {"대면", "비대면"}), "교육")
            onoff = next((tag for tag in tags if tag in {"대면", "비대면"}), "")
            card_pairs = palace_museum_card_pairs(item)
            image = item.find("img")
            image_url = normalize_link(current_url, image.get("src") if image else None)
            raw_url = f"{PALACE_MUSEUM_EDU_VIEW_URL}?{urlencode({'menuNo': menu_no, 'cultureSeq': culture_seq})}"

            detail_pairs: dict[str, str] = {}
            sessions: list[dict[str, str]] = []
            description = ""
            if detail_pages < max(1, detail_limit):
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_pages += 1
                    detail_pairs = palace_museum_detail_pairs(detail_soup)
                    sessions = palace_museum_session_rows(detail_soup)
                    description = palace_museum_detail_description(detail_soup, title, detail_pairs)
                    detail_image = detail_soup.select_one("table img[src*='imageSrc.do'], .board-view img[src*='imageSrc.do'], img[src*='imageSrc.do']")
                    detail_image_url = normalize_link(raw_url, detail_image.get("src") if detail_image else None)
                    if detail_image_url and "main_logo" not in detail_image_url:
                        image_url = detail_image_url
                except Exception as exc:
                    logger.debug("palace museum detail fetch failed %s: %s", raw_url, exc)

            common = {
                "provider": target.provider,
                "title": clean_text(detail_pairs.get("교육명") or title),
                "branch": "국립고궁박물관",
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status_raw,
                "fee": clean_text(detail_pairs.get("수강료") or card_pairs.get("수강료")),
                "material_fee": extract_material_fee_amount(description),
                "period": clean_text(detail_pairs.get("교육일정") or card_pairs.get("교육 일정")),
                "schedule_raw": clean_text(detail_pairs.get("요일/시간") or detail_pairs.get("교육시간")),
                "target": clean_text(detail_pairs.get("교육대상") or card_pairs.get("교육대상")),
                "room": clean_text(detail_pairs.get("교육장소")),
                "venue_name": clean_text(detail_pairs.get("장소") or detail_pairs.get("교육장소") or "국립고궁박물관"),
                "venue_address": PALACE_MUSEUM_ADDRESS,
                "address": PALACE_MUSEUM_ADDRESS,
                "apply_period": clean_text(detail_pairs.get("접수일시") or detail_pairs.get("접수기간")),
                "application_method_raw": clean_text(detail_pairs.get("접수방법")),
                "description": description,
                "image_url": image_url,
                "program_type": "강좌",
                "raw_fields": {
                    "parser": "palace_museum_edu_cards",
                    "culture_seq": culture_seq,
                    "tags": tags,
                    "onoff": onoff,
                    "card_pairs": card_pairs,
                    "detail_pairs": detail_pairs,
                },
            }

            if sessions:
                for session_row in sessions:
                    row = dict(common)
                    session_date = clean_text(session_row.get("date"))
                    session_time = clean_text(session_row.get("time"))
                    row["provider_course_id"] = f"{culture_seq}:{session_row.get('session_no')}"
                    row["raw_url"] = stable_list_item_url(
                        raw_url,
                        target.provider,
                        common["title"],
                        common["branch"],
                        culture_seq,
                        session_row.get("session_no"),
                        session_date,
                        session_time,
                    )
                    if session_date:
                        row["period"] = session_date
                        row["schedule_dates"] = [session_date]
                    if session_time:
                        row["schedule_raw"] = session_time
                    row["apply_period"] = session_row.get("apply_period") or row.get("apply_period", "")
                    row["capacity_current"] = session_row.get("capacity_current")
                    row["capacity_total"] = session_row.get("capacity_total")
                    row["waitlist_total"] = session_row.get("waitlist_total")
                    row["status"] = palace_museum_status(session_row.get("status") or status_raw)
                    row["raw_fields"] = {**common["raw_fields"], "session": session_row}
                    rows.append(row)
            else:
                row = dict(common)
                row["provider_course_id"] = culture_seq
                row["status"] = palace_museum_status(status_raw)
                rows.append(row)

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "palace_museum_edu_cards+detail", meta


DAEGU_NATIONAL_SCIENCE_SOURCES = (
    ("personal_science", "https://www.dnsm.or.kr/scienceClassroom/personalScienceEdu.do"),
    ("infinite_imagination", "https://www.dnsm.or.kr/scienceClassroom/muhanSangSangIndividual.do"),
    ("convergence", "https://www.dnsm.or.kr/scienceClassroom/convergenceEdu.do"),
    ("lab_education", "https://www.dnsm.or.kr/scienceClassroom/labEducation.do"),
)


def collect_daegu_national_science(target: CrawlTarget, timeout: int, max_pages: int) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    host = parsed.netloc or "www.dnsm.or.kr"
    s.cookies.set("sabFingerPrint", "1920,1080," + host, domain=host)
    s.cookies.set("sabSignature", "erJ66uEFuMacoJl/LW1J+A==", domain=host)
    source_items: list[tuple[str, str, Any]] = []
    source_counts: dict[str, int] = {}
    pages = 0
    unhandled_pagination = False
    for source_key, source_url in DAEGU_NATIONAL_SCIENCE_SOURCES[: max(1, max_pages)]:
        source_soup = fetch_soup(s, source_url, timeout=timeout)
        pages += 1
        items = source_soup.select("ul.rsv-list > li")[: max(20, max_pages * 20)]
        unhandled_pagination = unhandled_pagination or bool(
            source_soup.select(
                ".paging a[href], .pagination a[href], "
                "a[href*='pageIndex='], a[onclick*='pageIndex']"
            )
        )
        source_counts[source_key] = len(items)
        source_items.extend((source_key, source_url, item) for item in items)
    stop_labels = {"카테고리", "기간", "운영시간", "이용대상", "대상", "장소", "비용", "문의"}
    rows: list[dict[str, Any]] = []
    for source_key, source_url, item in source_items:
        lines = [clean_text(line) for line in item.get_text("\n", strip=True).splitlines() if clean_text(line)]
        if not lines:
            continue
        title = lines[0]
        if is_low_value_title(title):
            continue
        category = values_after_line(lines, "카테고리", stop_labels)
        period = values_after_line(lines, "기간", stop_labels)
        schedule = values_after_line(lines, "운영시간", stop_labels)
        target_text = values_after_line(lines, "이용대상", stop_labels)
        extra_target = values_after_line(lines, "대상", stop_labels)
        if extra_target and extra_target not in target_text:
            target_text = clean_text(" ".join(part for part in [target_text, extra_target] if part))
        room = values_after_line(lines, "장소", stop_labels)
        fee = values_after_line(lines, "비용", stop_labels)
        method = "온라인접수" if "온라인접수" in lines else "현장접수" if "현장접수" in lines else ""
        status = "접수중" if method == "온라인접수" else method
        href = ""
        for a in item.find_all("a", href=True):
            if "goDetail" in a.get("href", ""):
                href = a.get("href")
                break
        menu_id = ""
        match = re.search(r"goDetail\((\d+)\)", href or "")
        if match:
            menu_id = match.group(1)
        raw_url = urljoin(source_url, f"/reservation/detail.do?searchMenuId={menu_id}") if menu_id else source_url
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "category": category,
                "raw_url": raw_url,
                "application_url": raw_url if method == "온라인접수" else "",
                "status": status,
                "period": period,
                "schedule_raw": schedule or period,
                "target": target_text,
                "room": room,
                "venue_name": room,
                "fee": fee,
                "application_method_raw": method,
                "description": clean_text(" ".join(lines)),
                "reservation_available": method == "온라인접수",
                "raw_fields": {
                    "lines": lines,
                    "menu_id": menu_id,
                    "source_key": source_key,
                    "source_url": source_url,
                    "parser": "daegu_national_science",
                },
            }
        )
    source_fanout_complete = pages == len(DAEGU_NATIONAL_SCIENCE_SOURCES)
    pagination_complete = source_fanout_complete and not unhandled_pagination
    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(source_items),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": unhandled_pagination,
        "pagination_complete": pagination_complete,
        "source_cap_reached": not pagination_complete,
        "recursion_depth": 0,
        "source_counts": source_counts,
    }
    return dedupe_rows(rows), "daegu_national_science", meta


