def sejong_lifelong_category_map(s: requests.Session, timeout: int) -> dict[str, str]:
    try:
        response = s.post(
            f"{SEJONG_LIFELONG_API_BASE}/getCodeList",
            data={"manage_code": SEJONG_LIFELONG_MANAGE_CODE, "class": "763"},
            headers={"Referer": SEJONG_LIFELONG_LIST_URL},
            timeout=timeout,
        )
        response.raise_for_status()
        payload = response.json()
    except Exception as exc:
        logger.debug("sejong lifelong category fetch failed: %s", exc)
        return {}
    return {
        clean_text(item.get("CODE")): clean_text(item.get("DESCRIPTION"))
        for item in payload.get("LIST") or []
        if clean_text(item.get("CODE")) and clean_text(item.get("DESCRIPTION"))
    }


def sejong_lifelong_detail(s: requests.Session, rec_key: str, timeout: int) -> dict[str, Any]:
    if not rec_key:
        return {}
    try:
        response = s.post(
            f"{SEJONG_LIFELONG_API_BASE}/homepageprogramdetail",
            data={"manage_code": SEJONG_LIFELONG_MANAGE_CODE, "rec_key": rec_key},
            headers={"Referer": SEJONG_LIFELONG_LIST_URL},
            timeout=timeout,
        )
        response.raise_for_status()
        payload = response.json()
    except Exception as exc:
        logger.debug("sejong lifelong detail fetch failed rec_key=%s: %s", rec_key, exc)
        return {}
    data = payload.get("RESULT_DATA")
    return data if isinstance(data, dict) else {}


def sejong_lifelong_target(item: dict[str, Any], category: str) -> str:
    for key in (
        "PROGRAM_TARGET_DESC",
        "PROGRAM_TARGET",
        "TARGET_DESC",
        "TARGET",
        "APPLY_TARGET_DESC",
        "APPLY_TARGET_MEMBER_TYPE_DESC",
    ):
        value = clean_text(item.get(key))
        if value:
            return value
    category_text = clean_text(category)
    if any(token in category_text for token in ("영아", "유아", "어린이", "아동", "청소년", "초등", "중등", "고등", "성인", "노인")):
        return category_text.split(">")[-1].strip()
    return "전체"


def sejong_lifelong_is_expired(item: dict[str, Any]) -> bool:
    end_date_text = sejong_lifelong_date(item.get("PROGRAM_END_DATE") or item.get("PROGRAM_END_DT"))
    if not end_date_text:
        return False
    try:
        return datetime.strptime(end_date_text, "%Y-%m-%d").date() < datetime.now().date()
    except ValueError:
        return False


def sejong_lifelong_row_from_item(
    target: CrawlTarget,
    item: dict[str, Any],
    category_map: dict[str, str],
    detail: Optional[dict[str, Any]] = None,
) -> dict[str, Any]:
    merged = dict(item)
    if detail:
        merged.update({key: value for key, value in detail.items() if value not in (None, "")})

    rec_key = clean_text(merged.get("REC_KEY"))
    title = clean_text(merged.get("PROGRAM_TITLE") or merged.get("CJK_PROGRAM_TITLE") or merged.get("CTX_PROGRAM_TITLE"))
    raw_url = f"{SEJONG_LIFELONG_BASE_URL}/edu/community/events/program-detail/{rec_key}" if rec_key else target.url
    major_code = clean_text(merged.get("PROGRAM_MAJOR_CATEGORY"))
    major_category = clean_text(category_map.get(major_code))
    sub_category = clean_text(merged.get("PROGRAM_SUB_CATEGORY_DESC"))
    category = clean_text(" > ".join(part for part in (major_category, sub_category) if part))
    description = sejong_lifelong_clean_html(merged.get("PROGRAM_DESC") or merged.get("PROGRAM_DESC_TEXT"))
    start_time = sejong_lifelong_time(merged.get("PROGRAM_START_TIME"))
    end_time = sejong_lifelong_time(merged.get("PROGRAM_END_TIME"))
    time_range = f"{start_time}~{end_time}" if start_time and end_time else start_time or end_time
    days = sejong_lifelong_days(merged.get("PROGRAM_DAYS"))
    schedule = clean_text(" ".join(part for part in (days, time_range) if part))
    period = sejong_lifelong_date_range(merged.get("PROGRAM_START_DATE"), merged.get("PROGRAM_END_DATE"))
    apply_period = sejong_lifelong_date_range(merged.get("PROGRAM_APPLY_START_DATE"), merged.get("PROGRAM_APPLY_END_DATE"))
    material_fee = sejong_lifelong_fee(merged.get("MATERIAL_COST"))
    if material_fee == "무료":
        material_fee = ""
    status = sejong_lifelong_status(merged.get("PROGRAM_STATUS"))
    online_closed = clean_text(merged.get("ONLINE_CLOSED")).upper() == "Y"
    reservation_available = status in {"접수중", "접수대기"} and not online_closed
    total = clean_text(merged.get("RECRUITMENT_PERSONNEL_CNT") or merged.get("ONLINE_RECRUITMENT_CNT"))
    current = clean_text(merged.get("NOW_APPLY_CNT") or merged.get("NOW_ONLINE_APPLY_CNT"))

    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
        "title": title,
        "branch": target.branch,
        "branch_code": SEJONG_LIFELONG_BRANCH_CODE,
        "branch_url": SEJONG_LIFELONG_LIST_URL,
        "preserve_branch": True,
        "address": SEJONG_LIFELONG_ADDRESS,
        "venue_address": SEJONG_LIFELONG_ADDRESS,
        "category": category,
        "raw_url": raw_url,
        "application_url": raw_url if reservation_available else "",
        "reservation_available": reservation_available,
        "status": status,
        "fee": sejong_lifelong_fee(merged.get("PROGRAM_FEE")),
        "material_fee": material_fee,
        "material_note": f"재료비 {material_fee}" if material_fee else "",
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": schedule,
        "target": sejong_lifelong_target(merged, category),
        "capacity": f"{current}/{total}" if current and total else total,
        "capacity_total": total,
        "capacity_current": current,
        "waitlist_total": clean_text(merged.get("WAITING_PERSONNEL_CNT")),
        "room": clean_text(merged.get("PROGRAM_FACILITY_NAME") or merged.get("CJK_PROGRAM_FACILITY_NAME")),
        "venue_name": clean_text(merged.get("PROGRAM_FACILITY_NAME") or merged.get("CJK_PROGRAM_FACILITY_NAME")),
        "instructor": clean_text(merged.get("PROGRAM_INSTRUCTOR_NAME") or merged.get("CJK_PROGRAM_INSTRUCTOR_NAME")),
        "description": description,
        "image_url": clean_text(merged.get("THUMBNAIL_PATH")),
        "application_method_raw": "온라인 접수" if reservation_available else "",
                        "program_type": "\uAC15\uC88C",
        "collection_category": "평생학습",
        "domain_category": "평생학습",
        "source_group": "lifelong_learning",
        "operator_type": "교육청/공공기관",
        "collection_type": "api",
        "raw_fields": public_raw_fields(merged) | {
            "parser": "sejong_lifelong_program_api",
            "major_category_desc": major_category,
            "detail_url": raw_url,
        },
    }


def collect_sejong_lifelong_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Accept": "application/json,text/plain,*/*", "Referer": SEJONG_LIFELONG_LIST_URL})
    category_map = sejong_lifelong_category_map(s, timeout)
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    total_count = 0
    raw_row_count = 0
    pagination_detected = False
    status_queries = ("1and2and6", "3", "5")
    status_counts: dict[str, int] = {}
    page_size = 60

    for status_query in status_queries:
        for page in range(1, max(1, max_pages) + 1):
            data = {
                "manage_code": SEJONG_LIFELONG_MANAGE_CODE,
                "search_type": "title",
                "page_no": str(page),
                "display": str(page_size),
                "orderby_item": "PROGRAM_DATE",
                "orderby": "DESC",
                "program_status": status_query,
            }
            response = s.post(
                f"{SEJONG_LIFELONG_API_BASE}/homepageprogramlist",
                data=data,
                timeout=timeout,
            )
            response.raise_for_status()
            payload = response.json()
            items = payload.get("RESULT_LIST") or []
            query_total = int(payload.get("TOTAL_COUNT") or payload.get("TOTAL") or len(items))
            total_count += query_total if page == 1 else 0
            status_counts[status_query] = query_total
            if query_total > page_size:
                pagination_detected = True
            if not items:
                break

            pages += 1
            raw_row_count += len(items)
            for item in items:
                if not isinstance(item, dict) or sejong_lifelong_is_expired(item):
                    continue
                rec_key = clean_text(item.get("REC_KEY"))
                detail: dict[str, Any] = {}
                if detail_limit > 0 and detail_pages < detail_limit and rec_key:
                    detail = sejong_lifelong_detail(s, rec_key, timeout)
                    if detail:
                        detail_pages += 1
                row = sejong_lifelong_row_from_item(target, item, category_map, detail=detail)
                if row.get("title"):
                    rows.append(row)

            if query_total and page * page_size >= query_total:
                break
            if len(items) < page_size:
                break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "total_count": total_count,
        "raw_row_count": raw_row_count,
        "status_counts": status_counts,
    }
    return dedupe_rows(rows), "sejong_lifelong_program_api", meta


def fmcs_fee_text(value: Any) -> str:
    fee = clean_text(value)
    if not fee:
        return ""
    if fee in {"0", "0.0"}:
        return "\ubb34\ub8cc"
    if "\uc6d0" in fee or fee in {"\ubb34\ub8cc", "\uc720\ub8cc"}:
        return fee
    return f"{fee}\uc6d0"


def fmcs_detail_text(lines: list[str], label: str) -> str:
    stops = {
        "\uac15\uc88c \uc18c\uac1c",
        "\uac15\uc88c \ub0b4\uc6a9",
        "\uac15\uc0ac \uc548\ub0b4",
        "\ubaa9\ub85d\uc73c\ub85c",
        "\uac1c\uc778\uc815\ubcf4\ucc98\ub9ac\ubc29\uce68",
        "\uc774\uc6a9\uc57d\uad00",
    }
    for index, line in enumerate(lines):
        if clean_text(line).rstrip(":") != label:
            continue
        values: list[str] = []
        for value in lines[index + 1 :]:
            value = clean_text(value)
            if not value:
                continue
            if value.rstrip(":") in stops:
                break
            values.append(value)
        return clean_text(" ".join(values))
    return ""


def fmcs_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    pairs = pairs_from_tables(soup)
    for dl in soup.select(".proc_read dl"):
        dt = dl.find("dt")
        dd = dl.find("dd")
        key = clean_text(dt.get_text(" ", strip=True) if dt else "")
        value = clean_text(dd.get_text(" ", strip=True) if dd else "")
        if key and value:
            pairs[key] = value
    lines = lines_from_soup(soup)
    intro = fmcs_detail_text(lines, "\uac15\uc88c \uc18c\uac1c")
    content = fmcs_detail_text(lines, "\uac15\uc88c \ub0b4\uc6a9")
    description = clean_text(" ".join(part for part in [intro, content] if part))
    period = clean_text(pairs.get("\uad50\uc721\uae30\uac04") or pairs.get("\uc218\uac15\uae30\uac04"))
    fees: list[str] = []
    periods: list[str] = []
    for table in soup.select("table"):
        headers = [clean_text(cell.get_text(" ", strip=True)) for cell in table.select("thead th")]
        if not headers:
            continue
        period_index = headers.index("\uc218\uac15\uae30\uac04") if "\uc218\uac15\uae30\uac04" in headers else -1
        fee_index = headers.index("\uc218\uac15\ub8cc") if "\uc218\uac15\ub8cc" in headers else -1
        if period_index < 0 and fee_index < 0:
            continue
        for row in table.select("tbody tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in row.find_all(["th", "td"])]
            if period_index >= 0 and period_index < len(cells):
                value = clean_text(cells[period_index])
                if value:
                    periods.append(value)
            if fee_index >= 0 and fee_index < len(cells):
                value = clean_text(cells[fee_index])
                if value:
                    fees.append(value)
    if not period and periods:
        period = clean_text(" / ".join(dict.fromkeys(periods)))
    schedule = clean_text(pairs.get("\uc2dc\uac04/\uc694\uc77c"))
    center = clean_text(pairs.get("\uc6b4\uc601\uc13c\ud130"))
    if center and "/" in center:
        center = clean_text(center.split("/", 1)[0])
    return {
        "title": clean_text(pairs.get("\uac15\uc88c\uba85")),
        "branch": center,
        "period": period,
        "schedule_raw": schedule,
        "target": clean_text(pairs.get("\uad50\uc721\ub300\uc0c1")),
        "instructor": clean_text(pairs.get("\uac15\uc0ac\uba85")),
        "application_method_raw": clean_text(pairs.get("\uc811\uc218\ubc29\ubc95")),
        "fee": clean_text(" / ".join(dict.fromkeys(fees))),
        "capacity": clean_text(pairs.get("\uc2e0\uccad\uc778\uc6d0/\uc815\uc6d0")),
        "venue_name": clean_text(pairs.get("\uac15\uc2b5\uc7a5\uc18c") or pairs.get("\uad50\uc721\uc7a5\uc18c")),
        "description": description,
        "raw_detail_pairs": pairs,
    }


def fmcs_row_from_api_item(
    target: CrawlTarget,
    target_url: str,
    item: dict[str, Any],
    search_type: str,
    category_context: Optional[dict[str, str]] = None,
) -> dict[str, Any]:
    category_context = category_context or {}
    title = clean_text(item.get("class_nm"))
    branch = clean_text(item.get("comnm")) or target.branch
    comcd = clean_text(item.get("comcd"))
    class_cd = clean_text(item.get("class_cd"))
    read_query = urlencode({"action": "read", "comcd": comcd, "classcd": class_cd, "type": search_type or clean_text(item.get("status"))})
    raw_url = f"{target_url.split('?', 1)[0]}?{read_query}"
    start_time = clean_text(item.get("train_stime"))
    end_time = clean_text(item.get("train_etime"))
    train_day = clean_text(item.get("train_day_nm"))
    schedule = clean_text(f"{train_day} {start_time}~{end_time}") if start_time and end_time else train_day
    start_date = clean_text(item.get("train_sdate"))
    end_date = clean_text(item.get("train_edate"))
    period = f"{start_date} ~ {end_date}" if start_date and end_date else ""
    period_fallback = clean_text(item.get("category1") or category_context.get("category_path"))
    if not period and re.search(r"\d", period_fallback):
        period = period_fallback
    if not period and "ijongno.co.kr" in target_url:
        period = "월 단위 상시 강좌"
    reg_person = clean_text(item.get("reg_person"))
    capa = clean_text(item.get("capa"))
    capacity = f"{reg_person}/{capa}" if reg_person and capa else capa
    status_code = clean_text(item.get("status")).upper()
    status_text = fmcs_status_text(status_code)
    application_url = raw_url if status_code in {"R", "RW", "W"} else ""
    api_category = clean_text(" > ".join(part for part in [clean_text(item.get("category1")), clean_text(item.get("category2"))] if part))
    query_category = clean_text(category_context.get("category_path"))
    target_text = clean_text(
        item.get("target")
        or item.get("target_nm")
        or item.get("class_target")
        or item.get("use_target")
        or item.get("age_nm")
        or item.get("target_age_name")
    )
    instructor = clean_text(item.get("teacher_name"))
    fee = fmcs_fee_text(item.get("course_fee"))
    description = clean_text(
        " ".join(
            part
            for part in [api_category or query_category, branch, period, schedule, target_text, fee, instructor, status_text]
            if part
        )
    )
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, f"{comcd}:{class_cd}", title, branch),
        "title": title,
        "branch": branch,
        "branch_code": comcd or branch,
        "category": api_category or query_category,
        "raw_url": raw_url,
        "application_url": application_url,
        "status": status_text,
        "fee": fee,
        "period": period,
        "schedule_raw": schedule,
        "target": target_text,
        "instructor": instructor,
        "capacity": capacity,
        "venue_name": branch,
        "application_method_raw": clean_text(
            item.get("apply_method")
            or item.get("receipt_method")
            or item.get("reg_method")
        ),
        "description": description,
        "raw_fields": {
            "parser": "fmcs_lecture_api",
            "search_type": search_type,
            "category_context": category_context,
            "item": item,
        },
    }


YSSPORTS_FMCS_URL = "https://yssports.yong-san.or.kr/fmcs/8?center=YGSN01"
YSSPORTS_BRANCH_ADDRESSES = {
    "문화체육센터": "서울특별시 용산구 백범로 350",
    "이태원초등학교수영장": "서울특별시 용산구 녹사평대로 19",
    "구민체력단련장": "서울특별시 용산구 녹사평대로 150",
}


def yssports_category_name_map(
    s: requests.Session,
    root_url: str,
    method: str,
    referer: str,
    timeout: int,
) -> tuple[dict[tuple[str, str], dict[str, str]], int]:
    companies = fmcs_json_rows(
        fmcs_request_json(s, root_url, "rest/common/company", {"type": "L"}, method, referer, timeout)
    )
    contexts_by_name: dict[tuple[str, str], dict[str, str]] = {}
    combo_count = 0
    for company in companies:
        comcd = clean_text(company.get("comcd"))
        if not comcd:
            continue
        for context in fmcs_category_contexts(s, root_url, comcd, method, referer, timeout):
            category_name = clean_text(context.get("category_name"))
            parent_name = clean_text(context.get("parent_category_name"))
            top_name = clean_text(context.get("top_category_name"))
            category_path = clean_text(context.get("category_path"))
            combo_count += 1
            if category_name:
                contexts_by_name[(comcd, category_name)] = context
            if parent_name:
                contexts_by_name.setdefault((comcd, parent_name), context)
            if top_name:
                contexts_by_name.setdefault((comcd, top_name), context)
            if category_path:
                contexts_by_name.setdefault((comcd, category_path), context)
    return contexts_by_name, combo_count


def collect_yssports_fmcs_categories(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    root_url = fmcs_root_url(YSSPORTS_FMCS_URL)
    referer = YSSPORTS_FMCS_URL
    s.get(referer, timeout=timeout, verify=True)
    method = fmcs_http_method(s, root_url, referer, timeout)
    category_map, category_combo_count = yssports_category_name_map(s, root_url, method, referer, timeout)

    rows: list[dict[str, Any]] = []
    raw_row_count = 0
    api_pages = 0
    api_requests = 0
    total_count = 0
    pagination_detected = False
    page_size = 100
    page_limit = max(1, max_pages)

    for page in range(1, page_limit + 1):
        params = {
            "comcd": "",
            "type": "R",
            "event": "",
            "class": "",
            "page": str(page),
            "page_size": str(page_size),
        }
        data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
        api_requests += 1
        list_rows = fmcs_json_rows(data)
        if not list_rows:
            break
        api_pages += 1
        raw_row_count += len(list_rows)
        page_total_count = fmcs_int(list_rows[0].get("total_count"))
        total_count = max(total_count, page_total_count)
        pagination_detected = pagination_detected or page_total_count > page_size

        for item in list_rows:
            raw_title = clean_text(item.get("class_nm"))
            if any(token in raw_title.upper() for token in ("TEST", "\ud14c\uc2a4\ud2b8")) or "\uc2e0\uccad\uae08\uc9c0" in raw_title:
                continue
            comcd = clean_text(item.get("comcd"))
            category2 = clean_text(item.get("category2"))
            category1 = clean_text(item.get("category1"))
            category_context = category_map.get((comcd, category2)) or category_map.get((comcd, category1)) or {}
            row = fmcs_row_from_api_item(target, YSSPORTS_FMCS_URL, item, "R", category_context)
            branch = clean_text(row.get("branch"))
            address = YSSPORTS_BRANCH_ADDRESSES.get(branch, "")
            row.update(
                {
                    "address": address,
                    "venue_address": address,
                    "branch_url": YSSPORTS_FMCS_URL,
                    "preserve_branch": True,
                    "program_type": "강좌",
                    "collection_category": "체육/스포츠",
                    "domain_category": "체육/스포츠",
                    "source_group": "sports_facility",
                    "operator_type": "지자체/공공기관",
                    "collection_type": "api",
                }
            )
            row["raw_fields"]["parser"] = "yssports_fmcs_category_api"
            row["raw_fields"]["category_matched_by"] = "api_category_name"
            if row.get("title"):
                rows.append(row)
        if len(list_rows) < page_size:
            break

    detail_pages = 0
    enriched_rows: list[dict[str, Any]] = []
    for row in dedupe_rows(rows):
        if detail_pages < detail_limit and row.get("raw_url"):
            try:
                detail = fmcs_detail_fields(s, row["raw_url"], timeout)
                row = merge_course_rows(row, detail)
                branch = clean_text(row.get("branch"))
                address = YSSPORTS_BRANCH_ADDRESSES.get(branch, row.get("address") or "")
                if address:
                    row["address"] = address
                    row["venue_address"] = address
                row["raw_fields"]["parser"] = "yssports_fmcs_category_api+detail"
                detail_pages += 1
            except Exception as exc:
                logger.debug("yssports detail fetch failed %s: %s", row.get("raw_url"), exc)
        enriched_rows.append(row)

    meta = {
        "pages": api_pages,
        "api_requests": api_requests,
        "raw_row_count": raw_row_count,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "company_count": len({clean_text(row.get("branch_code")) for row in rows if row.get("branch_code")}),
        "category_combo_count": category_combo_count,
        "target_center": "YGSN01",
        "legacy_list_endpoint": True,
        "total_count": total_count,
        "http_method": method,
    }
    return enriched_rows, "yssports_fmcs_category_api", meta


