PAJU_PCY_PROVIDER = "MUNI_PAJU_PCY_OR_KR_412053A6"
YP21_FMCS_URL = "https://www.yp21.go.kr/pool/fmcs/9"
YP21_PROVIDER = "MUNI_WWW_YP21_GO_KR_EA0D7B81"
YP21_BRANCH_ADDRESS = "경기도 양평군 양평읍 마유산로 3"
PTLIB_PROVIDER = "MUNI_WWW_PTLIB_GO_KR_D9537B1F"
PTLIB_LIST_URL = "https://www.ptlib.go.kr/intro/menu/10025/program/30025/lectureList.do"
PTLIB_DETAIL_URL = "https://www.ptlib.go.kr/intro/menu/10025/program/30025/lectureDetail.do"


def yp21_target_from_title(title: Any) -> str:
    text = clean_text(title)
    targets: list[str] = []
    if "경로" in text:
        targets.append("경로")
    if "장애인" in text:
        targets.append("장애인")
    if "성인" in text:
        targets.append("성인")
    if "청소년" in text:
        targets.append("청소년")
    if "어린이" in text or "초등" in text:
        targets.append("어린이")
    if "유아" in text:
        targets.append("유아")
    if "여성" in text:
        targets.append("여성")
    if "남성" in text:
        targets.append("남성")
    if ("여성" in text or "남성" in text) and not any(target in targets for target in ("성인", "청소년", "어린이", "유아", "경로")):
        targets.insert(0, "성인")
    return clean_text(", ".join(dict.fromkeys(targets)))


def ptlib_is_expired(period: str) -> bool:
    _, end_date = parse_date_range(period)
    if not end_date:
        return False
    return end_date < datetime.now().date()


def ptlib_status(value: Any) -> str:
    text = clean_text(value)
    return {
        "접수예정": "접수예정",
        "접수중": "접수중",
        "접수마감": "마감",
        "종료": "종료",
    }.get(text, text)


def ptlib_schedule(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    return re.sub(r"\s+", " ", text)


def ptlib_detail_fields(s: requests.Session, lecture_idx: str, timeout: int) -> tuple[dict[str, Any], dict[str, str]]:
    if not lecture_idx:
        return {}, {}
    raw_url = f"{PTLIB_DETAIL_URL}?{urlencode({'lectureIdx': lecture_idx})}"
    response = s.get(raw_url, timeout=timeout)
    response.raise_for_status()
    soup = BeautifulSoup(response.text, "html.parser")
    pairs = pairs_from_tables(soup)
    title = clean_text(pairs.get("문화행사명"))
    branch = clean_text(pairs.get("기관명"))
    period = normalize_mixed_date_range(clean_text(pairs.get("교육기간")))
    apply_period = normalize_mixed_date_range(clean_text(pairs.get("모집기간")))
    online = clean_text(pairs.get("온라인접수"))
    capacity_match = re.search(r"(\d+\s*/\s*\d+)", online)
    status_match = re.search(r"(접수예정|접수중|접수마감|대기자접수|종료)", online)
    detail = {
        "title": title,
        "branch": f"{branch}도서관" if branch and not branch.endswith(("도서관", "음악관")) else branch,
        "room": clean_text(pairs.get("장소")),
        "venue_name": clean_text(pairs.get("장소")),
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": ptlib_schedule(pairs.get("시간")),
        "target": clean_text(pairs.get("교육대상") or pairs.get("대상")),
        "capacity": clean_text(capacity_match.group(1) if capacity_match else ""),
        "status": ptlib_status(status_match.group(1) if status_match else online),
        "raw_url": raw_url,
        "application_url": raw_url,
        "description": "",
    }
    return {key: value for key, value in detail.items() if value}, pairs


def collect_ptlib_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    first_soup = fetch_soup(s, PTLIB_LIST_URL, timeout=timeout)
    manage_options = [
        (clean_text(option.get("value")), clean_text(option.get_text(" ", strip=True)))
        for option in first_soup.select("select[name=manageCd] option")
    ]
    manage_options = [
        (code, name)
        for code, name in manage_options
        if code and code != "ALL"
    ] or [("ALL", "전체도서관")]

    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    manage_counts: dict[str, int] = {}
    page_limit = max(1, max_pages)

    for manage_cd, manage_name in manage_options:
        manage_rows = 0
        for page in range(1, page_limit + 1):
            params = {
                "manageCd": manage_cd,
                "currentPageNo": str(page),
                "recordCountPerPage": "50",
            }
            soup = fetch_soup(s, f"{PTLIB_LIST_URL}?{urlencode(params)}", timeout=timeout)
            pages += 1
            pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination, a[href*='fnList'], a[onclick*='fnList']"))
            table = soup.select_one("table")
            if not table:
                break
            body_rows = table.select("tbody tr")
            if not body_rows:
                break

            page_added = 0
            for tr in body_rows:
                cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
                if len(cells) < 6 or "검색결과가 없습니다" in " ".join(cells):
                    continue
                onclick = " ".join(clean_text(a.get("onclick")) for a in tr.select("a[onclick]"))
                match = re.search(r"fnDetail\('([^']+)'", onclick)
                lecture_idx = clean_text(match.group(1) if match else "")
                branch = clean_text(cells[0])
                branch_name = f"{branch}도서관" if branch and not branch.endswith(("도서관", "문학관")) else branch
                title = clean_text(cells[1])
                period = normalize_mixed_date_range(cells[2])
                if ptlib_is_expired(period):
                    continue
                raw_url = f"{PTLIB_DETAIL_URL}?{urlencode({'lectureIdx': lecture_idx})}" if lecture_idx else PTLIB_LIST_URL
                row: dict[str, Any] = {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, lecture_idx or raw_url, title, branch_name),
                    "title": title,
                    "branch": branch_name or manage_name or target.branch,
                    "branch_code": manage_cd or branch_name,
                    "branch_url": PTLIB_LIST_URL,
                    "preserve_branch": True,
                    "category": "도서관 문화행사",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "period": period,
                    "target": clean_text(cells[3]),
                    "capacity": clean_text(cells[4]),
                    "status": ptlib_status(cells[5]),
                    "fee": "",
                    "collection_category": "도서관",
                    "domain_category": "도서관",
                    "operator_type": "도서관",
                    "source_group": "library",
                    "collection_type": "static_html",
                        "program_type": "\uAC15\uC88C",
                    "raw_fields": {
                        "parser": "ptlib_lecture_list",
                        "manage_cd": manage_cd,
                        "manage_name": manage_name,
                        "lecture_idx": lecture_idx,
                        "list_cells": cells,
                    },
                }
                if detail_pages < detail_limit and lecture_idx:
                    try:
                        detail, pairs = ptlib_detail_fields(s, lecture_idx, timeout)
                        row = merge_course_rows(row, detail)
                        row["raw_fields"]["parser"] = "ptlib_lecture_list+detail"
                        row["raw_fields"]["detail_pairs"] = pairs
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("ptlib detail fetch failed idx=%s: %s", lecture_idx, exc)
                rows.append(row)
                manage_rows += 1
                page_added += 1
            if page_added == 0:
                break
            if len(body_rows) < 50:
                break
        manage_counts[manage_name or manage_cd] = manage_rows

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": len(rows),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "manage_count": len(manage_options),
        "manage_counts": manage_counts,
        "expired_filtered": True,
    }
    return dedupe_rows(rows), "ptlib_lecture_list", meta


def paju_pcy_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    response = s.get(url, timeout=timeout, verify=True)
    response.raise_for_status()
    soup = BeautifulSoup(response.text, "html.parser")
    detail = fmcs_detail_fields(s, url, timeout)

    periods: list[str] = []
    fees: list[str] = []
    for table in soup.select("table"):
        headers = [clean_text(cell.get_text(" ", strip=True)) for cell in table.select("thead th")]
        if "수강기간" not in headers:
            continue
        period_index = headers.index("수강기간")
        fee_index = headers.index("수강료") if "수강료" in headers else -1
        for row in table.select("tbody tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in row.find_all(["th", "td"])]
            if period_index < len(cells):
                period = clean_text(cells[period_index])
                if period:
                    periods.append(period)
            if fee_index >= 0 and fee_index < len(cells):
                fee = clean_text(cells[fee_index])
                if fee:
                    fees.append(fee)
    if periods:
        detail["period"] = clean_text(" / ".join(dict.fromkeys(periods)))
    if fees:
        detail["fee"] = clean_text(" / ".join(dict.fromkeys(fees)))
    for excluded_key in (
        "instructor",
        "description",
        "contact",
        "phone",
        "raw_detail_pairs",
    ):
        detail.pop(excluded_key, None)
    return detail


def collect_yp21_fmcs_categories(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    root_url = fmcs_root_url(YP21_FMCS_URL)
    referer = YP21_FMCS_URL
    s.get(referer, timeout=timeout, verify=True)
    method = fmcs_http_method(s, root_url, referer, timeout)
    companies = fmcs_json_rows(
        fmcs_request_json(s, root_url, "rest/common/company", {"type": "L"}, method, referer, timeout)
    )

    rows: list[dict[str, Any]] = []
    api_pages = 0
    api_requests = 0
    raw_row_count = 0
    category_combo_count = 0
    total_count = 0
    pagination_detected = False
    page_size = 100
    page_limit = max(1, max_pages)
    category_counts: dict[str, int] = {}

    for company in companies:
        comcd = clean_text(company.get("comcd"))
        if not comcd:
            continue
        contexts = fmcs_category_contexts(s, root_url, comcd, method, referer, timeout)
        category_combo_count += len(contexts)
        for context in contexts:
            category_cd = clean_text(context.get("category_cd"))
            category_level = clean_text(context.get("category_level")) or "9"
            page = 1
            while page <= page_limit:
                params = {
                    "company_code": comcd,
                    "mem_no": "",
                    "search_type": "%",
                    "category_cd": category_cd,
                    "category_level": category_level,
                    "class_nm": "",
                    "train_day": "",
                    "adult_gubn": "",
                    "lecturer_nm": "",
                    "page": str(page),
                    "page_size": str(page_size),
                }
                data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
                api_requests += 1
                list_rows = fmcs_json_rows(data)
                if not list_rows:
                    break
                api_pages += 1
                raw_row_count += len(list_rows)
                page_total_count = fmcs_int(list_rows[0].get("total_count"))
                total_count = max(total_count, page_total_count)
                pagination_detected = pagination_detected or page_total_count > page_size
                for item in list_rows:
                    row = fmcs_row_from_api_item(target, YP21_FMCS_URL, item, "%", context)
                    if not row.get("title"):
                        continue
                    row.update(
                        {
                            "address": YP21_BRANCH_ADDRESS,
                            "venue_address": YP21_BRANCH_ADDRESS,
                            "branch_url": YP21_FMCS_URL,
                            "preserve_branch": True,
                            "program_type": "강좌",
                            "collection_category": "체육/스포츠",
                            "domain_category": "체육/스포츠",
                            "source_group": "sports_facility",
                            "operator_type": "지자체/공공기관",
                            "collection_type": "api",
                        }
                    )
                    if not row.get("target"):
                        row["target"] = yp21_target_from_title(row.get("title"))
                    row["raw_fields"]["parser"] = "yp21_fmcs_category_api"
                    row["raw_fields"]["company"] = company
                    rows.append(row)
                    category_key = clean_text(row.get("category")) or clean_text(context.get("category_path")) or "uncategorized"
                    category_counts[category_key] = category_counts.get(category_key, 0) + 1
                if len(list_rows) < page_size:
                    break
                page += 1

    detail_pages = 0
    enriched_rows: list[dict[str, Any]] = []
    for row in dedupe_rows(rows):
        if detail_pages < detail_limit and row.get("raw_url"):
            try:
                detail = paju_pcy_detail_fields(s, row["raw_url"], timeout)
                row = merge_course_rows(row, detail)
                row["raw_fields"]["parser"] = "yp21_fmcs_category_api+detail"
                detail_pages += 1
            except Exception as exc:
                logger.debug("yp21 fmcs detail fetch failed %s: %s", row.get("raw_url"), exc)
        enriched_rows.append(row)

    meta = {
        "pages": api_pages,
        "api_requests": api_requests,
        "raw_row_count": raw_row_count,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "company_count": len(companies),
        "category_combo_count": category_combo_count,
        "category_counts": category_counts,
        "total_count": total_count,
        "http_method": method,
    }
    return enriched_rows, "yp21_fmcs_category_api", meta


