def collect_paju_pcy_fmcs_aggregate(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    """Collect each PCY company through its complete unfiltered aggregate."""
    if max_pages < 1:
        raise ValueError("Paju youth FMCS requires at least one aggregate page")
    s = session()
    root_url = fmcs_root_url(PAJU_PCY_FMCS_URL)
    referer = PAJU_PCY_FMCS_URL
    s.get(referer, timeout=timeout, verify=True)
    method = fmcs_http_method(s, root_url, referer, timeout)
    companies = fmcs_json_rows(
        fmcs_request_json(
            s, root_url, "rest/common/company", {"type": "L"}, method, referer, timeout
        )
    )
    expected_companies = {
        "PJYF01": "파주시청소년수련관",
        "PJYF02": "교하청소년문화의집",
        "PJYF03": "금촌청소년문화의집",
        "PJYF04": "운정청소년센터",
    }
    company_names = {
        clean_text(company.get("comcd")): clean_text(company.get("comnm"))
        for company in companies
        if clean_text(company.get("comcd"))
    }
    if company_names != expected_companies:
        raise ValueError("Paju youth FMCS company registry changed")

    rows: list[dict[str, Any]] = []
    category_counts: Counter[str] = Counter()
    company_totals: dict[str, int] = {}
    api_requests = 0
    page_size = 100
    for company in companies:
        comcd = clean_text(company.get("comcd"))
        company_rows: list[dict[str, Any]] = []
        declared_total: int | None = None
        page = 1
        page_count = 1
        while page <= page_count:
            if api_requests >= max_pages:
                raise ValueError("Paju youth FMCS max_pages truncates aggregate pages")
            params = {
                "company_code": comcd,
                "mem_no": "",
                "search_type": "%",
                "category_cd": "",
                "category_level": "9",
                "class_nm": "",
                "train_day": "",
                "adult_gubn": "",
                "lecturer_nm": "",
                "page": str(page),
                "page_size": str(page_size),
            }
            items = fmcs_json_rows(
                fmcs_request_json(
                    s, root_url, "rest/lecture/list", params, method, referer, timeout
                )
            )
            api_requests += 1
            if not items:
                if page == 1 and comcd == "PJYF03":
                    declared_total = 0
                    break
                raise ValueError(f"Paju youth FMCS aggregate page {page} is empty for {comcd}")
            page_total = fmcs_int(items[0].get("total_count"))
            if declared_total is None:
                declared_total = page_total
                page_count = max(1, (declared_total + page_size - 1) // page_size)
            if page_total != declared_total:
                raise ValueError(f"Paju youth FMCS total changed while paging {comcd}")
            company_rows.extend(items)
            page += 1

        declared_total = declared_total or 0
        if len(company_rows) != declared_total:
            raise ValueError(
                f"Paju youth FMCS expected {declared_total} rows for {comcd}, "
                f"found {len(company_rows)}"
            )
        company_totals[comcd] = declared_total
        for item in company_rows:
            if clean_text(item.get("comcd")) != comcd:
                raise ValueError("Paju youth FMCS returned a cross-company row")
            row = fmcs_row_from_api_item(target, PAJU_PCY_FMCS_URL, item, "%")
            if not row.get("title"):
                raise ValueError("Paju youth FMCS row is missing identity/title")
            row.update(
                {
                    "branch_url": PAJU_PCY_FMCS_URL,
                    "preserve_branch": True,
                    "program_type": "강좌",
                    "collection_category": "체육/스포츠",
                    "domain_category": "체육/스포츠",
                    "source_group": "sports_facility",
                    "operator_type": "지자체/공공기관",
                    "collection_type": "api",
                }
            )
            row["raw_fields"]["parser"] = "paju_pcy_fmcs_aggregate_api"
            row["raw_fields"]["company"] = company
            rows.append(row)
            category_counts[clean_text(row.get("category")) or "uncategorized"] += 1

    unique_rows = dedupe_rows(rows)
    declared_total = sum(company_totals.values())
    if len(rows) != declared_total or len(unique_rows) != declared_total:
        raise ValueError(
            f"Paju youth FMCS expected {declared_total} unique rows, "
            f"found {len(unique_rows)}"
        )
    if detail_limit < len(unique_rows):
        raise ValueError(
            f"Paju youth FMCS detail_limit allows {detail_limit} of {len(unique_rows)} details"
        )

    enriched_rows: list[dict[str, Any]] = []
    for row in unique_rows:
        detail = paju_pcy_detail_fields(s, row["raw_url"], timeout)
        row = merge_course_rows(row, detail)
        row["raw_fields"]["parser"] = "paju_pcy_fmcs_aggregate_api+detail"
        enriched_rows.append(row)

    return enriched_rows, "paju_pcy_fmcs_aggregate_api+all_details", {
        "pages": api_requests,
        "api_requests": api_requests,
        "raw_row_count": len(rows),
        "detail_pages": len(enriched_rows),
        "discovered_links": 0,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
        "company_count": len(companies),
        "company_totals": company_totals,
        "category_combo_count": len(companies),
        "category_counts": dict(category_counts),
        "total_count": len(unique_rows),
        "expected_total_count": declared_total,
        "audited_total_count": 183,
        "snapshot_complete": len(enriched_rows) == declared_total,
        "http_method": method,
    }


MUNGYEONG_YOUTH_PROVIDER = "MUNI_WWW_GBMG_GO_KR_E3F4EA45"
MUNGYEONG_YOUTH_HOST = "www.gbmg.go.kr"
MUNGYEONG_YOUTH_MENU_ID = "0109020000"
MUNGYEONG_YOUTH_LIST_PATH = "/reservation/youthCulture/lecture/list.do"
MUNGYEONG_YOUTH_DETAIL_PATH = "/reservation/youthCulture/lecture/view.do"
MUNGYEONG_YOUTH_ENROLL_PATH = "/reservation/youthCulture/enroll/write.do"
MUNGYEONG_YOUTH_LIST_URL = (
    f"https://{MUNGYEONG_YOUTH_HOST}{MUNGYEONG_YOUTH_LIST_PATH}?mId={MUNGYEONG_YOUTH_MENU_ID}"
)
MUNGYEONG_YOUTH_BRANCH = "문경시 청소년문화의집"
MUNGYEONG_YOUTH_ADDRESS = "경상북도 문경시 신흥로 11"
MUNGYEONG_YOUTH_DEFAULT_TARGET = "초등 3학년 이상 청소년"
MUNGYEONG_YOUTH_PARSER = "mungyeong_youth_culture_lecture_list+detail"


def is_mungyeong_youth_lecture_target(url: str) -> bool:
    parsed = urlparse(url)
    if (
        parsed.scheme.lower() != "https"
        or parsed.netloc.lower() != MUNGYEONG_YOUTH_HOST
        or parsed.path != MUNGYEONG_YOUTH_LIST_PATH
        or parsed.fragment
    ):
        return False
    query = parse_qs(parsed.query, keep_blank_values=True)
    return query.get("mId") == [MUNGYEONG_YOUTH_MENU_ID]


def canonical_mungyeong_youth_urls(lecture_idx: Any) -> tuple[str, str]:
    idx = clean_text(lecture_idx)
    if not re.fullmatch(r"\d{1,12}", idx):
        return "", ""
    detail_query = urlencode({"mId": MUNGYEONG_YOUTH_MENU_ID, "idx": idx})
    enroll_query = urlencode({"mId": MUNGYEONG_YOUTH_MENU_ID, "lectureIdx": idx})
    return (
        f"https://{MUNGYEONG_YOUTH_HOST}{MUNGYEONG_YOUTH_DETAIL_PATH}?{detail_query}",
        f"https://{MUNGYEONG_YOUTH_HOST}{MUNGYEONG_YOUTH_ENROLL_PATH}?{enroll_query}",
    )


def mungyeong_youth_normalize_range(value: Any) -> str:
    text = clean_text(value).replace("\xa0", " ")
    text = re.sub(r"\s*~\s*", " ~ ", text)
    text = re.sub(
        r"(\d{4})[./](\d{1,2})[./](\d{1,2})",
        lambda match: f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}",
        text,
    )
    return clean_text(text)


def mungyeong_youth_split_period(value: Any) -> tuple[str, str]:
    period, schedule = split_period_and_schedule(mungyeong_youth_normalize_range(value))
    schedule = clean_text(schedule)
    if schedule.startswith("(") and schedule.endswith(")"):
        schedule = clean_text(schedule[1:-1])
    return mungyeong_youth_normalize_range(period), schedule


def mungyeong_youth_capacity(value: Any) -> tuple[Optional[int], Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    match = re.search(
        r"(\d{1,5})\s*/\s*(\d{1,5})(?:\s*\(\s*(\d{1,5})\s*/\s*(\d{1,5})\s*\))?",
        text,
    )
    if not match:
        return None, None, None, None
    return tuple(int(value) if value is not None else None for value in match.groups())  # type: ignore[return-value]


def mungyeong_youth_status(value: Any) -> str:
    status = re.sub(r"\s+", "", clean_text(value))
    if not status:
        return ""
    if status in {"대기자접수중", "대기접수중", "대기자접수"}:
        return "WAITING"
    if status in {"접수중", "신청가능"}:
        return "OPEN"
    if status in {"접수예정", "신청예정", "신청대기"}:
        return "SCHEDULED"
    if any(token in status for token in ("마감", "종료", "폐강", "취소", "교육중", "운영중")):
        return "CLOSED"
    return ""


def mungyeong_youth_page_numbers(soup: BeautifulSoup) -> tuple[Optional[int], Optional[int]]:
    node = soup.select_one("p.page_num")
    text = clean_text(node.get_text(" ", strip=True) if node else "")
    match = re.search(r"현재\s*페이지\s*(\d+)\s*/\s*전체\s*페이지\s*(\d+)", text)
    if not match:
        return None, None
    current, total = int(match.group(1)), int(match.group(2))
    if current < 1 or total < 1 or current > total:
        return None, None
    return current, total


def mungyeong_youth_lecture_table(soup: BeautifulSoup) -> Any:
    if soup.select_one("form#listForm") is None:
        return None
    for table in soup.select("table"):
        headers = [clean_text(cell.get_text(" ", strip=True)) for cell in table.select("thead th")]
        if (
            len(headers) >= 6
            and headers[0] == "구분"
            and headers[1] == "교육명"
            and headers[2] == "신청기간"
            and headers[3] == "교육기간"
            and "접수자" in headers[4]
            and "정원" in headers[4]
            and headers[5] == "상태"
        ):
            return table
    return None


def mungyeong_youth_response_soup(response: requests.Response) -> BeautifulSoup:
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    return BeautifulSoup(response.text, "lxml")


def mungyeong_youth_list_page(
    s: requests.Session,
    page: int,
    timeout: int,
) -> BeautifulSoup:
    if page == 1:
        return fetch_soup(s, MUNGYEONG_YOUTH_LIST_URL, timeout=timeout)
    response = s.post(
        MUNGYEONG_YOUTH_LIST_URL,
        data={
            "currentPageNo": str(page),
            "keywordType": "",
            "keyword": "",
        },
        timeout=timeout,
    )
    return mungyeong_youth_response_soup(response)


def mungyeong_youth_row_from_table(target: CrawlTarget, tr: Any) -> dict[str, Any]:
    cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.select("td")]
    if len(cells) < 6:
        return {}
    link = tr.select_one('a[data-button="view"][data-idx]')
    lecture_idx = clean_text(link.get("data-idx") if link else "")
    raw_url, enroll_url = canonical_mungyeong_youth_urls(lecture_idx)
    title = clean_text(link.get_text(" ", strip=True) if link else cells[1])
    source_status = cells[5]
    status = mungyeong_youth_status(source_status)
    period, schedule_raw = mungyeong_youth_split_period(cells[3])
    apply_period = mungyeong_youth_normalize_range(cells[2])
    start_date, end_date = parse_date_range(period)
    apply_start, apply_end = parse_date_range(apply_period)
    capacity_current, capacity_total, waitlist_current, waitlist_total = mungyeong_youth_capacity(cells[4])
    if (
        not raw_url
        or not title
        or is_low_value_title(title)
        or not status
        or not period
        or start_date is None
        or end_date is None
        or not apply_period
        or apply_start is None
        or apply_end is None
        or capacity_current is None
        or capacity_total is None
    ):
        return {}
    reservation_available = status in {"OPEN", "WAITING"}
    description = clean_text(" | ".join(cell for cell in cells if cell))
    return {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:lecture:{lecture_idx}"[:100],
        "title": title,
        "branch": MUNGYEONG_YOUTH_BRANCH,
        "branch_code": target.provider,
        "preserve_branch": True,
        "branch_url": MUNGYEONG_YOUTH_LIST_URL,
        "category": cells[0],
        "raw_url": raw_url,
        "application_url": enroll_url if reservation_available else "",
        "application_type": "ONLINE_RESERVATION" if reservation_available else "",
        "application_method_raw": "온라인 신청",
        "reservation_available": reservation_available,
        "status": status,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": schedule_raw,
        "start_date": start_date,
        "end_date": end_date,
        "target": MUNGYEONG_YOUTH_DEFAULT_TARGET,
        "capacity": capacity_total,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "capacity_remaining": max(0, capacity_total - capacity_current),
        "waitlist_current": waitlist_current,
        "waitlist_total": waitlist_total,
        "venue_name": MUNGYEONG_YOUTH_BRANCH,
        "venue_address": MUNGYEONG_YOUTH_ADDRESS,
        "address": MUNGYEONG_YOUTH_ADDRESS,
        "description": description,
        "collection_category": clean_text(target.extra.get("collection_category") or "공공예약"),
        "domain_category": clean_text(target.extra.get("domain_category") or "교육·강좌"),
        "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
        "source_group": clean_text(target.extra.get("source_group") or "municipal_reservation"),
        "service_group": "공공강좌",
        "service_group_policy": "locked",
        "collection_type": "static_html+detail_html",
        "program_type": "강좌",
        "raw_fields": {
            "parser": MUNGYEONG_YOUTH_PARSER,
            "lecture_idx": lecture_idx,
            "menu_id": MUNGYEONG_YOUTH_MENU_ID,
            "list_cells": cells,
            "list_source_status": source_status,
        },
    }


def mungyeong_youth_detail_fields(
    s: requests.Session,
    detail_url: str,
    timeout: int,
) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    pairs = pairs_from_tables(soup)
    description = clean_text(pairs.get("교육내용 소개"))
    detail_status = clean_text(pairs.get("진행상태"))
    normalized_status = mungyeong_youth_status(detail_status)
    period = mungyeong_youth_normalize_range(pairs.get("교육기간"))
    apply_period = mungyeong_youth_normalize_range(pairs.get("신청기간"))
    schedule_raw = clean_text(pairs.get("교육시간"))
    capacity_current, capacity_total, waitlist_current, waitlist_total = mungyeong_youth_capacity(
        pairs.get("신청현황")
    )
    target_text = extract_target_text(description)
    own_cost_match = re.search(r"(?:참가자\s*)?자부담\s*([\d,]+)\s*원", description)
    result: dict[str, Any] = {
        "room": clean_text(pairs.get("강의장소")),
        "description": description,
        "target": target_text,
        "material_fee": extract_material_fee_amount(description),
        "fee": int(own_cost_match.group(1).replace(",", "")) if own_cost_match else None,
        "raw_fields": {
            "detail_pairs": pairs,
            "detail_source_status": detail_status,
        },
    }
    if normalized_status:
        result["status"] = normalized_status
    if period:
        result["period"] = period
        start_date, end_date = parse_date_range(period)
        result["start_date"] = start_date
        result["end_date"] = end_date
    if apply_period:
        result["apply_period"] = apply_period
    if schedule_raw:
        result["schedule_raw"] = schedule_raw
    if capacity_current is not None:
        result["capacity_current"] = capacity_current
    if capacity_total is not None:
        result["capacity"] = capacity_total
        result["capacity_total"] = capacity_total
        result["capacity_remaining"] = max(0, capacity_total - (capacity_current or 0))
    if waitlist_current is not None:
        result["waitlist_current"] = waitlist_current
    if waitlist_total is not None:
        result["waitlist_total"] = waitlist_total
    return result


def crawl_mungyeong_youth_culture_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if not is_mungyeong_youth_lecture_target(target.url):
        raise ValueError("Mungyeong youth target must use the official HTTPS lecture menu")
    s = session()
    candidates: list[dict[str, Any]] = []
    seen_lecture_idxs: set[str] = set()
    pages_seen = 0
    total_pages: Optional[int] = None
    invalid_rows = 0
    duplicate_rows = 0
    no_data_placeholders = 0
    structurally_valid_rows = 0
    pagination_exhausted = False
    partial_collection_error = ""

    for page in range(1, max(1, max_pages) + 1):
        soup = mungyeong_youth_list_page(s, page, timeout)
        pages_seen += 1
        current_page, declared_total_pages = mungyeong_youth_page_numbers(soup)
        if current_page != page or declared_total_pages is None:
            partial_collection_error = f"page {page} did not expose a valid current/total page marker"
            break
        if total_pages is None:
            total_pages = declared_total_pages
        elif declared_total_pages != total_pages:
            partial_collection_error = (
                f"page {page} changed declared total pages from {total_pages} to {declared_total_pages}"
            )
            break

        table = mungyeong_youth_lecture_table(soup)
        if table is None:
            partial_collection_error = f"page {page} did not expose the official lecture table"
            break
        table_rows = table.select("tbody tr")
        table_has_explicit_no_data = bool(COURSE_NO_DATA_PATTERN.search(clean_text(table.get_text(" ", strip=True))))
        if not table_rows:
            if page == 1 and declared_total_pages == 1 and table_has_explicit_no_data:
                no_data_placeholders += 1
                pagination_exhausted = True
            else:
                partial_collection_error = f"page {page} did not expose lecture rows"
            break

        page_data_rows = 0
        for tr in table_rows:
            if is_explicit_course_no_data_row(tr):
                no_data_placeholders += 1
                continue
            page_data_rows += 1
            row = mungyeong_youth_row_from_table(target, tr)
            if not row:
                invalid_rows += 1
                continue
            lecture_idx = clean_text((row.get("raw_fields") or {}).get("lecture_idx"))
            if lecture_idx in seen_lecture_idxs:
                duplicate_rows += 1
                continue
            seen_lecture_idxs.add(lecture_idx)
            structurally_valid_rows += 1
            candidates.append(row)

        if no_data_placeholders and (page != 1 or declared_total_pages != 1 or page_data_rows):
            partial_collection_error = "explicit no-data placeholder was mixed with paginated lecture rows"
            break
        if invalid_rows:
            partial_collection_error = f"listed lecture rows were malformed ({invalid_rows} invalid rows)"
            break
        if duplicate_rows:
            partial_collection_error = f"page {page} repeated previously discovered lecture idx rows"
            break
        if page >= declared_total_pages:
            pagination_exhausted = True
            break

    if total_pages is None and not partial_collection_error:
        partial_collection_error = "lecture list did not declare total pages"
    if (
        not partial_collection_error
        and total_pages is not None
        and pages_seen < total_pages
    ):
        partial_collection_error = (
            f"max_pages cap reached after {pages_seen} of {total_pages} declared pages"
        )

    expired_rows = 0
    current_rows: list[dict[str, Any]] = []
    for row in candidates:
        if should_skip_expired_course(row):
            expired_rows += 1
        else:
            current_rows.append(row)

    detail_attempts = 0
    detail_pages = 0
    detail_errors = 0
    detail_cap = max(0, detail_limit)
    rows: list[dict[str, Any]] = []
    for row in current_rows:
        if detail_attempts < detail_cap:
            detail_attempts += 1
            try:
                detail = mungyeong_youth_detail_fields(s, clean_text(row.get("raw_url")), timeout)
                row = merge_course_rows(row, detail)
                for key in (
                    "status",
                    "period",
                    "apply_period",
                    "schedule_raw",
                    "start_date",
                    "end_date",
                    "room",
                    "description",
                    "target",
                    "fee",
                    "material_fee",
                    "capacity",
                    "capacity_current",
                    "capacity_total",
                    "capacity_remaining",
                    "waitlist_current",
                    "waitlist_total",
                ):
                    if detail.get(key) not in (None, "", [], {}):
                        row[key] = detail[key]
                detail_pages += 1
            except Exception as exc:
                detail_errors += 1
                logger.debug(
                    "Mungyeong youth detail fetch failed url=%s error_type=%s",
                    safe_url_for_log(clean_text(row.get("raw_url"))),
                    type(exc).__name__,
                )

        row["branch"] = MUNGYEONG_YOUTH_BRANCH
        row["branch_code"] = target.provider
        row["preserve_branch"] = True
        row["venue_name"] = MUNGYEONG_YOUTH_BRANCH
        row["venue_address"] = MUNGYEONG_YOUTH_ADDRESS
        row["address"] = MUNGYEONG_YOUTH_ADDRESS
        row["service_group"] = "공공강좌"
        row["service_group_policy"] = "locked"
        row["target"] = clean_text(row.get("target")) or MUNGYEONG_YOUTH_DEFAULT_TARGET
        lecture_idx = clean_text((row.get("raw_fields") or {}).get("lecture_idx"))
        raw_url, enroll_url = canonical_mungyeong_youth_urls(lecture_idx)
        row["provider_course_id"] = f"{target.provider}:lecture:{lecture_idx}"[:100]
        row["raw_url"] = raw_url
        reservation_available = row.get("status") in {"OPEN", "WAITING"}
        row["reservation_available"] = reservation_available
        row["application_url"] = enroll_url if reservation_available else ""
        row["application_type"] = "ONLINE_RESERVATION" if reservation_available else ""
        rows.append(row)

    rows = dedupe_rows(rows)
    collection_complete = pagination_exhausted and not partial_collection_error
    all_valid_rows_expired = bool(
        structurally_valid_rows
        and expired_rows == structurally_valid_rows
        and not rows
    )
    explicit_no_data = bool(no_data_placeholders and structurally_valid_rows == 0)
    no_current_data = collection_complete and not rows and (explicit_no_data or all_valid_rows_expired)
    source_cap_reached = bool(total_pages is not None and pages_seen < total_pages)
    meta: dict[str, Any] = {
        "pages": pages_seen,
        "total_pages": total_pages or 0,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_errors": detail_errors,
        "detail_candidates": len(current_rows),
        "detail_enrichment_capped": detail_attempts < len(current_rows),
        "discovered_links": len(seen_lecture_idxs),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": bool((total_pages or 0) > 1),
        "pagination_complete": collection_complete,
        "pagination_exhausted": collection_complete,
        "source_cap_reached": source_cap_reached,
        "valid_count": structurally_valid_rows,
        "invalid_count": invalid_rows,
        "duplicate_count": duplicate_rows,
        "expired_count": expired_rows,
        "no_data_placeholders": no_data_placeholders,
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": (
            "explicit no-data placeholder"
            if no_current_data and explicit_no_data
            else "all listed courses are expired"
            if no_current_data and all_valid_rows_expired
            else ""
        ),
    }
    if partial_collection_error:
        meta["configured_collection_error"] = partial_collection_error
    return rows, MUNGYEONG_YOUTH_PARSER, meta


