POCHEON_GGSHARE_RECOVERY_ATTEMPTS = 3
POCHEON_GGSHARE_RECOVERY_ID_LIMIT = 12
POCHEON_GGSHARE_RECOVERY_COOLDOWN_SECONDS = 8.0
POCHEON_GGSHARE_RECOVERY_ITEM_COOLDOWN_SECONDS = 2.0
POCHEON_GGSHARE_RECOVERY_BACKOFF_SECONDS = 3.0
POCHEON_GGSHARE_PARSER = "pocheon_ggshare_lecture_list+local+share_detail"
POCHEON_GGSHARE_BRANCHES: dict[str, tuple[str, str]] = {
    "포천시청년센터": ("POCHEON_YOUTH_CENTER", "경기 포천시 호국로 1423"),
    "포천미디어센터": ("POCHEON_MEDIA_CENTER", "경기 포천시 호국로 1423"),
    "포천음악창작소": ("POCHEON_MUSIC_STUDIO", "경기 포천시 호국로 1423"),
    "포천외국인주민지원센터": (
        "POCHEON_FOREIGN_RESIDENT_CENTER",
        "경기 포천시 군내면 용정경제로1길 47-14",
    ),
}


def is_pocheon_ggshare_target(url: str) -> bool:
    parsed = urlparse(clean_text(url))
    query = parse_qs(parsed.query)
    return (
        parsed.scheme.lower() == "https"
        and parsed.netloc.lower() in POCHEON_GGSHARE_LOCAL_HOSTS
        and parsed.path == POCHEON_GGSHARE_LIST_PATH
        and query.get("key") == [POCHEON_GGSHARE_KEY]
    )


def pocheon_ggshare_list_url(page: int) -> str:
    return "https://pocheon.go.kr{}?{}".format(
        POCHEON_GGSHARE_LIST_PATH,
        urlencode(
            {
                "key": POCHEON_GGSHARE_KEY,
                "pageUnit": str(POCHEON_GGSHARE_PAGE_SIZE),
                "searchCnd": "all",
                "pageIndex": str(max(1, page)),
            }
        ),
    )


def pocheon_ggshare_local_detail_url(lecture_no: str) -> str:
    if not re.fullmatch(r"\d+", clean_text(lecture_no)):
        raise ValueError("Pocheon lecture_no must be numeric")
    return "https://pocheon.go.kr{}?{}".format(
        POCHEON_GGSHARE_DETAIL_PATH,
        urlencode({"lecture_no": lecture_no, "key": POCHEON_GGSHARE_KEY}),
    )


def pocheon_ggshare_share_url(lecture_no: str) -> str:
    if not re.fullmatch(r"\d+", clean_text(lecture_no)):
        raise ValueError("Pocheon lecture_no must be numeric")
    return "https://share.gg.go.kr{}?{}".format(
        POCHEON_GGSHARE_SHARE_PATH,
        urlencode({"id": lecture_no, "eshare": "1"}),
    )


def pocheon_ggshare_page_totals(soup: BeautifulSoup) -> tuple[Optional[int], int]:
    text = clean_text(soup.get_text(" ", strip=True)).replace(",", "")
    total_match = re.search(r"총\s*(\d+)\s*건", text)
    pages_match = re.search(r"\[\s*\d+\s*/\s*(\d+)\s*페이지\s*\]", text)
    return (
        int(total_match.group(1)) if total_match else None,
        int(pages_match.group(1)) if pages_match else 0,
    )


def pocheon_ggshare_receipt_values(anchor: Any) -> dict[str, str]:
    values: dict[str, str] = {}
    for item in anchor.select(".receipt_content li"):
        label_node = item.select_one(".lt")
        value_node = item.select_one(".ld")
        label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if label and value:
            values[label] = value
    return values


def pocheon_ggshare_list_item(anchor: Any, page_url: str, page: int) -> dict[str, Any]:
    href = clean_text(anchor.get("href"))
    query = parse_qs(urlparse(urljoin(page_url, href)).query)
    lecture_no = clean_text((query.get("lecture_no") or [""])[0])
    title_node = anchor.select_one(".receipt_subject span") or anchor.select_one(".receipt_subject")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    status = next(
        (
            clean_text(node.get_text(" ", strip=True))
            for node in anchor.select(".temp_badge")
            if clean_text(node.get_text(" ", strip=True))
        ),
        "",
    )
    method_node = anchor.select_one(".receipt_target")
    values = pocheon_ggshare_receipt_values(anchor)
    period = clean_text(values.get("교육기간"))
    start_date, end_date = parse_date_range(period)
    return {
        "lecture_no": lecture_no,
        "title": title,
        "list_status": status,
        "application_method_raw": clean_text(
            method_node.get_text(" ", strip=True) if method_node else ""
        ),
        "venue": clean_text(values.get("교육장소")),
        "period": period,
        "start_date": start_date,
        "end_date": end_date,
        "fee": clean_text(values.get("이용요금")),
        "page": page,
        "page_url": page_url,
        "list_text": clean_text(anchor.get_text(" ", strip=True)),
    }


def pocheon_ggshare_is_test_title(title: Any) -> bool:
    text = clean_text(title)
    return "테스트" in text or bool(re.search(r"\btest\b", text, re.IGNORECASE))


def pocheon_ggshare_fallback_branch(title: Any, venue: Any) -> tuple[str, str, str]:
    title_text = clean_text(title)
    venue_text = clean_text(venue)
    if "외국인주민" in title_text or "외국인주민지원센터" in venue_text:
        branch = "포천외국인주민지원센터"
    elif "포천미디어센터" in venue_text:
        branch = "포천미디어센터"
    elif "포천음악창작소" in venue_text and "청년비전센터" in venue_text and "," in venue_text:
        # Only the two combined-venue long-running rows use this operator.
        # Newer rows titled "[포천음악창작소]" belong to the youth centre.
        branch = "포천음악창작소"
    elif any(token in venue_text for token in ("청년센터", "청년비전센터", "음악창작소")):
        branch = "포천시청년센터"
    else:
        return "", "", ""
    branch_code, address = POCHEON_GGSHARE_BRANCHES[branch]
    return branch, branch_code, address


def pocheon_ggshare_table_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for row in soup.select("table tr"):
        header = row.find("th")
        value = row.find("td")
        label = clean_text(header.get_text(" ", strip=True) if header else "")
        text = clean_text(value.get_text(" ", strip=True) if value else "")
        if label and text:
            pairs[label] = text
    return pairs


def pocheon_ggshare_local_detail_fields(
    soup: BeautifulSoup,
    lecture_no: str,
    expected_title: str,
) -> tuple[dict[str, Any], str]:
    detail_url = pocheon_ggshare_local_detail_url(lecture_no)
    caption_node = soup.select_one("caption")
    caption = clean_text(caption_node.get_text(" ", strip=True) if caption_node else "")
    if not caption or not caption.startswith(clean_text(expected_title)):
        raise ValueError("local detail did not expose the expected course caption")

    share_url = ""
    for link in soup.select("a[href]"):
        candidate = urljoin(detail_url, clean_text(link.get("href")))
        parsed = urlparse(candidate)
        query = parse_qs(parsed.query)
        if (
            parsed.scheme.lower() == "https"
            and parsed.netloc.lower() == POCHEON_GGSHARE_SHARE_HOST
            and parsed.path == POCHEON_GGSHARE_SHARE_PATH
            and query.get("id") == [lecture_no]
            and query.get("eshare") == ["1"]
        ):
            share_url = pocheon_ggshare_share_url(lecture_no)
            break
    if not share_url:
        raise ValueError("local detail did not expose a matching share.gg lecture link")

    pairs = pocheon_ggshare_table_pairs(soup)
    period = clean_text(pairs.get("교육시간") or pairs.get("교육기간"))
    venue = clean_text(pairs.get("교육장소"))
    if not venue or not period:
        raise ValueError("local detail did not expose education place and period")
    start_date, end_date = parse_date_range(period)
    return (
        {
            "category": clean_text(pairs.get("구분")),
            "venue": venue,
            "period": period,
            "start_date": start_date,
            "end_date": end_date,
            "fee": clean_text(pairs.get("수강료") or pairs.get("이용요금")),
            "local_detail_pairs": pairs,
        },
        share_url,
    )


def pocheon_ggshare_fetch_local_detail(
    s: requests.Session,
    lecture_no: str,
    expected_title: str,
    timeout: int,
    attempts: int = POCHEON_GGSHARE_LOCAL_DETAIL_ATTEMPTS,
    backoff_seconds: float = POCHEON_GGSHARE_LOCAL_BACKOFF_SECONDS,
) -> tuple[dict[str, Any], str, int]:
    detail_url = pocheon_ggshare_local_detail_url(lecture_no)
    attempts = max(1, attempts)
    errors: list[str] = []
    for attempt in range(1, attempts + 1):
        time.sleep(POCHEON_GGSHARE_DETAIL_PACING_SECONDS)
        try:
            soup = fetch_soup(s, detail_url, timeout=timeout)
            fields, share_url = pocheon_ggshare_local_detail_fields(
                soup,
                lecture_no,
                expected_title,
            )
            return fields, share_url, attempt
        except Exception as exc:
            logger.debug(
                "Pocheon local detail validation failed url=%s attempt=%s error_type=%s",
                safe_url_for_log(detail_url),
                attempt,
                type(exc).__name__,
            )
            errors.append(f"{type(exc).__name__}: {clean_text(exc)}")
            if attempt < attempts:
                time.sleep(max(0.0, backoff_seconds) * (2 ** (attempt - 1)))
    raise ValueError(
        f"local detail remained invalid after {attempts} attempts: "
        f"{errors[-1] if errors else 'unknown'}"
    )


def pocheon_ggshare_labeled_span(soup: BeautifulSoup, label: str) -> str:
    for label_node in soup.select("span.lineL"):
        if clean_text(label_node.get_text(" ", strip=True)) != label:
            continue
        value_node = label_node.find_next_sibling("span")
        if value_node is not None:
            return clean_text(value_node.get_text(" ", strip=True))
    return ""


def pocheon_ggshare_share_detail_fields(
    soup: BeautifulSoup,
    expected_title: str,
) -> dict[str, Any]:
    expected = clean_text(expected_title)
    actual_titles = [
        clean_text(node.get_text(" ", strip=True))
        for node in soup.select("p.tit")
        if clean_text(node.get_text(" ", strip=True))
    ]
    if expected not in actual_titles:
        raise ValueError("share.gg HTTP response did not contain the expected detail title")

    branches = [
        clean_text(node.get_text(" ", strip=True))
        for node in soup.select("span.txt2")
        if clean_text(node.get_text(" ", strip=True)) in POCHEON_GGSHARE_BRANCHES
    ]
    branch = branches[0] if branches else ""
    place = pocheon_ggshare_labeled_span(soup, "교육장소")
    if not branch or not place:
        raise ValueError("share.gg HTTP response did not contain branch and education place")

    road_address = ""
    for button in soup.select("button[onclick*='f_mapPop']"):
        onclick = clean_text(button.get("onclick"))
        address_match = re.search(r"f_mapPop\(\s*['\"]([^'\"]+)['\"]", onclick)
        if address_match and clean_text(address_match.group(1)).startswith("경기 포천시"):
            road_address = clean_text(address_match.group(1))
            break
    branch_code, fallback_address = POCHEON_GGSHARE_BRANCHES[branch]
    road_address = road_address or fallback_address
    if not road_address.startswith("경기 포천시"):
        raise ValueError("share.gg HTTP response did not contain an official Pocheon address")

    room = place
    if room.startswith(road_address):
        room = clean_text(room[len(road_address):])
    return {
        "branch": branch,
        "branch_code": branch_code,
        "preserve_branch": True,
        "room": room,
        "venue_name": branch,
        "venue_address": road_address,
        "address": road_address,
        "provider_organizer": branch,
        "share_place": place,
    }


def pocheon_ggshare_fetch_share_detail(
    s: requests.Session,
    share_url: str,
    expected_title: str,
    timeout: int,
    attempts: int = POCHEON_GGSHARE_DETAIL_ATTEMPTS,
    backoff_seconds: float = POCHEON_GGSHARE_SHARE_BACKOFF_SECONDS,
) -> tuple[dict[str, Any], int]:
    attempts = max(1, attempts)
    errors: list[str] = []
    for attempt in range(1, attempts + 1):
        time.sleep(POCHEON_GGSHARE_DETAIL_PACING_SECONDS)
        try:
            soup = fetch_soup(s, share_url, timeout=timeout)
            return pocheon_ggshare_share_detail_fields(soup, expected_title), attempt
        except Exception as exc:
            logger.debug(
                "Pocheon share detail validation failed url=%s attempt=%s error_type=%s",
                safe_url_for_log(share_url),
                attempt,
                type(exc).__name__,
            )
            errors.append(f"{type(exc).__name__}: {clean_text(exc)}")
            if attempt < attempts:
                time.sleep(max(0.0, backoff_seconds) * (2 ** (attempt - 1)))
    raise ValueError(
        f"share.gg detail remained invalid after {attempts} attempts: "
        f"{errors[-1] if errors else 'unknown'}"
    )


def pocheon_ggshare_status(value: Any) -> str:
    text = clean_text(value)
    if "대기" in text:
        return "WAITING"
    if "예정" in text:
        return "SCHEDULED"
    if any(token in text for token in ("마감", "종료", "폐강")):
        return "CLOSED"
    if "접수중" in text:
        return "OPEN"
    return normalize_status(text)


POCHEON_GGSHARE_CORE_STATUSES = {"OPEN", "WAITING", "SCHEDULED", "CLOSED"}


def pocheon_ggshare_core_missing_fields(
    row: dict[str, Any],
    lecture_no: str,
    *,
    require_official_fallback: bool,
) -> list[str]:
    missing: list[str] = []
    branch = clean_text(row.get("branch"))
    branch_mapping = POCHEON_GGSHARE_BRANCHES.get(branch)
    if not branch_mapping:
        missing.append("official_branch")
    else:
        expected_code, fallback_address = branch_mapping
        if clean_text(row.get("branch_code")) != expected_code:
            missing.append("official_branch_code")
        address = clean_text(row.get("address"))
        if require_official_fallback:
            if address != fallback_address:
                missing.append("official_fallback_address")
        elif not address.startswith("경기 포천시"):
            missing.append("official_pocheon_address")
        if clean_text(row.get("venue_address")) != address:
            missing.append("venue_address")
        if clean_text(row.get("venue_name")) != branch:
            missing.append("venue_name")
        if clean_text(row.get("provider_organizer")) != branch:
            missing.append("provider_organizer")

    if clean_text(row.get("provider")) != POCHEON_GGSHARE_PROVIDER:
        missing.append("provider")
    if clean_text(row.get("provider_course_id")) != (
        f"{POCHEON_GGSHARE_PROVIDER}:lecture:{lecture_no}"
    ):
        missing.append("provider_course_id")
    if not clean_text(row.get("title")):
        missing.append("title")
    if not clean_text(row.get("period")):
        missing.append("period")
    if row.get("start_date") is None:
        missing.append("start_date")
    if row.get("end_date") is None:
        missing.append("end_date")
    if clean_text(row.get("status")) not in POCHEON_GGSHARE_CORE_STATUSES:
        missing.append("status")
    if not clean_text(row.get("room")):
        missing.append("room")
    if clean_text(row.get("raw_url")) != pocheon_ggshare_local_detail_url(lecture_no):
        missing.append("raw_url")
    if clean_text(row.get("branch_url")) != POCHEON_GGSHARE_LIST_URL:
        missing.append("branch_url")
    if clean_text((row.get("raw_fields") or {}).get("lecture_no")) != lecture_no:
        missing.append("raw_lecture_no")
    return missing


def pocheon_ggshare_base_row(target: CrawlTarget, item: dict[str, Any]) -> dict[str, Any]:
    lecture_no = clean_text(item.get("lecture_no"))
    title = clean_text(item.get("title"))
    list_venue = clean_text(item.get("venue"))
    branch, branch_code, address = pocheon_ggshare_fallback_branch(title, list_venue)
    status = pocheon_ggshare_status(item.get("list_status"))
    return {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:lecture:{lecture_no}"[:100],
        "title": title,
        "branch": branch,
        "branch_code": branch_code,
        "preserve_branch": True,
        "branch_url": POCHEON_GGSHARE_LIST_URL,
        "raw_url": pocheon_ggshare_local_detail_url(lecture_no),
        "status": status,
        "reservation_available": status in {"OPEN", "WAITING"},
        "application_type": "INFO_ONLY",
        "period": clean_text(item.get("period")),
        "start_date": item.get("start_date"),
        "end_date": item.get("end_date"),
        "schedule_raw": clean_text(item.get("period")),
        "room": list_venue,
        "venue_name": branch,
        "venue_address": address,
        "address": address,
        "provider_organizer": branch,
        "application_method_raw": clean_text(item.get("application_method_raw")),
        "fee": clean_text(item.get("fee")),
        "description": clean_text(item.get("list_text"))[:2000],
        "collection_category": "공공예약",
        "domain_category": "교육·강좌",
        "source_group": "municipal_reservation",
        "operator_type": "지자체/공공기관",
        "service_group": "공공강좌",
        "service_group_policy": "locked",
        "collection_type": "static_html",
        "program_type": "강좌",
        "raw_fields": {
            "parser": POCHEON_GGSHARE_PARSER,
            "lecture_no": lecture_no,
            "list_page": int(item.get("page") or 0),
            "list_page_url": clean_text(item.get("page_url")),
            "list_status": clean_text(item.get("list_status")),
            "list_venue": list_venue,
            "list_application_method": clean_text(item.get("application_method_raw")),
            "service_group_policy": "locked",
        },
    }


def crawl_pocheon_ggshare_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if target.provider != POCHEON_GGSHARE_PROVIDER or not is_pocheon_ggshare_target(target.url):
        raise ValueError("Pocheon collector requires its official provider and HTTPS education list")

    s = session()
    errors: list[str] = []
    seen_lectures: set[str] = set()
    current_items: list[dict[str, Any]] = []
    pages = 0
    declared_total: Optional[int] = None
    declared_pages = 0
    pagination_exhausted = False
    source_cap_reached = False
    invalid_rows = 0
    duplicate_rows = 0
    expired_rows = 0
    test_rows = 0

    def add_error(value: str) -> None:
        value = clean_text(value)
        if value and value not in errors:
            errors.append(value)

    page_cap = max(1, max_pages)
    for page in range(1, page_cap + 1):
        if page > 1:
            time.sleep(POCHEON_GGSHARE_LIST_PACING_SECONDS)
        page_url = pocheon_ggshare_list_url(page)
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_total, page_total_pages = pocheon_ggshare_page_totals(soup)
        if page == 1:
            declared_total = page_total
            declared_pages = page_total_pages
            if declared_total is None or declared_pages < 1:
                add_error("first page did not declare total rows and pages")
        else:
            if page_total is None or page_total_pages < 1:
                add_error(f"page {page} did not declare total rows and pages")
            if page_total is not None and declared_total is not None and page_total != declared_total:
                add_error(f"page {page} declared total {page_total}, expected {declared_total}")
            if page_total_pages and declared_pages and page_total_pages != declared_pages:
                add_error(f"page {page} declared {page_total_pages} pages, expected {declared_pages}")

        anchors = soup.select(
            "a.receipt_anchor[href*='ggShareLctreGroupWebView.do'][href*='lecture_no=']"
        )
        page_new_ids = 0
        for anchor in anchors:
            item = pocheon_ggshare_list_item(anchor, page_url, page)
            lecture_no = clean_text(item.get("lecture_no"))
            if not re.fullmatch(r"\d+", lecture_no):
                invalid_rows += 1
                continue
            if lecture_no in seen_lectures:
                duplicate_rows += 1
                continue
            seen_lectures.add(lecture_no)
            page_new_ids += 1

            if (
                not clean_text(item.get("title"))
                or is_low_value_title(clean_text(item.get("title")))
                or not clean_text(item.get("list_status"))
                or not clean_text(item.get("venue"))
                or not clean_text(item.get("period"))
                or item.get("end_date") is None
            ):
                invalid_rows += 1
                continue
            if pocheon_ggshare_is_test_title(item.get("title")):
                test_rows += 1
                continue
            if should_skip_expired_course(item):
                expired_rows += 1
                continue
            current_items.append(item)

        if declared_pages and page >= declared_pages:
            pagination_exhausted = True
            break
        if not anchors or page_new_ids == 0:
            add_error(f"page {page} did not expose new lecture_no rows")
            break
        if not declared_pages and len(anchors) < POCHEON_GGSHARE_PAGE_SIZE:
            pagination_exhausted = True
            break

    if declared_pages and pages < declared_pages and not pagination_exhausted:
        source_cap_reached = pages >= page_cap
        if source_cap_reached:
            add_error(f"max_pages cap reached after {pages} of {declared_pages} declared pages")
    if pagination_exhausted and declared_total is not None and len(seen_lectures) != declared_total:
        add_error(f"parsed {len(seen_lectures)} of {declared_total} declared lecture rows")
    if invalid_rows:
        add_error(f"encountered {invalid_rows} malformed lecture rows")
    if duplicate_rows:
        add_error(f"encountered {duplicate_rows} duplicate lecture_no rows")

    detail_cap = max(0, detail_limit)
    detail_enrichment_capped = detail_cap < len(current_items)
    if detail_enrichment_capped:
        add_error(f"detail enrichment capped at {detail_cap} of {len(current_items)} current rows")

    def apply_local_detail(
        row: dict[str, Any],
        local_detail: dict[str, Any],
        share_url: str,
        attempts_used: int,
        *,
        recovery: bool = False,
    ) -> None:
        for key in ("category", "period", "start_date", "end_date", "fee"):
            if local_detail.get(key) not in (None, ""):
                row[key] = local_detail[key]
        if clean_text(row.get("period")):
            row["schedule_raw"] = clean_text(row.get("period"))
        raw_fields = row.setdefault("raw_fields", {})
        raw_fields["local_detail_pairs"] = local_detail.get("local_detail_pairs", {})
        raw_fields["share_detail_url"] = share_url
        raw_fields["local_detail_attempts"] = int(
            raw_fields.get("local_detail_attempts") or 0
        ) + attempts_used
        raw_fields.pop("local_detail_error", None)
        if recovery:
            raw_fields["local_recovery_attempts"] = attempts_used
            raw_fields["local_detail_recovered"] = True

    def apply_share_detail(
        row: dict[str, Any],
        share_detail: dict[str, Any],
        attempts_used: int,
        *,
        recovery: bool = False,
    ) -> None:
        row.update(share_detail)
        raw_fields = row.setdefault("raw_fields", {})
        raw_fields["share_detail_attempts"] = int(
            raw_fields.get("share_detail_attempts") or 0
        ) + attempts_used
        raw_fields["share_place"] = share_detail.get("share_place", "")
        raw_fields.pop("share_detail_error", None)
        if recovery:
            raw_fields["share_recovery_attempts"] = attempts_used
            raw_fields["share_detail_recovered"] = True

    row_states: list[dict[str, Any]] = []
    states_by_lecture_no: dict[str, dict[str, Any]] = {}
    local_detail_pages = 0
    share_detail_pages = 0
    local_http_attempts = 0
    share_http_attempts = 0
    local_retry_recoveries = 0
    share_retry_recoveries = 0
    initial_local_failure_ids: list[str] = []
    initial_share_failure_ids: list[str] = []
    final_local_failure_ids: set[str] = set()
    final_share_failure_ids: set[str] = set()
    for item in current_items[:detail_cap]:
        row = pocheon_ggshare_base_row(target, item)
        lecture_no = clean_text(item.get("lecture_no"))
        title = clean_text(item.get("title"))
        share_url = ""
        try:
            local_detail, share_url, local_attempts_used = pocheon_ggshare_fetch_local_detail(
                s,
                lecture_no,
                title,
                timeout,
            )
            local_http_attempts += local_attempts_used
            local_retry_recoveries += int(local_attempts_used > 1)
            local_detail_pages += 1
            apply_local_detail(row, local_detail, share_url, local_attempts_used)
        except Exception as exc:
            logger.debug(
                "Pocheon local detail validation failed lecture_no=%s error_type=%s",
                lecture_no,
                type(exc).__name__,
            )
            initial_local_failure_ids.append(lecture_no)
            final_local_failure_ids.add(lecture_no)
            local_http_attempts += POCHEON_GGSHARE_LOCAL_DETAIL_ATTEMPTS
            row["raw_fields"]["local_detail_attempts"] = (
                POCHEON_GGSHARE_LOCAL_DETAIL_ATTEMPTS
            )
            row["raw_fields"]["local_detail_error"] = (
                f"{type(exc).__name__}: {clean_text(exc)}"[:500]
            )

        if share_url:
            try:
                share_detail, attempts_used = pocheon_ggshare_fetch_share_detail(
                    s,
                    share_url,
                    title,
                    timeout,
                )
                share_http_attempts += attempts_used
                share_retry_recoveries += int(attempts_used > 1)
                share_detail_pages += 1
                apply_share_detail(row, share_detail, attempts_used)
            except Exception as exc:
                logger.debug(
                    "Pocheon share detail exhausted retries lecture_no=%s error_type=%s",
                    lecture_no,
                    type(exc).__name__,
                )
                initial_share_failure_ids.append(lecture_no)
                final_share_failure_ids.add(lecture_no)
                share_http_attempts += POCHEON_GGSHARE_DETAIL_ATTEMPTS
                row["raw_fields"]["share_detail_attempts"] = (
                    POCHEON_GGSHARE_DETAIL_ATTEMPTS
                )
                row["raw_fields"]["share_detail_error"] = (
                    f"{type(exc).__name__}: {clean_text(exc)}"[:500]
                )

        state = {
            "lecture_no": lecture_no,
            "title": title,
            "list_status": clean_text(item.get("list_status")),
            "row": row,
            "share_url": share_url,
        }
        row_states.append(state)
        states_by_lecture_no[lecture_no] = state

    recovery_candidate_ids = list(
        dict.fromkeys(initial_local_failure_ids + initial_share_failure_ids)
    )
    recovery_selected_ids = recovery_candidate_ids[:POCHEON_GGSHARE_RECOVERY_ID_LIMIT]
    recovery_skipped_ids = recovery_candidate_ids[POCHEON_GGSHARE_RECOVERY_ID_LIMIT:]
    recovery_attempted_ids: list[str] = []
    local_recovery_success_ids: list[str] = []
    share_recovery_success_ids: list[str] = []
    local_recovery_attempted = 0
    share_recovery_attempted = 0
    local_recovery_http_attempts = 0
    share_recovery_http_attempts = 0
    recovery_request_groups = 0
    recovery_passes = 0
    recovery_session_created = False
    recovery_session_error_type = ""

    if recovery_selected_ids:
        try:
            recovery_s = session()
            recovery_session_created = True
        except Exception as exc:
            recovery_session_error_type = type(exc).__name__
            logger.debug(
                "Pocheon recovery session creation failed error_type=%s",
                recovery_session_error_type,
            )
        else:
            recovery_passes = 1
            time.sleep(POCHEON_GGSHARE_RECOVERY_COOLDOWN_SECONDS)
            try:
                for lecture_no in recovery_selected_ids:
                    if lecture_no not in final_local_failure_ids:
                        continue
                    state = states_by_lecture_no[lecture_no]
                    if recovery_request_groups:
                        time.sleep(POCHEON_GGSHARE_RECOVERY_ITEM_COOLDOWN_SECONDS)
                    recovery_request_groups += 1
                    recovery_attempted_ids.append(lecture_no)
                    local_recovery_attempted += 1
                    try:
                        local_detail, share_url, attempts_used = (
                            pocheon_ggshare_fetch_local_detail(
                                recovery_s,
                                lecture_no,
                                state["title"],
                                timeout,
                                attempts=POCHEON_GGSHARE_RECOVERY_ATTEMPTS,
                                backoff_seconds=POCHEON_GGSHARE_RECOVERY_BACKOFF_SECONDS,
                            )
                        )
                    except Exception as exc:
                        logger.debug(
                            "Pocheon local recovery exhausted lecture_no=%s error_type=%s",
                            lecture_no,
                            type(exc).__name__,
                        )
                        local_http_attempts += POCHEON_GGSHARE_RECOVERY_ATTEMPTS
                        local_recovery_http_attempts += POCHEON_GGSHARE_RECOVERY_ATTEMPTS
                        raw_fields = state["row"].setdefault("raw_fields", {})
                        raw_fields["local_detail_attempts"] = int(
                            raw_fields.get("local_detail_attempts") or 0
                        ) + POCHEON_GGSHARE_RECOVERY_ATTEMPTS
                        raw_fields["local_recovery_attempts"] = (
                            POCHEON_GGSHARE_RECOVERY_ATTEMPTS
                        )
                        raw_fields["local_detail_error"] = (
                            f"{type(exc).__name__}: {clean_text(exc)}"[:500]
                        )
                        continue

                    local_http_attempts += attempts_used
                    local_recovery_http_attempts += attempts_used
                    local_detail_pages += 1
                    final_local_failure_ids.discard(lecture_no)
                    local_recovery_success_ids.append(lecture_no)
                    state["share_url"] = share_url
                    apply_local_detail(
                        state["row"],
                        local_detail,
                        share_url,
                        attempts_used,
                        recovery=True,
                    )

                share_recovery_ids = [
                    lecture_no
                    for lecture_no in recovery_selected_ids
                    if lecture_no in initial_share_failure_ids
                    or lecture_no in local_recovery_success_ids
                ]
                for lecture_no in share_recovery_ids:
                    if lecture_no in final_local_failure_ids:
                        continue
                    state = states_by_lecture_no[lecture_no]
                    share_url = clean_text(state.get("share_url"))
                    if not share_url:
                        final_share_failure_ids.add(lecture_no)
                        continue
                    if recovery_request_groups:
                        time.sleep(POCHEON_GGSHARE_RECOVERY_ITEM_COOLDOWN_SECONDS)
                    recovery_request_groups += 1
                    if lecture_no not in recovery_attempted_ids:
                        recovery_attempted_ids.append(lecture_no)
                    share_recovery_attempted += 1
                    try:
                        share_detail, attempts_used = pocheon_ggshare_fetch_share_detail(
                            recovery_s,
                            share_url,
                            state["title"],
                            timeout,
                            attempts=POCHEON_GGSHARE_RECOVERY_ATTEMPTS,
                            backoff_seconds=POCHEON_GGSHARE_RECOVERY_BACKOFF_SECONDS,
                        )
                    except Exception as exc:
                        logger.debug(
                            "Pocheon share recovery exhausted lecture_no=%s error_type=%s",
                            lecture_no,
                            type(exc).__name__,
                        )
                        final_share_failure_ids.add(lecture_no)
                        share_http_attempts += POCHEON_GGSHARE_RECOVERY_ATTEMPTS
                        share_recovery_http_attempts += POCHEON_GGSHARE_RECOVERY_ATTEMPTS
                        raw_fields = state["row"].setdefault("raw_fields", {})
                        raw_fields["share_detail_attempts"] = int(
                            raw_fields.get("share_detail_attempts") or 0
                        ) + POCHEON_GGSHARE_RECOVERY_ATTEMPTS
                        raw_fields["share_recovery_attempts"] = (
                            POCHEON_GGSHARE_RECOVERY_ATTEMPTS
                        )
                        raw_fields["share_detail_error"] = (
                            f"{type(exc).__name__}: {clean_text(exc)}"[:500]
                        )
                        continue

                    share_http_attempts += attempts_used
                    share_recovery_http_attempts += attempts_used
                    share_detail_pages += 1
                    final_share_failure_ids.discard(lecture_no)
                    share_recovery_success_ids.append(lecture_no)
                    apply_share_detail(
                        state["row"],
                        share_detail,
                        attempts_used,
                        recovery=True,
                    )
            finally:
                close_recovery_session = getattr(recovery_s, "close", None)
                if callable(close_recovery_session):
                    close_recovery_session()

    recovery_complete_ids = [
        lecture_no
        for lecture_no in recovery_attempted_ids
        if lecture_no not in final_local_failure_ids
        and lecture_no not in final_share_failure_ids
    ]
    local_detail_failures = len(final_local_failure_ids)
    share_detail_failures = len(final_share_failure_ids)
    detail_failure_ids = final_local_failure_ids | final_share_failure_ids
    unknown_branch_rows = 0
    core_validation_failure_ids: list[str] = []
    core_missing_fields_by_id: dict[str, list[str]] = {}
    rows: list[dict[str, Any]] = []
    for state in row_states:
        lecture_no = clean_text(state.get("lecture_no"))
        row = state["row"]
        share_url = clean_text(state.get("share_url"))
        status = pocheon_ggshare_status(row.get("status") or state.get("list_status"))
        row["status"] = status
        row["reservation_available"] = bool(
            status in {"OPEN", "WAITING"} and share_url
        )
        raw_fields = row.setdefault("raw_fields", {})
        if row["reservation_available"]:
            row["application_url"] = share_url
            row["application_type"] = "ONLINE_RESERVATION"
            raw_fields.pop("clear_application_url", None)
        else:
            row.pop("application_url", None)
            row["application_type"] = "INFO_ONLY"
            raw_fields["clear_application_url"] = True
        row["schedule_raw"] = clean_text(row.get("period") or row.get("schedule_raw"))

        row_detail_warnings: list[str] = []
        if lecture_no in final_local_failure_ids:
            row_detail_warnings.append("local_detail_unavailable")
        if lecture_no in final_share_failure_ids:
            row_detail_warnings.append("share_detail_unavailable")
        raw_fields["detail_enrichment_complete"] = not row_detail_warnings
        if row_detail_warnings:
            raw_fields["detail_enrichment_warning"] = "; ".join(row_detail_warnings)
        else:
            raw_fields.pop("detail_enrichment_warning", None)

        missing_core_fields = pocheon_ggshare_core_missing_fields(
            row,
            lecture_no,
            require_official_fallback=lecture_no in detail_failure_ids,
        )
        if missing_core_fields:
            core_validation_failure_ids.append(lecture_no)
            core_missing_fields_by_id[lecture_no] = missing_core_fields
            unknown_branch_rows += int("official_branch" in missing_core_fields)
            continue
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

    detail_warning_parts: list[str] = []
    if local_detail_failures:
        detail_warning_parts.append(
            f"local detail unavailable for {local_detail_failures} current rows"
        )
    if share_detail_failures:
        detail_warning_parts.append(
            f"share.gg detail unavailable for {share_detail_failures} current rows"
        )
    if recovery_skipped_ids:
        detail_warning_parts.append(
            f"detail recovery capped at {POCHEON_GGSHARE_RECOVERY_ID_LIMIT} "
            f"of {len(recovery_candidate_ids)} failed lecture rows"
        )
    detail_enrichment_warning = "; ".join(detail_warning_parts)

    if unknown_branch_rows:
        add_error(f"could not assign an official branch to {unknown_branch_rows} current rows")
    if core_validation_failure_ids:
        add_error(f"core fields incomplete for {len(core_validation_failure_ids)} current rows")

    rows = dedupe_rows(rows)
    list_complete = (
        pagination_exhausted
        and declared_total is not None
        and declared_pages > 0
        and len(seen_lectures) == declared_total
        and invalid_rows == 0
        and duplicate_rows == 0
    )
    collection_complete = list_complete and not errors
    detail_enrichment_complete = (
        not detail_enrichment_capped
        and not local_detail_failures
        and not share_detail_failures
    )
    no_current_data = collection_complete and not rows
    meta: dict[str, Any] = {
        "pages": pages,
        "detail_pages": share_detail_pages,
        "local_detail_pages": local_detail_pages,
        "share_detail_pages": share_detail_pages,
        "local_http_attempts": local_http_attempts,
        "share_http_attempts": share_http_attempts,
        "local_retry_recoveries": local_retry_recoveries,
        "share_retry_recoveries": share_retry_recoveries,
        "initial_local_detail_failure_ids": initial_local_failure_ids,
        "initial_share_detail_failure_ids": initial_share_failure_ids,
        "local_detail_failure_ids": [
            lecture_no
            for lecture_no in recovery_candidate_ids
            if lecture_no in final_local_failure_ids
        ],
        "share_detail_failure_ids": [
            lecture_no
            for lecture_no in recovery_candidate_ids
            if lecture_no in final_share_failure_ids
        ],
        "recovery_candidate_ids": recovery_candidate_ids,
        "recovery_selected_ids": recovery_selected_ids,
        "recovery_attempted_ids": recovery_attempted_ids,
        "recovery_skipped_ids": recovery_skipped_ids,
        "recovery_complete_ids": recovery_complete_ids,
        "recovery_passes": recovery_passes,
        "recovery_session_created": recovery_session_created,
        "recovery_session_error_type": recovery_session_error_type,
        "recovery_capped": bool(recovery_skipped_ids),
        "recovery_recoveries": len(recovery_complete_ids),
        "local_recovery_attempted": local_recovery_attempted,
        "share_recovery_attempted": share_recovery_attempted,
        "local_recovery_http_attempts": local_recovery_http_attempts,
        "share_recovery_http_attempts": share_recovery_http_attempts,
        "local_recovery_recoveries": len(local_recovery_success_ids),
        "share_recovery_recoveries": len(share_recovery_success_ids),
        "local_recovery_success_ids": local_recovery_success_ids,
        "share_recovery_success_ids": share_recovery_success_ids,
        "list_pacing_seconds": POCHEON_GGSHARE_LIST_PACING_SECONDS,
        "detail_pacing_seconds": POCHEON_GGSHARE_DETAIL_PACING_SECONDS,
        "local_detail_attempt_limit": POCHEON_GGSHARE_LOCAL_DETAIL_ATTEMPTS,
        "share_detail_attempt_limit": POCHEON_GGSHARE_DETAIL_ATTEMPTS,
        "recovery_attempt_limit": POCHEON_GGSHARE_RECOVERY_ATTEMPTS,
        "recovery_id_limit": POCHEON_GGSHARE_RECOVERY_ID_LIMIT,
        "recovery_cooldown_seconds": POCHEON_GGSHARE_RECOVERY_COOLDOWN_SECONDS,
        "recovery_item_cooldown_seconds": POCHEON_GGSHARE_RECOVERY_ITEM_COOLDOWN_SECONDS,
        "recovery_backoff_seconds": POCHEON_GGSHARE_RECOVERY_BACKOFF_SECONDS,
        "detail_candidates": len(current_items),
        "detail_enrichment_capped": detail_enrichment_capped,
        "detail_enrichment_complete": detail_enrichment_complete,
        "detail_enrichment_warning": detail_enrichment_warning,
        "detail_failures": local_detail_failures + share_detail_failures,
        "discovered_links": len(seen_lectures),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "pagination_detected": declared_pages > 1,
        "pagination_complete": collection_complete,
        "list_collection_complete": collection_complete,
        "core_fields_complete": collection_complete,
        "list_pagination_complete": list_complete,
        "pagination_exhausted": pagination_exhausted,
        "source_cap_reached": source_cap_reached,
        "recursion_depth": 0,
        "total_count": declared_total or 0,
        "total_pages": declared_pages,
        "expired_count": expired_rows,
        "test_rows": test_rows,
        "invalid_count": invalid_rows,
        "duplicate_count": duplicate_rows,
        "current_count": len(current_items),
        "local_detail_failures": local_detail_failures,
        "share_detail_failures": share_detail_failures,
        "unknown_branch_rows": unknown_branch_rows,
        "core_validation_failure_ids": core_validation_failure_ids,
        "core_missing_fields_by_id": core_missing_fields_by_id,
        "no_current_data": no_current_data,
        "no_current_reason": "all listed courses are expired or test rows" if no_current_data else "",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(errors)
    return rows, POCHEON_GGSHARE_PARSER, meta


SB_PROVIDER = "MUNI_WWW_SB_GO_KR_FF615DE7"
SB_LIFELONG_PROVIDER = "MUNI_WWW_SB_GO_KR_CCBBD62B"
SB_LIST_URL = "https://www.sb.go.kr/yeyak/selectUnityProgrmWebList.do"
SB_DETAIL_URL = "https://www.sb.go.kr/yeyak/unityProgrmWebView.do"
SB_PAGE_SIZE = 100


def is_sb_unity_program_target(url: str) -> bool:
    parsed = urlparse(url)
    return (
        parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == "www.sb.go.kr"
        and parsed.path == "/yeyak/selectUnityProgrmWebList.do"
    )


def sb_target_params(target_url: str) -> dict[str, str]:
    if not is_sb_unity_program_target(target_url):
        raise ValueError("SB target must use the official HTTPS unity program list")
    query = parse_qs(urlparse(target_url).query)
    key = clean_text((query.get("key") or [""])[0])
    institution_type = clean_text((query.get("insttTy") or [""])[0])
    institution_no = clean_text((query.get("searchInsttNo") or [""])[0])
    if not re.fullmatch(r"\d+", key):
        raise ValueError("SB target key must be numeric")
    if institution_type != "URINTY01":
        raise ValueError("SB target insttTy must be URINTY01")
    if not re.fullmatch(r"\d+", institution_no):
        raise ValueError("SB target searchInsttNo must be numeric")
    return {
        "key": key,
        "insttTy": institution_type,
        "searchInsttNo": institution_no,
        "viewType": "list",
        "pageUnit": str(SB_PAGE_SIZE),
    }


def sb_clean_label(value: Any) -> str:
    return clean_text(value).lstrip("※ㆍ·• ").strip()


def sb_reservation_available(status: Any) -> bool:
    return public_course_reservation_available(status)


def sb_normalize_range(value: Any) -> str:
    text = clean_text(value).replace("\r", " ").replace("\n", " ")
    text = re.sub(r"\s*~\s*", " ~ ", text)
    text = re.sub(r"\s+", " ", text).strip()
    text = re.sub(
        r"(\d{4})[.](\d{1,2})[.](\d{1,2})",
        lambda match: f"{match.group(1)}-{int(match.group(2)):02d}-{int(match.group(3)):02d}",
        text,
    )
    return text


def sb_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for table in soup.select("table"):
        for tr in table.select("tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
            cells = [cell for cell in cells if cell]
            if len(cells) == 2:
                pairs[sb_clean_label(cells[0])] = cells[1]
    return pairs


def sb_extract_address(soup: BeautifulSoup) -> tuple[str, str, str]:
    venue_name = clean_text(soup.select_one(".map_info").get_text(" ", strip=True)) if soup.select_one(".map_info") else ""
    address = clean_text(soup.select_one(".map_info_item.address").get_text(" ", strip=True)) if soup.select_one(".map_info_item.address") else ""
    phone = clean_text(soup.select_one(".map_info_item.tel").get_text(" ", strip=True)) if soup.select_one(".map_info_item.tel") else ""
    if address:
        return venue_name, address.replace("\xa0", " "), phone
    lines = [clean_text(line).replace("\xa0", " ") for line in soup.get_text("\n", strip=True).splitlines()]
    for index, line in enumerate(lines):
        if re.match(r"^(서울|경기|인천|부산|대구|광주|대전|울산|세종|강원|충북|충남|전북|전남|경북|경남|제주)", line):
            venue_name = lines[index - 1] if index > 0 else ""
            phone = lines[index + 1] if index + 1 < len(lines) and re.search(r"\d{2,4}-\d{3,4}-\d{4}", lines[index + 1]) else ""
            return venue_name, line, phone
    return "", "", ""


def sb_facility_branch_room(
    venue_name: str,
    venue_address: str,
    operator: str,
) -> tuple[str, str]:
    venue_name = clean_text(venue_name)
    venue_address = clean_text(venue_address)
    operator = clean_text(operator)
    if venue_name.startswith("성북구평생학습관"):
        room = clean_text(venue_name.removeprefix("성북구평생학습관"))
        return "성북구평생학습관", room
    if venue_name.startswith("국민대학교"):
        room = clean_text(venue_name.removeprefix("국민대학교"))
        return "국민대학교", room
    resident_center = re.search(r"([가-힣0-9]+동\s*주민센터)", venue_address)
    if resident_center:
        return clean_text(resident_center.group(1)), venue_name
    if venue_name:
        return venue_name, ""
    return operator, ""


def sb_detail_fields(
    s: requests.Session,
    params: dict[str, str],
    title: str,
    timeout: int,
) -> tuple[dict[str, Any], str]:
    detail_url = f"{SB_DETAIL_URL}?{urlencode(params)}"
    try:
        soup = fetch_soup(s, detail_url, timeout=timeout)
    except Exception as exc:
        logger.debug(
            "SB detail fetch failed url=%s error_type=%s",
            safe_url_for_log(detail_url),
            type(exc).__name__,
        )
        return {}, detail_url
    pairs = sb_detail_pairs(soup)
    venue_name, venue_address, phone = sb_extract_address(soup)
    time_range = sb_normalize_range(pairs.get("교육시간"))
    weekday = clean_text(pairs.get("교육요일"))
    schedule_raw = clean_text(" ".join(part for part in [weekday, time_range] if part))
    fee = extract_krw_amount(pairs.get("이용요금")) or clean_text(pairs.get("이용요금"))
    material_fee_text = clean_text(
        pairs.get("재료비/교재비") or pairs.get("재료비") or pairs.get("교재비")
    )
    operator = clean_text(pairs.get("운영기관"))
    status = clean_text(pairs.get("접수상태") or pairs.get("운영상태") or pairs.get("상태"))
    place = clean_text(pairs.get("장소")) or venue_name
    branch, room = sb_facility_branch_room(venue_name or place, venue_address, operator)
    detail_text = soup.get_text("\n", strip=True)
    description = ""
    match = re.search(r"운영내용\s+(.*?)(?:장소안내|유의사항|환불정책|목록)", detail_text, re.DOTALL)
    if match:
        description = clean_text(match.group(1))
        if description == "운영내용":
            description = ""
    return (
        {
            "title": title,
            "branch": branch,
            "preserve_branch": True,
            "category": clean_text(pairs.get("교육과정") or pairs.get("구분")),
            "raw_url": detail_url,
            "application_url": detail_url,
            "status": status,
            "period": sb_normalize_range(pairs.get("교육기간")),
            "apply_period": sb_normalize_range(pairs.get("접수기간")),
            "schedule_raw": schedule_raw,
            "target": clean_text(pairs.get("교육대상") or pairs.get("대상")),
            "room": room,
            "venue_name": branch,
            "venue_address": venue_address,
            "address": venue_address,
            "phone": phone or clean_text(pairs.get("문의전화")),
            "fee": fee,
            "material_fee": extract_material_fee_amount(
                f"재료비/교재비 {material_fee_text}" if material_fee_text else ""
            ),
            "description": description,
            "capacity": parse_capacity_number(pairs.get("모집인원")),
            "waitlist_total": parse_capacity_number(pairs.get("대기 모집인원")),
            "application_method_raw": clean_text(pairs.get("접수방법")),
            "raw_fields": {
                "detail_pairs": pairs,
                "operator": operator,
                "source_venue_name": venue_name or place,
                "parser": "sb_unity_program_categories",
            },
        },
        detail_url,
    )


def sb_row_from_table(
    target: CrawlTarget,
    s: requests.Session,
    tr: Any,
    params: dict[str, str],
    timeout: int,
    detail_pages: int,
    detail_limit: int,
) -> tuple[dict[str, Any], int]:
    cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.select("td")]
    if len(cells) < 8:
        return {}, detail_pages
    title = cells[1]
    link = tr.find("a", href=True)
    match = re.search(r"fnView\([^,]+,\s*(\d+)\)", link.get("href") if link else "")
    program_no = match.group(1) if match else ""
    if not program_no:
        return {}, detail_pages
    detail_params = {"key": params["key"], "progrmNo": program_no}
    raw_url = f"{SB_DETAIL_URL}?{urlencode(detail_params)}"
    branch = cells[4] or target.branch
    current_capacity, total_capacity = parse_capacity_pair(cells[6])
    period = sb_normalize_range(cells[3])
    start_date, end_date = parse_date_range(period)
    status = cells[7]
    reservation_available = sb_reservation_available(status)
    base: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:program:{program_no}"[:100],
        "title": title,
        "branch": branch,
        "category": "",
        "raw_url": raw_url,
        "application_url": raw_url if reservation_available else "",
        "application_type": "ONLINE_RESERVATION" if reservation_available else "",
        "reservation_available": reservation_available,
        "apply_period": sb_normalize_range(cells[2]),
        "period": period,
        "start_date": start_date,
        "end_date": end_date,
        "schedule_raw": clean_text(cells[5]),
        "capacity": total_capacity,
        "capacity_current": current_capacity,
        "status": status,
        "collection_category": clean_text(target.extra.get("collection_category") or "공공예약"),
        "domain_category": clean_text(target.extra.get("domain_category") or "교육·강좌"),
        "operator_type": clean_text(target.extra.get("operator_type") or "지자체/공공기관"),
        "source_group": clean_text(target.extra.get("source_group") or "public_reservation"),
        "collection_type": "static_html",
        "program_type": "강좌",
        "raw_fields": {
            "list_cells": cells,
            "program_no": program_no,
            "target_key": params.get("key", ""),
            "institution_no": params.get("searchInsttNo", ""),
            "parser": "sb_unity_program_categories",
        },
    }
    if should_skip_expired_course(base):
        return {}, detail_pages
    if program_no and detail_pages < detail_limit:
        detail, raw_url = sb_detail_fields(s, detail_params, title, timeout)
        if detail:
            detail_status = clean_text(detail.get("status"))
            base = merge_course_rows(base, detail)
            for key in (
                "branch",
                "preserve_branch",
                "category",
                "period",
                "apply_period",
                "schedule_raw",
                "target",
                "room",
                "venue_name",
                "venue_address",
                "address",
                "phone",
                "fee",
                "material_fee",
                "description",
                "capacity",
                "waitlist_total",
                "application_method_raw",
            ):
                if detail.get(key) not in (None, "", [], {}):
                    base[key] = detail[key]
            base["status"] = detail_status or cells[7] or base.get("status", "")
            base["provider_course_id"] = f"{target.provider}:program:{program_no}"[:100]
            detail_pages += 1
    reservation_available = sb_reservation_available(base.get("status"))
    base["reservation_available"] = reservation_available
    base["application_url"] = raw_url if reservation_available else ""
    base["application_type"] = "ONLINE_RESERVATION" if reservation_available else ""
    return base, detail_pages


def collect_sb_unity_program_categories(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    pages_seen = 0
    base_params = sb_target_params(target.url)
    seen_programs: set[str] = set()
    expired_rows = 0
    ended_rows = 0
    test_rows = 0
    invalid_rows = 0
    no_data_placeholders = 0
    structurally_valid_rows = 0
    pagination_exhausted = False
    partial_collection_error = ""
    for page_index in range(1, max(1, max_pages) + 1):
        params = dict(base_params)
        params["pageIndex"] = str(page_index)
        soup = fetch_soup(s, f"{SB_LIST_URL}?{urlencode(params)}", timeout=timeout)
        table_rows = soup.select("table.p-table tbody tr")
        pages_seen += 1
        if not table_rows:
            pagination_exhausted = True
            break
        page_new_items = 0
        for tr in table_rows:
            if is_explicit_course_no_data_row(tr):
                no_data_placeholders += 1
                continue
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.select("td")]
            link = tr.find("a", href=True)
            match = re.search(r"fnView\([^,]+,\s*(\d+)\)", link.get("href") if link else "")
            program_no = match.group(1) if match else ""
            if not program_no or len(cells) < 8 or not cells[1] or is_low_value_title(cells[1]):
                invalid_rows += 1
                continue
            if program_no in seen_programs:
                continue
            seen_programs.add(program_no)
            page_new_items += 1
            structurally_valid_rows += 1
            if "테스트" in cells[1]:
                test_rows += 1
                continue
            if is_confirmed_course_ended_status(cells[7]):
                ended_rows += 1
                continue
            before_detail_pages = detail_pages
            parsed, detail_pages = sb_row_from_table(
                target,
                s,
                tr,
                params,
                timeout,
                detail_pages,
                detail_limit,
            )
            if parsed:
                if is_confirmed_course_ended_status(parsed.get("status")):
                    ended_rows += 1
                else:
                    rows.append(parsed)
            elif detail_pages == before_detail_pages:
                if len(cells) >= 4:
                    _start, end = parse_date_range(sb_normalize_range(cells[3]))
                    if end and should_skip_expired_course({"end_date": end}):
                        expired_rows += 1
                    else:
                        invalid_rows += 1
                else:
                    invalid_rows += 1
        if len(table_rows) < SB_PAGE_SIZE:
            pagination_exhausted = True
            break
        if page_new_items == 0:
            partial_collection_error = f"page {page_index} repeated previously discovered programs"
            break
    if not pagination_exhausted and not partial_collection_error:
        partial_collection_error = f"pagination capped at {max(1, max_pages)} pages"
    if structurally_valid_rows == 0 and invalid_rows > 0 and not partial_collection_error:
        partial_collection_error = (
            f"all listed program rows were malformed ({invalid_rows} invalid rows)"
        )
    rows = dedupe_rows(rows)
    collection_complete = pagination_exhausted and not partial_collection_error
    no_current_data = collection_complete and not rows
    meta = {
        "pages": pages_seen,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_programs),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "pagination_detected": pages_seen > 1,
        "pagination_complete": collection_complete,
        "pagination_exhausted": collection_complete,
        "expired_rows": expired_rows,
        "ended_rows": ended_rows,
        "test_rows": test_rows,
        "invalid_count": invalid_rows,
        "valid_count": structurally_valid_rows,
        "no_data_placeholders": no_data_placeholders,
        "detail_candidates": len(rows),
        "detail_enrichment_capped": max(0, detail_limit) < len(rows),
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": (
            "explicit no-data placeholder"
            if no_current_data and no_data_placeholders and structurally_valid_rows == 0
            else "all listed programs are expired, ended, or test rows"
            if no_current_data
            else ""
        ),
        "target_key": base_params["key"],
        "institution_no": base_params["searchInsttNo"],
    }
    if partial_collection_error:
        meta["configured_collection_error"] = partial_collection_error
    return (
        rows,
        "sb_unity_program_categories",
        meta,
    )


