def is_gwangjin_education_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == GWANGJIN_EDU_PROVIDER
        and parsed.scheme == "https"
        and parsed.netloc.lower() == GWANGJIN_EDU_HOST
        and parsed.path == GWANGJIN_EDU_LIST_PATH
    )


def is_gwangjin_fmcs_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == GWANGJIN_FMCS_PROVIDER
        and parsed.scheme == "https"
        and parsed.netloc.lower() == "booking.gwangjin.or.kr"
        and parsed.path == "/fmcs/2"
    )


def gwangjin_iso_dates(value: Any) -> list[str]:
    return re.findall(r"\b\d{4}-\d{2}-\d{2}\b", clean_text(value))


def gwangjin_program_end_date(value: Any) -> Optional[datetime]:
    dates = gwangjin_iso_dates(value)
    if not dates:
        return None
    try:
        return datetime.strptime(dates[-1], "%Y-%m-%d")
    except ValueError:
        return None


def gwangjin_edu_declaration(soup: BeautifulSoup) -> tuple[int, int, int] | None:
    text = clean_text(soup.get_text(" ", strip=True))
    match = re.search(
        r"Total\s*:\s*([\d,]+)\s*건\s*\[\s*(\d+)\s*/\s*(\d+)\s*pages\s*\]",
        text,
        re.IGNORECASE,
    )
    if not match:
        return None
    return int(match.group(1).replace(",", "")), int(match.group(2)), int(match.group(3))


def gwangjin_edu_capacity(value: Any) -> tuple[str, str, str, str]:
    text = clean_text(value)
    match = re.search(
        r"([\d,]+)명\s*\(([\d,]+)명\)\s*/\s*([\d,]+)명\s*\(([\d,]+)명\)",
        text,
    )
    if not match:
        return "", "", "", ""
    capacity_total, waitlist_total, capacity_current, waitlist_current = (
        value.replace(",", "") for value in match.groups()
    )
    return capacity_current, capacity_total, waitlist_current, waitlist_total


def gwangjin_edu_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dt in soup.select(".viewt dl > dt"):
        dd = dt.find_next_sibling("dd")
        key = clean_text(dt.get_text(" ", strip=True))
        value = clean_text(dd.get_text(" ", strip=True) if dd else "")
        if key and value:
            pairs[key] = value
    return pairs


def gwangjin_edu_fee_fields(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    main = clean_text(text.split("(", 1)[0])
    fee_match = re.search(r"([\d,]+)\s*원", main)
    fee = f"{fee_match.group(1)}원" if fee_match else main
    material_match = re.search(r"(?:교재\s*)?재료비\s*별도\s*:\s*([\d,]+)\s*원", text)
    material_fee = f"{material_match.group(1)}원" if material_match else ""
    return fee, material_fee


def gwangjin_edu_venue_teacher(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    if not text:
        return "", ""
    venue, separator, teacher = text.partition("/")
    if not separator:
        return text, ""
    return clean_text(venue), clean_text(re.sub(r"\(\s*강사\s*\)\s*$", "", teacher))


def gwangjin_edu_list_row(target: CrawlTarget, page_url: str, tr: Any) -> tuple[Optional[dict[str, Any]], str]:
    link = tr.find("a", href=lambda href: bool(href and "progrmSn=" in href))
    if not link:
        return None, ""
    cells = [
        clean_text(cell.get_text(" ", strip=True))
        for cell in tr.find_all(["th", "td"], recursive=False)
    ]
    if len(cells) < 6:
        return None, "malformed table row"
    detail_url = urljoin(page_url, clean_text(link.get("href")))
    query = parse_qs(urlparse(detail_url).query)
    program_id = clean_text((query.get("progrmSn") or [""])[0])
    title = re.sub(r"^\d+\.\s*", "", clean_text(link.get_text(" ", strip=True)))
    status_raw = cells[0]
    period = cells[3]
    if not re.fullmatch(r"\d{1,12}", program_id) or not title or not status_raw:
        return None, "missing official program ID, title, or status"
    if gwangjin_program_end_date(period) is None:
        return None, f"program {program_id} has no valid education end date"
    category_code = clean_text((query.get("ctgryCd") or [""])[0])
    category_detail_code = clean_text((query.get("ctgryDetailCd") or [""])[0])
    capacity_current, capacity_total, waitlist_current, waitlist_total = gwangjin_edu_capacity(cells[5])
    application_method = ""
    method_match = re.search(r"[【\[]\s*([^】\]]+)\s*[】\]]", cells[5])
    if method_match:
        application_method = clean_text(method_match.group(1))
    row: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:program:{program_id}",
        "prefer_incoming_provider_course_id": True,
        "title": title,
        "branch": GWANGJIN_EDU_BRANCH,
        "branch_code": GWANGJIN_EDU_BRANCH_CODE,
        "branch_url": GWANGJIN_EDU_LIST_URL,
        "preserve_branch": True,
        "category": GWANGJIN_EDU_CATEGORY_NAMES.get(category_code, "교육"),
        "raw_url": detail_url,
        "status": GWANGJIN_EDU_STATUS_MAP.get(status_raw, status_raw),
        "reservation_available": False,
        "period": period,
        "apply_period": cells[4],
        "schedule_raw": cells[2],
        "capacity": capacity_total,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_current": waitlist_current,
        "waitlist_total": waitlist_total,
        "application_method_raw": application_method,
        "program_type": "강좌",
        "collection_category": "공공예약",
        "domain_category": "교육·강좌",
        "source_group": "municipal_reservation",
        "operator_type": "지자체/공공기관",
        "collection_type": "current_programs+detail_html",
        "service_group": "공공강좌",
        "service_group_policy": "locked",
        "municipality_code": GWANGJIN_MUNICIPALITY_CODE,
        "municipality_full_name": GWANGJIN_MUNICIPALITY_NAME,
        "raw_fields": {
            "parser": GWANGJIN_EDU_PARSER,
            "program_id": program_id,
            "category_code": category_code,
            "category_detail_code": category_detail_code,
            "status_raw": status_raw,
            "list_cells": cells,
            "page_url": page_url,
            "clear_application_url": True,
        },
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}, ""


def gwangjin_enrich_edu_detail(row: dict[str, Any], soup: BeautifulSoup) -> bool:
    if not soup.select_one(".viewt"):
        return False
    pairs = gwangjin_edu_detail_pairs(soup)
    if not pairs.get("교육기간") or not pairs.get("교육장/강사"):
        return False
    row["apply_period"] = clean_text(pairs.get("접수기간")) or row.get("apply_period", "")
    row["period"] = clean_text(pairs.get("교육기간")) or row.get("period", "")
    row["schedule_raw"] = clean_text(pairs.get("교육시간")) or row.get("schedule_raw", "")
    row["target"] = clean_text(pairs.get("교육대상"))
    venue, instructor = gwangjin_edu_venue_teacher(pairs.get("교육장/강사"))
    row["venue_name"] = venue
    row["instructor"] = instructor
    row["phone"] = clean_text(pairs.get("문의사항"))
    fee, material_fee = gwangjin_edu_fee_fields(pairs.get("수강료"))
    row["fee"] = fee
    row["material_fee"] = material_fee
    capacity_current, capacity_total, waitlist_current, waitlist_total = gwangjin_edu_capacity(
        pairs.get("접수현황")
    )
    for key, value in (
        ("capacity", capacity_total),
        ("capacity_current", capacity_current),
        ("capacity_total", capacity_total),
        ("waitlist_current", waitlist_current),
        ("waitlist_total", waitlist_total),
    ):
        if value:
            row[key] = value
    description_parts = []
    for selector in ("#tab-area-1", "#tab-area-3"):
        node = soup.select_one(selector)
        value = clean_text(node.get_text(" ", strip=True) if node else "")
        if value and value not in description_parts:
            description_parts.append(value)
    row["description"] = clean_text(" ".join(description_parts))[:8000]
    application_link = next(
        (
            link
            for link in soup.select(".btnSet a.b-submit[href]")
            if "신청" in clean_text(link.get_text(" ", strip=True))
        ),
        None,
    )
    raw_fields = row.setdefault("raw_fields", {})
    raw_fields["detail_pairs"] = pairs
    raw_fields["detail_url"] = row.get("raw_url")
    raw_fields["clear_application_url"] = application_link is None
    if application_link is not None:
        application_url = urljoin(str(row.get("raw_url") or GWANGJIN_EDU_LIST_URL), application_link.get("href"))
        row["application_url"] = application_url
        row["reservation_available"] = True
        raw_fields["application_link_text"] = clean_text(application_link.get_text(" ", strip=True))
        raw_fields["application_link_kind"] = "official_applcnt"
    else:
        row.pop("application_url", None)
        row["reservation_available"] = False
    return True


def collect_gwangjin_education_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if not is_gwangjin_education_target(target):
        raise ValueError("Gwangjin education target must use the owned official HTTPS all-program route")
    s = session()
    seen: set[str] = set()
    listed_rows: list[dict[str, Any]] = []
    pages = 0
    declared_total: Optional[int] = None
    declared_pages = 0
    malformed_rows = 0
    duplicate_rows = 0
    errors: list[str] = []
    pagination_complete = False

    for page in range(1, max(1, max_pages) + 1):
        query = {"ctgryCd": "", "menuNo": "400008", "pageUnit": str(GWANGJIN_EDU_PAGE_SIZE), "pageIndex": str(page)}
        page_url = f"https://{GWANGJIN_EDU_HOST}{GWANGJIN_EDU_LIST_PATH}?{urlencode(query)}"
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        declaration = gwangjin_edu_declaration(soup)
        if declaration is None:
            errors.append(f"page {page} did not expose a valid total/page declaration")
            break
        page_total, current_page, page_count = declaration
        if current_page != page:
            errors.append(f"page {page} declared itself as page {current_page}")
        if declared_total is None:
            declared_total, declared_pages = page_total, page_count
        elif (page_total, page_count) != (declared_total, declared_pages):
            errors.append(
                f"page {page} changed the declaration from {declared_total}/{declared_pages} to {page_total}/{page_count}"
            )
        page_rows = 0
        for tr in soup.select("tbody tr"):
            row, error = gwangjin_edu_list_row(target, page_url, tr)
            if error:
                malformed_rows += 1
                errors.append(error)
                continue
            if row is None:
                continue
            page_rows += 1
            program_id = clean_text(row.get("raw_fields", {}).get("program_id"))
            if program_id in seen:
                duplicate_rows += 1
                continue
            seen.add(program_id)
            listed_rows.append(row)
        if page < declared_pages and page_rows != GWANGJIN_EDU_PAGE_SIZE:
            errors.append(
                f"non-terminal page {page} exposed {page_rows} of {GWANGJIN_EDU_PAGE_SIZE} published rows"
            )
        if page >= declared_pages:
            pagination_complete = True
            break
        if page >= max_pages:
            errors.append(f"max_pages cap reached after {page} of {declared_pages} declared pages")
            break

    published_gap = (declared_total or 0) - len(seen)
    if pagination_complete and declared_total is not None:
        if published_gap < 0 or published_gap >= GWANGJIN_EDU_PAGE_SIZE:
            errors.append(
                f"published rows {len(seen)} are incompatible with declared total {declared_total}"
            )
    if duplicate_rows:
        errors.append(f"duplicated official progrmSn values ({duplicate_rows})")
    if malformed_rows:
        errors.append(f"malformed official list rows ({malformed_rows})")

    today = datetime.now().date()
    current_rows = [
        row
        for row in listed_rows
        if (gwangjin_program_end_date(row.get("period")) or datetime.min).date() >= today
    ]
    expired_count = len(listed_rows) - len(current_rows)
    detail_attempts = min(max(0, detail_limit), len(current_rows))
    detail_pages = 0
    detail_failures: list[str] = []
    for row in current_rows[:detail_attempts]:
        try:
            detail_soup = fetch_soup(s, str(row.get("raw_url")), timeout=timeout)
            if not gwangjin_enrich_edu_detail(row, detail_soup):
                detail_failures.append(clean_text(row.get("raw_fields", {}).get("program_id")))
                continue
            detail_pages += 1
        except Exception as exc:
            program_id = clean_text(row.get("raw_fields", {}).get("program_id"))
            detail_failures.append(program_id)
            logger.debug("Gwangjin education detail fetch failed program=%s error_type=%s", program_id, type(exc).__name__)
    details_complete = detail_attempts == len(current_rows) and not detail_failures
    if detail_attempts < len(current_rows):
        errors.append(f"detail enrichment capped at {detail_attempts} of {len(current_rows)}")
    if detail_failures:
        errors.append(f"detail fetch or parse failed for {len(detail_failures)} programs")

    status_counts = Counter(clean_text(row.get("raw_fields", {}).get("status_raw")) for row in current_rows)
    snapshot_complete = pagination_complete and details_complete and not errors
    no_current_data = pagination_complete and not current_rows and not errors
    meta: dict[str, Any] = {
        "pages": pages,
        "declared_pages": declared_pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(seen),
        "raw_row_count": len(listed_rows),
        "total_count": declared_total or 0,
        "published_row_gap": published_gap,
        "current_count": len(current_rows),
        "expired_count": expired_count,
        "status_counts": dict(status_counts),
        "malformed_rows": malformed_rows,
        "duplicate_rows": duplicate_rows,
        "pagination_detected": declared_pages > 1,
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in current_rows),
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": "all published programs have ended" if no_current_data else "",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(current_rows), GWANGJIN_EDU_PARSER, meta


def gwangjin_fmcs_row(target: CrawlTarget, item: dict[str, Any]) -> Optional[dict[str, Any]]:
    comcd = clean_text(item.get("comcd"))
    class_cd = clean_text(item.get("class_cd"))
    title = clean_text(item.get("class_nm"))
    status_code = clean_text(item.get("status")).upper()
    if not comcd or not class_cd or not title or not status_code:
        return None
    row = fmcs_row_from_api_item(target, GWANGJIN_FMCS_LIST_URL, item, status_code)
    row.update(
        {
            "provider_course_id": f"{target.provider}:class:{comcd}:{class_cd}",
            "prefer_incoming_provider_course_id": True,
            "branch": clean_text(item.get("comnm")) or target.branch,
            "branch_code": comcd,
            "branch_url": GWANGJIN_FMCS_LIST_URL,
            "preserve_branch": True,
            "reservation_available": status_code in {"R", "RW"},
            "program_type": "강좌",
            "collection_category": "공공예약",
            "domain_category": "교육·강좌",
            "source_group": "municipal_reservation",
            "operator_type": "지자체/공공기관",
            "collection_type": "company_lecture_api+detail_html",
            "service_group": "공공강좌",
            "service_group_policy": "locked",
            "municipality_code": GWANGJIN_MUNICIPALITY_CODE,
            "municipality_full_name": GWANGJIN_MUNICIPALITY_NAME,
        }
    )
    raw_fields = row.setdefault("raw_fields", {})
    raw_fields.update(
        {
            "parser": GWANGJIN_FMCS_PARSER,
            "official_company_code": comcd,
            "official_class_code": class_cd,
            "status_code": status_code,
            "clear_application_url": status_code not in {"R", "RW"},
        }
    )
    if status_code in {"R", "RW"}:
        row["application_url"] = row["raw_url"]
    else:
        row.pop("application_url", None)
    return row


def collect_gwangjin_fmcs_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if not is_gwangjin_fmcs_target(target):
        raise ValueError("Gwangjin FMCS target must use the owned official HTTPS lecture route")
    s = session()
    root_url = fmcs_root_url(target.url)
    method = fmcs_http_method(s, root_url, target.url, timeout)
    companies = fmcs_json_rows(
        fmcs_request_json(s, root_url, "rest/common/company", {"type": "L"}, method, target.url, timeout)
    )
    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    pages = 0
    api_requests = 0
    raw_row_count = 0
    malformed_rows = 0
    duplicate_rows = 0
    declared_total = 0
    errors: list[str] = []
    company_totals: dict[str, int] = {}
    company_pages: dict[str, int] = {}
    status_counts: Counter[str] = Counter()
    page_size = 100

    for company in companies:
        comcd = clean_text(company.get("comcd"))
        if not comcd:
            malformed_rows += 1
            continue
        page = 1
        company_total: Optional[int] = None
        expected_pages = 1
        while page <= expected_pages:
            if pages >= max(1, max_pages):
                errors.append(f"max_pages cap reached before completing company {comcd}")
                break
            params = {
                "company_code": comcd,
                "mem_no": "",
                "search_type": "%",
                "category_cd": "",
                "category_level": "9",
                "class_nm": "",
                "train_day": "",
                "adult_gubn": "",
                "lecturer_nm": "",
                "page": str(page),
                "page_size": str(page_size),
            }
            data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, target.url, timeout)
            api_requests += 1
            pages += 1
            items = fmcs_json_rows(data)
            if not items:
                if page == 1:
                    company_total = 0
                    expected_pages = 1
                else:
                    errors.append(f"company {comcd} page {page} was unexpectedly empty")
                break
            page_total = fmcs_int(items[0].get("total_count"), -1)
            if page_total < 0:
                errors.append(f"company {comcd} page {page} omitted total_count")
                break
            if company_total is None:
                company_total = page_total
                expected_pages = max(1, (company_total + page_size - 1) // page_size)
            elif page_total != company_total:
                errors.append(f"company {comcd} changed total_count from {company_total} to {page_total}")
            raw_row_count += len(items)
            for item in items:
                identity = (clean_text(item.get("comcd")), clean_text(item.get("class_cd")))
                row = gwangjin_fmcs_row(target, item)
                if row is None or identity[0] != comcd:
                    malformed_rows += 1
                    continue
                if identity in seen:
                    duplicate_rows += 1
                    continue
                seen.add(identity)
                rows.append(row)
                status_counts[clean_text(item.get("status")).upper()] += 1
            page += 1
        company_total = company_total or 0
        company_totals[comcd] = company_total
        company_pages[comcd] = expected_pages
        declared_total += company_total
        if pages >= max(1, max_pages) and page <= expected_pages:
            break

    if len(seen) != declared_total:
        errors.append(f"parsed {len(seen)} unique company/class IDs of {declared_total} declared rows")
    if malformed_rows:
        errors.append(f"malformed FMCS rows ({malformed_rows})")
    if duplicate_rows:
        errors.append(f"duplicated FMCS company/class IDs ({duplicate_rows})")

    detail_attempts = min(max(0, detail_limit), len(rows))
    detail_pages = 0
    detail_failures: list[str] = []
    for row in rows[:detail_attempts]:
        identity = clean_text(row.get("provider_course_id"))
        try:
            detail = fmcs_detail_fields(s, str(row.get("raw_url")), timeout)
            if not detail.get("title") or not detail.get("venue_name"):
                detail_failures.append(identity)
                continue
            row.update({key: value for key, value in detail.items() if value not in (None, "", [], {})})
            detail_pairs = detail.get("raw_detail_pairs") if isinstance(detail.get("raw_detail_pairs"), dict) else {}
            if clean_text(detail_pairs.get("접수방식")):
                row["application_method_raw"] = clean_text(detail_pairs.get("접수방식"))
            row["raw_fields"]["detail_pairs"] = detail_pairs
            row["raw_fields"]["detail_url"] = row.get("raw_url")
            detail_pages += 1
        except Exception as exc:
            detail_failures.append(identity)
            logger.debug("Gwangjin FMCS detail fetch failed identity=%s error_type=%s", identity, type(exc).__name__)
    details_complete = detail_attempts == len(rows) and not detail_failures
    if detail_attempts < len(rows):
        errors.append(f"detail enrichment capped at {detail_attempts} of {len(rows)}")
    if detail_failures:
        errors.append(f"detail fetch or parse failed for {len(detail_failures)} classes")

    pagination_complete = len(company_totals) == len(companies) and len(seen) == declared_total
    snapshot_complete = pagination_complete and details_complete and not errors
    meta: dict[str, Any] = {
        "pages": pages,
        "api_requests": api_requests,
        "raw_row_count": raw_row_count,
        "total_count": declared_total,
        "company_count": len(companies),
        "company_totals": company_totals,
        "company_pages": company_pages,
        "status_counts": dict(status_counts),
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(seen),
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in rows),
        "pagination_detected": pages > len(companies),
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "http_method": method,
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(rows), GWANGJIN_FMCS_PARSER, meta


