def nowon_public_course_fields(collection_type: str) -> dict[str, Any]:
    return {
        "program_type": "강좌",
        "collection_category": "공공예약",
        "domain_category": "교육·강좌",
        "source_group": "municipal_reservation",
        "operator_type": "지자체/공공기관",
        "collection_type": collection_type,
        "service_group": "공공강좌",
        "service_group_policy": "locked",
        "municipality_code": NOWON_MUNICIPALITY_CODE,
        "municipality_full_name": NOWON_MUNICIPALITY_NAME,
    }


def is_nowon_lifelong_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == NOWON_LIFELONG_PROVIDER
        and parsed.scheme == "https"
        and parsed.netloc.lower() == NOWON_LIFELONG_HOST
        and parsed.path == NOWON_LIFELONG_LIST_PATH
        and not parsed.query
    )


def is_nowon_fmcs_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == NOWON_FMCS_PROVIDER
        and parsed.scheme == "https"
        and parsed.netloc.lower() == NOWON_FMCS_HOST
        and parsed.path == NOWON_FMCS_LIST_PATH
        and not parsed.query
    )


def nowon_status(value: Any) -> str:
    raw = clean_text(value)
    compact = re.sub(r"\s+", "", raw)
    return NOWON_LIFELONG_STATUS_MAP.get(compact, raw)


def nowon_date_range(value: Any) -> str:
    text = clean_text(value)
    matches = re.findall(
        r"(?<!\d)(\d{2}|\d{4})[.\-/](\d{1,2})[.\-/](\d{1,2})(?:[_T ](\d{1,2}:\d{2}))?",
        text,
    )
    values: list[str] = []
    for year, month, day, clock in matches[:2]:
        full_year = int(year) + 2000 if len(year) == 2 else int(year)
        value_text = f"{full_year:04d}-{int(month):02d}-{int(day):02d}"
        if clock:
            value_text = f"{value_text} {clock}"
        values.append(value_text)
    if len(values) >= 2:
        return values[0] if values[0] == values[1] else f"{values[0]} ~ {values[1]}"
    return values[0] if values else text


def nowon_period_end(value: Any) -> Optional[datetime]:
    matches = re.findall(r"\b(\d{4}-\d{2}-\d{2})\b", nowon_date_range(value))
    if not matches:
        return None
    try:
        return datetime.strptime(matches[-1], "%Y-%m-%d")
    except ValueError:
        return None


def nowon_branch_code(prefix: str, branch: Any) -> str:
    name = clean_text(branch)
    digest = hashlib.sha1(name.encode("utf-8")).hexdigest()[:12].upper()
    return f"{prefix}_{digest}"


def nowon_fetch_soups_parallel(
    urls: list[str],
    timeout: int,
    *,
    workers: int = 4,
) -> tuple[dict[int, BeautifulSoup], dict[int, str]]:
    """Fetch large official detail snapshots with a small, bounded connection pool."""
    soups: dict[int, BeautifulSoup] = {}
    failures: dict[int, str] = {}
    if not urls:
        return soups, failures

    batches: list[list[tuple[int, str]]] = [[] for _ in range(min(max(1, workers), len(urls)))]
    for index, url in enumerate(urls):
        batches[index % len(batches)].append((index, url))

    def fetch_batch(batch: list[tuple[int, str]]) -> tuple[dict[int, BeautifulSoup], dict[int, str]]:
        detail_session = session()
        fetched: dict[int, BeautifulSoup] = {}
        errors: dict[int, str] = {}
        try:
            for index, url in batch:
                try:
                    fetched[index] = fetch_soup(detail_session, url, timeout=timeout)
                except Exception as exc:
                    errors[index] = type(exc).__name__
                    logger.debug(
                        "Nowon detail fetch failed url=%s error_type=%s",
                        safe_url_for_log(url),
                        type(exc).__name__,
                    )
        finally:
            closer = getattr(detail_session, "close", None)
            if callable(closer):
                closer()
        return fetched, errors

    with ThreadPoolExecutor(max_workers=len(batches), thread_name_prefix="nowon-detail") as executor:
        for fetched, errors in executor.map(fetch_batch, batches):
            soups.update(fetched)
            failures.update(errors)
    return soups, failures


def nowon_lifelong_declaration(soup: BeautifulSoup) -> Optional[int]:
    scripts = "\n".join(script.get_text(" ", strip=True) for script in soup.find_all("script"))
    match = re.search(r"총\s*([\d,]+)\s*개", scripts)
    return int(match.group(1).replace(",", "")) if match else None


def nowon_lifelong_list_row(
    target: CrawlTarget,
    page_url: str,
    card: Any,
) -> tuple[Optional[dict[str, Any]], str]:
    title_node = card.select_one(".top_tit")
    detail_link = card.find("a", href=lambda href: bool(href and "fnGoDetail" in href))
    status_node = card.select_one(".ask")
    if not title_node or not detail_link or not status_node:
        return None, "missing title, detail link, or published status"
    program_match = re.search(r"fnGoDetail\(\s*(\d+)\s*\)", clean_text(detail_link.get("href")))
    if not program_match:
        return None, "missing official edcPrgmid"
    program_id = program_match.group(1)
    title = re.sub(r"^-?\d+\.\s*", "", clean_text(title_node.get_text(" ", strip=True)))
    if not title:
        return None, f"program {program_id} omitted title"

    list_labels = [clean_text(node.get_text(" ", strip=True)) for node in card.select(".top_box ul > li")]
    target_text = list_labels[0] if list_labels else ""
    area = list_labels[1] if len(list_labels) > 1 else ""
    list_fields: dict[str, str] = {}
    for dl in card.select(".bottom_box dl"):
        dt = dl.find("dt")
        dd = dl.find("dd")
        if not dt or not dd:
            continue
        class_name = clean_text(" ".join(dt.get("class") or []))
        list_fields[class_name] = clean_text(dd.get_text(" ", strip=True))
    branch = list_fields.get("place") or target.branch
    detail_url = f"https://{NOWON_LIFELONG_HOST}/nwll/web/edc/program/{program_id}"
    image_node = card.find("img", src=True)
    status_raw = clean_text(status_node.get_text(" ", strip=True))
    row: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:program:{program_id}",
        "prefer_incoming_provider_course_id": True,
        "title": title,
        "branch": branch,
        "branch_code": nowon_branch_code("NOWON_LLL", branch),
        "branch_url": NOWON_LIFELONG_LIST_URL,
        "preserve_branch": True,
        "raw_url": detail_url,
        "status": nowon_status(status_raw),
        "reservation_available": False,
        "schedule_raw": list_fields.get("time", ""),
        "target": target_text,
        "fee": list_fields.get("price", ""),
        "instructor": list_fields.get("teacher", ""),
        "image_url": urljoin(page_url, image_node.get("src")) if image_node else "",
        "venue_name": branch,
        **nowon_public_course_fields("all_programs_ajax+detail_html"),
        "raw_fields": {
            "parser": NOWON_LIFELONG_PARSER,
            "official_program_id": program_id,
            "status_raw": status_raw,
            "area": area,
            "page_url": page_url,
            "clear_application_url": True,
        },
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}, ""


def nowon_lifelong_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs = pairs_from_tables(soup)
    return {
        clean_text(key).rstrip(":").strip(): clean_text(value)
        for key, value in pairs.items()
        if clean_text(key) and clean_text(value)
    }


def nowon_lifelong_capacity(value: Any) -> tuple[Optional[int], Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    current: Optional[int] = None
    total: Optional[int] = None
    pair_match = re.search(r"\(\s*(\d+)\s*/\s*(\d+)\s*\)", text)
    if pair_match:
        current, total = int(pair_match.group(1)), int(pair_match.group(2))
    total_match = re.search(r"총\s*(\d+)\s*명", text)
    if total_match:
        total = int(total_match.group(1))
    waitlist_match = re.search(r"(\d+)\s*명\s*까지", text)
    waitlist = int(waitlist_match.group(1)) if waitlist_match else None
    return current, total, waitlist


def nowon_safe_application_url(value: Any) -> str:
    # Do not apply html.unescape to a raw JavaScript URL: a valid query such as
    # ``&currentPage=1`` begins with the legacy ``&curren`` entity name and can
    # otherwise be corrupted into a currency-sign character.
    url = clean_text(value).replace("&amp;", "&")
    try:
        parsed = urlparse(url)
    except ValueError:
        return ""
    if parsed.scheme not in {"http", "https"} or not parsed.hostname or parsed.username or parsed.password:
        return ""
    return url


def nowon_enrich_lifelong_detail(row: dict[str, Any], soup: BeautifulSoup) -> tuple[bool, str]:
    pairs = nowon_lifelong_detail_pairs(soup)
    period = nowon_date_range(pairs.get("교육기간"))
    if nowon_period_end(period) is None:
        return False, "missing valid education period"

    branch = re.sub(r"(?:\s+)?이동\s*$", "", clean_text(pairs.get("주관기관"))) or clean_text(row.get("branch"))
    row["branch"] = branch
    row["branch_code"] = nowon_branch_code("NOWON_LLL", branch)
    row["period"] = period
    row["apply_period"] = nowon_date_range(pairs.get("신청기간"))
    row["schedule_raw"] = clean_text(pairs.get("요일/시간")) or row.get("schedule_raw", "")
    row["target"] = clean_text(pairs.get("대상")) or row.get("target", "")
    row["fee"] = clean_text(pairs.get("수강료")) or row.get("fee", "")
    row["category"] = clean_text(pairs.get("강좌분야")) or "교육"
    row["instructor"] = clean_text(pairs.get("강사명")) or row.get("instructor", "")
    row["phone"] = clean_text(pairs.get("문의전화"))
    row["venue_name"] = clean_text(pairs.get("장소")) or branch
    row["application_method_raw"] = clean_text(
        " / ".join(
            dict.fromkeys(
                value
                for value in (clean_text(pairs.get("접수경로")), clean_text(pairs.get("접수방식")))
                if value
            )
        )
    )
    current, total, waitlist = nowon_lifelong_capacity(pairs.get("정원"))
    if total is not None:
        row["capacity"] = str(total)
        row["capacity_total"] = total
    if current is not None:
        row["capacity_current"] = current
    waitlist_from_method = nowon_lifelong_capacity(pairs.get("접수방식"))[2]
    if waitlist is not None or waitlist_from_method is not None:
        row["waitlist_total"] = waitlist if waitlist is not None else waitlist_from_method

    description_parts: list[str] = []
    for selector in ("#tab01", "#tab02", ".tab_con"):
        for node in soup.select(selector):
            value = clean_text(node.get_text(" ", strip=True))
            if value and value not in description_parts:
                description_parts.append(value)
    row["description"] = clean_text(" ".join(description_parts))[:8000]

    scripts = "\n".join(script.get_text("\n") for script in soup.find_all("script"))
    receipt_match = re.search(r'var\s+rsvnRectype\s*=\s*"([^"]*)"', scripts)
    link_match = re.search(r'var\s+linkUrl\s*=\s*"([^"]*)"', scripts)
    program_match = re.search(r"data\.edcPrgmid\s*=\s*(\d+)", scripts)
    set_match = re.search(r"data\.edcRsvnsetSeq\s*=\s*(\d+)", scripts)
    receipt_type = receipt_match.group(1) if receipt_match else ""
    external_url = nowon_safe_application_url(link_match.group(1) if link_match else "")
    has_apply_control = bool(
        soup.find("a", href=lambda href: bool(href and re.search(r"fnDetailApply\s*\(", href)))
    )
    status = clean_text(row.get("status"))
    application_url = ""
    if status in {"OPEN", "WAITING"} and has_apply_control:
        if receipt_type == "5001":
            application_url = external_url
        elif program_match and set_match:
            application_url = (
                f"https://{NOWON_LIFELONG_HOST}/nwll/web/edc/rsvn/termsAgree/"
                f"{program_match.group(1)}/{set_match.group(1)}"
            )
    if application_url:
        row["application_url"] = application_url
        row["reservation_available"] = True
        row["raw_fields"].pop("clear_application_url", None)
    else:
        row.pop("application_url", None)
        row["reservation_available"] = False
        row["raw_fields"]["clear_application_url"] = True
    row["raw_fields"].update(
        {
            "detail_pairs": pairs,
            "detail_url": row.get("raw_url"),
            "reservation_receipt_type": receipt_type,
            "has_application_control": has_apply_control,
            "external_application_url": external_url,
        }
    )
    return True, ""


def collect_nowon_lifelong_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if not is_nowon_lifelong_target(target):
        raise ValueError("Nowon lifelong target must use the owned canonical HTTPS all-program route")
    s = session()
    s.headers.update({"Referer": NOWON_LIFELONG_LIST_URL})
    base_params = {
        "searchTab": "EDCANM",
        "searchOnOff": "ALL",
        "scrollVar": "",
        "searchKeyword": "",
        "areaName": "",
        "areaCd": "0",
        "edcTargetinfo": "",
        "comCtgcd": "",
        "orgLtype": "",
        "orgMtype": "",
        "dayGbn": "",
        "hourbandGbn": "",
        "searchOrderBy": "BY_RECENT_UP",
    }
    listed_rows: list[dict[str, Any]] = []
    seen_programs: set[str] = set()
    errors: list[str] = []
    pages = 0
    raw_row_count = 0
    malformed_rows = 0
    duplicate_rows = 0
    declared_total: Optional[int] = None
    declared_pages = 0

    page = 1
    while page == 1 or page <= declared_pages:
        if pages >= max(1, max_pages):
            errors.append(f"max_pages cap reached before completing {declared_pages or 'declared'} pages")
            break
        page_url = f"{NOWON_LIFELONG_AJAX_URL}?{urlencode(base_params | {'pageIndex': str(page)})}"
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_total = nowon_lifelong_declaration(soup)
        if page_total is None:
            errors.append(f"page {page} omitted official total declaration")
            break
        if declared_total is None:
            declared_total = page_total
            declared_pages = max(1, (declared_total + NOWON_LIFELONG_PAGE_SIZE - 1) // NOWON_LIFELONG_PAGE_SIZE)
        elif page_total != declared_total:
            errors.append(f"total declaration changed from {declared_total} to {page_total} on page {page}")
        cards = soup.select(".search_list > li.li")
        expected_rows = (
            NOWON_LIFELONG_PAGE_SIZE
            if page < declared_pages
            else declared_total - NOWON_LIFELONG_PAGE_SIZE * (declared_pages - 1)
        )
        if len(cards) != expected_rows:
            errors.append(f"page {page} exposed {len(cards)} of {expected_rows} declared rows")
        raw_row_count += len(cards)
        for card in cards:
            row, error = nowon_lifelong_list_row(target, page_url, card)
            if row is None:
                malformed_rows += 1
                if error:
                    errors.append(error)
                continue
            program_id = clean_text(row.get("raw_fields", {}).get("official_program_id"))
            if program_id in seen_programs:
                duplicate_rows += 1
                continue
            seen_programs.add(program_id)
            listed_rows.append(row)
        page += 1

    declared_total = declared_total or 0
    if len(seen_programs) != declared_total:
        errors.append(f"parsed {len(seen_programs)} unique edcPrgmid values of {declared_total} declared rows")
    if malformed_rows:
        errors.append(f"malformed list rows ({malformed_rows})")
    if duplicate_rows:
        errors.append(f"duplicated edcPrgmid values ({duplicate_rows})")

    detail_attempts = min(max(0, detail_limit), len(listed_rows))
    detail_soups, fetch_failures = nowon_fetch_soups_parallel(
        [str(row.get("raw_url")) for row in listed_rows[:detail_attempts]],
        timeout,
    )
    current_rows: list[dict[str, Any]] = []
    detail_pages = 0
    detail_failures: list[str] = []
    expired_count = 0
    for index, row in enumerate(listed_rows[:detail_attempts]):
        identity = clean_text(row.get("provider_course_id"))
        soup = detail_soups.get(index)
        if soup is None:
            detail_failures.append(identity)
            continue
        valid, reason = nowon_enrich_lifelong_detail(row, soup)
        if not valid:
            detail_failures.append(identity)
            if reason:
                errors.append(f"{identity}: {reason}")
            continue
        detail_pages += 1
        end_date = nowon_period_end(row.get("period"))
        if end_date is not None and should_skip_expired_course({"end_date": end_date.date()}):
            expired_count += 1
            continue
        current_rows.append(row)
    if detail_attempts < len(listed_rows):
        errors.append(f"detail enrichment capped at {detail_attempts} of {len(listed_rows)}")
    if fetch_failures or detail_failures:
        errors.append(f"detail fetch or parse failed for {len(set(detail_failures))} programs")

    pagination_complete = pages == declared_pages and len(seen_programs) == declared_total
    details_complete = detail_attempts == len(listed_rows) and not detail_failures and not fetch_failures
    snapshot_complete = pagination_complete and details_complete and not errors
    meta: dict[str, Any] = {
        "pages": pages,
        "declared_pages": declared_pages,
        "raw_row_count": raw_row_count,
        "total_count": declared_total,
        "discovered_links": len(seen_programs),
        "current_count": len(current_rows),
        "expired_count": expired_count,
        "detail_attempts": detail_attempts,
        "detail_pages": detail_pages,
        "detail_failures": detail_failures,
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in current_rows),
        "pagination_detected": declared_pages > 1,
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "no_current_data": snapshot_complete and not current_rows,
        "no_current_reason": "all declared programs have ended" if snapshot_complete and not current_rows else "",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(current_rows), NOWON_LIFELONG_PARSER, meta


def nowon_fmcs_detail_fields(
    soup: BeautifulSoup,
    expected_comcd: str,
    expected_classcd: str,
) -> tuple[Optional[dict[str, Any]], str]:
    container = soup.select_one(".lctre_detail")
    form = soup.select_one("#form_lecture_reg")
    if not container or not form:
        return None, "missing official lecture detail or registration form"
    hidden = {
        clean_text(node.get("name")): clean_text(node.get("value"))
        for node in form.select("input[name]")
    }
    if hidden.get("comcd") != expected_comcd or hidden.get("classcd") != expected_classcd:
        return None, "detail form identity did not match API company/class"
    if hidden.get("type") != "R":
        return None, "detail form omitted program-information type R"

    pairs: dict[str, str] = {}
    for dt in container.select("dt"):
        dd = dt.find_next_sibling("dd")
        key = clean_text(dt.get_text(" ", strip=True)).lstrip("· ").strip()
        value = clean_text(dd.get_text(" ", strip=True) if dd else "")
        if key and value:
            pairs[key] = value
    center_text = clean_text(pairs.get("센터명"))
    branch, _, phone = center_text.partition("/")
    branch = clean_text(branch)
    phone = clean_text(phone)

    fee = ""
    duration = ""
    product_name = ""
    for table in container.select("table"):
        headers = [clean_text(cell.get_text(" ", strip=True)) for cell in table.select("thead th")]
        if "월수강료" not in headers or "수강기간" not in headers:
            continue
        row = table.select_one("tbody tr")
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in row.find_all(["th", "td"]) ] if row else []
        for label, field in (("상품명", "product"), ("월수강료", "fee"), ("수강기간", "duration")):
            if label not in headers:
                continue
            index = headers.index(label)
            value = cells[index] if index < len(cells) else ""
            if field == "product":
                product_name = value
            elif field == "fee":
                fee = value
            else:
                duration = value
        break

    description_parts: list[str] = []
    for heading in container.find_all("strong"):
        if clean_text(heading.get_text(" ", strip=True)) != "강좌 안내":
            continue
        current = heading.parent.find_next_sibling() if heading.parent else None
        while current is not None:
            if getattr(current, "select_one", None) and current.select_one(".tt_txt strong"):
                break
            value = clean_text(current.get_text(" ", strip=True)) if hasattr(current, "get_text") else ""
            if value:
                description_parts.append(value)
            current = current.find_next_sibling() if hasattr(current, "find_next_sibling") else None
        break
    capacity = clean_text(pairs.get("신청인원/정원"))
    if not re.search(r"\d", capacity):
        capacity = ""
    return {
        "title": clean_text(pairs.get("강좌명")),
        "branch": branch,
        "phone": phone,
        "period": duration,
        "schedule_raw": clean_text(pairs.get("시간/요일")),
        "target": clean_text(pairs.get("교육대상")),
        "instructor": clean_text(pairs.get("강사명")),
        "application_method_raw": clean_text(pairs.get("접수방식")),
        "fee": fee,
        "capacity": capacity,
        "venue_name": branch,
        "description": clean_text(" ".join(description_parts))[:8000],
        "raw_detail_pairs": pairs,
        "detail_form": {key: value for key, value in hidden.items() if key != "SecurityToken"},
        "product_name": product_name,
    }, ""


def nowon_fmcs_row(target: CrawlTarget, item: dict[str, Any]) -> Optional[dict[str, Any]]:
    comcd = clean_text(item.get("comcd"))
    class_cd = clean_text(item.get("class_cd"))
    title = clean_text(item.get("class_nm"))
    status_code = clean_text(item.get("status")).upper()
    if not comcd or not class_cd or not title or not status_code:
        return None
    row = fmcs_row_from_api_item(target, NOWON_FMCS_LIST_URL, item, "R")
    row.update(
        {
            "provider_course_id": f"{target.provider}:class:{comcd}:{class_cd}",
            "prefer_incoming_provider_course_id": True,
            "branch": clean_text(item.get("comnm")) or target.branch,
            "branch_code": comcd,
            "branch_url": NOWON_FMCS_LIST_URL,
            "preserve_branch": True,
            "status": NOWON_FMCS_STATUS_MAP.get(status_code, status_code),
            "reservation_available": status_code in {"R", "RW"},
            **nowon_public_course_fields("company_lecture_api+detail_html"),
        }
    )
    row["raw_url"] = (
        f"{NOWON_FMCS_LIST_URL}?"
        f"{urlencode({'action': 'read', 'comcd': comcd, 'classcd': class_cd, 'type': 'R'})}"
    )
    raw_fields = row.setdefault("raw_fields", {})
    raw_fields.update(
        {
            "parser": NOWON_FMCS_PARSER,
            "official_company_code": comcd,
            "official_class_code": class_cd,
            "status_code": status_code,
            "clear_application_url": status_code not in {"R", "RW"},
        }
    )
    if status_code in {"R", "RW"}:
        row["application_url"] = row["raw_url"]
    else:
        row.pop("application_url", None)
    return row


def collect_nowon_fmcs_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if not is_nowon_fmcs_target(target):
        raise ValueError("Nowon FMCS target must use the owned canonical HTTPS lecture route")
    s = session()
    root_url = fmcs_root_url(target.url)
    method = fmcs_http_method(s, root_url, target.url, timeout)
    companies = fmcs_json_rows(
        fmcs_request_json(s, root_url, "rest/common/lecture_company", {}, method, target.url, timeout)
    )
    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    pages = 0
    api_requests = 0
    raw_row_count = 0
    malformed_rows = 0
    duplicate_rows = 0
    declared_total = 0
    errors: list[str] = []
    company_totals: dict[str, int] = {}
    company_names: dict[str, str] = {}
    company_pages: dict[str, int] = {}
    status_counts: Counter[str] = Counter()

    for company in companies:
        comcd = clean_text(company.get("comcd"))
        comnm = clean_text(company.get("comnm"))
        if not comcd or not comnm:
            malformed_rows += 1
            continue
        company_names[comcd] = comnm
        page = 1
        company_total: Optional[int] = None
        expected_pages = 1
        while page <= expected_pages:
            if pages >= max(1, max_pages):
                errors.append(f"max_pages cap reached before completing company {comcd}")
                break
            params = {
                "company_code": comcd,
                "mem_no": "",
                "search_type": "",
                "category_cd": "",
                "category_level": "9",
                "class_nm": "",
                "train_day": "",
                "adult_gubn": "",
                "lecturer_nm": "",
                "page": str(page),
                "page_size": str(NOWON_FMCS_PAGE_SIZE),
            }
            data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, target.url, timeout)
            api_requests += 1
            pages += 1
            items = fmcs_json_rows(data)
            if not items:
                if page == 1:
                    company_total = 0
                    expected_pages = 1
                else:
                    errors.append(f"company {comcd} page {page} was unexpectedly empty")
                break
            page_total = fmcs_int(items[0].get("total_count"), -1)
            if page_total < 0:
                errors.append(f"company {comcd} page {page} omitted total_count")
                break
            if company_total is None:
                company_total = page_total
                expected_pages = max(1, (company_total + NOWON_FMCS_PAGE_SIZE - 1) // NOWON_FMCS_PAGE_SIZE)
            elif page_total != company_total:
                errors.append(f"company {comcd} changed total_count from {company_total} to {page_total}")
            expected_rows = (
                NOWON_FMCS_PAGE_SIZE
                if page < expected_pages
                else company_total - NOWON_FMCS_PAGE_SIZE * (expected_pages - 1)
            )
            if len(items) != expected_rows:
                errors.append(f"company {comcd} page {page} exposed {len(items)} of {expected_rows} rows")
            raw_row_count += len(items)
            for item in items:
                identity = (clean_text(item.get("comcd")), clean_text(item.get("class_cd")))
                row = nowon_fmcs_row(target, item)
                if row is None or identity[0] != comcd:
                    malformed_rows += 1
                    continue
                if identity in seen:
                    duplicate_rows += 1
                    continue
                seen.add(identity)
                rows.append(row)
                status_counts[clean_text(item.get("status")).upper()] += 1
            page += 1
        company_total = company_total or 0
        company_totals[comcd] = company_total
        company_pages[comcd] = expected_pages
        declared_total += company_total
        if pages >= max(1, max_pages) and page <= expected_pages:
            break

    if len(seen) != declared_total:
        errors.append(f"parsed {len(seen)} unique company/class IDs of {declared_total} declared rows")
    if malformed_rows:
        errors.append(f"malformed FMCS rows ({malformed_rows})")
    if duplicate_rows:
        errors.append(f"duplicated FMCS company/class IDs ({duplicate_rows})")

    detail_attempts = min(max(0, detail_limit), len(rows))
    detail_soups, fetch_failures = nowon_fetch_soups_parallel(
        [str(row.get("raw_url")) for row in rows[:detail_attempts]],
        timeout,
    )
    detail_pages = 0
    detail_failures: list[str] = []
    for index, row in enumerate(rows[:detail_attempts]):
        identity = clean_text(row.get("provider_course_id"))
        soup = detail_soups.get(index)
        if soup is None:
            detail_failures.append(identity)
            continue
        raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
        detail, reason = nowon_fmcs_detail_fields(
            soup,
            clean_text(raw_fields.get("official_company_code")),
            clean_text(raw_fields.get("official_class_code")),
        )
        if detail is None or not detail.get("title") or not detail.get("branch"):
            detail_failures.append(identity)
            if reason:
                errors.append(f"{identity}: {reason}")
            continue
        for key, value in detail.items():
            if key in {"raw_detail_pairs", "detail_form"} or value in (None, "", [], {}):
                continue
            row[key] = value
        row["raw_fields"]["detail_pairs"] = detail.get("raw_detail_pairs", {})
        row["raw_fields"]["detail_form"] = detail.get("detail_form", {})
        row["raw_fields"]["detail_url"] = row.get("raw_url")
        row["raw_fields"]["product_name"] = detail.get("product_name", "")
        detail_pages += 1
    details_complete = (
        detail_attempts == len(rows)
        and not detail_failures
        and not fetch_failures
    )
    if detail_attempts < len(rows):
        errors.append(f"detail enrichment capped at {detail_attempts} of {len(rows)}")
    if fetch_failures or detail_failures:
        errors.append(f"detail fetch or parse failed for {len(set(detail_failures))} classes")

    pagination_complete = len(company_totals) == len(companies) and len(seen) == declared_total
    snapshot_complete = pagination_complete and details_complete and not errors
    meta: dict[str, Any] = {
        "pages": pages,
        "api_requests": api_requests,
        "raw_row_count": raw_row_count,
        "total_count": declared_total,
        "company_count": len(companies),
        "company_totals": company_totals,
        "company_names": company_names,
        "company_pages": company_pages,
        "status_counts": dict(status_counts),
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(seen),
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in rows),
        "pagination_detected": pages > len(companies),
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "http_method": method,
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(rows), NOWON_FMCS_PARSER, meta


EUNPYEONG_MUNICIPALITY_CODE = "1138000000"
EUNPYEONG_MUNICIPALITY_NAME = "서울특별시 은평구"

EUNPYEONG_EDU_PROVIDER = "MUNI_EDU_EUNPYEONG_GO_KR_DA5DB65F"
EUNPYEONG_EDU_HOST = "edu.eunpyeong.go.kr"
EUNPYEONG_EDU_MENU_ID = "15022"
EUNPYEONG_EDU_LIST_URL = (
    f"https://{EUNPYEONG_EDU_HOST}/edu/list.nx?M2_IDX={EUNPYEONG_EDU_MENU_ID}"
)
EUNPYEONG_EDU_PARSER = "eunpyeong_learning_all_states_current+detail"

EUNPYEONG_EPLEARNING_PROVIDER = "MUNI_WWW_EPLEARNING_OR_KR_E230FB67"
EUNPYEONG_EPLEARNING_HOST = "www.eplearning.or.kr"
EUNPYEONG_EPLEARNING_MENU_ID = "22423"
EUNPYEONG_EPLEARNING_LIST_URL = (
    f"https://{EUNPYEONG_EPLEARNING_HOST}/edu/list.nx?M2_IDX={EUNPYEONG_EPLEARNING_MENU_ID}"
)
EUNPYEONG_EPLEARNING_PARSER = "eplearning_aggregator_all_states_current+detail"

EUNPYEONG_NX_PAGE_SIZE = 12
EUNPYEONG_EPLEARNING_PAGE_SIZE = 10
EUNPYEONG_NX_STATUS_CODES: tuple[str, ...] = ("E", "B", "C")
EUNPYEONG_NX_STATUS_MAP = {
    "E": "SCHEDULED",
    "B": "OPEN",
    "C": "CLOSED",
}
EUNPYEONG_NX_SOURCES: dict[str, dict[str, str]] = {
    EUNPYEONG_EDU_PROVIDER: {
        "host": EUNPYEONG_EDU_HOST,
        "menu_id": EUNPYEONG_EDU_MENU_ID,
        "list_url": EUNPYEONG_EDU_LIST_URL,
        "parser": EUNPYEONG_EDU_PARSER,
        "collection_type": "all_status_pages+current_detail_html",
    },
    EUNPYEONG_EPLEARNING_PROVIDER: {
        "host": EUNPYEONG_EPLEARNING_HOST,
        "menu_id": EUNPYEONG_EPLEARNING_MENU_ID,
        "list_url": EUNPYEONG_EPLEARNING_LIST_URL,
        "parser": EUNPYEONG_EPLEARNING_PARSER,
        "collection_type": "all_status_pages+current_detail_html",
    },
}

EUNPYEONG_EFMC_PROVIDER = "MUNI_WWW_EFMC_OR_KR_C846830E"
EUNPYEONG_EFMC_HOST = "www.efmc.or.kr"
EUNPYEONG_EFMC_LIST_URL = f"https://{EUNPYEONG_EFMC_HOST}/fmcs/27"
EUNPYEONG_EFMC_PARSER = "eunpyeong_efmc_open_top_categories+detail"
EUNPYEONG_EFMC_PAGE_SIZE = 100
EUNPYEONG_EFMC_EXPECTED_COMPANIES = {
    "EFMC01": "은평종합스포츠타운",
    "EFMC02": "은평청여울수영장",
}


def eunpyeong_public_course_fields(collection_type: str) -> dict[str, Any]:
    return {
        "program_type": "강좌",
        "collection_category": "공공예약",
        "domain_category": "교육·강좌",
        "source_group": "municipal_reservation",
        "operator_type": "지자체/공공기관",
        "collection_type": collection_type,
        "service_group": "공공강좌",
        "service_group_policy": "locked",
        "municipality_code": EUNPYEONG_MUNICIPALITY_CODE,
        "municipality_full_name": EUNPYEONG_MUNICIPALITY_NAME,
    }


def eunpyeong_nx_source(target: CrawlTarget) -> Optional[dict[str, str]]:
    source = EUNPYEONG_NX_SOURCES.get(target.provider)
    if source is None:
        return None
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query, keep_blank_values=True)
    if (
        parsed.scheme != "https"
        or parsed.netloc.lower() != source["host"]
        or parsed.path != "/edu/list.nx"
        or parsed.fragment
        or query != {"M2_IDX": [source["menu_id"]]}
    ):
        return None
    return source


def is_eunpyeong_nx_target(target: CrawlTarget) -> bool:
    return eunpyeong_nx_source(target) is not None


def is_eunpyeong_efmc_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == EUNPYEONG_EFMC_PROVIDER
        and parsed.scheme == "https"
        and parsed.netloc.lower() == EUNPYEONG_EFMC_HOST
        and parsed.path == "/fmcs/27"
        and not parsed.query
        and not parsed.fragment
    )


def eunpyeong_nx_page_url(source: dict[str, str], status_code: str, page: int) -> str:
    return (
        f"https://{source['host']}/edu/list.nx?"
        f"{urlencode({'M2_IDX': source['menu_id'], 'SC_STATUS': status_code, 'page': page})}"
    )


def eunpyeong_nx_page_size(source: dict[str, str]) -> int:
    if source["host"] == EUNPYEONG_EPLEARNING_HOST:
        return EUNPYEONG_EPLEARNING_PAGE_SIZE
    return EUNPYEONG_NX_PAGE_SIZE


def eunpyeong_nx_detail_url(source: dict[str, str], ep_idx: str, em_idx: str) -> str:
    return (
        f"https://{source['host']}/edu/read2.nx?"
        f"{urlencode({'M2_IDX': source['menu_id'], 'EP_IDX': ep_idx, 'EM_IDX': em_idx})}"
    )


def eunpyeong_date_range(value: Any) -> str:
    text = clean_text(value)
    matches = re.findall(
        r"(?<!\d)(20\d{2})[.\-/](\d{1,2})[.\-/](\d{1,2})"
        r"(?:\([^)]*\))?(?:\s+(\d{1,2}:\d{2}))?",
        text,
    )
    values: list[str] = []
    for year, month, day, clock in matches[:2]:
        result = f"{int(year):04d}-{int(month):02d}-{int(day):02d}"
        if clock:
            result = f"{result} {clock}"
        values.append(result)
    if len(values) >= 2:
        return values[0] if values[0] == values[1] else f"{values[0]} ~ {values[1]}"
    return values[0] if values else ""


def eunpyeong_period_end(value: Any) -> Optional[datetime]:
    matches = re.findall(r"\b(20\d{2}-\d{2}-\d{2})\b", clean_text(value))
    if not matches:
        return None
    try:
        return datetime.strptime(matches[-1], "%Y-%m-%d")
    except ValueError:
        return None


def eunpyeong_is_expired(value: Any) -> bool:
    end = eunpyeong_period_end(value)
    return bool(end and should_skip_expired_course({"end_date": end.date()}))


def eunpyeong_branch_name(venue_value: Any, title_value: Any, fallback: str) -> str:
    venue = re.sub(r"^장소\s*:\s*", "", clean_text(venue_value)).strip()
    title = clean_text(title_value)
    combined = f"{title} {venue}"
    if "미래교육센터" in combined:
        return "은평구미래교육센터"
    if "영어도서관" in combined:
        return "은평어린이영어도서관"
    if (
        "은평구평생학습관" in combined
        or "은평평생학습관" in combined
        or "은평구평색학습관" in combined
    ):
        return "은평구평생학습관"
    venue_head = clean_text(venue.split("(", 1)[0])
    resident = re.search(r"([가-힣0-9]+동)\s*주민센터", venue_head)
    if resident:
        return f"{resident.group(1)} 주민센터"
    venue_head = re.split(
        r"\s+(?:지하\s*)?\d+층|\s+(?:온빛\s*)?강의실|\s+채움실\d*|\s+나눔실\d*|\s+공감홀",
        venue_head,
        maxsplit=1,
    )[0]
    if (
        venue_head
        and venue_head not in {"온라인", "온라인으로 진행", "온라인 진행"}
        and len(venue_head) <= 60
        and re.search(r"(?:문화센터|도서관|복지관|학습관|센터|학교|공방|캠퍼스|홀)$", venue_head)
    ):
        return venue_head
    return clean_text(fallback) or "은평구평생학습관"


def eunpyeong_branch_code(prefix: str, branch: Any) -> str:
    name = clean_text(branch)
    digest = hashlib.sha1(name.encode("utf-8")).hexdigest()[:12].upper()
    return f"{prefix}_{digest}"


def eunpyeong_fetch_soups_parallel(
    urls: list[str],
    timeout: int,
    *,
    workers: int = 4,
) -> tuple[dict[int, BeautifulSoup], dict[int, str]]:
    soups: dict[int, BeautifulSoup] = {}
    failures: dict[int, str] = {}
    if not urls:
        return soups, failures
    batches: list[list[tuple[int, str]]] = [[] for _ in range(min(max(1, workers), len(urls)))]
    for index, url in enumerate(urls):
        batches[index % len(batches)].append((index, url))

    def fetch_batch(batch: list[tuple[int, str]]) -> tuple[dict[int, BeautifulSoup], dict[int, str]]:
        detail_session = session()
        fetched: dict[int, BeautifulSoup] = {}
        errors: dict[int, str] = {}
        try:
            for index, url in batch:
                try:
                    fetched[index] = fetch_soup(detail_session, url, timeout=timeout)
                except Exception as exc:
                    errors[index] = type(exc).__name__
                    logger.debug(
                        "Eunpyeong detail fetch failed url=%s error_type=%s",
                        safe_url_for_log(url),
                        type(exc).__name__,
                    )
        finally:
            closer = getattr(detail_session, "close", None)
            if callable(closer):
                closer()
        return fetched, errors

    with ThreadPoolExecutor(max_workers=len(batches), thread_name_prefix="eunpyeong-detail") as executor:
        for fetched, errors in executor.map(fetch_batch, batches):
            soups.update(fetched)
            failures.update(errors)
    return soups, failures


def eunpyeong_nx_card_row(
    target: CrawlTarget,
    source: dict[str, str],
    page_url: str,
    status_code: str,
    card: Any,
) -> tuple[Optional[dict[str, Any]], str]:
    link = card.find("a", href=lambda href: bool(href and "read2.nx" in href))
    if link is None:
        return None, "missing official detail link"
    query = parse_qs(urlparse(urljoin(page_url, clean_text(link.get("href")))).query)
    ep_idx = clean_text((query.get("EP_IDX") or [""])[0])
    em_idx = clean_text((query.get("EM_IDX") or [""])[0])
    if not ep_idx.isdigit() or not em_idx.isdigit():
        return None, "missing numeric EP_IDX or EM_IDX"
    title_node = card.select_one(".title")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    if not title:
        return None, f"program {ep_idx}/{em_idx} omitted title"
    period_node = card.select_one(".schedule")
    place_node = card.select_one(".place")
    description_node = card.select_one(".ct")
    status_node = card.select_one(".btn")
    image_node = card.find("img", src=True)
    period = eunpyeong_date_range(period_node.get_text(" ", strip=True) if period_node else "")
    venue = re.sub(
        r"^장소\s*:\s*",
        "",
        clean_text(place_node.get_text(" ", strip=True) if place_node else ""),
    )
    branch = eunpyeong_branch_name(venue, title, target.branch)
    detail_url = eunpyeong_nx_detail_url(source, ep_idx, em_idx)
    row: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:program:{ep_idx}:{em_idx}",
        "prefer_incoming_provider_course_id": True,
        "title": title,
        "branch": branch,
        "branch_code": eunpyeong_branch_code("EUNPYEONG_NX", branch),
        "branch_url": source["list_url"],
        "preserve_branch": True,
        "raw_url": detail_url,
        "status": EUNPYEONG_NX_STATUS_MAP[status_code],
        "reservation_available": False,
        "period": period,
        "venue_name": venue,
        "description": clean_text(
            description_node.get_text(" ", strip=True) if description_node else ""
        )[:4000],
        "image_url": urljoin(page_url, clean_text(image_node.get("src"))) if image_node else "",
        **eunpyeong_public_course_fields(source["collection_type"]),
        "raw_fields": {
            "parser": source["parser"],
            "official_ep_idx": ep_idx,
            "official_em_idx": em_idx,
            "status_code": status_code,
            "status_label": clean_text(status_node.get_text(" ", strip=True) if status_node else ""),
            "list_page_url": page_url,
            "clear_application_url": True,
        },
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}, ""


def eunpyeong_nx_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in soup.select("ul.nx-detail > li"):
        heading = item.select_one("h6.nx-detail-tit")
        if heading is None:
            continue
        key = clean_text(heading.get_text(" ", strip=True)).rstrip(":：").strip()
        text = clean_text(item.get_text(" ", strip=True))
        value = clean_text(text[len(key) :]) if text.startswith(key) else text
        if key and value:
            pairs[key] = value
    return pairs


def eunpyeong_enrich_nx_detail(row: dict[str, Any], soup: BeautifulSoup) -> tuple[bool, str]:
    title_node = soup.select_one("h4.nx-edu-tit1")
    title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    pairs = eunpyeong_nx_detail_pairs(soup)
    raw_period = clean_text(pairs.get("학습기간"))
    period = eunpyeong_date_range(raw_period)
    venue = clean_text(pairs.get("학습장소"))
    raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
    if not title or not venue:
        return False, "detail omitted title, valid learning period, or learning venue"
    if eunpyeong_period_end(period) is None:
        if re.fullmatch(r"상시(?:\s*운영)?", raw_period):
            raw_fields.update(
                {
                    "detail_pairs": pairs,
                    "detail_url": row.get("raw_url"),
                    "excluded_reason": "undated_continuous_program",
                }
            )
            row["raw_fields"] = raw_fields
            return False, "undated_continuous_program"
        return False, "detail omitted title, valid learning period, or learning venue"
    em_idx = clean_text(raw_fields.get("official_em_idx"))
    branch = eunpyeong_branch_name(venue, title, clean_text(row.get("branch")))
    row.update(
        {
            "title": title,
            "branch": branch,
            "branch_code": eunpyeong_branch_code("EUNPYEONG_NX", branch),
            "period": period,
            "apply_period": eunpyeong_date_range(pairs.get("모집기간")),
            "venue_name": venue,
            "region": clean_text(pairs.get("지역")),
            "target": clean_text(pairs.get("대상")),
            "category": clean_text(pairs.get("분야별")) or "교육",
        }
    )
    has_application_control = False
    for link in soup.select("a[href]"):
        match = re.fullmatch(
            r"javascript:onclLogin\(\s*\d+\s*,\s*(\d+)\s*\);?",
            clean_text(link.get("href")),
            flags=re.IGNORECASE,
        )
        if match and match.group(1) == em_idx:
            has_application_control = True
            break
    status_code = clean_text(raw_fields.get("status_code"))
    if status_code == "B" and has_application_control:
        row["application_url"] = clean_text(row.get("raw_url"))
        row["reservation_available"] = True
        raw_fields.pop("clear_application_url", None)
    else:
        row.pop("application_url", None)
        row["reservation_available"] = False
        raw_fields["clear_application_url"] = True
    raw_fields.update(
        {
            "detail_pairs": pairs,
            "detail_url": row.get("raw_url"),
            "has_application_control": has_application_control,
        }
    )
    row["raw_fields"] = raw_fields
    return True, ""


def collect_eunpyeong_nx_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    source = eunpyeong_nx_source(target)
    if source is None:
        raise ValueError("Eunpyeong NX target must use its owned canonical HTTPS all-course route")
    page_size = eunpyeong_nx_page_size(source)
    s = session()
    s.headers.update({"Referer": source["list_url"]})
    listed_rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    status_totals: dict[str, int] = {}
    status_pages: dict[str, int] = {}
    terminal_repeat_pages: dict[str, int] = {}
    status_counts: Counter[str] = Counter()
    errors: list[str] = []
    list_requests = 0
    raw_row_count = 0
    malformed_rows = 0
    duplicate_rows = 0
    completed_statuses: set[str] = set()

    for status_code in EUNPYEONG_NX_STATUS_CODES:
        previous_signature: Optional[tuple[tuple[str, str], ...]] = None
        previous_count = 0
        unique_page_count = 0
        status_seen: set[tuple[str, str]] = set()
        for page in range(1, max(1, max_pages) + 1):
            if list_requests >= max(1, max_pages):
                errors.append(f"max_pages cap reached before status {status_code} repeated its terminal page")
                break
            page_url = eunpyeong_nx_page_url(source, status_code, page)
            soup = fetch_soup(s, page_url, timeout=timeout)
            list_requests += 1
            menu_input = soup.select_one("input[name='M2_IDX']")
            status_input = soup.select_one("input[name='SC_STATUS']")
            container = soup.select_one("#edu_lst")
            if (
                container is None
                or clean_text(menu_input.get("value") if menu_input else "") != source["menu_id"]
                or clean_text(status_input.get("value") if status_input else "") != status_code
            ):
                errors.append(f"status {status_code} page {page} omitted its official route declaration")
                break
            cards = [
                card
                for card in container.select(":scope > li")
                if card.find("a", href=lambda href: bool(href and "read2.nx" in href))
            ]
            no_data = container.select_one("li.nodata")
            if not cards:
                if page == 1 and no_data is not None and "등록된 정보가 없습니다" in clean_text(no_data.get_text(" ", strip=True)):
                    status_totals[status_code] = 0
                    status_pages[status_code] = 0
                    completed_statuses.add(status_code)
                else:
                    errors.append(f"status {status_code} page {page} exposed no course cards or official no-data marker")
                break
            parsed_page: list[tuple[tuple[str, str], dict[str, Any]]] = []
            page_errors: list[str] = []
            for card in cards:
                row, error = eunpyeong_nx_card_row(target, source, page_url, status_code, card)
                if row is None:
                    malformed_rows += 1
                    if error:
                        page_errors.append(error)
                    continue
                raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
                identity = (
                    clean_text(raw_fields.get("official_ep_idx")),
                    clean_text(raw_fields.get("official_em_idx")),
                )
                parsed_page.append((identity, row))
            signature = tuple(identity for identity, _row in parsed_page)
            if page_errors or len(signature) != len(cards) or not signature:
                errors.extend(page_errors or [f"status {status_code} page {page} contained malformed cards"])
                break
            if len(set(signature)) != len(signature):
                errors.append(f"status {status_code} page {page} repeated an EP_IDX/EM_IDX identity")
                break
            if signature == previous_signature:
                terminal_repeat_pages[status_code] = page
                status_totals[status_code] = len(status_seen)
                status_pages[status_code] = unique_page_count
                completed_statuses.add(status_code)
                break
            if previous_signature is not None and previous_count != page_size:
                errors.append(
                    f"status {status_code} page {page - 1} exposed {previous_count} rows before a later page"
                )
                break
            if len(signature) > page_size:
                errors.append(
                    f"status {status_code} page {page} exceeded the {page_size}-row official page size"
                )
                break
            for identity, row in parsed_page:
                if identity in status_seen or identity in seen:
                    duplicate_rows += 1
                    continue
                status_seen.add(identity)
                seen.add(identity)
                listed_rows.append(row)
                status_counts[status_code] += 1
            raw_row_count += len(parsed_page)
            unique_page_count += 1
            previous_signature = signature
            previous_count = len(signature)
        else:
            errors.append(
                f"max_pages cap reached before status {status_code} repeated its terminal page"
            )
        if status_code not in completed_statuses:
            break

    if malformed_rows:
        errors.append(f"malformed NX list rows ({malformed_rows})")
    if duplicate_rows:
        errors.append(f"duplicated cross-page/status EP_IDX/EM_IDX values ({duplicate_rows})")
    declared_total = sum(status_totals.values())
    if len(completed_statuses) == len(EUNPYEONG_NX_STATUS_CODES) and len(seen) != declared_total:
        errors.append(f"parsed {len(seen)} unique program identities of {declared_total} completed status rows")

    current_candidates: list[dict[str, Any]] = []
    expired_count = 0
    for row in listed_rows:
        if eunpyeong_period_end(row.get("period")) is None or not eunpyeong_is_expired(row.get("period")):
            current_candidates.append(row)
        else:
            expired_count += 1
    detail_attempts = min(max(0, detail_limit), len(current_candidates))
    detail_soups, fetch_failures = eunpyeong_fetch_soups_parallel(
        [clean_text(row.get("raw_url")) for row in current_candidates[:detail_attempts]],
        timeout,
    )
    current_rows: list[dict[str, Any]] = []
    detail_pages = 0
    detail_failures: list[str] = []
    expired_after_detail = 0
    undated_continuous_count = 0
    for index, row in enumerate(current_candidates[:detail_attempts]):
        identity = clean_text(row.get("provider_course_id"))
        soup = detail_soups.get(index)
        if soup is None:
            detail_failures.append(identity)
            continue
        valid, reason = eunpyeong_enrich_nx_detail(row, soup)
        if not valid:
            if reason == "undated_continuous_program":
                detail_pages += 1
                undated_continuous_count += 1
                continue
            detail_failures.append(identity)
            if reason:
                errors.append(f"{identity}: {reason}")
            continue
        detail_pages += 1
        if eunpyeong_is_expired(row.get("period")):
            expired_after_detail += 1
            continue
        current_rows.append(row)
    expired_count += expired_after_detail
    details_complete = (
        detail_attempts == len(current_candidates)
        and not detail_failures
        and not fetch_failures
    )
    if detail_attempts < len(current_candidates):
        errors.append(f"detail enrichment capped at {detail_attempts} of {len(current_candidates)} current candidates")
    if detail_failures or fetch_failures:
        errors.append(f"detail fetch or parse failed for {len(set(detail_failures) | set(fetch_failures))} programs")

    pagination_complete = len(completed_statuses) == len(EUNPYEONG_NX_STATUS_CODES)
    snapshot_complete = pagination_complete and details_complete and not errors
    meta: dict[str, Any] = {
        "pages": list_requests,
        "list_requests": list_requests,
        "raw_row_count": raw_row_count,
        "total_count": declared_total,
        "status_totals": status_totals,
        "status_pages": status_pages,
        "status_counts": dict(status_counts),
        "terminal_repeat_pages": terminal_repeat_pages,
        "current_count": len(current_rows),
        "expired_count": expired_count,
        "undated_continuous_count": undated_continuous_count,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(seen),
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in current_rows),
        "pagination_detected": any(count > 1 for count in status_pages.values()),
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": not snapshot_complete,
        "recursion_depth": 0,
        "no_current_data": snapshot_complete and not current_rows,
        "no_current_reason": (
            "no dated current/future programs remain after official E/B/C detail validation"
            if snapshot_complete and not current_rows
            else ""
        ),
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(current_rows), source["parser"], meta


def eunpyeong_efmc_row(
    target: CrawlTarget,
    item: dict[str, Any],
    category: dict[str, Any],
) -> Optional[dict[str, Any]]:
    comcd = clean_text(item.get("comcd"))
    class_cd = clean_text(item.get("class_cd"))
    title = clean_text(item.get("class_nm"))
    status_code = clean_text(item.get("status")).upper()
    if not comcd or not class_cd or not title or status_code not in {"R", "RW"}:
        return None
    row = fmcs_row_from_api_item(
        target,
        EUNPYEONG_EFMC_LIST_URL,
        item,
        "R",
        fmcs_category_context(category),
    )
    branch = clean_text(item.get("comnm")) or EUNPYEONG_EFMC_EXPECTED_COMPANIES.get(comcd) or target.branch
    raw_url = (
        f"{EUNPYEONG_EFMC_LIST_URL}?"
        f"{urlencode({'action': 'read', 'comcd': comcd, 'classcd': class_cd, 'type': 'R'})}"
    )
    row.update(
        {
            "provider_course_id": f"{target.provider}:class:{comcd}:{class_cd}",
            "prefer_incoming_provider_course_id": True,
            "branch": branch,
            "branch_code": comcd,
            "branch_url": EUNPYEONG_EFMC_LIST_URL,
            "preserve_branch": True,
            "raw_url": raw_url,
            "application_url": raw_url,
            "status": "WAITING" if status_code == "RW" else "OPEN",
            "reservation_available": True,
            "venue_name": branch,
            **eunpyeong_public_course_fields("open_top_category_api+detail_html"),
            "raw_fields": {
                "parser": EUNPYEONG_EFMC_PARSER,
                "official_company_code": comcd,
                "official_class_code": class_cd,
                "official_category_code": clean_text(category.get("category_code")),
                "official_category_name": clean_text(category.get("category_name")),
                "status_code": status_code,
                "search_type": "R",
            },
        }
    )
    return row


def collect_eunpyeong_efmc_open_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    if not is_eunpyeong_efmc_target(target):
        raise ValueError("Eunpyeong EFMC target must use the owned canonical HTTPS lecture route")
    s = session()
    root_url = fmcs_root_url(target.url)
    method = fmcs_http_method(s, root_url, target.url, timeout)
    companies = fmcs_json_rows(
        fmcs_request_json(s, root_url, "rest/common/company", {"type": "L"}, method, target.url, timeout)
    )
    api_requests = 1
    company_names: dict[str, str] = {}
    malformed_companies = 0
    for company in companies:
        code = clean_text(company.get("comcd"))
        name = clean_text(company.get("comnm"))
        if not code or not name:
            malformed_companies += 1
            continue
        company_names[code] = name

    errors: list[str] = []
    missing_companies = sorted(set(EUNPYEONG_EFMC_EXPECTED_COMPANIES) - set(company_names))
    if missing_companies:
        errors.append(f"company API omitted expected branches: {', '.join(missing_companies)}")
    if malformed_companies:
        errors.append(f"malformed EFMC company rows ({malformed_companies})")

    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    category_totals: dict[str, int] = {}
    category_pages: dict[str, int] = {}
    category_names: dict[str, str] = {}
    category_count = 0
    list_requests = 0
    raw_row_count = 0
    malformed_categories = 0
    malformed_rows = 0
    duplicate_rows = 0
    source_cap_reached = False

    for comcd, comnm in company_names.items():
        categories = fmcs_json_rows(
            fmcs_request_json(
                s,
                root_url,
                "rest/common/category",
                {"company_code": comcd},
                method,
                target.url,
                timeout,
            )
        )
        api_requests += 1
        top_categories: list[dict[str, Any]] = []
        for category in categories:
            code = clean_text(category.get("category_code"))
            level = clean_text(category.get("category_level"))
            name = clean_text(category.get("category_name"))
            if not code or not name:
                malformed_categories += 1
                continue
            if level and level != "1":
                continue
            top_categories.append(category)
        if not top_categories:
            errors.append(f"company {comcd} exposed no official top-level categories")
            continue
        category_count += len(top_categories)

        for category in top_categories:
            category_code = clean_text(category.get("category_code"))
            category_key = f"{comcd}:{category_code}"
            category_names[category_key] = clean_text(category.get("category_name"))
            page = 1
            expected_pages = 1
            category_total: Optional[int] = None
            while page <= expected_pages:
                if list_requests >= max(1, max_pages):
                    errors.append(f"max_pages cap reached before category {category_key} completed")
                    source_cap_reached = True
                    break
                params = {
                    "company_code": comcd,
                    "mem_no": "",
                    "search_type": "R",
                    "category_cd": category_code,
                    "category_level": "1",
                    "class_nm": "",
                    "train_day": "",
                    "adult_gubn": "",
                    "lecturer_nm": "",
                    "page": str(page),
                    "page_size": str(EUNPYEONG_EFMC_PAGE_SIZE),
                }
                data = fmcs_request_json(
                    s,
                    root_url,
                    "rest/lecture/list",
                    params,
                    method,
                    target.url,
                    timeout,
                )
                api_requests += 1
                list_requests += 1
                items = fmcs_json_rows(data)
                if not items:
                    if page == 1:
                        category_total = 0
                        expected_pages = 0
                    else:
                        errors.append(f"category {category_key} page {page} was unexpectedly empty")
                    break
                page_total = fmcs_int(items[0].get("total_count"), -1)
                if page_total < 0:
                    errors.append(f"category {category_key} page {page} omitted total_count")
                    break
                if category_total is None:
                    category_total = page_total
                    expected_pages = max(
                        1,
                        (category_total + EUNPYEONG_EFMC_PAGE_SIZE - 1) // EUNPYEONG_EFMC_PAGE_SIZE,
                    )
                elif page_total != category_total:
                    errors.append(
                        f"category {category_key} changed total_count from {category_total} to {page_total}"
                    )
                expected_rows = (
                    EUNPYEONG_EFMC_PAGE_SIZE
                    if page < expected_pages
                    else category_total - EUNPYEONG_EFMC_PAGE_SIZE * (expected_pages - 1)
                )
                if len(items) != expected_rows:
                    errors.append(f"category {category_key} page {page} exposed {len(items)} of {expected_rows} rows")
                raw_row_count += len(items)
                for item in items:
                    identity = (clean_text(item.get("comcd")), clean_text(item.get("class_cd")))
                    row = eunpyeong_efmc_row(target, item, category)
                    if row is None or identity[0] != comcd:
                        malformed_rows += 1
                        continue
                    if identity in seen:
                        duplicate_rows += 1
                        continue
                    seen.add(identity)
                    rows.append(row)
                page += 1
            category_totals[category_key] = category_total or 0
            category_pages[category_key] = expected_pages
            if source_cap_reached:
                break
        if source_cap_reached:
            break

    if malformed_categories:
        errors.append(f"malformed EFMC top-level categories ({malformed_categories})")
    if malformed_rows:
        errors.append(f"malformed or non-open EFMC lecture rows ({malformed_rows})")
    if duplicate_rows:
        errors.append(f"duplicated EFMC company/class IDs across top-level categories ({duplicate_rows})")
    declared_total = sum(category_totals.values())
    if not source_cap_reached and len(seen) != declared_total:
        errors.append(f"parsed {len(seen)} unique company/class IDs of {declared_total} declared open rows")

    detail_attempts = min(max(0, detail_limit), len(rows))
    detail_soups, fetch_failures = eunpyeong_fetch_soups_parallel(
        [clean_text(row.get("raw_url")) for row in rows[:detail_attempts]],
        timeout,
    )
    detail_pages = 0
    detail_failures: list[str] = []
    for index, row in enumerate(rows[:detail_attempts]):
        identity = clean_text(row.get("provider_course_id"))
        soup = detail_soups.get(index)
        if soup is None:
            detail_failures.append(identity)
            continue
        raw_fields = row.get("raw_fields") if isinstance(row.get("raw_fields"), dict) else {}
        detail, reason = nowon_fmcs_detail_fields(
            soup,
            clean_text(raw_fields.get("official_company_code")),
            clean_text(raw_fields.get("official_class_code")),
        )
        if detail is None or not detail.get("title") or not detail.get("branch"):
            detail_failures.append(identity)
            if reason:
                errors.append(f"{identity}: {reason}")
            continue
        for key, value in detail.items():
            if key in {"raw_detail_pairs", "detail_form"} or value in (None, "", [], {}):
                continue
            row[key] = value
        row["branch_code"] = clean_text(raw_fields.get("official_company_code"))
        row["venue_name"] = clean_text(row.get("branch"))
        row["raw_fields"]["detail_pairs"] = detail.get("raw_detail_pairs", {})
        row["raw_fields"]["detail_form"] = detail.get("detail_form", {})
        row["raw_fields"]["detail_url"] = row.get("raw_url")
        row["raw_fields"]["product_name"] = detail.get("product_name", "")
        detail_pages += 1
    details_complete = detail_attempts == len(rows) and not detail_failures and not fetch_failures
    if detail_attempts < len(rows):
        errors.append(f"detail enrichment capped at {detail_attempts} of {len(rows)} open classes")
    if detail_failures or fetch_failures:
        errors.append(f"detail fetch or parse failed for {len(set(detail_failures) | set(fetch_failures))} classes")

    completed_categories = len(category_totals) == category_count
    pagination_complete = (
        not source_cap_reached
        and completed_categories
        and len(seen) == declared_total
        and set(EUNPYEONG_EFMC_EXPECTED_COMPANIES).issubset(company_names)
    )
    snapshot_complete = pagination_complete and details_complete and not errors
    meta: dict[str, Any] = {
        "pages": list_requests,
        "api_requests": api_requests,
        "raw_row_count": raw_row_count,
        "total_count": declared_total,
        "company_count": len(company_names),
        "company_names": company_names,
        "category_count": category_count,
        "category_names": category_names,
        "category_totals": category_totals,
        "category_pages": category_pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(seen),
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in rows),
        "pagination_detected": any(count > 1 for count in category_pages.values()),
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached or not snapshot_complete,
        "recursion_depth": 0,
        "http_method": method,
        "no_current_data": snapshot_complete and not rows,
        "no_current_reason": "official EFMC search_type=R top-category fanout returned 0 rows"
        if snapshot_complete and not rows
        else "",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(rows), EUNPYEONG_EFMC_PARSER, meta


