JUNGNANG_MUNICIPALITY_NAME = "서울특별시 중랑구"
JUNGNANG_STUDY_PROVIDER = "MUNI_WWW_JUNGNANG_GO_KR_2B41C2EF"
JUNGNANG_STUDY_HOST = "www.jungnang.go.kr"
JUNGNANG_STUDY_LIST_PATH = "/study/app/studyLecture/list.do"
JUNGNANG_STUDY_DETAIL_PATH = "/study/app/studyLecture/select.do"
JUNGNANG_STUDY_LIST_URL = (
    "https://www.jungnang.go.kr/study/app/studyLecture/list.do?"
    "programId=studyLecture&division=studyLecture&menuNo=1200040"
)
JUNGNANG_STUDY_PARSER = "jungnang_study_current_full_snapshot+detail"
JUNGNANG_STUDY_PAGE_SIZE = 100
# The site honors pageUnit=100 for rows but its display ordinal still advances by the UI default of 10.
JUNGNANG_STUDY_ORDINAL_PAGE_STEP = 10
JUNGNANG_STUDY_STATUS_MAP = {
    "접수중": "OPEN",
    "접수예정": "SCHEDULED",
    "접수마감": "CLOSED",
    "마감": "CLOSED",
}

JUNGNANG_BANG_PROVIDER = "MUNI_EDUCENTER_JUNGNANG_GO_KR_BDA8816B"
JUNGNANG_BANG_HOST = "educenter.jungnang.go.kr"
JUNGNANG_BANG_LIST_PATH = "/pf/listG.php"
JUNGNANG_BANG_DETAIL_PATH = "/pf/content.php"
JUNGNANG_BANG_LIST_URL = "https://educenter.jungnang.go.kr/pf/listG.php"
JUNGNANG_BANG_PARSER = "jungnang_bang_current_full_snapshot+detail"
JUNGNANG_BANG_PAGE_SIZE = 10
JUNGNANG_BANG_BRANCH = "중랑구 방정환교육지원센터"


def jungnang_public_course_fields() -> dict[str, Any]:
    return {
        "program_type": "강좌",
        "collection_category": "공공예약",
        "domain_category": "교육·강좌",
        "source_group": "municipal_reservation",
        "operator_type": "지자체/공공기관",
        "service_group": "공공강좌",
        "service_group_policy": "locked",
        "municipality_code": JUNGNANG_MUNICIPALITY_CODE,
        "municipality_full_name": JUNGNANG_MUNICIPALITY_NAME,
    }


def jungnang_date_end(value: Any) -> Optional[datetime]:
    dates = re.findall(r"\b\d{4}-\d{2}-\d{2}\b", clean_text(value))
    if not dates:
        return None
    try:
        return datetime.strptime(dates[-1], "%Y-%m-%d")
    except ValueError:
        return None


def jungnang_capacity_pair(value: Any) -> tuple[Optional[int], Optional[int]]:
    match = re.search(r"모집\s*:?\s*([\d,]+)\s*명?\s*/\s*(?:신청|접수)\s*:?\s*([\d,]+)", clean_text(value))
    if not match:
        match = re.search(r"([\d,]+)\s*/\s*([\d,]+)", clean_text(value))
    if not match:
        return None, None
    return int(match.group(2).replace(",", "")), int(match.group(1).replace(",", ""))


def is_jungnang_study_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query, keep_blank_values=True)
    return (
        target.provider == JUNGNANG_STUDY_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == JUNGNANG_STUDY_HOST
        and parsed.path == JUNGNANG_STUDY_LIST_PATH
        and query.get("programId") == ["studyLecture"]
        and query.get("division") == ["studyLecture"]
        and query.get("menuNo") == ["1200040"]
        and not query.get("gubun")
    )


def jungnang_study_list_url(page_index: int) -> str:
    query = urlencode(
        {
            "programId": "studyLecture",
            "division": "studyLecture",
            "menuNo": "1200040",
            "pageIndex": str(max(1, page_index)),
            "pageUnit": str(JUNGNANG_STUDY_PAGE_SIZE),
        }
    )
    return f"https://{JUNGNANG_STUDY_HOST}{JUNGNANG_STUDY_LIST_PATH}?{query}"


def jungnang_study_detail_url(lecture_id: str) -> str:
    query = urlencode(
        {
            "id": clean_text(lecture_id),
            "division": "studyLecture",
            "programId": "studyLecture",
            "menuNo": "1200040",
        }
    )
    return f"https://{JUNGNANG_STUDY_HOST}{JUNGNANG_STUDY_DETAIL_PATH}?{query}"


def jungnang_study_list_rows(
    target: CrawlTarget,
    soup: BeautifulSoup,
    page_index: int,
) -> tuple[list[dict[str, Any]], int]:
    rows: list[dict[str, Any]] = []
    invalid_rows = 0
    for tr in soup.select("table tbody tr"):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"], recursive=False)]
        link = tr.find("a", href=lambda value: bool(value and "studyLecture/select.do" in value and "id=" in value))
        if not cells and link is None:
            continue
        if len(cells) != 6 or link is None or not cells[0].isdigit():
            invalid_rows += 1
            continue
        linked_url = normalize_link(JUNGNANG_STUDY_LIST_URL, link.get("href"))
        parsed = urlparse(linked_url)
        lecture_id = clean_text((parse_qs(parsed.query).get("id") or [""])[0])
        title = clean_text(link.get_text(" ", strip=True))
        status_raw = next((value for value in JUNGNANG_STUDY_STATUS_MAP if cells[2].startswith(value)), "")
        dates = re.findall(r"\b\d{4}-\d{2}-\d{2}\b", cells[3])
        capacity_current, capacity_total = jungnang_capacity_pair(cells[5])
        if (
            parsed.scheme.lower() != "https"
            or parsed.netloc.lower() != JUNGNANG_STUDY_HOST
            or parsed.path != JUNGNANG_STUDY_DETAIL_PATH
            or not lecture_id.isdigit()
            or not title
            or not status_raw
            or len(dates) != 4
            or capacity_current is None
            or capacity_total is None
        ):
            invalid_rows += 1
            continue
        source_group = clean_text(cells[1])
        branch = "중랑구 평생학습관" if source_group == "평생학습관" else source_group
        detail_url = jungnang_study_detail_url(lecture_id)
        row: dict[str, Any] = {
            "provider": target.provider,
            "provider_course_id": f"{target.provider}:lecture:{lecture_id}",
            "prefer_incoming_provider_course_id": True,
            "title": title,
            "branch": branch,
            "branch_code": stable_provider("JUNGNANG_STUDY_BRANCH", branch),
            "branch_url": JUNGNANG_STUDY_LIST_URL,
            "preserve_branch": True,
            "category": source_group or "평생학습",
            "raw_url": detail_url,
            "status": JUNGNANG_STUDY_STATUS_MAP[status_raw],
            "reservation_available": False,
            "period": f"{dates[2]} ~ {dates[3]}",
            "apply_period": f"{dates[0]} ~ {dates[1]}",
            "fee": cells[4],
            "capacity": cells[5],
            "capacity_current": capacity_current,
            "capacity_total": capacity_total,
            "collection_type": "full_pagination+current_detail_html",
            "description": title,
            "raw_fields": {
                "parser": JUNGNANG_STUDY_PARSER,
                "lecture_id": lecture_id,
                "list_ordinal": int(cells[0]),
                "page_index": page_index,
                "source_group": source_group,
                "status_raw": status_raw,
                "list_cells": cells,
                "clear_application_url": True,
            },
            **jungnang_public_course_fields(),
        }
        rows.append(row)
    return rows, invalid_rows


def jungnang_study_application_url(soup: BeautifulSoup, detail_url: str) -> str:
    has_apply_control = any(
        "신청하기" in clean_text(link.get_text(" ", strip=True))
        and "lfn_verification" in clean_text(link.get("href"))
        for link in soup.select("a[href]")
    )
    if not has_apply_control:
        return ""
    inline = "\n".join(script.get_text("\n") for script in soup.select("script:not([src])"))
    match = re.search(
        r"location\.href\s*=\s*['\"]([^'\"]*/portal/member/vnameLoginTo\.do\?[^'\"]+)['\"]",
        inline,
    )
    return normalize_link(detail_url, match.group(1)) if match else ""


def jungnang_enrich_study_detail(row: dict[str, Any], soup: BeautifulSoup) -> str:
    pairs = pairs_from_tables(soup)
    required = ("강사명", "교육대상", "교육장소", "교육장소 상세", "교육시간", "구분", "모집/대기/신청", "기간")
    missing = [label for label in required if not clean_text(pairs.get(label))]
    if missing:
        return f"missing detail labels: {','.join(missing)}"
    period_text = clean_text(pairs.get("기간"))
    period_match = re.search(r"신청\s*(.+?)\s*교육\s*(.+)$", period_text)
    if not period_match:
        return "invalid application/education period detail"
    apply_period = bucheon_reservation_datetime_range(period_match.group(1))
    education_period = bucheon_reservation_datetime_range(period_match.group(2))
    if not apply_period or not education_period:
        return "invalid normalized application/education period detail"
    capacity_match = re.fullmatch(
        r"\s*([\d,]+)\s*/\s*([\d,]+)\s*/\s*([\d,]+)\s*",
        clean_text(pairs.get("모집/대기/신청")),
    )
    if not capacity_match:
        return "invalid 모집/대기/신청 detail"
    capacity_total, waitlist_total, capacity_current = (
        int(value.replace(",", "")) for value in capacity_match.groups()
    )
    source_group = clean_text(pairs.get("구분"))
    location = clean_text(pairs.get("교육장소"))
    if source_group == "평생학습관":
        branch = "중랑구 평생학습관"
    elif source_group == "동 평생학습센터":
        branch = location if "평생학습센터" in location else f"{location} 평생학습센터"
    else:
        branch = source_group or location or clean_text(row.get("branch"))
    row.update(
        {
            "branch": branch,
            "branch_code": stable_provider("JUNGNANG_STUDY_BRANCH", branch),
            "category": source_group or row.get("category"),
            "period": education_period,
            "apply_period": apply_period,
            "schedule_raw": clean_text(pairs.get("교육시간")),
            "target": clean_text(" ".join(filter(None, (pairs.get("교육대상"), pairs.get("교육대상 상세"))))),
            "room": clean_text(pairs.get("교육장소 상세")),
            "venue_name": clean_text(pairs.get("교육장소 상세")),
            "instructor": clean_text(pairs.get("강사명")),
            "fee": clean_text(pairs.get("수강료")) or row.get("fee"),
            "material_fee": clean_text(pairs.get("재료비")),
            "capacity": clean_text(pairs.get("모집/대기/신청")),
            "capacity_current": capacity_current,
            "capacity_total": capacity_total,
            "waitlist_total": waitlist_total,
            "application_method_raw": clean_text(pairs.get("신청방법")),
            "description": clean_text(" ".join(f"{key} {value}" for key, value in pairs.items()))[:8000],
        }
    )
    raw_fields = row.setdefault("raw_fields", {})
    raw_fields["detail_pairs"] = pairs
    raw_fields["detail_url"] = row.get("raw_url")
    application_url = jungnang_study_application_url(soup, clean_text(row.get("raw_url")))
    if row.get("status") == "OPEN":
        if not application_url:
            return "open detail did not expose the official application/login control"
        row["application_url"] = application_url
        row["application_type"] = "ONLINE_RESERVATION"
        row["reservation_available"] = True
        raw_fields["clear_application_url"] = False
        raw_fields["application_link_kind"] = "official_anonymous_login_redirect"
    else:
        row.pop("application_url", None)
        row["reservation_available"] = False
        raw_fields["clear_application_url"] = True
    return ""


def collect_jungnang_study_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    errors: list[str] = []
    if not is_jungnang_study_target(target):
        errors.append("target does not match the canonical Jungnang all-lecture route")
    s = session()
    listed_rows: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    pages = 0
    invalid_rows = 0
    duplicate_rows = 0
    declared_total = 0
    declared_pages = 0
    source_cap_reached = False

    first_soup: Optional[BeautifulSoup] = None
    if not errors:
        try:
            first_soup = fetch_soup(s, jungnang_study_list_url(1), timeout=timeout)
        except Exception as exc:
            logger.warning(
                "Jungnang study list fetch failed page=1 error_type=%s",
                type(exc).__name__,
            )
            errors.append(f"list page 1: {type(exc).__name__}")
    if first_soup is not None:
        first_rows, first_invalid = jungnang_study_list_rows(target, first_soup, 1)
        invalid_rows += first_invalid
        if not first_rows:
            errors.append("first page did not expose a valid numbered lecture row")
        else:
            declared_total = int(first_rows[0]["raw_fields"]["list_ordinal"])
            declared_pages = max(1, (declared_total + JUNGNANG_STUDY_PAGE_SIZE - 1) // JUNGNANG_STUDY_PAGE_SIZE)
            allowed_pages = max(0, max_pages)
            if allowed_pages < declared_pages:
                source_cap_reached = True
                errors.append(f"max_pages cap allows {allowed_pages} of {declared_pages} declared pages")
            for page_index in range(1, min(declared_pages, allowed_pages) + 1):
                try:
                    soup = first_soup if page_index == 1 else fetch_soup(
                        s, jungnang_study_list_url(page_index), timeout=timeout
                    )
                except Exception as exc:
                    logger.warning(
                        "Jungnang study list fetch failed page=%s error_type=%s",
                        page_index,
                        type(exc).__name__,
                    )
                    errors.append(f"list page {page_index}: {type(exc).__name__}")
                    break
                pages += 1
                page_rows, page_invalid = (
                    (first_rows, 0)
                    if page_index == 1
                    else jungnang_study_list_rows(target, soup, page_index)
                )
                invalid_rows += page_invalid
                expected_count = min(
                    JUNGNANG_STUDY_PAGE_SIZE,
                    max(0, declared_total - (page_index - 1) * JUNGNANG_STUDY_PAGE_SIZE),
                )
                if len(page_rows) != expected_count:
                    errors.append(f"page {page_index} exposes {len(page_rows)} of {expected_count} declared rows")
                for row_index, row in enumerate(page_rows):
                    raw_fields = row.get("raw_fields", {})
                    expected_ordinal = declared_total - (page_index - 1) * JUNGNANG_STUDY_ORDINAL_PAGE_STEP - row_index
                    if int(raw_fields.get("list_ordinal") or 0) != expected_ordinal:
                        errors.append(f"page {page_index} has a non-contiguous ordinal")
                    lecture_id = clean_text(raw_fields.get("lecture_id"))
                    if lecture_id in seen_ids:
                        duplicate_rows += 1
                        continue
                    seen_ids.add(lecture_id)
                    listed_rows.append(row)

    if invalid_rows:
        errors.append(f"malformed official list rows ({invalid_rows})")
    if duplicate_rows:
        errors.append(f"duplicated official lecture IDs ({duplicate_rows})")
    if declared_total and len(seen_ids) != declared_total:
        errors.append(f"parsed {len(seen_ids)} unique lecture IDs of {declared_total} declared rows")
    pagination_complete = bool(declared_pages) and pages == declared_pages and len(seen_ids) == declared_total
    today = datetime.now().date()
    current_rows = [
        row for row in listed_rows
        if (jungnang_date_end(row.get("period")) or datetime.min).date() >= today
    ]
    expired_count = len(listed_rows) - len(current_rows)
    allowed_details = max(0, detail_limit)
    detail_attempts = min(allowed_details, len(current_rows))
    detail_pages = 0
    detail_failures: list[str] = []
    if allowed_details < len(current_rows):
        source_cap_reached = True
        errors.append(f"detail_limit cap allows {allowed_details} of {len(current_rows)} current details")
    for row in current_rows[:detail_attempts]:
        lecture_id = clean_text(row.get("raw_fields", {}).get("lecture_id"))
        try:
            soup = fetch_soup(s, clean_text(row.get("raw_url")), timeout=timeout)
            error = jungnang_enrich_study_detail(row, soup)
            if error:
                detail_failures.append(f"{lecture_id}:{error}")
                continue
            detail_pages += 1
        except Exception as exc:
            logger.debug(
                "Jungnang study detail fetch failed lecture_id=%s error_type=%s",
                lecture_id,
                type(exc).__name__,
            )
            detail_failures.append(f"{lecture_id}:{type(exc).__name__}")
    if detail_failures:
        errors.append(f"detail fetch or parse failed for {len(detail_failures)} lectures")
    details_complete = detail_attempts == len(current_rows) and not detail_failures
    snapshot_complete = pagination_complete and details_complete and not errors
    no_current_data = pagination_complete and not current_rows and not errors
    meta: dict[str, Any] = {
        "pages": pages,
        "declared_pages": declared_pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(seen_ids),
        "raw_row_count": len(listed_rows),
        "total_count": declared_total,
        "current_count": len(current_rows),
        "expired_count": expired_count,
        "status_counts": dict(Counter(clean_text(row.get("raw_fields", {}).get("status_raw")) for row in current_rows)),
        "invalid_rows": invalid_rows,
        "duplicate_rows": duplicate_rows,
        "pagination_detected": declared_pages > 1,
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached or not snapshot_complete,
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in current_rows),
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": "all published lectures have ended" if no_current_data else "",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(current_rows), JUNGNANG_STUDY_PARSER, meta


def is_jungnang_bang_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == JUNGNANG_BANG_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == JUNGNANG_BANG_HOST
        and parsed.path == JUNGNANG_BANG_LIST_PATH
        and not parsed.query
    )


def jungnang_bang_list_url(page_index: int) -> str:
    return f"https://{JUNGNANG_BANG_HOST}{JUNGNANG_BANG_LIST_PATH}?{urlencode({'intPage': max(1, page_index)})}"


def jungnang_bang_detail_url(program_id: str, source_category: str) -> str:
    query = urlencode({"sgm": clean_text(source_category), "no": clean_text(program_id), "sugang": "0"})
    return f"https://{JUNGNANG_BANG_HOST}{JUNGNANG_BANG_DETAIL_PATH}?{query}"


def jungnang_bang_declaration(soup: BeautifulSoup) -> Optional[int]:
    match = re.search(r"총\s*([\d,]+)\s*개", clean_text(soup.get_text(" ", strip=True)))
    return int(match.group(1).replace(",", "")) if match else None


def jungnang_bang_list_rows(
    target: CrawlTarget,
    soup: BeautifulSoup,
    page_index: int,
) -> tuple[list[dict[str, Any]], int]:
    rows: list[dict[str, Any]] = []
    invalid_rows = 0
    for block in soup.select("ul.bLine"):
        cells = [clean_text(node.get_text(" ", strip=True)) for node in block.find_all("li", recursive=False)]
        link = block.find("a", href=lambda value: bool(value and "/pf/content.php" in value and "no=" in value))
        if not cells and link is None:
            continue
        # Historical rows may expose an extra responsive-only action cell after the five data cells.
        if len(cells) < 5 or link is None or not cells[0].isdigit():
            invalid_rows += 1
            continue
        cells = cells[:5]
        linked_url = normalize_link(JUNGNANG_BANG_LIST_URL, link.get("href"))
        parsed = urlparse(linked_url)
        query = parse_qs(parsed.query, keep_blank_values=True)
        program_id = clean_text((query.get("no") or [""])[0])
        source_category = clean_text((query.get("sgm") or [""])[0])
        title = clean_text(link.get_text(" ", strip=True))
        status_raw = next((value for value in JUNGNANG_STUDY_STATUS_MAP if cells[1].startswith(value)), "")
        dates = re.findall(r"\b\d{4}-\d{2}-\d{2}\b", cells[2])
        capacity_current, capacity_total = jungnang_capacity_pair(cells[3])
        target_text = clean_text(re.split(r"모집\s*:", cells[3], maxsplit=1)[0])
        if (
            parsed.scheme.lower() != "https"
            or parsed.netloc.lower() != JUNGNANG_BANG_HOST
            or parsed.path != JUNGNANG_BANG_DETAIL_PATH
            or not program_id.isdigit()
            or not source_category
            or not title
            or not status_raw
            or len(dates) not in {2, 4}
            or capacity_current is None
            or capacity_total is None
        ):
            invalid_rows += 1
            continue
        detail_url = jungnang_bang_detail_url(program_id, source_category)
        education_dates = dates[2:4] if len(dates) == 4 else dates[0:2]
        row: dict[str, Any] = {
            "provider": target.provider,
            "provider_course_id": f"{target.provider}:program:{program_id}",
            "prefer_incoming_provider_course_id": True,
            "title": title,
            "branch": JUNGNANG_BANG_BRANCH,
            "branch_code": "JUNGNANG_BANG_CENTER",
            "branch_url": JUNGNANG_BANG_LIST_URL,
            "preserve_branch": True,
            "category": clean_text(cells[4]) or "교육",
            "raw_url": detail_url,
            "status": JUNGNANG_STUDY_STATUS_MAP[status_raw],
            "reservation_available": False,
            "period": f"{education_dates[0]} ~ {education_dates[1]}",
            "apply_period": f"{dates[0]} ~ {dates[1]}",
            "target": target_text,
            "capacity": clean_text(cells[3]),
            "capacity_current": capacity_current,
            "capacity_total": capacity_total,
            "collection_type": "full_pagination+current_detail_html",
            "description": title,
            "raw_fields": {
                "parser": JUNGNANG_BANG_PARSER,
                "program_id": program_id,
                "source_category": source_category,
                "list_ordinal": int(cells[0]),
                "page_index": page_index,
                "status_raw": status_raw,
                "published_date_range_count": len(dates) // 2,
                "list_cells": cells,
                "clear_application_url": True,
            },
            **jungnang_public_course_fields(),
        }
        rows.append(row)
    return rows, invalid_rows


def jungnang_bang_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for block in soup.select("div.li"):
        label = block.find("p")
        value = block.find("font")
        key = clean_text(label.get_text(" ", strip=True) if label else "")
        text = clean_text(value.get_text(" ", strip=True) if value else "")
        if key and text:
            pairs[key] = text
    return pairs


def jungnang_bang_application_url(soup: BeautifulSoup, detail_url: str) -> str:
    has_apply_control = any(
        "신청하기" in clean_text(link.get_text(" ", strip=True))
        and "popupFormFunc" in clean_text(link.get("href"))
        for link in soup.select("a[href]")
    )
    if not has_apply_control:
        return ""
    inline = "\n".join(script.get_text("\n") for script in soup.select("script:not([src])"))
    match = re.search(
        r"location\.href\s*=\s*['\"]([^'\"]*/member/login\.php\?redirectUrl=[^'\"]+)['\"]",
        inline,
    )
    return normalize_link(detail_url, match.group(1)) if match else ""


def jungnang_enrich_bang_detail(row: dict[str, Any], soup: BeautifulSoup) -> str:
    pairs = jungnang_bang_detail_pairs(soup)
    required = ("접수기간", "강의대상", "교육장소", "교육시간", "인원")
    missing = [label for label in required if not clean_text(pairs.get(label))]
    if missing:
        return f"missing detail labels: {','.join(missing)}"
    capacity_current, capacity_total = jungnang_capacity_pair(pairs.get("인원"))
    if capacity_current is None or capacity_total is None:
        return "invalid 모집/접수 detail"
    detail_text = clean_text(soup.get_text(" ", strip=True))
    if clean_text(row.get("title")) not in detail_text:
        return "detail title does not match list title"
    description_table = next(
        (
            table for table in soup.select("table")
            if "교육 내용" in clean_text(table.get_text(" ", strip=True))
            or "상세 내용" in clean_text(table.get_text(" ", strip=True))
        ),
        None,
    )
    row.update(
        {
            "apply_period": bucheon_reservation_datetime_range(pairs.get("접수기간")) or row.get("apply_period"),
            "schedule_raw": clean_text(pairs.get("교육시간")),
            "target": clean_text(pairs.get("강의대상")),
            "room": clean_text(pairs.get("교육장소")),
            "venue_name": clean_text(pairs.get("교육장소")),
            "instructor": clean_text(pairs.get("강사")),
            "phone": clean_text(pairs.get("문의")),
            "fee": clean_text(pairs.get("수강료")),
            "material_fee": clean_text(pairs.get("재료비")),
            "capacity": clean_text(pairs.get("인원")),
            "capacity_current": capacity_current,
            "capacity_total": capacity_total,
            "application_method_raw": "인터넷",
            "description": clean_text(
                description_table.get_text(" ", strip=True) if description_table else row.get("title")
            )[:8000],
        }
    )
    raw_fields = row.setdefault("raw_fields", {})
    raw_fields["detail_pairs"] = pairs
    raw_fields["detail_url"] = row.get("raw_url")
    application_url = jungnang_bang_application_url(soup, clean_text(row.get("raw_url")))
    if row.get("status") == "OPEN":
        if not application_url:
            return "open detail did not expose the official application/login control"
        row["application_url"] = application_url
        row["application_type"] = "ONLINE_RESERVATION"
        row["reservation_available"] = True
        raw_fields["clear_application_url"] = False
        raw_fields["application_link_kind"] = "official_anonymous_login_redirect"
    else:
        row.pop("application_url", None)
        row["reservation_available"] = False
        raw_fields["clear_application_url"] = True
    return ""


def collect_jungnang_bang_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    errors: list[str] = []
    if not is_jungnang_bang_target(target):
        errors.append("target does not match the canonical Bang Jeong-hwan all-program route")
    s = session()
    listed_rows: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    pages = 0
    declared_total = 0
    declared_pages = 0
    invalid_rows = 0
    duplicate_rows = 0
    source_cap_reached = False
    first_soup: Optional[BeautifulSoup] = None
    if not errors:
        try:
            first_soup = fetch_soup(s, jungnang_bang_list_url(1), timeout=timeout)
        except Exception as exc:
            logger.warning(
                "Jungnang community lecture list fetch failed page=1 error_type=%s",
                type(exc).__name__,
            )
            errors.append(f"list page 1: {type(exc).__name__}")
    if first_soup is not None:
        declaration = jungnang_bang_declaration(first_soup)
        if declaration is None:
            errors.append("first page did not expose the official total count")
        else:
            declared_total = declaration
            declared_pages = max(1, (declared_total + JUNGNANG_BANG_PAGE_SIZE - 1) // JUNGNANG_BANG_PAGE_SIZE)
            allowed_pages = max(0, max_pages)
            if allowed_pages < declared_pages:
                source_cap_reached = True
                errors.append(f"max_pages cap allows {allowed_pages} of {declared_pages} declared pages")
            for page_index in range(1, min(declared_pages, allowed_pages) + 1):
                try:
                    soup = first_soup if page_index == 1 else fetch_soup(
                        s, jungnang_bang_list_url(page_index), timeout=timeout
                    )
                except Exception as exc:
                    logger.warning(
                        "Jungnang community lecture list fetch failed page=%s error_type=%s",
                        page_index,
                        type(exc).__name__,
                    )
                    errors.append(f"list page {page_index}: {type(exc).__name__}")
                    break
                pages += 1
                if jungnang_bang_declaration(soup) != declared_total:
                    errors.append(f"page {page_index} changed the official total count")
                page_rows, page_invalid = jungnang_bang_list_rows(target, soup, page_index)
                invalid_rows += page_invalid
                expected_count = min(
                    JUNGNANG_BANG_PAGE_SIZE,
                    max(0, declared_total - (page_index - 1) * JUNGNANG_BANG_PAGE_SIZE),
                )
                if len(page_rows) != expected_count:
                    errors.append(f"page {page_index} exposes {len(page_rows)} of {expected_count} declared rows")
                for row_index, row in enumerate(page_rows):
                    raw_fields = row.get("raw_fields", {})
                    expected_ordinal = declared_total - (page_index - 1) * JUNGNANG_BANG_PAGE_SIZE - row_index
                    if int(raw_fields.get("list_ordinal") or 0) != expected_ordinal:
                        errors.append(f"page {page_index} has a non-contiguous ordinal")
                    program_id = clean_text(raw_fields.get("program_id"))
                    if program_id in seen_ids:
                        duplicate_rows += 1
                        continue
                    seen_ids.add(program_id)
                    listed_rows.append(row)
    if invalid_rows:
        errors.append(f"malformed official list rows ({invalid_rows})")
    if duplicate_rows:
        errors.append(f"duplicated official program IDs ({duplicate_rows})")
    if declared_total and len(seen_ids) != declared_total:
        errors.append(f"parsed {len(seen_ids)} unique program IDs of {declared_total} declared rows")
    pagination_complete = bool(declared_pages) and pages == declared_pages and len(seen_ids) == declared_total
    today = datetime.now().date()
    current_rows = [
        row for row in listed_rows
        if (jungnang_date_end(row.get("period")) or datetime.min).date() >= today
    ]
    expired_count = len(listed_rows) - len(current_rows)
    allowed_details = max(0, detail_limit)
    detail_attempts = min(allowed_details, len(current_rows))
    detail_pages = 0
    detail_failures: list[str] = []
    if allowed_details < len(current_rows):
        source_cap_reached = True
        errors.append(f"detail_limit cap allows {allowed_details} of {len(current_rows)} current details")
    for row in current_rows[:detail_attempts]:
        program_id = clean_text(row.get("raw_fields", {}).get("program_id"))
        try:
            soup = fetch_soup(s, clean_text(row.get("raw_url")), timeout=timeout)
            error = jungnang_enrich_bang_detail(row, soup)
            if error:
                detail_failures.append(f"{program_id}:{error}")
                continue
            detail_pages += 1
        except Exception as exc:
            logger.debug(
                "Jungnang community lecture detail fetch failed program_id=%s error_type=%s",
                program_id,
                type(exc).__name__,
            )
            detail_failures.append(f"{program_id}:{type(exc).__name__}")
    if detail_failures:
        errors.append(f"detail fetch or parse failed for {len(detail_failures)} programs")
    details_complete = detail_attempts == len(current_rows) and not detail_failures
    snapshot_complete = pagination_complete and details_complete and not errors
    no_current_data = pagination_complete and not current_rows and not errors
    meta: dict[str, Any] = {
        "pages": pages,
        "declared_pages": declared_pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_failures": detail_failures,
        "discovered_links": len(seen_ids),
        "raw_row_count": len(listed_rows),
        "total_count": declared_total,
        "current_count": len(current_rows),
        "expired_count": expired_count,
        "status_counts": dict(Counter(clean_text(row.get("raw_fields", {}).get("status_raw")) for row in current_rows)),
        "invalid_rows": invalid_rows,
        "duplicate_rows": duplicate_rows,
        "pagination_detected": declared_pages > 1,
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached or not snapshot_complete,
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in current_rows),
        "recursion_depth": 0,
        "no_current_data": no_current_data,
        "no_current_reason": "all published programs have ended" if no_current_data else "",
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(current_rows), JUNGNANG_BANG_PARSER, meta


JUNGNANG_IMC_PROVIDER = "MUNI_WWW_JUNGNANGIMC_OR_KR_D39C4013"
JUNGNANG_IMC_HOST = "www.jungnangimc.or.kr"
JUNGNANG_IMC_LIST_URL = "https://www.jungnangimc.or.kr/lecture/list/JUNGNANG02"
JUNGNANG_IMC_PARSER = "jungnang_imc_four_center_program_item_api"
JUNGNANG_IMC_PAGE_SIZE = 5000
JUNGNANG_IMC_CENTERS: dict[str, tuple[str, str]] = {
    "JUNGNANG01": ("중랑구민체육센터", "중랑구민체육센터(묵동)"),
    "JUNGNANG02": ("중랑문화체육관", "중랑문화체육관(면목7동)"),
    "JUNGNANG03": ("면목2동체육관", "면목2동체육관"),
    "JUNGNANG19": ("묵2동문화체육복합센터", "묵2동문화체육복합센터"),
}


def is_jungnang_imc_target(target: CrawlTarget) -> bool:
    parsed = urlparse(target.url)
    return (
        target.provider == JUNGNANG_IMC_PROVIDER
        and parsed.scheme.lower() == "https"
        and parsed.netloc.lower() == JUNGNANG_IMC_HOST
        and parsed.path == "/lecture/list/JUNGNANG02"
        and not parsed.query
    )


def jungnang_imc_request_json(
    s: requests.Session,
    endpoint: str,
    params: Optional[dict[str, Any]],
    timeout: int,
) -> Any:
    response = s.get(
        f"https://{JUNGNANG_IMC_HOST}{endpoint}",
        params=params or None,
        headers={"X-Requested-With": "XMLHttpRequest", "Referer": JUNGNANG_IMC_LIST_URL},
        timeout=timeout,
    )
    response.raise_for_status()
    return response.json()


def jungnang_imc_ymd(value: Any) -> str:
    text = clean_text(value)
    if not re.fullmatch(r"\d{8}", text):
        return ""
    try:
        parsed = datetime.strptime(text, "%Y%m%d")
    except ValueError:
        return ""
    return parsed.strftime("%Y-%m-%d")


def jungnang_imc_status(item: dict[str, Any], today: str) -> tuple[str, str]:
    group = item.get("grpcd") if isinstance(item.get("grpcd"), dict) else {}
    use_yn = clean_text(item.get("useYn")).upper()
    always = clean_text(item.get("alwaysAcceptYn")).upper()
    web_finished = clean_text(item.get("webAcceptFinishYn")).upper()
    rec_start = clean_text(group.get("recSdate"))
    rec_end = clean_text(group.get("recEdate"))
    if use_yn == "R":
        return "CLOSED", "휴강"
    if web_finished == "Y":
        return "CLOSED", "접수마감"
    if always == "Y":
        return "OPEN", "상시접수"
    if rec_start <= today <= rec_end:
        return "OPEN", "접수중"
    if today < rec_start:
        return "SCHEDULED", "접수예정"
    return "CLOSED", "접수마감"


def jungnang_imc_program_period(item: dict[str, Any], program: dict[str, Any]) -> str:
    fixed_start = jungnang_imc_ymd(item.get("tcSdate"))
    fixed_end = jungnang_imc_ymd(item.get("tcEdate"))
    if clean_text(item.get("tdateUseYn")).upper() == "Y" and fixed_start and fixed_end:
        return f"{fixed_start} ~ {fixed_end}"
    if clean_text(item.get("alwaysAcceptYn")).upper() == "Y":
        return "상시 운영"
    group = item.get("grpcd") if isinstance(item.get("grpcd"), dict) else {}
    rec_start = jungnang_imc_ymd(group.get("recSdate"))
    start_day = clean_text(group.get("startdate"))
    try:
        rec_date = datetime.strptime(rec_start, "%Y-%m-%d")
        day = int(start_day)
        month_count = max(1, int(program.get("monthCnt") or 1))
    except (TypeError, ValueError):
        return ""
    start_month = rec_date.month + 1
    start_year = rec_date.year + (start_month - 1) // 12
    start_month = (start_month - 1) % 12 + 1
    start = datetime(start_year, start_month, min(day, calendar.monthrange(start_year, start_month)[1]))
    anchor_month = start.month + month_count
    anchor_year = start.year + (anchor_month - 1) // 12
    anchor_month = (anchor_month - 1) % 12 + 1
    anchor = datetime(anchor_year, anchor_month, min(start.day, calendar.monthrange(anchor_year, anchor_month)[1]))
    end = anchor - timedelta(days=1)
    return f"{start:%Y-%m-%d} ~ {end:%Y-%m-%d}"


def jungnang_imc_number(value: Any) -> Optional[int]:
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def jungnang_imc_course_row(
    target: CrawlTarget,
    item: dict[str, Any],
    program: dict[str, Any],
    *,
    today: str,
    facility: dict[str, Any],
    program_count: int,
) -> tuple[Optional[dict[str, Any]], str]:
    center_code = clean_text(item.get("comcd"))
    class_code = clean_text(item.get("classCd"))
    item_code = clean_text(program.get("itemCd"))
    class_name = clean_text(item.get("classNm"))
    if center_code not in JUNGNANG_IMC_CENTERS or not class_code or not item_code or not class_name:
        return None, "missing official center/class/item identity or class title"
    expected_api_name, branch = JUNGNANG_IMC_CENTERS[center_code]
    if clean_text(item.get("comnm")) != expected_api_name:
        return None, f"center name mismatch for {center_code}"
    group = item.get("grpcd") if isinstance(item.get("grpcd"), dict) else {}
    rec_start = jungnang_imc_ymd(group.get("recSdate"))
    rec_end = jungnang_imc_ymd(group.get("recEdate"))
    if not rec_start or not rec_end:
        return None, "missing official new-application window"
    status, status_raw = jungnang_imc_status(item, today)
    adult_group = clean_text(program.get("adultGubn"))
    title = class_name
    if program_count > 1 and adult_group and adult_group not in class_name:
        title = f"{class_name} ({adult_group})"
    raw_url = (
        f"https://{JUNGNANG_IMC_HOST}/lecture/list/{center_code}?"
        f"{urlencode({'classCd': class_code, 'itemCd': item_code})}"
    )
    branch_url = f"https://{JUNGNANG_IMC_HOST}/lecture/list/{center_code}"
    capacity_total = jungnang_imc_number(item.get("webCapa"))
    capacity_current = jungnang_imc_number(item.get("webUser"))
    if capacity_total is None or capacity_current is None:
        return None, "missing official web capacity"
    cost = program.get("costAmt")
    if clean_text(item.get("freeClassYn")).upper() == "Y":
        fee = "무료"
    else:
        try:
            fee = f"{int(float(cost)):,}원"
        except (TypeError, ValueError):
            fee = ""
    period = jungnang_imc_program_period(item, program)
    if not period:
        return None, "could not derive the official program period"
    target_parts = [clean_text(item.get("classObj")), adult_group]
    target_text = clean_text(" ".join(dict.fromkeys(part for part in target_parts if part)))
    schedule = clean_text(" / ".join(filter(None, (item.get("trainDayNm"), item.get("trainTimeNm")))))
    venue = clean_text(item.get("placeCdNm")) or branch
    description_parts = [
        clean_text(item.get("classDesc")),
        clean_text(item.get("classNote")),
        clean_text(item.get("bigo")),
        clean_text(program.get("itemNm")),
    ]
    row: dict[str, Any] = {
        "provider": target.provider,
        "provider_course_id": f"{target.provider}:class:{center_code}:{class_code}:{item_code}",
        "prefer_incoming_provider_course_id": True,
        "title": title,
        "branch": branch,
        "branch_code": center_code,
        "branch_url": branch_url,
        "preserve_branch": True,
        "category": clean_text(item.get("sportsCdNm")) or clean_text(group.get("cdNm")) or "체육강좌",
        "raw_url": raw_url,
        "status": status,
        "reservation_available": status == "OPEN",
        "period": period,
        "apply_period": f"{rec_start} ~ {rec_end}",
        "schedule_raw": schedule,
        "target": target_text,
        "fee": fee,
        "capacity": f"{capacity_current} / {capacity_total}",
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "capacity_remaining": max(0, capacity_total - capacity_current),
        "room": venue,
        "venue_name": venue,
        "venue_address": clean_text(facility.get("addr")),
        "phone": clean_text(facility.get("tel1")),
        "application_method_raw": "온라인 수강신청",
        "collection_type": "four_center_program_item_json_api",
        "description": clean_text(" ".join(dict.fromkeys(part for part in description_parts if part)))[:8000],
        "raw_fields": {
            "parser": JUNGNANG_IMC_PARSER,
            "official_center_code": center_code,
            "official_class_code": class_code,
            "official_item_code": item_code,
            "status_raw": status_raw,
            "use_yn": clean_text(item.get("useYn")),
            "always_accept_yn": clean_text(item.get("alwaysAcceptYn")),
            "web_accept_finish_yn": clean_text(item.get("webAcceptFinishYn")),
            "new_application_start": clean_text(group.get("recSdate")),
            "new_application_end": clean_text(group.get("recEdate")),
            "return_application_start": clean_text(group.get("repSdate")),
            "return_application_end": clean_text(group.get("repEdate")),
            "program_item_name": clean_text(program.get("itemNm")),
            "program_month_count": program.get("monthCnt"),
            "clear_application_url": status != "OPEN",
        },
        **jungnang_public_course_fields(),
    }
    if status == "OPEN":
        row["application_url"] = raw_url
        row["application_type"] = "ONLINE_RESERVATION"
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}, ""


def collect_jungnang_imc_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    errors: list[str] = []
    if not is_jungnang_imc_target(target):
        errors.append("target does not match the canonical Jungnang IMC aggregate route")
    s = session()
    api_requests = 0
    facilities: dict[str, dict[str, Any]] = {}
    today = ""
    if not errors:
        try:
            facility_data = jungnang_imc_request_json(s, "/data/lecture/sb1", None, timeout)
            api_requests += 1
            if not isinstance(facility_data, list):
                errors.append("facility API did not return a list")
            else:
                facilities = {
                    clean_text(item.get("comcd")): item
                    for item in facility_data
                    if isinstance(item, dict) and clean_text(item.get("comcd")) in JUNGNANG_IMC_CENTERS
                }
                for center_code, (expected_name, _display_name) in JUNGNANG_IMC_CENTERS.items():
                    facility = facilities.get(center_code) or {}
                    if clean_text(facility.get("comnm")) != expected_name:
                        errors.append(f"facility API is missing the official {center_code} branch")
            today_data = jungnang_imc_request_json(s, "/data/lecture/today", None, timeout)
            api_requests += 1
            today = clean_text(today_data.get("today")) if isinstance(today_data, dict) else ""
            if not jungnang_imc_ymd(today):
                errors.append("today API did not return a valid YYYYMMDD value")
        except Exception as exc:
            logger.warning(
                "Jungnang IMC facility metadata fetch failed error_type=%s",
                type(exc).__name__,
            )
            errors.append(f"facility/today API: {type(exc).__name__}")

    rows: list[dict[str, Any]] = []
    seen_classes: set[tuple[str, str]] = set()
    seen_items: set[tuple[str, str, str]] = set()
    center_totals: dict[str, int] = {}
    center_item_totals: dict[str, int] = {}
    center_complete: dict[str, bool] = {}
    pages = 0
    raw_row_count = 0
    empty_program_classes = 0
    malformed_classes = 0
    malformed_items = 0
    duplicate_classes = 0
    duplicate_items = 0
    status_counts: Counter[str] = Counter()
    page_budget = PageBudget(max(0, max_pages))
    source_cap_reached = False

    if not errors:
        for center_code in JUNGNANG_IMC_CENTERS:
            center_total: Optional[int] = None
            center_class_count = 0
            center_item_count = 0
            completed = False
            for page_index in range(1, max(0, max_pages) + 1):
                if not page_budget.claim():
                    source_cap_reached = True
                    errors.append(f"max_pages cap reached before completing {center_code}")
                    break
                start_row = (page_index - 1) * JUNGNANG_IMC_PAGE_SIZE
                params = {
                    "comcd": center_code,
                    "sportsCd": "all",
                    "msportsCd": "all",
                    "searchValue": "",
                    "pageIndex": str(page_index),
                    "pageSize": str(JUNGNANG_IMC_PAGE_SIZE),
                    "startRow": str(start_row),
                }
                try:
                    data = jungnang_imc_request_json(s, "/data/lecture/lectureList/", params, timeout)
                    api_requests += 1
                except Exception as exc:
                    logger.warning(
                        "Jungnang IMC lecture API fetch failed center=%s page=%s error_type=%s",
                        center_code,
                        page_index,
                        type(exc).__name__,
                    )
                    errors.append(f"{center_code} page {page_index}: {type(exc).__name__}")
                    break
                pages += 1
                if not isinstance(data, dict) or not isinstance(data.get("resultList"), list):
                    errors.append(f"{center_code} page {page_index} did not return resultList")
                    break
                try:
                    page_total = int(data.get("totalCount"))
                    declared_page = int(data.get("pageIndex"))
                    declared_size = int(data.get("pageSize"))
                    declared_start = int(data.get("startRow"))
                except (TypeError, ValueError):
                    errors.append(f"{center_code} page {page_index} has invalid pagination metadata")
                    break
                if center_total is None:
                    center_total = page_total
                elif center_total != page_total:
                    errors.append(f"{center_code} changed totalCount from {center_total} to {page_total}")
                if (declared_page, declared_size, declared_start) != (
                    page_index,
                    JUNGNANG_IMC_PAGE_SIZE,
                    start_row,
                ):
                    errors.append(f"{center_code} page {page_index} changed pagination metadata")
                result_list = data["resultList"]
                expected_count = min(JUNGNANG_IMC_PAGE_SIZE, max(0, page_total - start_row))
                if len(result_list) != expected_count:
                    errors.append(
                        f"{center_code} page {page_index} exposes {len(result_list)} of {expected_count} declared classes"
                    )
                raw_row_count += len(result_list)
                for item in result_list:
                    if not isinstance(item, dict):
                        malformed_classes += 1
                        continue
                    item_center = clean_text(item.get("comcd"))
                    class_code = clean_text(item.get("classCd"))
                    class_name = clean_text(item.get("classNm"))
                    if item_center != center_code or not class_code or not class_name:
                        malformed_classes += 1
                        continue
                    class_identity = (center_code, class_code)
                    if class_identity in seen_classes:
                        duplicate_classes += 1
                        continue
                    seen_classes.add(class_identity)
                    center_class_count += 1
                    programs = item.get("programItem")
                    if not isinstance(programs, list):
                        malformed_classes += 1
                        continue
                    if not programs:
                        empty_program_classes += 1
                        continue
                    for program in programs:
                        if not isinstance(program, dict):
                            malformed_items += 1
                            continue
                        item_code = clean_text(program.get("itemCd"))
                        identity = (center_code, class_code, item_code)
                        if not item_code:
                            malformed_items += 1
                            continue
                        if identity in seen_items:
                            duplicate_items += 1
                            continue
                        row, error = jungnang_imc_course_row(
                            target,
                            item,
                            program,
                            today=today,
                            facility=facilities.get(center_code) or {},
                            program_count=len(programs),
                        )
                        if error or row is None:
                            malformed_items += 1
                            continue
                        seen_items.add(identity)
                        center_item_count += 1
                        rows.append(row)
                        status_counts[clean_text(row.get("raw_fields", {}).get("status_raw"))] += 1
                if start_row + len(result_list) >= page_total:
                    completed = center_class_count == page_total
                    break
                if not result_list:
                    break
            else:
                source_cap_reached = True
                errors.append(f"max_pages cap reached before completing {center_code}")
            center_totals[center_code] = center_total or 0
            center_item_totals[center_code] = center_item_count
            center_complete[center_code] = completed

    declared_class_count = sum(center_totals.values())
    if len(seen_classes) != declared_class_count:
        errors.append(f"parsed {len(seen_classes)} unique center/class IDs of {declared_class_count} declared classes")
    if malformed_classes:
        errors.append(f"malformed official class rows ({malformed_classes})")
    if malformed_items:
        errors.append(f"malformed official selectable program items ({malformed_items})")
    if duplicate_classes:
        errors.append(f"duplicated official center/class IDs ({duplicate_classes})")
    if duplicate_items:
        errors.append(f"duplicated official center/class/item IDs ({duplicate_items})")
    pagination_complete = (
        len(center_complete) == len(JUNGNANG_IMC_CENTERS)
        and all(center_complete.values())
        and len(seen_classes) == declared_class_count
    )
    details_complete = pagination_complete and malformed_classes == 0 and malformed_items == 0
    snapshot_complete = pagination_complete and details_complete and not errors
    meta: dict[str, Any] = {
        "pages": pages,
        "api_requests": api_requests,
        "raw_row_count": raw_row_count,
        "total_count": len(rows),
        "declared_class_count": declared_class_count,
        "selectable_item_count": len(seen_items),
        "empty_program_classes": empty_program_classes,
        "center_count": len(JUNGNANG_IMC_CENTERS),
        "center_totals": center_totals,
        "center_item_totals": center_item_totals,
        "center_complete": center_complete,
        "status_counts": dict(status_counts),
        "malformed_classes": malformed_classes,
        "malformed_items": malformed_items,
        "duplicate_classes": duplicate_classes,
        "duplicate_items": duplicate_items,
        "detail_pages": 0,
        "detail_attempts": 0,
        "detail_failures": [],
        "discovered_links": len(seen_items),
        "reservation_discovery_links": sum(bool(row.get("application_url")) for row in rows),
        "pagination_detected": pages > len(JUNGNANG_IMC_CENTERS),
        "pagination_complete": pagination_complete,
        "details_complete": details_complete,
        "snapshot_complete": snapshot_complete,
        "source_cap_reached": source_cap_reached or not snapshot_complete,
        "recursion_depth": 0,
        "official_today": today,
    }
    if errors:
        meta["configured_collection_error"] = "; ".join(dict.fromkeys(errors))
    return dedupe_rows(rows), JUNGNANG_IMC_PARSER, meta


def collect_fmcs_lecture_api(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    root_url = fmcs_root_url(target.url)
    referer = target.url
    method = fmcs_http_method(s, root_url, referer, timeout)
    companies = fmcs_request_json(s, root_url, "rest/common/company", {"type": "L"}, method, referer, timeout)
    if isinstance(companies, dict):
        companies = []

    rows: list[dict[str, Any]] = []
    api_pages = 0
    api_requests = 0
    raw_row_count = 0
    category_combo_count = 0
    total_count = 0
    pagination_detected = False
    page_size = 100
    page_limit = max(1, max_pages)

    parsed_query = parse_qs(urlparse(target.url).query)
    target_center = clean_text((parsed_query.get("center") or [""])[0])
    use_global_all_query = target.provider == "MUNI_WWW_IJONGNO_CO_KR_F9ED1CA5"
    use_target_center_query = bool(target_center) and not use_global_all_query
    if use_global_all_query:
        category_combo_count += 1
        for search_type in ("%",):
            page = 1
            while page <= page_limit:
                params = {
                    "company_code": "",
                    "mem_no": "",
                    "search_type": search_type,
                    "category_cd": "",
                    "category_level": "9",
                    "class_nm": "",
                    "train_day": "",
                    "adult_gubn": "",
                    "lecturer_nm": "",
                    "page": str(page),
                    "page_size": str(page_size),
                }
                data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
                api_requests += 1
                list_rows = fmcs_json_rows(data)
                if not list_rows:
                    break
                api_pages += 1
                raw_row_count += len(list_rows)
                page_total_count = fmcs_int(list_rows[0].get("total_count"))
                total_count = max(total_count, page_total_count)
                pagination_detected = pagination_detected or page_total_count > page_size
                for item in list_rows:
                    row = fmcs_row_from_api_item(target, target.url, item, search_type)
                    if row.get("title"):
                        rows.append(row)
                if len(list_rows) < page_size:
                    break
                page += 1

    if not rows and use_target_center_query:
        category_combo_count += 1
        for search_type in ("%",):
            page = 1
            while page <= page_limit:
                params = {
                    "company_code": target_center,
                    "mem_no": "",
                    "search_type": search_type,
                    "category_cd": "",
                    "category_level": "9",
                    "class_nm": "",
                    "train_day": "",
                    "adult_gubn": "",
                    "lecturer_nm": "",
                    "page": str(page),
                    "page_size": str(page_size),
                }
                data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
                api_requests += 1
                list_rows = fmcs_json_rows(data)
                if not list_rows:
                    break
                api_pages += 1
                raw_row_count += len(list_rows)
                page_total_count = fmcs_int(list_rows[0].get("total_count"))
                total_count = max(total_count, page_total_count)
                pagination_detected = pagination_detected or page_total_count > page_size
                for item in list_rows:
                    row = fmcs_row_from_api_item(target, target.url, item, search_type)
                    if row.get("title"):
                        rows.append(row)
                if len(list_rows) < page_size:
                    break
                page += 1

    if not rows:
        if target_center:
            companies = [
                company
                for company in companies
                if clean_text(company.get("comcd")) == target_center
            ]
        for company in companies:
            if api_pages >= page_limit:
                break
            comcd = clean_text(company.get("comcd"))
            if not comcd:
                continue
            company_row_start = len(rows)
            category_contexts = fmcs_category_contexts(s, root_url, comcd, method, referer, timeout)
            category_combo_count += len(category_contexts)
            for category_context in category_contexts:
                if api_pages >= page_limit:
                    break
                for search_type in ("%",):
                    if api_pages >= page_limit:
                        break
                    page = 1
                    while page <= page_limit and api_pages < page_limit:
                        category_cd = clean_text(category_context.get("category_cd"))
                        category_level = clean_text(category_context.get("category_level")) or "9"
                        params = {
                            "company_code": comcd,
                            "mem_no": "",
                            "search_type": search_type,
                            "category_cd": category_cd,
                            "category_level": category_level,
                            "class_nm": "",
                            "train_day": "",
                            "adult_gubn": "",
                            "lecturer_nm": "",
                            "page": str(page),
                            "page_size": str(page_size),
                        }
                        data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
                        api_requests += 1
                        list_rows = fmcs_json_rows(data)
                        if not list_rows:
                            break
                        api_pages += 1
                        raw_row_count += len(list_rows)
                        page_total_count = fmcs_int(list_rows[0].get("total_count"))
                        total_count = max(total_count, page_total_count)
                        pagination_detected = pagination_detected or page_total_count > page_size
                        for item in list_rows:
                            row = fmcs_row_from_api_item(target, target.url, item, search_type, category_context)
                            if row.get("title"):
                                rows.append(row)
                        if len(list_rows) < page_size:
                            break
                        page += 1

            if len(rows) == company_row_start and api_pages < page_limit:
                for search_type in ("R", "E"):
                    if api_pages >= page_limit:
                        break
                    page = 1
                    while page <= page_limit and api_pages < page_limit:
                        params = {
                            "company_code": comcd,
                            "mem_no": "",
                            "search_type": search_type,
                            "category_cd": "",
                            "category_level": "9",
                            "class_nm": "",
                            "train_day": "",
                            "adult_gubn": "",
                            "lecturer_nm": "",
                            "page": str(page),
                            "page_size": str(page_size),
                        }
                        data = fmcs_request_json(s, root_url, "rest/lecture/list", params, method, referer, timeout)
                        api_requests += 1
                        list_rows = fmcs_json_rows(data)
                        if not list_rows:
                            break
                        api_pages += 1
                        raw_row_count += len(list_rows)
                        page_total_count = fmcs_int(list_rows[0].get("total_count"))
                        total_count = max(total_count, page_total_count)
                        pagination_detected = pagination_detected or page_total_count > page_size
                        for item in list_rows:
                            row = fmcs_row_from_api_item(target, target.url, item, search_type)
                            if row.get("title"):
                                rows.append(row)
                        if len(list_rows) < page_size:
                            break
                        page += 1

    detail_pages = 0
    enriched_rows: list[dict[str, Any]] = []
    for row in dedupe_rows(rows):
        if detail_pages < detail_limit and row.get("raw_url"):
            try:
                detail = fmcs_detail_fields(s, row["raw_url"], timeout)
                row = merge_course_rows(row, detail)
                detail_pages += 1
            except Exception as exc:
                logger.debug("fmcs detail fetch failed %s: %s", row.get("raw_url"), exc)
        enriched_rows.append(row)

    meta = {
        "pages": api_pages,
        "api_requests": api_requests,
        "raw_row_count": raw_row_count,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "company_count": len(companies),
        "category_combo_count": category_combo_count,
        "global_all_query": use_global_all_query and bool(rows),
        "target_center": target_center,
        "target_center_query": use_target_center_query and bool(rows),
        "total_count": total_count,
        "http_method": method,
    }
    return enriched_rows, "fmcs_lecture_api", meta


