def buan_page_url(url: str, page: int) -> str:
    parsed = urlparse(url)
    query = parse_qs(parsed.query)
    query["pageIndex"] = [str(page)]
    if parsed.path.endswith("/board/list.buan"):
        query["startPage"] = [str(page)]
        query.setdefault("paging", ["ok"])
        query.setdefault("listRow", ["9"])
        query.setdefault("listCel", ["1"])
    return parsed._replace(query=urlencode(query, doseq=True)).geturl()


def buan_card_pairs(card: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dd in card.select("dd"):
        strong = dd.select_one("strong")
        if not strong:
            continue
        key = clean_text(strong.get_text(" ", strip=True))
        value = clean_text(dd.get_text(" ", strip=True))
        if key and value.startswith(key):
            value = clean_text(value[len(key) :])
        if key and value:
            pairs[key] = value
    return pairs


def buan_detail_pairs(scope: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in scope.select(".bbs_vtop li"):
        strong = item.select_one("strong")
        span = item.select_one("span")
        if not strong or not span:
            continue
        key = clean_text(strong.get_text(" ", strip=True).split("*", 1)[0])
        value = clean_text(span.get_text(" ", strip=True))
        if key and value:
            pairs[key] = value
    return pairs


def buan_first_image_url(base_url: str, scope: BeautifulSoup) -> str:
    image = scope.select_one(".bbs_con img[src], .img_box img[src], img[src]")
    if not image:
        return ""
    src = clean_text(image.get("src"))
    if not src:
        return ""
    absolute = urldefrag(urljoin(base_url, src))[0]
    parsed = urlparse(absolute)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return ""
    return absolute


def buan_branch_info(branch: str) -> dict[str, str]:
    branch = clean_text(branch)
    if branch in {"전라북도 부안군", "전북특별자치도 부안군"}:
        return BUAN_BRANCH_INFO["부안군"]
    if branch in BUAN_BRANCH_INFO:
        return BUAN_BRANCH_INFO[branch]
    if "예술회관" in branch:
        return BUAN_BRANCH_INFO["부안예술회관"]
    return {}


def buan_branch_from_context(context_branch: str, venue: str, category_label: str, fallback: str) -> str:
    context_branch = clean_text(context_branch)
    venue = clean_text(venue)
    category_label = clean_text(category_label)
    if context_branch and context_branch not in {"전체", "모두배정"}:
        return context_branch
    if venue and venue not in {"미정", "없음"}:
        return venue
    if category_label == "예술회관":
        return "부안예술회관"
    if category_label == "미디어센터":
        return "부안미디어센터"
    return clean_text(fallback) or "부안군"


def buan_application_status(apply_period: str, application_url: str, detail_text: str = "") -> str:
    text = clean_text(" ".join([application_url, detail_text]))
    if "모집인원 초과" in text or "마감" in text:
        return "접수마감"
    apply_start, apply_end = parse_date_range(apply_period)
    today = datetime.now().date()
    if apply_start and today < apply_start:
        return "접수예정"
    if apply_end and today > apply_end:
        return "접수마감"
    if apply_start or apply_end:
        return "접수중"
    return ""


def buan_parse_card(
    target: CrawlTarget,
    card: BeautifulSoup,
    page_url: str,
    category_label: str,
    domain_category: str,
    context_branch: str = "",
) -> dict[str, Any]:
    title_el = card.select_one("dt")
    title_link = card.select_one("dt a[href]") or card.select_one(".counter a[href]")
    title = clean_text(title_link.get("title") if title_link and title_link.get("title") else title_el.get_text(" ", strip=True) if title_el else "")
    if not title or "프로그램이 없습니다" in clean_text(card.get_text(" ", strip=True)):
        return {}
    raw_url = normalize_link(page_url, title_link.get("href") if title_link else "") or page_url
    pairs = buan_card_pairs(card)
    badges = [clean_text(i.get_text(" ", strip=True)) for i in card.select("span i") if clean_text(i.get_text(" ", strip=True))]
    category = clean_text(badges[0] if badges else category_label)
    fee_text = clean_text(pairs.get("교육비") or (badges[1] if len(badges) > 1 else ""))
    if fee_text == "무료":
        fee = "0원"
    elif fee_text == "유료":
        fee = fee_text
    else:
        fee = fee_text
    venue = clean_text(pairs.get("진행장소") or pairs.get("교육장소"))
    branch = buan_branch_from_context(context_branch, venue, category_label, target.branch)
    branch_info = buan_branch_info(branch)
    apply_period = clean_text(pairs.get("접수기간"))
    detail_application = title_link or card.select_one(".counter a[href], .counter a[onclick]")
    application_url = ""
    detail_status_text = ""
    if detail_application:
        href = clean_text(detail_application.get("href"))
        onclick = clean_text(detail_application.get("onclick"))
        detail_status_text = clean_text(" ".join([href, onclick, detail_application.get_text(" ", strip=True)]))
        if href and href != "#" and "javascript" not in href:
            application_url = normalize_link(page_url, href) or ""
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
        "title": title,
        "branch": branch,
        "branch_code": branch,
        "address": clean_text(branch_info.get("address")),
        "venue_address": clean_text(branch_info.get("address")),
        "phone": clean_text(pairs.get("문의처") or branch_info.get("phone")),
        "category": category,
        "collection_category": "공공예약",
        "domain_category": domain_category,
        "source_group": "public_reservation",
        "operator_type": "지자체/공공기관",
        "collection_type": "static_html",
        "raw_url": raw_url,
        "application_url": application_url,
        "status": buan_application_status(apply_period, application_url, detail_status_text),
        "fee": fee,
        "period": clean_text(pairs.get("교육기간")),
        "apply_period": apply_period,
        "schedule_raw": clean_text(pairs.get("요일/시간") or pairs.get("교육시간")),
        "target": clean_text(pairs.get("교육대상") or pairs.get("대상")),
        "capacity": clean_text(pairs.get("모집정원") or pairs.get("모집인원")),
        "waitlist": clean_text(pairs.get("예비인원")),
        "venue_name": venue,
        "room": venue,
        "application_method_raw": clean_text(pairs.get("접수방법")),
        "preserve_branch": True,
        "raw_fields": {
            "parser": "buan_reserve_card",
            "page_url": page_url,
            "category_label": category_label,
            "context_branch": context_branch,
            "badges": badges,
            "pairs": pairs,
        },
    }


def buan_detail_fields(s: requests.Session, url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, url, timeout=timeout)
    scope = soup.select_one(".bbs_view") or soup
    pairs = buan_detail_pairs(scope)
    title = clean_text((scope.select_one(".bbs_vtop h4") or scope.select_one("h4") or scope).get_text(" ", strip=True))
    content = scope.select_one(".bbs_con")
    description = clean_text(content.get_text("\n", strip=True) if content else "")
    image_url = buan_first_image_url(url, scope)
    file_names = [
        clean_text(a.get_text(" ", strip=True))
        for a in scope.select(".bbs_filedown a[href]")
        if clean_text(a.get_text(" ", strip=True))
    ]
    application_url = ""
    application_status_text = ""
    apply_button = scope.select_one(".bbs_btn a.bbs_bt2[href], .bbs_btn a.bbs_bt2[onclick]")
    if apply_button:
        href = clean_text(apply_button.get("href"))
        onclick = clean_text(apply_button.get("onclick"))
        application_status_text = clean_text(" ".join([href, onclick, apply_button.get_text(" ", strip=True)]))
        if href and href != "#" and "javascript" not in href:
            application_url = normalize_link(url, href) or ""
    target = clean_text(pairs.get("교육대상") or pairs.get("이용대상"))
    period = clean_text(pairs.get("교육기간"))
    schedule = clean_text(pairs.get("교육시간"))
    venue = clean_text(pairs.get("교육장소") or pairs.get("진행장소"))
    fee = clean_text(pairs.get("수강료"))
    if fee == "무료":
        fee = "0원"
    apply_period = clean_text(pairs.get("접수기간"))
    capacity = clean_text(pairs.get("정원/대기정원") or pairs.get("정원/접수인원/대기자정원"))
    return {
        "title": title,
        "period": period,
        "schedule_raw": schedule,
        "target": target,
        "venue_name": venue,
        "room": venue,
        "instructor": clean_text(pairs.get("강사명")),
        "capacity": capacity,
        "apply_period": apply_period,
        "fee": fee,
        "description": description,
        "material_fee": extract_material_fee_amount(description),
        "material_note": clean_text(
            "\n".join(
                line
                for line in description.splitlines()
                if any(keyword in line for keyword in ("재료", "재료비", "준비물", "교재비"))
            )
        ),
        "application_url": application_url,
        "status": buan_application_status(apply_period, application_url, application_status_text),
        "image_url": image_url,
        "raw_detail_pairs": pairs,
        "attachments": file_names,
    }


def buan_discover_branch_urls(s: requests.Session, url: str, timeout: int) -> list[tuple[str, str]]:
    soup = fetch_soup(s, url, timeout=timeout)
    branch_urls: list[tuple[str, str]] = []
    seen: set[str] = set()
    for link in soup.select(".basic_tab2 a[href]"):
        label = clean_text(link.get_text(" ", strip=True))
        href = normalize_link(url, link.get("href"))
        if not href or href in seen:
            continue
        seen.add(href)
        branch_urls.append((label, href))
    if any(label != "전체" for label, _ in branch_urls):
        return [(label, href) for label, href in branch_urls if label != "전체"]
    return [("", url)]


def collect_buan_reservation_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    branch_page_counts: dict[str, int] = {}
    category_counts: dict[str, int] = {}
    discovered_branch_links = 0
    page_limit = max(1, max_pages)

    for config in BUAN_RESERVE_COURSE_URLS:
        category_label = clean_text(config["label"])
        domain_category = clean_text(config["domain_category"])
        branch_urls = buan_discover_branch_urls(s, config["url"], timeout)
        discovered_branch_links += max(0, len(branch_urls) - 1)
        for context_branch, branch_url in branch_urls:
            blank_pages = 0
            for page in range(1, page_limit + 1):
                current_url = buan_page_url(branch_url, page)
                soup = fetch_soup(s, current_url, timeout=timeout)
                pages += 1
                cards = [
                    card
                    for card in soup.select(".ed_list > div")
                    if "프로그램이 없습니다" not in clean_text(card.get_text(" ", strip=True))
                ]
                if not cards:
                    blank_pages += 1
                    if page == 1 or blank_pages >= 1:
                        break
                    continue
                page_rows = 0
                for card in cards:
                    row = buan_parse_card(target, card, current_url, category_label, domain_category, context_branch)
                    if not row.get("title"):
                        continue
                    if detail_pages < detail_limit and row.get("raw_url") and row["raw_url"] != current_url:
                        try:
                            detail = buan_detail_fields(s, row["raw_url"], timeout)
                            row = merge_course_rows(row, detail)
                            branch = buan_branch_from_context(
                                context_branch,
                                clean_text(row.get("venue_name")),
                                category_label,
                                target.branch,
                            )
                            branch_info = buan_branch_info(branch)
                            row.update(
                                {
                                    "branch": branch,
                                    "branch_code": branch,
                                    "address": clean_text(branch_info.get("address")) or clean_text(row.get("address")),
                                    "venue_address": clean_text(branch_info.get("address")) or clean_text(row.get("venue_address")),
                                    "phone": clean_text(row.get("phone") or branch_info.get("phone")),
                                    "provider_course_id": stable_course_id(target.provider, row["raw_url"], row["title"], branch),
                                    "preserve_branch": True,
                                }
                            )
                            detail_pages += 1
                        except Exception as exc:
                            logger.debug("buan detail fetch failed %s: %s", row.get("raw_url"), exc)
                    rows.append(row)
                    page_rows += 1
                    category_counts[category_label] = category_counts.get(category_label, 0) + 1
                    branch_page_counts[row.get("branch") or context_branch or category_label] = (
                        branch_page_counts.get(row.get("branch") or context_branch or category_label, 0) + 1
                    )
                if len(cards) < 9 or page_rows == 0:
                    break

    rows = dedupe_rows(rows)
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": discovered_branch_links,
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > len(BUAN_RESERVE_COURSE_URLS),
        "recursion_depth": 0,
        "category_counts": category_counts,
        "branch_counts": branch_page_counts,
        "source_urls": [config["url"] for config in BUAN_RESERVE_COURSE_URLS],
    }
    return rows, "buan_reserve_card+detail", meta


DOBONG_REQUEST_PACE_SECONDS = 0.4
DOBONG_RATE_LIMIT_RETRY_DELAYS = (2.0, 5.0, 10.0)


def dobong_retry_delay(response: Optional[requests.Response], fallback: float) -> float:
    retry_after = clean_text(response.headers.get("Retry-After") if response is not None else "")
    try:
        return max(1.0, min(float(retry_after), 30.0))
    except (TypeError, ValueError):
        return fallback


def fetch_dobong_soup(
    s: requests.Session,
    url: str,
    timeout: int,
) -> BeautifulSoup:
    for attempt in range(len(DOBONG_RATE_LIMIT_RETRY_DELAYS) + 1):
        try:
            soup = fetch_soup(s, url, timeout=timeout)
        except requests.HTTPError as exc:
            status_code = getattr(exc.response, "status_code", None)
            if status_code != 429 or attempt >= len(DOBONG_RATE_LIMIT_RETRY_DELAYS):
                raise
            delay = dobong_retry_delay(
                exc.response,
                DOBONG_RATE_LIMIT_RETRY_DELAYS[attempt],
            )
            logger.warning(
                "Dobong lecture request was rate limited; retrying in %.1fs. url=%s",
                delay,
                safe_url_for_log(url),
            )
            time.sleep(delay)
            continue
        time.sleep(DOBONG_REQUEST_PACE_SECONDS)
        return soup
    raise AssertionError("unreachable")


def post_dobong_detail(
    s: requests.Session,
    url: str,
    *,
    data: dict[str, str],
    headers: dict[str, str],
    timeout: int,
) -> requests.Response:
    for attempt in range(len(DOBONG_RATE_LIMIT_RETRY_DELAYS) + 1):
        response = s.post(
            url,
            data=data,
            headers=headers,
            timeout=timeout,
            verify=True,
        )
        if response.status_code == 429 and attempt < len(DOBONG_RATE_LIMIT_RETRY_DELAYS):
            delay = dobong_retry_delay(
                response,
                DOBONG_RATE_LIMIT_RETRY_DELAYS[attempt],
            )
            response.close()
            logger.warning(
                "Dobong lecture detail was rate limited; retrying in %.1fs. url=%s",
                delay,
                safe_url_for_log(url),
            )
            time.sleep(delay)
            continue
        response.raise_for_status()
        time.sleep(DOBONG_REQUEST_PACE_SECONDS)
        return response
    raise AssertionError("unreachable")


def dobong_lecture_index_url(url: str) -> str:
    parsed = urlparse(url)
    query = parse_qs(parsed.query)
    c_id = clean_text((query.get("c_id") or ["01"])[0])
    event_code = clean_text((query.get("event_code") or [""])[0])
    class_code = clean_text((query.get("class_code") or [""])[0])
    page = clean_text((query.get("page") or [""])[0])
    params = {"c_id": c_id, "page_info": "index", "n_type": "lecture"}
    if event_code:
        params["event_code"] = event_code
    if class_code:
        params["class_code"] = class_code
    if page:
        params["page"] = page
    return f"{parsed.scheme}://{parsed.netloc}/lecture/index.php?{urlencode(params)}"


def dobong_lecture_entry_urls(s: requests.Session, target: CrawlTarget, timeout: int) -> list[str]:
    parsed = urlparse(target.url)
    if not parsed.path.endswith("/lecture/guide.php"):
        return [dobong_lecture_index_url(target.url)]
    soup = fetch_dobong_soup(s, target.url, timeout=timeout)
    urls: list[str] = []
    seen: set[str] = set()
    for link in soup.find_all("a", href=True):
        text = clean_text(link.get_text(" ", strip=True))
        if text != "수강신청":
            continue
        href = normalize_link(target.url, link.get("href"))
        if not href:
            continue
        parsed_href = urlparse(href)
        if not parsed_href.path.endswith("/lecture/index.php"):
            continue
        query = parse_qs(parsed_href.query)
        c_id = clean_text((query.get("c_id") or [""])[0])
        if not c_id or c_id in seen:
            continue
        seen.add(c_id)
        params = {"c_id": c_id, "page_info": "index", "n_type": "lecture"}
        urls.append(f"{parsed_href.scheme}://{parsed_href.netloc}/lecture/index.php?{urlencode(params)}")
    return urls or [dobong_lecture_index_url(target.url)]


def dobong_branch_from_soup(soup: BeautifulSoup, fallback: str) -> str:
    candidates = [clean_text(node.get_text(" ", strip=True)) for node in soup.find_all("h2")]
    for text in reversed(candidates):
        if text and "좌측" not in text and text != "교육/강좌":
            return text
    return fallback


def dobong_golink_params(node: Any) -> dict[str, str]:
    onclick = clean_text(node.get("onclick") if hasattr(node, "get") else "")
    match = re.search(r"goLink\((.*?)\)", onclick)
    if not match:
        return {}
    values = re.findall(r"'([^']*)'", match.group(1))
    if len(values) < 5:
        return {}
    return {
        "c_id": values[0],
        "event_code": values[1],
        "class_code": values[2],
        "idx": values[3],
        "sales_code": values[4],
    }


def dobong_period_from_anchor(
    anchor_period: Any,
    title: str,
    target: str,
) -> str:
    period = normalize_mixed_date_range(anchor_period)
    start_date, _end_date = parse_date_range(period)
    if not start_date:
        return period

    duration_text = clean_text(f"{title} {target}")
    duration_match = re.search(r"(\d{1,2})\s*(?:개월|달)", duration_text)
    if not duration_match:
        return period
    duration_months = int(duration_match.group(1))
    duration_months = max(1, min(duration_months, 24))
    end_month_index = (start_date.month - 1) + duration_months - 1
    end_year = start_date.year + (end_month_index // 12)
    end_month = (end_month_index % 12) + 1
    end_day = calendar.monthrange(end_year, end_month)[1]
    return (
        f"{start_date.isoformat()}"
        f" ~ {end_year:04d}-{end_month:02d}-{end_day:02d}"
    )


def dobong_detail_fields(s: requests.Session, base_url: str, params: dict[str, str], timeout: int) -> dict[str, Any]:
    detail_url = urljoin(base_url, "/lecture/lecture_iview.php")
    payload = {
        "c_id": params.get("c_id", ""),
        "event_code": params.get("event_code", ""),
        "class_code": params.get("class_code", ""),
        "idx": params.get("idx", ""),
        "sales_code": params.get("sales_code", ""),
        "n_type": "lecture",
        "lec_status": "on",
    }
    response = post_dobong_detail(
        s,
        detail_url,
        data=payload,
        headers={"Referer": base_url},
        timeout=timeout,
    )
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    soup = BeautifulSoup(response.text, "lxml")
    labels = {
        "\uad50\uc721\uae30\uac04",
        "\uad50\uc721\uc2dc\uac04",
        "\uad50\uc721\uc7a5\uc18c",
        "\uc218\uac15\ub8cc(\uc6d0)",
        "\uc811\uc218\uae30\uac04",
        "\uac15\uc88c\uc18c\uac1c",
        "\uac15\uc88c\ub0b4\uc6a9",
        "\uac1c\uc778\uc900\ube44\ubb3c",
        "\uc7ac\ub8cc\ube44",
        "\uad50\uc7ac\ube44",
    }
    pairs = sequence_lines_to_pairs(lines_from_soup(soup), labels)
    description = clean_text(" ".join(part for part in [pairs.get("\uac15\uc88c\uc18c\uac1c"), pairs.get("\uac15\uc88c\ub0b4\uc6a9")] if part))
    material_note = clean_text(pairs.get("\uac1c\uc778\uc900\ube44\ubb3c"))
    return {
        "period": normalize_mixed_date_range(pairs.get("\uad50\uc721\uae30\uac04", "")),
        "schedule_raw": clean_text(pairs.get("\uad50\uc721\uc2dc\uac04")),
        "room": clean_text(pairs.get("\uad50\uc721\uc7a5\uc18c")),
        "venue_name": clean_text(pairs.get("\uad50\uc721\uc7a5\uc18c")),
        "fee": fmcs_fee_text(pairs.get("\uc218\uac15\ub8cc(\uc6d0)")),
        "apply_period": normalize_mixed_date_range(pairs.get("\uc811\uc218\uae30\uac04", "")),
        "description": description,
        "material_note": material_note,
        "material_fee": clean_text(pairs.get("\uc7ac\ub8cc\ube44") or pairs.get("\uad50\uc7ac\ube44")),
        "raw_detail_pairs": pairs,
    }


def collect_dobongsiseol_lecture(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    entry_urls = dobong_lecture_entry_urls(s, target, timeout=timeout)
    queue = list(entry_urls)
    queued = set(entry_urls)
    visited: set[str] = set()
    rows: list[dict[str, Any]] = []
    pagination_detected = False
    detail_pages = 0
    detail_group_cache_hits = 0
    detail_group_cache: dict[tuple[str, str], dict[str, str]] = {}

    while queue and len(visited) < max_pages:
        url = queue.pop(0)
        if url in visited:
            continue
        visited.add(url)
        soup = fetch_dobong_soup(s, url, timeout=timeout)
        branch = dobong_branch_from_soup(soup, target.branch)
        state: dict[str, str] = {}
        for tr in soup.select("table tbody tr"):
            cells = [clean_text(td.get_text(" ", strip=True)) for td in tr.find_all("td")]
            if len(cells) >= 9:
                state = {
                    "title": cells[0],
                    "instructor": cells[1],
                    "schedule": cells[3],
                    "target": cells[4],
                    "fee": cells[5],
                    "capacity": cells[6],
                    "status": cells[7],
                }
                detail_node = tr.find("a", onclick=re.compile("goLink"))
            elif len(cells) >= 4 and state:
                state = {
                    **state,
                    "schedule": cells[0],
                    "target": cells[1],
                    "fee": cells[2],
                }
                detail_node = tr.find("a", onclick=re.compile("goLink"))
            else:
                continue
            title = clean_text(state.get("title"))
            if not title or is_low_value_title(title):
                continue
            params = dobong_golink_params(detail_node) if detail_node else {}
            identity = ":".join(params.get(key, "") for key in ("c_id", "event_code", "class_code", "idx", "sales_code")) or title
            raw_url = f"{url}#lecture-{identity}"
            target_text = clean_text(state.get("target"))
            detail_group_key = (
                clean_text(params.get("c_id")),
                clean_text(params.get("event_code")),
            )
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, identity, title, branch),
                "title": title,
                "branch": branch,
                "branch_code": params.get("c_id") or branch,
                "category": clean_text(state.get("target")),
                "raw_url": raw_url,
                "application_url": url if "\ubd88\uac00" not in clean_text(state.get("status")) else "",
                "status": clean_text(state.get("status")),
                "fee": fmcs_fee_text(state.get("fee")),
                "period": "",
                "schedule_raw": clean_text(state.get("schedule")),
                "target": target_text,
                "instructor": clean_text(state.get("instructor")),
                "capacity": clean_text(state.get("capacity")),
                "venue_name": branch,
                "description": clean_text(
                    " ".join(
                        part
                        for part in (
                            title,
                            state.get("instructor"),
                            state.get("target"),
                            state.get("schedule"),
                        )
                        if clean_text(part)
                    )
                ),
                "raw_fields": {
                    "parser": "dobongsiseol_lecture_table",
                    "detail_params": params,
                    "list_url": url,
                    "detail_group_key": ":".join(detail_group_key),
                },
            }
            cached_detail = detail_group_cache.get(detail_group_key)
            if cached_detail:
                row["period"] = dobong_period_from_anchor(
                    cached_detail.get("period"),
                    title,
                    target_text,
                )
                row["apply_period"] = clean_text(cached_detail.get("apply_period"))
                row["raw_fields"]["detail_group_cache_hit"] = True
                detail_group_cache_hits += 1
            elif params and all(detail_group_key) and detail_pages < detail_limit:
                try:
                    detail = dobong_detail_fields(s, url, params, timeout)
                    anchor_period = clean_text(detail.get("period"))
                    if anchor_period:
                        detail_group_cache[detail_group_key] = {
                            "period": anchor_period,
                            "apply_period": clean_text(detail.get("apply_period")),
                        }
                        detail["period"] = dobong_period_from_anchor(
                            anchor_period,
                            title,
                            target_text,
                        )
                    row = merge_course_rows(row, detail)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("dobongsiseol detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)

        for a in soup.find_all("a", href=True):
            link = normalize_link(url, a.get("href"))
            if not link or link in queued or not same_site(url, link):
                continue
            parsed = urlparse(link)
            if not parsed.path.endswith("/lecture/index.php"):
                continue
            query = parse_qs(parsed.query)
            if clean_text((query.get("n_type") or [""])[0]) != "lecture":
                continue
            if "event_code" in query or "page" in query:
                pagination_detected = pagination_detected or "page" in query
                queued.add(link)
                queue.append(link)

    page_cap_reached = bool(queue and len(visited) >= max_pages)
    snapshot_complete = not page_cap_reached
    meta = {
        "pages": len(visited),
        "detail_pages": detail_pages,
        "detail_groups": len(detail_group_cache),
        "detail_group_cache_hits": detail_group_cache_hits,
        "discovered_links": len(queued) - len(entry_urls),
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": snapshot_complete,
        "pagination_exhausted": snapshot_complete,
        "page_cap_reached": page_cap_reached,
        "source_cap_reached": page_cap_reached,
        "snapshot_complete": snapshot_complete,
        "no_current_data": snapshot_complete and not rows,
        "no_current_reason": (
            "complete Dobong lecture catalogue contains no current rows"
            if snapshot_complete and not rows
            else ""
        ),
        "recursion_depth": 1 if len(visited) > 1 else 0,
        "branches": len(entry_urls),
    }
    return dedupe_rows(rows), "dobongsiseol_lecture_table", meta


def normalize_seongju_welfare_date_range(value: Any) -> str:
    text = clean_text(value).replace("`", "").replace("∼", "~").replace("～", "~")

    def repl(match: re.Match[str]) -> str:
        year = int(match.group(1))
        month = int(match.group(2))
        day = int(match.group(3))
        return f"20{year:02d}-{month:02d}-{day:02d}"

    text = re.sub(r"\b(\d{2})[-.](\d{1,2})[-.](\d{1,2})\b", repl, text)
    return clean_text(text)


def extract_seongju_welfare_target(description: str, category: str) -> str:
    text = clean_text(description)
    match = re.search(
        r"모집대상\s*[:：]?\s*(.*?)(?=\s*[-ㆍ·]?\s*(?:수강요일|교육장소|교육기간|수강료|교육비|재료비|신청)|$)",
        text,
    )
    if match:
        target = clean_text(match.group(1))
        target = re.sub(r"\s*\d+\s*명\s*$", "", target).strip()
        if target:
            return target
    if "청소년문화의집" in category:
        return "청소년"
    return "성주군민"


def extract_seongju_welfare_venue(description: str, category: str) -> tuple[str, str]:
    text = clean_text(description)
    venue = ""
    match = re.search(r"교육장소\s*[:：]?\s*(.*)$", text)
    if match:
        venue = match.group(1)
        for marker in ("<신청", "신청", "유의사항", "수강료", "교육비", "재료비"):
            venue = venue.split(marker, 1)[0]
        venue = clean_text(venue).strip("-:：")
    if "창의문화센터" in venue:
        return venue, "경북 성주군 성주읍 경산길 17"
    if "문화예술회관" in venue:
        return venue, "경북 성주군 성주읍 성주로 3204"
    if "청소년문화의집" in category:
        return "성주군청소년문화의집", "경북 성주군 성주읍 성주로 3200"
    return venue or "성주복지플랫폼", ""


def parse_seongju_welfare_detail(
    provider: str,
    branch: str,
    category: str,
    raw_url: str,
    soup: BeautifulSoup,
) -> dict[str, Any]:
    pairs = pairs_from_tables(soup)
    title = ""
    for tr in soup.select("table tr"):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
        if len(cells) == 1:
            title = clean_text(re.sub(r"\s+\d{4}-\d{2}-\d{2}\s+조회\s*$", "", cells[0]))
            break
    description = clean_text(pairs.get("교육내용"))
    venue_name, venue_address = extract_seongju_welfare_venue(description, category)
    target_text = extract_seongju_welfare_target(description, category)
    capacity_current, capacity_total = parse_capacity_pair(pairs.get("모집인원"))
    return {
        "title": title,
        "period": normalize_seongju_welfare_date_range(pairs.get("수강기간") or pairs.get("기간")),
        "schedule_raw": clean_text(pairs.get("요일/시간") or pairs.get("교육시간")),
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "description": description,
        "fee": clean_text(pairs.get("수강료")),
        "material_fee": clean_text(pairs.get("재료비")),
        "status": clean_text(pairs.get("상태")),
        "target": target_text,
        "venue_name": venue_name,
        "venue_address": venue_address,
        "address": venue_address,
        "raw_url": raw_url,
        "application_url": raw_url,
        "raw_fields": {"detail_pairs": pairs, "parser": "seongju_welfare_detail"},
    }


def collect_seongju_welfare_platform(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    default_urls = [
        "https://sj-welfare.or.kr/cnts/community/educationApplication.html",
        "https://sj-welfare.or.kr/cnts/community/youthCulturalCenter.html",
    ]
    configured_urls: list[str] = []
    for key in ("list_urls", "additional_urls", "related_urls"):
        values = target.extra.get(key) if isinstance(target.extra, dict) else None
        if isinstance(values, list):
            configured_urls.extend(clean_text(value) for value in values if clean_text(value))
    list_urls = configured_urls or default_urls
    if target.url not in list_urls:
        list_urls.insert(0, target.url)

    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    pagination_detected = False
    exhausted_lists = 0
    seen_detail_urls: set[str] = set()

    for list_url in list_urls:
        category = "청소년문화의집" if "youthCulturalCenter" in list_url else "군민평생교육"
        list_exhausted = False
        for page in range(1, max(1, max_pages) + 1):
            parsed = urlparse(list_url)
            query = parse_qs(parsed.query)
            query["page"] = [str(page)]
            page_url = parsed._replace(query=urlencode(query, doseq=True)).geturl()
            soup = fetch_soup(s, page_url, timeout=timeout)
            pages += 1
            table = soup.find("table")
            if not table:
                break
            header = [clean_text(cell.get_text(" ", strip=True)) for cell in table.select("tr:first-child th")]
            body_rows = table.select("tbody tr") or table.select("tr")[1:]
            page_rows = 0
            for tr in body_rows:
                cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all("td")]
                if len(cells) < 8 or not re.fullmatch(r"\d+", cells[0] or ""):
                    continue
                values = dict(zip(header, cells))
                detail_link = tr.find("a", href=True)
                raw_url = normalize_link(page_url, detail_link.get("href") if detail_link else None) or page_url
                title = values.get("강좌명") or cells[1]
                row = {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, category),
                    "title": title,
                    "branch": "성주복지플랫폼",
                    "category": category,
                    "collection_category": "평생학습",
                    "domain_category": "평생학습",
                    "source_group": "lifelong_learning",
                    "operator_type": "지자체/공공기관",
                    "collection_type": "static_html",
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": values.get("상태") or cells[6],
                    "period": normalize_seongju_welfare_date_range(values.get("수강기간") or values.get("기간") or cells[4]),
                    "schedule_raw": clean_text(values.get("요일/시간") or values.get("교육시간")),
                    "capacity": values.get("모집인원") or cells[5],
                    "target": "청소년" if category == "청소년문화의집" else "성주군민",
                    "venue_name": "성주군청소년문화의집" if category == "청소년문화의집" else "성주복지플랫폼",
                    "venue_address": "경북 성주군 성주읍 성주로 3200",
                    "address": "경북 성주군 성주읍 성주로 3200",
                    "raw_fields": {"list_values": values, "parser": "seongju_welfare_table"},
                }
                if raw_url not in seen_detail_urls and detail_pages < detail_limit:
                    seen_detail_urls.add(raw_url)
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail = parse_seongju_welfare_detail(target.provider, target.branch, category, raw_url, detail_soup)
                        row = merge_course_rows(row, detail)
                        row["title"] = detail.get("title") or row["title"]
                        for key in (
                            "target",
                            "venue_name",
                            "venue_address",
                            "address",
                            "fee",
                            "material_fee",
                            "description",
                            "period",
                            "schedule_raw",
                            "status",
                            "capacity_current",
                            "capacity_total",
                        ):
                            if detail.get(key):
                                row[key] = detail[key]
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("seongju welfare detail fetch failed %s: %s", raw_url, exc)
                rows.append(row)
                page_rows += 1
            pagination_detected = pagination_detected or bool(soup.select(".pagination, .paging, a[href*='page=']"))
            if page_rows == 0 or page >= 1 and not soup.select(f"a[href*='page={page + 1}']"):
                list_exhausted = True
                break
        if list_exhausted:
            exhausted_lists += 1

    pagination_exhausted = exhausted_lists == len(list_urls)
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "source_cap_reached": not pagination_exhausted,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "seongju_welfare_table+detail", meta


ICHEON_WORKER_WELFARE_BRANCH = "이천시노동자복지관"
ICHEON_WORKER_WELFARE_ADDRESS = "경기도 이천시 부발읍 무촌로18번길 60-26"
ICHEON_WORKER_WELFARE_PHONE = "031-632-9806~8"


def normalize_icheon_worker_title(value: Any) -> str:
    title = clean_text(value)
    title = re.sub(r"^\((오전|오후|야간|주야)\)\s*", "", title)
    title = re.sub(r"^(오전|오후|야간|주야)\s+", "", title)
    return clean_text(title)


def normalize_icheon_worker_apply_period(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    text = re.sub(r"(\d{2})\.(\d{2})\.(\d{2})", r"20\1-\2-\3", text)
    text = re.sub(r"\((?:선착순|정시|대기자)?\s*모집\s*기간\)", "", text)
    return clean_text(text)


def icheon_worker_detail_description(soup: BeautifulSoup) -> str:
    node = soup.select_one(".board_view .con")
    if not node:
        return ""
    return clean_text(node.get_text("\n", strip=True))


def icheon_worker_target_from_description(description: str) -> str:
    parts: list[str] = []
    target_match = re.search(
        r"일반모집대상\s*[:：]?\s*(.+?)(?=\s*(?:◈|최소연령제한|인터넷접수|$))",
        description,
    )
    if target_match:
        parts.append(clean_text(target_match.group(1)))
    age_match = re.search(
        r"최소연령제한\s*[:：]?\s*(.+?)(?=\s*(?:◈|인터넷접수|$))",
        description,
    )
    if age_match:
        parts.append(clean_text(age_match.group(1)))
    return " / ".join(part for part in parts if part)


def parse_icheon_worker_detail(soup: BeautifulSoup, raw_url: str) -> dict[str, Any]:
    view = soup.select_one(".board_view") or soup
    pairs = pairs_from_definition_lists(view)
    raw_title = clean_text((view.select_one("p.title") or view.select_one(".title") or view).get_text(" ", strip=True))
    description = icheon_worker_detail_description(soup)
    target_text = icheon_worker_target_from_description(description)
    material_note = "\n".join(
        line
        for line in description.splitlines()
        if any(keyword in line for keyword in ("재료비", "교재비", "재료", "준비물"))
    )
    values = re.findall(r"\d+", pairs.get("정원 / 신청자 / 대기자") or "")
    capacity_total = values[0] if len(values) >= 1 else ""
    capacity_current = values[1] if len(values) >= 2 else ""
    waitlist_total = values[2] if len(values) >= 3 else ""
    return {
        "title": normalize_icheon_worker_title(raw_title),
        "category": clean_text(pairs.get("교육과정") or pairs.get("분야")),
        "apply_period": normalize_icheon_worker_apply_period(pairs.get("정시 모집 기간")),
        "waitlist_period": normalize_icheon_worker_apply_period(pairs.get("대기자 모집 기간")),
        "period": clean_text(pairs.get("교육기간")),
        "schedule_raw": clean_text(
            pairs.get("요일/시간")
            or pairs.get("교육시간")
            or pairs.get("교육일시")
        ),
        "fee": clean_text(pairs.get("수강료")),
        "room": clean_text(pairs.get("강의실")),
        "venue_name": clean_text(pairs.get("강의실")),
        "phone": clean_text(pairs.get("문의처")) or ICHEON_WORKER_WELFARE_PHONE,
        "instructor": clean_instructor_name(pairs.get("강사명")),
        "description": description,
        "target": target_text,
        "eligibility_raw": target_text,
        "capacity": pairs.get("정원 / 신청자 / 대기자"),
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "waitlist_total": waitlist_total,
        "material_note": clean_text(material_note),
        "material_fee": extract_material_fee_amount(material_note, description),
        "application_method_raw": "홈페이지 회원 로그인 후 온라인 접수",
        "raw_url": raw_url,
        "application_url": raw_url,
        "raw_fields": {"detail_pairs": pairs, "parser": "icheon_worker_welfare_detail"},
    }


def collect_icheon_worker_welfare(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    list_url = "https://www.icheon-hrd.or.kr/program/programInfoList.do"
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    detail_attempts = 0
    detail_errors = 0
    seen_detail_urls: set[str] = set()
    enriched_detail_urls: set[str] = set()
    effective_detail_limit = 10**9 if detail_limit is None or detail_limit < 0 else detail_limit
    site_last_page = 0
    pagination_complete = False
    terminal_count = 0

    for page in range(1, max(1, max_pages) + 1):
        page_url = f"{list_url}?pgno={page}"
        soup = fetch_soup(s, page_url, timeout=timeout)
        page_text = clean_text(soup.get_text(" ", strip=True))
        page_match = re.search(r"현재페이지\s*:\s*(\d+)\s*/\s*(\d+)", page_text)
        if not page_match:
            raise ValueError(
                f"Icheon worker welfare page {page} omitted pagination declaration"
            )
        current_page = int(page_match.group(1))
        observed_last_page = int(page_match.group(2))
        if current_page != page or observed_last_page < page:
            raise ValueError(
                "Icheon worker welfare pagination response changed "
                f"(requested={page} current={current_page} last={observed_last_page})"
            )
        if site_last_page and observed_last_page != site_last_page:
            raise ValueError(
                "Icheon worker welfare last page changed "
                f"from {site_last_page} to {observed_last_page}"
            )
        site_last_page = observed_last_page
        table = soup.find("table")
        if not table:
            raise ValueError(f"Icheon worker welfare page {page} omitted the course table")
        pages += 1
        body_rows = table.select("tr")[1:]
        source_page_rows = 0
        for tr in body_rows:
            cells = tr.find_all("td")
            if len(cells) < 7:
                continue
            title_link = cells[0].find("a", href=True)
            if not title_link:
                continue
            source_page_rows += 1
            time_slot_node = cells[0].select_one(".tag")
            time_slot = clean_text(time_slot_node.get_text(" ", strip=True) if time_slot_node else "")
            title = normalize_icheon_worker_title(title_link.get_text(" ", strip=True))
            if not title or is_low_value_title(title):
                continue
            raw_url = normalize_link(page_url, title_link.get("href")) or page_url
            status = clean_text(" / ".join(span.get_text(" ", strip=True) for span in cells[6].select(".edutag")))
            if any(token in status for token in ("교육종료", "강좌취소", "폐강")):
                terminal_count += 1
                continue
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, ICHEON_WORKER_WELFARE_BRANCH),
                "title": title,
                "branch": ICHEON_WORKER_WELFARE_BRANCH,
                "branch_code": "ICHEON_WORKER_WELFARE_CENTER",
                "preserve_branch": True,
                "address": ICHEON_WORKER_WELFARE_ADDRESS,
                "venue_address": ICHEON_WORKER_WELFARE_ADDRESS,
                "phone": ICHEON_WORKER_WELFARE_PHONE,
                "category": time_slot,
                "raw_url": raw_url,
                "application_url": raw_url,
                "status": status,
                "schedule_raw": "",
                "apply_period": normalize_icheon_worker_apply_period(cells[2].get_text(" ", strip=True)),
                "capacity_total": clean_text(cells[3].get_text(" ", strip=True)),
                "capacity_current": clean_text(cells[4].get_text(" ", strip=True)),
                "waitlist_total": clean_text(cells[5].get_text(" ", strip=True)),
                "fee": "무료",
                "target": "지역주민 및 일반인",
                "collection_category": "복지관",
                "domain_category": "복지관",
                "source_group": "welfare",
                "operator_type": "복지기관",
                "collection_type": "static_html",
                "program_type": "강좌",
                "application_method_raw": "홈페이지 회원 로그인 후 온라인 접수",
                "raw_fields": {"time_slot": time_slot, "parser": "icheon_worker_welfare_list"},
            }
            if raw_url not in seen_detail_urls and detail_attempts < effective_detail_limit:
                seen_detail_urls.add(raw_url)
                detail_attempts += 1
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail = parse_icheon_worker_detail(detail_soup, raw_url)
                    row = merge_course_rows(row, detail)
                    row["title"] = detail.get("title") or row["title"]
                    row["apply_period"] = (
                        detail.get("apply_period") or row["apply_period"]
                    )
                    row["target"] = detail.get("target") or row["target"]
                    row["category"] = " / ".join(
                        part for part in (time_slot, detail.get("category")) if clean_text(part)
                    )
                    row["preserve_branch"] = True
                    row["branch"] = ICHEON_WORKER_WELFARE_BRANCH
                    row["branch_code"] = "ICHEON_WORKER_WELFARE_CENTER"
                    row["address"] = ICHEON_WORKER_WELFARE_ADDRESS
                    row["venue_address"] = ICHEON_WORKER_WELFARE_ADDRESS
                    detail_pages += 1
                    enriched_detail_urls.add(raw_url)
                except Exception as exc:
                    detail_errors += 1
                    row.setdefault("raw_fields", {})["detail_error"] = type(exc).__name__
                    logger.debug("icheon worker welfare detail fetch failed %s: %s", raw_url, exc)
            rows.append(row)
        if source_page_rows == 0 and page < site_last_page:
            raise ValueError(
                f"Icheon worker welfare page {page} was empty before declared last page "
                f"{site_last_page}"
            )
        if page >= site_last_page:
            pagination_complete = True
            break

    rows = dedupe_rows(rows)
    expected_detail_urls = {
        clean_text(row.get("raw_url"))
        for row in rows
        if clean_text(row.get("raw_url"))
    }
    detail_enrichment_complete = (
        not expected_detail_urls
        or (
            detail_errors == 0
            and expected_detail_urls.issubset(enriched_detail_urls)
        )
    )
    page_cap_reached = not pagination_complete
    detail_cap_reached = bool(
        expected_detail_urls - enriched_detail_urls
    ) and detail_attempts >= effective_detail_limit
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "detail_attempts": detail_attempts,
        "detail_errors": detail_errors,
        "detail_enrichment_complete": detail_enrichment_complete,
        "detail_cap_reached": detail_cap_reached,
        "discovered_links": 0,
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": site_last_page > 1,
        "pagination_complete": pagination_complete,
        "pagination_exhausted": pagination_complete,
        "page_cap_reached": page_cap_reached,
        "source_cap_reached": page_cap_reached or detail_cap_reached,
        "recursion_depth": 0,
        "declared_last_page": site_last_page,
        "terminal_count": terminal_count,
        "no_current_data": pagination_complete and not rows,
        "no_current_reason": (
            "all Icheon worker welfare courses have ended"
            if pagination_complete and not rows
            else ""
        ),
        "configured_collection_error": (
            f"detail fetch failed for {detail_errors} current courses"
            if detail_errors
            else ""
        ),
    }
    return rows, "icheon_worker_welfare_table+detail", meta


def normalize_link(base_url: str, href: str | None) -> str:
    if not href:
        return ""
    href = href.strip()
    if not href or href.startswith(("javascript:", "mailto:", "tel:", "#")):
        return ""
    absolute = urljoin(base_url, href)
    absolute = urldefrag(absolute)[0]
    parsed = urlparse(absolute)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        return ""
    if parsed.path.lower().endswith(REJECT_EXTENSIONS):
        return ""
    return absolute


def javascript_url_candidates(base_url: str, script: Any) -> list[str]:
    text = clean_text(script)
    if not text:
        return []
    candidates: list[str] = []
    seen: set[str] = set()
    patterns = (
        r"(?:location(?:\.href)?|document\.location|window\.location)\s*=\s*['\"]([^'\"]+)['\"]",
        r"(?:window\.open|location\.replace|location\.assign)\s*\(\s*['\"]([^'\"]+)['\"]",
        r"(?:goUrl|goLink|fn_goUrl|fnGoUrl|fnLink|fn_move|movePage)\s*\(\s*['\"]([^'\"]+)['\"]",
    )
    for pattern in patterns:
        for match in re.findall(pattern, text, flags=re.IGNORECASE):
            url = normalize_link(base_url, match)
            if url and url not in seen:
                seen.add(url)
                candidates.append(url)
    for quoted in re.findall(r"['\"]([^'\"]+)['\"]", text):
        if not re.search(r"(?:https?://|/|\.do|\.jsp|\.php|\.asp|\.aspx|\.html?)", quoted, re.IGNORECASE):
            continue
        url = normalize_link(base_url, quoted)
        if url and url not in seen:
            seen.add(url)
            candidates.append(url)
    return candidates


def node_link_evidence(node: Any) -> str:
    parts: list[str] = []
    if hasattr(node, "get_text"):
        parts.append(clean_text(node.get_text(" ", strip=True)))
    for attr in (
        "title",
        "aria-label",
        "alt",
        "data-title",
        "data-name",
        "data-menu",
        "data-menu-name",
        "data-label",
        "data-text",
    ):
        if hasattr(node, "get"):
            parts.append(clean_text(node.get(attr)))
    if hasattr(node, "select"):
        for image in node.select("img[alt]")[:3]:
            parts.append(clean_text(image.get("alt")))
    return clean_text(" ".join(part for part in parts if part))


def node_link_url(base_url: str, node: Any) -> str:
    if not hasattr(node, "get"):
        return ""
    href = node.get("href")
    url = normalize_link(base_url, href)
    if url:
        return url
    for attr in ("data-url", "data-href", "data-link", "data-target-url"):
        url = normalize_link(base_url, node.get(attr))
        if url:
            return url
    for url in javascript_url_candidates(base_url, node.get("onclick")):
        return url
    return ""


JPYOUTH_BRANCH = "증평군청소년수련관"
JPYOUTH_ADDRESS = "충북 증평군 증평읍 보건복지로 64-2"


def jpyouth_list_url(base_url: str, page: int) -> str:
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    query["menukey"] = ["54"]
    query["mode"] = ["list"]
    query["page"] = [str(page)]
    query.setdefault("srhctgr", [""])
    query.setdefault("srhstr", [""])
    return urlunparse((parsed.scheme, parsed.netloc, parsed.path or "/sub.php", "", urlencode(query, doseq=True), ""))


def jpyouth_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for tr in soup.select("table tr"):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
        cells = [cell for cell in cells if cell]
        if len(cells) == 2:
            pairs[cells[0]] = cells[1]
        elif len(cells) >= 4:
            for index in range(0, len(cells) - 1, 2):
                key = cells[index]
                value = cells[index + 1]
                if key and value:
                    pairs[key] = value
    return pairs


def jpyouth_detail_fields(s: requests.Session, detail_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    pairs = jpyouth_pairs(soup)
    description = clean_text(pairs.get("본문내용"))
    fee = clean_text(pairs.get("수강료"))
    if not fee and description:
        fee_match = re.search(
            r"(?:참가비|수강료|재료비)\s*[:：]?\s*((?:[가-힣A-Za-z0-9]+\s*)?\d[\d,]*\s*원(?:\([^)]*\))?)",
            description,
        )
        if fee_match:
            fee = clean_text(fee_match.group(1))
        elif extract_krw_amount(description):
            fee = f"{extract_krw_amount(description):,}원"
    instructor_raw = clean_text(pairs.get("문의 및 담당자"))
    instructor = clean_text(re.sub(r"\b0\d{1,2}[-)]?\d{3,4}[-]?\d{4}\b", "", instructor_raw))
    return {
        "title": clean_text(pairs.get("제목")),
        "period": clean_text(pairs.get("교육기간")),
        "schedule_raw": clean_text(pairs.get("요일/시간") or pairs.get("교육시간")),
        "apply_period": clean_text(pairs.get("접수일시")),
        "room": clean_text(pairs.get("장소")),
        "venue_name": clean_text(pairs.get("장소")),
        "target": clean_text(pairs.get("교육대상") or pairs.get("대상")),
        "capacity_total": parse_capacity_number(pairs.get("접수인원")),
        "instructor": clean_instructor_name(pairs.get("강사명") or instructor),
        "description": description,
        "fee": fee,
        "raw_fields": {"detail_pairs": pairs, "parser": "jpyouth_table+detail"},
    }


def split_jpyouth_list_schedule(value: Any) -> tuple[str, str]:
    text = clean_text(value)
    match = re.match(
        r"^(\d{4}[./-]\d{1,2}[./-]\d{1,2}\s*~\s*\d{4}[./-]\d{1,2}[./-]\d{1,2})(.*)$",
        text,
    )
    if not match:
        return text, text
    tail = clean_text(match.group(2))
    schedule = tail
    dated_schedule = re.search(r"(\d{4}\.\s*\d{1,2}\.\s*\d{1,2}\.\s*\([^)]+\).*|매주\s*.+)", tail)
    if dated_schedule:
        schedule = clean_text(dated_schedule.group(1))
    return clean_text(match.group(1)), schedule


def collect_jpyouth_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    seen_urls: set[str] = set()
    for page in range(1, max_pages + 1):
        page_url = jpyouth_list_url(target.url, page)
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for tr in soup.select("table tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
            if len(cells) < 7 or not re.fullmatch(r"\d+", cells[0] or ""):
                continue
            link = tr.find("a", href=True)
            raw_url = normalize_link(page_url, link.get("href") if link else None) or page_url
            if raw_url in seen_urls:
                continue
            seen_urls.add(raw_url)

            title = clean_text(link.get_text(" ", strip=True) if link else cells[1]) or cells[1]
            period, schedule = split_jpyouth_list_schedule(cells[2])
            capacity_total = parse_capacity_number(cells[3])
            room = clean_text(cells[4])
            target_text = clean_text(cells[5])
            status = clean_text(cells[6].replace("상태 :", ""))

            detail: dict[str, Any] = {}
            if detail_pages < detail_limit and raw_url:
                try:
                    detail = jpyouth_detail_fields(s, raw_url, timeout=timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("jpyouth detail fetch failed %s: %s", raw_url, exc)

            title = title or clean_text(detail.get("title"))
            period = clean_text(detail.get("period")) or period
            schedule = clean_text(detail.get("schedule_raw")) or schedule
            room = clean_text(detail.get("room")) or room
            target_text = clean_text(detail.get("target")) or target_text
            start_date, end_date = parse_date_range(period)
            course_for_expiry = {"end_date": end_date}
            if should_skip_expired_course(course_for_expiry):
                continue

            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, JPYOUTH_BRANCH),
                "title": title,
                "branch": JPYOUTH_BRANCH,
                "branch_code": target.provider,
                "address": JPYOUTH_ADDRESS,
                "venue_name": room or JPYOUTH_BRANCH,
                "venue_address": JPYOUTH_ADDRESS if room == JPYOUTH_BRANCH else "",
                "raw_url": raw_url,
                "application_url": raw_url if "마감" not in status else "",
                "status": status,
                "period": period,
                "schedule_raw": schedule,
                "apply_period": clean_text(detail.get("apply_period")),
                "target": target_text,
                "eligibility_raw": target_text,
                "capacity_total": capacity_total or detail.get("capacity_total"),
                "fee": clean_text(detail.get("fee")),
                "instructor": clean_text(detail.get("instructor")),
                "description": clean_text(detail.get("description")),
                "start_date": start_date,
                "end_date": end_date,
                "collection_category": "청소년",
                "domain_category": "청소년",
                "source_group": "youth",
                "operator_type": "청소년시설",
                "collection_type": "static_html",
                "preserve_branch": True,
                "raw_fields": {
                    "parser": "jpyouth_table+detail",
                    "list_url": page_url,
                    "cells": cells,
                    "detail": detail.get("raw_fields", {}),
                },
            }
            rows.append(row)
            page_rows += 1
        if page_rows == 0:
            break

        pager_text = soup.get_text(" ", strip=True)
        if str(page + 1) not in pager_text and page >= 1:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_urls),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pages > 1,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jpyouth_table+detail", meta


SUWON_LEARNING_LIST_PATH = "/lmth/01_lecture01.asp"
SUWON_LEARNING_BRANCH = "수원시 평생학습관"
SUWON_RESIDENT_AUTONOMY_HOSTS = {
    "jangan.suwon.go.kr",
    "ksun.suwon.go.kr",
    "paldal.suwon.go.kr",
    "ytedu.suwon.go.kr",
}


def suwon_learning_list_url(base_url: str, page: int) -> str:
    parsed = urlparse(base_url)
    query = parse_qs(parsed.query)
    if parsed.path != SUWON_LEARNING_LIST_PATH:
        query = {}
    if page > 1:
        query["page"] = [str(page)]
        query["block"] = [str(((page - 1) // 10) + 1)]
    else:
        query.pop("page", None)
        query.pop("block", None)
    return parsed._replace(path=SUWON_LEARNING_LIST_PATH, query=urlencode(query, doseq=True)).geturl()


def suwon_resident_autonomy_list_url(base_url: str, page: int) -> str:
    if page <= 1:
        return base_url
    return url_with_query(base_url, {"page": page, "block": ((page - 1) // 10) + 1})


def suwon_resident_autonomy_branch_name(dong_name: Any) -> str:
    text = clean_text(dong_name)
    if not text:
        return ""
    if any(token in text for token in ("주민자치센터", "행정복지센터", "문화센터", "센터")):
        return text
    if text.endswith("동"):
        return f"{text} 주민자치센터"
    return text


def suwon_resident_autonomy_row(
    target: CrawlTarget,
    current_url: str,
    pairs: dict[str, str],
    raw_url: str = "",
) -> dict[str, Any] | None:
    dong_name = clean_text(pairs.get("동명"))
    title = clean_text(pairs.get("강좌명") or pairs.get("프로그램명"))
    if not dong_name or not title or is_low_value_title(title):
        return None

    branch = suwon_resident_autonomy_branch_name(dong_name) or target.branch
    detail_url = clean_text(raw_url) or current_url
    schedule_raw = clean_text(pairs.get("교육일시") or pairs.get("교육시간") or pairs.get("시간"))
    capacity = clean_text(
        pairs.get("접수/모집")
        or pairs.get("접수/총정원/ 온라인/방문")
        or pairs.get("신청/정원")
        or pairs.get("정원")
    )
    capacity_current, capacity_total = parse_capacity_pair(capacity)
    status_text = clean_text(pairs.get("상태") or pairs.get("접수") or pairs.get("현황"))
    period = normalize_mixed_date_range(
        pairs.get("교육기간") or pairs.get("신청/교육기간") or pairs.get("강좌기간") or ""
    )
    apply_period = normalize_mixed_date_range(
        pairs.get("접수기간") or pairs.get("신청기간") or pairs.get("신청/교육기간") or ""
    )
    row = {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, detail_url, title, branch),
        "title": title,
        "branch": branch,
        "branch_code": stable_provider(target.provider[:32], branch),
        "category": "주민자치프로그램",
        "raw_url": detail_url,
        "application_url": detail_url if status_text and status_text not in {"마감", "종료"} else "",
        "status": normalize_status(status_text) or status_text,
        "fee": clean_text(pairs.get("수강료") or pairs.get("교육비")),
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": schedule_raw,
        "target": clean_text(pairs.get("대상") or pairs.get("교육대상")),
        "venue_name": branch,
        "room": branch,
        "capacity": capacity,
        "capacity_current": capacity_current,
        "capacity_total": capacity_total,
        "description": clean_text(" ".join(value for value in pairs.values() if clean_text(value))),
        "program_type": "강좌",
        "collection_category": "평생학습",
        "domain_category": "주민자치",
        "source_group": "lifelong_learning",
        "operator_type": "지자체/공공기관",
        "collection_type": "resident_autonomy_table",
        "raw_fields": {
            "parser": "suwon_resident_autonomy_table",
            "source_url": current_url,
            "pairs": pairs,
        },
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}


def collect_suwon_resident_autonomy_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    pages = 0
    detail_pages = 0
    pagination_detected = False

    for page in range(1, max(1, max_pages) + 1):
        current_url = suwon_resident_autonomy_list_url(target.url, page)
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_rows = 0
        for table in soup.find_all("table"):
            header_row = table.find("tr")
            headers = [clean_text(cell.get_text(" ", strip=True)) for cell in header_row.find_all(["th", "td"])] if header_row else []
            if "동명" not in headers or not any(header in headers for header in ("강좌명", "프로그램명")):
                continue
            for tr in table.find_all("tr")[1:]:
                cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
                if len(cells) < 2:
                    continue
                pairs = {headers[index]: cells[index] for index in range(min(len(headers), len(cells)))}
                link = tr.select_one("a[href]")
                raw_url = normalize_link(current_url, link.get("href") if link else None)
                row = suwon_resident_autonomy_row(target, current_url, pairs, raw_url)
                if not row:
                    continue
                row_key = clean_text(row.get("provider_course_id")) or clean_text(row.get("raw_url"))
                if row_key in seen:
                    continue
                seen.add(row_key)
                if raw_url and detail_pages < detail_limit:
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pages += 1
                        detail_text = clean_text(detail_soup.get_text(" ", strip=True))
                        if detail_text:
                            row["description"] = detail_text[:2500]
                    except Exception as exc:
                        logger.debug("suwon resident autonomy detail fetch failed %s: %s", raw_url, exc)
                rows.append(row)
                page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select("a[href*='page=']"))
        if page_rows == 0:
            break
        if not pagination_detected:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "suwon_resident_autonomy_table+detail", meta


def suwon_learning_pairs(node: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(node, "select"):
        return pairs
    for dl in node.select("dl"):
        key_node = dl.select_one("dt")
        value_node = dl.select_one("dd")
        key = clean_text(key_node.get_text(" ", strip=True) if key_node else "").rstrip(":：")
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if key and value:
            pairs[key] = value
    return pairs


def suwon_learning_card_title(strong: Any) -> tuple[str, str, str]:
    if not strong:
        return "", "", ""
    mode = ""
    status = ""
    parts: list[str] = []
    for child in strong.children:
        if getattr(child, "name", None) == "em":
            text = clean_text(child.get_text(" ", strip=True))
            if "type_a" in (child.get("class") or []):
                status = text
            elif not mode:
                mode = text
            continue
        text = clean_text(child.get_text(" ", strip=True) if hasattr(child, "get_text") else str(child))
        if text:
            parts.append(text)
    title = clean_text(" ".join(parts))
    return title, mode, status


def suwon_learning_status(value: Any) -> str:
    text = clean_text(value)
    if "수강신청" in text or "접수중" in text:
        return "접수중"
    if "대기" in text or "예정" in text:
        return "접수예정"
    if "마감" in text:
        return "접수마감"
    if "종료" in text:
        return "교육종료"
    return normalize_status(text) or text


def suwon_learning_capacity(node: Any) -> tuple[str, Optional[int], Optional[int]]:
    text = clean_text(node.get_text(" ", strip=True) if node else "")
    match = re.search(r"(\d{1,5})\s*명?\s*/\s*(\d{1,5})\s*명?", text.replace(",", ""))
    if match:
        current = int(match.group(1))
        total = int(match.group(2))
        return f"{current}/{total}", current, total
    current, total = parse_capacity_pair(text)
    return text, current, total


def suwon_learning_detail_description(s: requests.Session, url: str, timeout: int) -> str:
    soup = fetch_soup(s, url, timeout=timeout)
    content = soup.select_one(".contents")
    if not content:
        return ""
    lines = lines_from_soup(content)
    stop_labels = {"목록", "수강신청"}
    values: list[str] = []
    capture = False
    for line in lines:
        if line in stop_labels:
            continue
        if line == "문 의":
            break
        if capture:
            values.append(line)
        if line == "수강신청":
            capture = True
    return clean_text(" ".join(values))[:1200]


def collect_suwon_learning_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    seen: set[str] = set()
    pagination_detected = False

    for page in range(1, max(1, max_pages) + 1):
        page_url = suwon_learning_list_url(target.url, page)
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        cards = soup.select(".webzinBoardList .listBody > ul > li")
        if not cards:
            break
        page_rows = 0
        for card in cards:
            post = card.select_one(".postInfo")
            link = post.select_one("a[href*='01_lecture01_view']") if post else None
            strong = post.select_one("strong") if post else None
            title, mode, status_text = suwon_learning_card_title(strong)
            if not link or not title or is_low_value_title(title):
                continue
            raw_url = normalize_link(page_url, link.get("href"))
            idx = clean_text((parse_qs(urlparse(raw_url).query).get("idx") or [""])[0])
            key = idx or f"{page}:{title}"
            if key in seen:
                continue
            seen.add(key)
            pairs = suwon_learning_pairs(post)
            status = suwon_learning_status(status_text or clean_text(card.select_one(".tools button").get_text(" ", strip=True) if card.select_one(".tools button") else ""))
            capacity, capacity_current, capacity_total = suwon_learning_capacity(card.select_one(".tools .joinIn"))
            summary = ""
            for em in link.find_all("em", recursive=False):
                if "type_a" not in (em.get("class") or []):
                    summary = clean_text(em.get_text(" ", strip=True))
            description = summary
            if raw_url and detail_pages < detail_limit:
                try:
                    detail_description = suwon_learning_detail_description(s, raw_url, timeout)
                    if detail_description:
                        description = detail_description
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("suwon learning detail fetch failed %s: %s", raw_url, exc)
            period = normalize_mixed_date_range(pairs.get("교육기간", ""))
            row = {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, idx or raw_url, title, SUWON_LEARNING_BRANCH),
                "title": title,
                "branch": SUWON_LEARNING_BRANCH,
                "branch_code": stable_provider(target.provider[:32], SUWON_LEARNING_BRANCH),
                "raw_url": raw_url,
                "application_url": raw_url if status in {"접수중", "접수예정"} else "",
                "status": status,
                "period": period,
                "schedule_raw": clean_text(pairs.get("시간")),
                "target": clean_text(pairs.get("대상")),
                "fee": clean_text(pairs.get("수강료")),
                "instructor": clean_text(pairs.get("강사")),
                "capacity": capacity,
                "capacity_current": capacity_current,
                "capacity_total": capacity_total,
                "venue_name": SUWON_LEARNING_BRANCH if mode != "온라인" else "온라인",
                "description": description,
                "application_method_raw": mode,
                "program_type": "강좌",
                "collection_category": "평생학습",
                "domain_category": "평생학습",
                "source_group": "lifelong_learning",
                "operator_type": "지자체/공공기관",
                "collection_type": "static_html",
                "raw_fields": {
                    "parser": "suwon_learning_webzin_list+detail",
                    "page_url": page_url,
                    "idx": idx,
                    "mode": mode,
                    "pairs": pairs,
                },
            }
            rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            page_rows += 1
        pagination_detected = pagination_detected or bool(soup.select("a[href*='page=']"))
        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "suwon_learning_webzin_list+detail", meta


def same_site(left: str, right: str) -> bool:
    return urlparse(left).netloc.lower() == urlparse(right).netloc.lower()


def is_pagination_link(text: str, url: str) -> bool:
    haystack = f"{text} {url}".lower()
    if any(keyword in haystack for keyword in PAGINATION_KEYWORDS):
        return True
    if re.search(r"(?:page|pageIndex|pageNo|currentPage|currentPageNo|cpage|p)=\d+", url, re.IGNORECASE):
        return True
    return bool(re.fullmatch(r"\d{1,3}", clean_text(text)))


def is_relevant_link(text: str, url: str) -> bool:
    haystack = clean_text(f"{text} {url}").lower()
    parsed = urlparse(url)
    url_path_query = clean_text(f"{parsed.path} {parsed.query}").lower()
    if any(keyword.lower() in haystack for keyword in LINK_REJECT_KEYWORDS):
        return False
    return (
        any(keyword.lower() in haystack for keyword in COURSE_LINK_KEYWORDS)
        or any(keyword.lower() in haystack for keyword in MENU_DISCOVERY_KEYWORDS)
        or any(token in url_path_query for token in MENU_DISCOVERY_URL_TOKENS)
        or is_pagination_link(text, url)
    )


def is_reservation_discovery_link(text: str, url: str) -> bool:
    haystack = clean_text(f"{text} {url}").lower()
    if any(keyword.lower() in haystack for keyword in LINK_REJECT_KEYWORDS):
        return False
    return any(keyword.lower() in haystack for keyword in RESERVATION_DISCOVERY_KEYWORDS)


def menu_link_score(text: str, url: str) -> int:
    haystack = clean_text(f"{text} {url}").lower()
    parsed = urlparse(url)
    url_path_query = clean_text(f"{parsed.path} {parsed.query}").lower()
    score = 0
    for keyword in MENU_DISCOVERY_KEYWORDS:
        if keyword.lower() in haystack:
            score += 4
    for token in MENU_DISCOVERY_URL_TOKENS:
        if token in url_path_query:
            score += 2
    if is_reservation_discovery_link(text, url):
        score += 3
    if is_pagination_link(text, url):
        score -= 2
    return score


def discover_links(base_url: str, soup: BeautifulSoup) -> tuple[list[str], bool]:
    pagination_detected = False
    links: list[str] = []
    seen: set[str] = set()
    for node in soup.find_all(["a", "button"]):
        text = node_link_evidence(node)
        absolute = node_link_url(base_url, node)
        if not absolute or absolute in seen or not same_site(base_url, absolute):
            continue
        if is_pagination_link(text, absolute):
            pagination_detected = True
        if is_relevant_link(text, absolute):
            seen.add(absolute)
            links.append(absolute)

    # JavaScript-only "more" buttons cannot be followed with requests, but they
    # are still useful for the report because they identify pagination work.
    if soup.select(".btn-more, .more, button[class*='more'], a[class*='more']"):
        pagination_detected = True

    links.sort(key=lambda link: (0 if is_pagination_link("", link) else 1, -menu_link_score("", link), len(link), link))
    return links, pagination_detected


def discover_reservation_links(base_url: str, soup: BeautifulSoup) -> list[str]:
    links: list[str] = []
    seen: set[str] = set()
    for node in soup.find_all(["a", "button"]):
        text = node_link_evidence(node)
        absolute = node_link_url(base_url, node)
        if not absolute or absolute in seen or not same_site(base_url, absolute):
            continue
        if is_reservation_discovery_link(text, absolute):
            seen.add(absolute)
            links.append(absolute)
    links.sort(key=lambda link: (-menu_link_score("", link), len(link), link))
    return links


def merge_course_rows(base: dict[str, Any], detail: dict[str, Any]) -> dict[str, Any]:
    merged = dict(base)
    for key, value in detail.items():
        if value in (None, "", [], {}):
            continue
        if key == "title":
            current_title = clean_text(merged.get("title"))
            next_title = clean_text(value)
            if next_title and (not current_title or is_low_value_title(current_title)) and not is_low_value_title(next_title):
                merged["title"] = next_title
            continue
        if key == "raw_fields" and isinstance(value, dict):
            raw_fields = merged.get("raw_fields") if isinstance(merged.get("raw_fields"), dict) else {}
            merged["raw_fields"] = {**raw_fields, **value}
            continue
        if not merged.get(key):
            merged[key] = value
    return merged


def dedupe_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    deduped: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in rows:
        key = clean_text(
            row.get("provider_course_id")
            or "|".join(
                [
                    clean_text(row.get("provider")),
                    clean_text(row.get("raw_url")),
                    clean_text(row.get("title")),
                    clean_text(row.get("branch")),
                ]
            )
        )
        if not key or key in seen:
            continue
        seen.add(key)
        deduped.append(row)
    return deduped


GENERIC_LABELS = set(
    TITLE_KEYS
    + PERIOD_KEYS
    + APPLY_KEYS
    + SCHEDULE_KEYS
    + SCHEDULE_DATE_KEYS
    + TARGET_KEYS
    + FEE_KEYS
    + STATUS_KEYS
    + CAPACITY_KEYS
    + CAPACITY_CURRENT_KEYS
    + ROOM_KEYS
    + BRANCH_KEYS
    + VENUE_NAME_KEYS
    + VENUE_ADDRESS_KEYS
    + INSTRUCTOR_KEYS
    + DESCRIPTION_KEYS
    + APPLICATION_METHOD_KEYS
)


def generic_pairs_from_lines(lines: list[str]) -> dict[str, str]:
    pairs = labeled_lines_to_pairs(lines)
    pairs.update(sequence_lines_to_pairs(lines, GENERIC_LABELS))
    for line in lines:
        for separator in (":", "\uff1a", "\u2236"):
            if separator not in line:
                continue
            key, value = line.split(separator, 1)
            key = clean_text(key).rstrip(":")
            value = clean_text(value)
            if key and value and (key in GENERIC_LABELS or any(label in key for label in GENERIC_LABELS)):
                pairs.setdefault(key, value)
            break
    return pairs


def generic_title_from_cells(cells: list[str], fallback: str = "") -> str:
    candidates = [fallback, *cells]
    for value in candidates:
        title = clean_text(value)
        if not title or len(title) < 2 or len(title) > 140:
            continue
        if title.rstrip(":：").strip() in GENERIC_LABELS:
            continue
        if extract_target_text(title) == title:
            continue
        if re.fullmatch(r"[\d\s./:~()-]+", title):
            continue
        if is_low_value_title(title) or has_course_evidence(title):
            continue
        return title
    return clean_text(fallback)


def generic_period_from_evidence(evidence: str) -> str:
    text = clean_text(evidence)
    date = r"(?:20\d{2}[./-]\s*\d{1,2}[./-]\s*\d{1,2}|\d{4}\s*년\s*\d{1,2}\s*월\s*\d{1,2}\s*일)"
    match = re.search(date + r"\s*(?:~|-|부터|∼|～)\s*" + date, text)
    if match:
        return normalize_mixed_date_range(match.group(0)) or clean_text(match.group(0))
    match = re.search(r"(?:연중|상시)\s*(?:접수|운영|모집)?", text)
    return clean_text(match.group(0)) if match else ""


def generic_schedule_from_evidence(evidence: str) -> str:
    text = clean_text(evidence)
    time = r"\d{1,2}\s*:\s*\d{2}"
    match = re.search(r"(?:매주\s*)?(?:월|화|수|목|금|토|일)(?:[~\-,/·]\s*(?:월|화|수|목|금|토|일))*[^\d]{0,12}" + time + r"\s*(?:~|-|∼|～)\s*" + time, text)
    if match:
        return clean_text(match.group(0))
    match = re.search(time + r"\s*(?:~|-|∼|～)\s*" + time, text)
    return clean_text(match.group(0)) if match else ""


def chungnam_detail_title(lines: list[str], fallback: str) -> str:
    fallback = clean_text(fallback)
    if fallback and not is_low_value_title(fallback):
        return fallback
    for index, line in enumerate(lines):
        if line in {"공지사항", "교육정보"} and index + 1 < len(lines):
            candidate = clean_text(lines[index + 1])
            if candidate and len(candidate) <= 140 and not is_low_value_title(candidate):
                return candidate
    return fallback


def chungnam_labeled_value(text: str, labels: tuple[str, ...]) -> str:
    stops = (
        "접수기간",
        "교육일정",
        "교육기간",
        "교육내용",
        "교육대상",
        "교육비",
        "접수방법",
        "문의사항",
        "사업명",
        "교육과정명",
        "심사일",
        "이전글",
        "다음글",
    )
    for label in labels:
        value = extract_korean_labeled_value(text, label, stops)
        if value:
            return value
    return ""


def parse_chungnam_civil_detail(
    target: CrawlTarget,
    detail_url: str,
    soup: BeautifulSoup,
    fallback_title: str,
) -> dict[str, Any] | None:
    lines = lines_from_node(soup)
    full_text = clean_text(" ".join(lines))
    title = chungnam_detail_title(lines, fallback_title)
    if not title or is_low_value_title(title):
        return None
    if any(token in title for token in ("위탁업체", "대행업체", "진행업체", "수질검사", "최종합격자", "채용시험")):
        return None

    apply_period = normalize_mixed_date_range(chungnam_labeled_value(full_text, ("접수기간", "신청기간")))
    period = normalize_mixed_date_range(chungnam_labeled_value(full_text, ("교육일정", "교육기간")))
    target_text = chungnam_labeled_value(full_text, ("교육대상", "참가자격"))
    fee = chungnam_labeled_value(full_text, ("교육비", "참가비"))
    content = chungnam_labeled_value(full_text, ("교육내용", "공모내용"))

    if not period or not any([target_text, fee, content]):
        return None
    period = clean_text(period.rstrip("○ "))
    target_text = clean_text(target_text.rstrip("○ "))
    fee = clean_text(fee.rstrip("○ "))
    content = clean_text(content.rstrip("○ "))

    start_date, end_date = parse_date_range(period)
    status = normalize_status("", clean_text(f"{title} {full_text}"))
    row = {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, detail_url, title, target.branch),
        "title": title,
        "branch": target.branch,
        "branch_code": target.provider,
        "raw_url": detail_url,
        "application_url": detail_url if apply_period and status in {"OPEN", "WAITING", "SCHEDULED"} else "",
        "status": status,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": period,
        "target": target_text,
        "fee": fee,
        "description": clean_text(content or full_text[:1200]),
        "start_date": start_date,
        "end_date": end_date,
        "raw_fields": {"parser": "chungnam_civil_detail", "source_url": detail_url},
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}


def collect_chungnam_civil_education(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    pages = 0
    detail_pages = 0
    for page in range(1, max(1, max_pages) + 1):
        page_url = target.url if page == 1 else url_with_query(target.url, {"pageIndex": page})
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        links: list[tuple[str, str]] = []
        for node in soup.select("a.title, a[href*='/civileducation/bbs/']"):
            title = clean_text(node.get_text(" ", strip=True))
            href = node.get("href") if hasattr(node, "get") else ""
            detail_url = normalize_link(page_url, href)
            if not title or not detail_url or detail_url in seen:
                continue
            if "/civileducation/bbs/" not in detail_url or "/view.do" not in detail_url:
                continue
            if any(token in detail_url for token in ("/fileDown.", "/download", "fileSn=")):
                continue
            links.append((title, detail_url))

        for title, detail_url in links:
            if detail_limit > 0 and detail_pages >= detail_limit:
                break
            seen.add(detail_url)
            try:
                detail_soup = fetch_soup(s, detail_url, timeout=timeout)
            except Exception as exc:
                logger.debug("chungnam detail fetch failed %s: %s", detail_url, exc)
                continue
            detail_pages += 1
            row = parse_chungnam_civil_detail(target, detail_url, detail_soup, title)
            if row:
                rows.append(row)
        if detail_limit > 0 and detail_pages >= detail_limit:
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen),
        "pagination_detected": pages > 1,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "chungnam_civil_detail", meta


def is_ignored_generic_container(node: Any) -> bool:
    current = node
    depth = 0
    ignored_names = {"nav", "header", "footer", "aside"}
    ignored_tokens = (
        "gnb",
        "lnb",
        "snb",
        "menu",
        "nav",
        "footer",
        "header",
        "sitemap",
        "quick",
        "search",
        "breadcrumb",
        "side",
        "util",
        "login",
        "popup",
    )
    while current is not None and hasattr(current, "name"):
        if depth <= 5 and current.name in ignored_names:
            return True
        attrs: list[str] = []
        for key in ("id", "class", "role"):
            value = current.get(key) if hasattr(current, "get") else None
            if isinstance(value, list):
                attrs.extend(clean_text(item).lower() for item in value)
            elif value:
                attrs.append(clean_text(value).lower())
        attr_text = " ".join(attrs)
        if depth <= 5 and any(token in attr_text for token in ignored_tokens):
            return True
        current = current.parent if hasattr(current, "parent") else None
        depth += 1
    return False


def generic_application_url(raw_url: str, evidence: str, status: str) -> str:
    haystack = clean_text(f"{raw_url} {evidence}").lower()
    if any(
        token in haystack
        for token in (
            "apply",
            "reserve",
            "reservation",
            "yeyak",
            "sugang",
            "ticket",
            "\uc2e0\uccad",
            "\uc811\uc218",
            "\uc608\uc57d",
            "\uc608\ub9e4",
            "\uad00\ub78c",
            "\uc804\uc2dc",
            "\uacf5\uc5f0",
        )
    ):
        return raw_url
    if status in {"OPEN", "WAITING", "SCHEDULED"} and raw_url:
        return raw_url
    return ""


def build_generic_course_row(
    provider: str,
    branch: str,
    page_url: str,
    pairs: dict[str, str],
    evidence: str,
    fallback_title: str,
    link_url: str,
    parser_name: str,
) -> dict[str, Any] | None:
    title = first_by_keys(pairs, TITLE_KEYS) or clean_text(fallback_title)
    evidence = clean_text(evidence)
    if not title or is_low_value_title(title) or is_navigation_title(title, evidence):
        return None
    status_text = first_by_keys(pairs, STATUS_KEYS)
    if not has_course_evidence(evidence) and not status_has_course_state(status_text):
        return None

    navigable_url = clean_text(link_url) or page_url
    period = first_by_keys(pairs, PERIOD_KEYS) or generic_period_from_evidence(evidence)
    apply_period = first_by_keys(pairs, APPLY_KEYS)
    schedule_raw = first_by_keys(pairs, SCHEDULE_KEYS) or first_by_keys(pairs, SCHEDULE_DATE_KEYS) or generic_schedule_from_evidence(evidence)
    target_text = first_by_keys(pairs, TARGET_KEYS) or extract_target_text(title) or extract_target_text(evidence)
    fee = first_by_keys(pairs, FEE_KEYS)
    if not fee:
        fee_match = re.search(r"\d[\d,]*\s*\uc6d0", evidence)
        fee = fee_match.group(0) if fee_match else ""
    status = normalize_status(status_text, evidence)
    room = first_by_keys(pairs, ROOM_KEYS)
    row_branch = first_by_keys(pairs, BRANCH_KEYS) or branch
    venue_name = first_by_keys(pairs, VENUE_NAME_KEYS) or room
    venue_address = first_by_keys(pairs, VENUE_ADDRESS_KEYS)
    instructor = first_by_keys(pairs, INSTRUCTOR_KEYS)
    description = first_by_keys(pairs, DESCRIPTION_KEYS)
    capacity_value = first_by_keys(pairs, CAPACITY_KEYS)
    capacity_current, capacity_total = parse_capacity_pair(capacity_value)
    if capacity_total is None:
        capacity_total = parse_capacity_number(capacity_value)
    current_value = first_by_keys(pairs, CAPACITY_CURRENT_KEYS)
    current_from_field, total_from_field = parse_capacity_pair(current_value)
    if current_from_field is not None:
        capacity_current = current_from_field
    if total_from_field is not None:
        capacity_total = total_from_field
    start_date, end_date = parse_date_range(period)
    raw_url = navigable_url
    if not clean_text(link_url):
        raw_url = stable_list_item_url(
            page_url,
            provider,
            title,
            row_branch,
            period,
            apply_period,
            schedule_raw,
            venue_name,
        )

    row = {
        "provider": provider,
        "provider_course_id": stable_course_id(provider, raw_url, title, row_branch),
        "title": title,
        "branch": row_branch,
        "branch_code": provider,
        "raw_url": raw_url,
        "application_url": generic_application_url(navigable_url, evidence, status),
        "status": status,
        "period": period,
        "apply_period": apply_period,
        "schedule_raw": schedule_raw,
        "target": target_text,
        "fee": fee,
        "room": room,
        "venue_name": venue_name,
        "venue_address": venue_address,
        "instructor": instructor,
        "description": description or evidence[:500],
        "program_type": infer_program_type(title, first_by_keys(pairs, TITLE_KEYS), evidence, navigable_url),
        "start_date": start_date,
        "end_date": end_date,
        "capacity_total": capacity_total,
        "capacity_current": capacity_current,
        "raw_fields": {"parser": parser_name, "pairs": pairs, "source_url": page_url},
    }
    return {key: value for key, value in row.items() if value not in (None, "", [], {})}


def parse_generic_table_courses(provider: str, branch: str, url: str, soup: BeautifulSoup) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    page_title = first_title_candidate(soup)
    for table in soup.find_all("table"):
        table_text = clean_text(table.get_text(" ", strip=True))
        table_pairs = pairs_from_tables(table)
        # A conventional list table has one header row and many independent
        # course rows.  Treating the entire table as a detail record collapses
        # it into one bogus course whose title is a header such as "\ud559\uc2b5\uc7a5\uc18c".
        # Whole-table label/value parsing is only appropriate for detail tables.
        is_list_table = bool(table.select("thead th")) and bool(table.select("tbody tr td"))
        if is_ignored_generic_container(table) and not (table_pairs and has_course_evidence(table_text)):
            continue
        table_lines = lines_from_node(table)
        if table_pairs and has_course_evidence(table_text) and not is_list_table:
            table_row = build_generic_course_row(
                provider,
                branch,
                url,
                table_pairs,
                table_text,
                first_by_keys(table_pairs, TITLE_KEYS) or generic_title_from_cells(table_lines, page_title),
                "",
                "generic_table",
            )
            if table_row:
                rows.append(table_row)
                continue
        headers: list[str] = []
        for tr in table.find_all("tr"):
            cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
            cells = [cell for cell in cells if cell]
            if not cells:
                continue
            th_count = len(tr.find_all("th"))
            td_count = len(tr.find_all("td"))
            if th_count and not td_count:
                headers = cells
                continue
            pairs: dict[str, str] = {}
            if headers and len(cells) >= 2:
                pairs.update({headers[index]: cells[index] for index in range(min(len(headers), len(cells)))})
            elif th_count and td_count and len(cells) >= 2:
                for index in range(0, len(cells) - 1, 2):
                    if len(cells[index]) <= 30:
                        pairs[cells[index]] = cells[index + 1]
            link = tr.find("a", href=True)
            link_text = clean_text(link.get_text(" ", strip=True)) if link else ""
            link_url = normalize_link(url, link.get("href") if link else None)
            fallback_title = generic_title_from_cells(cells, link_text or page_title)
            evidence = clean_text(" ".join(cells))
            row = build_generic_course_row(
                provider,
                branch,
                url,
                pairs,
                evidence,
                fallback_title,
                link_url,
                "generic_table",
            )
            if row:
                rows.append(row)
    return rows


def parse_generic_card_courses(provider: str, branch: str, url: str, soup: BeautifulSoup) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    selectors = "li, article, .item, .program, .course, .lecture, .card, .board-item"
    page_title = first_title_candidate(soup)
    for node in soup.select(selectors)[:300]:
        if is_ignored_generic_container(node):
            continue
        if node.find("table"):
            continue
        evidence = clean_text(node.get_text(" ", strip=True))
        if not evidence or len(evidence) > 1800 or not has_course_evidence(evidence):
            continue
        lines = [clean_text(part) for part in node.get_text("\n", strip=True).splitlines() if clean_text(part)]
        pairs = generic_pairs_from_lines(lines)
        heading = node.find(["h1", "h2", "h3", "h4", "strong", "b", "a"])
        heading_title = clean_text(heading.get_text(" ", strip=True)) if heading else ""
        fallback_title = generic_title_from_cells(lines, heading_title or page_title)
        link = node.find("a", href=True)
        link_url = normalize_link(url, link.get("href") if link else None)
        row = build_generic_course_row(
            provider,
            branch,
            url,
            pairs,
            evidence,
            fallback_title,
            link_url,
            "generic_card",
        )
        if row:
            rows.append(row)
    return rows


def parse_all_courses(provider: str, branch: str, url: str, soup: BeautifulSoup) -> tuple[list[dict[str, Any]], str]:
    rows = parse_generic_table_courses(provider, branch, url, soup)
    rows.extend(parse_generic_card_courses(provider, branch, url, soup))
    rows = dedupe_rows(rows)
    parser_names = sorted(
        {
            clean_text((row.get("raw_fields") or {}).get("parser"))
            for row in rows
            if isinstance(row.get("raw_fields"), dict) and clean_text((row.get("raw_fields") or {}).get("parser"))
        }
    )
    return rows, "+".join(parser_names) if parser_names else "none"


def generic_row_quality_score(row: dict[str, Any]) -> int:
    title = clean_text(row.get("title"))
    score = 0
    for key in ("period", "apply_period", "schedule_raw", "target", "fee", "venue_name", "venue_address"):
        if clean_text(row.get(key)):
            score += 3
    if clean_text(row.get("description")):
        score += 1
    if status_has_course_state(row.get("status", "")):
        score += 2
    raw_url = clean_text(row.get("raw_url"))
    source_url = clean_text((row.get("raw_fields") or {}).get("source_url"))
    if raw_url and raw_url != source_url:
        score += 2
    if re.search(r"/view|\bview\b|lecDetSn|class|course|edu", raw_url, re.IGNORECASE):
        score += 2
    if is_low_value_title(title) or is_navigation_title(title, clean_text(row.get("description"))):
        score -= 20
    if len(title) <= 1:
        score -= 10
    return score


def is_generic_registration_form_row(row: dict[str, Any]) -> bool:
    text = clean_text(" ".join(clean_text(row.get(key)) for key in ("title", "description", "raw_url")))
    if not text:
        return False
    form_markers = (
        "\ub4f1\ub85d/\uc218\uc815/\uc2e0\uccad\ud558\uae30",
        "\uc2b9\uc778\uc5ec\ubd80",
        "\ub178\ucd9c\uc5ec\ubd80",
        "\uc138\ubd80\ubd84\ub958",
        "\ucca8\ubd80\ud30c\uc77c",
    )
    marker_count = sum(1 for marker in form_markers if marker in text)
    if marker_count >= 2:
        return True
    raw_url = clean_text(row.get("raw_url")).lower()
    return "mode=w" in raw_url and marker_count >= 1


def generic_row_has_course_shape(row: dict[str, Any]) -> bool:
    """Require either structured course fields or a course-like detail URL."""

    if any(
        clean_text(row.get(key))
        for key in (
            "period",
            "apply_period",
            "schedule_raw",
            "target",
            "fee",
            "venue_name",
            "venue_address",
            "instructor",
            "capacity_total",
            "capacity_current",
        )
    ):
        return True
    raw_url = clean_text(row.get("raw_url"))
    source_url = clean_text((row.get("raw_fields") or {}).get("source_url"))
    if not raw_url or raw_url == source_url:
        return False
    return bool(
        re.search(
            r"(?:view|detail|program|lecture|lctre|course|class|edu)",
            raw_url,
            re.IGNORECASE,
        )
    )


def filter_generic_miscollected_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    filtered: list[dict[str, Any]] = []
    for row in rows:
        title = clean_text(row.get("title"))
        if not title or is_low_value_title(title):
            continue
        if semantic_course_title_rejection_reason(title):
            continue
        if is_generic_registration_form_row(row):
            continue
        if not generic_row_has_course_shape(row):
            continue
        evidence = clean_text(
            " ".join(
                clean_text(row.get(key))
                for key in (
                    "title",
                    "period",
                    "apply_period",
                    "schedule_raw",
                    "target",
                    "fee",
                    "status",
                    "description",
                    "application_url",
                    "raw_url",
                )
            )
        )
        if has_course_evidence(evidence) or status_has_course_state(row.get("status", "")):
            filtered.append(row)

    return sorted(filtered, key=generic_row_quality_score, reverse=True)


def eshare_branch_code(provider: str, branch: str, address: str) -> str:
    source = "|".join([provider, clean_text(branch), clean_text(address)])
    digest = hashlib.sha1(source.encode("utf-8")).hexdigest()[:12].upper()
    slug = re.sub(r"[^A-Za-z0-9\uac00-\ud7a3]+", "_", clean_text(branch)).strip("_")[:28]
    return f"{slug}_{digest}"[:50] if slug else f"{provider}_{digest}"[:50]


def eshare_clean_place(value: Any) -> str:
    text = clean_text(value)
    text = re.sub(r"\s*\uc9c0\ub3c4\ubcf4\uae30\s*$", "", text)
    return clean_text(text)


def eshare_pairs_from_tables(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}

    # The detail table exposes its semantic label on each value cell. Using it
    # avoids shifting every later field when an optional value cell is empty.
    for cell in soup.select("td[data-cell-header]"):
        label = clean_text(cell.get("data-cell-header"))
        if not label:
            continue
        value = clean_text(cell.get_text(" ", strip=True))
        if label not in pairs or (value and not pairs[label]):
            pairs[label] = value

    for table in soup.find_all("table"):
        for tr in table.find_all("tr"):
            cells = tr.find_all(["th", "td"], recursive=False)
            for index, cell in enumerate(cells):
                if cell.name != "th":
                    continue
                value_cell = next(
                    (candidate for candidate in cells[index + 1 :] if candidate.name == "td"),
                    None,
                )
                if value_cell is None:
                    continue
                label = clean_text(cell.get_text(" ", strip=True))
                value = clean_text(value_cell.get_text(" ", strip=True))
                if label and len(label) <= 30 and (label not in pairs or (value and not pairs[label])):
                    pairs[label] = value
    return pairs


def eshare_status_from_detail(soup: BeautifulSoup, fallback: str) -> str:
    text = clean_text(soup.get_text(" ", strip=True))
    for token in (
        "\uc624\ud508\uc608\uc815",
        "\uc608\uc57d\uac00\ub2a5",
        "\uc608\uc57d\ubd88\uac00",
        "\uc811\uc218\uc911",
        "\uc811\uc218\ub9c8\uac10",
        "\ub9c8\uac10",
    ):
        if token in text:
            return token
    return fallback


def eshare_description_from_row(title: str, info_pairs: dict[str, str], category_parts: list[str]) -> str:
    parts = [title]
    for key in ("\uc608\uc57d\ubc29\ubc95", "\uc2ec\uc0ac\uc5ec\ubd80", "\uc774\uc6a9\uc694\uae08"):
        if info_pairs.get(key):
            parts.append(f"{key}: {info_pairs[key]}")
    if category_parts:
        parts.append(" / ".join(category_parts))
    return clean_text(" | ".join(part for part in parts if part))


ESHARE_SEARCH_URL = (
    "https://www.eshare.go.kr/UserPortal/adv/resources/"
    "AdvEsSearchResourcesMainView.do?rsrcClsCd=040000"
)
ESHARE_LIST_URL = (
    "https://www.eshare.go.kr/UserPortal/adv/resources/"
    "AdvEsSearchResourcesList.do"
)
ESHARE_DETAIL_BASE = "https://www.eshare.go.kr/UserPortal/Upv/UprResrcEdu/index.do"
ESHARE_LIST_PAGE_SIZE = 500
ESHARE_MAX_LIST_ROWS = 5_000
ESHARE_SCHEDULE_PROBE_LIMIT = 7
ESHARE_REALTIME_RESERVATION = "\uc2e4\uc2dc\uac04\uc608\uc57d"
ESHARE_TARGET_FALLBACK = "\uc81c\uacf5\uae30\uad00 \ubb38\uc758"


def eshare_calendar_window(today: date) -> tuple[date, date]:
    start = today.replace(day=1)
    if today.month == 12:
        next_month = date(today.year + 1, 1, 1)
    else:
        next_month = date(today.year, today.month + 1, 1)
    end = next_month.replace(day=calendar.monthrange(next_month.year, next_month.month)[1])
    return start, end


def eshare_json_list_response(
    response: requests.Response,
    *,
    endpoint: str,
) -> list[dict[str, Any]]:
    response.raise_for_status()
    payload = response.json()
    if not isinstance(payload, list) or any(not isinstance(item, dict) for item in payload):
        raise RuntimeError(f"ESHARE {endpoint} response is not a JSON object list")
    return payload


def eshare_open_calendar_entries(
    payload: list[dict[str, Any]],
    *,
    today: date,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    today_text = today.isoformat()
    for item in payload:
        date_text = clean_text(item.get("date"))
        try:
            available_date = date.fromisoformat(date_text)
        except ValueError:
            continue
        if available_date < today:
            continue
        if clean_text(item.get("useYn")).upper() not in {"Y", "S", "E"}:
            continue
        if clean_text(item.get("exclShareYn")).upper() == "Y":
            continue
        if clean_text(item.get("magamcheck")).upper() == "Y":
            continue
        if clean_text(item.get("excelShareMsg")):
            continue
        if clean_text(item.get("drawYn")).upper() == "Y":
            apply_start = clean_text(item.get("applsdtm"))[:10]
            apply_end = clean_text(item.get("appledtm"))[:10]
            if apply_start and apply_end and not (apply_start <= today_text <= apply_end):
                continue
        rows.append(item)
    return sorted(rows, key=lambda item: clean_text(item.get("date")))


def eshare_open_schedule_slots(payload: list[dict[str, Any]]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for item in payload:
        capacity = parse_capacity_number(item.get("useCapa"))
        current = parse_capacity_number(item.get("useCapaQty"))
        start_time = re.sub(r"\D", "", clean_text(item.get("usePsblBgnTm")))
        end_time = re.sub(r"\D", "", clean_text(item.get("usePsblEndTm")))
        if capacity is None or current is None or current >= capacity:
            continue
        if len(start_time) != 4 or len(end_time) != 4:
            continue
        rows.append(item)
    return rows


def eshare_schedule_text(slots: list[dict[str, Any]]) -> str:
    values: list[str] = []
    for slot in slots:
        start_time = re.sub(r"\D", "", clean_text(slot.get("usePsblBgnTm")))
        end_time = re.sub(r"\D", "", clean_text(slot.get("usePsblEndTm")))
        value = f"{start_time[:2]}:{start_time[2:]}~{end_time[:2]}:{end_time[2:]}"
        if value not in values:
            values.append(value)
    return " / ".join(values)


def eshare_period_text(entries: list[dict[str, Any]]) -> str:
    dates = [clean_text(item.get("date")) for item in entries if clean_text(item.get("date"))]
    if not dates:
        return ""
    if len(dates) == 1:
        return dates[0]
    return f"{dates[0]} ~ {dates[-1]} (\uc608\uc57d \uac00\ub2a5 {len(dates)}\uc77c)"


def collect_eshare_public_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
    *,
    session_factory: Callable[[], requests.Session] = session,
    today: Optional[date] = None,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session_factory()
    s.headers.update(
        {
            "Referer": ESHARE_SEARCH_URL,
            "X-Requested-With": "XMLHttpRequest",
        }
    )

    today_value = today or datetime.now().date()
    calendar_start, calendar_end = eshare_calendar_window(today_value)
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    list_pages = 0
    total_rows = 0
    cards_by_id: dict[str, Any] = {}

    for page_index in range(max(1, max_pages)):
        payload = {
            "instt_code": "",
            "curr_page_no": str(page_index),
            "rows_per_page": str(ESHARE_LIST_PAGE_SIZE),
            "searchConvList": "",
            "searchSbclsCd": "",
            "searchMnclsCd": "",
            "sido": "",
            "sigungu": "",
            "searchFreeYn": "",
            "searchIntnetRsrvPsblYn": "Y",
            "searchApplAprvObjYn": "",
            "searchDate": today_value.isoformat(),
            "searchRsrcNm": "",
            "rsrcClsCd": "040000",
            "latitude": "",
            "longitude": "",
        }
        response = s.post(ESHARE_LIST_URL, data=payload, timeout=timeout)
        response.raise_for_status()
        list_pages += 1
        soup = BeautifulSoup(response.text, "html.parser")
        cards = soup.select("li.item")
        if not cards:
            break

        total_input = soup.select_one("#tot_rows_cnt")
        if total_input and clean_text(total_input.get("value")):
            total_rows = parse_capacity_number(total_input.get("value")) or total_rows
        if total_rows > ESHARE_MAX_LIST_ROWS:
            raise RuntimeError(
                f"ESHARE online result count {total_rows} exceeds reviewed cap "
                f"{ESHARE_MAX_LIST_ROWS}"
            )
        previous_count = len(cards_by_id)
        for card in cards:
            link_node = card.select_one("[data-rsrcno]")
            rsrc_no = clean_text(link_node.get("data-rsrcno") if link_node else "")
            if not re.fullmatch(r"[A-Za-z0-9_-]{4,80}", rsrc_no):
                raise RuntimeError("ESHARE list contains a missing or invalid rsrc_no")
            cards_by_id.setdefault(rsrc_no, card)
        if total_rows and len(cards_by_id) >= total_rows:
            break
        if len(cards) < ESHARE_LIST_PAGE_SIZE:
            break
        if len(cards_by_id) == previous_count:
            raise RuntimeError("ESHARE pagination repeated a page before completion")
    if total_rows and len(cards_by_id) < total_rows:
        raise RuntimeError(
            f"ESHARE list pagination incomplete: collected={len(cards_by_id)} "
            f"declared={total_rows} max_pages={max_pages}"
        )

    realtime_cards: list[tuple[str, Any]] = []
    external_rows = 0
    unsupported_rows = 0
    for rsrc_no, card in cards_by_id.items():
        category_parts = [
            clean_text(span.get_text(" ", strip=True))
            for span in card.select(".category span")
            if clean_text(span.get_text(" ", strip=True))
        ]
        reservation_type = category_parts[2] if len(category_parts) >= 3 else ""
        if reservation_type == ESHARE_REALTIME_RESERVATION:
            realtime_cards.append((rsrc_no, card))
        elif "\uc678\ubd80\uc608\uc57d" in reservation_type:
            external_rows += 1
        else:
            unsupported_rows += 1

    if detail_limit <= 0 or len(realtime_cards) > detail_limit:
        raise RuntimeError(
            f"ESHARE realtime detail scope {len(realtime_cards)} exceeds "
            f"detail_limit={detail_limit}"
        )

    no_available_dates = 0
    no_open_schedule = 0
    calendar_requests = 0
    schedule_requests = 0
    incomplete_required = 0

    for rsrc_no, card in realtime_cards:
        title_node = card.select_one(".rsrcNmWrap strong")
        title = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
        if not title:
            raise RuntimeError(f"ESHARE resource {rsrc_no} has no title")
        detail_url = f"{ESHARE_DETAIL_BASE}?{urlencode({'rsrc_no': rsrc_no})}"

        info_pairs: dict[str, str] = {}
        for item in card.select(".infoList li"):
            label_node = item.find("strong")
            label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
            value = clean_text(item.get_text(" ", strip=True))
            if label:
                info_pairs[label] = clean_text(value.replace(label, "", 1))

        category_parts = [
            clean_text(span.get_text(" ", strip=True))
            for span in card.select(".category span")
            if clean_text(span.get_text(" ", strip=True))
        ]
        region_text = " ".join(category_parts[:2])
        reservation_type = category_parts[2] if len(category_parts) >= 3 else ""

        detail_soup = fetch_soup(s, detail_url, timeout=timeout)
        detail_pages += 1
        detail_pairs = eshare_pairs_from_tables(detail_soup)
        merged_pairs = {**info_pairs, **detail_pairs}

        calendar_url = (
            f"https://www.eshare.go.kr/UserPortal/Upv/{rsrc_no}/"
            "selectCpsResvExclShareCalendar.do"
        )
        calendar_payload = eshare_json_list_response(
            s.post(
                calendar_url,
                data={
                    "startDate": calendar_start.isoformat(),
                    "endDate": calendar_end.isoformat(),
                },
                timeout=timeout,
            ),
            endpoint="calendar",
        )
        calendar_requests += 1
        available_entries = eshare_open_calendar_entries(
            calendar_payload,
            today=today_value,
        )
        if not available_entries:
            no_available_dates += 1
            continue

        open_slots: list[dict[str, Any]] = []
        schedule_date = ""
        schedule_url = (
            f"https://www.eshare.go.kr/UserPortal/Upv/{rsrc_no}/"
            "searchCpsGnrResvSchedDetlQty.do"
        )
        for available_entry in available_entries[:ESHARE_SCHEDULE_PROBE_LIMIT]:
            candidate_date = clean_text(available_entry.get("date"))
            slot_payload = eshare_json_list_response(
                s.post(
                    schedule_url,
                    data={"searchDate": candidate_date},
                    timeout=timeout,
                ),
                endpoint="schedule",
            )
            schedule_requests += 1
            open_slots = eshare_open_schedule_slots(slot_payload)
            if open_slots:
                schedule_date = candidate_date
                break
        if not open_slots:
            no_open_schedule += 1
            continue

        detail_title = first_by_keys(merged_pairs, ("\uc790\uc6d0 \uba85\uce6d",))
        title = detail_title or title
        branch = (
            first_by_keys(merged_pairs, ("\uc81c\uacf5 \uae30\uad00", "\uc81c\uacf5\uae30\uad00"))
            or region_text
            or target.branch
        )
        place = eshare_clean_place(
            first_by_keys(
                merged_pairs,
                ("\uc7a5\uc18c/\uc704\uce58", "\uc7a5\uc18c", "\uc704\uce58"),
            )
        )
        fee = (
            first_by_keys(merged_pairs, ("\uc774\uc6a9 \uc694\uae08", "\uc774\uc6a9\uc694\uae08"))
            or info_pairs.get("\uc774\uc6a9\uc694\uae08", "")
        )
        period = eshare_period_text(available_entries)
        schedule_raw = eshare_schedule_text(open_slots)
        target_text = (
            first_by_keys(merged_pairs, ("\uc774\uc6a9 \ub300\uc0c1", "\uc774\uc6a9\ub300\uc0c1"))
            or ESHARE_TARGET_FALLBACK
        )
        phone = first_by_keys(merged_pairs, ("\uc608\uc57d \ubb38\uc758", "\uc608\uc57d\ubb38\uc758"))
        category_raw = (
            first_by_keys(merged_pairs, ("\uc790\uc6d0 \ubd84\ub958", "\uc790\uc6d0\ubd84\ub958"))
            or "\uad50\uc721\u00b7\uac15\uc88c"
        )
        application_method = (
            first_by_keys(merged_pairs, ("\uc608\uc57d \ubc29\ubc95", "\uc608\uc57d\ubc29\ubc95"))
            or info_pairs.get("\uc608\uc57d\ubc29\ubc95", "")
        )
        capacity_total = max(
            (
                parse_capacity_number(slot.get("useCapa")) or 0
                for slot in open_slots
            ),
            default=0,
        )
        capacity_current = max(
            (
                parse_capacity_number(slot.get("useCapaQty")) or 0
                for slot in open_slots
            ),
            default=0,
        )
        required = (title, target_text, fee, period, place, category_raw, schedule_raw)
        if any(not clean_text(value) for value in required):
            incomplete_required += 1
            continue

        description = eshare_description_from_row(title, merged_pairs, category_parts)
        description = clean_text(
            f"{description} | \uc608\uc57d \uac00\ub2a5\uc77c: {period} | "
            f"\uc2dc\uac04: {schedule_raw}"
        )

        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, detail_url, title, branch),
                "title": title,
                "branch": branch,
                "branch_code": eshare_branch_code(target.provider, branch, place),
                "raw_url": detail_url,
                "application_url": detail_url,
                "status": "\uc608\uc57d\uac00\ub2a5",
                "period": period,
                "apply_period": "\uc0c1\uc2dc\uc811\uc218",
                "schedule_raw": schedule_raw,
                "target": target_text,
                "fee": fee,
                "address": place,
                "venue_address": place,
                "phone": phone,
                "capacity_total": capacity_total or None,
                "capacity_current": capacity_current,
                "category": category_raw,
                "category_raw": category_raw,
                "collection_category": target.extra.get("collection_category") or "\uacf5\uacf5\uc608\uc57d",
                "domain_category": target.extra.get("domain_category") or "\uad50\uc721\u00b7\uac15\uc88c",
                "application_method_raw": application_method,
                "application_type": "ONLINE_RESERVATION",
                "description": description,
                "raw_fields": {
                    "parser": "eshare_realtime_calendar",
                    "rsrc_no": rsrc_no,
                    "list_pairs": info_pairs,
                    "detail_pairs": detail_pairs,
                    "category_parts": category_parts,
                    "available_dates": [
                        clean_text(item.get("date"))
                        for item in available_entries
                    ],
                    "schedule_date": schedule_date,
                    "open_schedule_slots": open_slots,
                    "list_url": ESHARE_LIST_URL,
                },
            }
        )

    meta = {
        "pages": list_pages,
        "detail_pages": detail_pages,
        "discovered_links": len(cards_by_id),
        "reservation_discovery_links": len(realtime_cards),
        "reservation_fallback_pages": 0,
        "pagination_detected": total_rows > ESHARE_LIST_PAGE_SIZE,
        "recursion_depth": 0,
        "total_rows": total_rows,
        "realtime_rows": len(realtime_cards),
        "excluded_external_rows": external_rows,
        "excluded_unsupported_rows": unsupported_rows,
        "no_available_dates": no_available_dates,
        "no_open_schedule": no_open_schedule,
        "incomplete_required": incomplete_required,
        "calendar_requests": calendar_requests,
        "schedule_requests": schedule_requests,
        "no_current_data": bool(cards_by_id) and not rows,
        "no_current_reason": (
            "official realtime reservation calendars have no open course slots"
            if cards_by_id and not rows
            else ""
        ),
    }
    return dedupe_rows(rows), "eshare_realtime_calendar", meta


SJECAMPUS_LIST_BASE = "https://sjecampus.com/sugang/student/consent_list.php"
SJECAMPUS_COURSE_TYPES = (
    ("H1", "\uacf5\ub3d9\uad50\uc721\uacfc\uc815\u2160"),
    ("H2", "\uacf5\ub3d9\uad50\uc721\uacfc\uc815\u2161"),
    ("H9", "\uc628\uc138\uc885\ud559\uad50(\uc628\ub77c\uc778\uc218\uc5c5)"),
    ("HB", "\uace0\uad50-\ub300\ud559 \ubc0f \uc9c0\uc5ed\ud559\uc2b5\uc7a5 \uc5f0\uacc4 \uacf5\ub3d9\uad50\uc721\uacfc\uc815"),
    ("HD", "\uafc8\uafb8\uc138(\uc885) \uc9c1\uc5c5\uad50\uc721 \ucd95\uc81c"),
)
SJECAMPUS_DEFAULT_BRANCH = "\uc138\uc885\ud2b9\ubcc4\uc790\uce58\uc2dc\uad50\uc721\uccad"


def sjecampus_list_url(course_type: str) -> str:
    return f"{SJECAMPUS_LIST_BASE}?{urlencode({'s_LB_type': course_type})}"


def sjecampus_response_text(response: requests.Response) -> str:
    data = response.content
    if data.startswith(b"\x1f\x8b"):
        data = bounded_gzip_decompress(data)
    encodings = ["euc-kr", "cp949", response.encoding or "", response.apparent_encoding or "", "utf-8"]
    for encoding in dict.fromkeys(encoding for encoding in encodings if encoding):
        try:
            return data.decode(encoding)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", errors="replace")


def sjecampus_fetch_soup(s: requests.Session, url: str, timeout: int) -> BeautifulSoup:
    response = s.get(url, timeout=timeout)
    response.raise_for_status()
    return BeautifulSoup(sjecampus_response_text(response), "html.parser")


def sjecampus_pairs_from_detail(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for tr in soup.find_all("tr"):
        cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"], recursive=False)]
        cells = [cell for cell in cells if cell]
        if len(cells) == 2 and len(cells[0]) <= 30:
            pairs.setdefault(cells[0], cells[1])
        elif len(cells) >= 4:
            for index in range(0, len(cells) - 1, 2):
                key = cells[index]
                value = cells[index + 1]
                if key and value and len(key) <= 30:
                    pairs.setdefault(key, value)
    return pairs


def sjecampus_row_values(course_type: str, cells: list[str]) -> dict[str, str]:
    if course_type == "H1" and len(cells) >= 9:
        return {
            "serial": cells[0],
            "branch": cells[1],
            "title": cells[2],
            "category": cells[3],
            "target": cells[4],
            "schedule_raw": cells[5],
            "instructor": cells[6],
            "capacity_total": cells[7],
            "capacity_current": cells[8],
            "venue_name": cells[1],
        }
    if course_type in {"H2", "H9"} and len(cells) >= 9:
        return {
            "serial": cells[0],
            "category": cells[1],
            "title": cells[2],
            "target": cells[3],
            "schedule_raw": cells[4],
            "venue_name": cells[5],
            "branch": cells[5],
            "instructor": cells[6],
            "capacity_total": cells[7],
            "capacity_current": cells[8],
        }
    if course_type == "HB" and len(cells) >= 8:
        return {
            "serial": cells[0],
            "title": cells[1],
            "venue_name": cells[2],
            "branch": cells[2] or SJECAMPUS_DEFAULT_BRANCH,
            "target": cells[3],
            "schedule_raw": cells[4],
            "instructor": cells[5],
            "capacity_total": cells[6],
            "capacity_current": cells[7],
        }
    if course_type == "HD" and len(cells) >= 5:
        return {
            "serial": cells[0],
            "schedule_raw": cells[1],
            "title": cells[2],
            "capacity_total": cells[3],
            "capacity_current": cells[4],
            "branch": SJECAMPUS_DEFAULT_BRANCH,
            "venue_name": SJECAMPUS_DEFAULT_BRANCH,
        }
    return {}


def sjecampus_status(capacity_total: Any, capacity_current: Any) -> str:
    total = parse_capacity_number(capacity_total)
    current = parse_capacity_number(capacity_current)
    if total and current is not None and current >= total:
        return "\uc811\uc218\ub9c8\uac10"
    return "\uc811\uc218\uc911"


def sjecampus_description(
    type_label: str,
    values: dict[str, str],
    detail_pairs: dict[str, str],
) -> str:
    parts = [type_label]
    for key in ("category", "venue_name", "target", "instructor"):
        value = clean_text(values.get(key))
        if value:
            parts.append(value)
    profile = first_by_keys(detail_pairs, ("\uac15\uc0ac\ud504\ub85c\ud544", "\ube44\uace0", "\uc124\uba85"))
    if profile:
        parts.append(profile)
    return clean_text(" | ".join(parts))


def collect_sjecampus_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update({"Accept-Encoding": "identity"})
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    discovered_links = 0
    selected_types = SJECAMPUS_COURSE_TYPES[: max(1, min(max_pages, len(SJECAMPUS_COURSE_TYPES)))]

    for course_type, type_label in selected_types:
        list_url = sjecampus_list_url(course_type)
        soup = sjecampus_fetch_soup(s, list_url, timeout=timeout)
        for link in soup.select("a[href*='consent_view.php']"):
            tr = link.find_parent("tr")
            if not tr:
                continue
            cells = [
                clean_text(cell.get_text(" ", strip=True))
                for cell in tr.find_all(["th", "td"], recursive=False)
            ]
            cells = [cell for cell in cells if cell]
            values = sjecampus_row_values(course_type, cells)
            title = clean_text(values.get("title") or link.get_text(" ", strip=True))
            if not values or not title or is_low_value_title(title):
                continue

            raw_url = normalize_link(list_url, link.get("href"))
            if not raw_url:
                continue
            detail_pairs: dict[str, str] = {}
            if detail_pages < detail_limit:
                try:
                    detail_soup = sjecampus_fetch_soup(s, raw_url, timeout=timeout)
                    detail_pairs = sjecampus_pairs_from_detail(detail_soup)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("sjecampus detail fetch failed %s: %s", raw_url, exc)

            title = (
                first_by_keys(detail_pairs, ("\uad50\uacfc\uba85", "\uac15\uc88c\uba85", "\ub0b4\uc6a9"))
                or title
            )
            branch = (
                first_by_keys(detail_pairs, ("\uac70\uc810\ud559\uad50", "\uc7a5\uc18c"))
                or clean_text(values.get("branch"))
                or SJECAMPUS_DEFAULT_BRANCH
            )
            venue_name = first_by_keys(detail_pairs, ("\uc7a5\uc18c", "\uac70\uc810\ud559\uad50")) or clean_text(values.get("venue_name")) or branch
            category = (
                first_by_keys(detail_pairs, ("\uad50\uacfc\ubd84\ub958", "\uac15\uc88c\uad6c\ubd84"))
                or clean_text(values.get("category"))
                or type_label
            )
            target_text = first_by_keys(detail_pairs, ("\ub300\uc0c1\ud559\ub144", "\ub300\uc0c1")) or clean_text(values.get("target"))
            schedule_raw = first_by_keys(detail_pairs, ("\uc6b4\uc601\uc2dc\uac04", "\uc77c\uc2dc", "\uc2dc\uac04")) or clean_text(values.get("schedule_raw"))
            instructor = first_by_keys(detail_pairs, ("\uc9c0\ub3c4\uad50\uc0ac", "\uac15\uc0ac")) or clean_text(values.get("instructor"))
            capacity_total = parse_capacity_number(
                first_by_keys(detail_pairs, ("\ucd5c\ub300\ubaa8\uc9d1", "\ubaa8\uc9d1\uc790", "\ubaa8\uc9d1\uc778\uc6d0"))
                or values.get("capacity_total")
            )
            capacity_current = parse_capacity_number(
                first_by_keys(detail_pairs, ("\uc2e0\uccad\uc778\uc6d0", "\uc2e0\uccad\uc790", "\uc811\uc218\uc790"))
                or values.get("capacity_current")
            )
            period = schedule_raw if re.search(r"\d{4}[./-]\d{1,2}[./-]\d{1,2}", schedule_raw) else "2026\ud559\ub144\ub3c4 1\ud559\uae30"
            status = sjecampus_status(capacity_total, capacity_current)
            description = sjecampus_description(type_label, {**values, "venue_name": venue_name, "target": target_text, "instructor": instructor}, detail_pairs)

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "branch_code": stable_provider(target.provider[:32], branch),
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "period": period,
                    "schedule_raw": schedule_raw,
                    "target": target_text,
                    "fee": "\ubb34\ub8cc",
                    "venue_name": venue_name,
                    "instructor": instructor,
                    "capacity_total": capacity_total,
                    "capacity_current": capacity_current,
                    "capacity_remaining": (
                        max(capacity_total - capacity_current, 0)
                        if capacity_total is not None and capacity_current is not None
                        else None
                    ),
                    "category": category,
                    "category_raw": f"{type_label} / {category}" if category != type_label else category,
                    "collection_category": target.extra.get("collection_category") or "\ud3c9\uc0dd\ud559\uc2b5",
                    "domain_category": target.extra.get("domain_category") or "\uad50\uc721\u00b7\uac15\uc88c",
                    "application_type": "ONLINE_RESERVATION",
                    "reservation_available": status == "\uc811\uc218\uc911",
                    "description": description,
                    "raw_fields": {
                        "parser": "sjecampus_consent_list",
                        "course_type": course_type,
                        "type_label": type_label,
                        "list_url": list_url,
                        "cells": cells,
                        "detail_pairs": detail_pairs,
                    },
                }
            )
            discovered_links += 1

    meta = {
        "pages": len(selected_types),
        "detail_pages": detail_pages,
        "discovered_links": discovered_links,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
        "no_current_data": not rows,
        "no_current_reason": "no_current_sjecampus_courses" if not rows else "",
    }
    return dedupe_rows(rows), "sjecampus_consent_list", meta


JEONGSEON_BASE_URL = "https://edu.jeongseon.go.kr"
JEONGSEON_DEFAULT_BRANCH = "\uc815\uc120\uad70\ud3c9\uc0dd\ud559\uc2b5\uad00"
JEONGSEON_QUARTERS = (
    ("LifeEdu", "\ud3c9\uc0dd\uad50\uc721\uac15\uc88c"),
    ("InfoEdu", "\uae30\ucd08\ubb38\ud574\uad50\uc721\uac15\uc88c"),
    ("OnlineEdu", "\ub514\uc9c0\ud138\ubb38\ud574\uad50\uc721\uac15\uc88c"),
)


def jeongseon_list_url(quarter: str = "LifeEdu", page: int = 1) -> str:
    params: dict[str, Any] = {"quarter": quarter}
    if page > 1:
        params["page"] = str(page)
    return f"{JEONGSEON_BASE_URL}/lecture?{urlencode(params)}"


def jeongseon_pairs_from_table(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for tr in soup.select("table tr"):
        th = tr.find("th")
        td = tr.find("td")
        if not th or not td:
            continue
        key = clean_text(th.get_text(" ", strip=True))
        value = clean_text(td.get_text(" ", strip=True))
        if key and value and len(key) <= 30:
            pairs.setdefault(key, value)
    return pairs


def jeongseon_summary_from_script(node: Any) -> str:
    for script in node.find_all("script"):
        script_text = script.string or script.get_text(" ", strip=True)
        for match in re.finditer(r"`\s*<div>(.*?)</div>\s*`", script_text, flags=re.DOTALL):
            value = clean_text(BeautifulSoup(match.group(1), "html.parser").get_text(" ", strip=True))
            if value:
                return value
    return ""


def jeongseon_card_pairs(item: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for block in item.select("div.nomargin"):
        label = block.find("b")
        if not label:
            continue
        key = clean_text(label.get_text(" ", strip=True)).replace(" ", "")
        value_node = block.select_one(".commonValue")
        value = clean_text(value_node.get_text(" ", strip=True)) if value_node else ""
        if not value:
            value = jeongseon_summary_from_script(block)
        if key and value:
            pairs[key] = value
    return pairs


def jeongseon_clean_location(value: Any) -> str:
    text = clean_text(value)
    text = re.sub(r"\s*>\s*", " > ", text)
    return clean_text(text)


def jeongseon_clean_schedule(value: Any) -> str:
    text = clean_text(value).replace("|", " ")
    text = re.sub(r"\s+", " ", text).strip()
    if not re.search(r"\d|\uc6d4|\ud654|\uc218|\ubaa9|\uae08|\ud1a0|\uc77c", text):
        return ""
    return clean_text(text)


def jeongseon_capacity_pair(value: Any) -> tuple[Optional[int], Optional[int]]:
    text = clean_text(value).replace(",", "")
    match = re.search(r"(\d{1,5})\s*(?:\uba85|\ud300)?\s*/\s*(\d{1,5})\s*(?:\uba85|\ud300)?", text)
    if match:
        return int(match.group(1)), int(match.group(2))
    return parse_capacity_pair(text)


def jeongseon_status(value: Any) -> str:
    text = clean_text(value)
    if "\uc811\uc218\uc911" in text:
        return "\uc811\uc218\uc911"
    if "\uc608\uc815" in text:
        return "\uc811\uc218\uc608\uc815"
    if "\uc815\uc6d0\ucd08\uacfc" in text:
        return "\uc815\uc6d0\ucd08\uacfc"
    if "\uc2e0\uccad\uc885\ub8cc" in text or "\ub9c8\uac10" in text:
        return "\uc811\uc218\ub9c8\uac10"
    if "\uc885\uac15" in text:
        return "\uc885\uac15"
    if "\ud3d0\uac15" in text:
        return "\ud3d0\uac15"
    if "\uac15\uc758" in text:
        return "\uac15\uc758\uc911"
    return normalize_status(text, text) if text else ""


def collect_jeongseon_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    discovered_links = 0
    pagination_detected = False
    total_rows_by_quarter: dict[str, int] = {}
    finished_quarters: set[str] = set()
    fetch_budget = max(1, max_pages)

    for page_number in range(1, fetch_budget + 1):
        page_had_rows = False
        for quarter, quarter_label in JEONGSEON_QUARTERS:
            if pages >= fetch_budget:
                break
            if quarter in finished_quarters:
                continue

            list_url = jeongseon_list_url(quarter, page_number)
            soup = fetch_soup(s, list_url, timeout=timeout)
            pages += 1
            items = soup.select("div.program_list.apply_type1 > ul > li.clearfix")
            if not items:
                finished_quarters.add(quarter)
                continue

            page_had_rows = True
            page_text = clean_text(soup.get_text(" ", strip=True))
            total_match = re.search(r"\uc804\uccb4\s*:\s*(\d{1,5})", page_text)
            if total_match and page_number == 1:
                total_rows_by_quarter[quarter] = int(total_match.group(1))
            if soup.select("a[href*='page='], .pagination, .paging"):
                pagination_detected = True

            for item in items:
                title_link = item.select_one("p.tit a.click_move[data-move]") or item.select_one("a.click_move[data-move]")
                if not title_link:
                    continue
                title = clean_text(title_link.get_text(" ", strip=True))
                course_no = clean_text(title_link.get("data-move"))
                if not title or not course_no or is_low_value_title(title):
                    continue

                raw_url = f"{JEONGSEON_BASE_URL}/lec_view?{urlencode({'cls_no': course_no})}"
                card_pairs = jeongseon_card_pairs(item)
                detail_pairs: dict[str, str] = {}
                if detail_pages < detail_limit:
                    try:
                        detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                        detail_pairs = jeongseon_pairs_from_table(detail_soup)
                        detail_pages += 1
                    except Exception as exc:
                        logger.debug("jeongseon detail fetch failed %s: %s", raw_url, exc)

                title = first_by_keys(detail_pairs, ("\uac15\uc88c\uba85",)) or title
                category = first_by_keys(detail_pairs, ("\ubd84\uc57c",)) or quarter_label
                branch = JEONGSEON_DEFAULT_BRANCH
                venue_name = jeongseon_clean_location(first_by_keys(detail_pairs, ("\uc704\uce58",)))
                apply_period = first_by_keys(detail_pairs, ("\uc2e0\uccad\uae30\uac04",)) or card_pairs.get("\uc2e0\uccad\uae30\uac04", "")
                period = first_by_keys(detail_pairs, ("\uad50\uc721\uae30\uac04",)) or card_pairs.get("\uad50\uc721\uae30\uac04", "")
                schedule_raw = jeongseon_clean_schedule(
                    first_by_keys(detail_pairs, ("\uad50\uc721\uc2dc\uac04", "\uac15\uc758\uc2dc\uac04"))
                    or card_pairs.get("\uac15\uc758\uc2dc\uac04", "")
                )
                capacity_raw = first_by_keys(detail_pairs, ("\uc815\uc6d0",)) or clean_text(
                    (item.select_one(".util .loc") or item).get_text(" ", strip=True)
                )
                capacity_current, capacity_total = jeongseon_capacity_pair(capacity_raw)
                card_status_text = clean_text(
                    (item.select_one(".util .state") or item).get_text(" ", strip=True)
                )
                detail_status_text = first_by_keys(detail_pairs, ("\uac15\uc758\uc0c1\ud0dc",))
                status = jeongseon_status(card_status_text) or jeongseon_status(detail_status_text)
                description = first_by_keys(detail_pairs, ("\uc694\uc57d",)) or card_pairs.get("\uc694\uc57d", "")
                start_date, end_date = parse_date_range(period)

                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                        "title": title,
                        "branch": branch,
                        "branch_code": stable_provider(target.provider[:32], branch),
                        "raw_url": raw_url,
                        "application_url": raw_url,
                        "status": status,
                        "period": period,
                        "apply_period": apply_period,
                        "schedule_raw": schedule_raw,
                        "venue_name": venue_name,
                        "capacity_total": capacity_total,
                        "capacity_current": capacity_current,
                        "capacity_remaining": (
                            max(capacity_total - capacity_current, 0)
                            if capacity_total is not None and capacity_current is not None
                            else None
                        ),
                        "category": category,
                        "category_raw": f"{quarter_label} / {category}" if category != quarter_label else category,
                        "collection_category": target.extra.get("collection_category") or "\ud3c9\uc0dd\ud559\uc2b5",
                        "domain_category": target.extra.get("domain_category") or "\uad50\uc721\u00b7\uac15\uc88c",
                        "application_type": "ONLINE_RESERVATION",
                        "reservation_available": status == "\uc811\uc218\uc911",
                        "description": description
                        or clean_text(" ".join(detail_pairs.values()))
                        or clean_text(" ".join([title, period, schedule_raw])),
                        "start_date": start_date,
                        "end_date": end_date,
                        "raw_fields": {
                            "parser": "jeongseon_lifelong_lecture",
                            "quarter": quarter,
                            "quarter_label": quarter_label,
                            "course_no": course_no,
                            "list_url": list_url,
                            "card_pairs": card_pairs,
                            "detail_pairs": detail_pairs,
                            "capacity_raw": capacity_raw,
                            "card_status": card_status_text,
                            "detail_status": detail_status_text,
                        },
                    }
                )
                discovered_links += 1

        if pages >= fetch_budget or (not page_had_rows and len(finished_quarters) == len(JEONGSEON_QUARTERS)):
            break

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": discovered_links,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
        "total_rows": sum(total_rows_by_quarter.values()) if total_rows_by_quarter else len(rows),
        "total_rows_by_quarter": total_rows_by_quarter,
    }
    return dedupe_rows(rows), "jeongseon_lifelong_lecture", meta


JINDO_LIFELONG_URL = "https://www.jindo.go.kr/edu/edu/E0004.cs?m=9"
JINDO_DEFAULT_BRANCH = "\uc9c4\ub3c4\uad70 \ud3c9\uc0dd\ud559\uc2b5\uad00"


def jindo_lifelong_url(page_index: int = 1) -> str:
    params: dict[str, Any] = {"m": "9"}
    if page_index > 1:
        params["pageIndex"] = str(page_index)
    return f"https://www.jindo.go.kr/edu/edu/E0004.cs?{urlencode(params)}"


def jindo_pairs_from_info(scope: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in scope.select("li"):
        label = item.find("em")
        if not label:
            continue
        key = clean_text(label.get_text(" ", strip=True))
        span = item.find("span")
        if span:
            value = clean_text(span.get_text(" ", strip=True))
        else:
            value = clean_text(item.get_text(" ", strip=True))
            if value.startswith(key):
                value = clean_text(value[len(key):])
        if key and value and len(key) <= 30:
            pairs[key] = value
    return pairs


def jindo_status(value: Any) -> str:
    text = clean_text(value)
    if "\uc2e0\uccad\ub9c8\uac10" in text or "\ub9c8\uac10" in text:
        return "\uc811\uc218\ub9c8\uac10"
    if "\uc2e0\uccad\uc911" in text or "\uc811\uc218\uc911" in text or "\uc2e0\uccad\uac00\ub2a5" in text:
        return "\uc811\uc218\uc911"
    if "\uc608\uc815" in text:
        return "\uc811\uc218\uc608\uc815"
    return normalize_status(text, text) if text else ""


def jindo_fee_from_detail(soup: BeautifulSoup) -> str:
    for script in soup.find_all("script"):
        text = script.string or script.get_text(" ", strip=True)
        match = re.search(r"#eduPrice['\"]?\)\.text\('([^']*)'\)", text)
        if match:
            return clean_text(match.group(1))
    return ""


def collect_jindo_lifelong_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    discovered_links = 0
    pagination_detected = False
    seen_page_first_urls: set[str] = set()

    for page_index in range(1, max(1, max_pages) + 1):
        list_url = jindo_lifelong_url(page_index)
        soup = fetch_soup(s, list_url, timeout=timeout)
        pages += 1
        items = soup.select("ul.proList > li")
        if not items:
            break
        if soup.select(".paginate a[href*='pageIndex=']"):
            pagination_detected = True

        first_link = normalize_link(list_url, items[0].find("a", href=True).get("href") if items[0].find("a", href=True) else "")
        if first_link and first_link in seen_page_first_urls:
            break
        if first_link:
            seen_page_first_urls.add(first_link)

        for item in items:
            link = item.find("a", href=True)
            raw_url = normalize_link(list_url, link.get("href") if link else None)
            if not raw_url:
                continue
            list_pairs = jindo_pairs_from_info(item)
            title = clean_text((item.select_one(".tit") or item).get_text(" ", strip=True))
            title = first_by_keys(list_pairs, ("\uacfc\uc815\uba85",)) or title
            if not title or is_low_value_title(title):
                continue

            detail_pairs: dict[str, str] = {}
            detail_description = ""
            fee = ""
            detail_status = ""
            if detail_pages < detail_limit:
                try:
                    detail_soup = fetch_soup(s, raw_url, timeout=timeout)
                    detail_scope = detail_soup.select_one(".proInfo") or detail_soup
                    detail_pairs = jindo_pairs_from_info(detail_scope)
                    detail_description = clean_text(
                        (detail_soup.select_one(".proDetail .proContent") or detail_soup.select_one(".proDetail") or "").get_text(" ", strip=True)
                        if detail_soup.select_one(".proDetail .proContent") or detail_soup.select_one(".proDetail")
                        else ""
                    )
                    fee = jindo_fee_from_detail(detail_soup)
                    detail_status = clean_text((detail_soup.select_one(".proInfo .lkBtn") or detail_soup).get_text(" ", strip=True))
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("jindo detail fetch failed %s: %s", raw_url, exc)

            pairs = {**list_pairs, **detail_pairs}
            title = first_by_keys(pairs, ("\uacfc\uc815\uba85",)) or title
            period = first_by_keys(pairs, ("\uad50\uc721\uae30\uac04",))
            apply_period = first_by_keys(pairs, ("\uc2e0\uccad\uae30\uac04",))
            schedule_raw = first_by_keys(pairs, ("\uc6b4\uc601\uc2dc\uac04",))
            venue_name = first_by_keys(pairs, ("\uad50\uc721\uc7a5\uc18c",))
            instructor = first_by_keys(pairs, ("\uac15\uc0ac\uba85",))
            institution = first_by_keys(pairs, ("\uad50\uc721\uae30\uad00",))
            capacity_total = parse_capacity_number(first_by_keys(pairs, ("\ubaa8\uc9d1\uc778\uc6d0",)))
            status_text = clean_text((item.select_one(".status") or item).get_text(" ", strip=True))
            status = jindo_status(status_text) or jindo_status(detail_status)
            start_date, end_date = parse_date_range(period)
            description = detail_description or clean_text(" | ".join(part for part in (institution, instructor, venue_name) if part))

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, JINDO_DEFAULT_BRANCH),
                    "title": title,
                    "branch": JINDO_DEFAULT_BRANCH,
                    "branch_code": stable_provider(target.provider[:32], JINDO_DEFAULT_BRANCH),
                    "raw_url": raw_url,
                    "application_url": raw_url,
                    "status": status,
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule_raw,
                    "venue_name": venue_name,
                    "instructor": instructor,
                    "capacity_total": capacity_total,
                    "category": "\ud3c9\uc0dd\ud559\uc2b5",
                    "category_raw": "\ud3c9\uc0dd\ud559\uc2b5 / \uad50\uc721\uc77c\uc815",
                    "collection_category": target.extra.get("collection_category") or "\ud3c9\uc0dd\ud559\uc2b5",
                    "domain_category": target.extra.get("domain_category") or "\uad50\uc721\u00b7\uac15\uc88c",
                    "application_type": "ONLINE_RESERVATION",
                    "reservation_available": status == "\uc811\uc218\uc911",
                    "fee": fee,
                    "description": description,
                    "start_date": start_date,
                    "end_date": end_date,
                    "raw_fields": {
                        "parser": "jindo_lifelong_schedule",
                        "list_url": list_url,
                        "list_pairs": list_pairs,
                        "detail_pairs": detail_pairs,
                        "status_text": status_text,
                        "detail_status": detail_status,
                    },
                }
            )
            discovered_links += 1

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": discovered_links,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jindo_lifelong_schedule", meta


YUMCORP_SPORTS_LIST_URL = "https://www.yumcorp.or.kr/sports/lecture/list.do"
YUMCORP_DEFAULT_BRANCH = "\uc5ec\uc218\ub3c4\uc2dc\uad00\ub9ac\uacf5\ub2e8 \ud1b5\ud569\uc608\uc57d"


def yumcorp_sports_url(page_index: int = 1) -> str:
    if page_index <= 1:
        return YUMCORP_SPORTS_LIST_URL
    return f"{YUMCORP_SPORTS_LIST_URL}?{urlencode({'pageIndex': str(page_index)})}"


def yumcorp_fetch_soup(s: requests.Session, url: str, timeout: int) -> BeautifulSoup:
    response = s.get(url, timeout=timeout)
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    return BeautifulSoup(response.text, "html.parser")


def yumcorp_extract_periods(page_text: str) -> tuple[str, str]:
    apply_match = re.search(
        r"\uc2e0\uaddc\ud68c\uc6d0\s*\uc811\uc218\uae30\uac04\s*[:：]\s*(\d{4}-\d{2}-\d{2}\s*\d{2}:\d{2}\s*~\s*\d{4}-\d{2}-\d{2}\s*\d{2}:\d{2})",
        page_text,
    )
    period_match = re.search(
        r"\uc2e0\uaddc\ud68c\uc6d0\s*\uac15\uc2b5\uae30\uac04\s*[:：]\s*([0-9.:-]+\s*~\s*[0-9.:-]+)",
        page_text,
    )
    return (
        clean_text(period_match.group(1)) if period_match else "",
        clean_text(apply_match.group(1)) if apply_match else "",
    )


def yumcorp_pairs_from_desc(item: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in item.select("ul.desc li"):
        label = li.find("span")
        if not label:
            continue
        key = clean_text(label.get_text(" ", strip=True))
        value = clean_text(li.get_text(" ", strip=True))
        if value.startswith(key):
            value = clean_text(value[len(key):])
        if key and value:
            pairs[key] = value
    return pairs


def yumcorp_go_view_args(href: str) -> tuple[str, str, str, str]:
    match = re.search(r"goView\(([^)]*)\)", href or "", flags=re.IGNORECASE)
    if not match:
        return "", "", "", ""
    args = [clean_text(part.strip().strip("'\"")) for part in match.group(1).split(",")]
    args += [""] * (4 - len(args))
    return args[0], args[1], args[2], args[3]


def yumcorp_status(value: Any) -> str:
    text = clean_text(value)
    if "\uc811\uc218\uc911" in text or "\uc2e0\uccad\uc911" in text:
        return "\uc811\uc218\uc911"
    if "\uc900\ube44\uc911" in text or "\uc608\uc815" in text:
        return "\uc811\uc218\uc608\uc815"
    if "\ub9c8\uac10" in text:
        return "\uc811\uc218\ub9c8\uac10"
    return normalize_status(text, text) if text else ""


def collect_yumcorp_sports_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    discovered_links = 0
    pagination_detected = False

    for page_index in range(1, max(1, max_pages) + 1):
        list_url = yumcorp_sports_url(page_index)
        soup = yumcorp_fetch_soup(s, list_url, timeout=timeout)
        pages += 1
        page_text = clean_text(soup.get_text(" ", strip=True))
        period, apply_period = yumcorp_extract_periods(page_text)
        items = soup.select(".view_list > div")
        page_rows = 0
        if soup.select("a[href*='pageIndex=']"):
            pagination_detected = True

        for item in items:
            link = item.find("a", href=True)
            if not link or "goView" not in (link.get("href") or ""):
                continue
            site_code, group_id, item_id, goto_page = yumcorp_go_view_args(link.get("href") or "")
            if not item_id:
                continue

            facility_category = [clean_text(part) for part in item.select_one(".td.point1").stripped_strings] if item.select_one(".td.point1") else []
            facility = clean_text(facility_category[0]).strip("[]") if facility_category else YUMCORP_DEFAULT_BRANCH
            category = clean_text(facility_category[1]) if len(facility_category) > 1 else "\uc2a4\ud3ec\uce20\uac15\uc2b5"
            title_node = item.select_one("p.tit")
            status_node = title_node.select_one(".badge") if title_node else None
            status_text = clean_text(status_node.get_text(" ", strip=True)) if status_node else ""
            if status_node:
                status_node.decompose()
            title = clean_text(title_node.get_text(" ", strip=True)) if title_node else ""
            title = clean_text(re.sub(r"\s*-\s*", "-", title))
            if not title:
                continue

            pairs = yumcorp_pairs_from_desc(item)
            schedule_raw = first_by_keys(pairs, ("\uac15\uc2b5\uc2dc\uac04",))
            target_text = first_by_keys(pairs, ("\ub300\uc0c1",))
            capacity_total = parse_capacity_number(first_by_keys(pairs, ("\uc815\uc6d0",)))
            capacity_remaining = parse_capacity_number(first_by_keys(pairs, ("\ubaa8\uc9d1\uc778\uc6d0",)))
            capacity_current = (
                max(capacity_total - capacity_remaining, 0)
                if capacity_total is not None and capacity_remaining is not None
                else None
            )
            fee = first_by_keys(pairs, ("\uac15\uc2b5\ube44",))
            status = yumcorp_status(status_text)
            raw_url = (
                "https://www.yumcorp.or.kr/sports/lecture/detail.do?"
                + urlencode({"SiteCode": site_code, "Item1": group_id, "itemid": item_id, "pageIndex": goto_page or str(page_index)})
            )
            start_date, end_date = parse_date_range(period)

            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, facility),
                    "title": title,
                    "branch": facility,
                    "branch_code": stable_provider(target.provider[:32], facility),
                    "raw_url": raw_url,
                    "application_url": YUMCORP_SPORTS_LIST_URL,
                    "status": status,
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule_raw,
                    "target": target_text,
                    "fee": fee,
                    "venue_name": facility,
                    "capacity_total": capacity_total,
                    "capacity_current": capacity_current,
                    "capacity_remaining": capacity_remaining,
                    "category": category,
                    "category_raw": f"{facility} / {category}",
                    "collection_category": target.extra.get("collection_category") or "\uccb4\uc721\u00b7\uc2a4\ud3ec\uce20",
                    "domain_category": target.extra.get("domain_category") or "\uccb4\uc721\u00b7\uc2a4\ud3ec\uce20",
                    "application_type": "ONLINE_RESERVATION",
                    "reservation_available": status == "\uc811\uc218\uc911",
                    "description": clean_text(" | ".join(part for part in (facility, category, target_text) if part)),
                    "start_date": start_date,
                    "end_date": end_date,
                    "raw_fields": {
                        "parser": "yumcorp_sports_lecture_list",
                        "list_url": list_url,
                        "site_code": site_code,
                        "group_id": group_id,
                        "item_id": item_id,
                        "pairs": pairs,
                        "status_text": status_text,
                    },
                }
            )
            discovered_links += 1
            page_rows += 1

        if page_rows == 0:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": discovered_links,
        "reservation_discovery_links": sum(1 for row in rows if clean_text(row.get("application_url"))),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "yumcorp_sports_lecture_list", meta


SOOPERANG_BASE_URL = "https://www.sooperang.go.kr"
SOOPERANG_PROGRAM_LIST_URL = f"{SOOPERANG_BASE_URL}/rep/ari/selectPrgmRsrvtList.do"
SOOPERANG_INSTITUTION_AJAX_URL = f"{SOOPERANG_BASE_URL}/rep/ari/selectArcdInsttListAjax.do"
SOOPERANG_POLICY_AJAX_URL = (
    f"{SOOPERANG_BASE_URL}/rep/ari/selectInsttPlcyNotIncludeCheckoutAjax.do"
)
SOOPERANG_BRANCH = "\uc232e\ub791 \uc0b0\ub9bc\ubcf5\uc9c0\ud1b5\ud569\ud50c\ub7ab\ud3fc"
SOOPERANG_MAX_INSTITUTIONS = 50
SOOPERANG_MAX_BOOKING_DAYS = 62
SOOPERANG_FALLBACK_INSTITUTION_IDS = (
    "FA00001", "FA00002", "FA00003", "FA00004", "FA00005", "FA00006", "FA00007",
    "FT00001", "FT00002", "FT00003", "FT00004", "FT00005", "FT00006", "FT00007",
    "FT00008", "FT00009", "FT00010", "FT00011", "FT00012", "FT00013",
)


def sooperang_list_url(instt_id: str = "", use_date: str = "") -> str:
    params = {
        "menuNo": "1020000",
        "searchNofpr": "1",
    }
    if instt_id:
        params["searchInsttId"] = instt_id
        params["searchInsttIdSub"] = instt_id
    if use_date:
        params["searchUseDt"] = use_date
    return f"{SOOPERANG_PROGRAM_LIST_URL}?{urlencode(params)}"


def sooperang_institutions(
    s: requests.Session,
    timeout: int,
    *,
    strict: bool = True,
) -> list[tuple[str, str]]:
    try:
        response = s.post(
            SOOPERANG_INSTITUTION_AJAX_URL,
            data={"arcdNm": "", "prrtRsrvtYn": "N"},
            headers={
                "Referer": sooperang_list_url(),
                "X-Requested-With": "XMLHttpRequest",
            },
            timeout=timeout,
        )
        response.raise_for_status()
        payload = response.json()
        if not isinstance(payload, dict):
            raise RuntimeError("Sooperang institution response is not an object")
        institutions: list[tuple[str, str]] = []
        for item in payload.get("arcdInsttList") or []:
            if not isinstance(item, dict):
                raise RuntimeError("Sooperang institution response contains a non-object row")
            instt_id = clean_text(item.get("insttId"))
            instt_name = clean_text(item.get("insttNm"))
            if not re.fullmatch(r"[A-Z]{2}\d{5}", instt_id) or not instt_name:
                raise RuntimeError("Sooperang institution identity is missing or invalid")
            institutions.append((instt_id, instt_name))
        if len(institutions) != len({instt_id for instt_id, _ in institutions}):
            raise RuntimeError("Sooperang institution response contains duplicate IDs")
        if len(institutions) > SOOPERANG_MAX_INSTITUTIONS:
            raise RuntimeError(
                f"Sooperang institution count {len(institutions)} exceeds "
                f"reviewed cap {SOOPERANG_MAX_INSTITUTIONS}"
            )
        if institutions:
            return institutions
        raise RuntimeError("Sooperang institution response is empty")
    except Exception as exc:
        if strict:
            raise RuntimeError("Sooperang institution discovery failed") from exc
        logger.debug("Sooperang institution AJAX failed: %s", exc)
    return [(instt_id, "") for instt_id in SOOPERANG_FALLBACK_INSTITUTION_IDS]


def sooperang_parse_date(value: Any) -> date:
    text = clean_text(value)
    match = re.fullmatch(r"(\d{4})-(\d{1,2})-(\d{1,2})", text)
    if not match:
        raise RuntimeError(f"Sooperang date is invalid: {text!r}")
    try:
        return date(*(int(part) for part in match.groups()))
    except ValueError as exc:
        raise RuntimeError(f"Sooperang date is invalid: {text!r}") from exc


def sooperang_institution_policy(
    s: requests.Session,
    *,
    instt_id: str,
    timeout: int,
) -> dict[str, Any]:
    response = s.post(
        SOOPERANG_POLICY_AJAX_URL,
        data={"insttId": instt_id},
        headers={
            "Referer": sooperang_list_url(),
            "X-Requested-With": "XMLHttpRequest",
        },
        timeout=timeout,
    )
    response.raise_for_status()
    payload = response.json()
    policy = payload.get("rsrvtPlcyVO") if isinstance(payload, dict) else None
    if not isinstance(policy, dict):
        raise RuntimeError(f"Sooperang policy is missing for institution {instt_id}")
    start = sooperang_parse_date(policy.get("minDate"))
    end = sooperang_parse_date(policy.get("maxDate"))
    if start > end:
        raise RuntimeError(f"Sooperang policy date range is reversed for {instt_id}")
    if (end - start).days + 1 > SOOPERANG_MAX_BOOKING_DAYS:
        raise RuntimeError(
            f"Sooperang policy for {instt_id} exceeds reviewed "
            f"{SOOPERANG_MAX_BOOKING_DAYS}-day window"
        )
    return policy


def sooperang_policy_dates(
    policy: dict[str, Any],
    *,
    today: date,
) -> list[date]:
    start = max(today, sooperang_parse_date(policy.get("minDate")))
    end = sooperang_parse_date(policy.get("maxDate"))
    if start > end:
        return []
    disabled_dates = {
        sooperang_parse_date(value)
        for value in (policy.get("disabledDayList") or [])
        if clean_text(value)
    }
    return [
        start + timedelta(days=offset)
        for offset in range((end - start).days + 1)
        if start + timedelta(days=offset) not in disabled_dates
    ]


def sooperang_application_period(
    use_date: date,
    policy: dict[str, Any],
) -> str:
    if use_date.month == 1:
        open_year, open_month = use_date.year - 1, 12
    else:
        open_year, open_month = use_date.year, use_date.month - 1
    open_day = parse_capacity_number(policy.get("monthOpenBgdt")) or 15
    open_day = min(open_day, calendar.monthrange(open_year, open_month)[1])
    open_hour = parse_capacity_number(policy.get("monthOpenTm")) or 9
    close_days_before = parse_capacity_number(policy.get("dateOpenBgnDate")) or 1
    close_date = use_date - timedelta(days=close_days_before)
    return (
        f"{open_year:04d}-{open_month:02d}-{open_day:02d} {open_hour:02d}:00 ~ "
        f"{close_date.isoformat()} 15:00"
    )


def sooperang_card_pairs(card: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in card.select(".program_text_inner li"):
        label = clean_text(item.select_one("strong").get_text(" ", strip=True) if item.select_one("strong") else "")
        value = clean_text(item.select_one("p").get_text(" ", strip=True) if item.select_one("p") else "")
        if label and value:
            pairs[label] = value
    return pairs


def sooperang_program_ids(card: BeautifulSoup) -> tuple[str, str]:
    for node in card.select("[onclick*='fn_prgmRsrvt']"):
        onclick = clean_text(node.get("onclick"))
        match = re.search(r"fn_prgmRsrvt\('([^']+)'\s*,\s*'([^']+)'\)", onclick)
        if match:
            return match.group(1), match.group(2)
    return "", ""


def collect_sooperang_program_reservations(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    *,
    session_factory: Callable[[], requests.Session] = session,
    today: Optional[date] = None,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session_factory()
    s.headers.update({"Referer": sooperang_list_url()})
    institutions = sooperang_institutions(s, timeout=timeout, strict=True)
    today_value = today or datetime.now().date()
    scopes: list[tuple[str, str, date, dict[str, Any]]] = []
    for instt_id, instt_name in institutions:
        policy = sooperang_institution_policy(
            s,
            instt_id=instt_id,
            timeout=timeout,
        )
        for use_date in sooperang_policy_dates(policy, today=today_value):
            scopes.append((instt_id, instt_name, use_date, policy))
    if len(scopes) > max_pages:
        raise RuntimeError(
            f"Sooperang complete booking scope requires {len(scopes)} pages; "
            f"max_pages={max_pages}"
        )

    rows: list[dict[str, Any]] = []
    pages = 0
    candidate_cards = 0
    skipped_without_booking = 0

    for instt_id, instt_name, use_date, policy in scopes:
        use_date_text = use_date.isoformat()
        current_url = sooperang_list_url(instt_id, use_date_text)
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        branch = instt_name or target.branch or SOOPERANG_BRANCH
        for card in soup.select(".program"):
            candidate_cards += 1
            title = clean_text(
                card.select_one("h3").get_text(" ", strip=True)
                if card.select_one("h3")
                else ""
            )
            if not title or is_low_value_title(title):
                continue
            category = (
                clean_text(
                    card.select_one(".prg_label").get_text(" ", strip=True)
                    if card.select_one(".prg_label")
                    else ""
                )
                or "\uc0b0\ub9bc\ubcf5\uc9c0 \ud504\ub85c\uadf8\ub7a8"
            )
            tags = [
                clean_text(node.get_text(" ", strip=True))
                for node in card.select(".program_text > ul > li")
                if clean_text(node.get_text(" ", strip=True))
            ]
            pairs = sooperang_card_pairs(card)
            prgrm_id, goods_id = sooperang_program_ids(card)
            if not prgrm_id or not goods_id:
                skipped_without_booking += 1
                continue
            raw_url = f"{current_url}#{prgrm_id}:{goods_id}"
            image = card.select_one("img.slide_img")
            image_url = normalize_link(
                current_url,
                image.get("src") if image else None,
            )
            duration = pairs.get("\uc18c\uc694\uc2dc\uac04", "")
            effect = pairs.get("\ud6a8\uacfc", "")
            source_description = pairs.get("\uc124\uba85", "")
            period = use_date_text
            apply_period = sooperang_application_period(use_date, policy)
            schedule_raw = "\ud68c\ucc28 \uc2dc\uac04 \uae30\uad00 \ud611\uc758"
            if duration:
                schedule_raw = f"{schedule_raw} (\uc18c\uc694\uc2dc\uac04 {duration})"
            target_text = ", ".join(tags) or "\uc804\uc5f0\ub839"
            fee = "\uc694\uae08 \ubcc4\ub3c4 \uc548\ub0b4"
            description = clean_text(
                " | ".join(
                    part
                    for part in (
                        source_description,
                        effect,
                        schedule_raw,
                        fee,
                    )
                    if part
                )
            )
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(
                        target.provider,
                        raw_url,
                        title,
                        branch,
                    ),
                    "title": title,
                    "branch": branch,
                    "branch_code": instt_id,
                    "category": category,
                    "category_raw": category,
                    "raw_url": raw_url,
                    "application_url": current_url,
                    "status": "\uc608\uc57d\uac00\ub2a5",
                    "fee": fee,
                    "period": period,
                    "apply_period": apply_period,
                    "schedule_raw": schedule_raw,
                    "target": target_text,
                    "room": branch,
                    "venue_name": branch,
                    "description": description,
                    "image_url": image_url,
                    "collection_category": "\uccb4\ud5d8",
                    "domain_category": "\uc0b0\ub9bc\uccb4\ud5d8",
                    "operator_type": "\uad6d\ub9bd/\uacf5\uacf5\uae30\uad00",
                    "source_group": "national_institution",
                    "collection_type": "booking_policy_dates+program_cards",
                    "program_type": "\uccb4\ud5d8",
                    "reservation_available": True,
                    "application_type": "ONLINE_RESERVATION",
                    "application_method_raw": "\uc628\ub77c\uc778 \uc608\uc57d(\ub85c\uadf8\uc778 \ud544\uc694)",
                    "start_date": use_date_text,
                    "end_date": use_date_text,
                    "raw_fields": {
                        "parser": "sooperang_complete_booking_dates",
                        "instt_id": instt_id,
                        "use_date": use_date_text,
                        "prgrm_id": prgrm_id,
                        "goods_id": goods_id,
                        "tags": tags,
                        "pairs": pairs,
                        "policy": policy,
                        "fee": fee,
                        "schedule": schedule_raw,
                    },
                }
            )

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": len(scopes) > 1,
        "pagination_complete": pages == len(scopes),
        "source_cap_reached": pages != len(scopes),
        "recursion_depth": 0,
        "institutions": len(institutions),
        "policy_pages": len(institutions),
        "booking_scopes": len(scopes),
        "candidate_cards": candidate_cards,
        "skipped_without_booking": skipped_without_booking,
        "no_current_data": pages == len(scopes) and not rows,
        "no_current_reason": (
            "official booking policy dates contain no reservable programs"
            if pages == len(scopes) and not rows
            else ""
        ),
    }
    return dedupe_rows(rows), "sooperang_complete_booking_dates", meta


METEOROLOGICAL_MUSEUM_BRANCH = "\uad6d\ub9bd\uae30\uc0c1\ubc15\ubb3c\uad00"
METEOROLOGICAL_MUSEUM_EDU_URL = "https://science.kma.go.kr/museum/education/education"
METEOROLOGICAL_MUSEUM_EVENT_URL = "https://science.kma.go.kr/museum/education/festival"


def meteorological_museum_image_url(base_url: str, item: BeautifulSoup) -> str:
    thumbnail = item.select_one(".tmb")
    style = clean_text(thumbnail.get("style") if thumbnail else "")
    match = re.search(r"url\(['\"]?([^'\")]+)", style)
    return normalize_link(base_url, match.group(1)) if match else ""


def meteorological_museum_pairs(node: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for item in node.select(".inf li"):
        label_node = item.select_one("strong")
        label = clean_text(label_node.get_text(" ", strip=True) if label_node else "")
        if not label:
            continue
        value = clean_text(item.get_text(" ", strip=True).replace(label, "", 1))
        pairs[label] = value
    return pairs


def meteorological_museum_application_url(detail_url: str, soup: BeautifulSoup) -> str:
    naver = soup.select_one("a[href*='booking.naver.com']")
    if naver:
        return clean_text(naver.get("href"))
    for node in soup.select("[onclick*='window.open']"):
        onclick = clean_text(node.get("onclick"))
        match = re.search(r"window\.open\('([^']+)'", onclick)
        if match:
            return normalize_link(detail_url, match.group(1))
    return ""


def meteorological_museum_detail(
    s: requests.Session,
    detail_url: str,
    timeout: int,
) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    pairs = meteorological_museum_pairs(soup)
    content = soup.select_one(".exhibcont .contWrap") or soup.select_one(".exhibcont") or soup
    description = clean_text(content.get_text(" ", strip=True))
    times = list(dict.fromkeys(re.findall(r"\d{1,2}:\d{2}\s*~\s*\d{1,2}:\d{2}", description)))
    schedule = " / ".join(times[:4])
    return {
        "pairs": pairs,
        "description": description[:2000],
        "schedule_raw": schedule,
        "application_url": meteorological_museum_application_url(detail_url, soup),
    }


def collect_national_meteorological_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    sources = [
        ("\uad50\uc721", METEOROLOGICAL_MUSEUM_EDU_URL, "\uad50\uc721\ub300\uc0c1", "\uad50\uc721\uae30\uac04", "\uad50\uc721\uc7a5\uc18c", "\uad50\uc721\uc778\uc6d0"),
        ("\ud589\uc0ac", METEOROLOGICAL_MUSEUM_EVENT_URL, "\ucc38\uac00\ub300\uc0c1", "\ud589\uc0ac\uae30\uac04", "\ud589\uc0ac\uc7a5\uc18c", "\ucc38\uac00\uc778\uc6d0"),
    ]
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    unhandled_pagination = False

    for category, list_url, target_key, period_key, venue_key, capacity_key in sources:
        soup = fetch_soup(s, list_url, timeout=timeout)
        pages += 1
        unhandled_pagination = unhandled_pagination or bool(
            soup.select(
                "#sb-paging a[href], .paging a[href], .pagination a[href], "
                "#sb-paging a[onclick], .paging a[onclick], .pagination a[onclick]"
            )
        )
        for item in soup.select("ul.edulist > li"):
            link = item.select_one("a[href*='_view']")
            detail_url = normalize_link(list_url, link.get("href") if link else None) or list_url
            subject = clean_text(item.select_one(".txt").get_text(" ", strip=True) if item.select_one(".txt") else "")
            title_hint = clean_text(item.select_one(".tit").get_text(" ", strip=True) if item.select_one(".tit") else "")
            title = clean_text(f"{subject} - {title_hint}" if subject and title_hint else subject or title_hint)
            if not title or is_low_value_title(title):
                continue
            status = clean_text(item.select_one(".ico span").get_text(" ", strip=True) if item.select_one(".ico span") else "")
            pairs = meteorological_museum_pairs(item)
            detail: dict[str, Any] = {}
            if detail_pages < detail_limit:
                try:
                    detail = meteorological_museum_detail(s, detail_url, timeout=timeout)
                    detail_pages += 1
                except Exception as exc:
                    logger.debug("Meteorological museum detail fetch failed %s: %s", detail_url, exc)
            detail_pairs = detail.get("pairs") or {}
            merged_pairs = {**pairs, **detail_pairs}
            period = normalize_mixed_date_range(merged_pairs.get(period_key, "")) or merged_pairs.get(period_key, "")
            venue = clean_text(merged_pairs.get(venue_key) or merged_pairs.get("\uc7a5\uc18c") or METEOROLOGICAL_MUSEUM_BRANCH)
            application_url = clean_text(detail.get("application_url") or detail_url)
            reservation_available = status in {"\uc9c4\ud589\uc911", "\uc9c4\ud589\uc608\uc815"} and bool(application_url)
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, detail_url, title, METEOROLOGICAL_MUSEUM_BRANCH),
                    "title": title,
                    "branch": METEOROLOGICAL_MUSEUM_BRANCH,
                    "category": category,
                    "raw_url": detail_url,
                    "application_url": application_url if reservation_available else "",
                    "status": status,
                    "fee": "무료",
                    "period": period,
                    "apply_period": "",
                    "schedule_raw": clean_text(detail.get("schedule_raw") or period),
                    "target": clean_text(merged_pairs.get(target_key) or merged_pairs.get("\ub300\uc0c1")),
                    "capacity": clean_text(merged_pairs.get(capacity_key)),
                    "phone": clean_text(merged_pairs.get("\ubb38\uc758\ucc98") or merged_pairs.get("\ubb38\uc758")),
                    "room": venue,
                    "venue_name": venue,
                    "description": clean_text(detail.get("description") or item.get_text(" ", strip=True)),
                    "image_url": meteorological_museum_image_url(list_url, item),
                    "collection_category": "\ubc15\ubb3c\uad00/\uacfc\ud559\uad00",
                    "domain_category": "\ubc15\ubb3c\uad00/\uacfc\ud559\uad00",
                    "operator_type": "\uad6d\ub9bd/\uacf5\uacf5\uae30\uad00",
                    "source_group": "museum_science",
                    "collection_type": "static_html+detail_html",
                    "program_type": category,
                    "reservation_available": reservation_available,
                    "application_type": "ONLINE_RESERVATION" if reservation_available else "INFO_ONLY",
                    "application_method_raw": "\ub124\uc774\ubc84 \uc608\uc57d/\ubc15\ubb3c\uad00 \uc608\uc57d",
                    "raw_fields": {
                        "parser": "meteorological_museum_education_event",
                        "list_url": list_url,
                        "list_pairs": pairs,
                        "detail_pairs": detail_pairs,
                    },
                }
            )

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": unhandled_pagination,
        "pagination_complete": pages == len(sources) and not unhandled_pagination,
        "source_cap_reached": pages != len(sources) or unhandled_pagination,
        "recursion_depth": 1,
    }
    return dedupe_rows(rows), "meteorological_museum_education_event", meta


def ngii_map_museum_field_value(text: str, key: str) -> str:
    pattern = rf"{re.escape(key)}\s*:\s*(.*?)(?=\s*(?:교육명|교육일정|신청방법|교육대상|참여인원|교육내용|교육문의)\s*:|$)"
    match = re.search(pattern, text, flags=re.DOTALL)
    return clean_text(match.group(1)) if match else ""


def collect_national_map_museum(
    target: CrawlTarget,
    timeout: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    content = soup.select_one("#content") or soup.select_one(".content") or soup.select_one("main") or soup
    text = clean_text(content.get_text(" ", strip=True))
    rows: list[dict[str, Any]] = []

    chunks = re.split(r"(?=교육명\s*:)", text)
    for chunk in chunks:
        if "교육명" not in chunk:
            continue
        title = ngii_map_museum_field_value(chunk, "교육명")
        if not title or "준비 중" in title or is_low_value_title(title):
            continue
        period = normalize_mixed_date_range(ngii_map_museum_field_value(chunk, "교육일정")) or ngii_map_museum_field_value(chunk, "교육일정")
        application_method = ngii_map_museum_field_value(chunk, "신청방법")
        target_text = ngii_map_museum_field_value(chunk, "교육대상")
        capacity = ngii_map_museum_field_value(chunk, "참여인원")
        description = ngii_map_museum_field_value(chunk, "교육내용")
        phone = ngii_map_museum_field_value(chunk, "교육문의")
        schedule_times = " / ".join(dict.fromkeys(re.findall(r"\d{1,2}:\d{2}", chunk)))
        reservation_available = "현장" not in application_method and "추후" not in application_method
        raw_url = stable_list_item_url(
            target.url,
            target.provider,
            title,
            target.branch,
            period,
            schedule_times,
        )
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "branch_code": target.provider,
                "category": "교육",
                "raw_url": raw_url,
                "application_url": target.url if reservation_available else "",
                "status": "OPEN" if "현장" in application_method or period else "",
                "fee": "",
                "period": period,
                "apply_period": application_method,
                "schedule_raw": schedule_times or period,
                "target": target_text,
                "capacity": capacity,
                "phone": phone,
                "room": target.branch,
                "venue_name": target.branch,
                "venue_address": "경기도 수원시 영통구 월드컵로 92",
                "description": description,
                "collection_category": "박물관/과학관",
                "domain_category": "박물관/과학관",
                "operator_type": "국립/공공기관",
                "source_group": "museum_science",
                "collection_type": "static_html",
                "program_type": "교육",
                "reservation_available": reservation_available,
                "application_type": "INFO_ONLY",
                "application_method_raw": application_method,
                "raw_fields": {
                    "parser": "ngii_map_museum_education",
                    "source_url": target.url,
                    "application_method": application_method,
                    "raw_text": chunk[:1500],
                },
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": 0,
        "discovered_links": len(soup.find_all("a", href=True)),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "ngii_map_museum_education", meta


SUWON_LIBRARY_BRANCH_CODES = {
    "MA": "선경",
    "MB": "중앙",
    "MV": "창룡",
    "SB": "화서다산",
    "MY": "호매실",
    "MG": "서수원",
    "MU": "한림",
    "MW": "버드내",
    "MH": "북수원",
    "MT": "대추골",
    "MZ": "일월",
    "MX": "광교홍재",
    "MI": "태장마루",
    "SC": "광교푸른숲",
    "SD": "매여울",
    "SE": "망포글빛",
    "MD": "슬기샘",
    "MF": "지혜샘",
    "ME": "바른샘",
}


def suwon_library_status(text: str) -> str:
    value = clean_text(text)
    if "신청하기" in value or "접수중" in value:
        return "OPEN"
    if "대기자" in value:
        return "WAITLIST"
    if "접수예정" in value:
        return "WAITING"
    if "접수마감" in value or "종료" in value:
        return "CLOSED"
    return value


def suwon_library_info_value(spans: list[BeautifulSoup], key: str) -> str:
    prefix = f"{key} :"
    for span in spans:
        text = clean_text(span.get_text(" ", strip=True))
        if text.startswith(prefix):
            return clean_text(text[len(prefix) :])
    return ""


def suwon_library_capacity(text: str) -> tuple[Optional[int], Optional[int], Optional[int]]:
    match = re.search(r"신청자수\s*:\s*(\d+)\s*/\s*(\d+)", text)
    if not match:
        return None, None, None
    reported_current = int(match.group(1))
    capacity_total = int(match.group(2))
    # Suwon libraries include accepted wait-list applicants in the first
    # number, so it can exceed the class capacity. The normalized course
    # schema requires capacity_current <= capacity_total; retain the upstream
    # value in raw_fields and cap only the normalized value.
    return capacity_total, min(reported_current, capacity_total), reported_current


def normalize_suwon_library_date_range(value: Any) -> str:
    text = clean_text(value)
    match = re.search(
        r"(\d{4})[.-](\d{1,2})[.-](\d{1,2})\s*~\s*(\d{2})[.-](\d{1,2})[.-](\d{1,2})",
        text,
    )
    if not match:
        return normalize_mixed_date_range(text)

    start_year = int(match.group(1))
    end_year = (start_year // 100) * 100 + int(match.group(4))
    if end_year < start_year - 50:
        end_year += 100
    return (
        f"{start_year:04d}-{int(match.group(2)):02d}-{int(match.group(3)):02d}"
        f" ~ {end_year:04d}-{int(match.group(5)):02d}-{int(match.group(6)):02d}"
    )


def suwon_library_course_expired(
    period: str,
    apply_period: str,
    status_text: str,
    reference_date: Optional[date] = None,
) -> bool:
    today = reference_date or datetime.now().astimezone().date()
    _start_date, end_date = parse_date_range(period)
    if end_date is not None:
        return end_date < today
    apply_start, apply_end = parse_date_range(apply_period)
    closed = any(token in clean_text(status_text) for token in ("마감", "종료", "폐강"))
    if not closed:
        return False
    if apply_end is not None:
        return apply_end < today
    return apply_start is not None and apply_start < today - timedelta(days=366)


def collect_suwon_library_lectures(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    code = clean_text((query.get("searchManageCdArray") or [""])[0]).upper()
    branch_short = SUWON_LIBRARY_BRANCH_CODES.get(code) or target.branch.replace("도서관", "")
    branch = target.branch if target.branch.endswith("도서관") else f"{branch_short}도서관"
    rows: list[dict[str, Any]] = []
    pages = 0
    pagination_detected = False
    pagination_exhausted = False
    source_rows = 0
    expired_rows = 0
    seen_page_signatures: set[tuple[str, ...]] = set()

    for page in range(1, max(1, max_pages) + 1):
        page_query = dict(query)
        page_query["searchManageCdAll"] = ["N"]
        page_query["searchManageCdArray"] = [code] if code else page_query.get("searchManageCdArray", [])
        page_query["currentPageNo"] = [str(page)]
        page_query["recordCountPerPage"] = page_query.get("recordCountPerPage") or ["10"]
        page_url = urlunparse(parsed._replace(query=urlencode(page_query, doseq=True)))
        soup = fetch_soup(s, page_url, timeout=timeout)
        pages += 1
        items = soup.select(".lecture-list > li")
        pagination_detected = pagination_detected or bool(soup.select(".paging, .pagination"))
        if not items:
            pagination_exhausted = True
            break
        page_signature = tuple(
            clean_text(
                (item.select_one(".title a") or item).get_text(" ", strip=True)
            )
            for item in items
        )
        if page_signature in seen_page_signatures:
            pagination_exhausted = True
            break
        seen_page_signatures.add(page_signature)
        for item in items:
            title_link = item.select_one(".title a")
            title = clean_text(title_link.get_text(" ", strip=True) if title_link else "")
            if not title or is_low_value_title(title):
                continue
            onclick = title_link.get("onclick", "") if title_link else ""
            id_match = re.search(r"fnDetail\(['\"]?(\d+)['\"]?\)", onclick)
            lecture_id = id_match.group(1) if id_match else ""
            raw_url = f"https://www.suwonlib.go.kr/reserve/lecture/lectureDetail.do?lectureIdx={lecture_id}" if lecture_id else page_url
            application_url = f"https://www.suwonlib.go.kr/reserve/lecture/lectureList.do?lectureIdx={lecture_id}" if lecture_id else page_url
            spans = item.select(".info span")
            all_text = clean_text(item.get_text(" ", strip=True))
            target_text = suwon_library_info_value(spans, "대상")
            period = suwon_library_info_value(spans, "교육기간")
            schedule = suwon_library_info_value(spans, "시간")
            room = suwon_library_info_value(spans, "장소")
            apply_period = suwon_library_info_value(spans, "접수기간")
            method = suwon_library_info_value(spans, "접수방법")
            capacity_total, capacity_current, capacity_current_reported = suwon_library_capacity(all_text)
            status_text = clean_text(item.select_one(".info_r").get_text(" ", strip=True) if item.select_one(".info_r") else "")
            status = suwon_library_status(status_text)
            normalized_period = normalize_suwon_library_date_range(period) or period
            normalized_apply_period = normalize_suwon_library_date_range(apply_period) or apply_period
            source_rows += 1
            if suwon_library_course_expired(
                normalized_period,
                normalized_apply_period,
                status_text,
            ):
                expired_rows += 1
                continue
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
                    "title": title,
                    "branch": branch,
                    "branch_code": code or target.provider,
                    "category": "독서문화프로그램",
                    "raw_url": raw_url,
                    "application_url": application_url if status in {"OPEN", "WAITLIST"} else "",
                    "status": status,
                    "period": normalized_period,
                    "apply_period": normalized_apply_period,
                    "schedule_raw": schedule,
                    "target": target_text,
                    "fee": "무료",
                    "room": room,
                    "venue_name": branch,
                    "capacity_total": capacity_total,
                    "capacity_current": capacity_current,
                    "reservation_available": status in {"OPEN", "WAITLIST"},
                    "application_type": "ONLINE_RESERVATION",
                    "application_method_raw": method,
                    "description": clean_text(" | ".join(part for part in (target_text, period, schedule, room, apply_period, method) if part)),
                    "collection_category": "도서관",
                    "domain_category": "도서관",
                    "operator_type": "공공도서관",
                    "source_group": "library",
                    "collection_type": "static_html",
                    "program_type": "독서문화프로그램",
                    "raw_fields": {
                        "parser": "suwon_library_lecture_list",
                        "source_url": page_url,
                        "lecture_id": lecture_id,
                        "manage_code": code,
                        "status_text": status_text,
                        "capacity_current_reported": capacity_current_reported,
                    },
                }
            )
        if len(items) < int((page_query.get("recordCountPerPage") or ["10"])[0]):
            pagination_exhausted = True
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "source_rows": source_rows,
        "expired_count": expired_rows,
        "current_count": len(rows),
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "pagination_complete": pagination_exhausted,
        "pagination_exhausted": pagination_exhausted,
        "source_cap_reached": not pagination_exhausted,
        "no_current_data": pagination_exhausted and not rows,
        "no_current_reason": (
            "all Suwon library lecture rows are expired"
            if pagination_exhausted and not rows
            else ""
        ),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "suwon_library_lecture_list", meta


def mmk_detail_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for li in soup.select(".viewTypeB .progCon li"):
        key_node = li.select_one(".name")
        key = clean_text(key_node.get_text(" ", strip=True) if key_node else "")
        value = clean_text(li.get_text(" ", strip=True))
        if key and value.startswith(key):
            value = clean_text(value[len(key) :])
        if key:
            pairs[key] = value
    return pairs


def mmk_full_title_from_link(link: BeautifulSoup) -> str:
    candidates = [link.get("title"), link.get("aria-label"), link.get("data-title")]
    for selector in (".tit", ".title", "strong"):
        node = link.select_one(selector)
        if node:
            candidates.extend([node.get("title"), node.get("aria-label"), node.get_text(" ", strip=True)])
    candidates.append(link.get_text(" ", strip=True))
    for value in candidates:
        title = clean_text(value)
        title = re.sub(r"\s*(?:상세보기|자세히보기|바로가기)\s*$", "", title).strip()
        if title and not is_low_value_title(title):
            return title
    return ""


def mmk_detail_title(soup: BeautifulSoup) -> str:
    generic_titles = {"예약 현황", "교육·행사 예약", "교육·행사 프로그램", "상세보기"}
    for selector in (
        ".viewTypeB .tit",
        ".viewTypeB .title",
        ".viewTypeB h3",
        ".viewTypeB h4",
        ".board_view .tit",
        ".board_view h3",
        ".contents h3",
        "h3",
    ):
        node = soup.select_one(selector)
        title = clean_text(node.get_text(" ", strip=True) if node else "")
        title = re.sub(r"^(?:신청하기|접수중|접수마감|마감|종료)\s*", "", title).strip()
        if title and title not in generic_titles and not is_low_value_title(title):
            return title
    return ""


def collect_mmk_education_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    detail_pages = 0
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    status = "진행중" if (query.get("status") or [""])[0] == "present" else ""

    for link in soup.select('a[href*="folder=education"][href*="page=view"]'):
        title = mmk_full_title_from_link(link)
        if not title or is_low_value_title(title):
            continue
        raw_url = normalize_link(target.url, link.get("href"))
        if not raw_url:
            continue
        list_target = clean_text(link.select_one(".part").get_text(" ", strip=True) if link.select_one(".part") else "")
        list_period = clean_text(link.select_one(".data").get_text(" ", strip=True) if link.select_one(".data") else "")
        pairs: dict[str, str] = {}
        detail_text = ""
        if detail_pages < detail_limit:
            detail_soup = fetch_soup(s, raw_url, timeout=timeout)
            pairs = mmk_detail_pairs(detail_soup)
            title = mmk_detail_title(detail_soup) or title
            detail_text = clean_text(
                detail_soup.select_one(".viewTypeB .contents").get_text(" ", strip=True)
                if detail_soup.select_one(".viewTypeB .contents")
                else detail_soup.select_one(".viewTypeB").get_text(" ", strip=True)
                if detail_soup.select_one(".viewTypeB")
                else ""
            )
            detail_pages += 1
        period = clean_text(pairs.get("교육기간") or list_period)
        apply_period = clean_text(pairs.get("접수기간", ""))
        target_text = clean_text(pairs.get("교육대상") or list_target)
        capacity = clean_text(pairs.get("참가인원", ""))
        method = clean_text(pairs.get("참가방법", ""))
        fee = clean_text(pairs.get("참가비", ""))
        start_date, end_date = parse_date_range(period)
        rows.append(
            {
                "provider": target.provider,
                "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                "title": title,
                "branch": target.branch,
                "branch_code": target.provider,
                "category": "교육",
                "raw_url": raw_url,
                "application_url": raw_url if any(keyword in method for keyword in ("온라인", "누리집", "홈페이지", "사전 접수")) else "",
                "status": status or method,
                "period": period,
                "apply_period": apply_period,
                "schedule_raw": period,
                "start_date": start_date,
                "end_date": end_date,
                "target": target_text,
                "capacity": capacity,
                "capacity_total": parse_capacity_number(capacity),
                "fee": fee,
                "application_method_raw": method,
                "description": detail_text or clean_text(link.get_text(" ", strip=True)),
                "venue_name": target.branch,
                "raw_fields": {"parser": "mmk_education_card_detail", "detail_pairs": pairs},
            }
        )

    meta = {
        "pages": 1,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": False,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "mmk_education_card_detail", meta


def jeonju_program_pairs(soup: BeautifulSoup) -> dict[str, str]:
    pairs: dict[str, str] = {}
    for dl in soup.select("dl"):
        dt = dl.find("dt")
        dd = dl.find("dd")
        key = clean_text(dt.get_text(" ", strip=True) if dt else "")
        value = clean_text(dd.get_text(" ", strip=True) if dd else "")
        if key and value:
            pairs[key] = value
    return pairs


def jeonju_program_title_from_detail(soup: BeautifulSoup) -> tuple[str, str]:
    for node in soup.select(".tit"):
        parts = [clean_text(text) for text in node.stripped_strings if clean_text(text)]
        if not parts:
            continue
        status = parts[0] if parts[0] in {"신청하기", "접수대기", "종료", "마감", "접수중"} else ""
        title_parts = parts[1:] if status else parts
        title = clean_text(" ".join(title_parts))
        if title and not is_low_value_title(title):
            return title, status
    return "", ""


def jeonju_program_row_from_detail(
    target: CrawlTarget,
    detail_url: str,
    soup: BeautifulSoup,
    fallback_title: str = "",
    fallback_status: str = "",
    fallback_pairs: Optional[dict[str, str]] = None,
) -> dict[str, Any]:
    pairs = fallback_pairs or {}
    pairs = {**pairs, **jeonju_program_pairs(soup)}
    title, status = jeonju_program_title_from_detail(soup)
    title = title or fallback_title
    status = status or fallback_status
    category = clean_text(pairs.get("강좌분류", ""))
    period = clean_text(pairs.get("진행기간", ""))
    schedule = clean_text(pairs.get("강의일시", ""))
    if not schedule:
        schedule = clean_text(" ".join(part for part in [pairs.get("강의기간", ""), period] if part))
    capacity = clean_text(pairs.get("정원", ""))
    fee = clean_text(pairs.get("수강료", ""))
    target_text = clean_text(pairs.get("대상", ""))
    method = clean_text(pairs.get("신청방법", ""))
    description = clean_text(
        " ".join(
            part
            for part in [
                category,
                title,
                period,
                schedule,
                pairs.get("신청기간", ""),
                target_text,
                capacity,
                fee,
                method,
                pairs.get("문의", ""),
            ]
            if part
        )
    )
    return {
        "provider": target.provider,
        "provider_course_id": stable_course_id(target.provider, detail_url, title, target.branch),
        "title": title,
        "branch": target.branch,
        "branch_code": target.provider,
        "category": category,
        "raw_url": detail_url,
        "application_url": detail_url if any(token in status for token in ("신청", "접수")) and "종료" not in status else "",
        "status": status,
        "period": period,
        "apply_period": clean_text(pairs.get("신청기간", "")),
        "schedule_raw": schedule,
        "target": target_text,
        "fee": fee,
        "capacity": capacity,
        "capacity_total": parse_capacity_number(capacity),
        "application_method_raw": method,
        "venue_address": clean_text(pairs.get("교육장 주소", "")),
        "description": description,
        "raw_fields": {"parser": "jeonju_lifelong_program", "pairs": pairs},
    }


def jeonju_program_card_info(card: Any) -> tuple[str, str, str, dict[str, str]]:
    title_node = card.select_one(".tit")
    title_text = clean_text(title_node.get_text(" ", strip=True) if title_node else "")
    category = clean_text(card.select_one(".cate").get_text(" ", strip=True) if card.select_one(".cate") else "")
    fee = clean_text(card.select_one("[class*='program_ptype']").get_text(" ", strip=True) if card.select_one("[class*='program_ptype']") else "")
    title = title_text
    if category:
        title = clean_text(title.replace(category, "", 1))
    if fee:
        title = clean_text(re.sub(re.escape(fee) + r"$", "", title))
    status = clean_text(card.select_one(".state_acc").get_text(" ", strip=True) if card.select_one(".state_acc") else "")
    pairs = {"강좌분류": category.strip("[]"), "수강료": fee}
    for p in card.select(".txt p"):
        text = clean_text(p.get_text(" ", strip=True))
        if ":" in text:
            key, value = text.split(":", 1)
            pairs[clean_text(key)] = clean_text(value)
    return title, status, fee, pairs


def collect_jeonju_lifelong_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    soup = fetch_soup(s, target.url, timeout=timeout)
    rows: list[dict[str, Any]] = []
    detail_pages = 0

    cards = soup.select("ul.class_list_wrap > li")
    if not cards and soup.select("dl"):
        row = jeonju_program_row_from_detail(target, target.url, soup)
        if row.get("title"):
            rows.append(row)
    for card in cards:
        link = card.select_one("a[href]")
        raw_url = normalize_link(target.url, link.get("href") if link else "")
        if not raw_url:
            continue
        title, status, _fee, pairs = jeonju_program_card_info(card)
        if not title or is_low_value_title(title):
            continue
        if detail_pages < detail_limit:
            detail_soup = fetch_soup(s, raw_url, timeout=timeout)
            row = jeonju_program_row_from_detail(
                target,
                raw_url,
                detail_soup,
                fallback_title=title,
                fallback_status=status,
                fallback_pairs=pairs,
            )
            detail_pages += 1
        else:
            row = jeonju_program_row_from_detail(
                target,
                raw_url,
                BeautifulSoup("", "lxml"),
                fallback_title=title,
                fallback_status=status,
                fallback_pairs=pairs,
            )
        if row.get("title"):
            rows.append(row)

    meta = {
        "pages": 1,
        "detail_pages": detail_pages,
        "discovered_links": len(cards),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": bool(soup.select(".pagination a, .paging a, a[href*='page=']")),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jeonju_lifelong_program", meta


def collect_hamyang_welfare_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    max_page_seen = 1

    for page in range(1, max(1, max_pages) + 1):
        page_query = dict(query)
        if page > 1:
            page_query["cpage"] = [str(page)]
        current_url = parsed._replace(query=urlencode(page_query, doseq=True)).geturl()
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        page_numbers = [
            int(text)
            for text in (clean_text(node.get_text(" ", strip=True)) for node in soup.select(".pagination .pages a"))
            if text.isdigit()
        ]
        if page_numbers:
            max_page_seen = max(page_numbers)
        page_rows = 0
        for card in soup.select(".edu1list1 li.column"):
            title = clean_text(card.select_one("h2.h1").get_text(" ", strip=True) if card.select_one("h2.h1") else "")
            if not title or is_low_value_title(title):
                continue
            pairs: dict[str, str] = {}
            for li in card.select(".tg1 li"):
                key = clean_text(li.select_one(".t1").get_text(" ", strip=True) if li.select_one(".t1") else "")
                value = clean_text(li.select_one(".t2").get_text(" ", strip=True) if li.select_one(".t2") else "")
                if key:
                    pairs[key] = value
            session_name = clean_text(card.select_one(".hg1 .t1").get_text(" ", strip=True) if card.select_one(".hg1 .t1") else "")
            status = clean_text(card.select_one(".btns a").get_text(" ", strip=True) if card.select_one(".btns a") else "")
            period = clean_text(pairs.get("교육기간", ""))
            day_text = clean_text(pairs.get("교육요일", ""))
            time_text = clean_text(pairs.get("교육시간", ""))
            schedule = clean_text(" ".join(part for part in [day_text, time_text] if part))
            capacity = clean_text(pairs.get("교육정원", ""))
            capacity_current = parse_capacity_number(pairs.get("신청현황"))
            capacity_total = parse_capacity_number(capacity)
            description = clean_text(" ".join([session_name, title, card.get_text(" ", strip=True)]))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, current_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "branch_code": target.provider,
                    "category": session_name,
                    "raw_url": current_url,
                    "application_url": current_url if "가능" in status and "불가" not in status else "",
                    "status": status,
                    "period": period,
                    "apply_period": clean_text(pairs.get("신청기간", "")),
                    "schedule_raw": schedule or period,
                    "target": clean_text(pairs.get("교육대상", "") or pairs.get("모집대상", "")),
                    "capacity": capacity,
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "instructor": clean_instructor_name(pairs.get("강사", "")),
                    "fee": "",
                    "description": description,
                    "venue_name": target.branch,
                    "raw_fields": {"parser": "hamyang_welfare_course_card", "pairs": pairs},
                }
            )
            page_rows += 1
        if page_rows == 0:
            break
        if page >= max_page_seen:
            break

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": max_page_seen > 1,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "hamyang_welfare_course_card", meta


def collect_babsang_welfare_programs(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    visited: set[str] = set()
    queue = [target.url]
    pages = 0
    pagination_detected = False

    while queue and pages < max(1, max_pages):
        current_url = queue.pop(0)
        if current_url in visited:
            continue
        visited.add(current_url)
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1

        for tr in soup.select("table.program-table tbody tr, table.program-table tr"):
            title_link = tr.select_one(".program-title a[href]")
            title = clean_text(title_link.get_text(" ", strip=True) if title_link else "")
            if not title or is_low_value_title(title):
                continue
            pairs: dict[str, str] = {}
            for item in tr.select(".program-details-list .detail-item"):
                key = clean_text(item.select_one(".detail-label").get_text(" ", strip=True) if item.select_one(".detail-label") else "")
                value = clean_text(item.select_one(".detail-value").get_text(" ", strip=True) if item.select_one(".detail-value") else "")
                if key:
                    pairs[key] = value
            status = clean_text(tr.select_one(".program-status").get_text(" ", strip=True) if tr.select_one(".program-status") else "")
            raw_url = normalize_link(current_url, title_link.get("href") if title_link else "") or current_url
            apply_link = tr.select_one(".program-status a[href], .program-image-placeholder a[href]")
            application_url = normalize_link(current_url, apply_link.get("href") if apply_link and status == "접수중" else "")
            period_raw = clean_text(pairs.get("운영기간", ""))
            period = normalize_yymmdd_range(period_raw)
            schedule_parts = [clean_text(part) for part in period_raw.split("/")][1:]
            schedule = clean_text(" ".join(part for part in schedule_parts if part))
            capacity = clean_text(pairs.get("인원", ""))
            capacity_current, capacity_total = parse_capacity_pair(capacity)
            fee = clean_text(pairs.get("수강료", ""))
            if fee in {"0", "0원"}:
                fee = "무료"
            venue = clean_text(pairs.get("장소", ""))
            description = clean_text(" ".join([title, tr.get_text(" ", strip=True)]))
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, target.branch),
                    "title": title,
                    "branch": target.branch,
                    "branch_code": target.provider,
                    "category": "프로그램 신청",
                    "raw_url": raw_url,
                    "application_url": application_url,
                    "status": status,
                    "period": period,
                    "apply_period": normalize_yymmdd_range(clean_text(pairs.get("접수기간", ""))),
                    "schedule_raw": schedule or period,
                    "capacity": capacity,
                    "capacity_current": capacity_current,
                    "capacity_total": capacity_total,
                    "fee": fee,
                    "venue_name": venue or target.branch,
                    "description": description,
                    "raw_fields": {"parser": "babsang_welfare_program_table", "pairs": pairs},
                }
            )

        page_links = [
            normalize_link(current_url, link.get("href"))
            for link in soup.select(".pagination a[href], .paging a[href], a.page-numbers[href]")
        ]
        page_links = [link for link in page_links if link and link not in visited and same_site(target.url, link)]
        if page_links:
            pagination_detected = True
        for link in page_links:
            if link not in queue:
                queue.append(link)

    meta = {
        "pages": pages,
        "detail_pages": 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": pagination_detected,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "babsang_welfare_program_table", meta


