def gwangju_sciencecenter_view_url(list_url: str, wid: str) -> str:
    parsed = urlparse(list_url)
    query = parse_qs(parsed.query)
    query["mode"] = ["view"]
    query["wid"] = [wid]
    return urlunparse((parsed.scheme, parsed.netloc, parsed.path, "", urlencode(query, doseq=True), ""))


def gwangju_science_program_value(card: BeautifulSoup, label: str) -> str:
    for item in card.select(".desc_info ul.list > li"):
        label_node = item.find("b")
        if clean_text(label_node.get_text(" ", strip=True) if label_node else "") != label:
            continue
        value_node = item.find("span")
        return clean_text(value_node.get_text(" ", strip=True) if value_node else "")
    return ""


def collect_gwangju_science_program_list(
    target: CrawlTarget,
    s: requests.Session,
    list_url: str,
    *,
    category_hint: str,
    timeout: int,
    page_limit: int,
) -> tuple[list[dict[str, Any]], int, bool]:
    rows: list[dict[str, Any]] = []
    pages = 0
    declared_last = 1
    collection_complete = False
    for page in range(1, max(0, page_limit) + 1):
        current_url = url_with_query(list_url, {"page": page if page > 1 else None})
        soup = fetch_soup(s, current_url, timeout=timeout)
        pages += 1
        declared_pages = [
            int(match.group(1))
            for node in soup.select("[onclick*='linkPage']")
            if (match := re.search(r"linkPage\((\d+)\)", clean_text(node.get("onclick"))))
        ]
        if declared_pages:
            declared_last = max(declared_last, *declared_pages)
        cards = [
            card
            for card in soup.select("ul.program_thumb > li")
            if card.select_one(".desc_info")
        ]
        if not cards:
            collection_complete = True
            break

        parsed_cards = 0
        current_cards = 0
        for card in cards:
            title_nodes = card.select(".desc_info .title span")
            title = clean_text(title_nodes[-1].get_text(" ", strip=True) if title_nodes else "")
            if not title or is_low_value_title(title):
                continue
            parsed_cards += 1
            raw_link = card.select_one(".program_button a.view[href]")
            raw_url = normalize_link(current_url, raw_link.get("href") if raw_link else None) or current_url
            period = normalize_mixed_date_range(
                gwangju_science_program_value(card, "교육기간")
            )
            start_date, end_date = parse_date_range(period)
            if should_skip_expired_course({"end_date": end_date}):
                continue
            current_cards += 1
            apply_period = normalize_mixed_date_range(
                gwangju_science_program_value(card, "접수기간")
            )
            apply_start, apply_end = parse_date_range(apply_period)
            schedule_raw = gwangju_science_program_value(card, "교육시간")
            target_text = gwangju_science_program_value(card, "모집대상")
            fee = gwangju_science_program_value(card, "교육비")
            status_text = clean_text(
                card.select_one(".desc_thumb .cate").get_text(" ", strip=True)
                if card.select_one(".desc_thumb .cate")
                else ""
            )
            status = normalize_status(status_text) or status_text
            category_text = clean_text(
                title_nodes[0].get_text(" ", strip=True) if len(title_nodes) > 1 else ""
            )
            reservation_available = status in {"OPEN", "WAITLIST", "WAITING", "SCHEDULED"}
            rows.append(
                {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(
                        target.provider,
                        raw_url,
                        title,
                        target.branch,
                    ),
                    "title": title,
                    "branch": target.branch,
                    "branch_code": target.provider,
                    "category": category_hint or category_text,
                    "raw_url": raw_url,
                    "application_url": raw_url if reservation_available else "",
                    "status": status,
                    "period": period,
                    "start_date": start_date,
                    "end_date": end_date,
                    "apply_period": apply_period,
                    "apply_start": apply_start,
                    "apply_end": apply_end,
                    "schedule_raw": schedule_raw,
                    "target": target_text,
                    "fee": fee,
                    "venue_name": target.branch,
                    "description": clean_text(card.get_text(" ", strip=True)),
                    "reservation_available": reservation_available,
                    "application_type": "ONLINE_RESERVATION",
                    "collection_category": "박물관/과학관",
                    "domain_category": "박물관/과학관",
                    "operator_type": "국립/공공기관",
                    "source_group": "museum_science",
                    "collection_type": "static_html+detail_html",
                    "raw_fields": {
                        "parser": "gwangju_sciencecenter_program_list",
                        "source_url": current_url,
                        "status_text": status_text,
                        "category_text": category_text,
                    },
                }
            )

        if parsed_cards and current_cards == 0:
            collection_complete = True
            break
        if page >= declared_last:
            collection_complete = True
            break
    return dedupe_rows(rows), pages, collection_complete


def collect_gwangju_national_science_museum(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    declared_last = 1
    pagination_exhausted = False
    detail_cap_reached = False
    seen_wids: set[str] = set()
    application_sources: dict[str, str] = {}
    category_names = {"\uc2e4\ud5d8\ud0d0\uad6c", "\uacfc\ud559\ud0d0\uad6c", "\ub180\uc774\uc218\ud559", "SW\ud0d0\uad6c", "\ucf54\ub529\uad50\uc2e4", "\ub85c\ubd07\uad50\uc2e4"}

    for page in range(1, max(1, max_pages) + 1):
        list_url = url_with_query(target.url, {"page": page if page > 1 else None})
        list_soup = fetch_soup(s, list_url, timeout=timeout)
        pages += 1
        page_links = list_soup.select("a[onclick*='linkView']")
        declared_pages = [
            int(match.group(1))
            for node in list_soup.select("[onclick*='linkPage']")
            if (match := re.search(r"linkPage\((\d+)\)", clean_text(node.get("onclick"))))
        ]
        if declared_pages:
            declared_last = max(declared_last, *declared_pages)
        if not page_links:
            pagination_exhausted = page > declared_last
            break
        for link in page_links:
            onclick = clean_text(link.get("onclick"))
            match = re.search(r"linkView\((\d+)\)", onclick)
            if not match or match.group(1) in seen_wids:
                continue
            wid = match.group(1)
            seen_wids.add(wid)
            if detail_pages >= max(0, detail_limit):
                detail_cap_reached = True
                continue
            detail_url = gwangju_sciencecenter_view_url(target.url, wid)
            detail_soup = fetch_soup(s, detail_url, timeout=timeout)
            detail_pages += 1
            detail_scope = detail_soup.select_one(".board_view") or detail_soup
            detail_text = clean_text(detail_scope.get_text(" ", strip=True))
            apply_match = re.search(r"\uad50\uc721\uc811\uc218\s*(.+?)\s*\uc548\ub0b4\uc0ac\ud56d", detail_text)
            period_match = re.search(r"\uad50\uc721\uae30\uac04\s*(.+?)(?:\uc811\uc218\ubc29\ubc95|\uad50\uc721\ud61c\ud0dd|\ud658\ubd88 \uae30\uc900)", detail_text)
            apply_period = clean_text(apply_match.group(1) if apply_match else "")
            period = clean_text(period_match.group(1) if period_match else "")
            has_application_source = bool(
                detail_scope.select_one(
                    "table a[href*='/edu/'][href*='mode=list']"
                )
            )

            for tr in detail_scope.select("table tr"):
                cells = [clean_text(cell.get_text(" ", strip=True)) for cell in tr.find_all(["th", "td"])]
                cells = [cell for cell in cells if cell]
                if len(cells) < 2 or any(cell == "\uad50\uc721\uba85" for cell in cells):
                    continue
                capacity_fee = next((cell for cell in cells if re.search(r"\d+\s*(?:\uba85|\ud300)\s*/\s*[\d,]+\s*\uc6d0", cell)), "")
                reservation_link = tr.find("a", href=True)
                application_url = normalize_link(detail_url, reservation_link.get("href") if reservation_link else None) or detail_url
                if not capacity_fee and not reservation_link:
                    continue
                title_cells = [cell for cell in cells if cell not in {capacity_fee, "\ubc14\ub85c\uac00\uae30"}]
                if not title_cells:
                    continue
                category = title_cells[0] if title_cells[0] in category_names and len(title_cells) > 1 else ""
                title = title_cells[1] if category else title_cells[0]
                if not title or is_low_value_title(title):
                    continue
                if reservation_link:
                    application_sources[application_url] = category or title
                    continue
                if has_application_source:
                    continue
                fee = ""
                capacity = ""
                fee_match = re.search(r"([\d,]+\s*\uc6d0)", capacity_fee)
                cap_match = re.search(r"(\d+\s*(?:\uba85|\ud300))", capacity_fee)
                if fee_match:
                    fee = fee_match.group(1)
                if cap_match:
                    capacity = cap_match.group(1)
                item_url = stable_list_item_url(
                    detail_url,
                    target.provider,
                    title,
                    target.branch,
                    period,
                    capacity_fee,
                )
                rows.append(
                    {
                        "provider": target.provider,
                        "provider_course_id": stable_course_id(
                            target.provider,
                            item_url,
                            title,
                            target.branch,
                        ),
                        "title": title,
                        "branch": target.branch,
                        "branch_code": target.provider,
                        "category": category,
                        "raw_url": item_url,
                        "application_url": "",
                        "application_type": "INFO_ONLY",
                        "reservation_available": False,
                        "status": "\uc811\uc218\uc548\ub0b4",
                        "period": period,
                        "apply_period": apply_period,
                        "fee": fee,
                        "capacity": capacity,
                        "venue_name": target.branch,
                        "description": detail_text[:800],
                        "raw_fields": {
                            "parser": "gwangju_sciencecenter_notice_detail",
                            "detail_url": detail_url,
                            "cells": cells,
                        },
                    }
                )

        if page >= declared_last:
            pagination_exhausted = True
            break

    application_collection_complete = True
    for application_url, category_hint in application_sources.items():
        remaining_detail_pages = max(0, detail_limit - detail_pages)
        if remaining_detail_pages <= 0:
            detail_cap_reached = True
            application_collection_complete = False
            break
        application_rows, application_pages, application_complete = (
            collect_gwangju_science_program_list(
                target,
                s,
                application_url,
                category_hint=category_hint,
                timeout=timeout,
                page_limit=min(max(1, max_pages), remaining_detail_pages),
            )
        )
        detail_pages += application_pages
        rows.extend(application_rows)
        if not application_complete:
            detail_cap_reached = True
            application_collection_complete = False
            break

    collection_complete = (
        pagination_exhausted
        and application_collection_complete
        and not detail_cap_reached
    )
    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(seen_wids),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": declared_last > 1,
        "pagination_complete": collection_complete,
        "pagination_exhausted": pagination_exhausted,
        "detail_collection_complete": not detail_cap_reached,
        "detail_cap_reached": detail_cap_reached,
        "source_cap_reached": not collection_complete,
        "recursion_depth": 0,
        "declared_pages": declared_last,
        "application_sources": len(application_sources),
    }
    return dedupe_rows(rows), "gwangju_sciencecenter_notice_detail", meta


YONGIN_LIFELONG_BASE_URL = "https://lll.yongin.go.kr"
YONGIN_LIFELONG_LIST_URL = f"{YONGIN_LIFELONG_BASE_URL}/yongin/rgEdu/list.do"
YONGIN_LIFELONG_VIEW_URL = f"{YONGIN_LIFELONG_BASE_URL}/yongin/rgEdu/view.do"
YONGIN_LIFELONG_DEFAULT_SEARCH_P_IDX = "67"
YONGIN_LIFELONG_BRANCH = "용인시평생학습관"
YONGIN_LIFELONG_ADDRESS = "경기도 용인시 수지구 문정로7번길 15"
YONGIN_LIFELONG_TARGET = "용인시민, 재외국민, 결혼이민자, 용인시 관내 직장인"


def yongin_lifelong_fetch_soup(
    url: str,
    timeout: int,
    s: requests.Session,
    *,
    data: Optional[dict[str, Any]] = None,
    referer: str = "",
) -> BeautifulSoup:
    headers = {"Referer": referer} if referer else None
    if data is None:
        response = s.get(url, headers=headers, timeout=timeout)
    else:
        response = s.post(
            url,
            data={key: clean_text(value) for key, value in data.items()},
            headers=headers,
            timeout=timeout,
        )
    response.raise_for_status()
    if not response.encoding or response.encoding.lower() == "iso-8859-1":
        response.encoding = response.apparent_encoding
    return BeautifulSoup(response.text, "lxml")


def yongin_lifelong_search_p_idx(url: str) -> str:
    parsed = urlparse(url)
    query = parse_qs(parsed.query)
    return clean_text((query.get("search_p_idx") or [YONGIN_LIFELONG_DEFAULT_SEARCH_P_IDX])[0]) or YONGIN_LIFELONG_DEFAULT_SEARCH_P_IDX


def yongin_lifelong_list_data(search_p_idx: str, page: int, pg_idx: str = "") -> dict[str, str]:
    return {
        "srchCategory": "",
        "page": str(page),
        "pg_idx": clean_text(pg_idx),
        "program_type": "",
        "search_p_idx": search_p_idx,
        "srchWord": "",
    }


def yongin_lifelong_status(value: Any) -> str:
    text = clean_text(value)
    if "교육진행" in text:
        return "교육진행중"
    if "신청" in text or "접수" in text:
        return normalize_status(text) or text
    if "마감" in text:
        return "접수마감"
    return normalize_status(text) or text


def yongin_lifelong_page_total(soup: BeautifulSoup) -> int:
    text = clean_text(soup.select_one(".list-board-count").get_text(" ", strip=True) if soup.select_one(".list-board-count") else "")
    match = re.search(r"현재페이지\s*:\s*\d+\s*/\s*(\d+)", text)
    if match:
        return int(match.group(1))
    max_page = 1
    for link in soup.select(".paging a[onclick]"):
        match = re.search(r"getPaging\((\d+)", clean_text(link.get("onclick")))
        if match:
            max_page = max(max_page, int(match.group(1)))
    return max_page


def yongin_lifelong_card_pairs(card: Any) -> dict[str, str]:
    pairs: dict[str, str] = {}
    if not hasattr(card, "select"):
        return pairs
    for item in card.select(".bm li"):
        label_node = item.find("strong")
        value_node = item.find("span")
        label = clean_text(label_node.get_text(" ", strip=True) if label_node else "").rstrip(":：").strip()
        value = clean_text(value_node.get_text(" ", strip=True) if value_node else "")
        if label and value:
            pairs[label] = value
    return pairs


def yongin_lifelong_capacity(card: Any, label: str) -> Optional[int]:
    if not hasattr(card, "select"):
        return None
    for item in card.select(".edu-cnt li"):
        item_text = clean_text(item.get_text(" ", strip=True))
        if label not in item_text:
            continue
        value_node = item.select_one(".s strong")
        return parse_capacity_number(value_node.get_text(" ", strip=True) if value_node else item_text)
    return None


def yongin_lifelong_pg_idx(card: Any) -> str:
    if not hasattr(card, "select_one"):
        return ""
    link = card.select_one(".tp a[href*='goView']")
    href = clean_text(link.get("href") if link else "")
    match = re.search(r"goView\('([^']+)'\)", href)
    return match.group(1) if match else ""


def yongin_lifelong_card_title(card: Any) -> tuple[str, str]:
    if not hasattr(card, "select_one"):
        return "", ""
    title_node = card.select_one(".tp strong")
    if not title_node:
        return "", ""
    category_node = title_node.select_one(".board-cate")
    category = clean_text(category_node.get_text(" ", strip=True) if category_node else "").strip("[]")
    if category_node:
        category_node.extract()
    return clean_text(title_node.get_text(" ", strip=True)), category


def yongin_lifelong_lines_value(lines: list[str], label: str, *, max_parts: int = 2) -> str:
    normalized_label = clean_text(label).rstrip(":：")
    for index, line in enumerate(lines):
        current = clean_text(line)
        if current.rstrip(":：") == normalized_label:
            values: list[str] = []
            for candidate in lines[index + 1 : index + 1 + max_parts]:
                candidate = clean_text(candidate)
                if candidate and not re.fullmatch(r"[:：]", candidate):
                    values.append(candidate)
            return clean_text(" ".join(values))
        if current.startswith(normalized_label):
            value = clean_text(current[len(normalized_label) :].lstrip(":： "))
            if value:
                return value
    return ""


def yongin_lifelong_clean_fee(value: Any) -> str:
    text = clean_text(value).replace(" 원", "원")
    match = re.search(r"무료|\d[\d,]*\s*원", text)
    return clean_text(match.group(0).replace(" ", "") if match else text)


def yongin_lifelong_common_target(text: str) -> str:
    match = re.search(r"용인시에\s+주소를\s+둔\s+(.+?)만\s+수강할\s+수\s+있음", text)
    if match:
        return clean_text(match.group(1))
    return YONGIN_LIFELONG_TARGET


def yongin_lifelong_detail_fields(
    timeout: int,
    s: requests.Session,
    search_p_idx: str,
    page: int,
    pg_idx: str,
) -> dict[str, Any]:
    if not pg_idx:
        return {}
    soup = yongin_lifelong_fetch_soup(
        YONGIN_LIFELONG_VIEW_URL,
        timeout,
        s,
        data=yongin_lifelong_list_data(search_p_idx, page, pg_idx=pg_idx),
        referer=f"{YONGIN_LIFELONG_LIST_URL}?search_p_idx={search_p_idx}&seq=21",
    )
    lines = lines_from_soup(soup)
    page_text = clean_text(soup.get_text(" ", strip=True))
    fee = yongin_lifelong_clean_fee(yongin_lifelong_lines_value(lines, "수강료", max_parts=2))
    period_text = yongin_lifelong_lines_value(lines, "교육기간", max_parts=3)
    schedule_match = re.search(r"/\s*([^/]+?\d{1,2}회\)?)", period_text)
    room = yongin_lifelong_lines_value(lines, "강의장", max_parts=1)
    apply_period = normalize_mixed_date_range(yongin_lifelong_lines_value(lines, "수강신청기간", max_parts=1))
    payment_period = normalize_mixed_date_range(yongin_lifelong_lines_value(lines, "강좌료 납부기간", max_parts=1))
    return {
        "period": normalize_mixed_date_range(period_text),
        "schedule_raw": clean_text(schedule_match.group(1) if schedule_match else ""),
        "apply_period": apply_period,
        "fee": fee,
        "room": room,
        "venue_name": clean_text(f"{YONGIN_LIFELONG_BRANCH} {room}".strip()) if room else YONGIN_LIFELONG_BRANCH,
        "venue_address": YONGIN_LIFELONG_ADDRESS,
        "target": yongin_lifelong_common_target(page_text),
        "payment_period": payment_period,
        "description": page_text[:1000],
    }


def collect_yongin_lifelong_regular_courses(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    search_p_idx = yongin_lifelong_search_p_idx(target.url)
    s = session()
    rows: list[dict[str, Any]] = []
    pages = 0
    detail_pages = 0
    total_pages = 1
    try:
        first_url = f"{YONGIN_LIFELONG_LIST_URL}?search_p_idx={search_p_idx}&seq=21"
        yongin_lifelong_fetch_soup(first_url, timeout, s)
        for page in range(1, max(1, max_pages) + 1):
            list_soup = yongin_lifelong_fetch_soup(
                YONGIN_LIFELONG_LIST_URL,
                timeout,
                s,
                data=yongin_lifelong_list_data(search_p_idx, page),
                referer=first_url,
            )
            pages += 1
            total_pages = max(total_pages, yongin_lifelong_page_total(list_soup))
            cards = list_soup.select(".list-board.two-sec .board-section, .board-section")
            if not cards:
                break
            for card in cards:
                title, category = yongin_lifelong_card_title(card)
                if not title or is_low_value_title(title):
                    continue
                pairs = yongin_lifelong_card_pairs(card)
                pg_idx = yongin_lifelong_pg_idx(card)
                raw_url = f"{YONGIN_LIFELONG_VIEW_URL}?pg_idx={quote(pg_idx)}&search_p_idx={quote(search_p_idx)}" if pg_idx else target.url
                day = pairs.get("수강일", "")
                time_text = pairs.get("시간", "")
                schedule_raw = clean_text(" / ".join(part for part in (day, time_text) if part))
                status = yongin_lifelong_status(card.select_one(".ed-con").get_text(" ", strip=True) if card.select_one(".ed-con") else "")
                row = {
                    "provider": target.provider,
                    "provider_course_id": stable_course_id(target.provider, raw_url, title, YONGIN_LIFELONG_BRANCH),
                    "title": title,
                    "branch": YONGIN_LIFELONG_BRANCH,
                    "branch_code": target.provider,
                    "category": category,
                    "program_type": "강좌",
                    "raw_url": raw_url,
                    "status": status,
                    "period": normalize_mixed_date_range(pairs.get("교육기간", "")),
                    "schedule_raw": schedule_raw,
                    "target": YONGIN_LIFELONG_TARGET,
                    "fee": "상세 페이지 확인",
                    "venue_name": YONGIN_LIFELONG_BRANCH,
                    "venue_address": YONGIN_LIFELONG_ADDRESS,
                    "instructor": pairs.get("강사명", ""),
                    "capacity_current": yongin_lifelong_capacity(card, "신청"),
                    "capacity_total": yongin_lifelong_capacity(card, "정원"),
                    "description": clean_text(card.get_text(" ", strip=True)),
                    "raw_fields": {
                        "parser": "yongin_lifelong_regular_card+detail_post",
                        "pg_idx": pg_idx,
                        "search_p_idx": search_p_idx,
                        "page": page,
                        "card_pairs": pairs,
                    },
                }
                rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})
            if page >= total_pages:
                break

        detail_budget = min(len(rows), max(0, detail_limit))
        for row in rows[:detail_budget]:
            pg_idx = clean_text((row.get("raw_fields") or {}).get("pg_idx") if isinstance(row.get("raw_fields"), dict) else "")
            page = int((row.get("raw_fields") or {}).get("page") or 1) if isinstance(row.get("raw_fields"), dict) else 1
            try:
                detail = yongin_lifelong_detail_fields(
                    timeout=timeout,
                    s=s,
                    search_p_idx=search_p_idx,
                    page=page,
                    pg_idx=pg_idx,
                )
                if detail:
                    detail_schedule = clean_text(detail.pop("schedule_raw", ""))
                    row.update({key: value for key, value in detail.items() if value})
                    if not clean_text(row.get("schedule_raw")):
                        card_pairs = row.get("raw_fields", {}).get("card_pairs", {}) if isinstance(row.get("raw_fields"), dict) else {}
                        row["schedule_raw"] = clean_text(
                            " / ".join(part for part in (card_pairs.get("수강일", ""), card_pairs.get("시간", "")) if part)
                        ) or detail_schedule
                    detail_pages += 1
            except Exception as exc:
                logger.debug("yongin lifelong detail fetch failed %s: %s", row.get("raw_url"), exc)
    finally:
        s.close()

    meta = {
        "pages": pages,
        "detail_pages": detail_pages,
        "discovered_links": len(rows),
        "reservation_discovery_links": 0,
        "reservation_fallback_pages": 0,
        "pagination_detected": total_pages > 1,
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "yongin_lifelong_regular_card+detail_post", meta


JUMIN_NYJ_LIST_URL = "https://jumin.nyj.go.kr/web/edc/program/list"
JUMIN_NYJ_AJAX_URL = "https://jumin.nyj.go.kr/web/edc/program/list2Ajax"


def jumin_nyj_decode_ajax_payload(text: str) -> dict[str, Any]:
    payload = json.loads(text)
    if isinstance(payload, str):
        payload = json.loads(payload)
    return payload if isinstance(payload, dict) else {}


def jumin_nyj_date_range(start: Any, end: Any) -> str:
    start_text = format_yyyymmdd(start)
    end_text = format_yyyymmdd(end)
    if start_text and end_text:
        return f"{start_text} ~ {end_text}"
    return start_text or end_text


def jumin_nyj_datetime(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    match = re.fullmatch(r"(\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2})(?::\d{2})?", text)
    if match:
        return f"{match.group(1)} {match.group(2)}"
    return format_yyyymmdd(text)


def jumin_nyj_fee(value: Any) -> str:
    text = clean_text(value)
    if text == "":
        return ""
    amount = parse_capacity_number(text)
    if amount is None:
        return text
    return "무료" if amount == 0 else f"{amount:,}원"


def jumin_nyj_branch_code(provider: str, org_no: Any, branch: str) -> str:
    source = clean_text(str(org_no)) or branch
    digest = hashlib.sha1(f"{provider}|{source}".encode("utf-8")).hexdigest()[:8].upper()
    slug = re.sub(r"[^A-Za-z0-9\uac00-\ud7a3]+", "_", branch).strip("_")[:32]
    if slug:
        return f"{slug}_{digest}"[:50]
    return f"{provider[:40]}_{digest}"[:50]


def jumin_nyj_clean_detail_value(value: Any) -> str:
    text = clean_text(value)
    if not text:
        return ""
    text = re.split(r"\s+\?\s+|\s+·", text, maxsplit=1)[0]
    return clean_text(text)


def jumin_nyj_detail_fields(s: requests.Session, detail_url: str, timeout: int) -> dict[str, Any]:
    soup = fetch_soup(s, detail_url, timeout=timeout)
    pairs = pairs_from_tables(soup)
    fee_text = jumin_nyj_clean_detail_value(pairs.get("교육비"))
    fee_match = re.search(r"\d[\d,]*\s*원|무료", fee_text)
    return {
        "period": normalize_mixed_date_range(jumin_nyj_clean_detail_value(pairs.get("교육기간"))),
        "apply_period": normalize_mixed_date_range(jumin_nyj_clean_detail_value(pairs.get("신청기간"))),
        "schedule_raw": jumin_nyj_clean_detail_value(pairs.get("교육시간")),
        "target": jumin_nyj_clean_detail_value(pairs.get("교육대상")),
        "fee": fee_match.group(0) if fee_match else fee_text,
        "instructor": jumin_nyj_clean_detail_value(pairs.get("강사명")),
        "room": jumin_nyj_clean_detail_value(pairs.get("교육장소")),
        "venue_address": jumin_nyj_clean_detail_value(pairs.get("주소")),
        "phone": jumin_nyj_clean_detail_value(pairs.get("문의전화")),
        "application_method_raw": jumin_nyj_clean_detail_value(pairs.get("접수방법")),
        "description": jumin_nyj_clean_detail_value(pairs.get("강좌소개")),
    }


def collect_jumin_nyj_programs(
    target: CrawlTarget,
    timeout: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    s = session()
    s.headers.update(
        {
            "Accept": "application/json,text/plain,*/*",
            "Referer": JUMIN_NYJ_LIST_URL,
            "X-Requested-With": "XMLHttpRequest",
        }
    )
    parsed = urlparse(target.url)
    query = parse_qs(parsed.query)
    category_code = clean_text((query.get("CtgCd") or [""])[0])
    params = {
        "pageIndex": "1",
        "searchTab": "CATE",
        "CtgCd": category_code,
    }

    response = s.get(JUMIN_NYJ_AJAX_URL, params=params, timeout=timeout, verify=True)
    response.raise_for_status()
    payload = jumin_nyj_decode_ajax_payload(response.text)
    data = payload.get("data") if isinstance(payload.get("data"), dict) else {}
    contents = data.get("contents") if isinstance(data.get("contents"), list) else []

    rows: list[dict[str, Any]] = []
    for item in contents:
        if not isinstance(item, dict):
            continue
        program_no = clean_text(item.get("edc_prgm_no"))
        title = clean_text(item.get("edc_prgm_nm"))
        if not program_no or not title:
            continue
        raw_url = f"https://jumin.nyj.go.kr/web/edc/program/{program_no}"
        rsvnset_seq = clean_text(item.get("edc_rsvnset_seq"))
        status = clean_text(item.get("edc_status"))
        branch = clean_text(item.get("org_name")) or target.branch
        period = jumin_nyj_date_range(item.get("edc_sdate"), item.get("edc_edate"))
        apply_period = jumin_nyj_date_range(
            jumin_nyj_datetime(item.get("edc_rsvn_sdtime") or item.get("edc_rsvn_sdate")),
            jumin_nyj_datetime(item.get("edc_rsvn_edtime") or item.get("edc_rsvn_edate")),
        )
        day = clean_text(item.get("edc_day_gbn_nm"))
        time_text = clean_text(item.get("edc_time"))
        schedule_raw = clean_text(" / ".join(part for part in (day, time_text) if part))
        fee = jumin_nyj_fee(item.get("sale_amt"))
        capacity_total = parse_capacity_number(item.get("edc_pncpa"))
        capacity_current = parse_capacity_number(item.get("stat_apply_cnt"))
        application_url = (
            f"https://jumin.nyj.go.kr/web/edc/rsvn/termsAgree/{program_no}/{rsvnset_seq}"
            if status == "접수중" and rsvnset_seq
            else ""
        )
        description = clean_text(item.get("edc_prgm_intro_cnts"))
        if not description:
            description = clean_text(
                " | ".join(
                    part
                    for part in (
                        branch,
                        period,
                        schedule_raw,
                        clean_text(item.get("edc_place_nm")),
                        clean_text(item.get("target_name")),
                    )
                    if part
                )
            )

        row = {
            "provider": target.provider,
            "provider_course_id": stable_course_id(target.provider, raw_url, title, branch),
            "title": title,
            "branch": branch,
            "branch_code": jumin_nyj_branch_code(target.provider, item.get("org_no"), branch),
            "category": clean_text(item.get("ctg_nm")),
            "raw_url": raw_url,
            "application_url": application_url,
            "status": status,
            "period": period,
            "apply_period": apply_period,
            "schedule_raw": schedule_raw,
            "target": clean_text(item.get("target_name")),
            "fee": fee,
            "room": clean_text(item.get("edc_place_nm")),
            "venue_name": branch,
            "instructor": clean_text(item.get("instrctr_nm")),
            "phone": clean_text(item.get("edc_guide_telno")),
            "capacity_total": capacity_total,
            "capacity_current": capacity_current,
            "reservation_available": status == "접수중",
            "application_method_raw": clean_text(item.get("rsvn_type_nm")),
            "description": description,
            "start_date": format_yyyymmdd(item.get("edc_sdate")),
            "end_date": format_yyyymmdd(item.get("edc_edate")),
            "raw_fields": {
                "parser": "jumin_nyj_list2ajax",
                "source_url": JUMIN_NYJ_AJAX_URL,
                "edc_prgm_no": program_no,
                "edc_rsvnset_seq": rsvnset_seq,
                "edc_status_class": clean_text(item.get("edc_status_class")),
            },
        }
        rows.append({key: value for key, value in row.items() if value not in (None, "", [], {})})

    detail_pages = 0
    for row in rows[: max(0, detail_limit)]:
        detail_url = clean_text(row.get("raw_url"))
        if not detail_url:
            continue
        try:
            detail = jumin_nyj_detail_fields(s, detail_url, timeout=timeout)
            row.update(merge_course_rows(row, {key: value for key, value in detail.items() if value}))
            detail_pages += 1
        except Exception as exc:
            logger.debug("jumin nyj detail fetch failed %s: %s", detail_url, exc)

    pagination = data.get("pagination") if isinstance(data.get("pagination"), dict) else {}
    meta = {
        "pages": 1,
        "detail_pages": detail_pages,
        "discovered_links": len(contents),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": bool(parse_capacity_number(pagination.get("TotalRecordCount")) and len(contents) < parse_capacity_number(pagination.get("TotalRecordCount"))),
        "recursion_depth": 0,
    }
    return dedupe_rows(rows), "jumin_nyj_list2ajax+detail", meta


def collect_yeongdo_reserve_generated(
    target: CrawlTarget,
    timeout: int,
    max_pages: int,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], str, dict[str, Any]]:
    from Crawler.generated_yaml.MUNI_WWW_YEONGDO_GO_KR_33400564 import collect as collect_yeongdo_reserve

    use_detail = detail_limit != 0
    rows = collect_yeongdo_reserve(
        limit=None,
        max_pages=max_pages,
        timeout=timeout,
        include_expired=False,
        detail=use_detail,
    )
    meta = {
        "pages": max_pages,
        "detail_pages": len(rows) if use_detail else 0,
        "discovered_links": len(rows),
        "reservation_discovery_links": sum(1 for row in rows if row.get("application_url")),
        "reservation_fallback_pages": 0,
        "pagination_detected": len(rows) >= max_pages * 10,
        "recursion_depth": 0,
        "no_current_data": not rows,
        "no_current_reason": "no_current_yeongdo_reserve" if not rows else "",
    }
    return dedupe_rows(rows), "yeongdo_reserve_cards+detail", meta


